async def create_stock_movement_order(
    db: AsyncSession,
    data: s.StockMovementOrderWrite,
    user,
) -> dict:
    """Move several items between bins as one numbered document.

    The document IS its `ref_no`: one number from `sys_doc_series`, carried onto every
    ledger row the lines write. No header row is stored — see
    `list_stock_movement_orders` for why — so `ref_id` is 0 rather than a foreign key
    to a table that does not exist.
    """
    from app.modules.inventory.models import Stock
    from app.modules.inventory.models import (
        StockTransferOrder, StockTransferOrderItem, STO_KIND_MOVEMENT,
    )

    wh = await _warehouse(db, data.warehouse_id)

    # Its OWN series (2026-08-21). This drew on STOCK_MOVEMENT, which meant two
    # things at once: an order and a plain bin-to-bin movement shared one running
    # number, and the three-letter prefix fallback rendered both as "STO" — the
    # abbreviation this system already uses for a Stock TRANSFER Order, which is an
    # inter-warehouse document with a different table, a different screen and a
    # different meaning. An SMO now reads SMO.
    order_no = await next_number(db, WarehouseDocType.STOCK_MOVEMENT_ORDER.value)
    moved: list[dict] = []
    # Read once: the code toggle cannot differ between two lines of one order.
    code_config = await codeformat.code_settings(db)

    allowed_bins = await floor_scope_ids(db, user)
    if allowed_bins is not None and not allowed_bins:
        raise ValidationError("No warehouse floor is assigned to your HCM position")

    is_cross_floor = False

    for line in data.items:
        source = await _get(db, Bin, line.source_bin_id, "Source bin")
        destination = await _get(db, Bin, line.destination_bin_id, "Destination bin")
        if source.id == destination.id:
            raise ValidationError("Source and destination bins must be different")
        if source.warehouse_id != wh.id or destination.warehouse_id != wh.id:
            raise ValidationError("Both bins must belong to the selected warehouse")
        if allowed_bins is not None:
            if source.id not in allowed_bins or destination.id not in allowed_bins:
                raise ValidationError("You can only move stock within your assigned floors")
        if getattr(source, "floor_level", None) != getattr(destination, "floor_level", None):
            is_cross_floor = True
        # Not restricted to BIN rungs: putaway may place stock on a lane or a rack
        # (see `confirm_putaway`), and stock that can be put somewhere has to be
        # movable off it again or it is stranded there for good.
        if not source.is_active or not destination.is_active:
            raise ValidationError("Source and destination bins must be active")

        item = await _item_snapshot(db, line.item_id)
        batch_id = line.batch_id or m.NO_BATCH
        stock = _summed(row for row in (await db.execute(
            select(Stock).where(
                Stock.warehouse_id == wh.id,
                Stock.bin_id == source.id,
                Stock.item_id == item.id,
                Stock.batch_id == batch_id,
                Stock.project_id == 0,
            ).with_for_update()
        )).scalars().all() if stock_allocation.matches_combination(row, combo_dict(line)))
        if stock is None or _d(stock.available_qty) < _d(line.quantity):
            available = _d(stock.available_qty) if stock else ZERO
            raise ValidationError(
                f"Only {available} is available in source bin {source.code} for item {item.code}"
            )

        serial_numbers, serial_rows = await _movement_units(
            db, item=item, warehouse_id=wh.id, bin_id=source.id,
            batch_id=line.batch_id or None, values=line.serial_numbers,
            quantity=line.quantity, code_config=code_config,
            doc_no=order_no)

        moved.append({
            "item_id": item.id,
            "item_code": item.code,
            "item_name": item.name,
            "uom_code": item.uom_code,
            # The brand / variant / model this line moves, when it names one.
            "combination": (await combinations.resolve(db, item.id, line, label=item.code)
                            if line.brand_id else dict(combinations.NONE)),
            "batch_id": line.batch_id or None,
            "source_bin_id": source.id,
            "source_bin_code": source.code,
            "destination_bin_id": destination.id,
            "destination_bin_code": destination.code,
            "quantity": line.quantity,
            "serial_numbers": serial_numbers,
        })

    order = StockTransferOrder(
        sto_no=order_no,
        doc_kind=STO_KIND_MOVEMENT,
        from_warehouse_id=wh.id, from_warehouse_name=wh.name,
        to_warehouse_id=wh.id, to_warehouse_name=wh.name,
        status=MovementOrderStatus.DRAFT.value,
        requested_by_id=getattr(user, "id", None),
        requested_by_name=_name(user),
        remarks=data.reason,
        items=[StockTransferOrderItem(
            item_id=row["item_id"], item_code=row["item_code"],
            item_name=row["item_name"], uom_code=row["uom_code"],
            requested_qty=_d(row["quantity"]),
            source_bin_id=row["source_bin_id"],
            destination_bin_id=row["destination_bin_id"],
            batch_id=row["batch_id"],
            serial_numbers=row["serial_numbers"] or None,
            **row.get("combination", combinations.NONE),
        ) for row in moved],
    )
    db.add(order)
    await db.flush()

    await write_audit(
        db,
        entity="inv_sto",
        entity_id=order.id,
        entity_no=order_no,
        action=AuditAction.CREATE,
        actor=user,
        after={
            "warehouse_id": wh.id,
            "lines": len(data.items),
            "remarks": data.reason,
            "status": order.status,
        },
    )
    await db.commit()
    return await _smo_read(db, order)


async def raise_hold_release_order(db: AsyncSession, hold, *, quantity, serial_numbers,
                                   destination_bin_id: int, reason: str, user) -> dict:
    """Release part or all of a project hold BY MOVING IT: one SMO line from the held
    lot to a location the storekeeper names, run through the SMO's own ladder,
    inspection and completion. Putting it down somewhere new is what gives the freed
    stock its own lot; the hold is reduced only when that order completes
    (`_apply_hold_release`), so a rejected order leaves it exactly as it was."""
    from app.modules.inventory.models import (
        Stock, StockTransferOrder, StockTransferOrderItem, STO_KIND_MOVEMENT,
    )

    stock = await db.get(Stock, hold.stock_id)
    if stock is None:
        raise NotFoundError("The held lot is no longer on the shelf")
    wh = await _warehouse(db, hold.warehouse_id)
    if not hold.bin_id:
        raise ValidationError(
            f"{hold.hold_no} is held in bulk storage with no location, so there is "
            "nothing to move it off. Put it away to a location first.")
    source = await _get(db, Bin, hold.bin_id, "Source location")
    destination = await _get(db, Bin, destination_bin_id, "Destination location")
    if destination.id == source.id:
        raise ValidationError("Move it to a different location than the held lot")
    if destination.warehouse_id != wh.id or not destination.is_active:
        raise ValidationError("The destination must be an active location in this warehouse")
    allowed = await floor_scope_ids(db, user)
    if allowed is not None and (source.id not in allowed or destination.id not in allowed):
        raise ValidationError("You can only move stock within your assigned floors")

    item = await _item_snapshot(db, hold.item_id)
    qty = _d(quantity)
    stamp = project_hold_unit_marker(hold.project_id, hold.id)
    names = [v for v in (serial_numbers or []) if v and v.strip()]
    if not names and hold.serial_numbers and qty == _d(hold.quantity):
        names = list(hold.serial_numbers)
    # The same unit rule the order will be held to at inspection and completion.
    names, rows = await _movement_units(
        db, item=item, warehouse_id=wh.id, bin_id=source.id,
        batch_id=hold.batch_id or None, values=names, quantity=qty,
        code_config=await codeformat.code_settings(db),
        doc_no=hold.hold_no, allow_remark=stamp)
    if hold.serial_numbers:
        foreign = [r.serial_number for r in rows if r.remarks != stamp]
        if foreign:
            raise ValidationError(
                f"{hold.hold_no} names its units; these are not among them: "
                + ", ".join(foreign[:5]))

    order = StockTransferOrder(
        sto_no=await next_number(db, WarehouseDocType.STOCK_MOVEMENT_ORDER.value),
        doc_kind=STO_KIND_MOVEMENT,
        from_warehouse_id=wh.id, from_warehouse_name=wh.name,
        to_warehouse_id=wh.id, to_warehouse_name=wh.name,
        status=MovementOrderStatus.DRAFT.value,
        requested_by_id=getattr(user, "id", None), requested_by_name=_name(user),
        remarks=f"Release of {hold.hold_no} ({hold.project_name}): {reason}"[:500],
        items=[StockTransferOrderItem(
            item_id=item.id, item_code=item.code, item_name=item.name,
            uom_code=item.uom_code, requested_qty=qty,
            source_bin_id=source.id, destination_bin_id=destination.id,
            batch_id=hold.batch_id or None, serial_numbers=names or None,
        )],
    )
    db.add(order)
    await db.flush()
    hold.release_order_id = order.id
    hold.release_order_no = order.sto_no
    hold.release_qty = qty
    hold.release_serials = [r.serial_number for r in rows] or None
    hold.release_destination = destination.code
    await write_audit(db, entity="inv_sto", entity_id=order.id, entity_no=order.sto_no,
                      action=AuditAction.CREATE, actor=user,
                      after={"release_of": hold.hold_no, "quantity": str(qty),
                             "to": destination.code, "reason": reason})
    await db.flush()
    return await submit_stock_movement_order(db, order.id, user)


async def submit_stock_movement_order(db: AsyncSession, order_id: int, user) -> dict:
    """Send a DRAFT movement into its approval ladder.

    Saving an SMO moves nothing; this press starts the workflow. When the engine
    settles the instance at once — no ladder configured, or every rung resolving to the
    submitter — the order is performed right here, through the same
    `_perform_movement_order` an approver's signature reaches, so the shelf is re-checked
    under lock before a single unit moves. Otherwise it waits in PENDING_APPROVAL.
    """
    order = await _smo_by(db, order_id=order_id, lock=True)
    if order is None:
        raise NotFoundError(f"Stock movement order {order_id} not found")
    _guard(order.status, {MovementOrderStatus.DRAFT.value}, "submit", "stock movement order")

    bin_ids = {i for line in order.items
               for i in (line.source_bin_id, line.destination_bin_id) if i}
    floors = {b.id: getattr(b, "floor_level", None) for b in (await db.execute(
        select(Bin).where(Bin.id.in_(bin_ids)))).scalars()} if bin_ids else {}
    is_cross_floor = any(floors.get(line.source_bin_id) != floors.get(line.destination_bin_id)
                         for line in order.items)

    project_id, project_name = await wf_ladder.project_for(
        db, getattr(user, "active_position_id", None), user)

    before = order.status
    # `engine.start` is deliberately NOT called without a ladder: with nothing
    # configured the engine climbs the raiser's reporting line, which would put every
    # bin-to-bin movement into a stranger's queue. No ladder -> the press is the
    # approval, exactly as a movement behaved before drafts existed.
    if await wf_ladder.find_ladder(
            db, project_id, DocType.STOCK_MOVEMENT_ORDER.value) is None:
        await _perform_movement_order(db, order, user)
    else:
        order.status = MovementOrderStatus.PENDING_APPROVAL.value
        instance = await engine.start(
            db, doc_type=DocType.STOCK_MOVEMENT_ORDER.value, doc_id=order.id,
            context={
                "doc_no": order.sto_no,
                "doc_summary": f"Stock movement in {order.from_warehouse_name}",
                "warehouse_id": order.from_warehouse_id,
                "project_id": project_id,
                "project_name": project_name,
                "requester_position_id": getattr(user, "active_position_id", None),
                "is_cross_floor": str(is_cross_floor).lower(),
            },
            user=user,
        )
        # The ladder can finish AT SUBMIT — the submitter at the top of a self-owned
        # chain, or a ladder set to NO_APPROVAL. Then the stock moves now.
        if instance.status == InstanceStatus.APPROVED.value:
            await _perform_movement_order(db, order, user)
        elif instance.status == InstanceStatus.REJECTED.value:
            order.status = MovementOrderStatus.REJECTED.value
            await _unwind_hold_release(db, order)

    await write_audit(
        db, entity="inv_sto", entity_id=order.id, entity_no=order.sto_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before}, after={"status": order.status},
        summary="Submitted stock movement order",
    )
    await db.commit()
    return await _smo_read(db, order)


async def list_stock_movements(db: AsyncSession, params: PageParams, user=None) -> dict:
    """FIXED 2026-08-20 — was unscoped while every other warehouse list on this screen
    obeys a rung. A stock movement is a fact about a WAREHOUSE, so with no rung the
    Stock Movements register showed bin-to-bin moves at all 983 stocking points to
    anyone holding `stock.view`. WITHOUT this a storekeeper reads what every other
    branch shifted, and the warehouse rung on Job Profiles is silently ignored on one
    screen out of a dozen."""
    from app.modules.inventory.models import StockMovement

    stmt = select(StockMovement).where(
        StockMovement.ref_type == InventoryRefType.STOCK_MOVEMENT.value,
        StockMovement.direction == StockDirection.OUT.value,
    )
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=StockMovement.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            project_col=StockMovement.project_id,
            owner_col=StockMovement.created_by_id,
        ))
    page = await paginate(db, stmt.order_by(StockMovement.id.desc()), params)
    rows: list[dict] = []
    for outward in page["items"]:
        inward = await db.scalar(select(StockMovement).where(
            StockMovement.ref_type == InventoryRefType.STOCK_MOVEMENT.value,
            StockMovement.ref_no == outward.ref_no,
            StockMovement.direction == StockDirection.IN.value,
        ).limit(1))
        serial_strings = outward.serial_numbers or []
        if not serial_strings:
            serials = (await db.execute(select(m.SerialNumber).where(
                m.SerialNumber.remarks == f"Moved by {outward.ref_no}"
            ))).scalars().all()
            serial_strings = [
                row.serial_number or row.imei or row.asset_code or row.consumable_code
                for row in serials
            ]
            serial_strings = [s for s in serial_strings if s]

        rows.append({
            "movement_no": outward.ref_no,
            "movement_type": "BIN_TO_BIN",
            "warehouse_id": outward.warehouse_id,
            "warehouse_name": outward.warehouse_name,
            "source_bin_id": outward.bin_id,
            "source_bin_code": await _bin_code(db, outward.bin_id),
            "destination_bin_id": inward.bin_id if inward else 0,
            "destination_bin_code": await _bin_code(db, inward.bin_id if inward else None),
            "item_id": outward.item_id,
            "item_code": outward.item_code,
            "item_name": outward.item_name,
            "batch_id": outward.batch_id or None,
            "batch_no": outward.batch_no,
            "quantity": outward.quantity,
            "serial_numbers": serial_strings,
            "status": "COMPLETED",
            "moved_by_name": outward.created_by_name,
            "moved_at": outward.created_at,
            "remarks": outward.remarks,
        })
    page["items"] = rows
    return page


# `suggested_bins` was here, and the putaway screen's chips with it.
#
# A suggestion is a system telling a storekeeper where the goods ought to go. That
# was the right shape while a putaway could only be confirmed into a BIN — the
# screen had to narrow a thousand bays down to eight, and the ranking (does THIS
# pack go into that bay, never free cube) was the whole of the value. Placement is
# not narrow any more: `confirm_putaway` takes any rung of the tree, because a
# pallet of drums stands at the end of a lane and a delivery can land before its
# bay is built. A shortlist of eight bays in front of a person who may legitimately
# choose any of nine hundred locations is not advice, it is a wrong answer with a
# ranking on it.
#
# What replaced it is the location picker walking the hierarchy, and the capacity
# meter measuring whatever was chosen. The meter was always the part that told the
# truth; the chips only chose which truths to show first.

# ---------------------------------------------------------------------------
# Picking
# ---------------------------------------------------------------------------

async def list_pickings(db: AsyncSession, params: PageParams, *, status: str | None = None,
                        warehouse_id: int | None = None, search: str | None = None,
                        user=None) -> dict:
    stmt = select(m.Picking)
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.Picking.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        ))
    if status:
        stmt = stmt.where(m.Picking.status == status)
    if warehouse_id:
        stmt = stmt.where(m.Picking.warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.Picking.pick_no.ilike(like), m.Picking.ref_no.ilike(like),
            m.Picking.assigned_to_name.ilike(like)))
    return await paginate(db, stmt.order_by(m.Picking.id.desc()), params)


async def get_picking(db: AsyncSession, picking_id: int, user=None) -> m.Picking:
    picking = await _load(db, m.Picking, picking_id, "Material fulfilment",
                          m.Picking.items)
    # FIXED — see `_assert_in_scope`.
    return await _assert_in_scope(db, user, m.Picking, picking,
                                  warehouse_col=m.Picking.warehouse_id,
                                  label="Material fulfilment")


# ---------------------------------------------------------------------------
# How much of an indent is still owed
#
# An indent is served over time, not in one shot: ten asked, eight approved, four
# issued from the store that had them, the rest sent to procurement, and another four
# issued when that stock lands. A split allocation does the same thing in one go —
# one document per warehouse. Both are normal.
#
# The guards these replace counted DOCUMENTS: one live fulfilment per indent, one
# live issue per indent. That reads "you already served this indent once, go away",
# which is wrong on both counts — it refused the second warehouse of a split
# allocation (so a split could never be approved at all) and the second round after
# procurement.
#
# What actually must not happen is issuing MORE than was approved. So the test is on
# quantity, and each document type counts only its own kind: a picklist counts other
# picklists, an issue counts other issues. Counting both would double-count the
# ordinary picklist -> issue chain, where the same units legitimately appear twice.
# ---------------------------------------------------------------------------

async def _indent_cap(db: AsyncSession, indent_id: int) -> dict[int, Decimal]:
    """Per item, the most this indent may ever be served — what was approved, or what
    was asked for when nothing has been approved yet."""
    from app.modules.indents.models import IndentItem

    caps: dict[int, Decimal] = {}
    for item_id, approved, requested in (await db.execute(
        # The ORM names differ from the columns: `quantity` IS requested_qty.
        select(IndentItem.item_id, IndentItem.approved_quantity, IndentItem.quantity)
        .where(IndentItem.indent_id == indent_id)
    )).all():
        allowed = _d(approved) if _d(approved) > ZERO else _d(requested)
        caps[item_id] = caps.get(item_id, ZERO) + allowed
    return caps


async def _already_issued(db: AsyncSession, indent_id: int,
                          warehouse_id: int | None = None, *,
                          warehouse_ids: list[int] | None = None,
                          exclude_issue_id: int | None = None) -> dict[int, Decimal]:
    """Per item, what live issues from THIS POINT already cover.

    Per point, not per indent, because one indent is served down a chain: the main
    warehouse issues to the MDP, the MDP forwards to the LIP, and both movements are
    the same units travelling — not the indent being served twice. Counting every
    issue anywhere meant the warehouse's leg consumed the whole allowance and the MDP
    could never forward what it had just received.

    Within a point the cap still bites: that point cannot issue more than was approved.
    Cancelled and rejected issues hold nothing, so they free their quantity back up.

    `warehouse_ids` widens "this point" to every point of the same tier — the guard
    passes it, so two main warehouses cannot each issue the whole indent. A line is
    attributed by its OWN `indent_item_id` first and the header second, the rule
    `_indent_id_for_line` applies to incoming lines: a consolidated issue's lines
    were invisible to a header-only match. `exclude_issue_id` leaves out the document
    being edited, whose old lines are about to be replaced.
    """
    from app.modules.indents.models import IndentItem

    owner = func.coalesce(IndentItem.indent_id, m.MaterialIssue.indent_id)
    conditions = [
        owner == indent_id,
        m.MaterialIssue.direction == IssueDirection.OUT.value,
        m.MaterialIssue.status.notin_(DEAD_ISSUE_STATUSES),
    ]
    if warehouse_ids is not None:
        conditions.append(m.MaterialIssue.warehouse_id.in_(warehouse_ids))
    elif warehouse_id is not None:
        conditions.append(m.MaterialIssue.warehouse_id == warehouse_id)
    if exclude_issue_id is not None:
        conditions.append(m.MaterialIssue.id != exclude_issue_id)
    rows = (await db.execute(
        select(m.MaterialIssueLine.item_id,
               func.coalesce(func.sum(m.MaterialIssueLine.issued_qty), 0))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .outerjoin(IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id)
        .where(*conditions)
        .group_by(m.MaterialIssueLine.item_id)
    )).all()
    return {item_id: _d(qty) for item_id, qty in rows}


async def _same_tier_warehouse_ids(db: AsyncSession, warehouse_id: int) -> list[int]:
    """Every point on the same rung of the chain as this one, itself included.

    The indent cap is per TIER, not per point: WH -> MDP -> LIP are the same units
    travelling and each rung gets its own allowance, but two points on one rung are
    two sources for the same demand and must share it.
    """
    wh = await db.get(Warehouse, warehouse_id)
    if wh is None:
        return [warehouse_id]
    tier = stock_locations.tier_of(wh.warehouse_type)
    rows = (await db.execute(select(Warehouse.id, Warehouse.warehouse_type))).all()
    return [wid for wid, kind in rows if stock_locations.tier_of(kind) is tier]


async def _already_picking(db: AsyncSession, indent_id: int,
                           warehouse_id: int | None = None) -> dict[int, Decimal]:
    """Per item, what open fulfilments already cover. `out_picking_items` carries no
    indent line, so this matches on the item — which is the level the cap is at too."""
    rows = (await db.execute(
        select(m.PickingItem.item_id,
               func.coalesce(func.sum(m.PickingItem.required_qty), 0))
        .join(m.Picking, m.Picking.id == m.PickingItem.picking_id)
        .where(
            m.Picking.ref_type == "INDENT",
            m.Picking.ref_id == indent_id,
            m.Picking.status != PickingStatus.CANCELLED.value,
            *([m.Picking.warehouse_id == warehouse_id]
              if warehouse_id is not None else []),
        )
        .group_by(m.PickingItem.item_id)
    )).all()
    return {item_id: _d(qty) for item_id, qty in rows}


async def _live_issue_labels(db: AsyncSession, indent_id: int,
                             warehouse_ids: list[int] | None,
                             exclude_issue_id: int | None = None) -> str:
    """The issues already holding this indent's quantity here, named and with status.

    "Nothing is outstanding" is a true answer to the wrong question when the thing
    holding the quantity is a draft the same person raised a minute ago. Name it:
    the store can open it and finish it instead of guessing what drew the stock.
    Same scope and same line attribution as `_already_issued`, so the documents named
    are exactly the ones that were counted.
    """
    from app.modules.indents.models import IndentItem

    conditions = [
        func.coalesce(IndentItem.indent_id, m.MaterialIssue.indent_id) == indent_id,
        m.MaterialIssue.direction == IssueDirection.OUT.value,
        m.MaterialIssue.status.notin_(DEAD_ISSUE_STATUSES),
    ]
    if warehouse_ids is not None:
        conditions.append(m.MaterialIssue.warehouse_id.in_(warehouse_ids))
    if exclude_issue_id is not None:
        conditions.append(m.MaterialIssue.id != exclude_issue_id)
    rows = (await db.execute(
        # id is selected because MySQL refuses DISTINCT ordered by a column outside
        # the select list (3065).
        select(m.MaterialIssue.id, m.MaterialIssue.issue_no, m.MaterialIssue.status)
        .join(m.MaterialIssueLine, m.MaterialIssueLine.issue_id == m.MaterialIssue.id)
        .outerjoin(IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id)
        .where(*conditions)
        .distinct().order_by(m.MaterialIssue.id)
    )).all()
    return ", ".join(f"{issue_no} ({status})" for _, issue_no, status in rows)


async def _guard_issue_indent_caps(db: AsyncSession, items: list, header_indent_id: int | None,
                                   warehouse_id: int,
                                   exclude_issue_id: int | None = None) -> set[int]:
    """Refuses an outward issue that would take any indent it serves past approval.

    The ONE check, run on create AND on edit. It used to run on create only, so a
    draft raised small and then edited up — or raised with no lines and filled in
    afterwards — was never measured, and an indent already issued in full could be
    issued again. Returns the indent ids the lines serve (empty = none).

    A line with no `issued_qty` is counted at its requested quantity, which is what
    `_apply_issue_lines` will store for it; reading None as zero let it skip the cap.
    """
    from app.modules.indents.models import Indent

    wanted: dict[int, dict[int, Decimal]] = defaultdict(dict)
    for line in items:
        owner = await _indent_id_for_line(db, line, header_indent_id)
        if not owner:
            continue
        qty = _d(line.requested_qty if line.issued_qty is None else line.issued_qty)
        by_item = wanted[owner]
        by_item[line.item_id] = by_item.get(line.item_id, ZERO) + qty
    if not wanted:
        return set()
    # Scoped to THIS TIER: the same indent is served down a chain, and the
    # warehouse's leg must not consume the MDP's allowance to forward on — but two
    # points on one rung are sharing one demand.
    peers = await _same_tier_warehouse_ids(db, warehouse_id)
    for indent_id, by_item in wanted.items():
        served = await db.get(Indent, indent_id)
        if served is None:
            continue
        await _guard_indent_quantity(
            db, served.id, served.indent_no, by_item,
            await _already_issued(db, served.id, warehouse_ids=peers,
                                  exclude_issue_id=exclude_issue_id),
            "issue",
            await _live_issue_labels(db, served.id, peers, exclude_issue_id),
        )
    return set(wanted)


async def _guard_network_own_stock(db: AsyncSession, items: list,
                                   header_indent_id: int | None, warehouse_id: int, *,
                                   exclude_issue_id: int | None = None) -> None:
    """Across EVERY point, an indent may be served at most its approved quantity out of
    points' OWN stock (2026-10-06).

    The per-tier cap (`_guard_issue_indent_caps`) lets each rung of the chain issue the
    whole indent, because WH -> MDP -> LIP is the same units travelling. That is right
    for a forwarded leg and wrong for anything else: once the LIP had served its share
    from its own shelf, the main warehouse could still issue the indent's full approved
    quantity again out of free stock — the same item to the same indent, twice.

    So the units each point gives from its own shelf are counted network-wide: what a
    point issued for the indent, less what ARRIVED there for the indent on a dispatch
    receipt (that part is passing through, already counted where it came from). The
    sum may not pass the approved quantity. A pure forwarding leg adds nothing to it and
    is never refused here.
    """
    from app.modules.indents.models import Indent as Indent_, IndentItem

    wanted: dict[int, dict[int, Decimal]] = defaultdict(lambda: defaultdict(lambda: ZERO))
    for line in items:
        owner = await _indent_id_for_line(db, line, header_indent_id)
        if not owner:
            continue
        wanted[owner][int(line.item_id)] += _d(
            line.requested_qty if line.issued_qty is None else line.issued_qty)

    for indent_id, by_item in wanted.items():
        caps = await _indent_cap(db, indent_id)
        if not caps:
            continue
        owner = func.coalesce(IndentItem.indent_id, m.MaterialIssue.indent_id)
        issued: dict[tuple[int, int], Decimal] = defaultdict(lambda: ZERO)
        for wh_id, item_id, qty in (await db.execute(
            select(m.MaterialIssue.warehouse_id, m.MaterialIssueLine.item_id,
                   func.coalesce(func.sum(m.MaterialIssueLine.issued_qty), 0))
            .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
            .outerjoin(IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id)
            .where(owner == indent_id,
                   m.MaterialIssue.direction == IssueDirection.OUT.value,
                   m.MaterialIssue.status.notin_(DEAD_ISSUE_STATUSES),
                   *([m.MaterialIssue.id != exclude_issue_id] if exclude_issue_id else []))
            .group_by(m.MaterialIssue.warehouse_id, m.MaterialIssueLine.item_id)
        )).all():
            issued[(int(wh_id), int(item_id))] += _d(qty)
        arrived: dict[tuple[int, int], Decimal] = defaultdict(lambda: ZERO)
        for wh_id, item_id, qty in (await db.execute(
            select(m.Receipt.warehouse_id, m.ReceiptItem.item_id,
                   func.coalesce(func.sum(m.ReceiptItem.received_qty), 0))
            .join(m.Receipt, m.Receipt.id == m.ReceiptItem.receipt_id)
            .where(m.Receipt.receipt_type == ReceiptType.DISPATCH.value,
                   m.ReceiptItem.indent_id == indent_id,
                   m.Receipt.status.notin_((ReceiptStatus.DRAFT.value,
                                            ReceiptStatus.CANCELLED.value)))
            .group_by(m.Receipt.warehouse_id, m.ReceiptItem.item_id)
        )).all():
            arrived[(int(wh_id), int(item_id))] += _d(qty)

        def own_total(extra: dict[int, Decimal]) -> dict[int, Decimal]:
            totals: dict[int, Decimal] = defaultdict(lambda: ZERO)
            points = {key for key in issued} | {(warehouse_id, i) for i in extra}
            for wh_id, item_id in points:
                qty = issued.get((wh_id, item_id), ZERO) + (
                    extra.get(item_id, ZERO) if wh_id == warehouse_id else ZERO)
                totals[item_id] += max(ZERO, qty - arrived.get((wh_id, item_id), ZERO))
            return totals

        before, after = own_total({}), own_total(by_item)
        for item_id, total in after.items():
            cap = caps.get(item_id)
            if cap is None or total <= cap or total <= before.get(item_id, ZERO):
                continue
            indent_no = await db.scalar(
                select(Indent_.indent_no).where(Indent_.id == indent_id))
            name = getattr(await db.get(Item, item_id), "name", None) or f"item {item_id}"
            served = before.get(item_id, ZERO)
            raise ValidationError(
                f"{indent_no}: {name} has already been served {served} of {cap} from "
                f"stock across the warehouse, MDP and LIP points. This issue would give "
                f"{total - served} more of this point's own stock — at most "
                f"{max(cap - served, ZERO)} may still go out.")


async def _unposted_claims(db: AsyncSession, indent_id: int, warehouse_id: int, *,
                           exclude_issue_id: int | None = None) -> dict[int, Decimal]:
    """Per indent LINE, what live issues at THIS point have claimed but not yet posted.

    Posting consumes the reservation, so a posted issue has already taken its share
    off `held_here`. An unposted one has not — it is a claim on the same hold, and two
    of them each claiming the whole of it is how one point drafted the same three
    units twice. A split parent is dead (its children carry the claim).
    """
    from app.modules.indents.models import IndentItem

    rows = (await db.execute(
        select(m.MaterialIssueLine.indent_item_id,
               func.coalesce(func.sum(m.MaterialIssueLine.issued_qty), 0))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .join(IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id)
        .where(IndentItem.indent_id == indent_id,
               m.MaterialIssue.warehouse_id == warehouse_id,
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(False),
               m.MaterialIssue.status.notin_(DEAD_ISSUE_STATUSES),
               *([m.MaterialIssue.id != exclude_issue_id] if exclude_issue_id else []))
        .group_by(m.MaterialIssueLine.indent_item_id)
    )).all()
    return {int(line_id): _d(qty) for line_id, qty in rows if line_id}


async def _held_by_line(db: AsyncSession, indent_id: int, *,
                        warehouse_id: int | None = None) -> dict[int, Decimal]:
    """Per indent line, what the allocation still holds — at one point, or anywhere."""
    from app.modules.inventory.models import Reservation

    stmt = (select(Reservation.ref_line_id, func.sum(Reservation.quantity))
            .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
                   Reservation.ref_id == indent_id,
                   Reservation.status == ReservationStatus.ACTIVE.value)
            .group_by(Reservation.ref_line_id))
    if warehouse_id is not None:
        stmt = stmt.where(Reservation.warehouse_id == warehouse_id)
    return {int(line_id): _d(qty) for line_id, qty in (await db.execute(stmt)).all()
            if line_id}


async def _forwarding_point(db: AsyncSession, indent_id: int, warehouse_id: int) -> bool:
    """Did goods for this indent ARRIVE at this point on a dispatch receipt — is it a
    middle leg of WH -> MDP -> LIP for it? (`_is_forwarding`, for one indent.)"""
    return bool(await db.scalar(
        select(m.Receipt.id)
        .join(m.ReceiptItem, m.ReceiptItem.receipt_id == m.Receipt.id)
        .where(m.Receipt.receipt_type == ReceiptType.DISPATCH.value,
               m.Receipt.warehouse_id == warehouse_id,
               m.Receipt.status != ReceiptStatus.CANCELLED.value,
               m.ReceiptItem.indent_id == indent_id)
        .limit(1)))


async def _guard_point_reservation(db: AsyncSession, items: list,
                                   header_indent_id: int | None, warehouse_id: int, *,
                                   exclude_issue_id: int | None = None) -> None:
    """Refuse an indent line asking this point for more than its allocation here still
    has unclaimed (2026-10-06).

    The same rule `post_issue` applies — an indent line with a reservation anywhere may
    only issue what is reserved AT THIS POINT — asked at save time, net of the other
    unposted issues already claiming it. Without it a second draft for the same three
    units saved, climbed the whole approval ladder and only failed at the shelf.

    A line whose indent holds nothing anywhere (forwarded goods, a manual issue after
    the allocation was spent) is not measured here: the indent cap still bounds it.
    """
    from app.modules.indents.models import Indent

    wanted: dict[tuple[int, int], Decimal] = defaultdict(lambda: ZERO)
    labels: dict[tuple[int, int], str] = {}
    for line in items:
        if not getattr(line, "indent_item_id", None):
            continue
        owner = await _indent_id_for_line(db, line, header_indent_id)
        if not owner:
            continue
        key = (owner, int(line.indent_item_id))
        wanted[key] += _d(line.requested_qty if line.issued_qty is None
                          else line.issued_qty)
        labels[key] = getattr(line, "item_code", None) or f"item {line.item_id}"
    for (indent_id, line_id), qty in wanted.items():
        if qty <= ZERO:
            continue
        anywhere = (await _held_by_line(db, indent_id)).get(line_id, ZERO)
        if anywhere <= ZERO:
            continue
        # A forwarding point issues goods that arrived for the indent with no hold
        # here; the network own-stock cap bounds it instead.
        if await _forwarding_point(db, indent_id, warehouse_id):
            continue
        here = (await _held_by_line(db, indent_id, warehouse_id=warehouse_id)).get(
            line_id, ZERO)
        claimed = (await _unposted_claims(
            db, indent_id, warehouse_id, exclude_issue_id=exclude_issue_id)).get(
            line_id, ZERO)
        open_here = here - claimed
        if qty > open_here:
            indent_no = await db.scalar(
                select(Indent.indent_no).where(Indent.id == indent_id))
            others = await _live_issue_labels(db, indent_id, [warehouse_id],
                                              exclude_issue_id)
            raise ValidationError(
                f"{indent_no}: {labels[(indent_id, line_id)]} has {here} allocated at "
                f"this point"
                + (f", {claimed} of it already claimed by {others}" if claimed else "")
                + f" — {max(open_here, ZERO)} is left to issue here, not {qty}."
                + (" Open that issue instead of raising another." if claimed else ""))


async def _guard_indent_quantity(db: AsyncSession, indent_id: int, indent_no: str,
                                 wanted: dict[int, Decimal], taken: dict[int, Decimal],
                                 doc: str, holders: str = "") -> None:
    """Refuses a document that would take an indent past what was approved.

    `taken` is what documents of this same kind already hold — the new document's own
    lines are not in it yet, so the sum is what the indent would stand at afterwards.
    `holders` names those documents, so the refusal says what to go and look at.
    """
    caps = await _indent_cap(db, indent_id)
    if not caps:
        return   # nothing to measure against; the indent lines are gone
    for item_id, qty in wanted.items():
        if qty <= ZERO:
            continue
        cap = caps.get(item_id)
        if cap is None:
            continue   # an item the indent never asked for — other guards own that
        outstanding = cap - taken.get(item_id, ZERO)
        if qty > outstanding:
            name = (await db.get(Item, item_id)) if item_id else None
            label = getattr(name, "name", None) or f"item {item_id}"
            by = f" by {holders}" if holders else ""
            if outstanding <= ZERO:
                raise ValidationError(
                    f"{indent_no} is already covered for {label} — {cap} of {cap}"
                    f"{by}. Open that document to continue; there is nothing left to "
                    f"{doc.lower()} against this indent."
                )
            raise ValidationError(
                f"{indent_no} only has {outstanding} of {label} outstanding "
                f"({taken.get(item_id, ZERO)} of {cap} already covered{by}). "
                f"Reduce this {doc.lower()} to {outstanding} or less."
            )


async def _build_picking(db: AsyncSession, data: s.PickingWrite, user) -> m.Picking:
    """Build one material-fulfilment draft without committing it.

    Keeping construction separate from the public create endpoint lets allocation
    approval create every warehouse draft in the same transaction as its stock
    reservations. A split allocation therefore either creates all of its drafts or
    none of them.
    """
    wh = await _warehouse(db, data.warehouse_id)
    if not data.items:
        raise ValidationError("A material fulfilment with no lines gives the warehouse nothing to do")
    if data.ref_type == "INDENT" and not data.ref_id:
        raise ValidationError("An indent fulfilment needs an indent reference")

    if data.ref_type == "INDENT" and data.ref_id:
        # An indent may carry as many fulfilments as it takes to serve it — one per
        # warehouse in a split, and another round when procurement lands the shortfall.
        # What it may not do is total more than was approved. See _guard_indent_quantity.
        from app.modules.indents.models import Indent as _Indent

        indent_row = await db.get(_Indent, data.ref_id)
        wanted_by_item: dict[int, Decimal] = {}
        for line in data.items:
            wanted_by_item[line.item_id] = (
                wanted_by_item.get(line.item_id, ZERO) + _d(line.required_qty))
        await _guard_indent_quantity(
            db, data.ref_id,
            getattr(indent_row, "indent_no", None) or f"Indent {data.ref_id}",
            wanted_by_item, await _already_picking(db, data.ref_id, wh.id),
            "material fulfilment",
        )

        requested_by_item: dict[int, Decimal] = {}
        for line in data.items:
            requested_by_item[line.item_id] = (
                requested_by_item.get(line.item_id, ZERO) + _d(line.required_qty)
            )
        for item_id, required in requested_by_item.items():
            held = await stock_allocation.reserved_quantity(
                db,
                InventoryRefType.RESERVATION.value,
                data.ref_id,
                item_id=item_id,
                warehouse_id=wh.id,
            )
            if required > held:
                raise ValidationError(
                    f"Item {item_id}: fulfilment asks for {required}, but only {held} "
                    "is reserved for this indent in the warehouse."
                )

    picking = m.Picking(
        items=[],   # see create_issue: keeps the append below off a lazy load
        pick_no=await next_number(db, WarehouseDocType.PICKING.value),
        pick_date=data.pick_date,
        warehouse_id=wh.id, warehouse_name=wh.name,
        ref_type=data.ref_type, ref_id=data.ref_id,
        ref_no=await _warehouse_reference_no(db, data.ref_type, data.ref_id),
        strategy=data.strategy.value,
        status=PickingStatus.DRAFT.value,
        assigned_to_id=data.assigned_to_id,
        total_lines=len(data.items), picked_lines=0,
    )
    db.add(picking)
    await db.flush()

    for index, line in enumerate(data.items, start=1):
        item = await _item_snapshot(db, line.item_id)
        required = _d(line.required_qty)
        if required <= ZERO:
            raise ValidationError(f"Line {index}: required quantity must be positive")
        if line.bin_id:
            source_bin = await _get(db, Bin, line.bin_id, "Bin")
            if source_bin.warehouse_id != wh.id:
                raise ValidationError(
                    f"Line {index}: bin {source_bin.code} is not in {wh.name}"
                )
        batch = await db.get(m.Batch, line.batch_id) if line.batch_id else None
        # Nobody named a bin, so ask stock where the item is rather than sending the
        # picker out with "any". See _pick_bin_for.
        resolved_bin = line.bin_id or await _pick_bin_for(
            db, item_id=item.id, warehouse_id=wh.id, batch_id=line.batch_id or None,
        )
        picking.items.append(m.PickingItem(
            line_no=index, item_id=item.id, item_code=item.code, item_name=item.name,
            uom_code=item.uom_code,
            # The sentinel, not NULL. out_picking_items.bin_id and .batch_id are
            # NOT NULL DEFAULT 0 in the live schema even though the model says
            # nullable, so an unbinned/unbatched line has to be written as 0 the way
            # every other whs_ table already does.
            bin_id=resolved_bin or m.NO_BIN,
            bin_code=await _bin_code(db, resolved_bin),
            batch_id=line.batch_id or m.NO_BATCH,
            batch_no=batch.batch_no if batch else None,
            required_qty=required, picked_qty=ZERO,
            status=PickLineStatus.PENDING.value,
        ))
    await db.flush()

    await write_audit(db, entity="out_picking", entity_id=picking.id, entity_no=picking.pick_no,
                      action=AuditAction.CREATE, actor=user,
                      after={"status": picking.status, "lines": picking.total_lines})
    return picking


async def create_picking(db: AsyncSession, data: s.PickingWrite, user) -> m.Picking:
    picking = await _build_picking(db, data, user)
    await db.commit()
    return await get_picking(db, picking.id)


async def create_fulfilment_drafts_for_allocation(db: AsyncSession, alloc, user) -> list[m.MaterialIssue]:
    """Create one material issue draft per warehouse in an approved allocation.

    The automatic Inventory -> Warehouse handoff, and the head of the draft chain:
    allocation approved -> ISSUE draft -> (post stock) -> PICKING draft ->
    (complete pick) -> CONSIGNMENT. The issue comes first because posting stock is
    what turns an allocation into goods the floor can pick; a picklist raised before
    that would be asking someone to walk for stock nothing had committed yet.

    Allocation lines are combined by item within a warehouse. A split allocation
    therefore yields one draft per site, each carrying its own lines.
    """
    by_warehouse: dict[int, dict[int, dict]] = {}
    for line in alloc.items:
        qty = _d(line.quantity)
        if qty <= ZERO or not line.warehouse_id:
            continue
        by_item = by_warehouse.setdefault(line.warehouse_id, {})
        seen = by_item.get(line.item_id)
        if seen is None:
            by_item[line.item_id] = {
                "qty": qty,
                "requested": _d(line.requested_qty),
                # Only carried when the item maps to exactly one indent line. A line
                # split across warehouses would otherwise point every draft at the
                # same indent line and double-count it on the fulfilment view.
                "indent_item_id": line.indent_item_id,
                "project_id": line.project_id,
            }
        else:
            seen["qty"] += qty
            seen["requested"] += _d(line.requested_qty)
            if seen["indent_item_id"] != line.indent_item_id:
                seen["indent_item_id"] = None

    # The person the goods are for is the one who raised the indent — the same answer
    # _issue_destination already falls back to. Filling it here means the draft opens
    # with "Issued to" named instead of blank; the store can still change it.
    from app.modules.indents.models import Indent
    indent = await db.get(Indent, alloc.indent_id) if alloc.indent_id else None
    issued_to_id = getattr(indent, "requested_by_id", None) if indent else None
    # The indent already named the vehicle it is going out on. Same rule as the
    # person: default it in, leave it typeable.
    vehicle_id = getattr(indent, "vehicle_id", None) if indent else None
    vehicle_number = (getattr(indent, "vehicle_number", None) if indent else None) or (
        _vehicle_from_office_name(getattr(indent, "office_name", None) if indent else None)
    )

    drafts: list[m.MaterialIssue] = []
    for warehouse_id, lines in by_warehouse.items():
        # FIXED 2026-08-21 — draft only the INCREMENT, never the whole allocation.
        #
        # A requirement collects more than one approved allocation: the cascade hands
        # the remainder up the chain, and once the goods for a shortfall arrive the desk
        # allocates the rest against the same indent lines. The line an earlier
        # signature already issued is still owed nothing, so this used to re-draft the
        # full quantity and `_guard_indent_quantity` refused the whole batch:
        # "IND/2026-27/00093 is already covered for K2 EDTA Vacutainer Lavender 2 ml —
        # 10.000 of 10.000 by WHI/2026-27/00045 (ISSUED)". One settled line took the
        # topped-up line down with it, so nothing could be issued at all.
        #
        # The reservation half of approval was already incremental — `_settle_approved`
        # reserves the DIFFERENCE — and this is that same rule for the handoff. Netted
        # against live issues from THIS point only, the same scope the guard applies, so
        # a chain leg still gets its own allowance. An item with nothing left drops out
        # rather than raising: it is not an error for a line to be finished.
        #
        # This is NOT specific to a self-approving ladder. A reopened allocation signed
        # by a real approver reaches the identical handoff through `act()`, and hit the
        # identical refusal.
        already = await _already_issued(db, alloc.indent_id, warehouse_id)
        outstanding: dict[int, dict] = {}
        for item_id, v in lines.items():
            left = _d(v["qty"]) - already.get(item_id, ZERO)
            if left <= ZERO:
                continue
            outstanding[item_id] = {**v, "qty": left}
        if not outstanding:
            continue
        lines = outstanding
        # The CONSUMING project is the indent's (an STR's own project); the stock's
        # project is only the fallback for an indent that carries none.
        project_id = getattr(indent, "project_id", None) or next(
            (v["project_id"] for v in lines.values() if v["project_id"]), None
        )
        items: list[s.IssueItemWrite] = []
        for item_id, v in lines.items():
            items.extend(await _allocation_lines_by_batch(
                db, alloc.indent_id, warehouse_id, item_id, v,
            ))
        if not items:
            continue
        data = s.IssueWrite(
            issue_date=ist_today(),
            warehouse_id=warehouse_id,
            indent_id=alloc.indent_id,
            project_id=project_id,
            issued_to_id=issued_to_id,
            vehicle_id=vehicle_id,
            vehicle_number=vehicle_number,
            items=items,
        )
        draft = await _build_issue(db, data, user)
        drafts.append(draft)
        if indent is not None and indent.indent_type == _STR_INDENT_TYPE:
            await _record_sto_for_str_issue(db, draft, indent, user)
    return drafts


#: An indent of this type is a Stock Transfer Request — its served issues are STOs.
_STR_INDENT_TYPE = IndentType.STR.value


async def _record_sto_for_str_issue(db: AsyncSession, issue: m.MaterialIssue,
                                    indent, user) -> None:
    """The Stock Transfer Order one served STR produces, per source point.

    The allocation decided which point gives what; that decision, signed, IS the
    order. It is recorded as an `inv_sto` row pointing back at the STR and forward at
    the material issue that executes it, so Inventory > Stock Transfer can list the
    orders an STR produced. The row never moves stock — the issue posts it out and
    the requester's acknowledgement credits it in — so it is written APPROVED and its
    progress is read off the issue (`inventory.service._decorate_sto_stages`).
    """
    from app.modules.inventory.enums import STOStatus
    from app.modules.inventory.models import (
        STO_KIND_TRANSFER, StockTransferOrder, StockTransferOrderItem,
    )

    source = await db.get(Warehouse, issue.warehouse_id)
    destination = await _requesting_point(db, issue)
    order = StockTransferOrder(
        sto_no=await next_number(db, "sto", project=indent.project_name),
        doc_kind=STO_KIND_TRANSFER,
        from_warehouse_id=issue.warehouse_id,
        from_warehouse_name=getattr(source, "name", None) or issue.warehouse_name,
        # The requesting point may be unresolvable (an office with no stocking point);
        # the column is NOT NULL, so the source stands in and the name says why.
        to_warehouse_id=destination.id if destination else issue.warehouse_id,
        to_warehouse_name=(destination.name if destination
                           else f"{indent.office_name or 'Requester'} (no stocking point)"),
        from_project_id=indent.project_id or 0,
        to_project_id=indent.project_id or 0,
        status=STOStatus.APPROVED.value,
        requested_by_id=indent.requested_by_id,
        requested_by_name=indent.requested_by_name,
        approved_by_name=_name(user),
        approved_at=utcnow(),
        str_id=indent.id,
        str_no=indent.indent_no,
        issue_id=issue.id,
        issue_no=issue.issue_no,
        remarks=f"Serves {indent.indent_no}",
    )
    # One order line per ITEM: the issue splits an item over the batches and bays it
    # was reserved from, which is the storekeeper's detail, not the order's.
    # Per brand / variant / model too (2026-10-23).
    by_item: dict[tuple, StockTransferOrderItem] = {}
    for line in issue.items:
        key = (line.item_id, combo_key(line))
        row = by_item.get(key)
        if row is None:
            by_item[key] = StockTransferOrderItem(
                item_id=line.item_id, item_code=line.item_code,
                item_name=line.item_name, uom_code=line.uom_code,
                requested_qty=_d(line.requested_qty), **combinations.carry(line))
        else:
            row.requested_qty = _d(row.requested_qty) + _d(line.requested_qty)
    order.items = list(by_item.values())
    db.add(order)
    await db.flush()
    issue.remarks = " · ".join(filter(None, (issue.remarks, f"STO {order.sto_no}")))
    if destination is not None and not getattr(issue, "destination_warehouse_id", None):
        issue.destination_warehouse_id = destination.id
        issue.destination_warehouse_name = destination.name


async def draft_issue_for_sto(db: AsyncSession, sto, user) -> None:
    """ON_STO_APPROVED: a directly raised STO becomes a material issue draft at the
    source point, where the storekeeper picks batch, bay and serials exactly as for any
    other issue. An STO serving an STR already has its issue (the allocation drafted
    it), and a movement order (SMO) never leaves the building."""
    from app.modules.inventory.models import STO_KIND_TRANSFER

    if sto.doc_kind != STO_KIND_TRANSFER or sto.issue_id or sto.str_id:
        return
    # Project: the STO's own, else the source point's tag. Department: the raiser's
    # HCM department — an STO carries none of its own, and a blank here is copied onto
    # every floor piece of a split.
    from app.platform.hcm.models import HcmEmployee
    raiser = (await db.get(HcmEmployee, sto.requested_by_id)
              if getattr(sto, "requested_by_id", None) else None)
    project_id = (sto.from_project_id
                  or await stock_locations.project_of_location(db, sto.from_warehouse_id)
                  or getattr(raiser, "project_id", None) or None)
    data = s.IssueWrite(
        issue_date=ist_today(),
        warehouse_id=sto.from_warehouse_id,
        project_id=project_id,
        department_id=getattr(raiser, "department_id", None),
        remarks=f"STO {sto.sto_no} to {sto.to_warehouse_name}",
        # The order names where the goods go; the issue carries it from the first save
        # so the consignment and the receiving side read it without asking (2026-10-29).
        destination_warehouse_id=sto.to_warehouse_id,
        items=[s.IssueItemWrite(item_id=line.item_id, requested_qty=_d(line.requested_qty),
                                brand_id=line.brand_id or None,
                                variant_id=line.variant_id or None,
                                model_id=line.model_id or None)
               for line in sto.items],
    )
    issue = await _build_issue(db, data, user, for_sto=True)
    sto.issue_id = issue.id
    sto.issue_no = issue.issue_no
    await db.commit()


async def _allocation_lines_by_batch(
    db: AsyncSession,
    indent_id: int,
    warehouse_id: int,
    item_id: int,
    allocated: dict,
) -> list[s.IssueItemWrite]:
    """Split one allocated quantity into the batches and bins it was reserved from.

    `inv_allocation_items` records a quantity and a warehouse, nothing finer, so this
    used to draft one issue line on NO_BATCH/NO_BIN. Every document after it inherited
    that blank: no batch number, no expiry, no manufacturing date on the issue, the
    consignment, or the GRN at the receiving point — and the serial picker fell back to
    every unit the warehouse holds instead of the ones actually set aside.

    The detail was never missing, only unread. `allocate_for_indent` writes one
    `inv_reservations` row per stock row it draws from, and a stock row IS a
    (warehouse, bin, batch) — so the reservations spell out exactly which goods were
    promised. Read them back and draft one line per rung.

    Falls back to a single unsplit line when the reservations do not add up to what was
    allocated: a hand-edited allocation must still produce an issue, just a vaguer one.
    """
    from app.modules.inventory.models import Reservation

    qty = _d(allocated["qty"])
    base = {
        "item_id": item_id,
        "indent_item_id": allocated["indent_item_id"],
        "requested_qty": _d(allocated["requested"]) or qty,
    }
    # An allocation sets aside a QUANTITY, never a batch (2026-10-12): the batch is
    # the storekeeper's pick on the issue, offered earliest-expiry first, so whichever
    # indent is issued first gets the earliest-expiring stock. Drafting one line per
    # reserved batch put the allocator's row choice back on the document — exactly the
    # FEFO break this replaces. One line, no batch, no location.
    del indent_id, warehouse_id
    return [s.IssueItemWrite(**base, issued_qty=qty)]


async def _warehouse_reference_no(
    db: AsyncSession, ref_type: str | None, ref_id: int | None,
) -> str | None:
    if not ref_type or not ref_id:
        return None
    if ref_type == "INDENT":
        from app.modules.indents.models import Indent
        row = await db.get(Indent, ref_id)
        return row.indent_no if row else None
    if ref_type == "ISSUE":
        row = await db.get(m.MaterialIssue, ref_id)
        return row.issue_no if row else None
    if ref_type == "DISPATCH":
        row = await db.get(m.Dispatch, ref_id)
        return row.dispatch_no if row else None
    return None


async def release_picking(db: AsyncSession, picking_id: int, user) -> m.Picking:
    picking = await get_picking(db, picking_id)
    _guard(picking.status, {PickingStatus.DRAFT.value}, "release", "material fulfilment")
    picking.status = PickingStatus.RELEASED.value

    await write_audit(db, entity="out_picking", entity_id=picking.id, entity_no=picking.pick_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": PickingStatus.DRAFT.value},
                      after={"status": picking.status})
    await db.commit()
    return await get_picking(db, picking_id)


async def pick_line(db: AsyncSession, picking_id: int, line_id: int, data: s.PickLine,
                    user) -> m.Picking:
    """Confirms one line.

    Each line is its own request so a picker who loses signal halfway has not lost the
    first half of the trolley. Picking does not move stock — the issue that follows
    does; a picked line is stock in a trolley, still in the warehouse.
    """
    picking = await get_picking(db, picking_id)
    _guard(picking.status, {PickingStatus.RELEASED.value, PickingStatus.IN_PROGRESS.value},
           "pick against", "material fulfilment")

    line = next((l for l in picking.items if l.id == line_id), None)
    if line is None:
        raise NotFoundError(f"Line {line_id} is not on {picking.pick_no}")
    if line.status == PickLineStatus.PICKED.value:
        raise ValidationError(f"Line {line.line_no} is already picked")

    picked = _d(data.picked_qty)
    if picked <= ZERO:
        raise ValidationError("Picked quantity must be positive")
    if picked > _d(line.required_qty):
        raise ValidationError(
            f"Line {line.line_no} needs {line.required_qty}; {picked} is more than that.")

    line.picked_qty = picked
    line.status = (PickLineStatus.PICKED if picked >= _d(line.required_qty)
                   else PickLineStatus.SHORT).value
    line.picked_by_id = getattr(user, "id", None)
    line.picked_at = utcnow()
    if data.bin_id:
        source_bin = await _get(db, Bin, data.bin_id, "Bin")
        if source_bin.warehouse_id != picking.warehouse_id:
            raise ValidationError(
                f"Bin {source_bin.code} is not in {picking.warehouse_name}"
            )
        line.bin_id = source_bin.id
        line.bin_code = source_bin.code

    picking.picked_lines = sum(
        1 for l in picking.items
        if l.status in (PickLineStatus.PICKED.value, PickLineStatus.SHORT.value))
    if picking.status == PickingStatus.RELEASED.value:
        picking.status = PickingStatus.IN_PROGRESS.value
        picking.started_at = picking.started_at or utcnow()

    await write_audit(db, entity="out_picking_items", entity_id=line.id,
                      entity_no=picking.pick_no, action=AuditAction.UPDATE, actor=user,
                      after={"line_no": line.line_no, "picked_qty": str(picked),
                             "status": line.status})
    await db.commit()
    return await get_picking(db, picking_id)


async def _raise_consignment_for_picking(
    db: AsyncSession, picking: m.Picking, user,
) -> "m.Dispatch | None":
    """Raise the consignment that follows a completed pick.

    Rung three of the draft chain. Only picks raised off an issue carry a
    consignment — a pick against an indent under the older pick-then-issue path has
    no posted issue behind it yet, and a consignment has to point at one.

    Everything issued goes into a single package, since the storekeeper who just
    filled one trolley is the one who knows how it actually splits into boxes; the
    consignment form lets them break it up. Packing is validated as exactly-equals
    issued, so anything less than the whole issue would be rejected here.

    A failure here must not lose the pick, which is a physical fact already recorded.
    The consignment is convenience; it can be raised by hand from the issue.
    """
    if picking.ref_type != "ISSUE" or not picking.ref_id:
        return None
    if picking.status != PickingStatus.COMPLETED.value:
        return None      # a short pick cannot pack to the issued quantity

    if await _live_consignment_for_issue(db, picking.ref_id) is not None:
        return None

    issue = await get_issue(db, picking.ref_id)
    if not issue.is_stock_posted or issue.direction != IssueDirection.OUT.value:
        return None

    # Serial-tracked lines have to name their serials, and only the ones this issue
    # actually put out; the packer validates against exactly that set.
    serials_by_key: dict[tuple[int, int], list[str]] = {}
    serials_by_item: dict[int, list[str]] = {}
    # The index files one unit under each of its names; walk each unit ONCE.
    for row in {row.id: row for row in (await _issued_serial_index(db, issue)).values()}.values():
        serials_by_key.setdefault(
            (row.item_id, row.batch_id or m.NO_BATCH), []
        ).append(row.serial_number)
        serials_by_item.setdefault(row.item_id, []).append(row.serial_number)

    lines: list[s.ConsignmentPackageItemWrite] = []
    for (item_id, batch_id), qty in _issue_qty_by_item_batch(issue).items():
        if qty <= ZERO:
            continue
        item = await db.get(Item, item_id)
        picked = serials_by_key.get((item_id, batch_id))
        if not picked and (not batch_id or batch_id == m.NO_BATCH):
            picked = serials_by_item.get(item_id, [])
        if picked is None:
            picked = []
        if item is not None and item.is_serial_tracked and len(picked) != int(qty):
            return None       # serials incomplete — let the storekeeper pack by hand
        lines.append(s.ConsignmentPackageItemWrite(
            item_id=item_id,
            batch_id=None if batch_id == m.NO_BATCH else batch_id,
            serial_numbers=picked,
            quantity=qty,
            indent_id=issue.indent_id,
        ))
    if not lines:
        return None

    # A savepoint, because _build_consignment flushes the header before it packs:
    # without one, a rejected package list would leave that half-built PACKED row
    # behind to be committed with the pick.
    try:
        async with db.begin_nested():
            return await _build_consignment(db, s.ConsignmentWrite(
                issue_id=issue.id,
                # PROJECT, not the TRANSFER default: a transfer needs a destination
                # warehouse, and nothing upstream of here has chosen one.
                dispatch_type=DispatchType.PROJECT,
                dispatch_date=ist_today(),
                project_id=issue.project_id,
                packages=[s.ConsignmentPackageWrite(items=lines)],
            ), user)
    except AppException as exc:
        logger.warning("auto-consignment for %s skipped: %s", picking.pick_no, exc)
        return None


async def complete_picking(db: AsyncSession, picking_id: int, user) -> m.Picking:
    picking = await get_picking(db, picking_id)
    _guard(picking.status, {PickingStatus.IN_PROGRESS.value, PickingStatus.RELEASED.value},
           "complete", "material fulfilment")
    if picking.picked_lines == 0:
        raise ValidationError("Nothing has been picked yet")

    picking.status = (PickingStatus.COMPLETED if picking.picked_lines >= picking.total_lines
                      else PickingStatus.PICKED).value
    picking.completed_at = utcnow()

    consignment = await _raise_consignment_for_picking(db, picking, user)

    await write_audit(db, entity="out_picking", entity_id=picking.id, entity_no=picking.pick_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": PickingStatus.IN_PROGRESS.value},
                      after={"status": picking.status,
                             "picked_lines": picking.picked_lines,
                             "total_lines": picking.total_lines,
                             "consignment_no": consignment.dispatch_no if consignment else None})
    await db.commit()
    return await get_picking(db, picking_id)


# ---------------------------------------------------------------------------
# Material issues
# ---------------------------------------------------------------------------

def _issue_totals(issue: m.MaterialIssue) -> None:
    lines = issue.items
    issue.total_items = len(lines)
    issue.total_qty = sum((_d(l.issued_qty) for l in lines), ZERO)
    issue.total_value = sum((_d(l.amount) for l in lines), ZERO)


def _issue_serial_marker(issue_id: int) -> str:
    return f"Reserved for issue {issue_id}"


def _issue_line_serial_marker(issue_id: int, line_id: int | None) -> str:
    """The reservation stamp for ONE line of an issue.

    A held unit used to be stamped `Reserved for issue 72` — per DOCUMENT. An issue
    carrying the same item on two lines is the normal shape of a consolidated
    fulfilment (two batches of the same monitor), and with one stamp for the pair
    there was no way to say which line held which unit. Everything downstream then
    read the whole item's units against a single line: the screen showed BOTH lines
    every unit the issue held (the "serials are displaying overall, not by batch"
    report), `_mark_serials` compared one line's quantity against both lines'
    reservations, and `set_issue_serials` restated line A's units onto line B, where
    the batch check refused them with "is not in the selected batch". One line, one
    stamp, and every reader below keys on it.
    """
    if not line_id:
        return _issue_serial_marker(issue_id)
    return f"{_issue_serial_marker(issue_id)} line {line_id}"


def _issue_reservation_clause(issue_id: int):
    """Matches every reservation stamp this issue may carry — its own and its lines'.

    The separator is part of the pattern on purpose: `LIKE 'Reserved for issue 7%'`
    would also match issue 71's rows. Rows still carrying the old document-level
    stamp are matched too, so an issue drafted before this change is still readable.
    """
    base = _issue_serial_marker(issue_id)
    return or_(m.SerialNumber.remarks == base,
               m.SerialNumber.remarks.like(f"{base} line %"))


_ISSUE_MARKER_RE = re.compile(r"^Reserved for issue (\d+)")


async def _other_issue_claim_hint(db: AsyncSession, remarks: str,
                                  this_creator_id: int | None) -> str:
    """What to say about the issue that already holds this unit (SCM_0083).

    A storekeeper's own earlier create that only partly went through — a draft he
    never opened again — reserved the unit and left it holding nothing he could
    see; the generic "reserved by another issue" then sent him hunting for a
    document that, to him, did not exist. Naming it and saying it is his own draft
    is the one case the hint is specific about; any other holder stays generic —
    a stranger's in-flight issue is not this storekeeper's to open or cancel.
    """
    match = _ISSUE_MARKER_RE.match(remarks)
    if not match:
        return "open Issues to find which one"
    other = await db.get(m.MaterialIssue, int(match.group(1)))
    if other is None:
        return "open Issues to find which one"
    if (other.status == IssueStatus.DRAFT.value and this_creator_id is not None
            and other.created_by_id == this_creator_id):
        return (f"it is held by your own draft {other.issue_no}. Open it, "
                f"release or complete that line, then come back to this one")
    return f"it is held by {other.issue_no}"


async def _project_name(db: AsyncSession, project_id: int | None) -> str | None:
    """The project's display name, snapshotted beside its id (rule 10)."""
    from app.shared.models.master import Project
    project = await db.get(Project, project_id) if project_id else None
    return project.name if project else None


async def _consignment_project(
    db: AsyncSession, issue: m.MaterialIssue | None, project_id: int | None = None,
) -> tuple[int | None, str | None]:
    """The project a consignment is filed under: the one named on it, else the issue's,
    else the issue's indent's — which is where the ISSUE number itself takes it from.

    An issue raised off an indent carries no project of its own, so reading only the
    issue stamped `BHS/NA/...` on a consignment whose issue reads `BHS/104/...`, left
    the consignment's own project blank, and every shipment raised from it (its TR and
    its dispatch number) inherited the blank.
    """
    from app.modules.indents.models import Indent

    project_id = project_id or getattr(issue, "project_id", None)
    if project_id:
        return project_id, await _project_name(db, project_id)
    if issue is not None and issue.indent_id:
        indent = await db.get(Indent, issue.indent_id)
        if indent is not None and indent.project_id:
            return indent.project_id, (indent.project_name
                                       or await _project_name(db, indent.project_id))
    return None, None


async def _consignment_no(db: AsyncSession, project_name: str | None = None) -> str:
    """A consignment's number, from its own CONSIGNMENT series (`.../CON0001`)."""
    return await next_number(db, WarehouseDocType.CONSIGNMENT.value, project=project_name)


async def _issue_snapshot_values(
    db: AsyncSession,
    *,
    department_id: int | None,
    project_id: int | None,
    vehicle_id: int | None,
    issued_to_id: int | None,
    vehicle_number: str | None = None,
) -> dict[str, str | None]:
    from app.platform.hcm.models import HcmDepartment, HcmEmployee
    from app.shared.models.master import Project

    department = await db.get(HcmDepartment, department_id) if department_id else None
    project = await db.get(Project, project_id) if project_id else None
    employee = await db.get(HcmEmployee, issued_to_id) if issued_to_id else None
    vehicles = await vehicle_options(db) if vehicle_id else []
    vehicle = next((row for row in vehicles if row["id"] == vehicle_id), None)
    return {
        "department_name": department.name if department else None,
        "project_name": project.name if project else None,
        # A registered vehicle names itself; otherwise keep what was typed.
        "vehicle_number": vehicle["name"] if vehicle else (vehicle_number or None),
        "issued_to_name": employee.full_name if employee else None,
    }


#: How many unit ids travel in one `IN (...)`. MySQL parses a far longer list, but the
#: statement grows with every element and `max_allowed_packet` is a real ceiling, so a
#: 10,000-unit document is written as ten statements rather than one enormous one.
UNIT_WRITE_CHUNK = 1_000


def _in_chunks(values, size: int = UNIT_WRITE_CHUNK):
    """The ids of one document, in packets a single statement can carry."""
    values = list(values)
    for start in range(0, len(values), size):
        yield values[start:start + size]


async def _set_unit_fields(db: AsyncSession, ids, **values) -> None:
    """Write the same columns onto many units in one statement per chunk.

    THE reason a 10,000-serial document is affordable (2026-09-09). Every one of these
    paths used to assign to `row.remarks` / `row.status` inside a Python loop over
    loaded ORM rows, and SQLAlchemy turns that into one UPDATE per unit at flush —
    10,000 round trips inside one transaction, holding row locks and the connection
    for the whole of it. That is the timeout `limits.py` was capping around rather
    than fixing.

    `synchronize_session="fetch"` is deliberate and is NOT free: it costs one extra
    SELECT of the matched primary keys per statement. It buys correctness that a bulk
    UPDATE otherwise silently loses — SQLAlchemy does not, by default, overwrite
    already-loaded attributes of an object it hands back from the identity map, so a
    row this statement changed would keep reading with its OLD `remarks` for the rest
    of the transaction. `_reserve_issue_serials` decides "is this unit already claimed"
    off exactly that attribute, one call after `_clear_issue_serial_reservations`
    releases it, and would have refused units it had just freed itself.
    """
    for chunk in _in_chunks(ids):
        if not chunk:
            continue
        await db.execute(
            update(m.SerialNumber)
            .where(m.SerialNumber.id.in_(chunk))
            .values(**values)
            .execution_options(synchronize_session="fetch")
        )


async def _clear_issue_serial_reservations(
    db: AsyncSession,
    issue_id: int,
    *,
    line_ids: set[int] | None = None,
) -> None:
    """Release this issue's held units — all of them, or only the named lines'.

    `line_ids` is what lets `set_issue_serials` re-cut ONE line without dropping the
    reservations the storekeeper already made on the others; clearing the document
    wholesale and re-reserving everything is what used to shuffle units between lines
    of the same item.

    One UPDATE for the whole document, whatever it holds. The rows are never loaded:
    releasing a hold needs no per-unit decision, so there is nothing to read first.
    """
    stmt = (
        update(m.SerialNumber)
        .where(
            _issue_reservation_clause(issue_id),
            m.SerialNumber.status.in_(
                (SerialStatus.AVAILABLE.value, SerialStatus.ISSUED.value)
            ),
        )
        .values(remarks=None)
        .execution_options(synchronize_session="fetch")
    )
    if line_ids is not None:
        stmt = stmt.where(m.SerialNumber.remarks.in_(
            [_issue_line_serial_marker(issue_id, line_id) for line_id in line_ids]
        ))
    # The boxes it holds go back on the shelf with them (2026-10-26).
    await box_codes.release_issue(db, issue_id, line_ids)
    await db.execute(stmt)


UNIT_MODE_SERIAL = "SERIAL"
UNIT_MODE_IMEI = "IMEI"
UNIT_MODE_CODE = "CODE"

# What one unit is called in a message, per mode.
_UNIT_NOUN = {
    UNIT_MODE_SERIAL: "serial numbers",
    UNIT_MODE_IMEI: "IMEI numbers",
    UNIT_MODE_CODE: "unit codes",
}


def _unit_mode(item) -> str:
    """Which identifier names one unit of this item: serial → IMEI → code.

    The fallback ladder the business asked for. A serial is the primary identity
    whenever the item carries one; an item that has only IMEIs is named by those;
    everything else is named by the asset / consumable code stamped at putaway.
    The three are not alternatives on the same unit — they are the same row in
    `whs_serial_numbers` read through whichever column that item actually fills,
    so validating on one always yields the other two from the matched row.
    """
    if bool(getattr(item, "is_serial_tracked", False)):
        return UNIT_MODE_SERIAL
    if bool(getattr(item, "is_imei_tracked", False)):
        return UNIT_MODE_IMEI
    return UNIT_MODE_CODE


def _tracking_type(item, *, has_units: bool = True) -> str:
    """Which KIND of identifier a storekeeper is being asked to read, for the badge.

    `_unit_mode` above answers a different question — which column the matcher
    validates against — and folds an asset tag and a consumable lot code into one
    CODE. On the shelf they are two different labels in two different places, so the
    screen needs them apart; the fold stays where it belongs, in matching.

    `has_units` is per LINE, not per item: an item may be asset-coded in the master
    and still have nothing coded at THIS point, and a badge promising an asset tag
    over an empty picker is worse than no badge.
    """
    if bool(getattr(item, "is_serial_tracked", False)):
        return TrackingType.SERIAL.value
    if bool(getattr(item, "is_imei_tracked", False)):
        return TrackingType.IMEI.value
    if not has_units:
        return TrackingType.NONE.value
    if bool(getattr(item, "is_asset", False)):
        return TrackingType.ASSET.value
    return TrackingType.CONSUMABLE.value


def tracking_types() -> list[dict]:
    """The badge catalogue, served so no screen writes these words itself."""
    return [{"code": code, **meta} for code, meta in TRACKING_META.items()]


def _unit_keys(row, mode: str) -> list[str]:
    """Every value that may be typed or scanned to mean this unit, in this mode.

    A code-mode row answers to its code AND to its serial_number, because for an
    unserialised unit `_place_unit_codes` writes the same string into both.
    """
    if mode == UNIT_MODE_SERIAL:
        return [row.serial_number] if row.serial_number else []
    if mode == UNIT_MODE_IMEI:
        return [row.imei] if row.imei else []
    values = [row.asset_code, row.consumable_code, row.serial_number]
    seen: list[str] = []
    for value in values:
        if value and value not in seen:
            seen.append(value)
    return seen


def _outbound_seed_units(rows, *, item, item_id: int,
                         batch_id: int | None) -> list[str]:
    """Which identifiers an auto-raised outward inspection opens with.

    One string per unit this issue line sent out, named the way the issue
    picker named it (`_unit_mode` currency) — the same value the issue hands
    back as `unit_keys`, so the QC modal opens with everything accepted and
    the save validates against the same set.

    Every kind is seeded, not just serial-tracked lines: seeding only those
    left every IMEI / asset / consumable line stored with no units, which the
    picker reads as "every unit rejected" (an untouched `None` would mean no
    decision, but a stored empty list means rejected).

    A row carrying none of its mode's identifiers still contributes its first
    recorded one — an IMEI-tracked row with no IMEI recorded still has its
    code in `serial_number`, and an inspection seeded with nothing for it
    reads as rejected by default. Pure, so it is pinned without a database.
    """
    mode = _unit_mode(item)
    seen: set[int] = set()
    names: list[str] = []
    for row in rows:
        row_id = getattr(row, "id", None)
        if row_id in seen:
            continue
        if getattr(row, "item_id", None) != item_id:
            continue
        if batch_id and getattr(row, "batch_id", None) != batch_id:
            continue
        seen.add(row_id)
        marker = next(iter(_unit_keys(row, mode)), None)
        if marker is None:
            marker = next((value for value in (
                getattr(row, "serial_number", None),
                getattr(row, "imei", None),
                getattr(row, "asset_code", None),
                getattr(row, "consumable_code", None),
            ) if value), None)
        if marker and marker not in names:
            names.append(marker)
    return names


async def _lines_without_source(db: AsyncSession, issue: m.MaterialIssue) -> set[int]:
    """Lines that have not yet named where their goods come from.

    A batch is required only for an item whose stock here is batched, a location only
    where this point keeps locations — the same test `_assert_sources_picked` applies
    at submit.
    """
    from app.modules.inventory.models import Stock

    lines = [line for line in issue.items if line.id]
    if not lines:
        return set()
    wh = await db.get(Warehouse, issue.warehouse_id)
    bin_managed = bool(getattr(wh, "is_bin_managed", False))
    item_ids = {line.item_id for line in lines}
    batched = set((await db.execute(
        select(Stock.item_id).where(Stock.warehouse_id == issue.warehouse_id,
                                    Stock.item_id.in_(item_ids),
                                    Stock.batch_id != m.NO_BATCH,
                                    Stock.total_qty > ZERO).distinct()
    )).scalars().all())
    return {
        line.id for line in lines
        if (line.item_id in batched and not line.batch_id)
        or (bin_managed and not line.bin_id)
    }


async def _reserve_issue_serials(
    db: AsyncSession,
    issue: m.MaterialIssue,
    inputs: list[s.IssueItemWrite],
) -> None:
    # Every line carries its own stamp, so a unit held for line 3 is never read as
    # line 5's. See _issue_line_serial_marker.
    markers = {line.id: _issue_line_serial_marker(issue.id, line.id)
               for line in issue.items}
    line_no_by_marker = {markers[line.id]: line.line_no for line in issue.items}
    unpicked = await _lines_without_source(db, issue)
    for line, data in zip(issue.items, inputs, strict=True):
        marker = markers[line.id]
        item = await _item_snapshot(db, line.item_id)
        serials = [value.strip() for value in (data.serial_numbers or []) if value.strip()]
        # A code-tracked line that has not picked its batch / location yet holds NO
        # codes (2026-10-13). Auto-filling it took the oldest codes in the whole
        # warehouse — every code of the earliest batch — and the issue that then
        # picked that batch FEFO found none left to name (WHI0076 vs WHI0077). Codes
        # are taken from the line's own source once it has one.
        if (line.id in unpicked and issue.direction == IssueDirection.OUT.value
                and _unit_mode(item) == UNIT_MODE_CODE):
            setattr(line, "serial_numbers", [])
            setattr(line, "unit_keys", [])
            setattr(line, "unit_mode", UNIT_MODE_CODE)
            continue
        if len(serials) != len(set(serials)):
            raise ValidationError(f"{item.code}: serial numbers must be unique")
        mode = _unit_mode(item)
        if (mode == UNIT_MODE_CODE and issue.direction == IssueDirection.OUT.value
                and await _issue_container_packages(db, line.item_id)
                and await _unit_codes_required(db, item)):
            # Issued in a container (2026-10-26): the line names BOXES — one code per
            # box. The codes it names (scanned, picked, an old per-unit label, or the
            # screen's echo) are held first; the rest are chosen by `plan_boxes`.
            boxed = await box_codes.hold_line(
                db, issue, line, named=serials,
                claimed_prefixes=_CLAIMED_REMARK_PREFIXES)
            if boxed is not None:
                setattr(line, "serial_numbers", boxed["codes"])
                setattr(line, "unit_keys", boxed["codes"])
                setattr(line, "unit_mode", mode)
                continue
            # A lot with no boxes yet (old stock the conversion has not reached):
            # the per-unit path below, its codes re-derived on every save.
            serials = []
        noun = _UNIT_NOUN[mode]
        issued = _d(line.issued_qty)
        if mode == UNIT_MODE_SERIAL and issued != issued.to_integral_value():
            raise ValidationError(
                f"{item.code}: a serialized quantity must be a whole number"
            )
        auto_codes = (issue.direction == IssueDirection.OUT.value
                      and mode == UNIT_MODE_CODE)
        if not serials:
            # Nothing named. A serial or IMEI line stays empty — which handset leaves
            # is read off the label at the shelf. An asset- or consumable-coded line is
            # filled from its own batch and bay, oldest code first (`_auto_fill_codes`).
            setattr(line, "serial_numbers", [])
            setattr(line, "unit_keys", [])
            setattr(line, "unit_mode", mode)
            if auto_codes:
                await _auto_fill_codes(db, issue, line, marker=marker, mode=mode)
            continue
        if issued != issued.to_integral_value():
            raise ValidationError(
                f"{item.code}: a quantity named by {noun} must be a whole number"
            )
        # A draft may hold fewer serials than units, and usually holds none.
        #
        # These drafts are created for the storekeeper by
        # create_fulfilment_drafts_for_allocation, which runs when INVENTORY approves
        # an allocation. Inventory approves quantities; it has no idea which physical
        # units will be picked, and no screen on which to say. Demanding the full set
        # here made "Approve and reserve" fail with "select 5 serial numbers for the
        # issued quantity" — an error about a warehouse detail, raised on an inventory
        # screen, against a document the approver could not edit.
        #
        # The full set is required at post_issue, which is where stock actually moves
        # and where the storekeeper has the goods in hand. Same shape as the gate
        # entry / GRN split on inbound.
        if len(serials) > int(issued):
            raise ValidationError(
                f"{item.code}: {len(serials)} {noun} for {int(issued)} units"
            )
        expected_status = (
            SerialStatus.AVAILABLE.value
            if issue.direction == IssueDirection.OUT.value
            else SerialStatus.ISSUED.value
        )
        stmt = select(m.SerialNumber).where(
            m.SerialNumber.item_id == line.item_id,
            m.SerialNumber.warehouse_id == issue.warehouse_id,
            m.SerialNumber.status == expected_status,
            m.SerialNumber.is_active.is_(True),
        )
        # The one place the ladder is applied to the lookup itself: the same row is
        # found by whichever column this item names its units with.
        #
        # Read in chunks of the NAMES, not in one clause: a line may now carry 10,000
        # of them (`limits.MAX_SERIALS_PER_LINE`), and a single `IN` of that length is
        # a statement MySQL re-plans per element and can refuse outright on
        # `max_allowed_packet`. Each chunk still takes `FOR UPDATE`, so the whole set
        # is locked by the time the loop below decides anything about it.
        def _named(values):
            if mode == UNIT_MODE_SERIAL:
                return m.SerialNumber.serial_number.in_(values)
            if mode == UNIT_MODE_IMEI:
                return m.SerialNumber.imei.in_(values)
            return or_(
                m.SerialNumber.asset_code.in_(values),
                m.SerialNumber.consumable_code.in_(values),
                m.SerialNumber.serial_number.in_(values))

        rows = []
        for names in _in_chunks(serials):
            rows.extend((await db.execute(
                stmt.where(_named(names)).with_for_update()
            )).scalars().all())

        by_key: dict[str, m.SerialNumber] = {}
        for row in rows:
            for key in _unit_keys(row, mode):
                by_key.setdefault(key, row)
        chosen = [by_key.get(value) for value in serials]
        if any(row is None for row in chosen) or \
                len({row.id for row in chosen if row}) != len(serials):
            raise ValidationError(
                f"{item.code}: one or more selected units are unavailable"
            )
        for value, row in zip(serials, chosen, strict=True):
            if line.bin_id and row.bin_id != line.bin_id:
                raise ValidationError(f"{value} is not in the selected source bin")
            if line.batch_id and row.batch_id != line.batch_id:
                raise ValidationError(f"{value} is not in the selected batch")
            if row.remarks and row.remarks.startswith(PROJECT_HOLD_UNIT_PREFIX) \
                    and not row.remarks.startswith(
                        f"{PROJECT_HOLD_UNIT_PREFIX}{issue.project_id or 0} "):
                raise ValidationError(
                    f"{value} is held for another project. Release that hold on "
                    "Stock Segregation > Project Lots first.")
            if row.remarks and row.remarks.startswith("Reserved for issue ") \
                    and row.remarks != marker:
                # Naming WHICH line already holds it when it is this document own
                # line. "reserved by another issue" was the message a storekeeper
                # got for a unit he had picked himself two rows up, and it sent
                # him looking for a document that does not exist.
                other = line_no_by_marker.get(row.remarks)
                if other:
                    raise ValidationError(
                        f"{value} is already named on line {other} of this issue")
                raise ValidationError(
                    f"{value} is reserved by another issue — "
                    f"{await _other_issue_claim_hint(db, row.remarks, issue.created_by_id)}")
        # Stamped as a SET, once every unit on the line has passed its checks. The
        # per-row assignment this replaces was one UPDATE per serial at flush; it also
        # means nothing is written until the whole line validates, which is the
        # behaviour the ValidationErrors above already relied on.
        await _set_unit_fields(db, [row.id for row in chosen], remarks=marker)
        # The document always keeps the canonical serial — in code mode that IS the
        # code — while `unit_keys` echoes back what the storekeeper actually validated.
        setattr(line, "serial_numbers", [row.serial_number for row in chosen])
        setattr(line, "unit_keys", serials)
        setattr(line, "unit_mode", mode)
        if auto_codes and len(serials) < int(issued):
            await _auto_fill_codes(db, issue, line, marker=marker, mode=mode)


async def _issue_container_packages(db: AsyncSession, item_id: int) -> set[int]:
    """The container types (`mst_packaging` ids) an item is ISSUED in — empty when it
    is issued loose (2026-10-24)."""
    from app.shared.masters import packs as master_packs
    mapped = (await master_packs.usage_map(db, [item_id])).get(int(item_id), {})
    return {int(pid) for pid, usages in mapped.items() if pid and "ISSUE" in usages}


async def _container_codes(db: AsyncSession, rows, mode: str,
                           packages: set[int]) -> list[str]:
    """The identifiers a line's units are named by when the item is issued in a
    container (2026-10-24): the code of the ISSUE container each unit sits in — one
    box, one code — and a unit's own code only where it sits in no such container
    (loose stock). Lots coded per unit before the item was mapped keep their unit
    rows, which still move at posting; the document simply names the box."""
    from app.shared.models.master import ItemPackaging
    hus: dict[int, m.HandlingUnit] = {}
    frontier = {r.handling_unit_id for r in rows if r.handling_unit_id}
    while frontier:
        found = (await db.execute(select(m.HandlingUnit).where(
            m.HandlingUnit.id.in_(frontier)))).scalars().all()
        for hu in found:
            hus[hu.id] = hu
        frontier = {hu.parent_id for hu in found if hu.parent_id and hu.parent_id not in hus}
    rungs = {hu.item_packaging_id for hu in hus.values() if hu.item_packaging_id}
    package_of = dict((await db.execute(
        select(ItemPackaging.id, ItemPackaging.package_id)
        .where(ItemPackaging.id.in_(rungs)))).all()) if rungs else {}
    codes: list[str] = []
    seen: set[str] = set()
    for row in rows:
        hu = hus.get(row.handling_unit_id)
        while hu is not None and package_of.get(hu.item_packaging_id) not in packages:
            hu = hus.get(hu.parent_id)
        if hu is not None:
            key = hu.hu_code
        else:
            keys = _unit_keys(row, mode)
            key = keys[0] if keys else row.serial_number
        if key and key not in seen:
            seen.add(key)
            codes.append(key)
    return codes


async def _auto_fill_codes(
    db: AsyncSession, issue: m.MaterialIssue, line, *, marker: str, mode: str,
) -> None:
    """Top an asset- or consumable-coded line up to its issued quantity (2026-10-07).

    Those codes are GENERATED by the system at putaway — nobody reads one off a maker's
    label — so making a storekeeper tick fifteen of them by hand was clerical work with
    no judgement in it. The codes he did name stand (they are already stamped with
    `marker`, and `_claim_units` counts its own first); the rest are taken FIFO from
    the line's OWN batch and bay, so a split pick draws each bay's codes for that bay.

    Runs on every save — create, update and the approved-issue serials endpoint — so
    the set is held on the units themselves and survives submit and approval. Serial
    and IMEI lines never come here (`_unit_mode`). Best effort, like `_claim_units`: a
    bay holding fewer codes than the quantity fills what it can, and
    `_assert_units_obtainable` says so at submit.
    """
    wanted = int(_d(line.issued_qty))
    if wanted <= 0:
        return
    # A line stated in packs takes THOSE packs first (2026-10-08) — see
    # `packing.reserve_named_packs`. Whatever they do not cover is topped up below.
    await wh_packing.reserve_named_packs(
        db, warehouse_id=issue.warehouse_id, line=line, marker=marker,
        claimed_prefixes=_CLAIMED_REMARK_PREFIXES)
    batch_id = line.batch_id if line.batch_id and line.batch_id != m.NO_BATCH else None
    bin_id = line.bin_id if line.bin_id and line.bin_id != m.NO_BIN else None
    # Everything this line holds, WHEREVER the unit row says it stands (2026-10-24).
    # A named pack's units are taken whole even when some of their rows carry no
    # location; `_claim_units` counts only its own batch and bay, so it read those as
    # missing and topped the line up again — 80 codes held for a line of 50.
    own = (await db.execute(select(m.SerialNumber).where(
        m.SerialNumber.item_id == line.item_id,
        m.SerialNumber.warehouse_id == issue.warehouse_id,
        m.SerialNumber.status == SerialStatus.AVAILABLE.value,
        m.SerialNumber.is_active.is_(True),
        m.SerialNumber.remarks == marker).with_for_update())).scalars().all()
    in_scope = [row for row in own
                if (not batch_id or row.batch_id == batch_id)
                and (not bin_id or row.bin_id == bin_id)]
    outside = len(own) - len(in_scope)
    if len(own) > wanted:
        # Keep the container holding most of them, so the pick stays in as few
        # packs as it can; the rest go back on the shelf.
        weight: dict = {}
        for row in own:
            weight[row.handling_unit_id] = weight.get(row.handling_unit_id, 0) + 1
        ordered = sorted(own, key=lambda r: (r.handling_unit_id is None,
                                             -weight[r.handling_unit_id],
                                             r.handling_unit_id or 0, r.id))
        await _set_unit_fields(db, [row.id for row in ordered[wanted:]], remarks=None)
        rows = ordered[:wanted]
    else:
        rows = [row for row in own if row not in in_scope] + await _claim_units(
            db,
            item_id=line.item_id,
            warehouse_id=issue.warehouse_id,
            qty=wanted - outside,
            marker=marker,
            batch_id=batch_id,
            bin_id=bin_id,
        )
    setattr(line, "serial_numbers", [row.serial_number for row in rows])
    setattr(line, "unit_keys", [
        keys[0] for keys in (_unit_keys(row, mode) for row in rows) if keys])


async def _issue_units_by_line(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> dict[int, list[m.SerialNumber]]:
    """Which physical units each LINE of this issue holds, keyed on line id.

    Three stamps, one question. The reservation stamp names its own line, so those
    rows land where they belong with nothing to work out. The shipped and returned
    stamps stay per DOCUMENT — a unit in flight is read back by that exact string at
    the far end (`_land_units`, `_issued_serial_index`), and re-cutting it would
    strand every consignment already on the road — so those, and any row still
    carrying the pre-2026-09 document-level reservation stamp, are attributed here:
    spread over the lines carrying that item, in line order, each taking at most its
    own issued quantity. That is what a posted issue's units actually are, and it
    replaces the per-item lump that used to be shown against every line at once.
    """
    item_ids = {line.item_id for line in issue.items}
    if not item_ids:
        return {}
    rows = (await db.execute(
        select(m.SerialNumber).where(
            # Narrowed to this document's items first. The stamp is what identifies
            # the row, but `remarks` is a 500-wide free-text column with only a prefix
            # index on it — matching on it alone read all 773k units, which is where
            # four of the twenty-six seconds went.
            m.SerialNumber.item_id.in_(item_ids),
            or_(
                _issue_reservation_clause(issue.id),
                m.SerialNumber.remarks.in_((
                    f"Issued by issue {issue.id}",
                    f"Returned by issue {issue.id}",
                )),
            )
        ).order_by(m.SerialNumber.id)
    )).scalars().all()

    by_line: dict[int, list[m.SerialNumber]] = {line.id: [] for line in issue.items}
    unattributed: dict[int, list[m.SerialNumber]] = {}
    line_marker = {
        _issue_line_serial_marker(issue.id, line.id): line.id for line in issue.items
    }
    for row in rows:
        line_id = line_marker.get(row.remarks or "")
        if line_id is not None:
            by_line[line_id].append(row)
        else:
            unattributed.setdefault(row.item_id, []).append(row)

    _attribute_units_to_lines(issue.items, unattributed, by_line)
    return by_line


def _attribute_units_to_lines(lines, pool_by_item: dict, by_line: dict) -> None:
    """Hand document-stamped units to the lines that sent them, tightest match first.

    A posted unit keeps its `batch_id` and `bin_id`; only its stamp goes per document.
    So the same batch drawn from two bays on two lines — the normal shape of a split
    pick — is told apart by WHERE each unit was standing: an exact (batch, bin) match
    first, then the batch alone, then anything of the item. Handing them out in plain
    line order gave the first line every unit of the batch and left the second line
    with the other bay's codes, which outward QC and the consignment then validated
    against the wrong line. Pure: mutates `pool_by_item` and `by_line` only.
    """
    def _named(value, sentinel):
        return value if value and value != sentinel else None

    def _take(line, matches) -> None:
        pool = pool_by_item.get(line.item_id)
        if not pool:
            return
        room = int(_d(line.issued_qty)) - len(by_line[line.id])
        if room <= 0:
            return
        taken = [row for row in pool if matches(row)][:room]
        if not taken:
            return
        ids = {id(row) for row in taken}
        by_line[line.id].extend(taken)
        pool[:] = [row for row in pool if id(row) not in ids]

    for line in lines:
        batch, bay = _named(line.batch_id, m.NO_BATCH), _named(line.bin_id, m.NO_BIN)
        if batch and bay:
            _take(line, lambda row, b=batch, n=bay: row.batch_id == b and row.bin_id == n)
    for line in lines:
        batch = _named(line.batch_id, m.NO_BATCH)
        if batch:
            _take(line, lambda row, b=batch: row.batch_id == b)
    for line in lines:
        _take(line, lambda row: True)


def _unit_claim_free_clause(marker: str | None):
    """A unit nothing else is holding — or one this very line already holds.

    `marker` None asks only the first half: a document that holds no units of its
    own (a stock movement) may name only what nobody is holding.

    `_CLAIMED_REMARK_PREFIXES` is the same set `_claim_units` skips on; stating it
    once here keeps "what may I still pick" and "what may I still auto-claim" the
    same question.
    """
    unclaimed = [m.SerialNumber.remarks.is_(None)]
    unclaimed.append(and_(*[
        ~m.SerialNumber.remarks.like(f"{prefix}%")
        for prefix in _CLAIMED_REMARK_PREFIXES
    ]))
    if marker is None:
        return or_(*unclaimed)
    return or_(m.SerialNumber.remarks == marker, *unclaimed)


#: Past this many units on one line the availability probe stops being cheap, and a
#: line that large is test data or a bulk transfer, not something a warning helps.
_SUPPLY_PROBE_CEILING = 10_000


async def _issue_unit_supply(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> dict[int, int]:
    """How many units each line could still be given, from the source IT names —
    counted only as far as that line needs.

    The whole point of the count. `post_issue` refuses a serial-tracked line that
    cannot name one unit per issued unit, and by then the batch and bin are frozen —
    approval locks them — so a line pointed at a batch holding nothing was a document
    that could never be posted and could never be corrected either. Read here, the
    same answer is on the screen, at submit and in the approver's inbox, while the
    batch is still editable.

    STOPS AT `issued_qty + 1`. `whs_serial_numbers` holds one row per physical unit
    and this database already carries 465,354 available units of a single item at one
    warehouse, so a plain COUNT of the shelf took ten seconds and would only grow.
    Nothing here needs the shelf's total: the question is "does this line have
    enough", and one more than enough answers it. The `LIMIT` inside the subquery is
    what makes the index scan stop — the answer costs the same whether the bin holds
    twenty units or half a million.

    So a returned number equal to `issued_qty + 1` means "at least that many"; every
    smaller number is exact.

    WIDENED 2026-09-03 to every tracked mode, not just serials. It was serial-only
    because only `post_issue` read it and only serial lines are held to one named unit
    per issued unit — for anyone else it was "two thirds of the work on a typical issue
    and nobody's answer". It is somebody's answer now: the issue screen states how many
    codes a pick can actually name beside the quantity it takes, because those are two
    different numbers off two different tables and a storekeeper reading one as the
    other is the confusion this whole change exists to end. The probe is bounded, so
    widening it costs about a millisecond a line — measured against the 465k-unit item,
    where the same count unbounded takes 816 ms.
    """
    if issue.is_stock_posted:
        # Nothing left to answer. The units are off the shelf, so every line would
        # report what is still lying beside them — a number the screen would then
        # draw as a shortfall against a document that has already gone out.
        return {}
    outward = issue.direction == IssueDirection.OUT.value
    expected_status = (
        SerialStatus.AVAILABLE.value if outward else SerialStatus.ISSUED.value
    )
    # Every item on the document that HAS identified units at this point, not just the
    # serial-tracked ones. `post_issue` still only holds serial lines to one named unit
    # per issued unit — an IMEI- or code-named item tops up from whatever the shelf has
    # (see `_claim_units`) — but the screen now shows the count for all of them, so it
    # has to be answered for all of them. `== 1` rather than `.is_(True)` for the same
    # reason as the probe below.
    coded_items = set((await db.execute(
        select(m.SerialNumber.item_id)
        .where(m.SerialNumber.item_id.in_({line.item_id for line in issue.items}),
               m.SerialNumber.warehouse_id == issue.warehouse_id,
               m.SerialNumber.is_active == 1)
        .distinct()
    )).scalars().all()) if issue.items else set()

    supply: dict[int, int] = {}
    for line in issue.items:
        if line.item_id not in coded_items:
            continue
        need = max(int(_d(line.issued_qty)), 0)
        if need > _SUPPLY_PROBE_CEILING:
            # No answer rather than a slow one or a wrong one. Counting to a hundred
            # thousand is the one case where this probe stops being cheap, and a line
            # that big is not one a screen can usefully warn about anyway — leaving it
            # unanswered means the screen says nothing and submit does not block, and
            # `post_issue` still refuses an incomplete set at the shelf.
            continue
        cap = need + 1
        probe = (
            select(literal(1))
            .select_from(m.SerialNumber)
            .where(m.SerialNumber.item_id == line.item_id,
                   m.SerialNumber.warehouse_id == issue.warehouse_id,
                   m.SerialNumber.status == expected_status,
                   # `== 1`, not `.is_(True)`: SQLAlchemy renders the latter as
                   # `is_active IS true`, which MySQL will not resolve through an
                   # index, and the scan falls back to reading rows.
                   m.SerialNumber.is_active == 1)
        )
        # NO_BATCH / NO_BIN mean "the line names none", exactly as `_claim_units` and
        # `move_stock_out` read them: no narrowing, not a lookup for id 0.
        if line.batch_id and line.batch_id != m.NO_BATCH:
            probe = probe.where(m.SerialNumber.batch_id == line.batch_id)
        if line.bin_id and line.bin_id != m.NO_BIN:
            probe = probe.where(m.SerialNumber.bin_id == line.bin_id)
        if outward:
            # Free, or already held by THIS line. A unit coming back is by definition
            # stamped with the claim it is being released from, so the test only
            # applies on the way out.
            probe = probe.where(_unit_claim_free_clause(
                _issue_line_serial_marker(issue.id, line.id)))
        supply[line.id] = int((await db.execute(
            select(func.count()).select_from(probe.limit(cap).subquery())
        )).scalar() or 0)
    return supply


async def issue_unit_supply(
    db: AsyncSession,
    *,
    warehouse_id: int,
    picks: list[s.UnitSupplyPick],
    issue_id: int | None = None,
    direction: str = IssueDirection.OUT.value,
    user=None,
) -> list[dict]:
    """How many identified units each (item, batch, location) could name, right now.

    The same question `_issue_unit_supply` answers per SAVED line, asked about a pick
    the storekeeper has just repointed and not saved. It matters because the two
    numbers on that row come off two different tables: `drawable_qty` is a quantity on
    `stk_balance`, and this is how many physical units at that spot carry an
    identifier the line could name. Stock put away before the item was coded has the
    first and not the second, so a pick can be perfectly sound on quantity and
    impossible to post — and until this endpoint existed the screen could only say so
    after a save, by which time the storekeeper had moved on.

    **Bounded exactly as the per-line probe is** (see `_issue_unit_supply`): the count
    stops at `need + 1`, so a returned figure equal to `need + 1` means "at least that
    many" and every smaller one is exact. `whs_serial_numbers` is one row per physical
    unit and holds 773k of them; an unbounded COUNT over a well-stocked item takes the
    better part of a second, and this is called while somebody is typing.

    Units this document is already holding count as available to it — they are stamped
    with its own line's marker, not somebody else's — which is why `issue_id` is taken.
    """
    ids = [pick for pick in picks if pick.item_id]
    if not warehouse_id or not ids:
        return []

    outward = direction == IssueDirection.OUT.value
    expected_status = (
        SerialStatus.AVAILABLE.value if outward else SerialStatus.ISSUED.value
    )
    scope = None
    if user is not None:
        scope = await scope_condition(
            db, user,
            warehouse_col=m.SerialNumber.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        )

    # Which of these items carry a per-unit identity at this point at all. One read for
    # the whole document, and the answer a screen needs before it draws a unit picker:
    # an item with no coded units has nothing to pick and is not short of anything.
    coded = set((await db.execute(
        select(m.SerialNumber.item_id)
        .where(m.SerialNumber.item_id.in_({pick.item_id for pick in ids}),
               m.SerialNumber.warehouse_id == warehouse_id,
               m.SerialNumber.is_active == 1)
        .distinct()
    )).scalars().all())

    out: list[dict] = []
    for pick in ids:
        need = max(int(_d(pick.need)), 0)
        row = {
            "item_id": pick.item_id,
            "batch_id": pick.batch_id or None,
            "bin_id": pick.bin_id or None,
            "need": need,
            "has_units": pick.item_id in coded,
            "available": None,
            "batch_available": None,
            "point_available": None,
        }
        if pick.item_id not in coded or need > _SUPPLY_PROBE_CEILING:
            # No answer rather than a slow one. A line asking for a hundred thousand
            # units is not one a screen can usefully warn about, and `post_issue` still
            # refuses an incomplete set at the shelf.
            out.append(row)
            continue

        def _base():
            return (
                select(literal(1))
                .select_from(m.SerialNumber)
                .where(m.SerialNumber.item_id == pick.item_id,
                       m.SerialNumber.warehouse_id == warehouse_id,
                       m.SerialNumber.status == expected_status,
                       # `== 1`, not `.is_(True)`: MySQL will not resolve `IS true` through
                       # the index and falls back to reading rows.
                       m.SerialNumber.is_active == 1)
            )

        def _claimed(stmt):
            if scope is not None:
                stmt = stmt.where(scope)
            if outward:
                stmt = stmt.where(_unit_claim_free_clause(
                    _issue_line_serial_marker(issue_id, pick.line_id)
                    # "" matches no stamp — a pick with no saved line of its own holds
                    # nothing yet, so only genuinely unclaimed units count for it.
                    if issue_id and pick.line_id else ""))
            return stmt

        async def _count(stmt) -> int:
            return int((await db.execute(
                select(func.count()).select_from(stmt.limit(need + 1).subquery())
            )).scalar() or 0)

        # NO_BATCH / NO_BIN mean "the pick names none" — no narrowing, not a lookup for
        # id 0. Same reading as `_claim_units` and `move_stock_out`.
        exact = _base()
        if pick.batch_id and pick.batch_id != m.NO_BATCH:
            exact = exact.where(m.SerialNumber.batch_id == pick.batch_id)
        if pick.bin_id and pick.bin_id != m.NO_BIN:
            exact = exact.where(m.SerialNumber.bin_id == pick.bin_id)
        row["available"] = await _count(_claimed(exact))
        # Fallback circles: same batch anywhere here, then the whole point. Both
        # bounded like the exact probe — three cheap index lookups per pick.
        if pick.batch_id and pick.batch_id != m.NO_BATCH:
            batch_only = _claimed(_base().where(
                m.SerialNumber.batch_id == pick.batch_id))
            row["batch_available"] = await _count(batch_only)
        if pick.batch_id or pick.bin_id:
            row["point_available"] = await _count(_claimed(_base()))
        else:
            row["point_available"] = row["available"]
        out.append(row)
    return out


async def serial_scope_counts(db: AsyncSession, *, warehouse_id: int,
                             item_id: int, batch_id: int | None = None,
                             bin_id: int | None = None,
                             issue_id: int | None = None,
                             issue_line_id: int | None = None,
                             user=None) -> dict:
    """How many codable units each widening circle holds: bay, batch, point.

    The three answers behind the code picker's scope switch — "This bay", "This
    batch anywhere here", "Whole point" — each bounded to 201 rows so a
    half-million-unit bay costs the same as an empty one.
    """
    from app.modules.warehouse.enums import IssueDirection  # local: rule 5 safe
    _ = IssueDirection
    cap = 201
    coded = await db.scalar(
        select(m.SerialNumber.id)
        .where(m.SerialNumber.item_id == item_id,
               m.SerialNumber.warehouse_id == warehouse_id,
               m.SerialNumber.is_active == 1).limit(1))
    if coded is None:
        return {"item_id": item_id, "exact": None, "batch": None,
                "point": None, "has_units": False}
    claim = _unit_claim_free_clause(
        _issue_line_serial_marker(issue_id, issue_line_id) if issue_id else None)

    async def _count(batch=None, bin=None) -> int:
        stmt = (select(literal(1)).select_from(m.SerialNumber)
                .where(m.SerialNumber.item_id == item_id,
                       m.SerialNumber.warehouse_id == warehouse_id,
                       m.SerialNumber.status == SerialStatus.AVAILABLE.value,
                       m.SerialNumber.is_active == 1, claim))
        if batch:
            stmt = stmt.where(m.SerialNumber.batch_id == batch)
        if bin:
            stmt = stmt.where(m.SerialNumber.bin_id == bin)
        if user is not None:
            stmt = stmt.where(await scope_condition(
                db, user, warehouse_col=m.SerialNumber.warehouse_id,
                warehouse_ids=await warehouse_ids_for_user(db, user)))
        return int((await db.execute(
            select(func.count()).select_from(stmt.limit(cap).subquery())
        )).scalar() or 0)

    exact = await _count(batch=batch_id or None, bin=bin_id or None)
    batch_n = await _count(batch=batch_id or None) if batch_id else exact
    point = await _count()
    return {"item_id": item_id, "exact": exact, "batch": batch_n,
            "point": point, "has_units": True}


async def _assert_units_obtainable(db: AsyncSession, issue: m.MaterialIssue) -> None:
    """Refuse to submit an issue that could never be posted.

    Every line whose item must leave with one identifier per unit
    (`_unit_codes_required`) — the same test `_mark_serials` holds `post_issue` to, so
    an issue that would be refused at posting is refused here, before approval.

    Every failing line is reported at once, naming the batch, so the storekeeper
    fixes the document in one pass instead of one approval cycle per line.
    """
    if issue.direction != IssueDirection.OUT.value:
        return
    supply = await _issue_unit_supply(db, issue)
    code_config = await codeformat.code_settings(db)
    short: list[str] = []
    for line in issue.items:
        wanted = _d(line.issued_qty)
        if wanted <= ZERO:
            continue
        item = await _item_snapshot(db, line.item_id)
        if not await _unit_codes_required(db, item, config=code_config):
            continue
        # Issued in boxes (2026-10-26): the line's boxes must cover it, in the
        # container the master names today. The unit rows inside are history.
        # Only asset / consumable-coded items are issued by the box; a serial or IMEI
        # line names the maker's numbers whatever it is packed in.
        problem = (await box_codes.check_line(db, issue, line)
                   if _unit_mode(item) == UNIT_MODE_CODE else None)
        if problem:
            short.append(problem)
            continue
        if await box_codes.has_boxes(db, issue.id, line.id):
            continue
        # A lot with no recorded units is issued by quantity (2026-10-23).
        if not await _lot_has_units(db, item_id=line.item_id,
                                    warehouse_id=issue.warehouse_id,
                                    batch_id=line.batch_id, bin_id=line.bin_id):
            continue
        # `_issue_unit_supply` already counts the units this line is holding — they
        # are `available` rows stamped with its own marker — so adding the captured
        # set on top would count the storekeeper's own picks twice.
        available = supply.get(line.id, 0)
        if available >= int(wanted):
            continue
        where = (f"batch {line.batch_no}" if line.batch_no else "the unbatched stock")
        if line.bin_code:
            where += f" in bin {line.bin_code}"
        noun = _UNIT_NOUN[_unit_mode(item)]
        short.append(
            f"line {line.line_no} ({item.code}) needs {int(wanted)} {noun} "
            f"but {where} holds {available}")
    if short:
        raise ValidationError(
            "This issue cannot be served with the units on the shelf — "
            + "; ".join(short)
            + ". Change the batch or the quantity before submitting: after approval "
              "the batch is frozen and the issue could never be posted.")


async def _decorate_issue_serials(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> m.MaterialIssue:
    rows_by_line = await _issue_units_by_line(db, issue)
    item_ids = {line.item_id for line in issue.items}
    qc_by_item: dict[int, bool] = {}
    serial_by_item: dict[int, bool] = {}
    imei_tracked_by_item: dict[int, bool] = {}
    item_by_id: dict[int, object] = {}
    coded_items: set[int] = set()
    if item_ids:
        item_rows = (await db.execute(
            # `is_asset` too: it is what separates an asset tag from a consumable lot
            # code on the badge, and both are UNIT_MODE_CODE to the matcher.
            select(Item.id, Item.is_serial_tracked, Item.is_imei_tracked, Item.is_asset,
                   Item.requires_qi)
            .where(Item.id.in_(item_ids))
        )).all()
        qc_by_item = {row[0]: bool(row[4]) for row in item_rows}
        item_rows = [row[:4] for row in item_rows]
        serial_by_item = {
            item_id: bool(is_serial_tracked)
            for item_id, is_serial_tracked, _, _ in item_rows
        }
        imei_tracked_by_item = {
            item_id: bool(is_imei_tracked)
            for item_id, _, is_imei_tracked, _ in item_rows
        }
        item_by_id = {
            item_id: SimpleNamespace(is_serial_tracked=bool(serial),
                                     is_imei_tracked=bool(imei),
                                     is_asset=bool(asset))
            for item_id, serial, imei, asset in item_rows
        }
        # Which items actually have identified units AT THIS POINT. Without it the
        # screen would offer a unit picker on every bulk line, where there is nothing
        # to pick — and units coded at the warehouse are not pickable from an MDP.
        # `== 1` rather than `.is_(True)` for the same reason as `_issue_unit_supply`:
        # `IS true` costs MySQL the loose index scan, and this DISTINCT over 773k unit
        # rows went from 9.6 seconds to a few milliseconds with it.
        coded_items = set((await db.execute(
            select(m.SerialNumber.item_id)
            .where(m.SerialNumber.item_id.in_(item_ids),
                   m.SerialNumber.warehouse_id == issue.warehouse_id,
                   m.SerialNumber.is_active == 1)
            .distinct()
        )).scalars().all())
    # How many units this line's own source actually holds, so the screen can say so
    # before the document is submitted rather than at the shelf. Read once per
    # (item, batch, bin) — a consolidated issue repeats the same source across lines.
    supply = await _issue_unit_supply(db, issue)
    for line in issue.items:
        mode = _unit_mode(item_by_id.get(line.item_id))
        # Per LINE, not per item. Two lines of the same monitor in two batches are two
        # different sets of units, and lumping them showed each line the other's.
        line_rows = rows_by_line.get(line.id, [])
        setattr(line, "serial_numbers", [row.serial_number for row in line_rows])
        # IMEI travels with the serial, so the issue screen and everything downstream
        # can show both without going back to whs_serial_numbers per line.
        setattr(line, "imei_numbers", [row.imei for row in line_rows if row.imei])
        setattr(line, "is_serial_tracked", serial_by_item.get(line.item_id, False))
        setattr(line, "is_imei_tracked", imei_tracked_by_item.get(line.item_id, False))
        setattr(line, "unit_mode", mode)
        has_units = line.item_id in coded_items and (
            not (line.batch_id or line.bin_id)
            or await _lot_has_units(db, item_id=line.item_id,
                                    warehouse_id=issue.warehouse_id,
                                    batch_id=line.batch_id, bin_id=line.bin_id))
        setattr(line, "has_units", has_units)
        # What the badge on the screen says. Read per line, because `has_units` is —
        # see `_tracking_type`.
        setattr(line, "tracking_type",
                _tracking_type(item_by_id.get(line.item_id), has_units=has_units))
        setattr(line, "units_available", supply.get(line.id))
        setattr(line, "requires_qc", qc_by_item.get(line.item_id, False))
        # What the storekeeper validated on, echoed back in the same currency he typed:
        # the serial for a serialized item, the IMEI for a handset, the code otherwise.
        setattr(line, "unit_keys", [
            keys[0] for keys in (_unit_keys(row, mode) for row in line_rows) if keys
        ])
        setattr(line, "codes_needed", None)
        setattr(line, "box_codes", None)
        setattr(line, "container_note", None)
        setattr(line, "issue_in_boxes", False)
        if mode == UNIT_MODE_CODE and issue.direction == IssueDirection.OUT.value:
            view = await box_codes.line_view(db, issue, line)
            if view is not None:
                # Issued in a container (2026-10-26): the line names its BOXES.
                setattr(line, "issue_in_boxes", True)
                setattr(line, "container_note", view["container_note"])
                if view["codes"]:
                    setattr(line, "unit_keys", view["codes"])
                    setattr(line, "codes_needed", view["codes_needed"])
                    setattr(line, "box_codes", view["boxes"])
                else:
                    # No box held: an old lot not converted yet, named per unit's box.
                    packages = await _issue_container_packages(db, line.item_id)
                    codes = await _container_codes(db, line_rows, mode, packages)
                    setattr(line, "unit_keys", codes)
                    if len(line_rows) >= int(_d(line.issued_qty)) and codes:
                        setattr(line, "codes_needed", len(codes))
    return issue


# The most source rows `issue_stock_sources` probes for coded units. Each probe is one
# bounded index lookup; past this a screen is showing more bays than anybody reads.
_CODED_PROBE_ROWS = 400


async def issue_stock_sources(
    db: AsyncSession,
    *,
    warehouse_id: int,
    item_ids: list[int],
    indent_id: int | None = None,
    project_id: int | None = None,
    issue_id: int | None = None,
    user=None,
) -> list[dict]:
    """Every (batch, bin) an item can actually be drawn from here, oldest first.

    `issue_id`: the document being edited. A direct issue reserves its own picks
    (`ISSUE_HOLD`), and those count as its own exactly as an indent's allocation does.

    Each row also says whether the item MUST leave with a code per unit
    (`codes_required`) and whether that (batch, location) holds any free coded unit
    (`has_unit_codes`) — what the screen needs to offer the one batch swap FEFO allows
    past the same-day rule (`_coded_swap_verdict`). A bounded EXISTS per row, never a
    count.

    `project_id`: lots set aside for that project (`stk_project_holds`) count as this
    document's own, exactly like the indent's reservation. Nobody else sees them.

    The screen needs this because a line has ONE bin and ONE batch and the shelf
    frequently does not: fifteen monitors sitting five in one bay and ten in another
    are two picks, and the form could express only one of them. A storekeeper typed 15
    against a bin holding 5, the picker then offered 5 codes for a line claiming 15,
    and the mismatch between "codes selected" and "issued quantity" was the only hint
    anything was wrong.

    **`available_qty` alone is NOT what a line may draw, and reporting it as such is
    worse than saying nothing.** An approved allocation RESERVES the stock it is about
    to issue, so a document issuing exactly what was reserved for it sees its own
    balance row at `available_qty = 0` — the goods are on the shelf, spoken for, by
    this very document. Reporting 0 there tells a storekeeper his correct document is
    impossible. `own_reserved_qty` is that hold, and `drawable_qty` is the sum: the
    same rule `_stock_offerable` already applies to which ROWS are visible, applied to
    the quantity on them. Everyone else's reservations stay out of it.

    Read off `stk_balance` alone (4 ms for a whole document), never off
    `whs_serial_numbers`: that table is one row per physical unit, holds 773k of them,
    and a COUNT grouped by batch and bin measured 7.5 seconds. How many CODED units a
    pick can name is a different question with a different answer, and it is served per
    line by `_issue_unit_supply`, which stops counting as soon as it has enough.

    Ordered the way stock should leave: expiry first, then the older batch, then the
    bin code, so the default split a screen builds from this list is FIFO without the
    screen knowing what FIFO is.

    Each row also carries the two OUTER quantities its own numbers sit inside — the
    item's whole position in this warehouse (`item_total_qty` / `item_available_qty`)
    and this batch's (`batch_total_qty` / `batch_available_qty`), both denormalised
    onto every row of the item. A storekeeper asked to take 10 out of a bay needs to
    know whether the warehouse holds 12 of the thing or 1,200, and neither figure can
    be summed out of the list itself: rows another document has entirely reserved are
    not in it.
    """
    from app.modules.inventory.models import Reservation, Stock

    ids = [int(value) for value in dict.fromkeys(item_ids) if value]
    if not warehouse_id or not ids:
        return []
    # Stock this warehouse banked before it kept locations is given its Unlocated
    # location first, or none of it could be offered as a source — see `unlocated.py`.
    await unlocated.heal(db, warehouse_id, user)

    # What THIS indent is already holding on each balance row. Aggregated in a
    # subquery rather than joined directly: a balance row can carry several
    # reservation rows, and joining them would multiply the quantity sums.
    if indent_id or project_id:
        mine = (
            select(Reservation.stock_id.label("stock_id"),
                   func.sum(Reservation.quantity).label("qty"))
            .where(_own_hold_clause(indent_id, project_id),
                   Reservation.status == ReservationStatus.ACTIVE.value)
            .group_by(Reservation.stock_id)
            .subquery()
        )
        own = func.coalesce(func.sum(mine.c.qty), 0)
    else:
        mine = None
        own = literal(0)
    # A direct issue's own hold, served apart from the indent's: it is stock this
    # document may draw, but it is NOT an allocation — the screen must not read it as
    # one and switch the FEFO lock on for a manual issue.
    if issue_id:
        held = (
            select(Reservation.stock_id.label("stock_id"),
                   func.sum(Reservation.quantity).label("qty"))
            .where(Reservation.ref_type == InventoryRefType.ISSUE_HOLD.value,
                   Reservation.ref_id == issue_id,
                   Reservation.status == ReservationStatus.ACTIVE.value)
            .group_by(Reservation.stock_id)
            .subquery()
        )
        hold_qty = func.coalesce(func.sum(held.c.qty), 0)
    else:
        held = None
        hold_qty = literal(0)

    stmt = (
        select(
            Stock.item_id,
            Stock.bin_id,
            Stock.batch_id,
            func.sum(Stock.available_qty).label("available_qty"),
            func.sum(Stock.reserved_qty).label("reserved_qty"),
            func.sum(Stock.total_qty).label("total_qty"),
            own.label("own_reserved_qty"),
            hold_qty.label("issue_hold_qty"),
            Bin.code,
            Bin.name,
            m.Batch.batch_no,
            m.Batch.expiry_date,
            m.Batch.mfg_date,
            # Which brand / variant / model the row is (2026-10-23).
            Stock.brand_id, Stock.variant_id, Stock.model_id,
        )
        .select_from(Stock)
        .outerjoin(Bin, Bin.id == Stock.bin_id)
        .outerjoin(m.Batch, m.Batch.id == Stock.batch_id)
    )
    if mine is not None:
        stmt = stmt.outerjoin(mine, mine.c.stock_id == Stock.id)
    if held is not None:
        stmt = stmt.outerjoin(held, held.c.stock_id == Stock.id)
    stmt = (
        stmt
        .where(Stock.warehouse_id == warehouse_id,
               Stock.item_id.in_(ids),
               _stock_offerable(indent_id, project_id, issue_id),
               or_(
                   func.coalesce(m.Batch.expiry_date, Stock.expiry_date).is_(None),
                   func.coalesce(m.Batch.expiry_date, Stock.expiry_date) >= ist_today(),
               ))
        .group_by(Stock.item_id, Stock.bin_id, Stock.batch_id,
                  Bin.code, Bin.name, m.Batch.batch_no,
                  m.Batch.expiry_date, m.Batch.mfg_date,
                  Stock.brand_id, Stock.variant_id, Stock.model_id)
        .order_by(m.Batch.expiry_date.is_(None), m.Batch.expiry_date,
                  Stock.batch_id, Bin.code)
    )
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=Stock.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        ))
        # And within the warehouse, the caller's own floors. The warehouse scope above
        # answers "which building"; this answers "which floor of it", which is the
        # question a floor in-charge is bound by. Without it the splits this list
        # builds pointed at bins `_assert_issue_floor_access` then refused, so the
        # storekeeper filled in a form that could not be saved.
        allowed = await floor_scope_ids(db, user)
        if allowed is not None:
            stmt = stmt.where(Stock.bin_id.in_(allowed) if allowed else false())

    rows = (await db.execute(stmt)).all()

    # Other indents' quantity holds per (item, bin, batch), less what their open
    # issues have pinned — tradeable on save (`allocation.swap_holds`).
    tradeable: dict[tuple, Decimal] = {}
    if indent_id:
        for t_item, t_bin, t_batch, t_brand, t_variant, t_model, t_qty in (await db.execute(
            select(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                   Stock.brand_id, Stock.variant_id, Stock.model_id,
                   func.sum(Reservation.quantity))
            .join(Stock, Stock.id == Reservation.stock_id)
            .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
                   Reservation.status == ReservationStatus.ACTIVE.value,
                   Reservation.warehouse_id == warehouse_id,
                   Reservation.item_id.in_(ids),
                   Reservation.ref_id != indent_id)
            .group_by(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                      Stock.brand_id, Stock.variant_id, Stock.model_id)
        )).all():
            tradeable[(int(t_item), int(t_bin or 0), int(t_batch or 0),
                       *_combo3(t_brand, t_variant, t_model))] = _d(t_qty)
        _pins, pinned_slots = await _open_issue_pins(
            db, warehouse_id, set(ids), exclude_issue_id=issue_id)
        for pin_slot, pinned in pinned_slots.items():
            for slot in [key for key in tradeable if key[:3] == pin_slot]:
                used = min(tradeable[slot], pinned)
                tradeable[slot] -= used
                pinned -= used

    # What the warehouse holds for these items ALTOGETHER — every batch, every
    # location, and deliberately NOT filtered by `_stock_offerable`. A screen shows
    # three nested quantities, warehouse then batch then location, and the two outer
    # ones cannot be summed out of the rows above: a row every other document has
    # reserved is dropped from that list, so summing it would quietly report a
    # half-empty shelf as empty. Read once here, denormalised onto each row of the
    # item, because the answer is per (item, batch) and the caller reads it per source.
    totals = (
        select(Stock.item_id, Stock.batch_id,
               func.sum(Stock.total_qty).label("total_qty"),
               func.sum(Stock.available_qty).label("available_qty"))
        .outerjoin(m.Batch, m.Batch.id == Stock.batch_id)
        .where(Stock.warehouse_id == warehouse_id, Stock.item_id.in_(ids),
               or_(
                   func.coalesce(m.Batch.expiry_date, Stock.expiry_date).is_(None),
                   func.coalesce(m.Batch.expiry_date, Stock.expiry_date) >= ist_today(),
               ))
        .group_by(Stock.item_id, Stock.batch_id)
    )
    if user is not None:
        totals = totals.where(await scope_condition(
            db, user,
            warehouse_col=Stock.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        ))
    by_batch: dict[tuple[int, int], tuple[Decimal, Decimal]] = {}
    by_item: dict[int, tuple[Decimal, Decimal]] = {}
    for t_item, t_batch, t_total, t_available in (await db.execute(totals)).all():
        by_batch[(t_item, t_batch or 0)] = (_d(t_total), _d(t_available))
        held = by_item.get(t_item, (ZERO, ZERO))
        by_item[t_item] = (held[0] + _d(t_total), held[1] + _d(t_available))

    # One read of the warehouse's tree for the whole answer, so every source can name
    # the floor / lane / rack it sits on rather than a bare bin code.
    index = await _location_index(db, warehouse_id)
    # Must the item leave with a code per unit, and does this (batch, location) hold a
    # free coded unit? What the screen needs to offer the one batch swap FEFO allows
    # past the same-day rule (`_coded_swap_verdict`). A bounded EXISTS per row, never
    # a COUNT, and only for items that require codes.
    code_config = await codeformat.code_settings(db)
    codes_required = {
        item_id: await _unit_codes_required(
            db, await _item_snapshot(db, item_id), config=code_config)
        for item_id in {row[0] for row in rows}}
    coded_slots: set[tuple[int, int, int]] = set()
    for item_id, bin_id, batch_id, *_ in rows[:_CODED_PROBE_ROWS]:
        if not codes_required.get(item_id):
            continue
        probe = (select(literal(1)).select_from(m.SerialNumber)
                 .where(m.SerialNumber.item_id == item_id,
                        m.SerialNumber.warehouse_id == warehouse_id,
                        m.SerialNumber.status == SerialStatus.AVAILABLE.value,
                        m.SerialNumber.is_active == 1,
                        (m.SerialNumber.batch_id == batch_id) if batch_id else or_(
                            m.SerialNumber.batch_id.is_(None),
                            m.SerialNumber.batch_id == 0),
                        _unit_claim_free_clause("")))
        if bin_id:
            probe = probe.where(m.SerialNumber.bin_id == bin_id)
        if await db.scalar(probe.limit(1)):
            coded_slots.add((item_id, bin_id or 0, batch_id or 0))
    out = []
    for (item_id, bin_id, batch_id, available_qty, reserved_qty, total_qty,
         own_qty, hold_qty_row, bin_code, bin_name, batch_no, expiry_date,
         mfg_date, c_brand, c_variant, c_model) in rows:
        combo = _combo3(c_brand, c_variant, c_model)
        own_reserved = _d(own_qty)
        other_indents = tradeable.get((item_id, bin_id or 0, batch_id or 0, *combo), ZERO)
        issue_hold = _d(hold_qty_row)
        drawable = _d(available_qty) + own_reserved + other_indents + issue_hold
        if drawable <= ZERO:
            continue
        out.append({
            "item_id": item_id,
            # NO_BIN / NO_BATCH mean "the line names none" everywhere else in this
            # module (`_claim_units`, `move_stock_out`); they are handed back as null
            # so a screen never writes 0 into a picker as though it were an id.
            "bin_id": bin_id or None,
            "bin_code": bin_code or (None if not bin_id else f"Bin {bin_id}"),
            "bin_name": bin_name or bin_code,
            "bin_path": (index.get(bin_id) or {}).get("path") if bin_id else None,
            "bin_steps": (index.get(bin_id) or {}).get("steps", []) if bin_id else [],
            "batch_id": batch_id or None,
            "batch_no": batch_no,
            "expiry_date": expiry_date,
            "mfg_date": mfg_date,
            "available_qty": _d(available_qty),
            "reserved_qty": _d(reserved_qty),
            "own_reserved_qty": own_reserved,
            # Set aside for OTHER indents but tradeable — picking it here moves their
            # quantity hold onto another batch on save. Never a refusal.
            "other_indent_qty": other_indents,
            "issue_hold_qty": issue_hold,
            "total_qty": _d(total_qty),
            "drawable_qty": drawable,
            "batch_total_qty": by_batch.get((item_id, batch_id or 0), (ZERO, ZERO))[0],
            "batch_available_qty": by_batch.get((item_id, batch_id or 0), (ZERO, ZERO))[1],
            "item_total_qty": by_item.get(item_id, (ZERO, ZERO))[0],
            "item_available_qty": by_item.get(item_id, (ZERO, ZERO))[1],
            "codes_required": bool(codes_required.get(item_id)),
            "has_unit_codes": (item_id, bin_id or 0, batch_id or 0) in coded_slots,
            "brand_id": combo[0], "variant_id": combo[1], "model_id": combo[2],
        })
    await combinations.fill_names(db, out)
    return out


async def _realign_issue_reservations(db: AsyncSession, issue: m.MaterialIssue,
                                      user) -> list[dict]:
    """Follow the document when it changes where the goods are coming from.

    An indent-linked issue is drafted from an approved allocation, and that allocation
    holds CONCRETE stock rows — `inv_reservations`, one per (bin, batch) it drew on.
    The storekeeper who then walks the floor regularly finds the goods somewhere else
    and changes the batch or the storage location on the line.

    Until this ran, that edit was cosmetic. The hold stayed on the rows inventory
    picked, `post_issue` consumed those exact rows (it consumes the reservation, not
    the line), and so the stock left a bay the document did not name — while the bay
    it DID name stayed reserved for a document that had already gone. Two wrong
    balances from one honest correction.

    So: what the document has stopped naming is **released back to `available_qty`,
    free for anybody**, and the same quantity is taken where it now points.
    `allocation.relocate` owns the arithmetic — reservation columns are its to move
    (rule 7) — and it never changes the total held, so an issue drawing less than was
    allocated leaves the rest of the allocation exactly where it was.

    Per indent LINE, because that is what a reservation is keyed on, and summed over
    the issue's own lines first: one ask served out of two bays is two issue lines
    against one indent line, and looking at either alone would read the other's bay
    as abandoned.
    """
    if issue.direction != IssueDirection.OUT.value:
        return []

    line_indents = await _line_indent_ids(db, issue)
    # {(indent, indent line, item, combination): {(bin, batch): quantity}} — per
    # brand / variant / model too (2026-10-23): an Alpha line and a Beta line of one
    # indent line hold different stock and move separately.
    wanted: dict[tuple, dict[tuple[int, int], Decimal]] = defaultdict(dict)
    labels: dict[tuple, str] = {}
    for line in issue.items:
        if not line.indent_item_id:
            continue
        indent_id = line_indents.get(line.id) or issue.indent_id
        if not indent_id:
            continue
        qty = _d(line.issued_qty)
        if qty <= ZERO:
            continue
        key = (indent_id, line.indent_item_id, line.item_id, combo_key(line))
        slot = (int(line.bin_id or 0), int(line.batch_id or 0))
        wanted[key][slot] = wanted[key].get(slot, ZERO) + qty
        labels[key] = line.item_code or line.item_name or f"item {line.item_id}"

    moved: list[dict] = []
    for (indent_id, indent_item_id, item_id, combo), slots in wanted.items():
        combination = (None if combo is None else
                       {"brand_id": combo[0], "variant_id": combo[1], "model_id": combo[2]})
        # A document that names no location and no batch is not saying where the goods
        # are — it is saying nothing. Two shapes arrive like that and neither is a
        # correction to follow: a point that stocks in bulk (`bin_id` 0 on every line
        # by design), and `_split_by_reservations` falling back to one unsplit line
        # when the holds do not add up. Reading either as "move everything to bin 0"
        # would try to relocate onto a balance row that does not exist, and would fail
        # the allocation-approval transaction that drafts these issues in the first
        # place.
        if all(slot == (0, 0) for slot in slots):
            continue
        # A line naming a batch but no bay asks for THAT BATCH wherever it stands, not
        # for a bay numbered 0. When every hold of this line already sits on a batch the
        # document names, nothing has moved — relocating would try to pull the hold onto
        # a balance row that does not exist and refuse a correct document (found
        # 2026-10-06 by the split scenarios).
        if any(bin_id == 0 for bin_id, _batch in slots):
            from app.modules.inventory.models import Reservation
            named = {batch for _bin, batch in slots}
            held_batches = set((await db.execute(
                select(Reservation.batch_id).where(
                    Reservation.ref_type == InventoryRefType.RESERVATION.value,
                    Reservation.ref_id == indent_id,
                    Reservation.ref_line_id == indent_item_id,
                    Reservation.item_id == item_id,
                    Reservation.warehouse_id == issue.warehouse_id,
                    Reservation.status == ReservationStatus.ACTIVE.value)
            )).scalars().all())
            if 0 in named or {int(b or 0) for b in held_batches} <= named:
                continue
        if issue.project_id:
            await _free_project_holds_for_slots(
                db, issue, indent_id, indent_item_id, item_id, slots, user)
        # The batch picked may carry ANOTHER indent's quantity hold — holds float
        # between batches (`allocation.swap_holds`). Trade rows with it first; what is
        # left is covered out of free stock by `relocate`.
        pins, _by_slot = await _open_issue_pins(
            db, issue.warehouse_id, {item_id}, exclude_issue_id=issue.id)
        await stock_allocation.swap_holds(
            db, InventoryRefType.RESERVATION.value, indent_id,
            ref_line_id=indent_item_id, item_id=item_id,
            warehouse_id=issue.warehouse_id, wanted=slots, pinned=pins,
            combination=combination)
        for move in await stock_allocation.relocate(
            db,
            InventoryRefType.RESERVATION.value,
            indent_id,
            wanted=slots,
            ref_line_id=indent_item_id,
            item_id=item_id,
            warehouse_id=issue.warehouse_id,
            ref_no=issue.issue_no,
            user=user,
            label=labels[(indent_id, indent_item_id, item_id, combo)],
            combination=combination,
        ):
            moved.append({
                "item_id": move.item_id,
                "quantity": str(move.quantity),
                "from_bin": await _bin_code(db, move.from_bin_id or None),
                "to_bin": await _bin_code(db, move.to_bin_id or None),
                "from_batch_id": move.from_batch_id or None,
                "to_batch_id": move.to_batch_id or None,
            })

    if moved:
        # Worth an audit row of its own: a hold silently leaving one bay for another is
        # exactly the kind of change somebody comes back asking about a month later.
        await write_audit(
            db, entity="inv_reservations", entity_id=issue.id,
            entity_no=issue.issue_no, action=AuditAction.UPDATE, actor=user,
            before={"reason": "material issue moved off the allocated location"},
            after={"moves": moved},
        )
    return moved


async def _direct_issue_lines(db: AsyncSession, issue: m.MaterialIssue) -> list:
    """The outward lines no indent stands behind — a direct issue, a stock transfer,
    a scrap write-off. Nothing was allocated for them, so nothing is reserved for them
    unless the issue reserves it itself."""
    if issue.direction != IssueDirection.OUT.value:
        return []
    line_indents = await _line_indent_ids(db, issue)
    return [line for line in issue.items
            if _d(line.issued_qty) > ZERO
            and not (line_indents.get(line.id) or issue.indent_id)]


async def _release_issue_hold(db: AsyncSession, issue_id: int) -> Decimal:
    """Give everything a direct issue was holding back to `available_qty`."""
    return await stock_allocation.release(
        db, InventoryRefType.ISSUE_HOLD.value, issue_id)


async def _hold_direct_issue_stock(db: AsyncSession, issue: m.MaterialIssue, user, *,
                                   strict: bool = True) -> None:
    """Reserve the picks of a direct issue from the moment it is saved (2026-10-06).

    An indent-based issue is drafted from an approved allocation, which RESERVED the
    stock — nobody else can take it while the document climbs its ladder. A direct
    issue had no such hold: two drafts could promise the same ten units, both be
    approved, and the second found the shelf empty at posting, after its whole
    approval. Now each line's (bin, batch) is held under `ISSUE_HOLD`, re-taken on
    every save (released first, so an edit never double-holds), released on cancel
    and reject, and CONSUMED when the issue posts — exactly the life an allocation's
    hold has.

    Lots set aside for the issue's project are taken first (they are its own), the
    rest from free stock at the named spot. `strict=False` is the best-effort path a
    split parent uses when its floor issues are all cancelled: the hold is restored
    where it still can be, and posting re-checks the shelf either way.
    """
    await _release_issue_hold(db, issue.id)
    short: list[str] = []
    for line in await _direct_issue_lines(db, issue):
        want = _d(line.issued_qty)
        got = ZERO
        if issue.project_id:
            got += await stock_allocation.take_from_holds(
                db, item_id=line.item_id, project_id=issue.project_id, qty=want,
                ref_type=InventoryRefType.ISSUE_HOLD.value, ref_id=issue.id,
                ref_no=issue.issue_no, ref_line_id=line.id, user=user,
                warehouse_ids=[issue.warehouse_id],
                bin_id=line.bin_id or None, batch_id=line.batch_id or None,
                combination=combo_dict(line))
        if got < want:
            got += await stock_allocation.reserve_at(
                db, item_id=line.item_id, qty=want - got,
                warehouse_id=issue.warehouse_id,
                bin_id=line.bin_id or None, batch_id=line.batch_id or None,
                ref_type=InventoryRefType.ISSUE_HOLD.value, ref_id=issue.id,
                ref_no=issue.issue_no, ref_line_id=line.id, user=user,
                combination=combo_dict(line))
        if got < want:
            where = " / ".join(filter(None, (line.batch_no, line.bin_code))) or "this point"
            short.append(f"{line.item_code or line.item_id}: {want} wanted at {where}, "
                         f"only {got} free to reserve")
    if short and strict:
        raise ValidationError(
            "This issue could not reserve its stock — " + "; ".join(short)
            + ". Another document took it since the shelf was read; refresh and "
              "re-pick.")


async def _free_project_holds_for_slots(db: AsyncSession, issue: m.MaterialIssue,
                                        indent_id: int, indent_item_id: int,
                                        item_id: int,
                                        slots: dict[tuple[int, int], Decimal],
                                        user) -> None:
    """A pick moved onto a location whose stock is held for THIS issue's project.

    `relocate` takes the new location's quantity out of `available_qty`, and a held
    lot is not in it — so the move was refused although the stock is this project's
    own. Hand back exactly the part the free stock and the indent's own hold there
    cannot cover, and no more: anything handed back and not taken is free to all."""
    from app.modules.inventory.models import Reservation, Stock

    held_here: dict[tuple[int, int], Decimal] = defaultdict(Decimal)
    for bin_id, batch_id, qty in (await db.execute(
        select(Reservation.bin_id, Reservation.batch_id, func.sum(Reservation.quantity))
        .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
               Reservation.ref_id == indent_id,
               Reservation.ref_line_id == indent_item_id,
               Reservation.item_id == item_id,
               Reservation.warehouse_id == issue.warehouse_id,
               Reservation.status == ReservationStatus.ACTIVE.value)
        .group_by(Reservation.bin_id, Reservation.batch_id)
    )).all():
        held_here[(int(bin_id or 0), int(batch_id or 0))] += _d(qty)
    for (bin_id, batch_id), qty in slots.items():
        free = _d(await db.scalar(
            select(func.coalesce(func.sum(Stock.available_qty), 0)).where(
                Stock.item_id == item_id, Stock.warehouse_id == issue.warehouse_id,
                Stock.bin_id == bin_id, Stock.batch_id == batch_id)))
        need = _d(qty) - held_here.get((bin_id, batch_id), ZERO) - free
        if need > ZERO:
            await stock_allocation.take_from_holds(
                db, item_id=item_id, project_id=issue.project_id, qty=need,
                ref_type=None, ref_id=None, ref_no=None, ref_line_id=None, user=user,
                warehouse_ids=[issue.warehouse_id], bin_id=bin_id, batch_id=batch_id)


#: What a write line actually issues. `issued_qty` omitted means "all of it" — the
#: same reading `_apply_issue_lines` gives it a few lines further down, and a guard
#: reading it as zero would wave through exactly the lines that take the most.
def _line_issued(line) -> Decimal:
    return (_d(line.requested_qty) if getattr(line, "issued_qty", None) is None
            else _d(line.issued_qty))


#: Which (bin, batch) a write line names, in the module's own 0-means-none currency.
def _line_slot(line) -> tuple[int, int]:
    return (int(getattr(line, "bin_id", None) or 0),
            int(getattr(line, "batch_id", None) or 0))


def _fefo_swap_allowed(wanted, allocated: list) -> bool:
    """May a pick be moved off the batch that was allocated, onto this one?

    **Only onto a batch expiring on the same day**, which is the single swap FEFO
    cannot tell apart. Inventory allocated earliest-expiry-first; reaching past that
    batch onto a later one leaves the earlier stock on the shelf to expire, and does it
    invisibly — nothing downstream would ever say so.

    A batch with no recorded expiry matches only another with none. "No expiry" is
    nobody having written one down, not "never expires", and treating it as a distant
    date would let an undated batch be swapped for anything.

    Nothing allocated (`allocated` empty) is no constraint at all — a manual issue has
    nothing signed behind it to depart from. Pure, so the rule can be read and tested
    without a database; `_assert_issue_sources` is what applies it.
    """
    if not allocated:
        return True
    return any(row is not None and row.expiry_date == wanted.expiry_date
               for row in allocated)


def _expires_before(a, b) -> bool:
    """Does expiry `a` fall before `b`, in the order stock leaves the shelf?
    Undated sorts LAST — the same order `issue_stock_sources` serves — so an undated
    batch is never "older" than a dated one."""
    if a is None:
        return False
    return b is None or a < b


def _coded_swap_verdict(*, codes_required: bool, allocated_has_codes: bool,
                        wanted_has_codes: bool, earlier_coded: list) -> bool | None:
    """The one exception to the same-day FEFO rule (2026-10-06).

    An item that must leave with one serial / IMEI / asset or consumable code per unit
    cannot be issued out of a batch that carries no codes — `post_issue` refuses an
    incomplete set at the shelf, so the allocated batch is a document that can never
    post. Holding the storekeeper to that batch is not FEFO, it is a dead end. So a
    swap onto a later batch IS allowed when:

    - the item requires codes, and
    - the allocated batch has no free coded unit left here, and
    - the batch being moved onto has some, and
    - no OTHER batch expiring before it has any (`earlier_coded` empty) — FEFO still
      decides among the batches that can actually be issued.

    True = allowed. None = this exception does not apply (the ordinary rule stands).
    Pure, so it reads and tests without a database.
    """
    if not (codes_required and not allocated_has_codes and wanted_has_codes):
        return None
    return True if not earlier_coded else None


async def _batches_with_units(db: AsyncSession, *, item_id: int, warehouse_id: int,
                              batch_ids, bin_id: int | None = None) -> set[int]:
    """Which of these batches hold at least one free coded unit at this point.

    One bounded EXISTS per batch on `ix_whs_serial_stock_lookup` — never a COUNT:
    `whs_serial_numbers` is one row per physical unit and holds hundreds of thousands
    of them, and "is there at least one" is all the FEFO exception asks.
    """
    out: set[int] = set()
    for batch_id in {int(b) for b in batch_ids if b}:
        probe = (
            select(literal(1)).select_from(m.SerialNumber)
            .where(m.SerialNumber.item_id == item_id,
                   m.SerialNumber.warehouse_id == warehouse_id,
                   m.SerialNumber.status == SerialStatus.AVAILABLE.value,
                   m.SerialNumber.is_active == 1,
                   m.SerialNumber.batch_id == batch_id,
                   _unit_claim_free_clause(""))
        )
        if bin_id:
            probe = probe.where(m.SerialNumber.bin_id == bin_id)
        if await db.scalar(probe.limit(1)):
            out.add(batch_id)
    return out


async def _coded_swap(db: AsyncSession, *, issue: m.MaterialIssue, item_id: int,
                      wanted: m.Batch, signed: set[int],
                      batches: dict[int, m.Batch]) -> tuple[bool, str | None]:
    """Apply `_coded_swap_verdict` against the shelf. Returns (allowed, hint) — the
    hint names the batch the storekeeper should have picked instead, when the
    exception applies in principle but he reached past an older coded batch."""
    from app.modules.inventory.models import Stock

    item = await _item_snapshot(db, item_id)
    if not await _unit_codes_required(db, item):
        return False, None
    if await _batches_with_units(db, item_id=item_id, warehouse_id=issue.warehouse_id,
                                 batch_ids=signed):
        return False, None
    if not await _batches_with_units(db, item_id=item_id, warehouse_id=issue.warehouse_id,
                                     batch_ids={wanted.id}):
        return False, None
    # Every other batch of the item on this shelf that expires first.
    others = (await db.execute(
        select(m.Batch).join(Stock, Stock.batch_id == m.Batch.id)
        .where(Stock.item_id == item_id, Stock.warehouse_id == issue.warehouse_id,
               # Free stock only — the screen offers the same rows (stock-sources).
               Stock.available_qty > 0, m.Batch.id.notin_({wanted.id, *signed}))
        .distinct()
    )).scalars().all()
    earlier = [b for b in others if _expires_before(b.expiry_date, wanted.expiry_date)]
    coded = await _batches_with_units(db, item_id=item_id, warehouse_id=issue.warehouse_id,
                                      batch_ids={b.id for b in earlier})
    earlier_coded = sorted((b for b in earlier if b.id in coded),
                           key=lambda b: (b.expiry_date is None, b.expiry_date, b.id))
    verdict = _coded_swap_verdict(codes_required=True, allocated_has_codes=False,
                                  wanted_has_codes=True, earlier_coded=earlier_coded)
    if verdict:
        return True, None
    first = earlier_coded[0]
    batches.setdefault(first.id, first)
    return False, (f" The allocated batch carries no codes, so it may be swapped — but "
                   f"onto {first.batch_no or f'batch {first.id}'} "
                   f"({_fefo_expiry(first)}), the oldest batch here that does.")


def _fefo_expiry(batch) -> str:
    """A batch's expiry, said the way a refusal has to say it.

    An undated batch is not "expires never" — it is nobody having recorded one, and a
    message must not invent a date for it to be compared against.
    """
    if batch is None or batch.expiry_date is None:
        return "no expiry recorded"
    return f"expires {batch.expiry_date.isoformat()}"


async def _write_line_indents(db: AsyncSession,
                              lines: list[s.IssueItemWrite]) -> dict[int, int]:
    """`{indent line id: the indent it belongs to}` for the lines being written.

    One query for the document. `_indent_id_for_line` answers the same question per
    line, and a consolidated issue serving a monthly cycle has hundreds of them.
    """
    from app.modules.indents.models import IndentItem

    wanted = {int(line.indent_item_id) for line in lines if line.indent_item_id}
    if not wanted:
        return {}
    rows = (await db.execute(
        select(IndentItem.id, IndentItem.indent_id).where(IndentItem.id.in_(wanted))
    )).all()
    return {int(row[0]): int(row[1]) for row in rows if row[1]}


def _expires_later(a, b) -> bool:
    """Does expiry `a` come after expiry `b`? A batch with no recorded expiry sorts
    after every dated one — "nobody wrote a date" is never "leaves first"."""
    if a is None:
        return b is not None
    if b is None:
        return False
    return a > b


def _fefo_expiry_date(value) -> str:
    return f"expires {value}" if value else "no expiry recorded"


async def _open_issue_pins(db: AsyncSession, warehouse_id: int, item_ids,
                           *, exclude_issue_id: int | None = None):
    """What OTHER open issues have explicitly picked here, indent line by indent line.

    Returns ({(indent, indent line, bin, batch): qty}, {(item, bin, batch): qty}). Those
    holds are somebody's named goods: `swap_holds` never trades them away and a pick
    never counts them as drawable, or that issue would post from a row it does not
    name. An issue naming no batch and no location pins nothing.
    """
    ids = {int(i) for i in item_ids if i}
    if not ids:
        return {}, {}
    by_owner: dict[tuple[int, int, int, int], Decimal] = defaultdict(Decimal)
    by_slot: dict[tuple[int, int, int], Decimal] = defaultdict(Decimal)
    stmt = (
        select(m.MaterialIssue.indent_id, m.MaterialIssueLine.indent_item_id,
               m.MaterialIssueLine.item_id, m.MaterialIssueLine.bin_id,
               m.MaterialIssueLine.batch_id, m.MaterialIssueLine.issued_qty)
        .join(m.MaterialIssueLine, m.MaterialIssueLine.issue_id == m.MaterialIssue.id)
        .where(m.MaterialIssue.warehouse_id == warehouse_id,
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(False),
               m.MaterialIssue.status.notin_(UNSERVED_ISSUE_STATUSES),
               m.MaterialIssueLine.item_id.in_(ids),
               m.MaterialIssueLine.indent_item_id.is_not(None))
    )
    if exclude_issue_id:
        stmt = stmt.where(m.MaterialIssue.id != exclude_issue_id)
    for indent_id, line_id, item_id, bin_id, batch_id, qty in (await db.execute(stmt)).all():
        if not (bin_id or batch_id) or not indent_id:
            continue
        by_owner[(int(indent_id), int(line_id), int(bin_id or 0), int(batch_id or 0))] += _d(qty)
        by_slot[(int(item_id), int(bin_id or 0), int(batch_id or 0))] += _d(qty)
    return dict(by_owner), dict(by_slot)


async def _assert_sources_picked(db: AsyncSession, issue: m.MaterialIssue) -> None:
    """Every outward line names the batch and location it is taken from.

    Nothing is auto-picked any more (2026-10-12): an allocation sets aside a quantity,
    and the storekeeper chooses the batch — earliest expiry first — and the location
    on the issue. Refused at submit, while both are still editable, and named line by
    line so the fix is obvious. A batch is required only for an item whose stock here
    is batched, a location only where this warehouse keeps locations.
    """
    if issue.direction != IssueDirection.OUT.value:
        return
    from app.modules.inventory.models import Stock

    wh = await db.get(Warehouse, issue.warehouse_id)
    bin_managed = bool(getattr(wh, "is_bin_managed", False))
    item_ids = {line.item_id for line in issue.items if _d(line.issued_qty) > ZERO}
    batched = set((await db.execute(
        select(Stock.item_id).where(Stock.warehouse_id == issue.warehouse_id,
                                    Stock.item_id.in_(item_ids),
                                    Stock.batch_id != m.NO_BATCH,
                                    Stock.total_qty > ZERO).distinct()
    )).scalars().all()) if item_ids else set()
    missing = []
    for line in issue.items:
        if _d(line.issued_qty) <= ZERO:
            continue
        need = []
        if line.item_id in batched and not line.batch_id:
            need.append("batch")
        if bin_managed and not line.bin_id:
            need.append("storage location")
        if need:
            missing.append(f"{line.item_code or line.item_name} ({' and '.join(need)})")
    if missing:
        raise ValidationError(
            "Pick the batch and storage location for every line before submitting — "
            "batches are offered earliest-expiry first. Still to pick: "
            + "; ".join(missing[:5]) + (f" and {len(missing) - 5} more" if len(missing) > 5 else ""))


def _summed(rows):
    """Every balance row at one spot, read as one — available added up.

    A spot (location, item, batch, project) holds one row PER brand / variant / model
    since 2026-10-23, so reading it with `scalar_one_or_none` fails the moment a
    second brand lands there. None where nothing stands there at all."""
    rows = list(rows)
    if not rows:
        return None
    return SimpleNamespace(available_qty=sum((_d(r.available_qty) for r in rows), ZERO))


async def _move_between_bins(db: AsyncSession, *, item_id: int, qty, warehouse_id: int,
                             from_bin_id: int, to_bin_id: int, batch_id: int,
                             project_id: int, ref_type: str, ref_id: int, ref_no: str,
                             user, serial_numbers=None,
                             combination: dict | None = None) -> None:
    """Move stock from one location to another — out, then in AS WHAT CAME OUT.

    Each slice keeps its brand / variant / model (2026-10-23): moving five Alpha
    monitors to another bay lands five Alpha monitors there, never five of none."""
    for slice_ in await move_stock_out(
            db, item_id=item_id, qty=qty, ref_type=ref_type, ref_id=ref_id,
            ref_no=ref_no, user=user, warehouse_id=warehouse_id, bin_id=from_bin_id,
            batch_id=batch_id, project_id=project_id, serial_numbers=serial_numbers,
            **(combination or {})):
        await move_stock(
            db, item_id=item_id, qty=slice_["qty"], direction=StockDirection.IN.value,
            ref_type=ref_type, ref_id=ref_id, ref_no=ref_no, user=user,
            warehouse_id=warehouse_id, bin_id=to_bin_id, batch_id=slice_["batch_id"],
            project_id=project_id, serial_numbers=slice_["serial_numbers"],
            brand_id=slice_["brand_id"], variant_id=slice_["variant_id"],
            model_id=slice_["model_id"])


def _combo3(brand, variant, model) -> tuple[int, int, int]:
    """A balance row's brand / variant / model as a key part (2026-10-23)."""
    return (int(brand or 0), int(variant or 0), int(model or 0))


def line_combo_label(line) -> str:
    """"Alpha · 24-inch · M1" for a line naming a combination, for messages."""
    get = (line.get if isinstance(line, dict) else (lambda k, d=None: getattr(line, k, d)))
    return " · ".join(part for part in (get("brand_name"), get("variant_name"),
                                        get("model_name")) if part) or "that brand"


async def _assert_issue_sources(db: AsyncSession, issue: m.MaterialIssue,
                                lines: list[s.IssueItemWrite]) -> None:
    """Is every pick on this document one the shelf can actually serve?

    Two questions, asked together because they are answered off the same two reads and
    a document that passes one and fails the other is a document that fails.

    **Does the stock exist?** A line may take what is free at its (batch, location)
    plus what THIS indent already holds there — the same `drawable_qty` the screen
    shows, and the same rule `_stock_offerable` applies to which rows are offered at
    all. Nothing checked it before: a manual issue could promise a hundred units of an
    item the point holds none of, and the mistake surfaced at `post_issue`, against a
    document that had by then been through the whole approval ladder. Summed across
    the picks per (item, batch, location), because two picks on one bay each passing
    on their own is how a bay gets over-drawn.

    **May the batch be swapped?** A line drafted from an approved allocation names the
    batch inventory reserved, and that batch was chosen FEFO — earliest expiry first.
    The storekeeper standing at the shelf may well find it behind a pallet, so the swap
    has to be possible; what it must never do is quietly reach past an earlier-expiring
    batch. So it is allowed **only onto a batch expiring on the same day**, which is
    the one swap FEFO cannot tell apart. An unallocated line — a manual issue, with
    nothing signed behind it — is not held to this: it is offered its batches
    oldest-first and there is no allocation to depart from.

    The storage LOCATION is deliberately not constrained beyond the stock check. One
    batch sitting in two bays is one batch, FEFO cannot tell those apart either, and
    which bay a picker walks to is his call — the check that the bay actually holds
    that batch of that item falls out of the first question.
    """
    if issue.direction != IssueDirection.OUT.value:
        return
    outward = [line for line in lines if _line_issued(line) > ZERO]
    if not outward:
        return

    from app.modules.inventory.models import Reservation, Stock

    item_ids = {int(line.item_id) for line in outward}
    line_indents = await _write_line_indents(db, outward)

    # What is on the shelf here, per (item, location, batch). One read for the whole
    # document — the alternative is a query per line. Expired stock is not on it: it is
    # never to be issued, so it can neither satisfy a pick nor be drawn by one.
    today = ist_today()
    # Keyed (item, location, batch, brand, variant, model) since 2026-10-23: a line
    # naming a brand / variant / model draws that combination and no other.
    on_hand: dict[tuple, Decimal] = {}
    for item_id, bin_id, batch_id, c_brand, c_variant, c_model, available in (await db.execute(
        select(Stock.item_id, Stock.bin_id, Stock.batch_id, Stock.brand_id, Stock.variant_id, Stock.model_id,
               func.sum(Stock.available_qty))
        .outerjoin(m.Batch, m.Batch.id == Stock.batch_id)
        .where(Stock.warehouse_id == issue.warehouse_id, Stock.item_id.in_(item_ids),
               or_(
                   func.coalesce(m.Batch.expiry_date, Stock.expiry_date).is_(None),
                   func.coalesce(m.Batch.expiry_date, Stock.expiry_date) >= today,
               ))
        .group_by(Stock.item_id, Stock.bin_id, Stock.batch_id, Stock.brand_id, Stock.variant_id, Stock.model_id)
    )).all():
        on_hand[(int(item_id), int(bin_id or 0), int(batch_id or 0),
                 *_combo3(c_brand, c_variant, c_model))] = _d(available)

    # What this document's own indent lines are already holding, and where. That hold
    # is stock this issue may draw on — an approved allocation reserves exactly what it
    # is about to issue, so counting only what is free would refuse every correct
    # indent-linked document.
    own: dict[tuple, Decimal] = {}
    allocated_batches: dict[tuple[int, int], set[int]] = {}
    pairs = {(line_indents[int(line.indent_item_id)], int(line.indent_item_id))
             for line in outward
             if line.indent_item_id and int(line.indent_item_id) in line_indents}
    if pairs:
        for (item_id, bin_id, batch_id, ref_id, ref_line_id, c_brand, c_variant, c_model,
             qty) in (await db.execute(
            select(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                   Reservation.ref_id, Reservation.ref_line_id, Stock.brand_id, Stock.variant_id, Stock.model_id,
                   func.sum(Reservation.quantity))
            .join(Stock, Stock.id == Reservation.stock_id)
            .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
                   Reservation.status == ReservationStatus.ACTIVE.value,
                   Reservation.warehouse_id == issue.warehouse_id,
                   Reservation.ref_id.in_({pair[0] for pair in pairs}),
                   Reservation.ref_line_id.in_({pair[1] for pair in pairs}))
            .group_by(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                      Reservation.ref_id, Reservation.ref_line_id, Stock.brand_id, Stock.variant_id, Stock.model_id)
        )).all():
            # The two `IN`s above are a cross product; only the pairs the document
            # actually carries count.
            if (int(ref_id), int(ref_line_id or 0)) not in pairs:
                continue
            slot = (int(item_id), int(bin_id or 0), int(batch_id or 0),
                    *_combo3(c_brand, c_variant, c_model))
            own[slot] = own.get(slot, ZERO) + _d(qty)
            if batch_id:
                allocated_batches.setdefault(
                    (int(ref_line_id or 0), int(item_id)), set()).add(int(batch_id))

    # What THIS document holds itself — a direct issue reserves its picks the moment
    # it is saved (`_hold_direct_issue_stock`), and an edit to the same picks must not
    # be refused for want of the stock it is already holding.
    if issue.id:
        for item_id, bin_id, batch_id, c_brand, c_variant, c_model, qty in (await db.execute(
            select(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                   Stock.brand_id, Stock.variant_id, Stock.model_id, func.sum(Reservation.quantity))
            .join(Stock, Stock.id == Reservation.stock_id)
            .where(Reservation.ref_type == InventoryRefType.ISSUE_HOLD.value,
                   Reservation.ref_id == issue.id,
                   Reservation.status == ReservationStatus.ACTIVE.value)
            .group_by(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                      Stock.brand_id, Stock.variant_id, Stock.model_id)
        )).all():
            slot = (int(item_id), int(bin_id or 0), int(batch_id or 0),
                    *_combo3(c_brand, c_variant, c_model))
            own[slot] = own.get(slot, ZERO) + _d(qty)

    # Lots held for this document's project are its own too (stk_project_holds).
    if issue.project_id:
        for item_id, bin_id, batch_id, c_brand, c_variant, c_model, qty in (await db.execute(
            select(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                   Stock.brand_id, Stock.variant_id, Stock.model_id, func.sum(Reservation.quantity))
            .join(Stock, Stock.id == Reservation.stock_id)
            .where(_own_hold_clause(None, issue.project_id),
                   Reservation.status == ReservationStatus.ACTIVE.value,
                   Reservation.warehouse_id == issue.warehouse_id,
                   Reservation.item_id.in_(item_ids))
            .group_by(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                      Stock.brand_id, Stock.variant_id, Stock.model_id)
        )).all():
            slot = (int(item_id), int(bin_id or 0), int(batch_id or 0),
                    *_combo3(c_brand, c_variant, c_model))
            own[slot] = own.get(slot, ZERO) + _d(qty)

    # Other indents' quantity holds here, less what their open issues have pinned.
    others: dict[tuple, Decimal] = {}
    _pins, pinned_slots = await _open_issue_pins(
        db, issue.warehouse_id, item_ids, exclude_issue_id=getattr(issue, "id", None))
    own_pairs = pairs or set()
    for (item_id, bin_id, batch_id, ref_id, ref_line_id, c_brand, c_variant, c_model,
         qty) in (await db.execute(
        select(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
               Reservation.ref_id, Reservation.ref_line_id, Stock.brand_id, Stock.variant_id, Stock.model_id,
               func.sum(Reservation.quantity))
        .join(Stock, Stock.id == Reservation.stock_id)
        .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
               Reservation.status == ReservationStatus.ACTIVE.value,
               Reservation.warehouse_id == issue.warehouse_id,
               Reservation.item_id.in_(item_ids))
        .group_by(Reservation.item_id, Reservation.bin_id, Reservation.batch_id,
                  Reservation.ref_id, Reservation.ref_line_id, Stock.brand_id, Stock.variant_id, Stock.model_id)
    )).all():
        if (int(ref_id), int(ref_line_id or 0)) in own_pairs:
            continue
        slot = (int(item_id), int(bin_id or 0), int(batch_id or 0),
                *_combo3(c_brand, c_variant, c_model))
        others[slot] = others.get(slot, ZERO) + _d(qty)
    for pin_slot, pinned in pinned_slots.items():
        for slot in [key for key in others if key[:3] == pin_slot]:
            used = min(others[slot], pinned)
            others[slot] -= used
            pinned -= used

    # The FEFO plan per item: every batch this document could draw from, grouped into
    # TIERS of the same expiry date (FEFO cannot tell same-day batches apart), earliest
    # first. Expired stock is not in it at all — it is never to be issued. An indent
    # line may also draw on other indents' floating holds (`others`); a manual line
    # only on free stock and its project's own lots.
    indent_items = {int(line.item_id) for line in outward if line.indent_item_id}
    # Per brand / variant / model too (2026-10-23): FEFO is asked within the
    # combination a line names — an older batch of ANOTHER brand is not one this line
    # could have taken first.
    drawable_by_batch: dict[tuple, Decimal] = defaultdict(Decimal)
    for source, indent_only in ((on_hand, False), (own, False), (others, True)):
        for (s_item, _s_bin, s_batch, *s_combo), qty in source.items():
            if s_batch and (not indent_only or s_item in indent_items):
                drawable_by_batch[(s_item, tuple(s_combo), s_batch)] += qty
    fefo_ids = {b for (_i, _c, b), q in drawable_by_batch.items() if q > ZERO}
    fefo_rows = {row.id: row for row in (await db.execute(
        select(m.Batch).where(m.Batch.id.in_(fefo_ids))
    )).scalars().all()} if fefo_ids else {}
    today = ist_today()

    def tiers_for(item: int, combo) -> dict[object, list[tuple[int, Decimal]]]:
        per_batch: dict[int, Decimal] = defaultdict(Decimal)
        for (s_item, s_combo, s_batch), qty in drawable_by_batch.items():
            if s_item == item and (combo is None or s_combo == combo):
                per_batch[s_batch] += qty
        tiers: dict[object, list[tuple[int, Decimal]]] = {}
        for s_batch, qty in per_batch.items():
            row = fefo_rows.get(s_batch)
            if qty <= ZERO or row is None:
                continue
            if row.expiry_date is not None and row.expiry_date < today:
                continue
            tiers.setdefault(row.expiry_date, []).append((s_batch, qty))
        return tiers

    # Every batch either named or allocated, read once: expiry is the whole of the
    # FEFO question.
    batch_ids = {int(line.batch_id) for line in outward if line.batch_id}
    for signed in allocated_batches.values():
        batch_ids |= signed
    batches: dict[int, m.Batch] = {}
    if batch_ids:
        batches = {row.id: row for row in (await db.execute(
            select(m.Batch).where(m.Batch.id.in_(batch_ids))
        )).scalars().all()}

    def named(batch_id: int) -> str:
        row = batches.get(batch_id)
        return row.batch_no if row is not None and row.batch_no else f"batch {batch_id}"

    taken: dict[tuple, Decimal] = {}
    for index, line in enumerate(outward, start=1):
        item_id = int(line.item_id)
        bin_id, batch_id = _line_slot(line)
        combo = combo_key(line)
        label = line.item_code or f"item {item_id}"

        # Reject an expired batch right away
        if batch_id:
            chosen = batches.get(batch_id)
            if chosen and chosen.expiry_date and chosen.expiry_date < today:
                raise ValidationError(
                    f"{label}: batch {named(batch_id)} expired on {chosen.expiry_date} "
                    f"and cannot be issued.")

        # --- and the stock itself ------------------------------------------------
        slot = (item_id, bin_id, batch_id, combo)
        want = taken.get(slot, ZERO) + _line_issued(line)
        # A line naming no location (a point that stocks in bulk) or no batch is asking
        # about everything under that heading, exactly as `_issue_unit_supply` and
        # `move_stock_out` read the same zeros.
        def under(source: dict[tuple[int, int, int], Decimal]) -> Decimal:
            return sum((qty for key, qty in source.items()
                        if key[0] == item_id
                        and (not bin_id or key[1] == bin_id)
                        and (not batch_id or key[2] == batch_id)
                        and (combo is None or tuple(key[3:]) == combo)), ZERO)

        mine = under(own)
        # Another indent's quantity hold on this row is drawable too: holds float
        # between batches and trade rows on save (`allocation.swap_holds`). What an
        # open issue of theirs has explicitly picked stays theirs.
        tradeable = under(others) if line.indent_item_id else ZERO
        drawable = under(on_hand) + mine + tradeable
        if want > drawable:
            where = []
            if batch_id:
                where.append(f"batch {named(batch_id)}")
            if bin_id:
                where.append(await _bin_code(db, bin_id) or f"location {bin_id}")
            place = " in ".join(where) if where else "this warehouse"
            if combo is not None:
                place = f"{line_combo_label(line)} in {place}"
            raise ValidationError(
                f"Line {index}: {label} takes {want} from {place}, which can give "
                f"{drawable}."
                + (f" {mine} of that is this indent's own reservation." if mine else "")
                + " Split the rest onto another location, or reduce the quantity."
            )
        taken[slot] = want

    # --- FEFO, strictly, per item over the whole document ------------------------
    # Only the batches the quantity actually needs, earliest expiry first, and an
    # earlier batch used up before a later one is touched (2026-10-12). Damaged or
    # unusable stock is the stock audit's business, never the issue's — so there is
    # no "later batch with a reason". Same-day batches form one tier and may be mixed.
    by_item_batch: dict[tuple, dict[int, Decimal]] = defaultdict(lambda: defaultdict(Decimal))
    for (t_item, _t_bin, t_batch, t_combo), qty in taken.items():
        if t_batch:
            by_item_batch[(t_item, t_combo)][t_batch] += qty
    for (t_item, t_combo), takes in by_item_batch.items():
        label = next((line.item_code for line in outward
                      if int(line.item_id) == t_item and line.item_code), f"item {t_item}")
        tiers = sorted(tiers_for(t_item, t_combo).items(),
                       key=lambda kv: (kv[0] is None, kv[0] or date.max))
        known = {b for _e, members in tiers for b, _q in members}
        stray = [b for b in takes if b not in known]
        if stray:
            raise ValidationError(
                f"{label}: {named(stray[0])} has nothing this issue may take — it is "
                "expired, empty, or held by another document. Pick from the batches "
                "offered, earliest expiry first.")
        remaining = sum(takes.values(), ZERO)
        short_tier = None
        for expiry, members in tiers:
            if remaining <= ZERO:
                break
            tier_draw = sum((q for _b, q in members), ZERO)
            tier_take = sum((takes.get(b, ZERO) for b, _q in members), ZERO)
            expect = min(tier_draw, remaining)
            if short_tier is not None and tier_take > ZERO:
                first_expiry, first_members, first_expect, first_take = short_tier
                names = ", ".join(named(b) for b, _q in first_members)
                raise ValidationError(
                    f"{label}: take {first_expect:g} from {names} "
                    f"({_fefo_expiry_date(first_expiry)}) before "
                    f"{', '.join(named(b) for b, _q in members if takes.get(b))} "
                    f"({_fefo_expiry_date(expiry)}) — this issue takes only "
                    f"{first_take:g} there. Stock leaves earliest-expiry first.")
            if tier_take < expect and short_tier is None:
                short_tier = (expiry, members, expect, tier_take)
            remaining -= tier_take


async def _held_combinations(db: AsyncSession, indent_item_ids) -> dict[int, set]:
    """Per indent line, the brand / variant / model its reservations stand on —
    active or already consumed — read off the stock rows they sit on."""
    from app.modules.inventory.models import Reservation, Stock
    ids = {int(i) for i in indent_item_ids if i}
    out: dict[int, set] = {}
    if not ids:
        return out
    for line_id, b, v, m_ in (await db.execute(
            select(Reservation.ref_line_id, Stock.brand_id, Stock.variant_id, Stock.model_id)
            .join(Stock, Stock.id == Reservation.stock_id)
            .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
                   Reservation.ref_line_id.in_(ids),
                   Reservation.status.in_((ReservationStatus.ACTIVE.value,
                                           ReservationStatus.CONSUMED.value)))
            .distinct())).all():
        out.setdefault(int(line_id), set()).add(_combo3(b, v, m_))
    return out


async def _issue_line_combinations(db: AsyncSession,
                                   lines: list[s.IssueItemWrite]) -> list[dict]:
    """Which brand / variant / model each issue line takes (2026-10-23).

    A line serving an indent line that named one takes exactly that — the
    storekeeper cannot change it. Otherwise (an indent line that said Any, or a
    direct issue) the storekeeper's pick off the shelf, checked against the item's
    ON combinations; with none picked the line names none and draws any.
    The pick is written back onto the line, so every check after this reads it.
    """
    from app.modules.indents.models import IndentItem
    ids = {int(line.indent_item_id) for line in lines if line.indent_item_id}
    asked = {row.id: row for row in (await db.execute(
        select(IndentItem).where(IndentItem.id.in_(ids)))).scalars().all()} if ids else {}
    held = await _held_combinations(db, ids)
    out = []
    for index, line in enumerate(lines, start=1):
        source = asked.get(int(line.indent_item_id or 0))
        named = (int(getattr(line, "brand_id", 0) or 0), int(getattr(line, "variant_id", 0) or 0),
                 int(getattr(line, "model_id", 0) or 0))
        holds = held.get(int(line.indent_item_id or 0), set())
        asked3 = (_combo3(source.brand_id, source.variant_id, source.model_id)
                  if source is not None else None)
        if source is not None and source.brand_id and named[0] and named in holds:
            # The allocation gave ANOTHER brand than the indent named (a recorded
            # substitution, 2026-10-24): the issue takes what was reserved.
            combo = await combinations.resolve(db, line.item_id, line, label=f"Line {index}")
        elif (source is not None and source.brand_id and len(holds) == 1
                and asked3 not in holds):
            # Everything held for the line is ONE other combination — a substitution
            # the desk recorded, possibly onto stock with no brand: issue that.
            only = next(iter(holds))
            combo = (dict(combinations.NONE) if not only[0] else await combinations.resolve(
                db, line.item_id, {"brand_id": only[0], "variant_id": only[1],
                                   "model_id": only[2]}, label=f"Line {index}"))
        elif source is not None and source.brand_id:
            combo = combinations.carry(source)
        elif getattr(line, "brand_id", None):
            combo = await combinations.resolve(
                db, line.item_id, line, label=f"Line {index}")
        else:
            combo = {**combinations.NONE,
                     "combination_any": bool(source is not None and source.combination_any)}
        for key in ("brand_id", "variant_id", "model_id", "brand_name", "variant_name",
                    "model_name"):
            setattr(line, key, combo[key])
        out.append(combo)
    return out


async def _apply_issue_lines(db: AsyncSession, issue: m.MaterialIssue,
                             lines: list[s.IssueItemWrite]) -> None:
    issue.items.clear()
    await db.flush()
    line_combos = await _issue_line_combinations(db, lines)

    # Every location named on the document, checked once for the whole document.
    #
    # The line's `bin_id` used to be written through unread — any integer at all became
    # a location, including one belonging to another warehouse or one that had been
    # deactivated, and the mistake only surfaced at posting when `stk_balance` had no
    # such row. It is checked here instead, and checked as a LOCATION rather than as a
    # bin: stock is allowed to sit on a lane, a rack or a whole floor (see
    # `confirm_putaway`), so demanding a BIN rung would refuse exactly the documents
    # that placement change exists to allow.
    named = {int(line.bin_id) for line in lines if line.bin_id}
    known: dict[int, Bin] = {}
    if named:
        known = {row.id: row for row in (await db.execute(
            select(Bin).where(Bin.id.in_(named))
        )).scalars().all()}
    for bin_id in sorted(named):
        location = known.get(bin_id)
        if location is None:
            raise ValidationError(f"Storage location {bin_id} does not exist")
        if location.warehouse_id != issue.warehouse_id:
            raise ValidationError(
                f"{location.code} is not in {issue.warehouse_name or 'this warehouse'}")
        if not location.is_active:
            raise ValidationError(
                f"{location.code} is inactive and cannot be issued from")

    # A line stated in packs ("2 Box + 5 Strip") issues exactly that many units; the
    # server works the quantity out before anything below reads it (2026-10-08).
    line_packs = []
    for line in lines:
        hid, entries, base = await wh_packing.issue_line_packing(
            db, item=await _item_snapshot(db, line.item_id), line_in=line)
        if base is not None:
            line.issued_qty = base
        line_packs.append((hid, entries))

    # Does the shelf actually hold what every pick claims, and is a swapped batch one
    # FEFO cannot tell apart from the one that was allocated? Both refused here, on
    # the draft, while the batch and the location are still the storekeeper's to
    # change — after approval they are frozen. See `_assert_issue_sources`.
    await _assert_issue_sources(db, issue, lines)

    # How finely each line's unit divides — the rule indents and approvals already
    # apply (`shared/uom`). Nobody hands over 9.5 Nos; the issue form accepted it and
    # the half unit then stranded the line at Outward QC, whose serial check can never
    # account for it.
    item_ids = {line.item_id for line in lines if line.item_id}
    uom_codes = dict((await db.execute(
        select(Item.id, Item.uom_code).where(Item.id.in_(item_ids))
    )).all()) if item_ids else {}
    decimals = await uom_rules.decimals_by_code(db, uom_codes.values())

    for index, line in enumerate(lines, start=1):
        item = await _item_snapshot(db, line.item_id)
        requested = _d(line.requested_qty)
        if requested <= ZERO:
            raise ValidationError(f"Line {index}: requested quantity must be positive")
        issued = requested if line.issued_qty is None else _d(line.issued_qty)
        if issued > requested:
            raise ValidationError(
                f"Line {index}: cannot issue {issued} against a request for {requested}")
        if decimals.get(item.uom_code, uom_rules.MAX_DECIMALS) == 0:
            # Name whichever figure is actually fractional — not always `issued`.
            # A request of 10.05 issued as 10 used to be refused with "10 is not
            # a whole number", which sends a storekeeper hunting for a fraction
            # in the number that is already whole (SCM_0080/SCM_0083).
            bad_field, bad_value = (
                ("requested", requested) if requested != requested.to_integral_value()
                else ("issued", issued) if issued != issued.to_integral_value()
                else (None, None)
            )
            if bad_field:
                raise ValidationError(
                    f"Line {index}: {item.code} is counted in {item.uom_code} — "
                    f"the {bad_field} quantity {bad_value} is not a whole number. "
                    f"Issue whole units only.")

        batch = await db.get(m.Batch, line.batch_id) if line.batch_id else None
        rate = _d(line.rate)
        if rate < ZERO:
            # WHI/2026-27/00030 carries rates of -1323, -233 and -4343, which is how
            # a material issue came to be worth ₹ -62,617. Goods leaving a store have
            # a cost or they have none; they never have a negative one.
            raise ValidationError(f"Line {index}: rate cannot be negative")
        if rate <= ZERO:
            # A drafted line carries no rate — the allocation and the picklist both
            # name goods, never a cost — so every automatic issue was worth ₹ 0. The
            # cost is already recorded: the batch was received at one, and the item
            # keeps the last purchase price as the valuation fallback (masters). Read
            # it here, once, so every creation path is costed the same way. Still
            # editable, and still ₹ 0 when nothing knows the cost.
            rate = _d(batch.rate if batch and batch.rate else None) or _d(
                getattr(item, "purchase_price", None))
        issue.items.append(m.MaterialIssueLine(
            line_no=index, indent_item_id=line.indent_item_id,
            item_id=item.id, item_code=item.code, item_name=item.name, uom_code=item.uom_code,
            # 0, not NULL. The live out_issue_items has bin_id and batch_id NOT NULL
            # DEFAULT 0 — the module's own NO_BIN/NO_BATCH convention — while the ORM
            # calls them nullable. Passing the NULL through failed the insert outright,
            # so an indent-linked issue (where bin and batch come from the reservation,
            # not from the line) could not be created at all.
            bin_id=line.bin_id or m.NO_BIN, bin_code=await _bin_code(db, line.bin_id),
            batch_id=line.batch_id or m.NO_BATCH,
            batch_no=batch.batch_no if batch else None,
            mfg_date=batch.mfg_date if batch else None,
            expiry_date=batch.expiry_date if batch else None,
            requested_qty=requested, issued_qty=issued, returned_qty=ZERO,
            rate=rate or None, amount=(issued * rate) if rate else None,
            remarks=line.remarks,
            pack_hierarchy_id=line_packs[index - 1][0],
            pack_breakdown=line_packs[index - 1][1],
            break_bulk=bool(getattr(line, "break_bulk", False)),
            **line_combos[index - 1],
        ))
    _issue_totals(issue)
    # Flushed so every line has an id before `_reserve_issue_serials` stamps units
    # with it — a reservation is per LINE now, and a line with no id yet would fall
    # back to the document-level stamp this change exists to retire.
    await db.flush()


async def list_issues(db: AsyncSession, params: PageParams, *, direction: str | None = None,
                      status: str | None = None, warehouse_id: int | None = None,
                      search: str | None = None, user=None) -> dict:
    stmt = select(m.MaterialIssue)
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.MaterialIssue.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.MaterialIssue.created_by_id,
            project_col=m.MaterialIssue.project_id,
        ))
        # A floor in-charge is given the pieces of work addressed to their floors and
        # nothing else — not the generic parents, which belong to the warehouse
        # manager and would only be documents they cannot act on. Everybody else is
        # unrestricted (`floor_scope_ids` answers None), so the manager still sees the
        # parents, the children and the unsplit issues together.
        floors = await floor_scope_ids(db, user)
        if floors is not None:
            stmt = stmt.where(m.MaterialIssue.floor_location_id.in_(floors)
                              if floors else false())
    if direction:
        stmt = stmt.where(m.MaterialIssue.direction == direction)
    if status:
        stmt = stmt.where(m.MaterialIssue.status == status)
    if warehouse_id:
        stmt = stmt.where(m.MaterialIssue.warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.MaterialIssue.issue_no.ilike(like), m.MaterialIssue.indent_no.ilike(like),
            m.MaterialIssue.issued_to_name.ilike(like), m.MaterialIssue.department_name.ilike(like)))
    page = await paginate(db, stmt.order_by(m.MaterialIssue.id.desc()), params)
    holders = await _issue_holders_bulk(db, list(page["items"]))
    for row in page["items"]:
        setattr(row, "currently_with", _currently_with(row, holders.get(row.id)))
    await _decorate_indent_types(db, list(page["items"]))
    return page


async def _decorate_indent_types(db: AsyncSession, issues: list) -> None:
    """Stamp `indent_type` so a screen can say "STR" rather than "Indent" for an issue
    serving a stock transfer request. One query for the page."""
    from app.modules.indents.models import Indent
    ids = {i.indent_id for i in issues if i.indent_id}
    types = dict((await db.execute(
        select(Indent.id, Indent.indent_type).where(Indent.id.in_(ids))
    )).all()) if ids else {}
    for issue in issues:
        setattr(issue, "indent_type", types.get(issue.indent_id))
    # The Stock Transfer Order each issue executes (2026-10-29): a direct STO names it
    # on `inv_sto.issue_id`, and so does the order an STR's allocation produced. The
    # screen shows the number and freezes the destination on it.
    from app.modules.inventory.models import STO_KIND_TRANSFER, StockTransferOrder
    issue_ids = {i.id for i in issues if getattr(i, "id", None)}
    orders = {row.issue_id: row for row in (await db.execute(
        select(StockTransferOrder.id, StockTransferOrder.sto_no, StockTransferOrder.status,
               StockTransferOrder.issue_id, StockTransferOrder.str_id,
               StockTransferOrder.str_no,
               StockTransferOrder.from_warehouse_name,
               StockTransferOrder.to_warehouse_id, StockTransferOrder.to_warehouse_name)
        .where(StockTransferOrder.issue_id.in_(issue_ids),
               StockTransferOrder.doc_kind == STO_KIND_TRANSFER)
    )).all()} if issue_ids else {}
    for issue in issues:
        order = orders.get(issue.id)
        setattr(issue, "sto_id", order.id if order else None)
        setattr(issue, "sto_no", order.sto_no if order else None)
        setattr(issue, "sto_status", order.status if order else None)
        setattr(issue, "sto_kind", None if order is None else ("STR" if order.str_id else "DIRECT"))
        setattr(issue, "sto_str_no", order.str_no if order else None)
        setattr(issue, "sto_from_warehouse_name", order.from_warehouse_name if order else None)
        setattr(issue, "sto_to_warehouse_id", order.to_warehouse_id if order else None)
        setattr(issue, "sto_to_warehouse_name", order.to_warehouse_name if order else None)


async def _decorate_can_approve(db: AsyncSession, doc, doc_type: str, user):
    """Set `can_approve` — is this document waiting on THIS person right now?

    The engine already owns the answer (`wf_pending`), but nothing exposed it, so the
    screens fell back to gating the Approve button on the permission alone. Every
    warehouse post shares one HCM rank, so all eleven holders saw Approve on a document
    only one of them could act on, and the other ten got "You are not a valid approver"
    after clicking. Hiding the button is not the security — `engine.act` still decides —
    it is simply telling the truth about whose turn it is.

    `user` is optional because get_issue() is also called from create_consignment() and
    other server-side paths where there is no one to answer this for; those get False.
    """
    can = False
    if user is not None:
        approvers = await engine.current_approvers(db, doc_type, doc.id)
        can = any(approver.id == user.id for approver in approvers)
    setattr(doc, "can_approve", can)
    return doc


async def get_issue(db: AsyncSession, issue_id: int, user=None) -> m.MaterialIssue:
    issue = await _load(db, m.MaterialIssue, issue_id, "Issue", m.MaterialIssue.items)
    issue = await _decorate_issue_serials(db, issue)
    # How many decimals each line's unit allows, served onto the line so the form
    # can refuse a typed fraction for a whole-unit item (NOS, Box…) before save,
    # the same rule `_apply_issue_lines` enforces on the server (SCM_0080).
    line_decimals = await uom_rules.decimals_by_code(
        db, {it.uom_code for it in issue.items})
    for it in issue.items:
        setattr(it, "qty_decimals", line_decimals.get(it.uom_code, uom_rules.MAX_DECIMALS))
    # The doc type the issue actually runs under, not a hardcoded WH_ISSUE: one that
    # left a point the submitter holds runs under OWN_STOCK_ISSUE, and asking the
    # engine for the wrong type finds no instance, returns no approvers, and hides the
    # Approve button from the very person it is waiting on.
    issue = await _decorate_can_approve(
        db, issue, await _issue_doc_type_of(db, issue.id), user)
    holders = (await _issue_holders_bulk(db, [issue])).get(issue.id, [])
    setattr(issue, "currently_with", _currently_with(issue, holders))
    # Who SUBMITTED it — the person who initiated it, which is not `created_by` when
    # an approved allocation drafted the document under the approver's name.
    setattr(issue, "submitted_by_name", (await db.execute(
        select(WfInstance.started_by_name)
        .where(WfInstance.doc_id == issue.id, WfInstance.doc_type.in_(ISSUE_DOC_TYPES))
        .order_by(WfInstance.id.desc()).limit(1)
    )).scalar_one_or_none())
    # The holder (or their reporting line), and anyone who APPROVED it — see
    # `_assert_issue_holder`, which the press itself goes through.
    setattr(issue, "can_issue_from_stock",
            issue.status == IssueStatus.APPROVED.value and not issue.is_stock_posted
            and user is not None
            and (await _may_act_as_issue_holder(db, user, holders)
                 or await _issue_approved_by(db, issue.id, user)))
    setattr(issue, "can_swap_codes", issue.can_issue_from_stock)
    setattr(issue, "can_acknowledge", await _receiver_confirmed(db, issue))
    setattr(issue, "is_stock_transfer", await is_stock_transfer_issue(db, issue.id))
    if issue.floor_location_id:
        setattr(issue, "floor_in_charge_names",
                (await stock_locations.floor_incharge_names(
                    db, {issue.floor_location_id})).get(issue.floor_location_id, []))
    # The split FAMILY, from either end: on a parent its floor issues, on a floor issue
    # its siblings (itself included), so a storekeeper holding -002 can see what -001
    # and -003 are doing without going back up to the parent.
    family = (await db.execute(
        select(m.MaterialIssue.id, m.MaterialIssue.issue_no, m.MaterialIssue.status,
               m.MaterialIssue.floor_location_id, m.MaterialIssue.floor_location_name,
               m.MaterialIssue.is_stock_posted, m.MaterialIssue.total_qty,
               m.MaterialIssue.total_items)
        .where(m.MaterialIssue.parent_issue_id == (issue.parent_issue_id or issue.id))
        .order_by(m.MaterialIssue.id)
    )).all()
    in_charge = await stock_locations.floor_incharge_names(
        db, {row.floor_location_id for row in family if row.floor_location_id})         if family else {}
    setattr(issue, "child_issues", [
        {**dict(row._mapping),
         "in_charge_names": in_charge.get(row.floor_location_id, [])}
        for row in family])
    await _decorate_indent_types(db, [issue])
    return await _decorate_issue_destination(db, issue)


async def is_stock_transfer_issue(db: AsyncSession, issue_id: int | None) -> bool:
    """Does this issue execute a stock transfer (an STO, or an STR it serves)? The
    screens use it to work the issue's QC on Inventory > Stock Transfer."""
    if not issue_id:
        return False
    return bool(await db.scalar(
        select(func.count()).select_from(
            _stock_transfer_issue_ids().where(m.MaterialIssue.id == issue_id).subquery())))


#: An issue whose goods actually went OUT to the requester.
#:
#: FIXED 2026-08-23. Both running totals below used to count any issue that was
#: `is_stock_posted`, which only says the stock came OFF THE SHELF — not that it ever
#: reached anybody. Issues were assumed to be delivered in creation order, and they are
#: not: a storekeeper commonly raises one issue, leaves it sitting, then raises and
#: hand-delivers a second.
#:
#: That is exactly what happened on IND0011. WHI0008 (10 units) was raised first and
#: never dispatched; WHI0009 (5 units) was raised second and hand-delivered. Confirming
#: those 5 computed `5 confirmed - 10 already delivered = -5`, clamped to zero, so the
#: cap came out empty, `credit_arrival` was never reached, and 15 units sat on the
#: ledger as OUT with no matching IN anywhere. The stock existed on no shelf.
#:
#: ISSUED is deliberately NOT here: it means picked and posted, still in the warehouse.
#: The rungs below are the ones that say it left — and a return only happens to
#: something that arrived, so both return states count too.
_GONE_OUT_STATUSES = (
    IssueStatus.DISPATCHED.value,
    IssueStatus.ACKNOWLEDGED.value,
    IssueStatus.PARTIALLY_RETURNED.value,
    IssueStatus.RETURNED.value,
)


async def _receiver_confirmed(db: AsyncSession, issue: m.MaterialIssue) -> bool:
    """Has the indent raiser said this issue's goods reached them?

    Acknowledging is the shipping side signing that a delivery landed, and it used to
    open the moment stock was posted — so the store that sent the goods could close the
    loop on itself, with the requester never asked. Only the raiser can say they
    arrived (`indents.acknowledge_receipt` writes `received_qty` and nothing else does).

    Measured per ISSUE, not per indent. A 10-unit indent served by a 4-unit issue is
    settled for THAT issue once those 4 are confirmed; the other 6 stay pending against
    whatever issue carries them later. So the test is a running total: everything
    delivered on this line up to and including this issue must be covered by what the
    raiser has confirmed on it.

    Lines with no `indent_item_id` are stock leaving against no request — nobody is
    waiting to confirm them, so they never hold the document up.
    """
    lines = [line for line in issue.items if line.indent_item_id]
    if not lines:
        return True

    from app.modules.indents.models import IndentItem

    confirmed = dict((await db.execute(
        select(IndentItem.id, IndentItem.received_quantity)
        .where(IndentItem.id.in_([line.indent_item_id for line in lines]))
    )).all())

    # Everything the same line already had on the road before this document. Relay legs
    # are excluded exactly as Acknowledgements excludes them (_relayed_onward): the raiser
    # never sees the WH -> MDP hop, so counting it would demand a confirmation nobody
    # can give.
    delivered = dict((await db.execute(
        select(m.MaterialIssueLine.indent_item_id,
               func.sum(m.MaterialIssueLine.issued_qty
                        - func.coalesce(m.MaterialIssueLine.returned_qty, 0)))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .where(m.MaterialIssueLine.indent_item_id.in_(
                   [line.indent_item_id for line in lines]),
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(True),
               # This issue always counts — it is the one being tested. An EARLIER one
               # counts only if it actually went out; see `_GONE_OUT_STATUSES`. Written
               # as an OR rather than a status filter over the whole set because
               # excluding the subject itself would make an undelivered issue trivially
               # "confirmed" and acknowledge it on the spot.
               or_(m.MaterialIssue.id == issue.id,
                   and_(m.MaterialIssue.id < issue.id,
                        m.MaterialIssue.status.in_(_GONE_OUT_STATUSES))),
               ~_relayed_onward())
        .group_by(m.MaterialIssueLine.indent_item_id)
    )).all())

    return all(
        _d(confirmed.get(line.indent_item_id)) >= _d(delivered.get(line.indent_item_id))
        for line in lines
    )


async def _dispatch_confirmation_caps(db: AsyncSession,
                                      issue_ids: list[int]) -> dict[int, Decimal]:
    """`_issue_confirmation_caps` summed over every issue a grouped consignment carries."""
    total: dict[int, Decimal] = defaultdict(lambda: ZERO)
    issues = (await db.execute(
        select(m.MaterialIssue).options(selectinload(m.MaterialIssue.items))
        .where(m.MaterialIssue.id.in_(issue_ids))
    )).scalars().all()
    for row in issues:
        for item_id, qty in (await _issue_confirmation_caps(db, row)).items():
            total[item_id] += _d(qty)
    return dict(total)


async def _issue_confirmation_caps(db: AsyncSession, issue: m.MaterialIssue) -> dict[int, Decimal]:
    """How much of THIS issue's quantities the requester has confirmed, per item.

    `_receiver_confirmed` answers yes/no — settle or wait — and a partial receipt
    failed it, which is why the six of ten units physically in the requester's hands
    sat on no shelf until the last four arrived. This returns the numbers instead:
    per line, what has been confirmed beyond everything EARLIER issues already
    carried (the same cumulative arithmetic `_receiver_confirmed` runs, with `<`
    instead of `<=`), clamped to this issue's own issued quantity, grouped by item
    so `credit_arrival` can cap a partial credit by it.
    """
    lines = [line for line in issue.items if line.indent_item_id]
    if not lines:
        return {}

    # An issue that has not gone out yet credits NOTHING, however much the requester
    # has confirmed. Without this the running total stops partitioning: excluding
    # undelivered issues from `delivered_before` (below) means an undelivered one no
    # longer subtracts from a later delivered one, so BOTH would claim the same
    # confirmed units and the arrival would be credited twice. An issue still sitting
    # in the warehouse has delivered nothing, so zero is also simply the true answer.
    if issue.status not in _GONE_OUT_STATUSES:
        return {}

    from app.modules.indents.models import IndentItem

    confirmed = dict((await db.execute(
        select(IndentItem.id, IndentItem.received_quantity)
        .where(IndentItem.id.in_([line.indent_item_id for line in lines]))
    )).all())

    delivered_before = dict((await db.execute(
        select(m.MaterialIssueLine.indent_item_id,
               func.sum(m.MaterialIssueLine.issued_qty
                        - func.coalesce(m.MaterialIssueLine.returned_qty, 0)))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .where(m.MaterialIssueLine.indent_item_id.in_(
                   [line.indent_item_id for line in lines]),
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(True),
               # Only what actually LEFT counts against this issue's share of the
               # confirmation — see `_GONE_OUT_STATUSES`.
               m.MaterialIssue.id < issue.id,
               m.MaterialIssue.status.in_(_GONE_OUT_STATUSES),
               ~_relayed_onward())
        .group_by(m.MaterialIssueLine.indent_item_id)
    )).all())

    caps: dict[int, Decimal] = {}
    for line in lines:
        mine = (_d(confirmed.get(line.indent_item_id))
                - _d(delivered_before.get(line.indent_item_id)))
        mine = max(ZERO, min(mine,
                             _d(line.issued_qty) - _d(line.returned_qty or ZERO)))
        if mine > ZERO:
            caps[line.item_id] = caps.get(line.item_id, ZERO) + mine
    return caps


async def _office_sac(db: AsyncSession, office_id: int | None) -> str | None:
    """The service area code of one office, read live from the HCM mirror.

    Not snapshotted onto the document, for the same reason the indent does not
    snapshot it (`indents.service._attach_office_sac`): no column holds it, and
    reading it at serve time means every issue and consignment already in the table
    shows one instead of only those raised from now on. It is a label on the office,
    so the current value is the right one. `mappers.office_sac` owns the HCM field
    name (rule 10) — nothing here knows what key it sits under.

    `db.get` goes through the session identity map, so a page of documents heading to
    the same office costs one query, not one per row.
    """
    from app.platform.hcm import mappers
    from app.platform.hcm.models import HcmOffice

    if not office_id:
        return None
    office = await db.get(HcmOffice, office_id)
    return mappers.office_sac(office.raw) if office else None


async def _decorate_issue_destination(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> m.MaterialIssue:
    office_id, office_name = await _issue_destination(db, issue)
    setattr(issue, "destination_office_id", office_id)
    setattr(issue, "destination_office_name", office_name)
    setattr(issue, "destination_office_sac", await _office_sac(db, office_id))
    chosen = getattr(issue, "destination_warehouse_id", None)
    point = await db.get(Warehouse, chosen) if chosen else None
    setattr(issue, "destination_warehouse_type", point.warehouse_type if point else None)
    return issue


_VEHICLE_IN_NAME = re.compile(r"([A-Z]{2}\d{1,2}[A-Z]{1,3}\d{3,4})$")


def _vehicle_from_office_name(office_name: str | None) -> str | None:
    """The registration number an MMU office carries in its own name.

    An indent can name a vehicle, but no live indent does and `trn_vehicles` is empty
    — the register was never populated, so there is nothing to look up. The number is
    recorded anyway: 2660 of 3282 offices are named for the vehicle that serves them
    (`AP-104-MMU-Guraja Phc-AP39TL9202`). Read the trailing token so the issue opens
    with the vehicle already filled. A prefill only — it is typed over freely, and a
    cleared box stays cleared.
    """
    if not office_name:
        return None
    tail = office_name.replace(" ", "").upper().split("-")[-1]
    found = _VEHICLE_IN_NAME.search(tail)
    return found.group(1) if found else None


def _consignment_vehicle(issue, destination_office_name: str | None) -> str | None:
    """The registration number a consignment travels on.

    Derived, never picked: `trn_vehicles` is empty, so the Vehicle box on the
    consignment form was a lookup with nothing in it. The number is already recorded
    twice over — the material issue carries whatever the store typed, and an MMU
    office is named for the vehicle that serves it (`AP-104-MMU-Badangi-AP39UH4792`),
    which is the same string the delivery address is filled from. Read it here so the
    consignment shows the vehicle the goods are actually going out on.
    """
    return (
        getattr(issue, "vehicle_number", None)
        or _vehicle_from_office_name(destination_office_name)
    )


def _address_without_vehicle(office_name: str | None) -> str | None:
    """An MMU office's name with the registration number it ends in taken off.

    The name doubles as the delivery address (`AP-104-MMU-Badangi-AP39UH4792`), so
    the address carried the vehicle number too — printed twice on every consignment
    now that the Vehicle box shows it. The number is on the document in its own
    column; the address is where the goods go.
    """
    if not office_name or not _vehicle_from_office_name(office_name):
        return office_name
    head, _, _tail = office_name.rpartition("-")
    return head.strip(" -") or office_name


async def _issue_destination(
    db: AsyncSession,
    issue: m.MaterialIssue | None,
) -> tuple[int | None, str | None]:
    """Where an issue is headed: the office it is going to, id and name.

    `issued_to_id` is the direct answer but it is empty on most live issues — an
    allocation-approval draft names a warehouse and an indent, not a person. Falling
    back to the INDENT's own office is the same answer arrived at the other way: the
    goods are for whoever raised the request. Without the fallback the consignment
    screen showed "Destination —" and left the delivery address blank on every issue
    the allocation created.
    """
    from app.platform.hcm.models import HcmEmployee
    from app.modules.indents.models import Indent

    if not issue:
        return None, None
    # A point the store CHOSE wins over anything derived. A main warehouse may stand
    # on no HCM office; it is still where the goods go, so its own name answers.
    chosen = getattr(issue, "destination_warehouse_id", None)
    if chosen:
        point = await db.get(Warehouse, chosen)
        if point is not None:
            return point.office_id, point.office_name or point.name
    if issue.issued_to_id:
        employee = await db.get(HcmEmployee, issue.issued_to_id)
        if employee is not None and employee.office_id:
            return employee.office_id, employee.office_name
    if issue.indent_id:
        indent = await db.get(Indent, issue.indent_id)
        if indent is not None and getattr(indent, "office_id", None):
            return indent.office_id, indent.office_name
    # An issue executing a directly raised STO: the order names the point it is for.
    if issue.id:
        from app.modules.inventory.models import StockTransferOrder
        from app.platform.hcm.models import HcmOffice

        to_warehouse_id = await db.scalar(
            select(StockTransferOrder.to_warehouse_id)
            # A floor piece of a split names its parent, which is what the STO
            # points at (SCM_0012) — looked up by its own id it found nothing.
            .where(StockTransferOrder.issue_id == (issue.parent_issue_id or issue.id))
            .limit(1))
        point = await db.get(Warehouse, to_warehouse_id) if to_warehouse_id else None
        if point is not None and point.office_id:
            return point.office_id, await db.scalar(
                select(HcmOffice.name).where(HcmOffice.id == point.office_id))
    return None, None


async def _destination_warehouse(
    db: AsyncSession,
    issue: m.MaterialIssue,
    origin_warehouse_id: int,
) -> Warehouse | None:
    """The stocking point a consignment is addressed to, derived from its issue.

    `to_warehouse_id` is the ONLY thing `incoming_dispatch_options` matches on, and
    nothing ever derived it — it was hand-typed, on a field the form labels "for
    transfer only". Half the live consignments went out with it blank, and not one of
    those could be inwarded: the goods arrived, and the receiving point had no
    consignment to raise a GRN against. It struck WH -> LIP direct exactly as hard as
    the MDP relay; the four that worked worked because somebody happened to fill it.

    Where the goods are going is already recorded twice over, so it never had to be
    asked: the issue names the person it is for, and the indent names the office that
    raised it. Either resolves to the one active stocking point serving that office.

    An explicit choice always wins — this only fills a blank. Origin and destination
    being the same point is not a delivery, and `create_dispatch` rejects it, so that
    case stays blank rather than writing a row its own guard would refuse.
    """
    warehouse = await _requesting_point(db, issue)
    if warehouse is None or warehouse.id == origin_warehouse_id:
        return None
    return warehouse


async def _requesting_point(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> Warehouse | None:
    """The stocking point serving the office this issue is for — origin or not.

    `_destination_warehouse` drops the case where that point IS the origin, because a
    consignment cannot be addressed to the point it leaves. The screens still need to
    know which point it was, so they can say WHY the destination came back blank
    instead of showing an empty box nobody can explain.
    """
    chosen = getattr(issue, "destination_warehouse_id", None)
    if chosen:
        point = await db.get(Warehouse, chosen)
        if point is not None:
            return point
    office_id, _ = await _issue_destination(db, issue)
    if office_id is None:
        return None
    return (await db.execute(
        select(Warehouse)
        .where(Warehouse.office_id == office_id, Warehouse.is_active.is_(True))
        .order_by(Warehouse.id)
        .limit(1)
    )).scalar_one_or_none()


async def _is_final_delivery_leg(
    db: AsyncSession,
    issue: m.MaterialIssue,
    dispatch: m.Dispatch,
) -> bool:
    """Did this consignment land where the request was raised, or is it a relay hop?

    WH -> LIP direct is one leg and the acknowledgement at the far end IS the delivery.
    WH -> MDP -> LIP is two, and the signature at the MDP is only "the lorry got here":
    the goods are on the MDP's shelf, the requester has not seen them, and the indent
    is still owed. Treating both the same closed the indent the moment the MDP signed —
    the raiser's request read as fulfilled with nothing in his hands and no way to say
    otherwise.

    Blank destination (a customer or vendor dispatch) and an unresolvable requesting
    point both answer True, which is exactly what this code did before the distinction
    existed. Only the relay case changes.
    """
    if not dispatch.to_warehouse_id:
        return True
    point = await _requesting_point(db, issue)
    return point is None or point.id == dispatch.to_warehouse_id


async def _decorate_dispatch_destination(
    db: AsyncSession,
    dispatch: m.Dispatch,
) -> m.Dispatch:
    # Every issue on a grouped consignment is bound for the same point
    # (`_consignment_destination`), so the first one answers for all of them.
    issue_ids = await _dispatch_issue_ids(db, dispatch)
    issue = await db.get(m.MaterialIssue, issue_ids[0]) if issue_ids else None
    office_id, office_name = await _issue_destination(db, issue)
    setattr(dispatch, "destination_office_id", office_id)
    setattr(dispatch, "destination_office_name", office_name)
    setattr(dispatch, "destination_office_sac", await _office_sac(db, office_id))
    return dispatch


async def _decorate_dispatch_page_destinations(db: AsyncSession, page: dict) -> dict:
    for dispatch in page.get("items", []):
        await _decorate_dispatch_destination(db, dispatch)
    return page


def _fill_from_indent(data: s.IssueWrite, indent) -> s.IssueWrite:
    """An issue against an indent IS indent-based, and takes the indent's project and
    department where the caller left them blank. Every door that builds an issue —
    the form, the allocation drafts, forwarding, STR — passes through here, so none of
    them can save "Direct" with an empty project for an indent's goods again."""
    if indent is None:
        return data
    return data.model_copy(update={
        "issue_type": IssueType.INDENT_BASED,
        "department_id": data.department_id or getattr(indent, "department_id", None),
        "project_id": data.project_id or getattr(indent, "project_id", None),
    })


async def _fill_from_employee(db: AsyncSession, data: s.IssueWrite) -> s.IssueWrite:
    """No indent: a blank department/project comes from the person it is issued TO
    (their HCM record), never overwriting what the form chose."""
    if not data.issued_to_id or (data.department_id and data.project_id):
        return data
    from app.platform.hcm.models import HcmEmployee
    employee = await db.get(HcmEmployee, data.issued_to_id)
    if employee is None:
        return data
    return data.model_copy(update={
        "department_id": data.department_id or employee.department_id,
        "project_id": data.project_id or employee.project_id,
    })


def _assert_direct_issue_parties(data: s.IssueWrite, *, for_sto: bool = False) -> None:
    """A DIRECT outward issue — no indent on the header or on any line, no stock
    transfer order, no pick list behind it — must name where the goods go and who
    takes them (2026-10-21). With nothing requesting the stock, those two are the only
    record of why it left; an indent-backed issue carries both on the indent."""
    if data.direction == IssueDirection.IN or for_sto or data.indent_id or data.picking_id:
        return
    if any(getattr(line, "indent_id", None) or getattr(line, "indent_item_id", None)
           for line in data.items):
        return
    missing = [label for label, value in (
        ("a destination", data.destination_warehouse_id),
        ("the person it is issued to", data.issued_to_id),
    ) if not value]
    if missing:
        raise ValidationError(
            f"A direct issue needs {' and '.join(missing)}. Pick "
            f"{'them' if len(missing) > 1 else 'it'} under Issue details.")


async def _build_issue(db: AsyncSession, data: s.IssueWrite, user, *,
                       for_sto: bool = False,
                       forwarding: bool = False) -> m.MaterialIssue:
    """Build one material issue draft without committing it.

    Same reason as _build_picking: allocation approval creates its warehouse drafts
    in the same transaction as the stock reservations behind them, so a split
    allocation either produces every draft or none.
    """
    wh = await _warehouse(db, data.warehouse_id)
    from app.modules.indents.models import Indent
    indent = await db.get(Indent, data.indent_id) if data.indent_id else None
    if not forwarding:
        _assert_direct_issue_parties(data, for_sto=for_sto)

    if data.direction != IssueDirection.IN and data.items:
        # An indent is served over several issues: one per warehouse when the
        # allocation is split, and another round when procurement covers the
        # shortfall. The cap is the approved quantity, not the document count — see
        # _guard_indent_quantity. A return (direction IN) is exempt: it exists to
        # point back at an issue already made.
        #
        # Grouped per indent, because one issue can now serve a whole consolidated
        # cycle. Capping the batch against the header's indent alone would let one
        # LT's line be checked and the other 899 sail through unchecked.
        wanted = await _guard_issue_indent_caps(db, data.items, data.indent_id, wh.id)
        # Not for a forward draft: it is written while a RECEIPT posts, and goods
        # forwarded down the chain hold no reservation at this point by design.
        if not forwarding:
            await _guard_point_reservation(db, data.items, data.indent_id, wh.id)
            await _guard_network_own_stock(db, data.items, data.indent_id, wh.id)

        # A LIP is the bottom of the chain: everything it holds arrived against a
        # request and everything it gives out answers one. Issuing with no indent
        # anywhere — not on the header, not on a line — was letting stock leave a
        # local point with nothing recording who asked for it, and the quantity cap
        # above has nothing to measure against either. Upstream points are
        # deliberately not held to this: a main store issues to departments, writes
        # off scrap and moves stock for reasons no indent covers.
        # An approved Stock Transfer Order is the request: its issue has no indent,
        # and a LIP sending stock sideways is exactly what the STO sanctioned.
        if not wanted and not for_sto and stock_locations.tier_of(
            wh.warehouse_type
        ) is stock_locations.LocationTier.LIP:
            raise ValidationError(
                f"{wh.name} can only issue against an indent. Pick the indent this "
                "material is being given out for.")

    if not data.items:
        raise ValidationError("An issue with no lines has nothing to issue")

    original = await get_issue(db, data.original_issue_id) if data.original_issue_id else None
    if data.direction == IssueDirection.IN and original is None:
        raise ValidationError("A return has to point at the issue it reverses")
    if original and (
        original.direction != IssueDirection.OUT.value or not original.is_stock_posted
    ):
        raise ValidationError("Materials can only return against a posted outward issue")
    picking = await get_picking(db, data.picking_id) if data.picking_id else None
    if data.picking_id and picking is None:
        raise NotFoundError(f"Material fulfilment {data.picking_id} not found")
    if picking:
        if picking.warehouse_id != wh.id:
            raise ValidationError(
                f"{picking.pick_no} belongs to {picking.warehouse_name}, not {wh.name}"
            )
        _guard(
            picking.status,
            {PickingStatus.PICKED.value, PickingStatus.COMPLETED.value},
            "raise an issue from", "material fulfilment",
        )
        existing = await db.scalar(
            select(m.MaterialIssue.id).where(
                m.MaterialIssue.picking_id == picking.id,
                m.MaterialIssue.status != IssueStatus.CANCELLED.value,
            ).limit(1)
        )
        if existing is not None:
            raise ValidationError(
                f"{picking.pick_no} already has material issue {existing}"
            )
    data = _fill_from_indent(data, indent)
    if indent is None:
        data = await _fill_from_employee(db, data)
    snapshots = await _issue_snapshot_values(
        db,
        department_id=data.department_id,
        project_id=data.project_id,
        vehicle_id=data.vehicle_id,
        issued_to_id=data.issued_to_id,
        vehicle_number=data.vehicle_number,
    )
    destination = await _issue_destination_point(db, data.destination_warehouse_id, wh.id)

    issue = m.MaterialIssue(
        # items=[] is not cosmetic. Without it the collection is unloaded after the
        # flush below, and _apply_issue_lines() opens with .clear(), which fires a lazy
        # SELECT. A lazy load inside an AsyncSession raises MissingGreenlet, so the
        # create failed before writing a single line. Same reason on every create_* here.
        items=[],
        # From the indent it serves — see the note on the GRN above.
        issue_no=await next_number(db, WarehouseDocType.WH_ISSUE.value,
                                   project=getattr(indent, "project_name", None) or snapshots["project_name"]),
        issue_type=data.issue_type.value,
        issue_date=data.issue_date,
        indent_id=data.indent_id,
        indent_no=indent.indent_no if indent else None,
        picking_id=data.picking_id,
        pick_no=picking.pick_no if picking else None,
        warehouse_id=wh.id, warehouse_name=wh.name,
        department_id=data.department_id,
        department_name=snapshots["department_name"],
        project_id=data.project_id,
        project_name=snapshots["project_name"],
        vehicle_id=data.vehicle_id,
        vehicle_number=snapshots["vehicle_number"],
        issued_to_id=data.issued_to_id,
        issued_to_name=snapshots["issued_to_name"],
        destination_warehouse_id=destination.id if destination else None,
        destination_warehouse_name=destination.name if destination else None,
        direction=data.direction.value,
        original_issue_id=original.id if original else None,
        original_issue_no=original.issue_no if original else None,
        status=IssueStatus.DRAFT.value,
        remarks=data.remarks,
        created_by_id=getattr(user, "id", None), created_by_name=_name(user),
    )
    db.add(issue)
    await db.flush()

    await _apply_issue_lines(db, issue, data.items)
    # Before the units are stamped: a relocation changes which balance rows this
    # document is holding, and `_reserve_issue_serials` validates the units it names
    # against the line's own bin and batch.
    await _realign_issue_reservations(db, issue, user)
    # A direct issue has no allocation holding its stock — it holds its own.
    await _hold_direct_issue_stock(db, issue, user)
    await _reserve_issue_serials(db, issue, data.items)
    # A coded pack leaves whole unless the line says break bulk (2026-10-08).
    await wh_packing.assert_issue_packs(db, issue, await _issue_units_by_line(db, issue),
                                        user)
    if original:
        _validate_issue_return(issue, original)
    if picking:
        _validate_picking_issue(issue, picking)
    await db.flush()

    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.CREATE, actor=user,
                      after={"status": issue.status, "total_qty": str(issue.total_qty)})
    return issue


async def _forwardable_serials(
    db: AsyncSession, *, item_id: int, named, warehouse_id: int, qty,
) -> list[str] | None:
    """The units named on this line that are still on the shelf at this point.

    Filtered rather than passed straight through, for two reasons that would both
    turn a handover into a 422. `_reserve_issue_serials` refuses a serial that is not
    AVAILABLE here, so one unit moved by hand would block the whole forward; and a
    partly rejected line carries more serials than it forwards, which trips the
    "N serial numbers for M units" guard. Whatever is dropped here is still editable
    on the draft — the storekeeper reviews it before submitting.

    Takes the serials rather than the line, because the two sources name them
    differently: a GRN line carries a `serial_numbers` list, a consignment line one
    `serial_no` per unit.
    """
    values = [value.strip() for value in (named or []) if value and value.strip()]
    if not values:
        return None
    rows = (await db.execute(
        select(m.SerialNumber.serial_number).where(
            m.SerialNumber.item_id == item_id,
            m.SerialNumber.serial_number.in_(values),
            m.SerialNumber.warehouse_id == warehouse_id,
            m.SerialNumber.status == SerialStatus.AVAILABLE.value,
            m.SerialNumber.is_active.is_(True),
        )
    )).scalars().all()
    on_shelf = {value.lower() for value in rows}
    return [value for value in values if value.lower() in on_shelf][:int(qty)] or None


async def _indent_line_for(db: AsyncSession, indent_id: int, item_id: int) -> int | None:
    """The indent line an onward issue line answers, when the source document did not
    carry `indent_item_id` itself (a consignment line never does)."""
    from app.modules.indents.models import IndentItem

    return await db.scalar(
        select(IndentItem.id).where(
            IndentItem.indent_id == indent_id,
            IndentItem.item_id == item_id,
        ).limit(1)
    )


async def _forward_drafts(db: AsyncSession, *, warehouse_id: int, source_no: str,
                          groups: dict[int, list], user) -> list[m.MaterialIssue]:
    """Build one onward issue draft per indent, out of the point that received them.

    Shared by both doorways into forwarding — the GRN (`forward_arrival`) and the
    consignment itself (`forward_dispatch`) — so the two can never disagree about what
    a handover is. Only drafts: the storekeeper still reviews and submits each one, and
    `_issue_doc_type` files them as FORWARD_ISSUE so Approvals Config can wave them
    through without touching the OWN_STOCK_ISSUE ladder.
    """
    from app.modules.indents.models import Indent

    drafts: list[m.MaterialIssue] = []
    for indent_id, items in groups.items():
        indent = await db.get(Indent, indent_id)
        if indent is None or not items:
            continue
        # Already forwarded once: a second draft would double-issue the same goods.
        if await db.scalar(
            select(m.MaterialIssue.id).where(
                m.MaterialIssue.indent_id == indent_id,
                m.MaterialIssue.warehouse_id == warehouse_id,
                m.MaterialIssue.status.not_in(list(DEAD_ISSUE_STATUSES)),
            ).limit(1)
        ):
            continue

        draft = await _build_issue(db, s.IssueWrite(
            issue_type=IssueType.INDENT_BASED,
            issue_date=ist_today(),
            indent_id=indent_id,
            warehouse_id=warehouse_id,
            department_id=indent.department_id,
            project_id=indent.project_id,
            issued_to_id=indent.requested_by_id,
            remarks=f"Forwarded from {source_no}",
            items=items,
        ), user, forwarding=True)
        drafts.append(draft)

    await db.commit()
    return [await get_issue(db, draft.id) for draft in drafts]


async def forward_arrival(db: AsyncSession, receipt_id: int, user) -> list[m.MaterialIssue]:
    """Pass an arrived consignment on to the points below — the MDP leg of WH -> MDP -> LIP.

    The MDP never owned these goods: they landed here on a consignment raised for
    indents whose delivery points sit further down, and the five people who signed
    each indent already sanctioned them. Forwarding is a handover, not a decision, so
    this only builds the onward DRAFTS; the storekeeper still reviews and submits, and
    `_issue_doc_type` will file them as FORWARD_ISSUE so Approvals Config can wave them
    through without touching the OWN_STOCK_ISSUE ladder.

    One draft per INDENT, because each LT is a separate delivery to a separate point —
    an issue cannot cover two destinations or nobody can say who received what.

    This is the doorway for a point that runs a receiving desk. A point that does not
    has no GRN to forward from — see `forward_dispatch`.
    """
    receipt = await get_receipt(db, receipt_id)
    if receipt.receipt_type != ReceiptType.DISPATCH.value:
        raise ValidationError(
            f"{receipt.grn_no} is not an arrived consignment; there is nothing to forward")
    if not receipt.is_stock_posted:
        raise ValidationError(
            f"{receipt.grn_no} has not been put away yet — forward it once the stock is here")

    # What each indent is owed here, keyed by the line so the onward issue points back
    # at the same `indent_item_id` the reservation was written against.
    by_indent: dict[int, list] = defaultdict(list)
    for line in receipt.items:
        if not line.indent_id or _d(line.accepted_qty) <= ZERO:
            continue
        by_indent[line.indent_id].append(line)
    if not by_indent:
        raise ValidationError(
            f"{receipt.grn_no} carries nothing raised against an indent, so there is "
            "nobody below to forward it to")

    groups: dict[int, list] = {}
    for indent_id, lines in by_indent.items():
        items = []
        for line in lines:
            indent_item_id = getattr(line, "indent_item_id", None) or \
                await _indent_line_for(db, indent_id, line.item_id)
            accepted = _d(line.accepted_qty)
            # The consignment landed in a batch, in a bin, as named units. That is the
            # only record of WHICH goods these are, and dropping it left the onward
            # issue on NO_BATCH/NO_BIN: the serial picker then fell back to every unit
            # the point holds — opening stock included — and handed the indent raiser
            # something that never came off this consignment.
            items.append(s.IssueItemWrite(
                indent_item_id=indent_item_id,
                item_id=line.item_id,
                item_code=line.item_code,
                item_name=line.item_name,
                batch_id=line.batch_id or None,
                bin_id=line.bin_id or None,
                requested_qty=accepted,
                issued_qty=accepted,
                serial_numbers=await _forwardable_serials(
                    db, item_id=line.item_id, named=line.serial_numbers,
                    warehouse_id=receipt.warehouse_id, qty=accepted),
                imei_numbers=[value.strip() for value in (line.imei_numbers or [])
                              if value.strip()] or None,
            ))
        groups[indent_id] = items

    return await _forward_drafts(db, warehouse_id=receipt.warehouse_id,
                                 source_no=receipt.grn_no, groups=groups, user=user)


async def can_forward_dispatch(db: AsyncSession, dispatch: m.Dispatch) -> bool:
    """Is `forward_dispatch` the way on from this consignment?

    True only for the relay hop that signed for the lorry and put the goods straight on
    the shelf: acknowledged here, no GRN behind it, and this point does not run a
    receiving desk. Every other case forwards from the GRN, or is the last leg and has
    nothing to forward at all.
    """
    if dispatch.status != DispatchStatus.ACKNOWLEDGED.value:
        return False
    # Nothing was credited here unless the goods landed on our own shelf, and a forward
    # off stock that was never posted builds a draft that dies at "0 available".
    if not _lands_on_internal_shelf(dispatch):
        return False
    issue_ids = await _dispatch_issue_ids(db, dispatch)
    if not issue_ids:
        return False
    if await requires_inward(db, dispatch.to_warehouse_id):
        return False
    if await _inward_receipt_for_dispatch(db, dispatch.id) is not None:
        return False
    # Forward when ANY issue on it still has a leg to go: `forward_dispatch` builds
    # one onward draft per indent, so issues that already ended here simply add none.
    for issue_id in issue_ids:
        issue = await db.get(m.MaterialIssue, issue_id)
        if issue is not None and not await _is_final_delivery_leg(db, issue, dispatch):
            return True
    return False


async def forward_dispatch(db: AsyncSession, dispatch_id: int, user) -> list[m.MaterialIssue]:
    """Forward a consignment that went straight onto stock, with no GRN behind it.

    The relay point that does not run a receiving desk has nothing for `forward_arrival`
    to start from: `acknowledge_dispatch` credited what arrived directly and no GRN was
    ever raised, so the MDP leg of WH -> MDP -> LIP dead-ended there. Same handover and
    the same one-draft-per-indent, started from the consignment instead.
    """
    dispatch = await get_dispatch(db, dispatch_id)
    if dispatch.status != DispatchStatus.ACKNOWLEDGED.value:
        raise ValidationError(
            f"{dispatch.dispatch_no} has not been acknowledged here yet — confirm what "
            "arrived before forwarding it on")
    if not dispatch.to_warehouse_id:
        raise ValidationError(
            f"{dispatch.dispatch_no} names no destination point, so there is nothing "
            "here to forward")
    existing = await _inward_receipt_for_dispatch(db, dispatch.id)
    if existing is not None:
        raise ValidationError(
            f"{dispatch.dispatch_no} was inwarded on {existing.grn_no} — forward it "
            "from there, so the handover carries the accepted quantity")
    if await requires_inward(db, dispatch.to_warehouse_id):
        raise ValidationError(
            f"{dispatch.to_warehouse_name or 'This point'} receives through Material "
            f"Inward, GRN and QC. Inward {dispatch.dispatch_no} first, then forward it "
            "from the GRN.")

    # A serialized item travels as one consignment line per unit, so the lines are
    # folded back to one row per item and batch before they can become an issue line.
    merged: dict[tuple[int, int, int], dict] = {}
    for line in dispatch.items:
        qty = _d(line.delivered_qty)
        if not line.indent_id or qty <= ZERO:
            continue
        row = merged.setdefault(
            (line.indent_id, line.item_id, line.batch_id or 0),
            {"line": line, "qty": ZERO, "serials": [], "imeis": []},
        )
        row["qty"] += qty
        if line.serial_no:
            row["serials"].append(line.serial_no)
        if line.imei_no:
            row["imeis"].append(line.imei_no)
    if not merged:
        raise ValidationError(
            f"{dispatch.dispatch_no} carries nothing raised against an indent, so there "
            "is nobody below to forward it to")

    groups: dict[int, list] = defaultdict(list)
    for (indent_id, item_id, _batch), row in merged.items():
        line, qty = row["line"], row["qty"]
        groups[indent_id].append(s.IssueItemWrite(
            indent_item_id=await _indent_line_for(db, indent_id, item_id),
            item_id=item_id,
            item_code=line.item_code,
            item_name=line.item_name,
            batch_id=line.batch_id or None,
            # Acknowledgement credits bulk (`NO_BIN`) — there was no putaway to move it
            # onto a shelf — so the onward issue draws from bulk too.
            bin_id=None,
            requested_qty=qty,
            issued_qty=qty,
            serial_numbers=await _forwardable_serials(
                db, item_id=item_id, named=row["serials"],
                warehouse_id=dispatch.to_warehouse_id, qty=qty),
            imei_numbers=[value.strip() for value in row["imeis"] if value.strip()] or None,
        ))

    return await _forward_drafts(db, warehouse_id=dispatch.to_warehouse_id,
                                 source_no=dispatch.dispatch_no, groups=dict(groups),
                                 user=user)


async def floor_scope_ids(db: AsyncSession, user) -> set[int] | None:
    """Every location a floor in-charge may touch, or None for warehouse-wide.

    `floor_ids_for_user` answers with the ROOTS — the floors the position is assigned
    and the ones an admin has granted on top. A floor is not where stock sits, though:
    it sits in a bay on a rack in a lane on that floor, so the roots have to be walked
    down before they can be compared with a `bin_id`.

    The walk is here, once, because the answer is needed in two different shapes and
    they must not disagree: as a filter on what the picker OFFERS, and as the gate on
    what the service ACCEPTS. Offering a location the write would refuse is a
    storekeeper filling in a form that cannot be saved; accepting one the picker never
    showed is the gate not being there at all (rule 6 — hiding the option is not the
    security, the server check is).

    An empty set is NOT the same as None: it means this position is a floor in-charge
    with no floor assigned, which must refuse everything rather than allow everything.
    """
    roots = await stock_locations.floor_ids_for_user(db, user)
    if roots is None:
        return None

    allowed = set(roots)
    frontier = set(roots)
    while frontier:
        children = set((await db.execute(select(m.WarehouseLocation.id).where(
            m.WarehouseLocation.parent_id.in_(frontier),
            m.WarehouseLocation.is_active.is_(True),
        ))).scalars().all())
        frontier = children - allowed
        allowed |= children
    # The Unlocated location of every warehouse those floors are in. It stands on no
    # floor — it is where stock waits that nobody ever put on one — so walking down
    # from a floor never reaches it, and a floor in-charge could neither issue that
    # stock nor move it to its real bay. It belongs to the whole warehouse.
    if roots:
        allowed |= set((await db.execute(
            select(m.WarehouseLocation.id).where(
                m.WarehouseLocation.warehouse_id.in_(
                    select(m.WarehouseLocation.warehouse_id)
                    .where(m.WarehouseLocation.id.in_(roots))),
                func.upper(m.WarehouseLocation.bin_type) == unlocated.KIND,
                m.WarehouseLocation.is_active.is_(True),
            ))).scalars().all())
    return allowed


async def _assert_floor_access(db: AsyncSession, location_id: int | None, user,
                               what: str) -> None:
    """The same gate as `_assert_issue_floor_access`, for a document with ONE location.

    A putaway, a movement and an issue all end with stock sitting somewhere, so they
    all have to answer the same question about who may put it there. The issue asks it
    per line because an issue has many; everything else asks it once.
    """
    allowed = await floor_scope_ids(db, user)
    if allowed is None:
        return
    if not allowed:
        raise ValidationError("No warehouse floor is assigned to your HCM position")
    if location_id not in allowed:
        raise ValidationError(
            f"{what} location is outside your assigned floor(s).")


async def _assert_issue_floor_access(db: AsyncSession, issue: m.MaterialIssue, user) -> None:
    """Hard write gate: floor in-charges may draw only from their assigned floors."""
    allowed = await floor_scope_ids(db, user)
    if allowed is None:
        return
    if not allowed:
        raise ValidationError("No warehouse floor is assigned to your HCM position")

    invalid = [line.bin_code or str(line.bin_id) for line in issue.items
               if not line.bin_id or line.bin_id not in allowed]
    if invalid:
        raise ValidationError(
            "Material issue contains stock outside your assigned floor(s): "
            + ", ".join(invalid))


async def create_issue(db: AsyncSession, data: s.IssueWrite, user) -> m.MaterialIssue:
    issue = await _build_issue(db, data, user)
    await _assert_issue_floor_access(db, issue, user)
    await db.commit()
    return await get_issue(db, issue.id)


async def update_issue(db: AsyncSession, issue_id: int, data: s.IssueWrite, user) -> m.MaterialIssue:
    issue = await get_issue(db, issue_id)
    _guard(issue.status, {IssueStatus.DRAFT.value}, "edit", "issue")
    # The same rule as on create. An STO's own issue is exempt: the transfer order is
    # its request, and names the destination itself.
    from app.modules.inventory.models import StockTransferOrder
    sto_row = (await db.execute(select(
        StockTransferOrder.id, StockTransferOrder.to_warehouse_id,
        StockTransferOrder.from_warehouse_id).where(
        StockTransferOrder.issue_id == issue.id).limit(1))).first()
    from_sto = sto_row.id if sto_row else None
    _assert_direct_issue_parties(data, for_sto=bool(from_sto))
    # FROZEN on the order (2026-10-29): the STO was approved for one destination, and
    # an issue re-pointing it would deliver somewhere nobody signed for. The screen
    # locks the field; this is what makes the lock true. An order whose destination
    # stood in for an unresolvable requester (to == from) names no real point.
    if sto_row and sto_row.to_warehouse_id != sto_row.from_warehouse_id:
        data = data.model_copy(update={"destination_warehouse_id": sto_row.to_warehouse_id})

    before = {"total_qty": str(issue.total_qty)}
    wh = await _warehouse(db, data.warehouse_id)
    if data.indent_id:
        from app.modules.indents.models import Indent
        data = _fill_from_indent(data, await db.get(Indent, data.indent_id))
    snapshots = await _issue_snapshot_values(
        db,
        department_id=data.department_id,
        project_id=data.project_id,
        vehicle_id=data.vehicle_id,
        issued_to_id=data.issued_to_id,
        vehicle_number=data.vehicle_number,
    )
    issue.issue_type = data.issue_type.value
    issue.issue_date = data.issue_date
    issue.indent_id = data.indent_id
    if data.indent_id:
        from app.modules.indents.models import Indent
        indent = await db.get(Indent, data.indent_id)
        issue.indent_no = indent.indent_no if indent else None
    else:
        issue.indent_no = None
    issue.picking_id = data.picking_id
    picking = await get_picking(db, data.picking_id) if data.picking_id else None
    issue.pick_no = picking.pick_no if picking else None
    issue.warehouse_id = wh.id
    issue.warehouse_name = wh.name
    issue.department_id = data.department_id
    issue.department_name = snapshots["department_name"]
    issue.project_id = data.project_id
    issue.project_name = snapshots["project_name"]
    issue.vehicle_id = data.vehicle_id
    issue.vehicle_number = snapshots["vehicle_number"]
    issue.issued_to_id = data.issued_to_id
    issue.issued_to_name = snapshots["issued_to_name"]
    destination = await _issue_destination_point(db, data.destination_warehouse_id, wh.id)
    issue.destination_warehouse_id = destination.id if destination else None
    issue.destination_warehouse_name = destination.name if destination else None
    issue.remarks = data.remarks

    if issue.direction != IssueDirection.IN.value and data.items:
        # The same cap `_build_issue` applies, with this draft's own old lines left
        # out — they are the ones being replaced.
        await _guard_issue_indent_caps(db, data.items, data.indent_id, wh.id,
                                       exclude_issue_id=issue.id)
        await _guard_point_reservation(db, data.items, data.indent_id, wh.id,
                                       exclude_issue_id=issue.id)
        await _guard_network_own_stock(db, data.items, data.indent_id, wh.id,
                                       exclude_issue_id=issue.id)
    await _clear_issue_serial_reservations(db, issue.id)
    await _apply_issue_lines(db, issue, data.items)
    # The edit that matters most on this screen: a storekeeper who moves a line onto
    # the bay the goods are actually in moves inventory's hold with it, and frees the
    # bay he has left. See `_realign_issue_reservations`.
    await _realign_issue_reservations(db, issue, user)
    await _hold_direct_issue_stock(db, issue, user)
    # Then the same floor gate `create_issue` applies, in the same place: a repointed
    # line may only land on a bay this user's position actually covers.
    await _assert_issue_floor_access(db, issue, user)
    await _reserve_issue_serials(db, issue, data.items)
    # A coded pack leaves whole unless the line says break bulk (2026-10-08).
    await wh_packing.assert_issue_packs(db, issue, await _issue_units_by_line(db, issue),
                                        user)
    if issue.direction == IssueDirection.IN.value and issue.original_issue_id:
        original = await get_issue(db, issue.original_issue_id)
        _validate_issue_return(issue, original)
    if picking:
        _validate_picking_issue(issue, picking)
    await db.flush()

    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.UPDATE, actor=user, before=before,
                      after={"total_qty": str(issue.total_qty)})
    await db.commit()
    return await get_issue(db, issue_id)


# ---- which approval event a material issue runs under -------------------------
#
# WH_ISSUE is the ordinary warehouse issue and keeps whatever ladder is configured for
# it. OWN_STOCK_ISSUE is the same document when the point it comes OUT of is one the
# submitter holds — his own MDP, or a LIP reporting under him. Nobody above him owns
# that shelf, so the default approver is him; configurable on its own row in Approvals
# Config without touching the WH_ISSUE ladder.
ISSUE_DOC_TYPES = (DocType.WH_ISSUE.value, DocType.OWN_STOCK_ISSUE.value,
                   DocType.FORWARD_ISSUE.value)


async def _indent_ids_on_issue(db: AsyncSession, issue: m.MaterialIssue) -> set[int]:
    """Every indent this issue serves — the header's, plus the lines'.

    The header carries one `indent_id`; a consolidated issue serving several LTs
    carries the rest on its lines via `indent_item_id`, so both have to be read or a
    batch issue looks like an indent-less one.
    """
    from app.modules.indents.models import IndentItem

    ids = {issue.indent_id} if issue.indent_id else set()
    # Queried, not read off `issue.items`: some callers reach here with an issue loaded
    # by db.get(), where touching the relationship would lazy-load under async and
    # raise MissingGreenlet.
    line_item_ids = [row for row in (await db.execute(
        select(m.MaterialIssueLine.indent_item_id)
        .where(m.MaterialIssueLine.issue_id == issue.id,
               m.MaterialIssueLine.indent_item_id.is_not(None))
    )).scalars().all() if row]
    if line_item_ids:
        ids |= {row for row in (await db.execute(
            select(IndentItem.indent_id).where(IndentItem.id.in_(line_item_ids))
        )).scalars().all() if row}
    return ids


async def _indent_id_for_line(db: AsyncSession, line, header_indent_id: int | None) -> int | None:
    """Which indent one INCOMING issue line serves.

    The line's own `indent_item_id` wins; the header is the fallback so a plain
    single-indent issue behaves exactly as it always did.
    """
    from app.modules.indents.models import IndentItem

    if getattr(line, "indent_item_id", None):
        owner = await db.scalar(
            select(IndentItem.indent_id).where(IndentItem.id == line.indent_item_id))
        if owner:
            return owner
    return header_indent_id


async def _line_indent_ids(db: AsyncSession, issue: m.MaterialIssue) -> dict[int, int]:
    """`{issue line id: the indent that line serves}`.

    One query for the whole document rather than one per line — a consolidated issue
    covering a monthly cycle has hundreds of lines and must not cost hundreds of round
    trips. Lines with no `indent_item_id` are absent; the caller falls back to the
    header, which is what a plain single-indent issue has always used.
    """
    from app.modules.indents.models import IndentItem

    pairs = {line.id: line.indent_item_id for line in (issue.items or [])
             if line.indent_item_id}
    if not pairs:
        return {}
    owner = {row[0]: row[1] for row in (await db.execute(
        select(IndentItem.id, IndentItem.indent_id)
        .where(IndentItem.id.in_(set(pairs.values())))
    )).all()}
    return {line_id: owner[item_id]
            for line_id, item_id in pairs.items() if item_id in owner}


async def _is_forwarding(db: AsyncSession, issue: m.MaterialIssue) -> bool:
    """Is this point merely passing goods along, rather than giving its own stock?

    True when the stock being issued arrived HERE on a consignment raised for the same
    indent — the WH -> MDP -> LIP middle leg. Those goods were sanctioned by the five
    people who signed the indent; the MDP never owned them and is not making a
    decision about them. Read off `inb_receipts` (ReceiptType.DISPATCH) rather than a
    new flag, because that row is already written when the MDP inwards the delivery.
    """
    indent_ids = await _indent_ids_on_issue(db, issue)
    if not indent_ids or not issue.warehouse_id:
        return False
    return bool(await db.scalar(
        select(m.Receipt.id)
        .join(m.ReceiptItem, m.ReceiptItem.receipt_id == m.Receipt.id)
        .where(
            m.Receipt.receipt_type == ReceiptType.DISPATCH.value,
            m.Receipt.warehouse_id == issue.warehouse_id,
            m.ReceiptItem.indent_id.in_(indent_ids),
        ).limit(1)
    ))


async def _issue_doc_type(db: AsyncSession, issue: m.MaterialIssue, user) -> str:
    """At submit: decide which of the three events this issue is.

    Order matters. Forwarding is checked first because it is also an issue out of a
    point the raiser holds, and so would otherwise be read as OWN_STOCK_ISSUE — "I
    chose to give my stock", which is a real decision and must keep its ladder. The
    two cannot share a row in Approvals Config or switching one off silently switches
    off the other.
    """
    my_points = await stock_locations.location_ids_for_user(db, user)
    if not (issue.warehouse_id and issue.warehouse_id in my_points):
        return DocType.WH_ISSUE.value
    if await _is_forwarding(db, issue):
        return DocType.FORWARD_ISSUE.value
    return DocType.OWN_STOCK_ISSUE.value


async def _issue_doc_type_of(db: AsyncSession, issue_id: int) -> str:
    """Afterwards: read back what it was submitted under.

    Off the instance rather than a column on the issue — there is no column, and the
    instance is the authority on which chain is actually running.
    """
    found = (await db.execute(
        select(WfInstance.doc_type)
        .where(WfInstance.doc_id == issue_id,
               WfInstance.doc_type.in_(ISSUE_DOC_TYPES))
        .order_by(WfInstance.id.desc()).limit(1)
    )).scalar_one_or_none()
    return found or DocType.WH_ISSUE.value


async def _issue_holders_bulk(db: AsyncSession,
                              issues: list) -> dict[int, list[tuple[int, str]]]:
    """Who holds each APPROVED, unposted issue — the people who issue it from stock.

    A floor piece of a split belongs to that floor's in-charge(s). Anything else goes
    back to whoever SUBMITTED it (the workflow instance's starter), falling back to
    whoever raised it. Read, never stored: reassigning a floor or a post changes the
    answer by existing. Issues in any other state are left out.
    """
    waiting = [issue for issue in issues
               if issue.status == IssueStatus.APPROVED.value and not issue.is_stock_posted]
    if not waiting:
        return {}
    out: dict[int, list[tuple[int, str]]] = {}
    floors = {issue.floor_location_id for issue in waiting if issue.floor_location_id}
    floor_people = await stock_locations.floor_incharge_people(db, floors) if floors else {}
    starters: dict[int, tuple[int, str]] = {}
    for doc_id, emp_id, name in (await db.execute(
        select(WfInstance.doc_id, WfInstance.started_by_id, WfInstance.started_by_name)
        .where(WfInstance.doc_id.in_([issue.id for issue in waiting]),
               WfInstance.doc_type.in_(ISSUE_DOC_TYPES),
               WfInstance.started_by_id.is_not(None))
        .order_by(WfInstance.id)
    )).all():
        starters[int(doc_id)] = (int(emp_id), name or "")   # latest instance wins
    for issue in waiting:
        people = floor_people.get(issue.floor_location_id) or []
        if not people and issue.id in starters:
            people = [starters[issue.id]]
        if not people and issue.created_by_id:
            people = [(int(issue.created_by_id), issue.created_by_name or "")]
        out[issue.id] = people
    return out


def _holder_label(people: list[tuple[int, str]]) -> str | None:
    names = list(dict.fromkeys(name for _id, name in people if name))
    if not names:
        return None
    return names[0] if len(names) == 1 else f"{names[0]} +{len(names) - 1}"


def _currently_with(issue, holders: list[tuple[int, str]] | None) -> str | None:
    """Where the document is RIGHT NOW — one answer for the list and the detail."""
    status = issue.status
    if status == IssueStatus.DRAFT.value:
        return getattr(issue, "created_by_name", None)
    if status == IssueStatus.PENDING_APPROVAL.value:
        return issue.current_approver_name or "unassigned"
    if status == IssueStatus.APPROVED.value and not issue.is_stock_posted:
        return _holder_label(holders or [])
    return None


async def _may_act_as_issue_holder(db: AsyncSession, user,
                                   holders: list[tuple[int, str]]) -> bool:
    """The holder, or anyone above them on the HCM reporting line, or an admin."""
    if user is None:
        return False
    if not holders or user.id in {emp_id for emp_id, _name in holders}:
        return True       # nobody resolvable must never strand the document (rule 8)
    from app.platform.hcm.models import HcmPosition, HcmPositionAssignment
    from app.platform.rbac.permissions import ADMIN_SETTINGS_MANAGE
    from app.platform.rbac.service import get_user_permissions
    if ADMIN_SETTINGS_MANAGE in await get_user_permissions(
            db, user, getattr(user, "active_position_id", None)):
        return True
    mine = await stock_locations.active_positions_of(db, user)
    if not mine:
        return False
    frontier = set((await db.execute(
        select(HcmPositionAssignment.position_id)
        .join(HcmPosition, HcmPosition.id == HcmPositionAssignment.position_id)
        .where(HcmPositionAssignment.employee_id.in_({e for e, _n in holders}),
               HcmPositionAssignment.is_active.is_(True),
               HcmPosition.is_active.is_(True))
    )).scalars().all())
    seen: set[int] = set(frontier)
    for _depth in range(15):           # bounded: a cycle in HCM must not spin
        parents = set((await db.execute(
            select(HcmPosition.parent_position_id)
            .where(HcmPosition.id.in_(frontier),
                   HcmPosition.parent_position_id.is_not(None))
        )).scalars().all()) - seen
        if not parents:
            return False
        if parents & mine:
            return True
        seen |= parents
        frontier = parents
    return False


async def _issue_approved_by(db: AsyncSession, issue_id: int, user) -> bool:
    """Did this person sign an approval on this issue? Read off `wf_actions`."""
    if user is None:
        return False
    # A floor piece carries its parent's approval (it is never approved itself), so
    # the parent's approvers count for it as well.
    parent_id = await db.scalar(
        select(m.MaterialIssue.parent_issue_id).where(m.MaterialIssue.id == issue_id))
    doc_ids = [issue_id] + ([parent_id] if parent_id else [])
    return (await db.execute(
        select(WfAction.id)
        .join(WfInstance, WfInstance.id == WfAction.instance_id)
        .where(WfInstance.doc_id.in_(doc_ids),
               WfInstance.doc_type.in_(ISSUE_DOC_TYPES),
               WfAction.actor_id == user.id,
               WfAction.action == ApprovalAction.APPROVED.value)
        .limit(1)
    )).scalar_one_or_none() is not None


async def _assert_issue_holder(db: AsyncSession, issue, user) -> None:
    """Who works an approved issue: the person it is WITH (or their reporting line),
    or anyone who APPROVED it.

    An approver signed off on exactly these goods, and in a small store the approver
    is very often the one standing at the shelf; refusing them the press left the issue
    waiting on a holder who was not there. Picking serials goes through here too,
    because an issue cannot be posted without them.
    """
    holders = (await _issue_holders_bulk(db, [issue])).get(issue.id, [])
    if await _may_act_as_issue_holder(db, user, holders):
        return
    if await _issue_approved_by(db, issue.id, user):
        return
    raise PermissionError_(
        f"{issue.issue_no} is with {_holder_label(holders) or 'another person'}. "
        "Only they, someone they report to, or an approver of this issue can pick its "
        "serials and issue it from stock.")


async def submit_issue(db: AsyncSession, issue_id: int, user) -> m.MaterialIssue:
    """Hands the document to the workflow engine.

    The engine owns the chain; this module owns the status and snapshots who is
    holding it so a list screen does not have to ask. If the engine has no workflow
    configured it falls back rather than stranding the document (rule 8), which is why
    a failure to start is logged and the document still moves.
    """
    issue = await get_issue(db, issue_id)
    _guard(issue.status, {IssueStatus.DRAFT.value}, "submit", "issue")
    if not issue.items:
        raise ValidationError("An issue with no lines has nothing to approve")
    await _assert_sources_picked(db, issue)
    # Checked HERE, while the batch is still editable. It used to be checked only at
    # post_issue, which runs after approval has frozen the batch and the bin, so a
    # line pointed at a batch holding too few serials became an issue that could
    # neither be posted nor corrected.
    await _assert_units_obtainable(db, issue)

    context = {
        "warehouse_id": issue.warehouse_id,
        "total_value": float(_d(issue.total_value)),
        "department_id": issue.department_id,
        "project_id": issue.project_id,
    }
    context.update({
        "doc_no": issue.issue_no,
        "doc_summary": f"Material issue {issue.issue_no}",
        "requester_position_id": getattr(user, "active_position_id", None),
    })
    doc_type = await _issue_doc_type(db, issue, user)
    instance = await engine.start(
        db, doc_type, issue.id, context, user
    )
    if instance.status == InstanceStatus.APPROVED.value:
        issue.status = IssueStatus.APPROVED.value
        issue.approved_by_name = _name(user)
        issue.approved_at = utcnow()
        issue.current_approver_name = None
    else:
        approvers = await engine.current_approvers(db, doc_type, issue.id)
        # Rung as well as name — see `_approver_label` (2026-08-21).
        issue.current_approver_name = _approver_label(
            approvers, await _approver_rank(db, doc_type, issue.id))
        issue.status = IssueStatus.PENDING_APPROVAL.value

    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": IssueStatus.DRAFT.value},
                      after={"status": issue.status,
                             "current_approver": issue.current_approver_name})
    await db.commit()
    return await get_issue(db, issue_id)


def _floor_of(index: dict, bin_id: int | None) -> tuple[int | None, str | None]:
    """Which FLOOR a location sits on — the outermost rung of its own ancestry.

    Read off `_location_index`, which already carries every node's whole chain, so
    this is a dictionary lookup rather than a walk per bin. A location whose ancestry
    is a single node IS the floor.
    """
    node = index.get(bin_id) if bin_id else None
    steps = (node or {}).get("steps") or []
    if not steps:
        return None, None
    return steps[0]["id"], steps[0]["name"]


async def split_issue_by_floor(db: AsyncSession, issue_id: int, user) -> dict:
    """Break one approved issue into a child per floor that actually holds the stock.

    **The issue itself is never tagged to a floor, and must not be.** It is raised by
    an allocation against a WAREHOUSE and belongs to nobody in particular; writing a
    floor onto it would be storing an answer that stops being true the moment the
    goods are moved. So the generic issue is broken UP instead: each child names the
    floor it was handed to — a fact about who was given the work, which moving stock
    does not change — and carries only what that floor was holding when the manager
    pressed the button.

    Quantities are DISTRIBUTED, never repeated. Ask for 100 with 40 on the third floor
    and 60 on the ground floor and you get two children, for 40 and 60. Ask for 100
    with only 70 anywhere and you get 70 — the missing 30 stays UNFULFILLED on the
    parent and is reported back, because a shortage belongs to the indent and rounding
    it away silently is how a site waits for goods nobody is buying.

    Splitting is OPTIONAL. A warehouse manager is not floor-restricted
    (`floor_scope_ids` answers None for them), so they can post the whole issue
    themselves and never press this. It exists for handing the work down, not for
    taking it away.

    Ordered expiry-then-batch, the same order `issue_stock_sources` uses, so the
    children come out FIFO without this function knowing what FIFO is.
    """
    from app.modules.inventory.models import Reservation, Stock

    parent = await get_issue(db, issue_id)
    if parent.status in (IssueStatus.SPLIT.value, IssueStatus.CLOSED.value):
        raise ValidationError(
            f"{parent.issue_no} has already been split. Work its floor issues, or "
            "cancel all of them to split it again.")
    _guard(parent.status, {IssueStatus.APPROVED.value}, "split", "issue")
    # The split code says WHO may split; this says WHERE. A storekeeper of another
    # warehouse holding the code must not be able to break this one's issue up.
    await _assert_in_scope(db, user, m.MaterialIssue, parent,
                           warehouse_col=m.MaterialIssue.warehouse_id,
                           owner_col=m.MaterialIssue.created_by_id, label="Issue")
    # Handing work ACROSS floors is a warehouse-wide decision. A floor in-charge sees
    # only their own floors, so a split by one would hand out stock they cannot see.
    if await floor_scope_ids(db, user) is not None:
        raise ValidationError(
            "Only a warehouse-wide user can split an issue across floors — you are "
            "assigned to specific floors.")
    if parent.parent_issue_id:
        raise ValidationError(
            f"{parent.issue_no} is already a split of {parent.parent_issue_no}.")
    existing = await db.scalar(
        select(func.count()).select_from(m.MaterialIssue).where(
            m.MaterialIssue.parent_issue_id == parent.id,
            m.MaterialIssue.status.notin_(UNSERVED_ISSUE_STATUSES),
        )
    )
    if existing:
        raise ValidationError(
            f"{parent.issue_no} has already been split into {existing} issue(s). "
            "Cancel those before splitting again.")

    index = await _location_index(db, parent.warehouse_id)

    # A direct parent holds its own stock (`_hold_direct_issue_stock`). Handed back
    # before the shelf is read, so the floors' free stock includes it; each child
    # re-takes exactly its own piece below, in the same transaction, so nothing is
    # ever briefly free to anybody else.
    await _release_issue_hold(db, parent.id)

    # Every (bin, batch) the parent's items can be drawn from in this warehouse,
    # oldest stock first. Read off stk_balance, never off the unit tables — those hold
    # one row per physical thing and there are hundreds of thousands of them.
    #
    # **`available_qty` ALONE IS WRONG HERE**, and getting it wrong looks exactly like
    # an empty warehouse. Approving the allocation behind this issue RESERVED the very
    # stock the issue is about to move, so the balance row it is going to draw from
    # reads `available_qty = 0` — the goods are on the shelf, spoken for, by this
    # document. Splitting on that number refused every real issue with "no floor is
    # holding stock for these items" while the pallet was standing on the third floor.
    # So this adds the parent's OWN reservations back, exactly as
    # `issue_stock_sources` does for the same reason; another indent's reservation
    # stays subtracted, because that stock genuinely is not ours to hand out.
    item_ids = [line.item_id for line in parent.items]
    if parent.indent_id:
        mine = (
            select(Reservation.stock_id.label("stock_id"),
                   func.sum(Reservation.quantity).label("qty"))
            .where(Reservation.ref_type == InventoryRefType.RESERVATION.value,
                   Reservation.ref_id == parent.indent_id,
                   Reservation.status == ReservationStatus.ACTIVE.value)
            .group_by(Reservation.stock_id)
            .subquery()
        )
        drawable = func.sum(Stock.available_qty) + func.coalesce(func.sum(mine.c.qty), 0)
    else:
        mine = None
        drawable = func.sum(Stock.available_qty)

    stmt = (
        select(Stock.item_id, Stock.bin_id, Stock.batch_id,
               drawable.label("qty"),
               m.Batch.batch_no, m.Batch.expiry_date)
        .select_from(Stock)
        .outerjoin(m.Batch, m.Batch.id == Stock.batch_id)
    )
    if mine is not None:
        stmt = stmt.outerjoin(mine, mine.c.stock_id == Stock.id)
    rows = (await db.execute(
        stmt.where(Stock.warehouse_id == parent.warehouse_id,
                   Stock.item_id.in_(item_ids),
                   _stock_offerable(parent.indent_id))
        .group_by(Stock.item_id, Stock.bin_id, Stock.batch_id,
                  m.Batch.batch_no, m.Batch.expiry_date)
        .order_by(m.Batch.expiry_date.is_(None), m.Batch.expiry_date, Stock.batch_id)
    )).all() if item_ids else []

    # floor id -> {name, lines: [...]}, and what could not be placed anywhere.
    by_floor: dict[int, dict] = {}
    shortfall: list[dict] = []

    for line in parent.items:
        outstanding = _d(line.requested_qty)
        if outstanding <= ZERO:
            continue
        # The children are written straight to the table and never pass through
        # `_reserve_issue_serials`, the check that refuses a fractional serialized
        # line on create and edit. So it is repeated here: a 9.5 child of a serialized
        # item can never be completed at Outward QC.
        item = await _item_snapshot(db, line.item_id)
        whole = item.is_serial_tracked or (
            await uom_rules.decimals_by_code(db, [line.uom_code])
        ).get(line.uom_code, uom_rules.MAX_DECIMALS) == 0
        if whole and outstanding != outstanding.to_integral_value():
            raise ValidationError(
                f"{item.code}: {outstanding} {line.uom_code} is not a whole number — "
                f"cancel {parent.issue_no} and raise it again in whole units.")
        for row in rows:
            if outstanding <= ZERO:
                break
            if row.item_id != line.item_id:
                continue
            available = _d(row.qty)
            if whole:
                # Whole units only, or a fractional balance row splits 9 into 4.5 + 4.5.
                available = Decimal(int(available))
            if available <= ZERO:
                continue
            floor_id, floor_name = _floor_of(index, row.bin_id)
            if floor_id is None:
                continue          # stock at warehouse level, not on any floor
            take = min(outstanding, available)
            node = index.get(row.bin_id) or {}
            bucket = by_floor.setdefault(floor_id, {"name": floor_name, "lines": []})
            bucket["lines"].append({
                "indent_item_id": line.indent_item_id,
                "item_id": line.item_id, "item_code": line.item_code,
                "item_name": line.item_name, "uom_code": line.uom_code,
                "bin_id": row.bin_id, "bin_code": node.get("code"),
                "batch_id": row.batch_id, "batch_no": row.batch_no,
                "expiry_date": row.expiry_date,
                "qty": take,
                # The parent line's own rate, so a child is valued exactly as the
                # parent was — a child written without one listed at Rs 0.
                "rate": line.rate,
            })
            outstanding -= take
        if outstanding > ZERO:
            shortfall.append({
                "item_id": line.item_id, "item_code": line.item_code,
                "item_name": line.item_name, "qty": str(outstanding),
            })

    if not by_floor:
        raise ValidationError(
            "No floor in this warehouse is holding stock for these items, so there "
            "is nothing to split. Post the issue yourself, or put the stock away "
            "first.")

    created: list[m.MaterialIssue] = []
    # Children are numbered off their PARENT — WHI0013-001, -002, -003 — so anybody
    # holding one floor's paper can see at a glance which issue it is a piece of, and
    # the pieces sort together. Counted over every child ever cut (cancelled ones
    # included), because a re-split must never reuse a number already printed.
    sequence = int(await db.scalar(
        select(func.count()).select_from(m.MaterialIssue)
        .where(m.MaterialIssue.parent_issue_id == parent.id)) or 0)
    for floor_id, bucket in by_floor.items():
        sequence, child_no = await _next_child_issue_no(db, parent.issue_no, sequence)
        child = m.MaterialIssue(
            items=[],
            issue_no=child_no,
            issue_type=parent.issue_type,
            issue_date=parent.issue_date,
            indent_id=parent.indent_id, indent_no=parent.indent_no,
            picking_id=parent.picking_id, pick_no=parent.pick_no,
            warehouse_id=parent.warehouse_id,
            warehouse_name=parent.warehouse_name,
            department_id=parent.department_id,
            department_name=parent.department_name,
            project_id=parent.project_id, project_name=parent.project_name,
            vehicle_id=parent.vehicle_id, vehicle_number=parent.vehicle_number,
            issued_to_id=parent.issued_to_id,
            issued_to_name=parent.issued_to_name,
            direction=parent.direction,
            parent_issue_id=parent.id, parent_issue_no=parent.issue_no,
            floor_location_id=floor_id, floor_location_name=bucket["name"],
            # A child CARRIES the parent's approval (SCM_0011). It is not a new ask:
            # its lines are a slice of exactly what the parent's ladder signed —
            # quantities distributed, never added — and the parent is locked SPLIT the
            # moment the children exist. Starting each piece at DRAFT sent the floor
            # in-charge back up a second ladder for stock already approved to leave,
            # so the piece could be seen and never issued. Who WORKS it is still the
            # floor's in-charge (`_issue_holders_bulk`), checked at post time.
            status=IssueStatus.APPROVED.value,
            approved_by_name=parent.approved_by_name,
            approved_at=parent.approved_at,
            created_by_id=getattr(user, "id", None),
            created_by_name=getattr(user, "full_name", None),
        )
        for number, spec in enumerate(bucket["lines"], start=1):
            child.items.append(m.MaterialIssueLine(
                line_no=number,
                indent_item_id=spec["indent_item_id"],
                item_id=spec["item_id"], item_code=spec["item_code"],
                item_name=spec["item_name"], uom_code=spec["uom_code"],
                bin_id=spec["bin_id"], bin_code=spec["bin_code"],
                batch_id=spec["batch_id"], batch_no=spec["batch_no"],
                expiry_date=spec["expiry_date"],
                # `issued_qty` is PREFILLED, exactly as `_allocation_lines_by_batch`
                # prefills the draft this split replaces. Leaving it at zero is not the
                # harmless "the storekeeper will type it" it looks like: `post_issue`
                # skips a line with nothing on it, so the document posted as ISSUED
                # while `move_stock` was never called and no `stk_ledger` row was
                # written — the paper said six went out and the shelf still held them.
                # It also silently turned QC off: `needs_qc` reads `requires_qi` only
                # for lines with a quantity, so an item that must be inspected went
                # out as NOT_REQUIRED and never reached the Outward QC queue.
                requested_qty=spec["qty"], issued_qty=spec["qty"],
                rate=spec["rate"],
                amount=(spec["qty"] * _d(spec["rate"])) if spec["rate"] else None,
            ))
        _issue_totals(child)
        db.add(child)
        created.append(child)

    await db.flush()
    # The pieces start APPROVED and are never edited, so the realign that runs on an
    # edit never runs for them: the holds would stay where the allocation put them and
    # posting floor A's piece could consume a reservation sitting on floor B. Realigned
    # ONCE over every piece together — per piece, each would read the others' bays as
    # abandoned and release their holds.
    await _realign_issue_reservations(db, SimpleNamespace(
        id=parent.id, issue_no=parent.issue_no, direction=parent.direction,
        indent_id=parent.indent_id, project_id=parent.project_id,
        warehouse_id=parent.warehouse_id,
        items=[line for child in created for line in child.items]), user)
    await _hand_codes_to_floor_pieces(db, parent, created)
    for child in created:
        # A direct parent's hold, re-taken piece by piece (see the release above).
        await _hold_direct_issue_stock(db, child, user)
    for child in created:
        await write_audit(db, entity="out_issues", entity_id=child.id,
                          action=AuditAction.CREATE, actor=user,
                          after={"issue_no": child.issue_no,
                                 "parent_issue_no": parent.issue_no,
                                 "floor": child.floor_location_name,
                                 "total_qty": str(child.total_qty)})
    # The parent is now carried by its children: locked against posting, editing and
    # cancelling, and out of every indent count (see `IssueStatus.SPLIT`).
    parent.status = IssueStatus.SPLIT.value
    await write_audit(db, entity="out_issues", entity_id=parent.id,
                      entity_no=parent.issue_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": IssueStatus.APPROVED.value},
                      after={"status": parent.status,
                             "children": [c.issue_no for c in created]})
    # The pieces land APPROVED in the in-charge's queue; say so, or it waits unseen.
    from app.platform.notifications import service as notifications
    people = await stock_locations.floor_incharge_people(
        db, {c.floor_location_id for c in created if c.floor_location_id})
    for child in created:
        await notifications.notify(
            db, [emp_id for emp_id, _name in people.get(child.floor_location_id, [])],
            title=f"{child.issue_no} is ready to issue",
            body=(f"Split from {parent.issue_no} for {child.floor_location_name}: "
                  f"{child.total_items} item(s), {child.total_qty} unit(s)."),
            deep_link=notifications.link_for("WH_ISSUE", child.id),
            entity_type="WH_ISSUE", entity_id=child.id)
    await db.commit()

    # Who each piece went to. A floor name alone left the manager guessing whose
    # queue it had landed in — and a floor nobody holds says so, empty, on screen.
    in_charge = await stock_locations.floor_incharge_names(
        db, {c.floor_location_id for c in created if c.floor_location_id})
    return {
        "parent_issue_id": parent.id,
        "parent_issue_no": parent.issue_no,
        "children": [{"id": c.id, "issue_no": c.issue_no,
                      "floor_location_id": c.floor_location_id,
                      "floor_location_name": c.floor_location_name,
                      "in_charge_names": in_charge.get(c.floor_location_id, []),
                      "total_items": c.total_items,
                      "total_qty": str(c.total_qty)} for c in created],
        # Said out loud, never rounded away — see the docstring.
        "unfulfilled": shortfall,
    }


async def _hand_codes_to_floor_pieces(db: AsyncSession, parent: m.MaterialIssue,
                                      pieces: list[m.MaterialIssue]) -> None:
    """Give each floor piece the unit codes for its own quantity (2026-10-13).

    The pieces are written straight to the table and never passed through
    `_reserve_issue_serials`, so an asset- or consumable-coded line arrived on the
    floor with no codes — asking for them again — while the parent, now SPLIT and
    issuing nothing, kept holding the ones it had been given.

    The parent's holds are released first. Each piece line is then reserved exactly
    as a saved line is: a code the parent already named that sits on this piece's own
    batch and location is kept (the storekeeper's choice survives the split), and the
    rest is auto-filled oldest first from that same batch and location
    (`_auto_fill_codes`). Serial and IMEI lines stay empty — those are read off the
    goods at the shelf. Every code stays swappable on the piece.
    """
    # What the parent held, read off the units themselves (a line keeps no list of
    # its codes — the stamp on the unit IS the claim), with where each one sits.
    held = (await db.execute(
        select(m.SerialNumber).where(_issue_reservation_clause(parent.id))
        .order_by(m.SerialNumber.id)
    )).scalars().all()
    modes: dict[int, str] = {}
    for item_id in {line.item_id for piece in pieces for line in piece.items}:
        modes[item_id] = _unit_mode(await db.get(Item, item_id))
    column = {UNIT_MODE_SERIAL: "serial_number", UNIT_MODE_IMEI: "imei"}
    named: dict[int, list[str]] = {}
    where: dict[str, tuple[int, int, int]] = {}
    for row in held:
        mode = modes.get(int(row.item_id))
        if mode is None:
            continue
        code = (getattr(row, column[mode]) if mode in column
                else (row.asset_code or row.consumable_code))
        if code:
            named.setdefault(int(row.item_id), []).append(code)
            where[code] = (int(row.item_id), int(row.batch_id or 0), int(row.bin_id or 0))
    await _clear_issue_serial_reservations(db, parent.id)
    await db.flush()

    used: set[str] = set()
    for piece in pieces:
        inputs = []
        for line in piece.items:
            want = int(_d(line.issued_qty))
            mine = [c for c in named.get(line.item_id, [])
                    if c not in used
                    and where.get(c) == (int(line.item_id), int(line.batch_id or 0),
                                         int(line.bin_id or 0))][:want]
            used.update(mine)
            inputs.append(s.IssueItemWrite(
                item_id=line.item_id, indent_item_id=line.indent_item_id,
                requested_qty=_d(line.requested_qty), issued_qty=_d(line.issued_qty),
                rate=_d(line.rate) if line.rate is not None else None,
                batch_id=line.batch_id or None, bin_id=line.bin_id or None,
                serial_numbers=mine))
        await _reserve_issue_serials(db, piece, inputs)
    await db.flush()


async def _next_child_issue_no(db: AsyncSession, parent_no: str,
                               after: int) -> tuple[int, str]:
    """The next free `<parent>-NNN` after `after`. Checked against the table rather
    than trusted to the count: an issue number is unique, and a hand-made row or a
    half-finished earlier split must not make the split fail on a duplicate."""
    sequence = after
    while True:
        sequence += 1
        candidate = f"{parent_no}-{sequence:03d}"
        if not await db.scalar(select(m.MaterialIssue.id).where(
                m.MaterialIssue.issue_no == candidate).limit(1)):
            return sequence, candidate


async def _sync_split_parent(db: AsyncSession, parent_id: int | None, user) -> None:
    """Roll a split parent's status up from its children. Never set by hand.

    - any child still open (draft, in approval, approved, not yet posted) -> SPLIT
    - every child that was not cancelled/rejected has posted              -> CLOSED
    - every child cancelled or rejected                                  -> APPROVED

    The last is the way BACK, and matters as much as the way forward: with nothing
    serving it the parent's own lines are the only claim left, so it returns to the
    state it was split from and can be posted or split again. Whatever a CLOSED
    parent's children did not cover (a shortfall at split time, a cancelled child) is
    left reserved against the indent exactly as a short issue leaves it, and the
    parent no longer counts toward the indent cap, so a fresh issue can take it.

    Read on every child transition — post, reject, cancel — and by
    `scripts.sync_split_issues` for parents split before this existed.
    """
    if not parent_id:
        return
    parent = await db.get(m.MaterialIssue, parent_id)
    if parent is None or parent.status not in (
            IssueStatus.APPROVED.value, IssueStatus.SPLIT.value, IssueStatus.CLOSED.value):
        return
    children = (await db.execute(
        select(m.MaterialIssue.status, m.MaterialIssue.is_stock_posted)
        .where(m.MaterialIssue.parent_issue_id == parent_id)
    )).all()
    if not children:
        return
    live = [row for row in children if row.status not in UNSERVED_ISSUE_STATUSES]
    if not live:
        after = IssueStatus.APPROVED.value
    elif all(row.is_stock_posted for row in live):
        after = IssueStatus.CLOSED.value
    else:
        after = IssueStatus.SPLIT.value
    if after == parent.status:
        return
    reason = "rolled up from its floor issues"
    full = None
    if after == IssueStatus.APPROVED.value:
        # Back to a whole document — but only if the indent still has room for it.
        # While it was split, a fresh issue may have been raised for the quantity its
        # children did not cover; reviving the parent at its full quantity beside that
        # issue would claim the same indent line twice. It CLOSES instead, having
        # served nothing, and the indent's remainder stays free for a new issue.
        full = await get_issue(db, parent.id)
        try:
            await _guard_issue_indent_caps(db, full.items, full.indent_id,
                                           full.warehouse_id, exclude_issue_id=parent.id)
        except ValidationError as refused:
            after = IssueStatus.CLOSED.value
            reason = f"floor issues cancelled; not reopened — {refused}"
    if after == parent.status:
        return
    before = parent.status
    parent.status = after
    if after == IssueStatus.APPROVED.value and full is not None:
        # A direct parent takes its hold back where the shelf still has it. Best
        # effort — posting re-reads the shelf either way.
        await _hold_direct_issue_stock(db, full, user, strict=False)
    await write_audit(db, entity="out_issues", entity_id=parent.id,
                      entity_no=parent.issue_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": before},
                      after={"status": after, "reason": reason})


async def act_on_issue(
    db: AsyncSession, issue_id: int, action: str, comments: str, user,
) -> m.MaterialIssue:
    """Apply an approval decision and keep the warehouse document in sync."""
    issue = await get_issue(db, issue_id)
    _guard(
        issue.status, {IssueStatus.PENDING_APPROVAL.value},
        action.lower(), "issue",
    )
    before = issue.status
    doc_type = await _issue_doc_type_of(db, issue.id)
    instance = await engine.act(
        db,
        doc_type,
        issue.id,
        action,
        user,
        comments,
        context={
            "doc_no": issue.issue_no,
            "doc_summary": f"Material issue {issue.issue_no}",
            "warehouse_id": issue.warehouse_id,
            "department_id": issue.department_id,
            "project_id": issue.project_id,
            "total_value": float(_d(issue.total_value)),
        },
    )
    if instance.status == InstanceStatus.APPROVED.value:
        issue.status = IssueStatus.APPROVED.value
        issue.approved_by_name = _name(user)
        issue.approved_at = utcnow()
        issue.current_approver_name = None
    elif instance.status == InstanceStatus.REJECTED.value:
        issue.status = IssueStatus.REJECTED.value
        issue.current_approver_name = None
        await _release_issue_hold(db, issue.id)
    else:
        issue.current_approver_name = _approver_label(
            await engine.current_approvers(db, doc_type, issue.id),
            await _approver_rank(db, doc_type, issue.id),
        )

    await write_audit(
        db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": issue.status, "comments": comments},
    )
    await _sync_split_parent(db, issue.parent_issue_id, user)
    await db.commit()
    return await get_issue(db, issue_id)


def _approver_label(approvers: list, rank: str | None = None) -> str | None:
    """A readable "who is holding this" from whatever the engine returned.

    2026-08-21 — now says the RUNG as well: "Mahendra Kumar (Warehouse Manager)". A bare
    name does not tell a requester why the document is with that person or how far it
    has climbed, and where one person holds two posts it is actively misleading.

    Kept as a list-taking helper rather than replaced by
    `engine.current_approver_label`, because all six callers here have already fetched
    the approvers for their own reasons and swapping them would double the queries. The
    rank is passed in from the same instance the caller already loaded. The collapsing
    rule ("first +N") is unchanged and is shared with the engine's builder — both write
    into `current_approver_name`, which is String(200).
    """
    names = []
    for a in approvers or []:
        name = (a.get("name") or a.get("employee_name") or a.get("full_name")
                if isinstance(a, dict) else getattr(a, "full_name", None))
        if name:
            names.append(name)
    who = ("" if not names
           else names[0] if len(names) == 1
           else f"{names[0]} +{len(names) - 1}")
    rank = (rank or "").strip()
    label = f"{who} ({rank})" if who and rank else (who or rank)
    return label[:200] if label else None


async def _approver_rank(db: AsyncSession, doc_type: str, doc_id: int) -> str | None:
    """The rung a document is sitting on, for `_approver_label` above.

    Read off the frozen `wf_instances.resolved_chain` by the engine, never derived from
    the approver's HCM record: the chain is what the ladder actually decided, and an
    approver holding two posts would otherwise be labelled with whichever hat came back
    first. See `engine.current_approver_label` for the full reasoning.
    """
    return await engine.current_stage_rank(db, doc_type, doc_id)


async def _raise_picking_for_issue(
    db: AsyncSession, issue: m.MaterialIssue, user,
) -> m.Picking | None:
    """Raise the picklist draft that follows an issue whose stock has just posted.

    Rung two of the draft chain, and it is strictly a convenience: posting stock is a
    physical fact — the goods have left the shelf — so nothing in here may veto it.
    Everything below either degrades or gives up quietly, and the storekeeper can
    always raise the pick by hand.

    Skipped when the issue already came from a picklist (issue.picking_id) — that is
    the older pick-then-issue path, and re-raising there would loop.
    """
    if issue.picking_id:
        return None
    existing = await db.scalar(
        select(m.Picking.id).where(
            m.Picking.ref_type == "ISSUE",
            m.Picking.ref_id == issue.id,
            m.Picking.status != PickingStatus.CANCELLED.value,
        ).limit(1)
    )
    if existing is not None:
        return None

    # Resolve the bins before handing them over. _build_picking rejects a bin it
    # cannot load, and live issue lines carry ids that no longer exist in
    # whs_warehouse_locations; sending one through would turn a stale reference on a
    # draft into a hard failure to issue stock at all. An unresolved bin becomes "no
    # bin", which is what the picker sees anyway when nothing has told them where to go.
    lines: list[s.PickingItemWrite] = []
    for line in issue.items:
        if _d(line.issued_qty) <= ZERO:
            continue
        bin_id = line.bin_id or None
        if bin_id is not None:
            source = await db.get(Bin, bin_id)
            if source is None or source.warehouse_id != issue.warehouse_id:
                logger.warning(
                    "issue %s line %s: bin %s is unusable, picking line raised unbinned",
                    issue.issue_no, line.line_no, bin_id,
                )
                bin_id = None
        if bin_id is None:
            # Nothing upstream chose a bin — an issue drafted from an allocation never
            # does — so 58 of 64 live pick lines told the picker to go to "any" bin.
            # A picklist without a location is a list of things to hunt for. Ask stock
            # where this item actually is, in the order the strategy says to draw it.
            bin_id = await _pick_bin_for(
                db, item_id=line.item_id, warehouse_id=issue.warehouse_id,
                batch_id=line.batch_id or None,
            )
        lines.append(s.PickingItemWrite(
            item_id=line.item_id,
            bin_id=bin_id,
            batch_id=line.batch_id or None,
            required_qty=_d(line.issued_qty),
        ))
    if not lines:
        return None

    # Savepoint for the same reason as the consignment below: _build_picking flushes
    # its header before its lines, so a rejection partway would otherwise leave a
    # half-built pick to be committed alongside the stock movement.
    try:
        async with db.begin_nested():
            return await _build_picking(db, s.PickingWrite(
                pick_date=ist_today(),
                warehouse_id=issue.warehouse_id,
                ref_type="ISSUE",
                ref_id=issue.id,
                items=lines,
            ), user)
    except AppException as exc:
        logger.warning("auto-picklist for %s skipped: %s", issue.issue_no, exc)
        return None


async def set_issue_serials(db: AsyncSession, issue_id: int,
                            data: s.IssueSerialsIn, user) -> m.MaterialIssue:
    """Name the physical units on an approved issue, without reopening the document.

    The rest of the issue stays frozen after approval — quantities, bins and batches
    are what the approver saw. Only which serials are being handed over is still
    open, because that is decided at the shelf. `update_issue` cannot do this: it
    is DRAFT-only by design, and post_issue refuses an incomplete serial set, so an
    approved serialized issue had no way to reach ISSUED at all.
    """
    issue = await get_issue(db, issue_id)
    _guard(issue.status, {IssueStatus.DRAFT.value, IssueStatus.APPROVED.value},
           "capture serials on", "issue")
    if issue.is_stock_posted:
        raise ValidationError(f"{issue.issue_no} has already been posted")
    if issue.status == IssueStatus.APPROVED.value:
        await _assert_issue_holder(db, issue, user)

    by_line = {row.id: row.serial_numbers for row in data.lines}
    unknown = set(by_line) - {line.id for line in issue.items}
    if unknown:
        raise ValidationError(
            f"Line {sorted(unknown)[0]} is not on {issue.issue_no}")

    # _reserve_issue_serials zips strictly against issue.items, so every line is
    # restated — the ones not being edited keep the serials already reserved.
    inputs = [
        s.IssueItemWrite(
            item_id=line.item_id,
            indent_item_id=line.indent_item_id,
            requested_qty=_d(line.requested_qty),
            issued_qty=_d(line.issued_qty),
            rate=_d(line.rate),
            batch_id=line.batch_id,
            bin_id=line.bin_id,
            remarks=line.remarks,
            break_bulk=bool(getattr(line, "break_bulk", False)),
            # `unit_keys`, not `serial_numbers`: an untouched line is restated in the
            # currency its item is validated on, so an IMEI-named unit is not looked
            # up by a serial the IMEI lookup cannot see.
            serial_numbers=by_line.get(
                line.id,
                getattr(line, "unit_keys", None)
                or getattr(line, "serial_numbers", None) or []),
        )
        for line in issue.items
    ]
    await _clear_issue_serial_reservations(db, issue.id)
    await _reserve_issue_serials(db, issue, inputs)
    await wh_packing.assert_issue_packs(db, issue, await _issue_units_by_line(db, issue),
                                        user)

    await write_audit(db, entity="out_issues", entity_id=issue.id,
                      entity_no=issue.issue_no, action=AuditAction.UPDATE, actor=user,
                      after={"serials": {str(line.id): getattr(line, "serial_numbers", [])
                                         for line in issue.items}})
    await db.commit()
    return await get_issue(db, issue.id)


def _row_combo(row) -> dict:
    """A balance row's combination, in the shape `move_stock_out` takes."""
    return {"brand_id": int(row.brand_id or 0), "variant_id": int(row.variant_id or 0),
            "model_id": int(row.model_id or 0)}


async def _issue_slices(
    db: AsyncSession, issue: m.MaterialIssue, line: m.MaterialIssueLine, qty,
) -> list[tuple]:
    """Where an unreserved issue line's goods actually are:
    (bin, batch, project, quantity, brand / variant / model).

    All three dimensions come off the balance row, not off the document. `stk_balance`
    is keyed on (item, warehouse, bin, batch, project) and `move_stock_out` filters on
    every one of them, so taking any of them from the issue header re-introduces the
    same miss this function exists to prevent. A forwarded consignment inwards with no
    project on the balance row while the issue itself carries the indent's project —
    that alone was enough to read as "0 available" with the goods on the shelf.

    The line's own bin and batch are honoured whenever they hold enough — a
    storekeeper who named a batch meant it. They are only resolved when the named
    location cannot cover the line, which is what a FORWARDED consignment always
    looks like: the reservation was consumed at the point that dispatched it, so the
    line arrives carrying that point's bin and batch (in practice none), while the
    goods sit here under the batch the inward GRN created.

    Earliest expiry first, then oldest row: goods with a shelf life must leave in the
    order they expire, and this is the one place an unreserved outward issue chooses.
    A line may span batches, so several slices can come back.

    Returns the line's own location unchanged when nothing is found, so a genuine
    shortage still fails in `move_stock_out` with its own message rather than being
    silently swallowed here.
    """
    from app.modules.inventory.models import Stock

    wanted = combo_dict(line)
    fallback = [(line.bin_id, line.batch_id, issue.project_id or 0, qty, wanted)]
    rows = (await db.execute(
        select(Stock)
        .where(Stock.warehouse_id == issue.warehouse_id,
               Stock.item_id == line.item_id,
               Stock.available_qty > 0)
        .order_by(Stock.expiry_date.is_(None), Stock.expiry_date, Stock.id)
    )).scalars().all()
    # Only the brand / variant / model the line names (2026-10-23); a line naming
    # none may take any.
    rows = [row for row in rows if stock_allocation.matches_combination(row, wanted)]
    if not rows:
        return fallback

    # The named (bin, batch) under the issue's project OR unscoped stock (project 0),
    # the project's own row first. Matching the project alone missed every direct issue
    # carrying a project over unscoped stock, and FEFO then drew from bays the line
    # never named — WHI0001 took 4 monitors off F1/batch 48 while their serials left
    # LANE-1/batch 51, leaving both balances wrong.
    own_project = issue.project_id or 0
    named = sorted((r for r in rows
                    if r.batch_id == line.batch_id and r.bin_id == line.bin_id
                    and r.project_id in (own_project, 0)),
                   key=lambda r: r.project_id != own_project)
    if named and sum((_d(r.available_qty) for r in named), ZERO) >= qty:
        slices, remaining = [], qty
        for row in named:
            take = min(remaining, _d(row.available_qty))
            if take > ZERO:
                slices.append((row.bin_id, row.batch_id, row.project_id, take,
                               _row_combo(row)))
                remaining -= take
            if remaining <= ZERO:
                break
        return slices

    slices: list[tuple] = []
    remaining = qty
    for row in rows:
        take = min(remaining, _d(row.available_qty))
        if take <= ZERO:
            continue
        slices.append((row.bin_id, row.batch_id, row.project_id, take, _row_combo(row)))
        remaining -= take
        if remaining <= ZERO:
            break
    # Short overall: leave it to move_stock_out to say so against the line's own
    # location, rather than issuing a partial quantity nobody asked for.
    return slices if remaining <= ZERO else fallback

def _line_needs_outward_qc(item, line) -> bool:
    """Does this issue line go on the outward QC sheet? Only an item that asks for it."""
    return bool(getattr(item, "requires_qi", False)) and _d(line.issued_qty) > ZERO


async def _raise_outbound_inspection_for(
    db: AsyncSession,
    issue: m.MaterialIssue,
    user,
) -> m.OutboundInspection:
    """The outbound inspection a posted issue creates for items requiring QC.

    Only lines whose item `requires_qi`. A line that needs no check goes to logistics
    at its issued quantity (`_line_needs_outward_qc`); putting it on the sheet made the
    inspector pass goods nobody asked him to look at, and a failed sheet held them back.
    """
    inspection = m.OutboundInspection(
        items=[],
        # From the receipt it belongs to — see the note on the GRN number.
        inspection_no=await next_number(db, WarehouseDocType.INSPECTION.value,
                                        project=getattr(issue, "project_name", None)),
        inspection_date=ist_today(),
        issue_id=issue.id,
        issue_no=issue.issue_no,
        warehouse_id=issue.warehouse_id,
        warehouse_name=issue.warehouse_name,
        status=InspectionStatus.DRAFT.value,
        inspector_id=getattr(user, "id", None),
        inspector_name=_name(user),
    )
    db.add(inspection)
    await db.flush()

    units_by_line = await _issue_units_by_line(db, issue)

    for line in issue.items:
        item = await _item_snapshot(db, line.item_id)
        if not _line_needs_outward_qc(item, line):
            continue

        # FIXED 2026-08-21 — one STRING per unit, seeded once.
        #
        # This appended a dict per entry, but `serial_numbers` is a list of strings
        # everywhere else it is touched: `OutboundInspectionItemWrite` accepts only
        # `dict[str, list[str]] | list[str]`, and `_apply_outbound_inspection_lines`
        # calls `.strip()` on each value. So Complete inspection was refused with one
        # validation error per unit — QC/2026-27/00019 could not be signed at all — and
        # reading the document back 500'd on ResponseValidationError.
        #
        # And it counted every unit twice. `_issued_serial_index` is a LOOKUP keyed on
        # any identifier: the same row is filed under its serial, its asset code and its
        # consumable code, which is right for resolving a scan and wrong to iterate as
        # though it were a list of units. 196 units carrying both a serial and an asset
        # code seeded 392 entries, which is the number the Accepted serials column showed.
        #
        # Deduplicated on the unit's own id, and named by whichever identifier it
        # actually carries — the same value the issue hands the picker, so QC and the
        # issue speak about a unit with one name. Every kind is seeded: gating this on
        # `is_serial_tracked` left IMEI / asset / consumable lines with no units
        # stored, which the picker reads as "every unit rejected".
        # This LINE's units, not the batch's: two lines on one batch in two bays each
        # sent their own units, and seeding by batch gave both lines every unit.
        line_serials = _outbound_seed_units(
            units_by_line.get(line.id, []), item=item, item_id=line.item_id,
            batch_id=line.batch_id)

        inspection.items.append(m.OutboundInspectionItem(
            issue_item_id=line.id, item_id=line.item_id,
            item_code=line.item_code, item_name=line.item_name, uom_code=line.uom_code,
            batch_no=line.batch_no,
            **combinations.carry(line),
            inspected_qty=_d(line.issued_qty), accepted_qty=_d(line.issued_qty),
            rejected_qty=ZERO, result=InspectionResult.PENDING.value,
            serial_numbers=line_serials if line_serials else None,
        ))
        
    _outbound_inspection_totals(inspection)
    await db.flush()
    return inspection


def _ledger_packs(line, qty) -> str | None:
    """The packs an issue line went out as, for the ledger row of one slice of it.
    A line drawn from several balance rows writes several ledger rows; each says it is
    PART of the line's packing rather than claiming all of it (2026-10-08)."""
    entries = getattr(line, "pack_breakdown", None)
    if not entries:
        return None
    text = shared_packing.describe(entries, getattr(line, "uom_code", None))
    return text if _d(qty) == _d(line.issued_qty) else f"Part of {text}"


async def post_issue(db: AsyncSession, issue_id: int, user) -> m.MaterialIssue:
    """Takes the stock off the shelf. The only step here that moves anything."""
    issue = await get_issue(db, issue_id)
    _guard(issue.status, {IssueStatus.APPROVED.value}, "issue stock against", "issue")
    if issue.is_stock_posted:
        raise ValidationError(f"{issue.issue_no} has already been posted")
    await _assert_issue_holder(db, issue, user)
    # Expiry and FEFO, re-read at the moment the goods LEAVE (2026-10-13). The save
    # checked them, but approval can take days: a picked batch may have expired since,
    # or a GRN may have brought in one that expires earlier. Same check as the save,
    # against today's shelf. Outward only — `_assert_issue_sources` returns otherwise.
    await _assert_issue_sources(db, issue, [
        s.IssueItemWrite(
            item_id=line.item_id, indent_item_id=line.indent_item_id,
            item_code=line.item_code,
            requested_qty=_d(line.requested_qty), issued_qty=_d(line.issued_qty),
            batch_id=line.batch_id or None, bin_id=line.bin_id or None,
        )
        for line in issue.items if _d(line.issued_qty) > ZERO
    ])
    # A parent split before SPLIT existed still reads APPROVED. Its children carry
    # its goods, so posting it as well would take the same stock off the shelf twice.
    live_children = (await db.execute(
        select(m.MaterialIssue.issue_no).where(
            m.MaterialIssue.parent_issue_id == issue.id,
            m.MaterialIssue.status.notin_(UNSERVED_ISSUE_STATUSES))
    )).scalars().all()
    if live_children:
        raise ValidationError(
            f"{issue.issue_no} has been split into {', '.join(live_children)}. Post "
            "those instead — or cancel all of them to post this one.")
    await _assert_issue_floor_access(db, issue, user)

    outward = issue.direction == IssueDirection.OUT.value
    direction = StockDirection.OUT.value if outward else StockDirection.IN.value

    # The last door before stock moves, so the indent cap is asked here too, against
    # every OTHER live issue as it stands NOW. The cap at save time is not enough:
    # a split parent whose floor issues are all cancelled rolls back to APPROVED and
    # counts again, and if a fresh issue was raised for the same indent while it was
    # split, both would otherwise post — the same item issued twice to one indent.
    if outward and issue.items:
        await _guard_issue_indent_caps(db, issue.items, issue.indent_id,
                                       issue.warehouse_id, exclude_issue_id=issue.id)
        await _guard_network_own_stock(db, issue.items, issue.indent_id,
                                       issue.warehouse_id, exclude_issue_id=issue.id)

    # The serial set has to be complete before anything leaves the shelf. Checked
    # here rather than at draft creation: this is the first moment the storekeeper
    # has actually handled the units. Every line is reported at once so a picker
    # holding a trolley is not sent back for one item at a time.
    incomplete = []
    needs_qc = False
    decimals = await uom_rules.decimals_by_code(db, {line.uom_code for line in issue.items})
    for line in issue.items:
        qty = _d(line.issued_qty)
        if qty <= ZERO:
            continue
        item = await _item_snapshot(db, line.item_id)
        if item.requires_qi:
            needs_qc = True
        # A counted unit (Nos, Box, Pack…) goes out whole, serialized or not. Drafts
        # saved before `_apply_issue_lines` checked this still carry 9.5 Nos.
        if (decimals.get(line.uom_code, uom_rules.MAX_DECIMALS) == 0
                and qty != qty.to_integral_value()):
            incomplete.append(
                f"{item.code}: {qty} {line.uom_code} is not a whole number — cancel "
                "this issue and raise it again in whole units")
            continue
        if not item.is_serial_tracked:
            continue
        # int(9.5) is 9, so nine serials used to pass for a line issuing 9.5 and the
        # half unit went out on the ledger. Outward QC then refuses the line forever
        # ("accepted quantity must be a whole number"), because no whole number of
        # serials can account for it. Refused here, the last door before stock moves.
        if qty != qty.to_integral_value():
            incomplete.append(
                f"{item.code}: {qty} is not a whole number of units — a serialized "
                "item is issued in whole units")
            continue
        captured = len(getattr(line, "serial_numbers", None) or [])
        if captured != int(qty) and (captured or await _lot_has_units(
                db, item_id=line.item_id, warehouse_id=issue.warehouse_id,
                batch_id=line.batch_id, bin_id=line.bin_id)):
            # A lot with no recorded units is issued by quantity (2026-10-23).
            incomplete.append(
                f"{item.code}: {captured} of {int(qty)} serial numbers captured")
    if incomplete:
        raise ValidationError(
            "Serial numbers are incomplete — " + "; ".join(incomplete))

    # Which indent each line belongs to. Read per LINE, not off the header: an issue
    # serving a consolidated batch carries lines from many indents, and a reservation
    # is held against the indent that raised it. Using the header here would look for
    # 900 LTs' holds under one requester's id and find nothing.
    line_indents = await _line_indent_ids(db, issue)

    # The units this issue is taking off the shelf, claimed BEFORE anything moves so
    # each ledger row can name the units it carried. Claiming after the moves (where
    # `_mark_serials` sits) would mean the rows were already written and `stk_ledger`
    # is append-only — the codes could never be added to them.
    line_units = await _claim_issue_units(db, issue) if outward else {}

    # A move between two points of the SAME tier is a transfer between peers, not a
    # warehouse issuing down the chain: WH -> WH, MDP -> MDP and LIP -> LIP all belong
    # on the ledger as STO. `inventory.service` already writes exactly that string for
    # a stock transfer order, so the ledger's own filter and its label cover these rows
    # the day they appear — this names the movement, it does not invent a vocabulary.
    #
    # The destination comes from `_requesting_point`, the office-to-stocking-point
    # answer the consignment screens already run on. NOT `indent.warehouse_id`: that
    # column is written by the warehouse when it fulfils, and is NULL on every live
    # indent, so a rule reading it would classify nothing at all.
    #
    # A return (`outward` False) keeps WH_ISSUE. It reverses whatever the issue was and
    # is matched by ref_id, so re-labelling it would only split one document's rows
    # across two ref_types.
    ledger_ref_type = InventoryRefType.WH_ISSUE.value
    if outward:
        source = await db.get(Warehouse, issue.warehouse_id)
        destination = await _requesting_point(db, issue)
        if (source is not None and destination is not None
                and source.id != destination.id
                and source.warehouse_type == destination.warehouse_type):
            ledger_ref_type = InventoryRefType.STO.value

    for line in issue.items:
        qty = _d(line.issued_qty)
        if qty <= ZERO:
            continue
        line_indent_id = line_indents.get(line.id) or issue.indent_id
        units = line_units.get(line.id)

        # An approved allocation reserves concrete stock rows. Consume and issue those
        # exact rows so the hold disappears with the goods, including its bin, batch
        # and project dimensions. Legacy/manual issues with no reservation retain the
        # explicit line location path below.
        if outward and line_indent_id:
            held = await stock_allocation.reserved_quantity(
                db,
                InventoryRefType.RESERVATION.value,
                line_indent_id,
                ref_line_id=line.indent_item_id,
                item_id=line.item_id,
            )
            if held > ZERO:
                held_here = await stock_allocation.reserved_quantity(
                    db,
                    InventoryRefType.RESERVATION.value,
                    line_indent_id,
                    ref_line_id=line.indent_item_id,
                    item_id=line.item_id,
                    warehouse_id=issue.warehouse_id,
                )
                # A point the indent's goods were FORWARDED to (WH -> MDP -> LIP)
                # holds them with no reservation here — that hold was consumed where
                # they came from. It takes what IS reserved here first and the rest
                # from its free stock below; `_guard_network_own_stock` (run above)
                # is what bounds that. Before this, an MDP forwarding goods for an
                # indent that ALSO had a share reserved at the LIP was refused here
                # outright, because "held anywhere > 0" read as "must be held here".
                forwarding_here = held_here < qty and await _forwarding_point(
                    db, line_indent_id, issue.warehouse_id)
                if not forwarding_here:
                    if qty > held:
                        raise ValidationError(
                            f"{line.item_code or line.item_id}: only {held} is allocated "
                            f"against this indent; cannot issue {qty}."
                        )
                    if held_here < qty:
                        raise ValidationError(
                            f"{line.item_code or line.item_id}: {qty} is allocated, but "
                            f"only {held_here} is reserved in "
                            f"{issue.warehouse_name or 'this warehouse'}."
                        )
                from_hold = min(qty, held_here)

                # The hold standing where THIS line says the goods are, first. One
                # allocation held in two bays is served by two issue lines, and an
                # unscoped consume let the first line eat the second line's bay — so
                # the stock left a location the document did not name. Whatever the
                # named location cannot cover falls back to the document's other
                # holds, which is what every unbinned and legacy line relies on.
                slices = await stock_allocation.consume_for_issue(
                    db,
                    InventoryRefType.RESERVATION.value,
                    line_indent_id,
                    quantity=from_hold,
                    ref_line_id=line.indent_item_id,
                    item_id=line.item_id,
                    warehouse_id=issue.warehouse_id,
                    bin_id=line.bin_id or None,
                    batch_id=line.batch_id or None,
                    combination=combo_dict(line),
                ) if from_hold > ZERO else []
                taken = sum((row.quantity for row in slices), ZERO)
                if taken < from_hold:
                    slices = slices + await stock_allocation.consume_for_issue(
                        db,
                        InventoryRefType.RESERVATION.value,
                        line_indent_id,
                        quantity=from_hold - taken,
                        ref_line_id=line.indent_item_id,
                        item_id=line.item_id,
                        warehouse_id=issue.warehouse_id,
                        combination=combo_dict(line),
                    )
                for stock in slices:
                    await move_stock(
                        db, item_id=line.item_id, qty=stock.quantity,
                        direction=StockDirection.OUT.value,
                        ref_type=ledger_ref_type,
                        ref_id=issue.id, ref_no=issue.issue_no, user=user,
                        warehouse_id=stock.warehouse_id,
                        bin_id=stock.bin_id, batch_id=stock.batch_id,
                        project_id=stock.project_id,
                        brand_id=stock.brand_id, variant_id=stock.variant_id,
                        model_id=stock.model_id,
                        serial_numbers=take_units(units, stock.quantity),
                        pack_text=_ledger_packs(line, stock.quantity),
                    )
                qty -= sum((row.quantity for row in slices), ZERO)
                if qty <= ZERO:
                    continue
                # Only a forwarding point gets here with quantity left: the rest of
                # the forwarded goods come off its free stock, below.

        if outward and not line_indent_id:
            # A direct issue's own hold (`_hold_direct_issue_stock`): consumed and
            # moved off exactly the balance rows it reserved, as an allocation's is.
            # Drafts saved before the hold existed carry none and fall through to the
            # free-stock path below for whatever is not covered.
            held_slices = await stock_allocation.consume_for_issue(
                db, InventoryRefType.ISSUE_HOLD.value, issue.id, quantity=qty,
                ref_line_id=line.id, item_id=line.item_id,
                warehouse_id=issue.warehouse_id, combination=combo_dict(line))
            for stock in held_slices:
                await move_stock(
                    db, item_id=line.item_id, qty=stock.quantity,
                    direction=StockDirection.OUT.value, ref_type=ledger_ref_type,
                    ref_id=issue.id, ref_no=issue.issue_no, user=user,
                    warehouse_id=stock.warehouse_id, bin_id=stock.bin_id,
                    batch_id=stock.batch_id, project_id=stock.project_id,
                    brand_id=stock.brand_id, variant_id=stock.variant_id,
                    model_id=stock.model_id,
                    serial_numbers=take_units(units, stock.quantity),
                    pack_text=_ledger_packs(line, stock.quantity),
                )
            qty -= sum((row.quantity for row in held_slices), ZERO)
            if qty <= ZERO:
                continue

        if outward and issue.project_id:
            # A line with no indent reservation draws off `available_qty`; a lot held
            # for this issue's project is set aside FOR it, so hand that back first.
            await stock_allocation.take_from_holds(
                db, item_id=line.item_id, project_id=issue.project_id, qty=qty,
                ref_type=None, ref_id=None, ref_no=None, ref_line_id=None, user=user,
                warehouse_ids=[issue.warehouse_id],
                bin_id=line.bin_id if line.bin_id else None,
                batch_id=line.batch_id if line.batch_id else None,
                combination=combo_dict(line))
        if outward:
            # Where this line's goods actually sit, not where the line says they do.
            # A forwarded consignment has no reservation at THIS point (the hold was
            # consumed at the warehouse that dispatched it), so it lands here with the
            # bin and batch it was allocated under upstream — usually none at all.
            # `stk_balance` is keyed on (item, warehouse, bin, batch, project), so a
            # line still carrying batch 0 looked up a row that does not exist and the
            # issue failed for "no stock" while the goods sat one key away.
            for source_bin, source_batch, source_project, slice_qty, source_combo in (
                    await _issue_slices(db, issue, line, qty)):
                await move_stock_out(
                    db, item_id=line.item_id, qty=slice_qty,
                    ref_type=ledger_ref_type,
                    ref_id=issue.id, ref_no=issue.issue_no, user=user,
                    warehouse_id=issue.warehouse_id,
                    bin_id=source_bin, batch_id=source_batch,
                    project_id=source_project,
                    **(source_combo or {}),
                    serial_numbers=take_units(units, slice_qty),
                    pack_text=_ledger_packs(line, slice_qty),
                )
        else:
            await move_stock(
                db, item_id=line.item_id, qty=qty, direction=direction,
                ref_type=ledger_ref_type,
                ref_id=issue.id, ref_no=issue.issue_no,
                user=user, warehouse_id=issue.warehouse_id,
                bin_id=line.bin_id or m.NO_BIN, batch_id=line.batch_id or m.NO_BATCH,
                project_id=issue.project_id or 0,
                brand_id=line.brand_id or 0, variant_id=line.variant_id or 0,
                model_id=line.model_id or 0,
            )

    if outward:
        # Whole boxes leave under their codes; part of a box leaves as a new part
        # box with a new code, and the shelf box keeps its own (2026-10-26).
        await box_codes.settle_on_post(db, issue, user)
    await _mark_serials(db, issue, outward)
    if outward:
        # The packs follow the units out (2026-10-08): emptied packs are consumed, a
        # part-taken one is opened and what stays is packed again, and every pack
        # around a changed one opens.
        await wh_packing.settle_issue(db, issue, await _issue_units_by_line(db, issue),
                                      user)
    if outward and issue.project_id:
        from app.modules.warehouse.project_holds import clear_spent_unit_stamps
        await clear_spent_unit_stamps(
            db, issue.project_id, {line.item_id for line in issue.items})
    if not outward and issue.original_issue_id:
        original = await get_issue(db, issue.original_issue_id)
        _apply_issue_return(issue, original)

    issue.is_stock_posted = True
    issue.posted_at = utcnow()
    issue.issued_by_id = getattr(user, "id", None)
    issue.issued_by_name = _name(user)
    issue.status = IssueStatus.ISSUED.value
    # Outward QC follows the ITEM (2026-10-07). An issue is inspected only when at least
    # one of its lines carries an item that `requires_qi`, and the sheet holds only those
    # lines (`_raise_outbound_inspection_for`); the rest go to logistics at their issued
    # quantity. An issue with no such line is NOT_REQUIRED and is consignable at once —
    # forcing every outward issue through QC held goods nobody had asked to inspect.
    issue.qc_status = QcStatus.PENDING.value if needs_qc else QcStatus.NOT_REQUIRED.value

    if needs_qc and outward:
        await _raise_outbound_inspection_for(db, issue, user)

    if outward:
        await _raise_picking_for_issue(db, issue, user)

    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"is_stock_posted": False},
                      after={"is_stock_posted": True, "status": issue.status,
                             "qc_status": issue.qc_status,
                             "total_qty": str(issue.total_qty)})
    await _sync_split_parent(db, issue.parent_issue_id, user)
    await db.commit()
    return await get_issue(db, issue_id)


def _validate_issue_return(issue: m.MaterialIssue, original: m.MaterialIssue) -> None:
    """Cap an inbound return at what remains outstanding on the original issue."""
    if issue.warehouse_id != original.warehouse_id:
        raise ValidationError(
            f"Return the material to {original.warehouse_name or 'the issuing warehouse'}"
        )
    outstanding: dict[int, Decimal] = {}
    for line in original.items:
        outstanding[line.item_id] = (
            outstanding.get(line.item_id, ZERO)
            + _d(line.issued_qty)
            - _d(line.returned_qty)
        )
    returning: dict[int, Decimal] = {}
    for line in issue.items:
        returning[line.item_id] = returning.get(line.item_id, ZERO) + _d(line.issued_qty)
    for item_id, qty in returning.items():
        allowed = outstanding.get(item_id, ZERO)
        if qty > allowed:
            raise ValidationError(
                f"Item {item_id}: only {allowed} remains returnable against "
                f"{original.issue_no}; cannot return {qty}."
            )


def _validate_picking_issue(issue: m.MaterialIssue, picking: m.Picking) -> None:
    picked: dict[tuple[int, int, int], Decimal] = {}
    for line in picking.items:
        key = (line.item_id, line.bin_id or 0, line.batch_id or 0)
        picked[key] = picked.get(key, ZERO) + _d(line.picked_qty)
    issuing: dict[tuple[int, int, int], Decimal] = {}
    for line in issue.items:
        key = (line.item_id, line.bin_id or 0, line.batch_id or 0)
        issuing[key] = issuing.get(key, ZERO) + _d(line.issued_qty)
    for key, qty in issuing.items():
        if qty > picked.get(key, ZERO):
            raise ValidationError(
                f"Item {key[0]}: issue quantity {qty} exceeds the {picked.get(key, ZERO)} "
                f"picked on {picking.pick_no}."
            )


def _apply_issue_return(issue: m.MaterialIssue, original: m.MaterialIssue) -> None:
    """Apply posted inbound quantities to the original issue's accountability."""
    for returned in issue.items:
        remaining = _d(returned.issued_qty)
        for original_line in original.items:
            if original_line.item_id != returned.item_id or remaining <= ZERO:
                continue
            open_qty = _d(original_line.issued_qty) - _d(original_line.returned_qty)
            take = min(open_qty, remaining)
            original_line.returned_qty = _d(original_line.returned_qty) + take
            remaining -= take

    fully_returned = all(
        _d(line.returned_qty) >= _d(line.issued_qty) for line in original.items
    )
    original.status = (
        IssueStatus.RETURNED.value
        if fully_returned
        else IssueStatus.PARTIALLY_RETURNED.value
    )


def _shipped_unit_marker(doc: str, doc_id: int) -> str:
    """The remark that ties a unit to the document currently carrying it.

    A unit in flight belongs to exactly one document, and this string is the link.
    `credit_arrival` reads it back at the far end to know which units to shelve.
    """
    return f"Issued by {doc} {doc_id}"


#: Remarks that mean "this unit is already spoken for by another document". A unit
#: carrying one of these must never be auto-picked for a second one.
#: The stamp a project hold puts on the exact units it names. Claimed, so every
#: picker and auto-claim skips them; only that project's issue may name them.
PROJECT_HOLD_UNIT_PREFIX = "Held for project "


def project_hold_unit_marker(project_id: int, hold_id: int) -> str:
    return f"{PROJECT_HOLD_UNIT_PREFIX}{project_id} by hold {hold_id}"


_CLAIMED_REMARK_PREFIXES = ("Reserved for issue ", "Issued by ", PROJECT_HOLD_UNIT_PREFIX)


async def _claim_units(
    db: AsyncSession,
    *,
    item_id: int,
    warehouse_id: int,
    qty,
    marker: str,
    batch_id: int | None = None,
    bin_id: int | None = None,
    top_up: bool = True,
) -> list[m.SerialNumber]:
    """Reserve up to `qty` of this item's units at this warehouse under `marker`.

    Rows already carrying `marker` are counted first — those are the ones the
    storekeeper picked by hand on the issue screen, and his choice always stands. The
    shortfall is topped up FIFO (oldest row id first) from what is free at that
    warehouse, skipping anything another document has already claimed.

    BEST EFFORT BY DESIGN. It returns fewer rows than asked rather than raising when
    the warehouse holds fewer coded units than the quantity being shipped, which is
    the normal case for stock that predates unit coding and for bulk goods that never
    had units at all. A missing identity row must never stop real goods from moving —
    the quantity is the stock record, the unit row is a label on it. Callers that DO
    require a complete set (serial-tracked items) check the count themselves.
    """
    wanted = int(_d(qty))
    if wanted <= 0:
        return []

    def _scoped(stmt):
        stmt = stmt.where(
            m.SerialNumber.item_id == item_id,
            m.SerialNumber.warehouse_id == warehouse_id,
            m.SerialNumber.is_active.is_(True),
        )
        # Only narrow by batch/bin when the document actually named one. A line that
        # names neither means "whatever is on the shelf", exactly as move_stock_out
        # reads an unspecified bin.
        if batch_id:
            stmt = stmt.where(m.SerialNumber.batch_id == batch_id)
        if bin_id:
            stmt = stmt.where(m.SerialNumber.bin_id == bin_id)
        return stmt

    mine = list((await db.execute(
        _scoped(select(m.SerialNumber)).where(
            m.SerialNumber.status == SerialStatus.AVAILABLE.value,
            m.SerialNumber.remarks == marker,
        ).order_by(m.SerialNumber.id).with_for_update()
    )).scalars().all())
    if len(mine) >= wanted or not top_up:
        # `top_up=False` is how a serialized item says "the scanned set is the set".
        # Which physical serial left the building is a fact the storekeeper establishes
        # by reading the label, never something this function may decide for him.
        return mine[:wanted]

    free = (await db.execute(
        _scoped(select(m.SerialNumber)).where(
            m.SerialNumber.status == SerialStatus.AVAILABLE.value,
            # AND of the negations, not OR: "Reserved for issue 5" does not start with
            # "Issued by ", so an OR here would have declared every claimed unit free
            # and handed the same code to two documents.
            or_(m.SerialNumber.remarks.is_(None),
                and_(*[~m.SerialNumber.remarks.startswith(prefix)
                       for prefix in _CLAIMED_REMARK_PREFIXES])),
        # Loose units first, then PART packs (2026-10-11 — a carton already short is
        # used up before a full one is touched), then pack by pack (2026-10-08). Packs
        # are created smallest-first at putaway, so this empties strips before it
        # opens a box and takes whole packs wherever the quantity allows — a pick lands
        # on at most one part pack, which is the one a coded item's break bulk has to
        # answer for.
        ).order_by(m.SerialNumber.handling_unit_id.is_not(None),
                   select(case((m.HandlingUnit.content_qty.is_(None), 1), else_=0))
                   .where(m.HandlingUnit.id == m.SerialNumber.handling_unit_id)
                   .correlate(m.SerialNumber).scalar_subquery(),
                   m.SerialNumber.handling_unit_id, m.SerialNumber.id)
        .limit(wanted - len(mine))
        .with_for_update()
    )).scalars().all()
    # One statement for the whole top-up, not one per unit claimed.
    await _set_unit_fields(db, [row.id for row in free], remarks=marker)
    mine.extend(free)
    return mine


async def _land_units(
    db: AsyncSession,
    *,
    markers: tuple[str, ...],
    item_id: int,
    qty,
    to_warehouse_id: int,
    ref_no: str | None,
) -> list[str]:
    """Shelve the units a consignment carried at the point that received it.

    THE missing half of the unit's journey. `_place_unit_codes` mints a unit at the
    warehouse that first receives the goods and deliberately never mints another one
    downstream — "what an MDP or a LIP inwards is that same unit arriving, already
    carrying its code". Nothing ever moved it, so every unit row in the database sat
    at the warehouse that received it while the quantity it names had long since been
    shipped on. An MDP showed five units of stock and a dash where their codes belong,
    and the source warehouse could pick the same code again the next morning.

    The unit is re-homed, not copied: one physical thing, one row, one code, moving
    from shelf to shelf. `bin_id` is cleared because a stocking point has no bins —
    that is what makes it a stocking point — and the row must key as bulk to sit
    beside the `stk_balance` row the same arrival creates.

    Returns the codes it shelved, so the caller can name them on the ledger row.
    """
    wanted = int(_d(qty))
    if wanted <= 0:
        return []
    rows = (await db.execute(
        select(m.SerialNumber).where(
            m.SerialNumber.item_id == item_id,
            m.SerialNumber.status == SerialStatus.ISSUED.value,
            m.SerialNumber.remarks.in_(markers),
            m.SerialNumber.is_active.is_(True),
        ).order_by(m.SerialNumber.id).limit(wanted).with_for_update()
    )).scalars().all()

    item = await db.get(Item, item_id)
    mode = _unit_mode(item)
    codes: list[str] = []
    for row in rows:
        keys = _unit_keys(row, mode)
        if keys:
            codes.append(keys[0])
    # Same four columns for every unit on the consignment, so one statement per chunk.
    await _set_unit_fields(
        db, [row.id for row in rows],
        warehouse_id=to_warehouse_id,
        bin_id=None,
        status=SerialStatus.AVAILABLE.value,
        remarks=(f"Received by {ref_no}" if ref_no else None),
    )
    await db.flush()
    return codes


async def _ship_units(
    db: AsyncSession,
    *,
    item_id: int,
    warehouse_id: int,
    qty,
    marker: str,
    batch_id: int | None = None,
) -> list[str]:
    """Claim units and send them out the gate in one step, returning their codes.

    For the door where there is no issue to hang them on — a consignment raised and
    gated out directly. `post_issue` keeps the two steps apart instead, because it has
    to name the units on its ledger rows before `_mark_serials` flips them.
    """
    rows = await _claim_units(
        db, item_id=item_id, warehouse_id=warehouse_id, qty=qty,
        marker=marker, batch_id=batch_id,
    )
    item = await db.get(Item, item_id)
    mode = _unit_mode(item)
    codes: list[str] = []
    for row in rows:
        keys = _unit_keys(row, mode)
        if keys:
            codes.append(keys[0])
    # Reading the codes is per row because each unit's is its own; WRITING is one
    # statement per chunk, because the status and the stamp are the same for all.
    await _set_unit_fields(db, [row.id for row in rows],
                           status=SerialStatus.ISSUED.value, remarks=marker)
    await db.flush()
    return codes


async def _claim_issue_units(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> dict[int, list[str]]:
    """Reserve the units each outward line is about to ship, and name them.

    The storekeeper's own picks are already stamped by `_reserve_issue_serials` when
    he scans them on the issue screen; this tops the line up to its full issued
    quantity from what is free at the warehouse. Most lines name nothing at all — a
    consolidated fulfilment draft is created for the storekeeper by inventory, which
    approves quantities and has no screen on which to say which physical units — and
    those lines are exactly the ones that used to ship with their codes left behind.

    Returns `{line_id: [code, ...]}` in the currency the item names its units with, for
    the ledger rows the caller is about to write.
    """
    claimed: dict[int, list[str]] = {}
    for line in issue.items:
        qty = _d(line.issued_qty)
        if qty <= ZERO:
            continue
        item = await _item_snapshot(db, line.item_id)
        mode = _unit_mode(item)
        if await box_codes.has_boxes(db, issue.id, line.id):
            # Issued in boxes (2026-10-26): what left is the boxes; the ledger names
            # them, and nothing is topped up from loose stock beside them.
            boxes = await box_codes.line_boxes(db, issue.id, line.id)
            if boxes:
                claimed[line.id] = [box.hu_code for box in boxes]
            continue
        rows = await _claim_units(
            db,
            item_id=line.item_id,
            warehouse_id=issue.warehouse_id,
            qty=qty,
            marker=_issue_line_serial_marker(issue.id, line.id),
            batch_id=line.batch_id or None,
            bin_id=line.bin_id or None,
            # A serialized line ships exactly the serials the storekeeper scanned.
            # `post_issue` has already refused the issue unless he captured one per
            # unit, so there is never a shortfall here worth guessing at.
            top_up=(mode != UNIT_MODE_SERIAL),
        )
        codes = [keys[0] for keys in
                 (_unit_keys(row, mode) for row in rows) if keys]
        if codes:
            claimed[line.id] = codes
    await db.flush()
    return claimed


async def _adopt_legacy_issue_reservations(
    db: AsyncSession, issue: m.MaterialIssue,
) -> None:
    """Re-stamp any unit still held under the old document-level reservation.

    An issue drafted before reservations became per-line carries rows marked
    `Reserved for issue 72` with no line on them. `_mark_serials` reads per line now,
    so without this a document already sitting in approval would post to "0 are
    reserved for this issue". The rows are handed to the lines of that item in line
    order, each taking at most its issued quantity — the same rule
    `_issue_units_by_line` reads them by, applied once and written down.
    """
    legacy = (await db.execute(
        select(m.SerialNumber).where(
            m.SerialNumber.remarks == _issue_serial_marker(issue.id)
        ).order_by(m.SerialNumber.id).with_for_update()
    )).scalars().all()
    if not legacy:
        return
    pool: dict[int, list[m.SerialNumber]] = {}
    for row in legacy:
        pool.setdefault(row.item_id, []).append(row)
    for line in issue.items:
        rows = pool.get(line.item_id)
        if not rows:
            continue
        room = int(_d(line.issued_qty))
        await _set_unit_fields(db, [row.id for row in rows[:room]],
                               remarks=_issue_line_serial_marker(issue.id, line.id))
        del rows[:room]
    await db.flush()


async def _lot_has_units(db: AsyncSession, *, item_id: int, warehouse_id: int | None,
                         batch_id: int | None = None, bin_id: int | None = None) -> bool:
    """Does this lot hold any recorded unit — a serial, IMEI or code — at all?

    Since the same-code consolidation (2026-10-23) one item can hold stock that was
    serial-tracked (one brand's) beside stock that never had a number recorded (a
    sibling that was not tracked). Demanding a number per unit from a lot that holds
    none asks for something that does not exist, so the rule applies per LOT: a lot
    with no recorded units is issued and moved by quantity. A bounded EXISTS, never a
    COUNT over the unit table. 0/None on batch or bin means "any".
    """
    probe = select(literal(1)).select_from(m.SerialNumber).where(
        m.SerialNumber.item_id == item_id,
        m.SerialNumber.is_active == 1,
        m.SerialNumber.status == SerialStatus.AVAILABLE.value)
    if warehouse_id:
        probe = probe.where(m.SerialNumber.warehouse_id == warehouse_id)
    if batch_id:
        probe = probe.where(m.SerialNumber.batch_id == batch_id)
    else:
        # Batch 0 is "any batch" on a document, but where unbatched stock really stands
        # at this point it is a lot of its own — the untracked sibling's — and only
        # ITS units count. Without unbatched stock, any batch's units do.
        from app.modules.inventory.models import Stock
        unbatched = await db.scalar(select(literal(1)).select_from(Stock).where(
            Stock.item_id == item_id, Stock.warehouse_id == warehouse_id,
            Stock.batch_id == 0, Stock.total_qty > 0).limit(1)) if warehouse_id else None
        if unbatched:
            probe = probe.where(or_(m.SerialNumber.batch_id.is_(None),
                                    m.SerialNumber.batch_id == 0))
    if bin_id:
        probe = probe.where(m.SerialNumber.bin_id == bin_id)
    return bool(await db.scalar(probe.limit(1)))


async def _unit_codes_required(db: AsyncSession, item, *, config: dict | None = None) -> bool:
    """Must an issue of this item name one identifier per unit before it may post?

    Until 2026-09-10 only `is_serial_tracked` did. An asset tag and a consumable lot
    code are the same promise — one label, one physical thing — so an asset issued
    without its tags left the building with nothing tying the goods to the document,
    and the gap showed up only when somebody went looking for a unit months later.

    The rule MIRRORS THE MINT, deliberately: the conditions are exactly the ones
    `_place_unit_codes` uses to decide whether to give these units codes at putaway —
    the item master's code toggle (`codeformat.is_code_tracked`) and countability.
    If putaway would have coded them, the issue must name them; if it would not,
    there is nothing to name and nothing is demanded. Any other pairing has one door
    minting labels the other never asks for, or asks for labels nothing mints.

    Serial and IMEI are declared on the item master directly and are unconditional —
    they are what the manufacturer stamped, and a countability check has no business
    overruling that.
    """
    if bool(getattr(item, "is_serial_tracked", False)):
        return True
    if bool(getattr(item, "is_imei_tracked", False)):
        return True
    if not codeformat.is_code_tracked(item, config or await codeformat.code_settings(db)):
        return False
    return await _is_countable(db, item)


async def _mark_serials(db: AsyncSession, issue: m.MaterialIssue, outward: bool) -> None:
    """Flips the status of the units leaving or coming back with an issue.

    Runs for EVERY item that names its units, not just serial-tracked ones. It used
    to skip anything without `is_serial_tracked`, which meant a coded consumable's
    units stayed `available` at the source warehouse after they had physically left —
    so the picker offered the same code again on the next issue. The set is still only
    ENFORCED for serial-tracked items, where the storekeeper is required to capture
    one serial per unit; a coded item takes what units it has.
    """
    new_status = (SerialStatus.ISSUED if outward else SerialStatus.RETURNED).value
    from_status = (SerialStatus.AVAILABLE if outward else SerialStatus.ISSUED).value
    await _adopt_legacy_issue_reservations(db, issue)
    # Five queries, read once for the document: the toggle cannot differ between two
    # lines of one issue.
    code_config = await codeformat.code_settings(db)

    for line in issue.items:
        item = await _item_snapshot(db, line.item_id)
        wanted = int(_d(line.issued_qty))
        if wanted <= 0:
            continue
        # This LINE's units, by its own stamp. Keyed on the document before, so an
        # issue carrying the same item twice weighed both lines' reservations against
        # one line's quantity and refused itself with "N serials are required, but M
        # are reserved for this issue".
        rows = (await db.execute(
            select(m.SerialNumber).where(
                m.SerialNumber.item_id == line.item_id,
                m.SerialNumber.warehouse_id == issue.warehouse_id,
                m.SerialNumber.status == from_status,
                m.SerialNumber.remarks == _issue_line_serial_marker(issue.id, line.id),
                m.SerialNumber.is_active.is_(True))
            .with_for_update()
        )).scalars().all()
        # Every kind of identifier the master declares, not just the serial. The noun
        # follows the kind, so an asset line is not told it is missing "serials".
        if (await _unit_codes_required(db, item, config=code_config)
                and len(rows) != wanted
                # Issued in boxes: the boxes are what was checked (2026-10-26).
                and not await box_codes.has_boxes(db, issue.id, line.id)
                # A lot with no recorded units is issued by quantity (2026-10-23).
                and (rows or await _lot_has_units(
                    db, item_id=line.item_id, warehouse_id=issue.warehouse_id,
                    batch_id=line.batch_id, bin_id=line.bin_id))):
            noun = _UNIT_NOUN[_unit_mode(item)]
            raise ValidationError(
                f"{line.item_code or line.item_id}: {wanted} {noun} are required, "
                f"but {len(rows)} are reserved for this issue"
            )
        if (outward and len(rows) < wanted and await box_codes.has_boxes(db, issue.id, line.id)
                and await _lot_has_units(db, item_id=line.item_id,
                                         warehouse_id=issue.warehouse_id,
                                         batch_id=line.batch_id, bin_id=line.bin_id)):
            # Boxes are what was checked, so this is not refused — but a lot holding
            # codes that ships boxes with fewer codes inside than they carry leaves
            # codes behind at the source, and that must never be silent again.
            logger.warning("issue %s line %s ships %s in boxes with only %s unit codes "
                           "inside; the rest stay at warehouse %s",
                           issue.issue_no, line.id, wanted, len(rows), issue.warehouse_id)
        # The flip is the same two columns for every unit on the line, so it is one
        # statement per chunk rather than one per unit. This is the path a 10,000-unit
        # issue actually posts through.
        await _set_unit_fields(
            db,
            [row.id for row in rows[:wanted]],
            status=new_status,
            remarks=(_shipped_unit_marker("issue", issue.id) if outward
                     else f"Returned by issue {issue.id}"),
        )
    await db.flush()


async def _dispatch_for_issue(db: AsyncSession, issue_id: int) -> m.Dispatch | None:
    """The consignment carrying this issue, if one was ever raised for it."""
    # Eager-loaded: `acknowledge_issue` books delivered quantities onto these lines,
    # and a lazy load on an async session raises MissingGreenlet.
    return (await db.execute(
        select(m.Dispatch).options(selectinload(m.Dispatch.items)).where(
            _carries_issue(issue_id),
            m.Dispatch.status != DispatchStatus.CANCELLED.value,
        ).limit(1)
    )).scalar_one_or_none()


async def _close_indents_on_issue(db: AsyncSession, issue: m.MaterialIssue, user) -> None:
    """Close every indent this issue served, not just the one on its header.

    An issue that covers a consolidated batch names one indent on the header and the
    rest on its lines. Closing only the header's would leave the other requesters'
    indents sitting at ALLOCATED forever, with the goods already in their hands. For a
    single-indent issue this is the same one call it always was.
    """
    for indent_id in await _indent_ids_on_issue(db, issue):
        await _close_indent_if_delivered(db, indent_id, user)


async def _close_indent_if_delivered(db: AsyncSession, indent_id: int | None, user) -> None:
    """Move the indent on once everything issued against it has been received.

    Acknowledgement used to stop at the issue: the indent behind it sat at
    ALLOCATED forever, so nothing on any screen ever showed a request as finished.
    An indent is only closed when no live issue against it is still outstanding AND
    nothing is still owed on it.
    """
    if not indent_id:
        return
    from app.modules.indents.models import Indent
    indent = await db.get(Indent, indent_id)
    if indent is None or indent.status in (
        IndentStatus.CLOSED.value, IndentStatus.REJECTED.value,
    ):
        return
    outstanding = await db.scalar(
        select(func.count(m.MaterialIssue.id)).where(
            m.MaterialIssue.indent_id == indent_id,
            m.MaterialIssue.direction == IssueDirection.OUT.value,
            m.MaterialIssue.status.notin_(
                (*DEAD_ISSUE_STATUSES, IssueStatus.ACKNOWLEDGED.value)
            ),
        )
    )
    if outstanding:
        return

    # A part-served indent is not finished just because the issue carrying that part
    # was acknowledged. An approver who gives 13 of the 20 asked for leaves 7 owed, and
    # that remainder still has to reach the Fulfilment Queue for a second allocation.
    # Closing ended it instead: CLOSED is not in `_ALLOCATION_ELIGIBLE_STATUSES`, so
    # the allocate screen answered "this indent is closed — there is nothing to
    # allocate" and the 7 was lost with the first 13 already in the requester's hands.
    #
    # Only the closing is withheld. The status the allocation path already set
    # (PARTIALLY_FULFILLED, or PENDING_APPROVAL while the remainder is still climbing)
    # is left exactly as it is — both are allocation-eligible and both already list in
    # the queue, so the remainder rejoins the ordinary flow with nothing else touched.
    #
    # `_committed_by_line` is the same arithmetic `list_indents(has_remainder=True)`
    # runs, so the queue and this check can never disagree about whether a request is
    # finished.
    from app.modules.indents.models import IndentItem
    from app.modules.indents.service import _committed_by_line, owed_quantity

    committed = await _committed_by_line(db, indent_id)
    owed_lines = (await db.execute(
        select(IndentItem).where(IndentItem.indent_id == indent_id)
    )).scalars().all()
    # "And something actually covers it", the same half `approvals.service._nothing_owed`
    # carries and for the same reason: an indent issued without ever passing through an
    # allocation has 0 allocated against a full approved quantity, which reads as
    # entirely unserved. Those close on the acknowledgement exactly as they always did —
    # the remainder guard below only speaks for indents the allocation flow has touched.
    covered = sum(
        (_d(line.allocated_quantity) + committed.get(line.id, ZERO)
         for line in owed_lines),
        ZERO,
    )
    if covered > ZERO and any(
        owed_quantity(line) - _d(line.allocated_quantity)
        - committed.get(line.id, ZERO) > ZERO
        for line in owed_lines
    ):
        return

    before_status = indent.status
    indent.status = IndentStatus.CLOSED.value
    from app.modules.indents.service import notify_indent_followers
    await notify_indent_followers(db, indent, indent.status)
    await write_audit(db, entity="ind_indents", entity_id=indent.id,
                      entity_no=indent.indent_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": before_status},
                      after={"status": indent.status})


async def _apply_issue_acknowledgement(db: AsyncSession, issue: m.MaterialIssue,
                                       by_name: str | None, remarks: str | None,
                                       user, *,
                                       received_by_item: dict[int, Decimal] | None = None,
                                       box_received: dict | None = None,
                                       ) -> None:
    """Sign the issue off and carry the signature onto what it was attached to.

    `received_by_item` is what the receiver COUNTED, per item. Without it every line is
    taken as delivered in full; with it the consignment lines are stamped with the
    count, so `credit_arrival` books 6 on the shelf when 6 of 10 arrived (SCM_0013).

    Does not commit and writes no audit row: both callers are mid-transaction and own
    their own audit trail.
    """
    issue.status = IssueStatus.ACKNOWLEDGED.value
    issue.acknowledged_by_name = by_name
    issue.acknowledged_at = utcnow()
    if remarks:
        issue.remarks = f"{issue.remarks or ''}\nReceiver: {remarks}".strip()

    # The receiver signs once. Leaving the consignment at DISPATCHED afterwards
    # made the dispatch board disagree with the issue it was carrying, and no
    # dispatch in the live data ever reached acknowledged_at.
    dispatch = await _dispatch_for_issue(db, issue.id)
    if dispatch is not None and dispatch.status in (
        DispatchStatus.DISPATCHED.value, DispatchStatus.IN_TRANSIT.value,
        DispatchStatus.DELIVERED.value,
    ):
        carried = await _dispatch_issue_ids(db, dispatch)
        grouped = len(carried) > 1
        # The requester has already confirmed every quantity carried by this issue
        # (_receiver_confirmed is the caller's guard). Keep the linked consignment's
        # line evidence in sync when the warehouse signs off through the issue page —
        # without it `out_dispatch_items.delivered_qty` stays 0 forever, and the
        # Journey's Delivery phase sits PENDING on an indent that is already closed.
        # Only THIS issue's lines: on a grouped consignment the other issues' goods are
        # somebody else's confirmation, still to come.
        budget = ({k: _d(v) for k, v in received_by_item.items()}
                  if received_by_item is not None else None)
        for line in _lines_for_issue(dispatch, issue.id, grouped=grouped):
            if budget is None:
                line.delivered_qty = _d(line.quantity)
            else:
                got = max(ZERO, min(_d(line.quantity), budget.get(line.item_id, ZERO)))
                budget[line.item_id] = budget.get(line.item_id, ZERO) - got
                line.delivered_qty = got
        # A package row records what arrived in THAT package (2026-10-26).
        box_codes.apply_package_receipts(
            _lines_for_issue(dispatch, issue.id, grouped=grouped), box_received)
        others_open = grouped and bool(await db.scalar(
            select(func.count(m.MaterialIssue.id)).where(
                m.MaterialIssue.id.in_([issue_id for issue_id in carried
                                        if issue_id != issue.id]),
                m.MaterialIssue.status.in_(
                    (IssueStatus.ISSUED.value, IssueStatus.DISPATCHED.value)),
            )
        ))
        if not others_open:
            dispatch.status = DispatchStatus.ACKNOWLEDGED.value
            dispatch.acknowledged_by_name = issue.acknowledged_by_name
            dispatch.acknowledged_at = issue.acknowledged_at
            dispatch.delivered_at = dispatch.delivered_at or issue.acknowledged_at

    # Signing here is the same physical event as signing on the consignment screen, so
    # it owes the same inward movement. Without this the LIP storekeeper confirmed his
    # delivery through the indent page, the issue and the consignment both read
    # ACKNOWLEDGED, and his inventory stayed empty — the goods in his hands existed on
    # no shelf in the system. Runs for a consignment that was ALREADY acknowledged too
    # (the `if` above only re-stamps the in-transit ones): `credit_arrival` is
    # idempotent on the ledger, so the credit lands exactly once whichever door ran first.
    if dispatch is not None:
        await credit_arrival(db, dispatch, user)

    await _close_indents_on_issue(db, issue, user)


# On the road: the units are genuinely out and can be credited as they are confirmed.
# DRAFT/PACKED consignments are still being built — nothing has physically moved, and
# stamping a delivery on one would invent an arrival. ACKNOWLEDGED is deliberately out
# too: that consignment was counted and signed for line by line, and a short delivery
# recorded there is evidence a later receipt must not quietly write over.
_STAMPABLE_DISPATCH_STATUSES = (
    DispatchStatus.DISPATCHED.value, DispatchStatus.IN_TRANSIT.value,
    DispatchStatus.DELIVERED.value,
)


def _stamp_confirmed_delivery(dispatch: m.Dispatch,
                              caps: dict[int, Decimal],
                              lines: list | None = None) -> bool:
    """Book what the requester has confirmed onto the consignment's own lines.

    `credit_arrival` reads `delivered_qty` — it credits what ARRIVED, never what was
    loaded — and on a partial receipt nothing had written that column yet: it is
    stamped when the issue finally settles (`_apply_issue_acknowledgement`), when a
    DELIVERED event is recorded, or when the consignment is acknowledged line by line.
    So the partial credit added alongside `_issue_confirmation_caps` capped a base
    quantity of zero and posted nothing: 1 of 2 confirmed left `delivered_qty` at 0,
    no DISPATCH IN row on `stk_ledger`, and no stock at the destination until the
    second unit turned up.

    The confirmation IS the arrival evidence for those units, so it is written here,
    spending each item's confirmed quantity across that item's lines in packing order
    — the same greedy per-item spend `credit_arrival` runs over the lots, so the two
    can never disagree on a total. Only ever upward: a line already carrying a
    delivered quantity (a counted acknowledgement, a delivery event) keeps it, because
    a receipt trickling in must never talk a recorded arrival back down.

    Returns whether anything moved, so the caller stamps `delivered_at` only on a
    consignment that really did land something.
    """
    remaining = {item_id: _d(qty) for item_id, qty in caps.items()}
    stamped = False
    # `lines` narrows it to one issue's lines on a grouped consignment, where the same
    # item can be packed for two issues and only one of them is being confirmed.
    for line in (dispatch.items if lines is None else lines):
        left = remaining.get(line.item_id, ZERO)
        if left <= ZERO:
            continue
        booked = min(_d(line.quantity), left)
        remaining[line.item_id] = left - booked
        if booked > _d(line.delivered_qty):
            line.delivered_qty = booked
            stamped = True
    return stamped


async def auto_acknowledge_for_indent(db: AsyncSession, indent_id: int,
                                      user, *, condition: str | None = None,
                                      remarks: str | None = None,
                                      fully_received: bool = False,
                                     box_received: dict | None = None) -> list[str]:
    """Sign off every open issue serving this indent that the raiser has now confirmed.

    The warehouse used to click Acknowledge a second time after the requester had
    already recorded what reached them in Acknowledgements — the same fact, entered
    twice, with the indent sitting open until somebody remembered the second click.
    `_receiver_confirmed` was always the real test, so the moment it passes the issue
    signs itself off in the requester's name.

    Called from `indents.acknowledge_receipt` inside its transaction, so this neither
    commits nor audits: the receipt that made the confirmation true and the
    acknowledgement it triggers have to land together or not at all. Returns the issue
    numbers it closed, for the caller's audit row.
    """
    from app.modules.indents.models import IndentItem

    line_issues = select(m.MaterialIssueLine.issue_id).join(
        IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id
    ).where(IndentItem.indent_id == indent_id)

    # Eager-loaded: `_receiver_confirmed` walks `issue.items`, and a lazy load on an
    # async session raises MissingGreenlet.
    issues = (await db.execute(
        select(m.MaterialIssue)
        .options(selectinload(m.MaterialIssue.items))
        .where(
            m.MaterialIssue.status.in_(
                (IssueStatus.ISSUED.value, IssueStatus.DISPATCHED.value)),
            or_(m.MaterialIssue.indent_id == indent_id,
                m.MaterialIssue.id.in_(line_issues)),
        )
    )).scalars().all()

    signed: list[str] = []
    settled: set[int] = set()
    for issue in issues:
        # A consolidated issue serves several indents. Only the one whose raiser has
        # confirmed everything it carried is settled — the rest keep it open.
        if not await _receiver_confirmed(db, issue):
            continue
        await _apply_issue_acknowledgement(db, issue, _name(user), None, user,
                                           box_received=box_received)
        signed.append(issue.issue_no)
        settled.add(issue.id)

    # FIXED 2026-08-22 (P1) — an issue that is only PARTLY confirmed used to be
    # skipped outright, and with it the arrival credit: the six of ten units
    # physically in the requester's hands sat on no shelf until the last four were
    # acknowledged, so his stock balance and ledger stayed empty for a partially
    # fulfilled indent while fully received ones posted neatly. The unsettled issues
    # now credit what HAS been confirmed so far (`_issue_confirmation_caps` caps the
    # credit at it), and `credit_arrival`'s running total tops the lot up as the
    # remaining receipts come in — including the final one that eventually settles
    # the issue through `_apply_issue_acknowledgement`.
    for issue in issues:
        if issue.id in settled:
            continue
        caps = await _issue_confirmation_caps(db, issue)
        if not caps or all(_d(v) <= ZERO for v in caps.values()):
            continue
        dispatch = await _dispatch_for_issue(db, issue.id)
        if dispatch is None:
            continue
        carried = await _dispatch_issue_ids(db, dispatch)
        grouped = len(carried) > 1
        # The confirmed units are the ones that arrived; write them onto the
        # consignment before crediting, because `credit_arrival` credits
        # `delivered_qty` and on a partial receipt nobody had written it yet.
        # See `_stamp_confirmed_delivery`.
        if (dispatch.status in _STAMPABLE_DISPATCH_STATUSES
                and _stamp_confirmed_delivery(
                    dispatch, caps,
                    _lines_for_issue(dispatch, issue.id, grouped=grouped))):
            dispatch.delivered_at = dispatch.delivered_at or utcnow()
        # The credit is a running total over the WHOLE consignment, so on a grouped one
        # its ceiling is what has been confirmed across every issue it carries — this
        # issue's caps alone would hold back units another issue already had credited.
        box_codes.apply_package_receipts(dispatch.items, box_received or None)
        await credit_arrival(db, dispatch, user,
                             cap_by_item=(await _dispatch_confirmation_caps(db, carried)
                                          if grouped else caps))

    signed += await _sign_transport_for_indent(
        db, indent_id, user, condition=condition, remarks=remarks,
        fully_received=fully_received)
    return signed


async def _sign_transport_for_indent(db: AsyncSession, indent_id: int, user, *,
                                     condition: str | None = None,
                                     remarks: str | None = None,
                                     fully_received: bool = False) -> list[str]:
    """Close the outward legs behind an indent its raiser has just confirmed.

    The requester saying "it reached me" is the same signature the logistics
    Acknowledgements desk takes, so a leg still reading in transit after it would
    leave the transport register disagreeing with the indent it was carrying —
    a shipment on the road against goods already in someone's hands.

    Stamped here rather than by calling `transport.acknowledge_tr`: the consignment,
    the issue and the indent were all settled by `_apply_issue_acknowledgement` on the
    way in, and re-entering through the transport service would run that cascade a
    second time. Neither commits — the caller owns the transaction.
    """
    from app.modules.logistics.enums import (
        AWAITING_ACK_STATUSES, SIGNABLE_STATUSES, AckCondition, TransportStatus,
    )
    from app.modules.logistics.models import TransportRequest

    # Not "everything still open". Receipts accumulate (see `acknowledge_receipt`: six
    # today, four next week), so this runs on EVERY partial acknowledgement, not just
    # the last one, and reaching too far back closes a leg that is still carrying goods.
    # DRAFT, PENDING_APPROVAL, QUOTING and AWAITING_CARRIER are never in either set —
    # a live tender signed off here would vanish out of the carriers' portals mid-bid.
    #
    # READY is the one rung that depends on how much arrived, and that distinction is
    # this integration's, not the branch's. READY means settled and sitting in the yard,
    # NOT dispatched. On a partial receipt a READY leg is very often the one carrying
    # the rest of the order, and signing it would mark undelivered material as received.
    # Once every line has been received there is nothing left for such a leg to carry,
    # so READY there is a departure nobody pressed the button for — which is exactly the
    # case `SIGNABLE_STATUSES` was widened for (a third-party leg tracked from the
    # carrier's own portal). Full receipt gets the wide set, a partial one gets the legs
    # that have demonstrably left.
    signable = SIGNABLE_STATUSES if fully_received else AWAITING_ACK_STATUSES
    legs = (await db.execute(
        select(TransportRequest)
        .options(selectinload(TransportRequest.items))
        .where(TransportRequest.indent_id == indent_id,
               TransportRequest.status.in_(signable))
    )).scalars().all()

    # The requester's word on the state of the goods, mapped onto logistics' own enum.
    # Absent (or GOOD) keeps the previous behaviour exactly: the leg closes clean.
    reported = (condition or AckCondition.GOOD.value).strip().upper()

    now = utcnow()
    who = _name(user) or "the requester"
    for leg in legs:
        # A leg signed for straight out of READY never had its departure recorded —
        # nobody pressed "it has left". The goods are in the requester's hands, so it
        # plainly went; stamping it keeps the shipment from reading as delivered on a
        # date it was never dispatched. The consignment and the issue behind it are
        # settled by `_apply_issue_acknowledgement` on the way in, which is why this
        # does not fire the release hook and run that cascade a second time.
        leg.dispatched_at = leg.dispatched_at or now
        leg.delivered_at = leg.delivered_at or now
        leg.status = TransportStatus.ACKNOWLEDGED.value
        leg.acknowledged_at = now
        leg.acknowledged_by_id = getattr(user, "id", None)
        leg.acknowledged_by_name = _name(user)
        leg.ack_condition = leg.ack_condition or reported
        leg.ack_remarks = leg.ack_remarks or remarks
        for line in leg.items:
            if not line.delivered_qty:
                line.delivered_qty = line.quantity
        _stamp_receipt_scans(leg, who, now)
        await write_audit(db, entity="lgs_transport_requests", entity_id=leg.id,
                          entity_no=leg.tr_no, action=AuditAction.UPDATE, actor=user,
                          after={"status": leg.status},
                          summary=(f"{_name(user) or 'The requester'} confirmed "
                                   f"{leg.tr_no} on the indent"))

    await _raise_receipt_claim(db, legs, reported, remarks, user)
    await _close_signed_legs(db, legs, user)
    # A consignment that travelled on a multi-drop trip: its stop, and — once every
    # stop has signed — the trip's shipment, settle here in the same transaction.
    from app.modules.warehouse import trips
    await trips.sync_for_indent(db, indent_id, user, condition=reported, remarks=remarks)
    return [leg.tr_no for leg in legs]


async def _close_signed_legs(db: AsyncSession, legs: list, user) -> None:
    """Take the acknowledged leg its last rung, to CLOSED.

    ACKNOWLEDGED was where the requester's receipt left every leg, whatever the mode,
    and the cycle then waited on a logistics desk pressing "Close shipment" — a
    keystroke that adds no fact. The signature IS the end of the leg: the goods are in
    the requester's hands, the consignment and the issue behind it are settled and the
    indent has closed. Nothing was left for that press to decide, and a queue of
    shipments needing it is a queue nobody works.

    The one thing it DID decide is kept, and it is the same rule `transport.close_tr`
    has always run on: an open claim holds the leg. A receipt reporting SHORT or
    DAMAGED raises one just above (`_raise_receipt_claim`), so those legs stay
    ACKNOWLEDGED with the desk's Close button still on them — the claim is settled
    with the provider before the shipment is done with. Closing around an unsettled
    claim would file the only document it is investigated from.

    Stamped rather than routed through `close_tr`: that call commits, and this runs
    inside the acknowledgement's transaction (rule 9 — the receipt and everything it
    settles land together or not at all).
    """
    from app.modules.logistics.enums import TransportStatus

    for leg in legs:
        if any(event.is_exception and event.resolved_at is None
               for event in leg.events):
            continue
        leg.status = TransportStatus.CLOSED.value
        await write_audit(db, entity="lgs_transport_requests", entity_id=leg.id,
                          entity_no=leg.tr_no, action=AuditAction.UPDATE, actor=user,
                          after={"status": leg.status},
                          summary=(f"{leg.tr_no} closed — "
                                   f"{_name(user) or 'the requester'} signed for it "
                                   f"on {leg.indent_no or 'the indent'}"))


def _stamp_receipt_scans(leg, who: str, now) -> None:
    """Put the requester's receipt on the shipment's own tracking timeline.

    The signature already moved the STATUS to ACKNOWLEDGED, but Tracking is read from
    `lgs_shipment_events` alone, so a leg whose goods were in someone's hands still
    showed "Out for delivery" as its last scan — the panel disagreeing with the header
    above it. The receipt is the arrival, so it is recorded as one.

    Two rows, not one: DELIVERED is stamped only when nothing ever recorded the
    arrival (a leg signed straight out of READY or IN_TRANSIT, where nobody pressed
    "it landed"), and ACKNOWLEDGED always, because who signed and when is the fact the
    Exceptions desk reads back. A leg the carrier already marked delivered keeps its
    own scan with its own timestamp; this never overwrites custody evidence.
    """
    from app.modules.logistics.enums import ShipmentEventType
    from app.modules.logistics.models import ShipmentEvent

    types = {event.event_type for event in leg.events}
    if ShipmentEventType.DELIVERED.value not in types:
        leg.events.append(ShipmentEvent(
            event_type=ShipmentEventType.DELIVERED.value,
            event_at=leg.delivered_at or now,
            location_name=leg.to_location_name,
            description=f"Reached {who}",
        ))
    if ShipmentEventType.ACKNOWLEDGED.value not in types:
        leg.events.append(ShipmentEvent(
            event_type=ShipmentEventType.ACKNOWLEDGED.value, event_at=now,
            location_name=leg.to_location_name,
            description=(f"{who} confirmed receipt on "
                         f"{leg.indent_no or 'the indent'}"),
            recorded_by_id=leg.acknowledged_by_id,
            recorded_by_name=leg.acknowledged_by_name,
        ))


async def _raise_receipt_claim(db: AsyncSession, legs: list, condition: str,
                               remarks: str | None, user) -> None:
    """Damage reported on an indent receipt, opened as a claim on the shipment.

    ONE claim, not one per leg. A requester reports on the delivery in front of them,
    not on the transport paperwork behind it, so an indent served by three legs would
    otherwise open three identical claims for one damaged carton and leave the
    Exceptions desk reconciling them. It lands on the most recently dispatched leg —
    the one the goods most likely came on — and the remarks travel with it, which is
    what the desk actually investigates from.

    DIRECT and OWN_VEHICLE have no carrier, so there is nobody to claim against. The
    damage is still recorded, because the Exceptions desk wants to know a delivery
    arrived broken whoever was driving; it is simply not called a carrier claim.
    """
    from app.modules.logistics.enums import (
        ACK_CLAIM_EVENT, AckCondition, ShipmentEventType, TransportMode,
    )
    from app.modules.logistics.models import ShipmentEvent

    claim_type = ACK_CLAIM_EVENT.get(condition)
    if not legs or condition == AckCondition.GOOD.value or not claim_type:
        return

    target = max(legs, key=lambda leg: (leg.dispatched_at or leg.id, leg.id))
    in_house = target.mode in (TransportMode.DIRECT.value,
                               TransportMode.OWN_VEHICLE.value)
    against = (target.carrier_name if not in_house and target.carrier_name
               else None)
    who = _name(user) or "The requester"
    target.events.append(ShipmentEvent(
        event_type=claim_type, event_at=utcnow(),
        location_name=target.to_location_name,
        description=(f"{who} reported damage on the indent receipt"
                     + (f" — claim against {against}" if against
                        else " — delivered in house, no carrier to claim against")
                     + (f": {remarks}" if remarks else "")),
        is_exception=True,
        recorded_by_id=getattr(user, "id", None),
        recorded_by_name=who,
    ))


async def acknowledge_issue(db: AsyncSession, issue_id: int, remarks: str | None,
                            user) -> m.MaterialIssue:
    issue = await get_issue(db, issue_id)
    # DISPATCHED is the same open state as ISSUED — gate-out only records that the
    # goods left the gate, the receiver still has to acknowledge them.
    _guard(issue.status, {IssueStatus.ISSUED.value, IssueStatus.DISPATCHED.value},
           "acknowledge", "issue")
    # Hiding the button is not the control (rule 6) — the raiser's confirmation is.
    if not await _receiver_confirmed(db, issue):
        raise ValidationError(
            f"{issue.issue_no} has not been confirmed by the requester yet. They "
            "record what reached them in Acknowledgements; this signs off on that.")
    before_status = issue.status
    await _apply_issue_acknowledgement(db, issue, _name(user), remarks, user)

    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": before_status},
                      after={"status": issue.status})
    await db.commit()
    return await get_issue(db, issue_id)


_DIRECT_ACK_OPEN = (IssueStatus.ISSUED.value, IssueStatus.DISPATCHED.value)


async def _own_points(db: AsyncSession, user) -> set[int]:
    """The stocking points whose SHELF this login holds — never its reportees'.
    Acknowledging is "it reached MY shelf"; a DM must not sign for an LIP under him."""
    points: set[int] = set()
    for position_id in await stock_locations.active_positions_of(db, user):
        points |= await stock_locations.held_location_ids(db, position_id, subtree=False)
    return points


#: A consignment still being built or approved: the goods have not left the gate.
_DISPATCH_NOT_LEFT = (DispatchStatus.DRAFT.value, DispatchStatus.PENDING_APPROVAL.value,
                      DispatchStatus.APPROVED.value, DispatchStatus.PACKED.value)


def _direct_issue_for(user, points: set[int], *, sto: bool = False):
    """A posted outward issue raised against no indent that THIS login receives.

    `sto=True` asks the same question of the OTHER half (2026-10-29): the issues that
    execute a direct Stock Transfer Order, received on Inventory > Stock Transfer >
    Acknowledgements. Those are also the destination point's when the goods were
    handed over without a consignment: the order names the point, so its holder is
    the receiver whether or not a carton ever left on a truck.

    An indent-linked issue is confirmed by the indent's raiser on the indent's own
    acknowledgement. A direct issue has no raiser, so it is the RECEIVER's (SCM_0013):
    - the point it was consigned to — a consignment out of the gate (`_ON_THE_ROAD`)
      whose `to_warehouse_id` is a shelf this login holds. A relay leg is addressed to
      the MDP, so only the MDP sees it; the LIP sees its own leg;
    - or the employee it was issued TO, provided nothing is still waiting at the gate:
      acknowledging before gate-out would close the issue with the goods in the store.
    """
    consigned = (select(m.Dispatch.id)
                 .where(_carries_issue(m.MaterialIssue.id),
                        m.Dispatch.status.in_(_ON_THE_ROAD)))
    not_left = (select(m.Dispatch.id)
                .where(_carries_issue(m.MaterialIssue.id),
                       m.Dispatch.status.in_(_DISPATCH_NOT_LEFT)))
    # Handed over without a consignment: only once outward QC has let it go — a
    # posted issue sits in QC in the store, and signing it there closes it unseen.
    receivers = [and_(m.MaterialIssue.issued_to_id == getattr(user, "id", 0),
                      ~not_left.correlate(m.MaterialIssue).exists(),
                      or_(m.MaterialIssue.qc_status.is_(None),
                          m.MaterialIssue.qc_status.in_(
                              (*CONSIGNABLE_QC, QcStatus.NOT_REQUIRED.value))))]
    if points:
        receivers.append(consigned.where(m.Dispatch.to_warehouse_id.in_(points))
                         .correlate(m.MaterialIssue).exists())
    from app.modules.inventory.models import StockTransferOrder
    sto_issues = (select(StockTransferOrder.issue_id)
                  .where(StockTransferOrder.issue_id.is_not(None)))
    common = (m.MaterialIssue.indent_id.is_(None),
              m.MaterialIssue.direction == IssueDirection.OUT.value,
              m.MaterialIssue.is_stock_posted.is_(True))
    if sto:
        # The order's own issue, or a floor piece of it.
        of_sto = or_(m.MaterialIssue.id.in_(sto_issues),
                     m.MaterialIssue.parent_issue_id.in_(sto_issues))
        if points:
            addressed = (select(StockTransferOrder.id)
                         .where(or_(StockTransferOrder.issue_id == m.MaterialIssue.id,
                                    StockTransferOrder.issue_id
                                    == m.MaterialIssue.parent_issue_id),
                                StockTransferOrder.to_warehouse_id.in_(points)))
            receivers.append(and_(
                addressed.correlate(m.MaterialIssue).exists(),
                ~not_left.correlate(m.MaterialIssue).exists(),
                or_(m.MaterialIssue.qc_status.is_(None),
                    m.MaterialIssue.qc_status.in_(
                        (*CONSIGNABLE_QC, QcStatus.NOT_REQUIRED.value)))))
        return and_(*common, of_sto, or_(*receivers))
    return and_(*common,
                # An STO's issue (or a floor piece of one) is received on the Stock
                # Transfer screen, not here.
                m.MaterialIssue.id.notin_(sto_issues),
                or_(m.MaterialIssue.parent_issue_id.is_(None),
                    m.MaterialIssue.parent_issue_id.notin_(sto_issues)),
                or_(*receivers))


async def direct_issues_for_recipient(db: AsyncSession, user, *, search: str | None = None,
                                      only_actionable: bool = False) -> list[dict]:
    statuses = _DIRECT_ACK_OPEN if only_actionable else (
        *_DIRECT_ACK_OPEN, IssueStatus.ACKNOWLEDGED.value)
    stmt = (select(m.MaterialIssue).options(selectinload(m.MaterialIssue.items))
            .where(_direct_issue_for(user, await _own_points(db, user)),
                   m.MaterialIssue.status.in_(statuses)))
    if search and search.strip():
        like = f"%{search.strip()}%"
        stmt = stmt.where(or_(
            m.MaterialIssue.issue_no.ilike(like),
            m.MaterialIssue.warehouse_name.ilike(like),
            select(m.MaterialIssueLine.id).where(
                m.MaterialIssueLine.issue_id == m.MaterialIssue.id,
                or_(m.MaterialIssueLine.item_code.ilike(like),
                    m.MaterialIssueLine.item_name.ilike(like)),
            ).correlate(m.MaterialIssue).exists(),
        ))
    issues = (await db.execute(stmt.order_by(m.MaterialIssue.id.desc()).limit(200))).scalars().all()
    consignments = await _consignments_of_issues(db, [issue.id for issue in issues])
    return [{
        "consignments": consignments.get(issue.id, []),
        "issue_id": issue.id, "issue_no": issue.issue_no, "issue_date": issue.issue_date,
        "status": issue.status, "warehouse_name": issue.warehouse_name,
        "department_name": issue.department_name, "project_name": issue.project_name,
        "issued_by_name": issue.issued_by_name or issue.created_by_name,
        "total_qty": issue.total_qty,
        "acknowledged_by_name": issue.acknowledged_by_name,
        "acknowledged_at": issue.acknowledged_at,
        "can_acknowledge": issue.status in _DIRECT_ACK_OPEN,
        "lines": [{"item_code": line.item_code, "item_name": line.item_name,
                   "uom_code": line.uom_code, "batch_no": line.batch_no,
                   "issued_qty": line.issued_qty}
                  for line in issue.items if _d(line.issued_qty) > 0],
    } for issue in issues]


async def stock_transfer_issues_for_receiver(
    db: AsyncSession, user, *, search: str | None = None, only_actionable: bool = False,
) -> list[dict]:
    """Direct STOs arriving at a point this login holds (2026-10-29).

    The receiving half of a direct Stock Transfer Order: the destination storekeeper
    sees the shipment the moment it leaves the gate (or is handed over) and signs it on
    Inventory > Stock Transfer > Acknowledgements. Signing runs the direct-issue
    receipt (`acknowledge_direct_issue`), whose `credit_arrival` books it onto the
    destination shelf. STR transfers are listed beside these from the indent side.
    """
    from app.modules.inventory.models import StockTransferOrder

    statuses = _DIRECT_ACK_OPEN if only_actionable else (
        *_DIRECT_ACK_OPEN, IssueStatus.ACKNOWLEDGED.value)
    stmt = (select(m.MaterialIssue).options(selectinload(m.MaterialIssue.items))
            .where(_direct_issue_for(user, await _own_points(db, user), sto=True),
                   m.MaterialIssue.status.in_(statuses)))
    if search and search.strip():
        like = f"%{search.strip()}%"
        sto_match = (select(StockTransferOrder.id)
                     .where(or_(StockTransferOrder.issue_id == m.MaterialIssue.id,
                                StockTransferOrder.issue_id == m.MaterialIssue.parent_issue_id),
                            StockTransferOrder.sto_no.ilike(like)))
        stmt = stmt.where(or_(
            m.MaterialIssue.issue_no.ilike(like),
            m.MaterialIssue.warehouse_name.ilike(like),
            sto_match.correlate(m.MaterialIssue).exists(),
            select(m.MaterialIssueLine.id).where(
                m.MaterialIssueLine.issue_id == m.MaterialIssue.id,
                or_(m.MaterialIssueLine.item_code.ilike(like),
                    m.MaterialIssueLine.item_name.ilike(like)),
            ).correlate(m.MaterialIssue).exists(),
        ))
    issues = (await db.execute(stmt.order_by(m.MaterialIssue.id.desc()).limit(200))).scalars().all()
    wanted = ({i.id for i in issues}
              | {i.parent_issue_id for i in issues if i.parent_issue_id}) or {0}
    order_of = {row.issue_id: row for row in (await db.execute(
        select(StockTransferOrder.issue_id, StockTransferOrder.id, StockTransferOrder.sto_no,
               StockTransferOrder.from_warehouse_name, StockTransferOrder.to_warehouse_name)
        .where(StockTransferOrder.issue_id.in_(wanted))
    )).all()}
    consignments = await _consignments_of_issues(db, [issue.id for issue in issues])
    rows = []
    for issue in issues:
        order = order_of.get(issue.id) or order_of.get(issue.parent_issue_id)
        rows.append({
            "consignments": consignments.get(issue.id, []),
            "issue_id": issue.id, "issue_no": issue.issue_no, "issue_date": issue.issue_date,
            "status": issue.status, "warehouse_name": issue.warehouse_name,
            "department_name": issue.department_name, "project_name": issue.project_name,
            "issued_by_name": issue.issued_by_name or issue.created_by_name,
            "total_qty": issue.total_qty,
            "acknowledged_by_name": issue.acknowledged_by_name,
            "acknowledged_at": issue.acknowledged_at,
            "can_acknowledge": issue.status in _DIRECT_ACK_OPEN,
            "lines": [{"item_code": line.item_code, "item_name": line.item_name,
                       "uom_code": line.uom_code, "batch_no": line.batch_no,
                       "issued_qty": line.issued_qty}
                      for line in issue.items if _d(line.issued_qty) > 0],
            "sto_id": order.id if order else None,
            "sto_no": order.sto_no if order else None,
            "from_warehouse_name": (order.from_warehouse_name if order
                                    else issue.warehouse_name),
            "to_warehouse_name": (order.to_warehouse_name if order
                                  else issue.destination_warehouse_name),
        })
    return rows


async def _consignments_of_issues(db: AsyncSession,
                                  issue_ids: list[int]) -> dict[int, list[dict]]:
    """The live consignments carrying each issue, with their package counts.

    `_carries_issue` for a page of issues in three queries: the consignment that names
    one issue as its reference, the ones that carry it among several (`DispatchSource`),
    and one grouped count of packages. Cancelled consignments are not on the road.
    """
    if not issue_ids:
        return {}
    live = m.Dispatch.status != DispatchStatus.CANCELLED.value
    pairs = list((await db.execute(
        select(m.Dispatch.ref_id, m.Dispatch.id, m.Dispatch.dispatch_no, m.Dispatch.status)
        .where(m.Dispatch.ref_type.in_(SINGLE_ISSUE_REF_TYPES),
               m.Dispatch.ref_id.in_(issue_ids), live)
    )).all()) + list((await db.execute(
        select(m.DispatchSource.issue_id, m.Dispatch.id, m.Dispatch.dispatch_no, m.Dispatch.status)
        .join(m.Dispatch, m.Dispatch.id == m.DispatchSource.dispatch_id)
        .where(m.DispatchSource.issue_id.in_(issue_ids), live)
    )).all())
    dispatch_ids = {dispatch_id for _i, dispatch_id, _n, _s in pairs}
    packages = dict((await db.execute(
        select(m.DispatchPackage.dispatch_id, func.count(m.DispatchPackage.id))
        .where(m.DispatchPackage.dispatch_id.in_(dispatch_ids))
        .group_by(m.DispatchPackage.dispatch_id)
    )).all()) if dispatch_ids else {}
    out: dict[int, list[dict]] = defaultdict(list)
    for issue_id, dispatch_id, dispatch_no, status in sorted(pairs, key=lambda p: p[1]):
        if any(row["dispatch_id"] == dispatch_id for row in out[issue_id]):
            continue
        out[issue_id].append({"dispatch_id": dispatch_id, "dispatch_no": dispatch_no,
                              "status": status,
                              "package_count": int(packages.get(dispatch_id, 0))})
    return out


ISSUE_ACK_ENTITY_TYPE = "ISSUE_RECEIPT"


async def _direct_issue_of(db: AsyncSession, issue_id: int, user, *,
                           open_only: bool = False) -> m.MaterialIssue:
    """A direct issue handed to THIS person — the only one who may receive it."""
    issue = await get_issue(db, issue_id)
    if issue.indent_id is not None:
        raise ValidationError(
            f"{issue.issue_no} was issued against {issue.indent_no or 'an indent'} — "
            "acknowledge it on that indent.")
    if not issue.is_stock_posted:
        raise ValidationError(f"{issue.issue_no} has not left the store yet")
    # The SAME predicate the list uses, so a row on the list always opens, and hiding
    # the row is never the control (rule 6): the receiving point, or the issued-to
    # person once nothing is waiting at the gate.
    points = await _own_points(db, user)
    if not await db.scalar(select(func.count()).select_from(m.MaterialIssue).where(
            m.MaterialIssue.id == issue.id,
            or_(_direct_issue_for(user, points),
                _direct_issue_for(user, points, sto=True)))):
        raise PermissionError_(
            f"{issue.issue_no} is signed for by the point it was dispatched to, or by "
            f"{issue.issued_to_name or 'the person it was issued to'}")
    if open_only:
        _guard(issue.status, set(_DIRECT_ACK_OPEN), "acknowledge", "issue")
    return issue


async def direct_issue_receipt(db: AsyncSession, issue_id: int, user) -> dict:
    """A direct issue in the SAME shape as an indent's acknowledgement row.

    So the indent receipt journey — consignment, packages, unit codes, photos — runs
    over it unchanged: `indent_id` carries the issue id, `indent_no` the issue number
    and each line's `indent_item_id` the ISSUE LINE id.
    """
    from app.modules.logistics.models import TransportRequest

    issue = await _direct_issue_of(db, issue_id, user)
    lines = [line for line in issue.items
             if _d(line.issued_qty) - _d(line.returned_qty) > 0]
    signed = issue.status == IssueStatus.ACKNOWLEDGED.value

    dispatches = list((await db.execute(
        select(m.Dispatch).where(_carries_issue(issue.id),
                                 m.Dispatch.status != DispatchStatus.CANCELLED.value)
        .order_by(m.Dispatch.id)
    )).scalars().all())
    dispatch_ids = [d.id for d in dispatches]

    # Package split: the consignment lines packed from this issue, per item.
    packages_by_item: dict[int, list[dict]] = defaultdict(list)
    if dispatch_ids:
        for (item_id, dispatch_id, dispatch_no, package_id, packed_qty, pack) in (await db.execute(
            select(m.DispatchItem.item_id, m.Dispatch.id, m.Dispatch.dispatch_no,
                   m.DispatchItem.package_id, func.sum(m.DispatchItem.quantity),
                   m.DispatchPackage)
            .join(m.Dispatch, m.Dispatch.id == m.DispatchItem.dispatch_id)
            .join(m.DispatchPackage, m.DispatchPackage.id == m.DispatchItem.package_id)
            .where(m.Dispatch.id.in_(dispatch_ids),
                   or_(m.DispatchItem.issue_id.is_(None),
                       m.DispatchItem.issue_id == issue.id))
            .group_by(m.DispatchItem.item_id, m.Dispatch.id, m.Dispatch.dispatch_no,
                      m.DispatchItem.package_id, m.DispatchPackage.id)
            .order_by(m.Dispatch.id, m.DispatchPackage.id)
        )).all():
            packages_by_item[item_id].append({
                "dispatch_id": dispatch_id, "dispatch_no": dispatch_no,
                "package_id": package_id, "package_no": pack.package_no,
                "quantity": float(_d(packed_qty)), "package_type": pack.package_type,
                "barcode": pack.barcode,
                "weight_kg": float(_d(pack.weight_kg)) if pack.weight_kg is not None else None,
                "length_cm": float(_d(pack.length_cm)) if pack.length_cm is not None else None,
                "width_cm": float(_d(pack.width_cm)) if pack.width_cm is not None else None,
                "height_cm": float(_d(pack.height_cm)) if pack.height_cm is not None else None,
                "is_fragile": bool(pack.is_fragile),
                "is_temp_controlled": bool(pack.is_temp_controlled),
                "packed_by_name": pack.packed_by_name, "packed_at": pack.packed_at,
            })
        await _package_rows_packed(db, packages_by_item, by="item")

    # Which units left, by every stamp a unit of this issue may be wearing now —
    # the same markers `_delivery_rows` reads for an indent.
    line_markers = {_issue_line_serial_marker(issue.id, line.id): line.id for line in lines}
    shared = {*_issue_serial_markers(issue.id), _shipped_unit_marker("issue", issue.id)}
    for d in dispatches:
        shared.add(_shipped_unit_marker("dispatch", d.id))
        if d.dispatch_no:
            shared.add(f"Received by {d.dispatch_no}")
    line_of_item: dict[int, int] = {}
    for line in lines:
        line_of_item.setdefault(line.item_id, line.id)
    item_rows = {row.id: row for row in (await db.execute(
        select(Item).where(Item.id.in_({line.item_id for line in lines} or {0}))
    )).scalars().all()}
    serials: dict[int, list[str]] = defaultdict(list)
    for unit in (await db.execute(
        select(m.SerialNumber)
        .where(m.SerialNumber.remarks.in_([*line_markers, *shared]),
               m.SerialNumber.is_active.is_(True))
        .order_by(m.SerialNumber.id)
    )).scalars().all():
        line_id = line_markers.get(unit.remarks or "") or line_of_item.get(unit.item_id)
        if line_id is None:
            continue
        keys = _unit_keys(unit, _unit_mode(item_rows.get(unit.item_id)))
        code = keys[0] if keys else (unit.serial_number or unit.asset_code
                                     or unit.consumable_code or unit.imei)
        if code and code not in serials[line_id]:
            serials[line_id].append(code)

    legs = list((await db.execute(
        select(TransportRequest).where(TransportRequest.dispatch_id.in_(dispatch_ids or [0]))
        .order_by(TransportRequest.id.desc())
    )).scalars().all())

    line_packs = await wh_packing.issue_line_packs(
        db, {line.id: _d(line.issued_qty) - _d(line.returned_qty) for line in lines})
    # Issued in PACKAGES (2026-10-26): each carton lists the packages it holds, and
    # the site checks them package by package — never one code per piece.
    in_carton: dict[tuple, list[dict]] = defaultdict(list)
    carton_ids = {row["package_id"] for rows in packages_by_item.values() for row in rows}
    if carton_ids:
        for package_id, item_id, code, qty, got, status in (await db.execute(
                select(m.DispatchItem.package_id, m.DispatchItem.item_id,
                       m.DispatchItem.box_code, m.DispatchItem.quantity,
                       m.DispatchItem.delivered_qty, m.Dispatch.status)
                .join(m.Dispatch, m.Dispatch.id == m.DispatchItem.dispatch_id)
                .where(m.DispatchItem.package_id.in_(carton_ids),
                       m.DispatchItem.box_code.isnot(None))
                .order_by(m.DispatchItem.id))).all():
            in_carton[(package_id, item_id)].append({
                "code": code, "quantity": float(_d(qty)),
                # What arrived in it, once the consignment is signed for (2026-10-26).
                "received": (float(_d(got)) if status == DispatchStatus.ACKNOWLEDGED.value
                             else None)})
        # Carton › box, and the strips inside each (2026-10-28): the site checks a
        # delivery the way it was packed, and may mark one strip of a box short.
        await box_codes.decorate_packs(db, [r for rows in in_carton.values() for r in rows])
    package_lines = {line.id for line in lines
                     if await box_codes.has_boxes(db, issue.id, line.id)}
    out_lines = []
    for line in lines:
        sent = _d(line.issued_qty) - _d(line.returned_qty)
        item = item_rows.get(line.item_id)
        if line.id in package_lines:
            serials[line.id] = []
        out_lines.append({
            "indent_item_id": line.id,
            "item_id": line.item_id,
            "item_code": line.item_code, "item_name": line.item_name,
            "uom_code": line.uom_code,
            **combinations.carry(line),
            "approved_quantity": float(sent),
            "issued_quantity": float(sent),
            # Handed over at the counter or on a consignment — either way it has left.
            "dispatched_quantity": float(sent),
            "received_quantity": float(sent) if signed else 0.0,
            "is_serial_tracked": bool(getattr(item, "is_serial_tracked", False)),
            "tracking_type": _tracking_type(item, has_units=bool(serials.get(line.id)))
            if item is not None else TrackingType.NONE.value,
            "serial_numbers": serials.get(line.id, []),
            "on_order_quantity": 0.0,
            "package_quantities": [
                {**pack, "quantity": min(pack["quantity"], float(sent)),
                 "box_codes": in_carton.get((pack["package_id"], line.item_id), [])}
                for pack in packages_by_item.get(line.item_id, [])],
            **line_packs.get(line.id, {}),
            "pending_with": None,
        })
    return {
        "indent_id": issue.id,
        "indent_no": issue.issue_no,
        "indent_date": issue.issue_date,
        "required_date": None,
        "status": issue.status,
        "priority": None,
        "project_name": issue.warehouse_name,
        "can_acknowledge": issue.status in _DIRECT_ACK_OPEN,
        "lines": out_lines,
        "shipments": [_shipment_row(leg) for leg in legs],
    }


async def direct_issue_attachments(db: AsyncSession, issue_id: int, user) -> list:
    await _direct_issue_of(db, issue_id, user)
    return await attachments.list_attachments(db, ISSUE_ACK_ENTITY_TYPE, issue_id)


async def add_direct_issue_attachment(db: AsyncSession, issue_id: int, upload, *,
                                      doc_category: str, user):
    """Same rules as an indent receipt photo (`indents.add_receipt_attachment`)."""
    from app.modules.indents import service as ind

    issue = await _direct_issue_of(db, issue_id, user, open_only=True)
    if ind.ack_category_base(doc_category) not in {ind.ACK_PHOTO_CATEGORY,
                                                   ind.ACK_BILL_CATEGORY}:
        raise ValidationError("A delivery attachment is either a photo or a bill")
    scope = ind.ack_category_scope(doc_category)
    if scope and (len(scope) > ind.ACK_SCOPE_MAX or not ind._ACK_SCOPE_OK.match(scope)):
        raise ValidationError("That is not a package this delivery was sent in")
    line_id = ind.ack_category_item(doc_category)
    if line_id is not None and line_id not in {line.id for line in issue.items}:
        raise ValidationError("That is not an item on this issue")
    return await attachments.add_attachment(
        db, entity_type=ISSUE_ACK_ENTITY_TYPE, entity_id=issue.id,
        upload=upload, doc_category=doc_category, user=user)


async def direct_issue_attachment_file(db: AsyncSession, issue_id: int,
                                       attachment_id: int, user):
    await _direct_issue_of(db, issue_id, user)
    row = await db.get(attachments.Attachment, attachment_id)
    if (row is None or row.entity_type != ISSUE_ACK_ENTITY_TYPE
            or int(row.entity_id) != issue_id):
        raise NotFoundError(f"Attachment {attachment_id} not found")
    return await attachments.attachment_file(db, attachment_id)


async def delete_direct_issue_attachment(db: AsyncSession, attachment_id: int, user) -> None:
    row = await attachments.require_attachment(
        db, attachment_id, entity_type=ISSUE_ACK_ENTITY_TYPE)
    issue = await _direct_issue_of(db, int(row.entity_id), user, open_only=True)
    await attachments.delete_attachment(
        db, attachment_id, user, entity_type=ISSUE_ACK_ENTITY_TYPE, entity_id=issue.id)


async def acknowledge_direct_issue(db: AsyncSession, issue_id: int,
                                   lines: dict[int, Decimal], user, *,
                                   condition: str | None = None,
                                   remarks: str | None = None,
                                   package_receipts: dict[int, dict] | None = None) -> dict:
    """The recipient of a direct issue confirms what reached them.

    Held to the indent receipt's proof rules: a consignment photo and a photo of every
    item being confirmed. The issue has no received column, so what was counted goes on
    the remarks and the audit row; the issue is signed either way, because a shortfall
    on a direct issue is a return to raise, not a delivery still coming.
    """
    from app.modules.indents import service as ind

    issue = await _direct_issue_of(db, issue_id, user, open_only=True)
    if not lines:
        raise ValidationError("Enter what you received on at least one line")
    photos = [row for row in await attachments.list_attachments(
        db, ISSUE_ACK_ENTITY_TYPE, issue.id)
        if ind.ack_category_base(row.doc_category) == ind.ACK_PHOTO_CATEGORY]
    if not any((scope := ind.ack_category_scope(row.doc_category)) == ""
               or scope.startswith("C-") for row in photos):
        raise ValidationError(
            "Attach a photo of the consignment (the load, the seal, the number plate) "
            "before acknowledging")
    by_id = {line.id: line for line in issue.items}
    photographed = {ind.ack_category_item(row.doc_category) for row in photos}
    unproven = [by_id[i] for i in lines if i in by_id and i not in photographed]
    if unproven:
        named = ", ".join(l.item_name or l.item_code or f"line {l.id}" for l in unproven[:4])
        more = len(unproven) - 4
        raise ValidationError(
            "Take a photo of each item you are confirming. Still without one: "
            f"{named}{f' and {more} more' if more > 0 else ''}.")
    counted: dict[str, float] = {}
    short: list[str] = []
    for line_id, got in lines.items():
        line = by_id.get(line_id)
        if line is None:
            raise ValidationError(f"Line {line_id} is not on {issue.issue_no}")
        sent = _d(line.issued_qty) - _d(line.returned_qty)
        got = _d(got)
        if got <= 0 or got > sent:
            raise ValidationError(
                f"{line.item_name or line.item_code}: enter between 1 and {sent:g}")
        counted[str(line.id)] = float(got)
        if got < sent:
            short.append(f"{line.item_name or line.item_code} {got:g} of {sent:g}")
    for line in issue.items:
        sent = _d(line.issued_qty) - _d(line.returned_qty)
        if line.id not in lines and sent > 0:
            short.append(f"{line.item_name or line.item_code} 0 of {sent:g}")
    # Packages that came short or missing (2026-10-26), against what each carried.
    package_notes: list[str] = []
    for line_id, by_code in (package_receipts or {}).items():
        if not by_code or line_id not in by_id:
            continue
        sent_in = {box.hu_code: box_codes.held(box)
                   for box in await box_codes.line_boxes(db, issue.id, line_id)}
        label = by_id[line_id].item_code or by_id[line_id].item_name
        for code, got in by_code.items():
            if code not in sent_in:
                raise ValidationError(f"{label}: {code} is not a package sent on this line")
            got = _d(got)
            if got < 0 or got > sent_in[code]:
                raise ValidationError(
                    f"{label}: {code} carried {shared_packing.fmt(sent_in[code])}; "
                    f"{shared_packing.fmt(got)} cannot have arrived in it")
            package_notes.append(f"{code} missing" if got == 0 else
                                 f"{code}: {shared_packing.fmt(got)} of "
                                 f"{shared_packing.fmt(sent_in[code])} arrived")
    ack_condition = ind._delivery_condition(condition, remarks)
    note = "; ".join(filter(None, [
        f"Condition {ack_condition}" if ack_condition != ind.ACK_CONDITION_GOOD else None,
        f"Short: {', '.join(short)}" if short else None,
        f"Packages: {'; '.join(package_notes)}" if package_notes else None,
        (remarks or "").strip() or None,
    ])) or None

    received_by_item: dict[int, Decimal] = defaultdict(Decimal)
    for line_id, got in lines.items():
        received_by_item[by_id[line_id].item_id] += _d(got)
    before_status = issue.status
    box_received = {code: _d(got) for by_code in (package_receipts or {}).values()
                    for code, got in (by_code or {}).items()}
    await _apply_issue_acknowledgement(db, issue, _name(user), note, user,
                                       received_by_item=received_by_item,
                                       box_received=box_received)
    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": before_status},
                      after={"status": issue.status, "received": counted,
                             "condition": ack_condition, "remarks": note})
    await db.commit()
    return await direct_issue_receipt(db, issue.id, user)


async def cancel_issue(db: AsyncSession, issue_id: int, reason: str | None, user) -> m.MaterialIssue:
    issue = await get_issue(db, issue_id)
    if issue.is_stock_posted:
        raise ValidationError(
            f"{issue.issue_no} has already left the store. Raise a return against it "
            "instead — cancelling would leave the stock unaccounted for.")
    if issue.status == IssueStatus.SPLIT.value or await db.scalar(
            select(func.count()).select_from(m.MaterialIssue).where(
                m.MaterialIssue.parent_issue_id == issue.id,
                m.MaterialIssue.status.notin_(UNSERVED_ISSUE_STATUSES))):
        raise ValidationError(
            f"{issue.issue_no} has been split into floor issues. Cancel those instead "
            "— once all of them are cancelled it returns to Approved.")
    _guard(issue.status,
           {IssueStatus.DRAFT.value, IssueStatus.PENDING_APPROVAL.value,
            IssueStatus.APPROVED.value, IssueStatus.REJECTED.value},
           "cancel", "issue")

    before = {"status": issue.status}
    issue.status = IssueStatus.CANCELLED.value
    issue.current_approver_name = None
    issue.remarks = f"{issue.remarks or ''}\nCancelled: {reason or '—'}".strip()

    # Withdrawing the document has to withdraw the approval behind it. Without
    # this the engine kept handing the task out: WHI/2026-27/00027 sat CANCELLED
    # in an approver's queue for two days with no decision left to make.
    await engine.abandon(db, await _issue_doc_type_of(db, issue.id), issue.id, user,
                         reason=reason or "Issue cancelled")

    await _clear_issue_serial_reservations(db, issue.id)
    # A direct issue's own hold goes back to the shelf with it. An indent issue's
    # stock stays reserved for the INDENT (the allocation still stands), so the indent
    # returns to this point's dropdown with that quantity still waiting for it.
    await _release_issue_hold(db, issue.id)
    await write_audit(db, entity="out_issues", entity_id=issue.id, entity_no=issue.issue_no,
                      action=AuditAction.UPDATE, actor=user, before=before,
                      after={"status": issue.status, "reason": reason})
    await _sync_split_parent(db, issue.parent_issue_id, user)
    await db.commit()
    return await get_issue(db, issue_id)


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def _dispatch_totals(dispatch: m.Dispatch) -> None:
    lines = dispatch.items
    dispatch.total_items = len(lines)
    dispatch.total_qty = sum((_d(l.quantity) for l in lines), ZERO)
    dispatch.total_value = sum((_d(l.amount) for l in lines), ZERO)
    dispatch.total_packages = len(dispatch.packages)
    dispatch.total_weight_kg = sum((_d(p.weight_kg) for p in dispatch.packages), ZERO)


def _validate_issue_dispatch(dispatch: m.Dispatch, issue: m.MaterialIssue) -> None:
    issued: dict[int, Decimal] = {}
    for line in issue.items:
        issued[line.item_id] = issued.get(line.item_id, ZERO) + _d(line.issued_qty)
    dispatched: dict[int, Decimal] = {}
    for line in dispatch.items:
        if line.issue_id is not None and line.issue_id != issue.id:
            continue
        dispatched[line.item_id] = dispatched.get(line.item_id, ZERO) + _d(line.quantity)
    for item_id, qty in dispatched.items():
        if qty > issued.get(item_id, ZERO):
            raise ValidationError(
                f"Item {item_id}: dispatch quantity {qty} exceeds the "
                f"{issued.get(item_id, ZERO)} posted on {issue.issue_no}."
            )


async def _apply_dispatch_lines(db: AsyncSession, dispatch: m.Dispatch,
                                lines: list[s.DispatchItemWrite]) -> None:
    dispatch.items.clear()
    await db.flush()

    for index, line in enumerate(lines, start=1):
        item = await _item_snapshot(db, line.item_id)
        qty = _d(line.quantity)
        if qty <= ZERO:
            raise ValidationError(f"Line {index}: quantity must be positive")
        batch = await db.get(m.Batch, line.batch_id) if line.batch_id else None
        rate = _d(line.rate)
        dispatch.items.append(m.DispatchItem(
            line_no=index, package_id=line.package_id,
            issue_id=line.issue_id, issue_no=line.issue_no,
            mr_id=line.mr_id, mr_no=line.mr_no,
            indent_id=line.indent_id,
            item_id=item.id, item_code=item.code, item_name=item.name, uom_code=item.uom_code,
            # 0, not NULL — out_dispatch_items.batch_id is NOT NULL DEFAULT 0 live.
            batch_id=line.batch_id or m.NO_BATCH,
            batch_no=batch.batch_no if batch else None,
            serial_no=line.serial_no,
            quantity=qty, delivered_qty=ZERO,
            rate=rate or None, amount=(qty * rate) if rate else None,
            remarks=line.remarks,
        ))
    _dispatch_totals(dispatch)


def _issue_qty_by_item_batch(issue: m.MaterialIssue) -> dict[tuple[int, int], Decimal]:
    issued: dict[tuple[int, int], Decimal] = {}
    for line in issue.items:
        key = (line.item_id, line.batch_id or m.NO_BATCH)
        issued[key] = issued.get(key, ZERO) + _d(line.issued_qty)
    return issued


def _issue_serial_markers(issue_id: int) -> tuple[str, str]:
    return (_issue_serial_marker(issue_id), f"Issued by issue {issue_id}")


async def _issued_serial_index(
    db: AsyncSession,
    issue: m.MaterialIssue,
) -> dict[str, m.SerialNumber]:
    rows = (await db.execute(
        select(m.SerialNumber).where(
            m.SerialNumber.warehouse_id == issue.warehouse_id,
            m.SerialNumber.status == SerialStatus.ISSUED.value,
            m.SerialNumber.remarks.in_(_issue_serial_markers(issue.id)),
            m.SerialNumber.is_active.is_(True),
        )
    )).scalars().all()
    index = {}
    for row in rows:
        if row.serial_number:
            index[row.serial_number.lower()] = row
        if row.asset_code:
            index[row.asset_code.lower()] = row
        if row.consumable_code:
            index[row.consumable_code.lower()] = row
        # An IMEI-named line is accepted at QC and packed by its IMEI.
        if row.imei:
            index.setdefault(row.imei.lower(), row)
    return index


async def _issue_available_qty_and_serials(
    db: AsyncSession,
    issue: m.MaterialIssue
) -> tuple[dict[tuple[int, int], Decimal], dict[str, m.SerialNumber]]:
    issued_qty = _issue_qty_by_item_batch(issue)
    issued_serials = await _issued_serial_index(db, issue)
    
    if issue.qc_status in (QcStatus.PASSED.value, QcStatus.PARTIAL.value):
        inspection = (await db.execute(
            select(m.OutboundInspection).where(
                m.OutboundInspection.issue_id == issue.id,
                m.OutboundInspection.status == InspectionStatus.COMPLETED.value
            ).order_by(m.OutboundInspection.id.desc()).limit(1)
        )).scalar_one_or_none()
        
        if inspection:
            accepted_qty: dict[tuple[int, int], Decimal] = {}
            accepted_serials: set[str] = set()
            
            insp_by_line = {
                row.issue_item_id: row
                for row in (await db.execute(
                    select(m.OutboundInspectionItem)
                    .where(m.OutboundInspectionItem.inspection_id == inspection.id)
                )).scalars().all()
            }

            for line in issue.items:
                batch_id = line.batch_id
                key = (line.item_id, batch_id or m.NO_BATCH)
                insp_item = insp_by_line.get(line.id)
                # A line the inspection does not cover counts at its issued quantity —
                # the same fallback `issue_dispatch_source` offers the packer, or the
                # screen offers a line the save then refuses as "0 issued".
                if insp_item is None:
                    accepted_qty[key] = accepted_qty.get(key, ZERO) + _d(line.issued_qty)
                    for s_key, s_row in issued_serials.items():
                        if s_row.item_id == line.item_id and (not batch_id or s_row.batch_id == batch_id):
                            accepted_serials.add(s_key.lower())
                    continue
                accepted_qty[key] = accepted_qty.get(key, ZERO) + _d(insp_item.accepted_qty)

                serials_data = insp_item.serial_numbers
                if serials_data:
                    if isinstance(serials_data, dict):
                        passed_list = serials_data.get("accepted", [])
                    elif isinstance(serials_data, list):
                        passed_list = serials_data
                    else:
                        passed_list = []
                    # A box code stands for the units inside it (2026-10-26).
                    for s in await box_codes.expand_box_codes(
                            db, list(passed_list), item_id=line.item_id):
                        accepted_serials.add(s.lower())
                else:
                    for s_key, s_row in issued_serials.items():
                        if s_row.item_id == insp_item.item_id and (not batch_id or s_row.batch_id == batch_id):
                            accepted_serials.add(s_key.lower())
                    
            issued_qty = accepted_qty
            issued_serials = {k: v for k, v in issued_serials.items() if k in accepted_serials}
            
    return issued_qty, issued_serials


def _issue_line_place(line) -> str:
    """'(batch B1 at F1-A1-R1-B2)' - how a packing message names ONE issue line."""
    batch = f"batch {line.batch_no}" if line.batch_no else "unbatched"
    return f"({batch} at {line.bin_code})" if line.bin_code else f"({batch})"


async def _issue_accepted_by_line(db: AsyncSession, issue: m.MaterialIssue) -> dict[int, Decimal]:
    """What each line may be packed: QC's accepted quantity, else what it issued.

    A line the completed sheet does not carry needed no check (`_line_needs_outward_qc`)
    and goes out whole - the same fallback `issue_dispatch_source` offers the packer.
    """
    accepted = {line.id: _d(line.issued_qty) for line in issue.items}
    if issue.qc_status not in (QcStatus.PASSED.value, QcStatus.PARTIAL.value):
        return accepted
    inspection_id = await db.scalar(
        select(m.OutboundInspection.id).where(
            m.OutboundInspection.issue_id == issue.id,
            m.OutboundInspection.status == InspectionStatus.COMPLETED.value,
        ).order_by(m.OutboundInspection.id.desc()).limit(1))
    if inspection_id is None:
        return accepted
    for line_id, qty in (await db.execute(
        select(m.OutboundInspectionItem.issue_item_id, m.OutboundInspectionItem.accepted_qty)
        .where(m.OutboundInspectionItem.inspection_id == inspection_id)
    )).all():
        if line_id in accepted:
            accepted[line_id] = _d(qty)
    return accepted


async def _apply_consignment_packages(
    db: AsyncSession,
    dispatch: m.Dispatch,
    issues: list[m.MaterialIssue],
    packages: list[s.ConsignmentPackageWrite],
    user,
    mr_by_issue: dict[int, dict] | None = None,
) -> None:
    if not packages:
        raise ValidationError("Add at least one package before saving the consignment")

    package_numbers: set[str] = set()
    barcodes: set[str] = set()
    packed_by_key: dict[tuple[int, int, int], Decimal] = {}
    used_serials: set[str] = set()
    issues_by_id = {issue.id: issue for issue in issues}
    if len(issues_by_id) != len(issues):
        raise ValidationError("The same material issue was selected more than once")
    default_issue_id = issues[0].id if len(issues) == 1 else None
    issued_by_key: dict[tuple[int, int, int], Decimal] = {}
    issued_serials_by_issue: dict[int, dict[str, m.SerialNumber]] = {}
    # Per issue LINE as well as per batch (2026-10-07): a row the screen names by its
    # issue line is held to THAT line's accepted quantity and THAT line's units, so a
    # batch split over two bays cannot be packed as two halves of one pile.
    lines_by_id: dict[int, m.MaterialIssueLine] = {}
    accepted_by_line: dict[int, Decimal] = {}
    unit_names_by_line: dict[int, set[str]] = {}
    for source_issue in issues:
        line_qty, line_serials = await _issue_available_qty_and_serials(db, source_issue)
        for (item_id, batch_id), qty in line_qty.items():
            issued_by_key[(source_issue.id, item_id, batch_id)] = qty
        issued_serials_by_issue[source_issue.id] = line_serials
        accepted_by_line.update(await _issue_accepted_by_line(db, source_issue))
        for line in source_issue.items:
            lines_by_id[line.id] = line
        for line_id, rows in (await _issue_units_by_line(db, source_issue)).items():
            unit_names_by_line[line_id] = {
                value.lower() for row in rows
                for value in (row.serial_number, row.imei, row.asset_code,
                              row.consumable_code) if value}
    packed_by_line: dict[int, Decimal] = {}
    # Issued in PACKAGES (2026-10-26): what each package carries after QC, per issue
    # line, and which carton already holds it — a package goes wholly into one carton.
    packages_by_line: dict[int, dict[str, Decimal]] = {}
    for source_issue in issues:
        for line in source_issue.items:
            after_qc = await box_codes.packages_after_qc(db, source_issue, line)
            if after_qc:
                packages_by_line[line.id] = after_qc
    carton_of_package: dict[str, str] = {}

    existing_barcode_stmt = select(m.DispatchPackage.barcode).join(m.Dispatch).where(
        m.DispatchPackage.barcode.isnot(None),
        m.DispatchPackage.dispatch_id != (dispatch.id or 0),
        m.Dispatch.status != DispatchStatus.CANCELLED.value,
    )
    existing_barcodes = {
        value.lower()
        for value in (await db.execute(existing_barcode_stmt)).scalars().all()
        if value
    }

    dispatch.items.clear()
    dispatch.packages.clear()
    await db.flush()

    line_no = 1
    for package_index, package_data in enumerate(packages, start=1):
        package_no = (
            package_data.package_no
            or f"{dispatch.dispatch_no}-P{package_index:02d}"
        ).strip()
        barcode = (
            package_data.barcode
            or f"{dispatch.dispatch_no}|P{package_index:02d}"
        ).strip()
        if not package_no:
            raise ValidationError(f"Package {package_index}: package no is required")
        if not barcode:
            raise ValidationError(f"Package {package_index}: barcode is required")
        if package_no.lower() in package_numbers:
            raise ValidationError(f"Package {package_no} is repeated in this consignment")
        if barcode.lower() in barcodes:
            raise ValidationError(f"Barcode {barcode} is repeated in this consignment")
        if barcode.lower() in existing_barcodes:
            raise ValidationError(f"Barcode {barcode} is already used on another package")
        if not package_data.items:
            raise ValidationError(f"Package {package_no} must contain at least one item")

        package_numbers.add(package_no.lower())
        barcodes.add(barcode.lower())
        package = m.DispatchPackage(
            dispatch_id=dispatch.id,
            package_no=package_no,
            package_type=package_data.package_type,
            barcode=barcode,
            weight_kg=package_data.weight_kg,
            length_cm=package_data.length_cm,
            width_cm=package_data.width_cm,
            height_cm=package_data.height_cm,
            is_fragile=package_data.is_fragile,
            is_temp_controlled=package_data.is_temp_controlled,
            status=PackageStatus.PACKED.value,
            packed_by_name=_name(user),
            packed_at=utcnow(),
        )
        dispatch.packages.append(package)
        await db.flush()
        carton_packs: list[dict] = []

        for item_data in package_data.items:
            source_issue_id = item_data.issue_id or default_issue_id
            if source_issue_id is None or source_issue_id not in issues_by_id:
                raise ValidationError(
                    f"{package_no}: item {item_data.item_id} does not say which "
                    "of the selected material issues it was packed from"
                )
            source_issue = issues_by_id[source_issue_id]
            item = await _item_snapshot(db, item_data.item_id)
            qty = _d(item_data.quantity)
            if qty <= ZERO:
                raise ValidationError(
                    f"{package_no}: {item.code} quantity must be positive"
                )
            batch_id = item_data.batch_id or m.NO_BATCH
            serials = [
                value.strip()
                for value in ([item_data.serial_no] if item_data.serial_no else item_data.serial_numbers)
                if value and value.strip()
            ]
            normalized_serials = [value.lower() for value in serials]
            if len(normalized_serials) != len(set(normalized_serials)):
                raise ValidationError(f"{package_no}: duplicate serials for {item.code}")

            # A line issued in packages names the PACKAGES this carton holds — whole
            # ones, each in exactly one carton, adding up to what the carton carries.
            box_map = packages_by_line.get(item_data.issue_item_id or 0)
            if box_map:
                if not serials:
                    raise ValidationError(
                        f"{package_no}: {item.code} — pick which packages go in this carton")
                stray = [code for code in serials if code not in box_map]
                if stray:
                    raise ValidationError(
                        f"{package_no}: {', '.join(stray[:5])} is not a package of "
                        f"{item.code} on this issue line (or was rejected at QC)")
                for code in serials:
                    if code in carton_of_package:
                        raise ValidationError(
                            f"{code} is already in {carton_of_package[code]} — a package "
                            "goes wholly into one carton")
                    carton_of_package[code] = package_no
                carried = sum((box_map[code] for code in serials), ZERO)
                if carried != qty:
                    raise ValidationError(
                        f"{package_no}: the packages picked for {item.code} carry {carried}, "
                        f"but the carton says {qty}")
            is_serialized = (item.is_serial_tracked or bool(serials)) and not box_map
            if is_serialized:
                if qty != qty.to_integral_value():
                    raise ValidationError(f"{package_no}: {item.code} serial quantity must be whole")
                if len(serials) != int(qty):
                    raise ValidationError(
                        f"{package_no}: choose exactly {int(qty)} serials for {item.code}"
                    )

            issue_line = None
            if item_data.issue_item_id is not None:
                issue_line = lines_by_id.get(item_data.issue_item_id)
                if (issue_line is None or issue_line.issue_id != source_issue.id
                        or issue_line.item_id != item.id
                        or (issue_line.batch_id or m.NO_BATCH) != batch_id):
                    raise ValidationError(
                        f"{package_no}: {item.code} names a line that is not on "
                        f"{source_issue.issue_no} for this batch")
                where = _issue_line_place(issue_line)
                packed_by_line[issue_line.id] = packed_by_line.get(issue_line.id, ZERO) + qty
                line_cap = accepted_by_line.get(issue_line.id, _d(issue_line.issued_qty))
                if packed_by_line[issue_line.id] > line_cap:
                    raise ValidationError(
                        f"{item.code} {where}: packed {packed_by_line[issue_line.id]} but "
                        f"only {line_cap} went out from there on {source_issue.issue_no}")
                own = unit_names_by_line.get(issue_line.id)
                if own and serials and not box_map:
                    stray = [value for value in serials if value.lower() not in own]
                    if stray:
                        raise ValidationError(
                            f"{item.code} {where}: {', '.join(stray[:5])} did not go out "
                            "from this location. Pick this row's own codes.")

            # The packs THIS carton holds of the line — its own share, never the
            # whole line's packs repeated in every carton (2026-10-22).
            try:
                # A line in packages is held as exactly the packages picked into the
                # carton (2026-10-26); anything else is the packer's own breakdown.
                packed = (await box_codes.carton_packs(db, serials, box_map, item.uom_code)
                          if box_map else
                          await wh_packing.package_line_packs(
                              db, item=item, issue_line=issue_line, qty=qty,
                              hierarchy_id=getattr(item_data, "pack_hierarchy_id", None),
                              entries=getattr(item_data, "pack_breakdown", None)))
            except ValidationError as exc:
                raise ValidationError(f"{package_no}: {item.code} — {exc}") from exc
            if packed:
                carton_packs.append({
                    "issue_item_id": issue_line.id if issue_line else None,
                    "item_id": item.id, "batch_id": batch_id, "quantity": str(qty),
                    **packed})

            key = (source_issue.id, item.id, batch_id)
            packed_by_key[key] = packed_by_key.get(key, ZERO) + qty
            if packed_by_key[key] > issued_by_key.get(key, ZERO):
                raise ValidationError(
                    f"{item.code}: packed quantity {packed_by_key[key]} exceeds "
                    f"{issued_by_key.get(key, ZERO)} issued for this batch on "
                    f"{source_issue.issue_no}"
                )

            batch = await db.get(m.Batch, batch_id) if batch_id != m.NO_BATCH else None
            rate = _d(item_data.rate)
            # Derived here, never taken from the client: the MR a line is filed
            # under is a trace people read, and a posted value would let any form
            # file goods against any request.
            source_mr = (mr_by_issue or {}).get(source_issue.id) or {}
            source_mr_id = source_mr.get("mr_id")
            source_mr_no = source_mr.get("mr_no")
            if is_serialized:
                for serial in serials:
                    lowered = serial.lower()
                    if lowered in used_serials:
                        raise ValidationError(f"Serial {serial} is already packed")
                    issued_serials = issued_serials_by_issue[source_issue.id]
                    serial_row = issued_serials.get(lowered)
                    if not serial_row or serial_row.item_id != item.id:
                        raise ValidationError(
                            f"Serial {serial} is not issued against {source_issue.issue_no}"
                        )
                    if batch_id != m.NO_BATCH and serial_row.batch_id != batch_id:
                        raise ValidationError(
                            f"Serial {serial} is not in the selected batch"
                        )
                    used_serials.add(lowered)
                    dispatch.items.append(m.DispatchItem(
                        line_no=line_no,
                        package_id=package.id,
                        issue_id=source_issue.id,
                        issue_no=source_issue.issue_no,
                        issue_item_id=issue_line.id if issue_line else None,
                        bin_code=issue_line.bin_code if issue_line else None,
                        **(combinations.carry(issue_line) if issue_line
                           else dict(combinations.NONE)),
                        mr_id=source_mr_id,
                        mr_no=source_mr_no,
                        indent_id=item_data.indent_id or source_issue.indent_id,
                        indent_no=source_issue.indent_no,
                        item_id=item.id,
                        item_code=item.code,
                        item_name=item.name,
                        uom_code=item.uom_code,
                        batch_id=batch_id,
                        batch_no=batch.batch_no if batch else None,
                        mfg_date=batch.mfg_date if batch else None,
                        expiry_date=batch.expiry_date if batch else None,
                        serial_no=serial,
                        # Off the unit, not off the form. The IMEI is a property of
                        # the handset in the carton; asking the packer to type it
                        # again is how it drifts from what was actually sent.
                        imei_no=serial_row.imei,
                        quantity=Decimal("1"),
                        delivered_qty=ZERO,
                        rate=rate or None,
                        amount=rate if rate else None,
                        remarks=item_data.remarks,
                    ))
                    line_no += 1
            elif box_map:
                # One row per package, carrying what that package carries.
                for code in serials:
                    part = box_map[code]
                    dispatch.items.append(m.DispatchItem(
                        line_no=line_no, package_id=package.id,
                        issue_id=source_issue.id, issue_no=source_issue.issue_no,
                        issue_item_id=issue_line.id if issue_line else None,
                        bin_code=issue_line.bin_code if issue_line else None,
                        **(combinations.carry(issue_line) if issue_line
                           else dict(combinations.NONE)),
                        mr_id=source_mr_id, mr_no=source_mr_no,
                        indent_id=item_data.indent_id or source_issue.indent_id,
                        indent_no=source_issue.indent_no,
                        item_id=item.id, item_code=item.code, item_name=item.name,
                        uom_code=item.uom_code, batch_id=batch_id,
                        batch_no=batch.batch_no if batch else None,
                        mfg_date=batch.mfg_date if batch else None,
                        expiry_date=batch.expiry_date if batch else None,
                        serial_no=None, imei_no=None, box_code=code,
                        quantity=part, delivered_qty=ZERO,
                        rate=rate or None, amount=(part * rate) if rate else None,
                        remarks=item_data.remarks,
                    ))
                    line_no += 1
            else:
                dispatch.items.append(m.DispatchItem(
                    line_no=line_no,
                    package_id=package.id,
                    issue_id=source_issue.id,
                    issue_no=source_issue.issue_no,
                    issue_item_id=issue_line.id if issue_line else None,
                    bin_code=issue_line.bin_code if issue_line else None,
                    **(combinations.carry(issue_line) if issue_line
                       else dict(combinations.NONE)),
                    mr_id=source_mr_id,
                    mr_no=source_mr_no,
                    indent_id=item_data.indent_id or source_issue.indent_id,
                    indent_no=source_issue.indent_no,
                    item_id=item.id,
                    item_code=item.code,
                    item_name=item.name,
                    uom_code=item.uom_code,
                    batch_id=batch_id,
                    batch_no=batch.batch_no if batch else None,
                    mfg_date=batch.mfg_date if batch else None,
                    expiry_date=batch.expiry_date if batch else None,
                    serial_no=None,
                    imei_no=None,
                    quantity=qty,
                    delivered_qty=ZERO,
                    rate=rate or None,
                    amount=(qty * rate) if rate else None,
                    remarks=item_data.remarks,
                ))
                line_no += 1

        package.item_packs = carton_packs or None

    # A line named on any row must be packed in full: half of one bay plus all of the
    # other adds up to the batch total and still leaves goods on the dock.
    for line_id, packed_qty in packed_by_line.items():
        line = lines_by_id[line_id]
        line_cap = accepted_by_line.get(line_id, _d(line.issued_qty))
        if packed_qty != line_cap:
            raise ValidationError(
                f"{line.item_code or line.item_id} {_issue_line_place(line)}: packed "
                f"{packed_qty} of {line_cap}")

    for key, issued_qty in issued_by_key.items():
        packed_qty = packed_by_key.get(key, ZERO)
        if packed_qty != issued_qty:
            source_issue = issues_by_id[key[0]]
            item = await db.get(Item, key[1])
            item_code = item.code if item else f"item {key[1]}"
            raise ValidationError(
                f"{source_issue.issue_no} / {item_code}: packed quantity {packed_qty} "
                f"must equal issued quantity {issued_qty}"
            )

    _dispatch_totals(dispatch)


# What an "on the way in" queue may hold. Anything past ACKNOWLEDGED has been signed
# for already and anything before DISPATCHED has not left the sending dock.
INBOUND_DISPATCH_STATUSES = (
    DispatchStatus.DISPATCHED.value,
    DispatchStatus.IN_TRANSIT.value,
    DispatchStatus.DELIVERED.value,
)


async def list_dispatches(db: AsyncSession, params: PageParams, *, status: str | None = None,
                          warehouse_id: int | None = None, search: str | None = None,
                          inbound: bool = False, user=None) -> dict:
    """Consignments this login may read; `inbound` narrows to the ones ARRIVING at it.

    The ordinary scope answers "which consignments may you see", and it is keyed on
    `warehouse_id` — the SENDING dock — because that is the point that owns the
    document. A receiving desk needs the opposite question, and asking the first one
    put every consignment in the company in front of a wide-scope login: the SCM head
    was offered the signature for goods arriving at a point he is nowhere near, and a
    receiver at an MDP was shown the consignments his own dock had sent out.

    `inbound` therefore scopes on `to_warehouse_id` against the points the login is
    actually attached to (`locations.location_ids_for_user` — their own posts and
    their reportees'), NOT against their data scope. Reading a document company-wide
    is a reporting question; signing for a lorry is a question of standing where it
    stopped. A login attached to no stocking point gets an empty queue, which is the
    honest answer — scanning a package still opens that consignment directly.
    """
    stmt = select(m.Dispatch)
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.Dispatch.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.Dispatch.created_by_id,
            project_col=m.Dispatch.project_id,
        ))
    if inbound:
        receivable = await stock_locations.location_ids_for_user(db, user) if user else set()
        stmt = stmt.where(
            m.Dispatch.to_warehouse_id.in_(receivable or {0}),
            m.Dispatch.status.in_(INBOUND_DISPATCH_STATUSES),
        )
    if status:
        stmt = stmt.where(m.Dispatch.status == status)
    if warehouse_id:
        stmt = stmt.where(m.Dispatch.warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.Dispatch.dispatch_no.ilike(like), m.Dispatch.vehicle_number.ilike(like),
            m.Dispatch.lr_no.ilike(like), m.Dispatch.customer_name.ilike(like),
            m.Dispatch.to_warehouse_name.ilike(like)))
    return await _decorate_dispatch_page_destinations(
        db,
        await paginate(db, stmt.order_by(m.Dispatch.id.desc()), params),
    )


async def list_consignments(db: AsyncSession, params: PageParams, *, status: str | None = None,
                            warehouse_id: int | None = None, search: str | None = None, user=None) -> dict:
    stmt = select(m.Dispatch)
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.Dispatch.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.Dispatch.created_by_id,
            project_col=m.Dispatch.project_id,
        )).where(
        # Every ref_type a consignment is written under — MULTI_ISSUE included, or a
        # consignment bundling several issues is packed and then never listed, so
        # neither this board nor the Dispatch queue built on it can find it again.
        m.Dispatch.ref_type.in_([kind.value for kind in ConsignmentRefType]),
        m.Dispatch.packages.any(),
    )
    # Comma-separated, because "ready to go out" is not one status. A consignment
    # sent for release comes back APPROVED, not PACKED, and the Dispatch queue asking
    # for a single value dropped every released consignment off the board it was
    # released onto. One value still behaves exactly as it always did.
    wanted = [part.strip().upper() for part in (status or "").split(",") if part.strip()]
    if wanted:
        stmt = stmt.where(m.Dispatch.status.in_(wanted))
    if warehouse_id:
        stmt = stmt.where(m.Dispatch.warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.Dispatch.dispatch_no.ilike(like),
            m.Dispatch.ref_no.ilike(like),
            m.Dispatch.customer_name.ilike(like),
            m.Dispatch.vendor_name.ilike(like),
            m.Dispatch.to_warehouse_name.ilike(like),
            m.Dispatch.delivery_address.ilike(like),
        ))
    return await _decorate_dispatch_page_destinations(
        db,
        await paginate(db, stmt.order_by(m.Dispatch.id.desc()), params),
    )


async def _dispatch_line_packs(db: AsyncSession, dispatch: m.Dispatch) -> list[dict]:
    """The packs each issue line travels in on this consignment (2026-10-22).

    A consignment holds one row PER UNIT for a coded item, so packs on a row would be
    "1 loose" fifteen times over. They are said once per issue line: what was sent,
    and — once the destination has acknowledged — what arrived. Codes stay on the
    unit rows; the packs only describe them.
    """
    sent: dict[int, Decimal] = {}
    arrived: dict[int, Decimal] = {}
    first: dict[int, m.DispatchItem] = {}
    for row in dispatch.items:
        if not row.issue_item_id:
            continue
        sent[row.issue_item_id] = sent.get(row.issue_item_id, ZERO) + _d(row.quantity)
        arrived[row.issue_item_id] = (arrived.get(row.issue_item_id, ZERO)
                                      + _d(row.delivered_qty))
        first.setdefault(row.issue_item_id, row)
    if not sent:
        return []
    packed = await wh_packing.issue_line_packs(db, sent)
    landed = await wh_packing.issue_line_packs(
        db, {k: v for k, v in arrived.items() if v > ZERO})
    out = []
    for line_id, row in first.items():
        if line_id not in packed:
            continue
        out.append({
            "issue_item_id": line_id, "item_id": row.item_id, "item_code": row.item_code,
            "item_name": row.item_name, "uom_code": row.uom_code, "batch_no": row.batch_no,
            "quantity": sent[line_id], "delivered_qty": arrived[line_id],
            **packed[line_id],
            "delivered_pack_breakdown": landed.get(line_id, {}).get("pack_breakdown"),
            "delivered_pack_text": landed.get(line_id, {}).get("pack_text"),
        })
    return out


async def get_dispatch(db: AsyncSession, dispatch_id: int, user=None) -> m.Dispatch:
    dispatch = await _load(db, m.Dispatch, dispatch_id, "Dispatch",
                           m.Dispatch.items, m.Dispatch.packages, m.Dispatch.events,
                           m.Dispatch.sources)
    dispatch = await _decorate_can_approve(
        db, dispatch, WarehouseDocType.DISPATCH.value, user)
    # Detail only: the relay hop needs the Forward button on the consignment it just
    # signed for, and answering this costs three queries — too much for a 50-row board.
    setattr(dispatch, "can_forward", await can_forward_dispatch(db, dispatch))
    setattr(dispatch, "line_packs", await _dispatch_line_packs(db, dispatch))
    # Carton › box for every package code it carries (2026-10-28), so the packing list
    # that travels with the truck says what the stickers say.
    ctx = await box_codes.pack_context(db, [row.box_code for row in dispatch.items if row.box_code])
    setattr(dispatch, "box_paths", {code: c["path"] for code, c in ctx.items()})
    setattr(dispatch, "public_scan_token", public_label_token("d", dispatch.id))
    for package in dispatch.packages:
        setattr(package, "public_scan_token", public_label_token("p", package.id))
    return await _decorate_dispatch_destination(db, dispatch)


def _guard_expected_delivery(dispatch_date, expected_delivery) -> None:
    """Goods cannot arrive before they leave.

    Checked here and not only on the form: the date arrives as a plain `date | None`
    on all three consignment/dispatch write paths and nothing compared it to the
    dispatch date, so a consignment could be saved promising delivery a week before
    it shipped. Measured against the dispatch date rather than today, because a
    consignment may be back-dated and its delivery date has to stay consistent with
    the day it actually left.
    """
    if expected_delivery is None or dispatch_date is None:
        return
    if expected_delivery < dispatch_date:
        raise ValidationError(
            f"Expected delivery {expected_delivery} is before the consignment leaves "
            f"({dispatch_date}). Pick a date on or after it."
        )


# ---------------------------------------------------------------------------
# Which material issues a consignment carries
# ---------------------------------------------------------------------------
# A consignment built from ONE issue names it on `ref_id` and lists it in
# `out_dispatch_sources`; one carrying SEVERAL issues for the same stocking point
# leaves `ref_id` NULL and lists them only there. Rows written before the table
# existed have `ref_id` alone. So every reader asks through `_carries_issue` /
# `_dispatch_issue_ids` and never through `ref_id` by itself — read `ref_id` alone and
# a grouped consignment silently carries nothing: gate-out books the stock out a
# second time, the issues never reach DISPATCHED, acknowledgement never closes the
# indents, and the requester's delivery screen never finds the parcel.


def _carries_issue(issue_id):
    """SQL: the `m.Dispatch` in scope carries this issue.

    `issue_id` may be a value or a column of an enclosing query (correlated).
    """
    return or_(
        and_(m.Dispatch.ref_type.in_(SINGLE_ISSUE_REF_TYPES), m.Dispatch.ref_id == issue_id),
        # `correlate_except`, not auto-correlation: nested inside `_relayed_onward` the
        # issue column belongs to a query two levels out, and auto-correlation only
        # looks one level up — it pulled the table in as a cross join instead.
        select(m.DispatchSource.id).where(
            m.DispatchSource.dispatch_id == m.Dispatch.id,
            m.DispatchSource.issue_id == issue_id,
        ).correlate_except(m.DispatchSource).exists(),
    )


async def _live_consignment_for_issue(db: AsyncSession, issue_id: int,
                                      *, exclude_dispatch_id: int | None = None) -> str | None:
    """The number of the non-cancelled consignment already carrying this issue."""
    return await db.scalar(
        select(m.Dispatch.dispatch_no).where(
            m.Dispatch.id != (exclude_dispatch_id or 0),
            m.Dispatch.status != DispatchStatus.CANCELLED.value,
            _carries_issue(issue_id),
        ).limit(1)
    )


async def _issue_ids_in_live_consignments(db: AsyncSession) -> set[int]:
    """Every issue some non-cancelled consignment already carries, either way."""
    single = (await db.execute(
        select(m.Dispatch.ref_id).where(
            m.Dispatch.ref_type.in_(SINGLE_ISSUE_REF_TYPES),
            m.Dispatch.ref_id.isnot(None),
            m.Dispatch.status != DispatchStatus.CANCELLED.value,
        )
    )).scalars().all()
    grouped = (await db.execute(
        select(m.DispatchSource.issue_id)
        .join(m.Dispatch, m.Dispatch.id == m.DispatchSource.dispatch_id)
        .where(m.DispatchSource.issue_id.isnot(None),
               m.Dispatch.status != DispatchStatus.CANCELLED.value)
    )).scalars().all()
    return {int(value) for value in (*single, *grouped)}


async def _dispatch_issue_ids(db: AsyncSession, dispatch: m.Dispatch) -> list[int]:
    """Every material issue this consignment carries, in the order they were added."""
    ids: list[int] = []
    if (dispatch.ref_type or "").upper() in SINGLE_ISSUE_REF_TYPES and dispatch.ref_id:
        ids.append(int(dispatch.ref_id))
    for issue_id in (await db.execute(
        select(m.DispatchSource.issue_id).where(
            m.DispatchSource.dispatch_id == dispatch.id,
            m.DispatchSource.issue_id.isnot(None),
        ).order_by(m.DispatchSource.id)
    )).scalars():
        if int(issue_id) not in ids:
            ids.append(int(issue_id))
    return ids


async def _dispatch_issues(db: AsyncSession, dispatch: m.Dispatch) -> list[m.MaterialIssue]:
    """The issues themselves, lines loaded.

    Raises rather than skipping an id that no longer resolves: gate-out reads "no
    issues" as "nothing posted the stock yet" and would book it out again.
    """
    ids = await _dispatch_issue_ids(db, dispatch)
    if not ids:
        return []
    rows = {
        row.id: row
        for row in (await db.execute(
            select(m.MaterialIssue)
            .options(selectinload(m.MaterialIssue.items))
            .where(m.MaterialIssue.id.in_(ids))
        )).scalars().all()
    }
    missing = [issue_id for issue_id in ids if issue_id not in rows]
    if missing:
        raise NotFoundError(
            f"{dispatch.dispatch_no} lists material issue(s) {missing} that no longer exist")
    return [rows[issue_id] for issue_id in ids]


def _lines_for_issue(dispatch: m.Dispatch, issue_id: int, *, grouped: bool) -> list:
    """The consignment lines packed from this issue.

    A line written before lines carried `issue_id` belongs to the consignment's one
    issue; on a grouped consignment every line names its issue, so an unnamed one is
    nobody's.
    """
    return [
        line for line in dispatch.items
        if line.issue_id == issue_id or (line.issue_id is None and not grouped)
    ]


def _consignment_issue_ids(data: s.ConsignmentWrite) -> list[int]:
    ids: list[int] = []
    if data.issue_id:
        ids.append(data.issue_id)
    ids.extend(data.issue_ids or [])
    unique = list(dict.fromkeys(issue_id for issue_id in ids if issue_id))
    if not unique:
        raise ValidationError("Select at least one material issue for the consignment")
    if len(unique) > MAX_ISSUES_PER_CONSIGNMENT:
        raise ValidationError(
            f"One consignment can carry at most {MAX_ISSUES_PER_CONSIGNMENT} material issues")
    return unique


async def _issue_mr_sources(db: AsyncSession, issue: m.MaterialIssue) -> list[dict]:
    """The material requests raised for the lines this issue serves — a trace for people.

    MR is the buying trail behind an indent; the issue is what physically ships. The
    link is soft (same indent, same item), so it is shown, never checked against.
    """
    if not issue.indent_id:
        return []
    from app.modules.inventory.models import MaterialRequest, MaterialRequestItem

    item_ids = {line.item_id for line in issue.items}
    if not item_ids:
        return []
    rows = (await db.execute(
        select(MaterialRequest.id, MaterialRequest.mr_no)
        .join(MaterialRequestItem, MaterialRequestItem.mr_id == MaterialRequest.id)
        .where(
            MaterialRequest.indent_id == issue.indent_id,
            MaterialRequest.status.notin_((MRStatus.REJECTED.value, MRStatus.CANCELLED.value)),
            MaterialRequestItem.item_id.in_(item_ids),
        )
        .group_by(MaterialRequest.id, MaterialRequest.mr_no)
        .order_by(MaterialRequest.id)
    )).all()
    return [{"mr_id": row[0], "mr_no": row[1]} for row in rows]


def _single_mr(mr_rows: list[dict]) -> dict:
    """The one MR behind an issue, or nothing when there are none or several."""
    return mr_rows[0] if len(mr_rows) == 1 else {}


def _multi_issue_ref_no(issues: list[m.MaterialIssue]) -> str:
    """`ISS/001 +2 more` — what a list screen shows for a grouped consignment."""
    return f"{issues[0].issue_no} +{len(issues) - 1} more"[:50]


async def _consignment_issues(
    db: AsyncSession,
    data: s.ConsignmentWrite,
    *,
    exclude_dispatch_id: int | None = None,
) -> list[m.MaterialIssue]:
    ids = _consignment_issue_ids(data)
    # Locked for the rest of the transaction: two storekeepers bundling the same issue
    # into two consignments at the same moment would otherwise both pass the check
    # below. Nothing else can stop it — the rule spans two tables.
    await db.execute(
        select(m.MaterialIssue.id).where(m.MaterialIssue.id.in_(ids)).with_for_update()
    )
    issues: list[m.MaterialIssue] = []
    for issue_id in ids:
        issue = await get_issue(db, issue_id)
        if issue.direction != IssueDirection.OUT.value or not issue.is_stock_posted:
            raise ValidationError(
                f"{issue.issue_no}: only a posted outward material issue can become a consignment")
        if issue.qc_status not in CONSIGNABLE_QC:
            raise ValidationError(
                f"{issue.issue_no}: outward QC is {issue.qc_status}, not passed. "
                f"Complete QC Outward before it goes to logistics.")
        existing = await _live_consignment_for_issue(
            db, issue.id, exclude_dispatch_id=exclude_dispatch_id)
        if existing is not None:
            raise ValidationError(f"{issue.issue_no} is already packed on consignment {existing}")
        issues.append(issue)

    if len({issue.warehouse_id for issue in issues}) != 1:
        raise ValidationError(
            "These material issues leave from different stocking points. One consignment "
            "is one lorry from one place — pick issues from the same point.")
    return issues


async def _consignment_destination(
    db: AsyncSession,
    issues: list[m.MaterialIssue],
    data: s.ConsignmentWrite,
    wh: Warehouse,
) -> Warehouse | None:
    """Where the consignment goes.

    Each issue's own destination is the stocking point serving the office it is for.
    Several issues share a consignment only when that point is the SAME for all of
    them — that is the whole rule of a grouped consignment. The packer may still route
    the lot through another point (a relay via an MDP) by choosing `to_warehouse_id`,
    but the choice applies to the lot; it never makes issues for two different LIPs
    into one delivery.
    """
    natural = [await _destination_warehouse(db, issue, wh.id) for issue in issues]
    if len(issues) > 1:
        for issue, point in zip(issues, natural):
            if point is None:
                raise ValidationError(
                    f"{issue.issue_no} has no stocking point to deliver to, so it cannot "
                    "share a consignment. Send it on its own.")
        names = {point.id: point.name for point in natural if point is not None}
        if len(names) > 1:
            raise ValidationError(
                "These material issues are going to different stocking points ("
                + ", ".join(sorted(names.values()))
                + "). Only issues for the same LIP/MDP can travel in one consignment.")

    explicit = await db.get(Warehouse, data.to_warehouse_id) if data.to_warehouse_id else None
    to_wh = explicit or natural[0]
    if data.dispatch_type == DispatchType.TRANSFER and to_wh is None:
        raise ValidationError("A stock transfer consignment needs a destination warehouse")
    if to_wh is not None and to_wh.id == wh.id:
        raise ValidationError("A transfer cannot have the same origin and destination")
    for issue in issues:
        _guard_leaves_the_company(data.dispatch_type, to_wh, issue)
    return to_wh


async def _write_dispatch_sources(
    db: AsyncSession,
    dispatch: m.Dispatch,
    issues: list[m.MaterialIssue],
    to_wh: Warehouse | None,
    mr_by_issue: dict[int, dict],
) -> None:
    """One `out_dispatch_sources` row per issue — rewritten whole on every save."""
    dispatch.sources.clear()
    # Flushed before the new rows go in: the unit of work inserts before it deletes,
    # and re-listing the same issue would trip the (dispatch_id, issue_id) unique key.
    await db.flush()
    for issue in issues:
        mr = mr_by_issue.get(issue.id) or {}
        dispatch.sources.append(m.DispatchSource(
            dispatch_id=dispatch.id,
            source_type=DispatchSourceType.ISSUE.value,
            source_id=issue.id,
            source_no=issue.issue_no,
            issue_id=issue.id,
            issue_no=issue.issue_no,
            mr_id=mr.get("mr_id"),
            mr_no=mr.get("mr_no"),
            indent_id=issue.indent_id,
            indent_no=issue.indent_no,
            destination_warehouse_id=to_wh.id if to_wh else None,
            destination_warehouse_name=to_wh.name if to_wh else None,
            quantity=_d(issue.total_qty),
        ))


async def _build_consignment(db: AsyncSession, data: s.ConsignmentWrite, user) -> m.Dispatch:
    """Build one consignment without committing it — see _build_picking / _build_issue.

    A consignment and a dispatch are the same `out_dispatches` row: this writes it at
    PACKED, and gate_out() later moves that same row out of the gate. There is no
    separate dispatch document to raise.
    """
    issues = await _consignment_issues(db, data)
    issue = issues[0]
    multi = len(issues) > 1
    wh = await _warehouse(db, issue.warehouse_id)
    to_wh = await _consignment_destination(db, issues, data, wh)
    mr_by_issue = {row.id: _single_mr(await _issue_mr_sources(db, row)) for row in issues}
    # Nothing to carry. The issue came OUT of the very point that raised the indent —
    # an OE serving his own LIP — so the goods are already on the requester's shelf.
    # Left to run, this wrote a consignment with a blank destination, and a blank
    # destination is the one thing `incoming_dispatch_options` cannot match: the
    # storekeeper acknowledged the delivery and then had no consignment to raise a
    # GRN against. Say it here, where it can still be acted on.
    if to_wh is None and not data.customer_id and not data.vendor_id:
        same_points = [await _requesting_point(db, row) for row in issues]
        if all(point is not None and point.id == wh.id for point in same_points):
            raise ValidationError(
                f"{', '.join(row.issue_no for row in issues)} was issued at {wh.name}, "
                "the point that raised the "
                "indent — the goods are already there. Acknowledge the issue instead "
                "of raising a consignment, or pick a destination to forward it on."
            )
    _guard_expected_delivery(data.dispatch_date, data.expected_delivery)
    vendor = await db.get(Vendor, data.vendor_id) if data.vendor_id else None
    _, destination_office_name = await _issue_destination(db, issue)
    project_id, project_name = await _consignment_project(db, issue, data.project_id)

    dispatch = m.Dispatch(
        items=[], packages=[], events=[], sources=[],
        # From the issue it ships — see the note on the GRN above.
        dispatch_no=await _consignment_no(db, project_name),
        dispatch_type=data.dispatch_type.value,
        dispatch_date=data.dispatch_date,
        warehouse_id=wh.id,
        warehouse_name=wh.name,
        warehouse_address=wh.address,
        to_warehouse_id=to_wh.id if to_wh else None,
        to_warehouse_name=to_wh.name if to_wh else None,
        customer_id=data.customer_id,
        vendor_id=data.vendor_id,
        vendor_name=vendor.name if vendor else None,
        project_id=project_id,
        # Snapshot the name beside the id, the way every other document here does
        # (rule 10). Live consignments carry project_id 4 with project_name NULL, so
        # the dispatch board and its printouts show a blank where the project goes.
        project_name=project_name,
        delivery_address=(data.delivery_address
                          or _address_without_vehicle(destination_office_name)),
        contact_person=data.contact_person,
        contact_phone=data.contact_phone,
        ref_type=(ConsignmentRefType.MULTI_ISSUE.value if multi
                  else ConsignmentRefType.WH_ISSUE.value),
        ref_id=None if multi else issue.id,
        ref_no=_multi_issue_ref_no(issues) if multi else issue.issue_no,
        transport_mode=data.transport_mode,
        carrier_id=data.carrier_id,
        vehicle_id=data.vehicle_id,
        vehicle_number=_consignment_vehicle(issue, destination_office_name),
        driver_name=data.driver_name,
        driver_phone=data.driver_phone,
        lr_no=data.lr_no,
        eway_bill_no=data.eway_bill_no,
        freight_amount=data.freight_amount,
        expected_delivery=data.expected_delivery,
        status=DispatchStatus.PACKED.value,
        remarks=data.remarks,
        created_by_id=getattr(user, "id", None),
        created_by_name=_name(user),
    )
    db.add(dispatch)
    await db.flush()
    await _write_dispatch_sources(db, dispatch, issues, to_wh, mr_by_issue)
    await _apply_consignment_packages(db, dispatch, issues, data.packages, user, mr_by_issue)
    for row in issues:
        _validate_issue_dispatch(dispatch, row)
    dispatch.status = DispatchStatus.PACKED.value
    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.CREATE, actor=user,
                      after={"status": dispatch.status, "packages": len(dispatch.packages)})
    return dispatch


async def create_consignment(db: AsyncSession, data: s.ConsignmentWrite, user) -> m.Dispatch:
    dispatch = await _build_consignment(db, data, user)
    await db.commit()
    return await get_dispatch(db, dispatch.id)


async def update_consignment(db: AsyncSession, dispatch_id: int, data: s.ConsignmentWrite,
                             user) -> m.Dispatch:
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status, {DispatchStatus.DRAFT.value, DispatchStatus.PACKED.value},
           "edit", "consignment")
    issues = await _consignment_issues(db, data, exclude_dispatch_id=dispatch_id)
    # What a consignment carries is decided when it is raised. Moving it onto other
    # issues is a different consignment — cancel this one and raise that.
    carried = await _dispatch_issue_ids(db, dispatch)
    if carried and set(carried) != {row.id for row in issues}:
        raise ValidationError(
            "A consignment cannot be moved to other material issues — cancel it and "
            "raise a new one")
    issue = issues[0]
    multi = len(issues) > 1
    wh = await _warehouse(db, issue.warehouse_id)
    to_wh = await _consignment_destination(db, issues, data, wh)
    mr_by_issue = {row.id: _single_mr(await _issue_mr_sources(db, row)) for row in issues}
    _guard_expected_delivery(data.dispatch_date, data.expected_delivery)
    vendor = await db.get(Vendor, data.vendor_id) if data.vendor_id else None
    _, destination_office_name = await _issue_destination(db, issue)

    before = {"status": dispatch.status, "packages": dispatch.total_packages}
    dispatch.dispatch_type = data.dispatch_type.value
    dispatch.dispatch_date = data.dispatch_date
    dispatch.warehouse_id = wh.id
    dispatch.warehouse_name = wh.name
    dispatch.warehouse_address = wh.address
    dispatch.to_warehouse_id = to_wh.id if to_wh else None
    dispatch.to_warehouse_name = to_wh.name if to_wh else None
    dispatch.customer_id = data.customer_id
    dispatch.vendor_id = data.vendor_id
    dispatch.vendor_name = vendor.name if vendor else None
    dispatch.project_id = data.project_id or issue.project_id
    dispatch.delivery_address = (data.delivery_address
                                 or _address_without_vehicle(destination_office_name))
    dispatch.contact_person = data.contact_person
    dispatch.contact_phone = data.contact_phone
    dispatch.ref_type = (ConsignmentRefType.MULTI_ISSUE.value if multi
                         else ConsignmentRefType.WH_ISSUE.value)
    dispatch.ref_id = None if multi else issue.id
    dispatch.ref_no = _multi_issue_ref_no(issues) if multi else issue.issue_no
    dispatch.transport_mode = data.transport_mode
    dispatch.carrier_id = data.carrier_id
    dispatch.vehicle_id = data.vehicle_id
    dispatch.vehicle_number = _consignment_vehicle(issue, destination_office_name)
    dispatch.driver_name = data.driver_name
    dispatch.driver_phone = data.driver_phone
    dispatch.lr_no = data.lr_no
    dispatch.eway_bill_no = data.eway_bill_no
    dispatch.freight_amount = data.freight_amount
    dispatch.expected_delivery = data.expected_delivery
    dispatch.remarks = data.remarks

    await _write_dispatch_sources(db, dispatch, issues, to_wh, mr_by_issue)
    await _apply_consignment_packages(db, dispatch, issues, data.packages, user, mr_by_issue)
    for row in issues:
        _validate_issue_dispatch(dispatch, row)
    dispatch.status = DispatchStatus.PACKED.value
    await db.flush()
    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
                      before=before,
                      after={"status": dispatch.status, "packages": dispatch.total_packages})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def create_dispatch(db: AsyncSession, data: s.DispatchWrite, user) -> m.Dispatch:
    wh = await _warehouse(db, data.warehouse_id)
    if not data.items:
        raise ValidationError("A dispatch with no lines has nothing to send")

    to_wh = await db.get(Warehouse, data.to_warehouse_id) if data.to_warehouse_id else None
    _guard_expected_delivery(data.dispatch_date, data.expected_delivery)

    vendor = await db.get(Vendor, data.vendor_id) if data.vendor_id else None
    ref_issue = None
    destination_office_name = None
    if (data.ref_type or "").upper() in {"ISSUE", "WH_ISSUE"}:
        if not data.ref_id:
            raise ValidationError("An issue-linked dispatch needs an issue reference")
        ref_issue = await get_issue(db, data.ref_id)
        if not ref_issue.is_stock_posted:
            raise ValidationError(f"{ref_issue.issue_no} has not posted stock yet")
        if ref_issue.qc_status not in CONSIGNABLE_QC:
            raise ValidationError(
                f"{ref_issue.issue_no}: outward QC is {ref_issue.qc_status}, not passed")
        if ref_issue.warehouse_id != wh.id:
            raise ValidationError(f"{ref_issue.issue_no} belongs to another warehouse")
        existing = await _live_consignment_for_issue(db, ref_issue.id)
        if existing is not None:
            raise ValidationError(
                f"{ref_issue.issue_no} already has dispatch {existing}"
            )
        _, destination_office_name = await _issue_destination(db, ref_issue)

    # Derive the destination from the issue when nobody typed one. Has to sit here, not
    # up with the other to_wh handling: it needs the issue, and the issue is only loaded
    # above. It read an undefined `issue` there and raised NameError on every dispatch
    # that left the field blank — which is every issue-linked delivery, since the form
    # labels that field "for transfer only".
    if to_wh is None and ref_issue is not None:
        to_wh = await _destination_warehouse(db, ref_issue, wh.id)

    if data.dispatch_type == DispatchType.TRANSFER and to_wh is None:
        raise ValidationError("A stock transfer needs a destination warehouse")
    if to_wh is not None and to_wh.id == wh.id:
        raise ValidationError("A transfer cannot have the same origin and destination")
    _guard_leaves_the_company(data.dispatch_type, to_wh, ref_issue)
    project_id, project_name = await _consignment_project(db, ref_issue, data.project_id)

    dispatch = m.Dispatch(
        # See create_issue. All three are delete-orphan collections, so the flush wants
        # them loaded to work out the cascade — which is a lazy load, which an
        # AsyncSession cannot do.
        items=[], packages=[], events=[],
        # From the issue it ships — see the note on the GRN above.
        dispatch_no=await _consignment_no(db, project_name),
        dispatch_type=data.dispatch_type.value,
        dispatch_date=data.dispatch_date,
        warehouse_id=wh.id, warehouse_name=wh.name, warehouse_address=wh.address,
        to_warehouse_id=to_wh.id if to_wh else None,
        to_warehouse_name=to_wh.name if to_wh else None,
        customer_id=data.customer_id,
        vendor_id=data.vendor_id, vendor_name=vendor.name if vendor else None,
        project_id=project_id, project_name=project_name,
        delivery_address=data.delivery_address or destination_office_name,
        contact_person=data.contact_person, contact_phone=data.contact_phone,
        ref_type=data.ref_type, ref_id=data.ref_id,
        ref_no=ref_issue.issue_no if ref_issue else None,
        transport_mode=data.transport_mode,
        carrier_id=data.carrier_id, vehicle_id=data.vehicle_id,
        driver_name=data.driver_name, driver_phone=data.driver_phone,
        lr_no=data.lr_no, eway_bill_no=data.eway_bill_no,
        freight_amount=data.freight_amount,
        expected_delivery=data.expected_delivery,
        status=DispatchStatus.DRAFT.value,
        remarks=data.remarks,
        created_by_id=getattr(user, "id", None), created_by_name=_name(user),
    )
    db.add(dispatch)
    await db.flush()

    await _apply_dispatch_lines(db, dispatch, data.items)
    if ref_issue:
        _validate_issue_dispatch(dispatch, ref_issue)
    await db.flush()

    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.CREATE, actor=user,
                      after={"status": dispatch.status, "total_qty": str(dispatch.total_qty)})
    await db.commit()
    return await get_dispatch(db, dispatch.id)


async def update_dispatch(db: AsyncSession, dispatch_id: int, data: s.DispatchWrite,
                          user) -> m.Dispatch:
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status, {DispatchStatus.DRAFT.value}, "edit", "dispatch")

    before = {"total_qty": str(dispatch.total_qty)}
    wh = await _warehouse(db, data.warehouse_id)
    to_wh = await db.get(Warehouse, data.to_warehouse_id) if data.to_warehouse_id else None

    dispatch.dispatch_type = data.dispatch_type.value
    dispatch.dispatch_date = data.dispatch_date
    dispatch.warehouse_id = wh.id
    dispatch.warehouse_name = wh.name
    dispatch.warehouse_address = wh.address
    dispatch.to_warehouse_id = to_wh.id if to_wh else None
    dispatch.to_warehouse_name = to_wh.name if to_wh else None
    dispatch.customer_id = data.customer_id
    dispatch.vendor_id = data.vendor_id
    dispatch.project_id = data.project_id
    dispatch.contact_person = data.contact_person
    dispatch.contact_phone = data.contact_phone
    dispatch.ref_type = data.ref_type
    dispatch.ref_id = data.ref_id
    ref_issue = None
    if (data.ref_type or "").upper() in {"ISSUE", "WH_ISSUE"} and data.ref_id:
        ref_issue = await get_issue(db, data.ref_id)
        if not ref_issue.is_stock_posted:
            raise ValidationError(f"{ref_issue.issue_no} has not posted stock yet")
        if ref_issue.warehouse_id != wh.id:
            raise ValidationError(f"{ref_issue.issue_no} belongs to another warehouse")
    dispatch.ref_no = ref_issue.issue_no if ref_issue else None
    # After `ref_issue` is resolved, so an issue-linked edit is judged on what the
    # consignment is actually carrying. Nothing is committed until the end of this
    # function, so raising here leaves the row exactly as it was.
    _guard_leaves_the_company(data.dispatch_type, to_wh, ref_issue)
    _, destination_office_name = await _issue_destination(db, ref_issue)
    dispatch.delivery_address = data.delivery_address or destination_office_name
    dispatch.transport_mode = data.transport_mode
    dispatch.carrier_id = data.carrier_id
    dispatch.vehicle_id = data.vehicle_id
    dispatch.driver_name = data.driver_name
    dispatch.driver_phone = data.driver_phone
    dispatch.lr_no = data.lr_no
    dispatch.eway_bill_no = data.eway_bill_no
    dispatch.freight_amount = data.freight_amount
    dispatch.expected_delivery = data.expected_delivery
    dispatch.remarks = data.remarks

    await _apply_dispatch_lines(db, dispatch, data.items)
    if ref_issue:
        _validate_issue_dispatch(dispatch, ref_issue)
    await db.flush()

    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
                      before=before, after={"total_qty": str(dispatch.total_qty)})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def _apply_dispatch_submit(db: AsyncSession, dispatch: m.Dispatch, user):
    """Start the consignment's approval chain and set its status from the answer.

    Split out of `submit_dispatch` for the same reason `_apply_gate_out` was: the
    release guard (`transport_release_blocked`) has to ask the ladder the real
    question — does anyone actually have to sign this — and it runs inside the
    transport service's transaction. Neither commits nor audits; the caller owns both.
    Returns the workflow instance, so "nobody had to sign" is distinguishable from
    "it is now with an approver".
    """
    context = {
        "warehouse_id": dispatch.warehouse_id,
        "total_value": float(_d(dispatch.total_value)),
        "dispatch_type": dispatch.dispatch_type,
    }
    context.update({
        "doc_no": dispatch.dispatch_no,
        "doc_summary": f"Dispatch {dispatch.dispatch_no}",
        "requester_position_id": getattr(user, "active_position_id", None),
    })
    instance = await engine.start(
        db, WarehouseDocType.DISPATCH.value, dispatch.id, context, user
    )
    if instance.status == InstanceStatus.APPROVED.value:
        dispatch.status = DispatchStatus.APPROVED.value
        dispatch.approved_by_name = _name(user)
        dispatch.approved_at = utcnow()
        dispatch.current_approver_name = None
    else:
        approvers = await engine.current_approvers(
            db, WarehouseDocType.DISPATCH.value, dispatch.id
        )
        dispatch.current_approver_name = _approver_label(
            approvers,
            await _approver_rank(db, WarehouseDocType.DISPATCH.value, dispatch.id))
        dispatch.status = DispatchStatus.PENDING_APPROVAL.value
    return instance


async def submit_dispatch(db: AsyncSession, dispatch_id: int, user) -> m.Dispatch:
    dispatch = await get_dispatch(db, dispatch_id)
    # PACKED as well as DRAFT: a consignment is packed before anyone is asked to
    # release it, so PACKED is the normal state to submit from — the Consignments
    # screen saves straight to it. Allowing only DRAFT meant a packed consignment
    # could never enter its own approval chain.
    _guard(dispatch.status,
           {DispatchStatus.DRAFT.value, DispatchStatus.PACKED.value},
           "submit", "dispatch")

    await _apply_dispatch_submit(db, dispatch, user)

    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": DispatchStatus.DRAFT.value},
                      after={"status": dispatch.status})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def act_on_dispatch(
    db: AsyncSession, dispatch_id: int, action: str, comments: str, user,
) -> m.Dispatch:
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(
        dispatch.status, {DispatchStatus.PENDING_APPROVAL.value},
        action.lower(), "dispatch",
    )
    before = dispatch.status
    instance = await engine.act(
        db,
        WarehouseDocType.DISPATCH.value,
        dispatch.id,
        action,
        user,
        comments,
        context={
            "doc_no": dispatch.dispatch_no,
            "doc_summary": f"Dispatch {dispatch.dispatch_no}",
            "warehouse_id": dispatch.warehouse_id,
            "dispatch_type": dispatch.dispatch_type,
            "total_value": float(_d(dispatch.total_value)),
        },
    )
    if instance.status == InstanceStatus.APPROVED.value:
        dispatch.status = DispatchStatus.APPROVED.value
        dispatch.approved_by_name = _name(user)
        dispatch.approved_at = utcnow()
        dispatch.current_approver_name = None
    elif instance.status == InstanceStatus.REJECTED.value:
        dispatch.status = DispatchStatus.REJECTED.value
        dispatch.current_approver_name = None
    else:
        dispatch.current_approver_name = _approver_label(
            await engine.current_approvers(
                db, WarehouseDocType.DISPATCH.value, dispatch.id
            ),
            await _approver_rank(db, WarehouseDocType.DISPATCH.value, dispatch.id),
        )

    await write_audit(
        db, entity="out_dispatches", entity_id=dispatch.id,
        entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": dispatch.status, "comments": comments},
    )
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def add_package(db: AsyncSession, dispatch_id: int, data: s.PackageWrite,
                      user) -> m.Dispatch:
    """Boxes some lines up.

    Assigning lines to a package is what makes an "it arrived short" call answerable:
    `out_dispatch_items.package_id` says which carton each item went into.
    """
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status,
           {DispatchStatus.APPROVED.value, DispatchStatus.PACKED.value,
            DispatchStatus.DRAFT.value},
           "pack", "dispatch")

    sequence = len(dispatch.packages) + 1
    package = m.DispatchPackage(
        dispatch_id=dispatch.id,
        package_no=f"{dispatch.dispatch_no}-P{sequence:02d}",
        package_type=data.package_type,
        barcode=f"{dispatch.dispatch_no}|P{sequence:02d}",
        weight_kg=data.weight_kg,
        length_cm=data.length_cm, width_cm=data.width_cm, height_cm=data.height_cm,
        is_fragile=data.is_fragile, is_temp_controlled=data.is_temp_controlled,
        status=PackageStatus.PACKED.value,
        packed_by_name=_name(user), packed_at=utcnow(),
    )
    dispatch.packages.append(package)
    await db.flush()

    if data.item_ids:
        by_id = {l.id: l for l in dispatch.items}
        for line_id in data.item_ids:
            line = by_id.get(line_id)
            if line is None:
                raise ValidationError(f"Line {line_id} is not on {dispatch.dispatch_no}")
            if line.package_id:
                raise ValidationError(
                    f"{line.item_code or line.item_id} is already in another package")
            line.package_id = package.id

    _dispatch_totals(dispatch)
    if dispatch.status == DispatchStatus.APPROVED.value:
        dispatch.status = DispatchStatus.PACKED.value

    await write_audit(db, entity="out_dispatch_packages", entity_id=package.id,
                      entity_no=package.package_no, action=AuditAction.CREATE, actor=user,
                      after={"lines": len(data.item_ids)})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def delete_package(db: AsyncSession, dispatch_id: int, package_id: int,
                         user) -> m.Dispatch:
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status,
           {DispatchStatus.APPROVED.value, DispatchStatus.PACKED.value,
            DispatchStatus.DRAFT.value},
           "unpack", "dispatch")

    package = next((p for p in dispatch.packages if p.id == package_id), None)
    if package is None:
        raise NotFoundError(f"Package {package_id} is not on {dispatch.dispatch_no}")

    for line in dispatch.items:
        if line.package_id == package_id:
            line.package_id = None

    dispatch.packages.remove(package)
    await db.flush()
    _dispatch_totals(dispatch)

    await write_audit(db, entity="out_dispatch_packages", entity_id=package_id,
                      entity_no=package.package_no, action=AuditAction.DEACTIVATE, actor=user,
                      before={"package_no": package.package_no})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def _dispatch_approval_pending(db: AsyncSession, dispatch: m.Dispatch,
                                     user) -> bool:
    """Does this consignment still owe a signature before it may leave?

    Gate-out has always accepted PACKED as well as APPROVED, so Confirm dispatch took
    goods out of the building without the DISPATCH workflow ever starting. A Logistics
    ladder configured on Approvals Config would simply never fire, which reads as the
    screen being ignored.

    Deliberately conditional on a ladder EXISTING for this scope. Where nobody has
    configured one, nothing changes and a packed consignment still gates straight out —
    this must not become a new mandatory step for every site that never asked for one.
    Configuring a Dispatch chain is what turns it on, which is the whole contract of
    that screen.

    Returns True when the caller should stop and leave the document in approval.
    """
    if dispatch.status == DispatchStatus.APPROVED.value:
        return False

    project_id, _project_name = await wf_ladder.project_for(
        db, getattr(user, "active_position_id", None), user)
    if await wf_ladder.find_ladder(
            db, project_id, WarehouseDocType.DISPATCH.value) is None:
        return False

    instance = (await db.execute(
        select(WfInstance)
        .where(WfInstance.doc_type == WarehouseDocType.DISPATCH.value,
               WfInstance.doc_id == dispatch.id)
        .order_by(WfInstance.id.desc()).limit(1)
    )).scalars().first()
    if instance is not None and instance.status == InstanceStatus.APPROVED.value:
        return False
    if instance is not None and instance.status == InstanceStatus.IN_PROGRESS.value:
        raise ValidationError(
            f"{dispatch.dispatch_no} is waiting on "
            f"{dispatch.current_approver_name or 'approval'} and cannot leave yet"
        )

    # Never submitted. Send it rather than refusing: to the person at the gate,
    # "Confirm dispatch" means "send this consignment", and where the project asks for
    # a signature that means starting the chain, not an error telling them to go and
    # find another button. If the chain resolves to NO_APPROVAL the engine returns it
    # approved immediately and gate-out carries straight on below.
    dispatch = await submit_dispatch(db, dispatch.id, user)
    return dispatch.status != DispatchStatus.APPROVED.value


async def gate_out(db: AsyncSession, dispatch_id: int, gate_pass_no: str | None,
                   user) -> m.Dispatch:
    """Releases the consignment and takes the stock out of the warehouse.

    This is where a dispatch moves stock, not at packing: goods on the packing bench
    are still yours. A transfer only takes stock out here; it comes back in at the
    destination through that site's own GRN, so it is never in two places at once.
    """
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status, {DispatchStatus.APPROVED.value, DispatchStatus.PACKED.value},
           "gate out", "dispatch")
    if await _dispatch_approval_pending(db, dispatch, user):
        # Now with its approvers. The goods stay on the bench until they sign.
        return await get_dispatch(db, dispatch_id)

    await _apply_gate_out(db, dispatch, gate_pass_no, user)

    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": DispatchStatus.PACKED.value},
                      after={"status": dispatch.status,
                             "gate_pass_no": dispatch.gate_pass_no})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def _apply_gate_out(db: AsyncSession, dispatch: m.Dispatch,
                          gate_pass_no: str | None, user) -> None:
    """The gate-out itself: stock leaves, the consignment reads DISPATCHED.

    Split out so the logistics desk releasing the same load (`hooks.ON_RELEASE`) does
    exactly this and not a second, drifting copy of it. Neither commits nor audits —
    both callers are mid-transaction and own their own audit row.
    """
    # The issues behind it posted the stock out already — every one of them, on a
    # grouped consignment. Read through `_dispatch_issues`, never `ref_id` alone: a
    # grouped consignment has no `ref_id`, and taking the no-issue branch below for it
    # booked the same goods out of the warehouse a second time.
    linked_issues = await _dispatch_issues(db, dispatch)
    grouped = len(linked_issues) > 1
    for linked_issue in linked_issues:
        if not linked_issue.is_stock_posted:
            raise ValidationError(
                f"{linked_issue.issue_no} has not posted stock yet; dispatch cannot gate out"
            )
        if linked_issue.warehouse_id != dispatch.warehouse_id:
            raise ValidationError(
                f"{linked_issue.issue_no} belongs to a different warehouse"
            )
        issued_by_item: dict[int, Decimal] = {}
        for line in linked_issue.items:
            issued_by_item[line.item_id] = (
                issued_by_item.get(line.item_id, ZERO) + _d(line.issued_qty)
            )
        dispatched_by_item: dict[int, Decimal] = {}
        for line in _lines_for_issue(dispatch, linked_issue.id, grouped=grouped):
            dispatched_by_item[line.item_id] = (
                dispatched_by_item.get(line.item_id, ZERO) + _d(line.quantity)
            )
        for item_id, qty in dispatched_by_item.items():
            if qty > issued_by_item.get(item_id, ZERO):
                raise ValidationError(
                    f"Item {item_id}: dispatch quantity {qty} exceeds the "
                    f"{issued_by_item.get(item_id, ZERO)} posted on {linked_issue.issue_no}."
                )
    already_issued = bool(linked_issues)

    if not already_issued:
        # One movement per lot, same as the inward leg — see `_dispatch_lots`. Walking
        # the per-unit lines wrote a quantity-1 OUT row for every unit that left the
        # gate, which is the same defect the arrival credit had, on the other side of
        # the journey. FIXED 2026-08-22.
        for item_id, batch_id, combo, qty in _dispatch_lots(dispatch.items, "quantity"):
            # No issue behind this consignment, so the units are claimed against the
            # consignment itself. Without this a directly-gated dispatch left its
            # units on the source shelf, free to be picked again tomorrow.
            units = await _ship_units(
                db, item_id=item_id, warehouse_id=dispatch.warehouse_id,
                qty=qty, batch_id=batch_id,
                marker=_shipped_unit_marker("dispatch", dispatch.id),
            )
            await move_stock_out(
                db, item_id=item_id, qty=qty,
                ref_type=InventoryRefType.DISPATCH.value, ref_id=dispatch.id,
                ref_no=dispatch.dispatch_no, user=user,
                warehouse_id=dispatch.warehouse_id,
                batch_id=batch_id,
                project_id=dispatch.project_id or 0,
                serial_numbers=units or None,
                brand_id=combo[0] or None, variant_id=combo[1], model_id=combo[2],
            )

    # The dispatch's own number off the DISPATCH series, never the consignment's with
    # GP/ in front — see `logistics.transport._assign_dispatch_no`, the other door.
    dispatch.gate_pass_no = gate_pass_no or await next_number(
        db, WarehouseDocType.DISPATCH.value, project=dispatch.project_name)
    dispatch.gate_out_at = utcnow()
    dispatch.security_by_name = _name(user)
    dispatch.status = DispatchStatus.DISPATCHED.value
    for linked_issue in linked_issues:
        linked_issue.status = IssueStatus.DISPATCHED.value

    for package in dispatch.packages:
        package.status = PackageStatus.LOADED.value

    db.add(m.DispatchEvent(
        dispatch_id=dispatch.id, event_type="GATE_OUT", event_at=utcnow(),
        location_name=dispatch.warehouse_name, is_breach=False,
        recorded_by_id=getattr(user, "id", None), recorded_by_name=_name(user),
    ))


async def add_dispatch_event(db: AsyncSession, dispatch_id: int, data: s.DispatchEventWrite,
                             user) -> m.Dispatch:
    """Records a stop, a scan or a temperature reading.

    A breach is decided here, not sent by the client: the thresholds live on the
    destination's `whs_locations` row, and a reading outside them is a breach whatever
    the device that reported it thinks.
    """
    dispatch = await get_dispatch(db, dispatch_id)
    if dispatch.status in (DispatchStatus.DRAFT.value, DispatchStatus.CANCELLED.value):
        raise ValidationError(
            f"Cannot record an event against a dispatch that is {dispatch.status}")

    is_breach = False
    if data.temperature_c is not None:
        is_breach = await _is_temperature_breach(db, dispatch, _d(data.temperature_c))

    db.add(m.DispatchEvent(
        dispatch_id=dispatch.id,
        event_type=data.event_type.value,
        event_at=utcnow(),
        location_name=data.location_name,
        latitude=data.latitude, longitude=data.longitude,
        temperature_c=data.temperature_c, humidity_percent=data.humidity_percent,
        is_breach=is_breach, notes=data.notes,
        recorded_by_id=getattr(user, "id", None), recorded_by_name=_name(user),
    ))

    if (
        data.event_type == DispatchEventType.IN_TRANSIT
        and dispatch.status == DispatchStatus.DISPATCHED.value
    ):
        dispatch.status = DispatchStatus.IN_TRANSIT.value
    if data.event_type == DispatchEventType.DELIVERED:
        dispatch.status = DispatchStatus.DELIVERED.value
        dispatch.delivered_at = utcnow()
        # Recording the consignment as delivered is the claim that all of it arrived —
        # the same claim `acknowledge_dispatch` records when no per-line detail is
        # given. Without it `out_dispatch_items.delivered_qty` stays 0, and the
        # indent's Delivery phase sits PENDING on goods the warehouse has already
        # handed over. A later acknowledgement overwrites these with what the
        # receiver actually counted, so a shortage still ends up on the record.
        for line in dispatch.items:
            if _d(line.delivered_qty) <= ZERO:
                line.delivered_qty = _d(line.quantity)

    await write_audit(db, entity="out_dispatch_events", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.CREATE, actor=user,
                      after={"event_type": data.event_type.value, "is_breach": is_breach})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def _is_temperature_breach(db: AsyncSession, dispatch: m.Dispatch,
                                 reading: Decimal) -> bool:
    """True when the reading is outside the destination's allowed range.

    With no temperature-controlled location on the destination there is no range to
    breach, so a reading is recorded and not flagged — flagging everything would make
    the flag meaningless.
    """
    if not dispatch.to_warehouse_id:
        return False
    row = (await db.execute(
        select(m.WarehouseLocation).where(
            m.WarehouseLocation.warehouse_id == dispatch.to_warehouse_id,
            m.WarehouseLocation.temperature_controlled.is_(True),
            m.WarehouseLocation.is_active.is_(True)).limit(1)
    )).scalar_one_or_none()
    if row is None:
        return False
    low = _d(row.min_temperature_celsius) if row.min_temperature_celsius is not None else None
    high = _d(row.max_temperature_celsius) if row.max_temperature_celsius is not None else None
    return (low is not None and reading < low) or (high is not None and reading > high)


async def acknowledge_dispatch(db: AsyncSession, dispatch_id: int, data: s.AcknowledgeWrite,
                               user) -> m.Dispatch:
    """Confirms what actually arrived, line by line.

    Delivered quantity is recorded per line rather than accepted wholesale: an
    acknowledgement on a consignment that arrived two cartons short is exactly the
    record that makes a shortage unprovable later.
    """
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status,
           {DispatchStatus.DISPATCHED.value, DispatchStatus.IN_TRANSIT.value,
            DispatchStatus.DELIVERED.value},
           "acknowledge", "dispatch")

    short = await _apply_dispatch_acknowledgement(db, dispatch, data, user)

    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": DispatchStatus.IN_TRANSIT.value},
                      after={"status": dispatch.status, "short_qty": str(short)})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


async def _apply_dispatch_acknowledgement(db: AsyncSession, dispatch: m.Dispatch,
                                          data: s.AcknowledgeWrite, user) -> Decimal:
    """Sign the consignment off and settle what it was carrying.

    Split out so the logistics desk taking the same signature on the transport leg
    (`hooks.ON_ACKNOWLEDGE`) settles the issue and the indent through exactly this
    path. Neither commits nor audits — both callers own their transaction. Returns the
    shortfall, for the caller's audit row.
    """
    by_id = {l.id: l for l in dispatch.items}
    for entry in data.lines:
        line = by_id.get(entry.id)
        if line is None:
            raise ValidationError(f"Line {entry.id} is not on {dispatch.dispatch_no}")
        delivered = _d(entry.delivered_qty)
        if delivered < ZERO or delivered > _d(line.quantity):
            raise ValidationError(
                f"{line.item_code or line.item_id}: delivered quantity must be between "
                f"0 and {line.quantity}")
        line.delivered_qty = delivered

    # No per-line detail means everything arrived; that is a claim worth recording
    # explicitly rather than leaving the column at zero.
    if not data.lines:
        for line in dispatch.items:
            line.delivered_qty = _d(line.quantity)

    short = sum((_d(l.quantity) - _d(l.delivered_qty) for l in dispatch.items), ZERO)

    await credit_arrival(db, dispatch, user)

    dispatch.acknowledged_by_name = data.acknowledged_by_name or _name(user)
    dispatch.acknowledged_at = utcnow()
    dispatch.delivered_at = dispatch.delivered_at or utcnow()
    dispatch.pod_url = data.pod_url or dispatch.pod_url
    dispatch.status = DispatchStatus.ACKNOWLEDGED.value
    if data.remarks:
        dispatch.remarks = f"{dispatch.remarks or ''}\nReceiver: {data.remarks}".strip()

    for package in dispatch.packages:
        package.status = PackageStatus.DELIVERED.value

    # Acknowledging the consignment acknowledges what it was carrying. Without this
    # the two documents drift: the dispatch reads ACKNOWLEDGED while the issue it
    # came from still reads DISPATCHED, and the indent never closes.
    #
    # Closing the INDENT is the separate question, and only the last leg may answer it.
    # A consignment addressed to an MDP on its way to a LIP ends this issue's journey —
    # it reached the point it was sent to — but the requester still has nothing, so the
    # indent stays open until the MDP forwards it on and the LIP signs for it there.
    # Every issue it carried, on a grouped consignment.
    for issue_id in await _dispatch_issue_ids(db, dispatch):
        issue = await db.get(m.MaterialIssue, issue_id)
        if issue is not None and issue.status in (
            IssueStatus.ISSUED.value, IssueStatus.DISPATCHED.value,
        ):
            issue.status = IssueStatus.ACKNOWLEDGED.value
            issue.acknowledged_by_name = dispatch.acknowledged_by_name
            issue.acknowledged_at = dispatch.acknowledged_at
            if await _is_final_delivery_leg(db, issue, dispatch):
                await _close_indents_on_issue(db, issue, user)

    # Whichever door the signature came through, a consignment on a multi-drop trip
    # rolls its stop — and, at the last one, the trip's shipment — up with it.
    from app.modules.warehouse import trips
    await trips.sync_for_dispatches(db, [dispatch.id], user)
    return short


async def cancel_dispatch(db: AsyncSession, dispatch_id: int, reason: str | None,
                          user) -> m.Dispatch:
    dispatch = await get_dispatch(db, dispatch_id)
    _guard(dispatch.status,
           {DispatchStatus.DRAFT.value, DispatchStatus.PENDING_APPROVAL.value,
            DispatchStatus.APPROVED.value, DispatchStatus.PACKED.value},
           "cancel", "dispatch")
    # A consignment planned onto a trip is on that truck's manifest and its shipment's
    # lines. Cancelling it underneath the trip would leave the carrier pricing a
    # carton that is no longer coming; the trip is cancelled (and re-planned) first.
    from app.modules.logistics.enums import ACTIVE_TRIP_STATUSES
    from app.modules.logistics.models import ConsolidatedTrip, ConsolidatedTripConsignment
    on_trip = await db.scalar(
        select(ConsolidatedTrip.trip_no).join(
            ConsolidatedTripConsignment,
            ConsolidatedTripConsignment.trip_id == ConsolidatedTrip.id)
        .where(ConsolidatedTripConsignment.dispatch_id == dispatch.id,
               ConsolidatedTrip.status.in_(ACTIVE_TRIP_STATUSES)).limit(1))
    if on_trip:
        raise ValidationError(
            f"{dispatch.dispatch_no} is planned on trip {on_trip}. Cancel that trip in "
            "Smart Load Planner first — its other consignments go back to the queue.")

    before = {"status": dispatch.status}
    dispatch.status = DispatchStatus.CANCELLED.value
    dispatch.remarks = f"{dispatch.remarks or ''}\nCancelled: {reason or '—'}".strip()

    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE, actor=user,
                      before=before, after={"status": dispatch.status, "reason": reason})
    await db.commit()
    return await get_dispatch(db, dispatch_id)


# ---------------------------------------------------------------------------
# Purchase returns
# ---------------------------------------------------------------------------

def _return_totals(doc: m.PurchaseReturn) -> None:
    doc.total_items = len(doc.items)
    doc.total_qty = sum((_d(l.quantity) for l in doc.items), ZERO)
    doc.total_value = sum((_d(l.amount) for l in doc.items), ZERO)


async def _purchase_return_source_vendor(db: AsyncSession, *, grn_id: int | None,
                                           po_id: int | None) -> tuple[int | None, str | None, str | None]:
    """Vendor the selected Purchase Invoice/PO belongs to — the single truth.

    Returns (vendor_id, vendor_name, source_no). Used to lock the draft's vendor
    to its source: the form never offers a vendor picker, and the service refuses
    a payload naming any other vendor.
    """
    if grn_id:
        receipt = await db.get(m.Receipt, grn_id)
        if receipt is None:
            raise NotFoundError(f"Purchase Invoice/GRN {grn_id} not found")
        return receipt.vendor_id, receipt.vendor_name, receipt.grn_no
    if po_id:
        try:
            from app.modules.procurement.models import PurchaseOrder as _PO
        except Exception:  # pragma: no cover - procurement always importable
            return None, None, None
        po = await db.get(_PO, po_id)
        if po is None:
            raise NotFoundError(f"Purchase Order {po_id} not found")
        return po.vendor_id, po.vendor_name, po.po_no
    return None, None, None


def _assert_vendor_locked(payload_vendor_id: int | None, source_vendor_id: int | None,
                          source_no: str | None) -> None:
    """The draft's vendor must come from its Invoice/PO — never typed, never swapped."""
    if source_vendor_id and payload_vendor_id and int(payload_vendor_id) != int(source_vendor_id):
        raise ValidationError(
            f"Vendor must come from the selected Purchase Invoice/PO"
            f"{f' {source_no}' if source_no else ''} and cannot be changed.")


def _grn_line_returnable(line: m.ReceiptItem) -> Decimal:
    """How much of one GRN line may go back to the vendor, before earlier returns.

    A QC rejection is the obvious case and used to be the only one this function's
    callers agreed on: `_apply_return_lines` capped every line at `rejected_qty`, while
    the served availability (`purchase_return_source_detail`, `_decorate_purchase_return`
    and `send_to_vendor`) all read `rejected_qty` where there was one and `received_qty`
    otherwise. So a fully-ACCEPTED line was offered on the screen with its received
    quantity available and then refused on save with "cannot exceed the available
    returnable quantity of 0" — the whole Warehouse → Vendor flow was unusable on any
    receipt QC had passed, which is most of them. One definition, read by all four.
    """
    rejected = _d(line.rejected_qty)
    return rejected if rejected > ZERO else _d(line.received_qty)


async def _apply_return_lines(db: AsyncSession, doc: m.PurchaseReturn,
                              lines: list[s.ReturnItemWrite]) -> None:
    """Replaces the lines, capped at what the source document still allows back.

    Returning more than was received is the mistake this document exists to prevent,
    so the cap is enforced here rather than trusted from the screen.
    """
    caps: dict[int, Decimal] = {}
    item_caps: dict[int, Decimal] = {}
    po_caps: dict[int, Decimal] = {}
    po_item_caps: dict[int, Decimal] = {}
    if doc.grn_id:
        receipt = await _load(db, m.Receipt, doc.grn_id, "Receipt", m.Receipt.items)
        caps = {l.id: _grn_line_returnable(l) for l in receipt.items}
        for line in receipt.items:
            item_caps[line.item_id] = (
                item_caps.get(line.item_id, ZERO) + _grn_line_returnable(line))
        already_rows = (await db.execute(
            select(
                m.PurchaseReturnItem.grn_item_id,
                func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0),
            )
            .join(
                m.PurchaseReturn,
                m.PurchaseReturn.id == m.PurchaseReturnItem.return_id,
            )
            .where(
                m.PurchaseReturn.grn_id == doc.grn_id,
                m.PurchaseReturn.id != doc.id,
                m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                m.PurchaseReturnItem.grn_item_id.isnot(None),
            )
            .group_by(m.PurchaseReturnItem.grn_item_id)
        )).all()
        for grn_item_id, returned in already_rows:
            caps[grn_item_id] = max(
                caps.get(grn_item_id, ZERO) - _d(returned), ZERO
            )
        # Already-returned quantities posted without a grn_item_id link still count:
        # without this a line saved without the link silently re-opens the cap.
        already_unlinked = (await db.execute(
            select(
                m.PurchaseReturnItem.item_id,
                func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0),
            )
            .join(
                m.PurchaseReturn,
                m.PurchaseReturn.id == m.PurchaseReturnItem.return_id,
            )
            .where(
                m.PurchaseReturn.grn_id == doc.grn_id,
                m.PurchaseReturn.id != doc.id,
                m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                m.PurchaseReturnItem.grn_item_id.is_(None),
            )
            .group_by(m.PurchaseReturnItem.item_id)
        )).all()
        for item_id, returned in already_unlinked:
            item_caps[item_id] = max(item_caps.get(item_id, ZERO) - _d(returned), ZERO)
        for grn_item_id, returned in already_rows:
            receipt_line = next((l for l in receipt.items if l.id == grn_item_id), None)
            if receipt_line is not None:
                item_caps[receipt_line.item_id] = max(
                    item_caps.get(receipt_line.item_id, ZERO) - _d(returned), ZERO)
    elif doc.po_id:
        try:
            from app.modules.procurement.models import POItem as _POItem
            po_items = (await db.execute(
                select(_POItem).where(_POItem.po_id == doc.po_id))).scalars().all()
            po_caps = {l.id: _d(l.quantity) for l in po_items}
            for line in po_items:
                po_item_caps[line.item_id] = po_item_caps.get(line.item_id, ZERO) + _d(line.quantity)
            already_po = (await db.execute(
                select(
                    m.PurchaseReturnItem.po_item_id,
                    func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0),
                )
                .join(m.PurchaseReturn,
                      m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
                .where(
                    m.PurchaseReturn.po_id == doc.po_id,
                    m.PurchaseReturn.id != doc.id,
                    m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                    m.PurchaseReturnItem.po_item_id.isnot(None),
                )
                .group_by(m.PurchaseReturnItem.po_item_id)
            )).all()
            for po_item_id, returned in already_po:
                po_caps[po_item_id] = max(po_caps.get(po_item_id, ZERO) - _d(returned), ZERO)
            already_po_unlinked = (await db.execute(
                select(
                    m.PurchaseReturnItem.item_id,
                    func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0),
                )
                .join(m.PurchaseReturn,
                      m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
                .where(
                    m.PurchaseReturn.po_id == doc.po_id,
                    m.PurchaseReturn.id != doc.id,
                    m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                    m.PurchaseReturnItem.po_item_id.is_(None),
                )
                .group_by(m.PurchaseReturnItem.item_id)
            )).all()
            for item_id, returned in already_po_unlinked:
                po_item_caps[item_id] = max(
                    po_item_caps.get(item_id, ZERO) - _d(returned), ZERO)
            for po_item_id, returned in already_po:
                src = next((l for l in po_items if l.id == po_item_id), None)
                if src is not None:
                    po_item_caps[src.item_id] = max(
                        po_item_caps.get(src.item_id, ZERO) - _d(returned), ZERO)
        except Exception:
            logger.debug("PO returnable caps skipped — procurement tables not reachable",
                         exc_info=True)

    doc.items.clear()
    await db.flush()

    for index, line in enumerate(lines, start=1):
        if not line.item_id:
            # Optional on the schema since manual lines exist; still required here,
            # because the cap this function enforces is computed against it.
            raise ValidationError(
                f"Line {index}: pick the item from the source document.")
        item = await _item_snapshot(db, line.item_id)
        qty = _d(line.quantity)
        if qty <= ZERO:
            raise ValidationError(f"Line {index}: return quantity must be greater than 0")

        cap = caps.get(line.grn_item_id) if line.grn_item_id else None
        if cap is None and doc.grn_id and not line.grn_item_id:
            cap = item_caps.get(line.item_id)
        if cap is not None and qty > cap:
            raise ValidationError(
                f"Return quantity cannot exceed the available returnable quantity of {cap}.")
        if doc.grn_id is None and doc.po_id:
            po_cap = po_caps.get(line.po_item_id) if line.po_item_id else None
            if po_cap is None and not line.po_item_id:
                po_cap = po_item_caps.get(line.item_id)
            if po_cap is not None and qty > po_cap:
                raise ValidationError(
                    f"Return quantity cannot exceed the available returnable quantity of {po_cap}.")

        batch = await db.get(m.Batch, line.batch_id) if line.batch_id else None
        rate = _d(line.rate)
        doc.items.append(m.PurchaseReturnItem(
            line_no=index, po_item_id=line.po_item_id, grn_item_id=line.grn_item_id,
            item_id=item.id, item_code=item.code, item_name=item.name, uom_code=item.uom_code,
            batch_id=line.batch_id, batch_no=batch.batch_no if batch else None,
            quantity=qty, rate=rate or None, amount=(qty * rate) if rate else None,
            reason=line.reason,
            # The brand / variant / model the receipt line booked in (2026-10-23).
            **(combinations.carry(await db.get(m.ReceiptItem, line.grn_item_id))
               if line.grn_item_id else dict(combinations.NONE)),
        ))
    _return_totals(doc)


async def _apply_manual_return_lines(db: AsyncSession, doc: m.PurchaseReturn,
                                     lines: list[s.ReturnItemWrite]) -> None:
    """Replaces the lines of a MANUAL return with what was typed.

    ADDED 2026-09-10. Deliberately a separate function from `_apply_return_lines` rather
    than a branch inside it: that one exists to cap every line at what the source
    document still allows back, and a manual return HAS no source document, so every
    cap it computes would be computed against a purchase this return never claimed to
    come from. Splitting them keeps the sourced path — the default, and the one every
    existing return uses — exactly as it was.

    What is NOT relaxed: a quantity still has to be a positive number, a line still has
    to name something, and the totals are still computed here rather than trusted from
    the screen. `original_qty` / `previously_returned` / `returnable_qty` are stored as
    typed because nothing can derive them, but the return quantity is checked against
    the typed availability so the document does not contradict itself on its own face.
    """
    doc.items.clear()
    await db.flush()

    for index, line in enumerate(lines, start=1):
        qty = _d(line.quantity)
        if qty <= ZERO:
            raise ValidationError(f"Line {index}: return quantity must be greater than 0")

        # An item from the masters where one was picked, the one the typed CODE names
        # where not, and the typed name where neither. The middle case is the common
        # one: the screen sends `item_id: null` for every manual line, so a line whose
        # code is a real master item used to be stored as if the item did not exist —
        # and the consignment raised at `arrange_return_transport` then died on
        # `out_dispatch_items.item_id`, which is NOT NULL.
        item = (await _item_snapshot(db, line.item_id) if line.item_id
                else await _item_by_code(db, line.item_code))
        name = (line.item_name or "").strip() or (item.name if item else "")
        if not name:
            raise ValidationError(f"Line {index}: enter an item name")

        available = line.returnable_qty
        if available is not None and _d(available) > ZERO and qty > _d(available):
            raise ValidationError(
                f"Line {index} ({name}): return quantity {qty} is more than the "
                f"available quantity {_d(available)} entered beside it.")

        rate = _d(line.rate)
        doc.items.append(m.PurchaseReturnItem(
            line_no=index,
            # No source document, so no source line to point at.
            po_item_id=None, grn_item_id=None, batch_id=None, batch_no=None,
            item_id=item.id if item else None,
            item_code=(item.code if item else line.item_code) or None,
            item_name=name,
            uom_code=(item.uom_code if item else line.uom_code) or None,
            quantity=qty,
            rate=rate or None,
            # Return amount = return qty x unit price. Computed here and not accepted
            # from the screen, the same way the sourced path computes it.
            amount=(qty * rate) if rate else None,
            reason=line.reason,
            is_manual=True,
            original_qty=_d(line.original_qty) if line.original_qty is not None else None,
            previously_returned=(_d(line.previously_returned)
                                 if line.previously_returned is not None else None),
            returnable_qty=_d(available) if available is not None else None,
        ))
    _return_totals(doc)


async def list_returns(db: AsyncSession, params: PageParams, *, status: str | None = None,
                       warehouse_id: int | None = None, search: str | None = None, user=None) -> dict:
    stmt = select(m.PurchaseReturn)
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.PurchaseReturn.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.PurchaseReturn.created_by_id,
        ))
    if status:
        stmt = stmt.where(m.PurchaseReturn.status == status)
    if warehouse_id:
        stmt = stmt.where(m.PurchaseReturn.warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.PurchaseReturn.return_no.ilike(like), m.PurchaseReturn.grn_no.ilike(like),
            m.PurchaseReturn.po_no.ilike(like),
            m.PurchaseReturn.vendor_name.ilike(like),
            m.PurchaseReturn.credit_note_no.ilike(like)))
    page = await paginate(db, stmt.order_by(m.PurchaseReturn.id.desc()), params)
    # The GRN, PO and vendor behind the rows that store none — read for the page in a
    # fixed number of queries, served on the `traced_*` fields and never written. The
    # register showed nothing but the return number on those rows otherwise.
    traced = await trace_purchase_sources(db, page["items"])
    for row in page["items"]:
        # Same field the detail serves, filled the same way — a register row carrying
        # `source_category` and a null label would read as "no category" on one screen
        # and "From LIP / MDB" on the other.
        row.source_category_label = PURCHASE_RETURN_SOURCE_LABELS.get(
            row.source_category or "")
        # And the supplier's answer, worded the same way the document words it — a
        # register that still read "SENT_TO_VENDOR" against a return the supplier had
        # accepted was the whole complaint.
        _apply_vendor_answer(row)
        found = traced.get(row.id) or {}
        row.chain_traced = bool(found)
        row.traced_grn_id = found.get("grn_id")
        row.traced_grn_no = found.get("grn_no")
        row.traced_po_id = found.get("po_id")
        row.traced_po_no = found.get("po_no")
        row.traced_vendor_id = found.get("vendor_id")
        row.traced_vendor_name = found.get("vendor_name")
    return page


async def get_return(db: AsyncSession, return_id: int, user=None) -> m.PurchaseReturn:
    doc = await _load(db, m.PurchaseReturn, return_id, "Return", m.PurchaseReturn.items)
    # Enrich with vendor auto-fetch + line returnable quantities
    await _decorate_purchase_return(db, doc)
    # The supplier's loading photograph and invoice, on our side of the document too —
    # see `ReturnDetail.replacement_documents`. Empty on every return whose replacement
    # has not been dispatched, and on every return that never had one.
    doc.replacement_documents = await _replacement_documents(db, doc.id)
    return await _decorate_can_approve(
        db, doc, WarehouseDocType.PURCHASE_RETURN.value, user)


async def return_document_file(db: AsyncSession, return_id: int, attachment_id: int,
                               user=None):
    """One of the replacement's files, for OUR store to open.

    SCOPED THROUGH THE RETURN, not through the attachment id. `get_return` is what
    decides whether this login may read the document at all, and it runs first — so an
    attachment id belonging to a return this user cannot see is refused before the
    filesystem is touched. `require_attachment` then proves the file hangs on THIS
    return, which is what stops an id from another document being passed in.
    """
    await get_return(db, return_id, user)
    await attachments.require_attachment(
        db, attachment_id, entity_type=RETURN_ATTACHMENT_ENTITY, entity_id=return_id)
    return await attachments.attachment_file(db, attachment_id)


def _manual_vendor_fields(data: s.ReturnWrite) -> dict:
    """The typed vendor, trimmed, ready to write onto a manual return."""
    def clean(value: str | None) -> str | None:
        return (value or "").strip() or None
    return {
        "manual_vendor_code": clean(data.vendor_code),
        "manual_vendor_contact_person": clean(data.vendor_contact_person),
        "manual_vendor_phone": clean(data.vendor_phone),
        "manual_vendor_email": clean(data.vendor_email),
        "manual_vendor_address": clean(data.vendor_address),
        "manual_vendor_city": clean(data.vendor_city),
        "manual_vendor_state": clean(data.vendor_state),
        "manual_vendor_pincode": clean(data.vendor_pincode),
        "manual_vendor_gstin": clean(data.vendor_gstin),
    }


#: The punctuation a company name is written with on one screen and without on another.
#: "Amara Raja Batteries Ltd." and "Amara Raja Batteries Ltd" are one company; so are
#: "ABC Pvt Ltd" and "ABC  Pvt  Ltd". Folded away on BOTH sides of every comparison
#: below, so a typed name only has to name the right company, not copy the master's
#: punctuation character for character. NOT a fuzzy match: every letter and digit still
#: has to be there, in order, which is what keeps two genuinely different suppliers apart.
_COMPANY_NOISE = (" ", ".", ",", "-", "&", "'")


def _fold_company(value: str | None) -> str:
    """A company name reduced to what actually identifies it, or "" if there is none."""
    folded = (value or "").strip().lower()
    for ch in _COMPANY_NOISE:
        folded = folded.replace(ch, "")
    return folded


def _fold_company_sql(column):
    """`_fold_company` as SQL, so the fold happens on the database's side of the match.

    The two MUST agree character for character — a Python fold compared against a raw
    column silently matches nothing — so they are written next to each other and read
    from the same tuple.
    """
    expr = func.lower(func.trim(column))
    for ch in _COMPANY_NOISE:
        expr = func.replace(expr, ch, "")
    return expr


async def _match_manual_vendor(db: AsyncSession, name: str | None,
                               code: str | None = None,
                               gstin: str | None = None) -> Vendor | None:
    """The `mst_vendors` row the TYPED vendor names, where one and only one exists.

    A manual return may name a company that is not in the masters at all — that is the
    whole point of one — but where it names a company that IS, the document has to be
    BOUND to it. `vendor_id` is the only handle the supplier portal has:
    `vendor_list_returns` scopes every read to `PurchaseReturn.vendor_id`, so a manual
    return that stored nothing but a typed `vendor_name` was invisible to the very
    supplier it was addressed to, before AND after it was sent to them.

    Matched in order of how strongly the value identifies a company — GSTIN, then the
    vendor code (unique in the master), then the name — and only ever bound on an
    UNAMBIGUOUS hit: two suppliers trading under the same name must leave the return
    unbound rather than have it silently addressed to whichever row came back first.
    Inactive vendors are excluded; a return cannot be sent to a supplier we have closed.

    Returns None whenever nothing matches, which is the pre-existing behaviour — every
    manual return naming a company outside the master keeps working exactly as before.
    """
    for column, value in ((Vendor.gstin, gstin),
                          (Vendor.code, code),
                          (Vendor.name, name)):
        folded = _fold_company(value)
        if not folded:
            continue
        rows = (await db.execute(
            select(Vendor).where(
                _fold_company_sql(column) == folded,
                Vendor.is_active.is_(True),
            ).limit(2)
        )).scalars().all()
        if len(rows) == 1:
            return rows[0]
    return None


async def _create_manual_return(db: AsyncSession, data: s.ReturnWrite,
                                user) -> m.PurchaseReturn:
    """A purchase return typed from scratch, for goods with no paperwork in the system.

    ADDED 2026-09-10 at the business owner's request. The sourced path — everything in
    `create_return` below — is untouched and remains the default; this is reached only
    when the screen sets `is_manual`.

    The one rule that cannot be relaxed is that the document has to say who it is going
    to: a return with no vendor is a pile of goods with nowhere to send them. A NAME is
    enough here, because the whole reason for a manual return is that the vendor may
    not be in `mst_vendors` either — but where a real `vendor_id` IS supplied it is
    validated against the master like any other.
    """
    if not data.items:
        raise ValidationError("A return with no lines sends nothing back")
    vendor_name = (data.vendor_name or "").strip()
    if not vendor_name and not data.vendor_id:
        raise ValidationError(
            "Enter the vendor's name — a manual return still has to say who the goods "
            "are going back to.")
    vendor = await db.get(Vendor, data.vendor_id) if data.vendor_id else None
    if data.vendor_id and vendor is None:
        raise NotFoundError(f"Vendor {data.vendor_id} not found")
    # The screen posts no `vendor_id` in manual mode — it types a company name. Where
    # that name (or code, or GSTIN) is one of our own suppliers, BIND it, so the return
    # reaches that supplier's portal. See `_match_manual_vendor`. The typed values are
    # still what the document shows; only the link is added.
    if vendor is None:
        vendor = await _match_manual_vendor(
            db, vendor_name, data.vendor_code, data.vendor_gstin)
    wh = await db.get(Warehouse, data.warehouse_id) if data.warehouse_id else None

    doc = m.PurchaseReturn(
        items=[],   # see create_issue: keeps _apply_*_lines()'s clear() off a lazy load
        return_no=await next_number(db, WarehouseDocType.PURCHASE_RETURN.value),
        return_date=data.return_date,
        # No purchase transaction behind it — that is what makes it manual. The typed
        # number, if any, is kept as a reference and is never resolved to a document.
        po_id=None, po_no=None, grn_id=None, grn_no=None,
        source_ref_no=(data.source_ref_no or "").strip() or None,
        vendor_id=vendor.id if vendor else None,
        vendor_name=vendor_name or (vendor.name if vendor else None),
        warehouse_id=data.warehouse_id,
        warehouse_name=wh.name if wh else None,
        reason=data.reason,
        remarks=(data.remarks or "").strip() or None,
        status=ReturnStatus.DRAFT.value,
        is_manual=True,
        created_by_id=getattr(user, "id", None), created_by_name=_name(user),
        **_manual_vendor_fields(data),
    )
    db.add(doc)
    await db.flush()

    await _apply_manual_return_lines(db, doc, data.items)
    await db.flush()

    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.CREATE, actor=user,
                      after={"status": doc.status, "total_qty": str(doc.total_qty),
                             "is_manual": True,
                             "vendor_name": doc.vendor_name,
                             "source_ref_no": doc.source_ref_no})
    await db.commit()
    return await get_return(db, doc.id)


async def create_return(db: AsyncSession, data: s.ReturnWrite, user) -> m.PurchaseReturn:
    if data.is_manual:
        return await _create_manual_return(db, data, user)
    if not data.items:
        raise ValidationError("A return with no lines sends nothing back")
    if not data.grn_id and not data.po_id:
        raise ValidationError("Select a Purchase Invoice/GRN or Purchase Order first")

    receipt = await db.get(m.Receipt, data.grn_id) if data.grn_id else None
    if data.grn_id and receipt is None:
        raise NotFoundError(f"Purchase Invoice/GRN {data.grn_id} not found")
    po = None
    if data.po_id or (receipt is not None and receipt.po_id):
        try:
            from app.modules.procurement.models import PurchaseOrder as _PO
            po = await db.get(_PO, data.po_id or (receipt.po_id if receipt else None))
        except Exception:
            po = None
        if data.po_id and po is None:
            raise NotFoundError(f"Purchase Order {data.po_id} not found")
    # Vendor must come from the selected Invoice/PO — never typed, never swapped.
    source_vendor_id = (receipt.vendor_id if receipt else None) or (po.vendor_id if po else None)
    source_vendor_name = (receipt.vendor_name if receipt else None) or (po.vendor_name if po else None)
    source_no = (receipt.grn_no if receipt else None) or (po.po_no if po else None)
    _assert_vendor_locked(data.vendor_id, source_vendor_id, source_no)
    if source_vendor_id is None and not data.vendor_id:
        raise ValidationError("Vendor is required — select a purchase transaction to auto-fetch vendor")
    vendor = await db.get(Vendor, data.vendor_id or source_vendor_id) if (data.vendor_id or source_vendor_id) else None
    if (data.vendor_id or source_vendor_id) and vendor is None:
        raise NotFoundError(f"Vendor {data.vendor_id or source_vendor_id} not found")
    wh = await db.get(Warehouse, data.warehouse_id) if data.warehouse_id else None

    doc = m.PurchaseReturn(
        items=[],   # see create_issue: keeps _apply_*_lines()'s clear() off a lazy load
        return_no=await next_number(db, WarehouseDocType.PURCHASE_RETURN.value),
        return_date=data.return_date,
        po_id=data.po_id or (receipt.po_id if receipt else None) or (po.id if po else None),
        po_no=(po.po_no if po else None) or (receipt.po_no if receipt else None),
        grn_id=data.grn_id, grn_no=receipt.grn_no if receipt else None,
        vendor_id=vendor.id if vendor else None,
        vendor_name=vendor.name if vendor else source_vendor_name,
        warehouse_id=data.warehouse_id or (receipt.warehouse_id if receipt else None),
        warehouse_name=wh.name if wh else (receipt.warehouse_name if receipt else None),
        reason=data.reason,
        remarks=(data.remarks or "").strip() or None,
        status=ReturnStatus.DRAFT.value,
        created_by_id=getattr(user, "id", None), created_by_name=_name(user),
    )
    db.add(doc)
    await db.flush()

    await _apply_return_lines(db, doc, data.items)
    await db.flush()

    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.CREATE, actor=user,
                      after={"status": doc.status, "total_qty": str(doc.total_qty)})
    await db.commit()
    return await get_return(db, doc.id)


async def update_return(db: AsyncSession, return_id: int, data: s.ReturnWrite,
                        user) -> m.PurchaseReturn:
    doc = await get_return(db, return_id)
    _guard(doc.status, {ReturnStatus.DRAFT.value}, "edit", "return")

    before = {"total_qty": str(doc.total_qty)}
    doc.return_date = data.return_date
    doc.reason = data.reason
    doc.remarks = (data.remarks or "").strip() or None

    # A MANUAL draft edits its own typed vendor and its own typed lines. It never falls
    # through to the source-binding below: there is no GRN or PO to re-lock the vendor
    # against, and the vendor lock is the whole of what that code is protecting.
    if doc.is_manual:
        vendor_name = (data.vendor_name or "").strip()
        if not vendor_name and not (data.vendor_id or doc.vendor_id):
            raise ValidationError(
                "Enter the vendor's name — a manual return still has to say who the "
                "goods are going back to.")
        if data.vendor_id:
            vendor = await db.get(Vendor, data.vendor_id)
            if vendor is None:
                raise NotFoundError(f"Vendor {data.vendor_id} not found")
            doc.vendor_id = vendor.id
        else:
            # RE-DERIVED on every edit rather than bound once at birth, and it may clear
            # the link as well as set it. The name on a manual draft is editable, so a
            # draft typed against one supplier and retyped against another has to follow:
            # leaving the old `vendor_id` in place would go on showing the return on the
            # first supplier's portal after the document stopped naming them.
            matched = await _match_manual_vendor(
                db, vendor_name or doc.vendor_name,
                data.vendor_code, data.vendor_gstin)
            doc.vendor_id = matched.id if matched else None
        if vendor_name:
            doc.vendor_name = vendor_name
        doc.source_ref_no = (data.source_ref_no or "").strip() or None
        for field, value in _manual_vendor_fields(data).items():
            setattr(doc, field, value)
        await _apply_manual_return_lines(db, doc, data.items)
        await db.flush()
        await write_audit(db, entity="pro_returns", entity_id=doc.id,
                          entity_no=doc.return_no, action=AuditAction.UPDATE,
                          actor=user, before=before,
                          after={"total_qty": str(doc.total_qty), "is_manual": True,
                                 "vendor_name": doc.vendor_name})
        await db.commit()
        return await get_return(db, return_id)

    if data.grn_id and data.grn_id != doc.grn_id:
        receipt = await db.get(m.Receipt, data.grn_id)
        if receipt is None:
            raise NotFoundError(f"Purchase Invoice/GRN {data.grn_id} not found")
        # Switching source re-locks the vendor to the new source.
        if receipt.vendor_id and doc.vendor_id and int(receipt.vendor_id) != int(doc.vendor_id):
            raise ValidationError(
                "Vendor must come from the selected Purchase Invoice/PO and cannot be changed. "
                f"This GRN belongs to a different vendor.")
        doc.grn_id = data.grn_id
        doc.grn_no = receipt.grn_no if receipt else None
        if receipt.po_id and not doc.po_id:
            doc.po_id = receipt.po_id
            doc.po_no = receipt.po_no
        if not doc.vendor_id:
            # Through the PO where the GRN names no vendor of its own — a gate entry
            # typed in at the barrier routinely doesn't. See `_receipt_vendor`.
            doc.vendor_id, doc.vendor_name = await _receipt_vendor(db, receipt)
    if data.po_id and data.po_id != doc.po_id and not data.grn_id:
        try:
            from app.modules.procurement.models import PurchaseOrder as _POU
            po = await db.get(_POU, data.po_id)
            if po is None:
                raise NotFoundError(f"Purchase Order {data.po_id} not found")
            if po.vendor_id and doc.vendor_id and int(po.vendor_id) != int(doc.vendor_id):
                raise ValidationError(
                    "Vendor must come from the selected Purchase Invoice/PO and cannot be changed.")
            doc.po_id = po.id
            doc.po_no = po.po_no
            if po.vendor_id and not doc.vendor_id:
                doc.vendor_id = po.vendor_id
                doc.vendor_name = po.vendor_name
        except (NotFoundError, ValidationError):
            raise
        except Exception:
            pass
    # A payload naming a different vendor than the locked one is refused — the
    # vendor section is read-only once auto-fetched.
    if data.vendor_id and doc.vendor_id and int(data.vendor_id) != int(doc.vendor_id):
        raise ValidationError("Vendor must come from the selected Purchase Invoice/PO and cannot be changed.")

    await _apply_return_lines(db, doc, data.items)
    await db.flush()

    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.UPDATE, actor=user, before=before,
                      after={"total_qty": str(doc.total_qty)})
    await db.commit()
    return await get_return(db, return_id)


async def submit_return(db: AsyncSession, return_id: int, user) -> m.PurchaseReturn:
    doc = await get_return(db, return_id)
    _guard(doc.status, {ReturnStatus.DRAFT.value}, "submit", "return")

    context = {"warehouse_id": doc.warehouse_id, "total_value": float(_d(doc.total_value)),
               "vendor_id": doc.vendor_id}
    context.update({
        "doc_no": doc.return_no,
        "doc_summary": f"Purchase return {doc.return_no}",
        "requester_position_id": getattr(user, "active_position_id", None),
    })
    instance = await engine.start(
        db, WarehouseDocType.PURCHASE_RETURN.value, doc.id, context, user
    )
    doc.status = (
        ReturnStatus.APPROVED.value
        if instance.status == InstanceStatus.APPROVED.value
        else ReturnStatus.PENDING_APPROVAL.value
    )

    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": ReturnStatus.DRAFT.value},
                      after={"status": doc.status})
    await db.commit()
    return await get_return(db, return_id)


async def act_on_return(
    db: AsyncSession, return_id: int, action: str, comments: str, user,
) -> m.PurchaseReturn:
    doc = await get_return(db, return_id)
    _guard(
        doc.status, {ReturnStatus.PENDING_APPROVAL.value},
        action.lower(), "return",
    )
    before = doc.status
    instance = await engine.act(
        db,
        WarehouseDocType.PURCHASE_RETURN.value,
        doc.id,
        action,
        user,
        comments,
        context={
            "doc_no": doc.return_no,
            "doc_summary": f"Purchase return {doc.return_no}",
            "warehouse_id": doc.warehouse_id,
            "vendor_id": doc.vendor_id,
            "total_value": float(_d(doc.total_value)),
        },
    )
    if instance.status == InstanceStatus.APPROVED.value:
        doc.status = ReturnStatus.APPROVED.value
    elif instance.status == InstanceStatus.REJECTED.value:
        doc.status = ReturnStatus.REJECTED.value

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": doc.status, "comments": comments},
    )
    await db.commit()
    return await get_return(db, return_id)


async def complete_return(db: AsyncSession, return_id: int, credit_note_no: str | None,
                          user) -> m.PurchaseReturn:
    """Closes the physical vendor return.

    QC-rejected quantities never entered available inventory, so sending those back
    must not subtract them a second time. A manual/posted-stock return line still
    moves OUT through move_stock().
    """
    doc = await get_return(db, return_id)
    # RECEIVED_AT_WAREHOUSE joined the set on 2026-09-11: a return whose material has
    # come back from the vendor and been signed in at the gate is exactly a return that
    # is ready to be closed with its credit note. The three that were already here are
    # untouched, so every return in flight under the older flow closes as it always did.
    _guard(doc.status, {ReturnStatus.APPROVED.value, ReturnStatus.DISPATCHED.value,
                        ReturnStatus.SENT_TO_VENDOR.value,
                        ReturnStatus.RECEIVED_AT_WAREHOUSE.value},
           "complete", "return")

    # A RETURN WITH A REPLACEMENT COMING CLOSES ITSELF, and must not be closed by hand
    # (2026-09-14). Two things go wrong if it is.
    #
    # It closes EARLY: this press would finish the document while the replacement is
    # still in a draft GRN, or failing QC, or standing on the dock — the three rungs the
    # intake exists to work through (`_close_return_on_intake_complete`).
    #
    # And it moves stock that has already moved. The loop below posts every line OUT of
    # the warehouse, which is right for a return whose goods are still on our floor and
    # wrong for this one: the faulty material left the books when the consignment was
    # gated out, so a manual close here would take the quantity out a second time and
    # leave the balance short by the whole return.
    #
    # Refused rather than quietly turned into a no-op, because the presser is asking for
    # something that will happen on its own and needs to be told where to look for it.
    if doc.vendor_followup_receipt_id:
        intake = await _replacement_intake(db, doc)
        if not intake["intake_complete"]:
            raise ValidationError(
                f"{doc.return_no} closes itself once the replacement is put away. Book "
                f"it in on goods receipt {intake['grn_no'] or doc.vendor_followup_receipt_no}"
                f" and take it through QC and putaway"
                + (" — the goods receipt has not been submitted yet."
                   if not intake["grn_booked"]
                   else f" — {intake['putaway_open']} putaway task(s) are still open."
                   if intake["putaway_open"]
                   else " — QC has not passed it yet." if not intake["qc_passed"]
                   else "."))
        # The intake IS finished and the return is somehow still open — the hook is a
        # never-raising one and a failed read leaves exactly this. Close it through the
        # SAME closer rather than falling into the stock loop below, so the recovery
        # path and the automatic one write the same thing.
        receipt = await db.get(m.Receipt, doc.vendor_followup_receipt_id)
        doc.credit_note_no = credit_note_no or doc.credit_note_no
        await _close_return_on_intake_complete(db, receipt, user)
        await db.commit()
        return await get_return(db, return_id)

    rejected_line_ids: set[int] = set()
    if doc.grn_id:
        receipt = await _load(db, m.Receipt, doc.grn_id, "Receipt", m.Receipt.items)
        rejected_line_ids = {
            line.id for line in receipt.items if _d(line.rejected_qty) > ZERO
        }

    for line in doc.items:
        qty = _d(line.quantity)
        if qty <= ZERO:
            continue
        if line.grn_item_id in rejected_line_ids:
            continue
        await move_stock_out(
            db, item_id=line.item_id, qty=qty,
            ref_type=InventoryRefType.PURCHASE_RETURN.value, ref_id=doc.id,
            ref_no=doc.return_no, user=user,
            warehouse_id=doc.warehouse_id,
            batch_id=line.batch_id,
            brand_id=line.brand_id or None, variant_id=line.variant_id,
            model_id=line.model_id,
        )

    doc.credit_note_no = credit_note_no or doc.credit_note_no
    doc.status = ReturnStatus.COMPLETED.value

    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": doc.status},
                      after={"status": ReturnStatus.COMPLETED.value,
                             "credit_note_no": doc.credit_note_no,
                             "total_qty": str(doc.total_qty)})
    await db.commit()
    return await get_return(db, return_id)


async def cancel_return(db: AsyncSession, return_id: int, reason: str | None,
                        user) -> m.PurchaseReturn:
    doc = await get_return(db, return_id)
    _guard(doc.status,
           {ReturnStatus.DRAFT.value, ReturnStatus.PENDING_APPROVAL.value,
            ReturnStatus.APPROVED.value},
           "cancel", "return")
    before = {"status": doc.status}
    doc.status = ReturnStatus.CANCELLED.value
    doc.reason = f"{doc.reason or ''}\nCancelled: {reason or '—'}".strip()

    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.UPDATE, actor=user, before=before,
                      after={"status": doc.status, "reason": reason})
    await db.commit()
    return await get_return(db, return_id)


async def returnable_lines(db: AsyncSession, grn_id: int) -> list[m.ReceiptItem]:
    """The rejected lines of a GRN — the only ones a return may be raised against."""
    receipt = await _load(db, m.Receipt, grn_id, "Receipt", m.Receipt.items)
    return [l for l in receipt.items if _d(l.rejected_qty) > ZERO]


# ---------------------------------------------------------------------------
# Purchase Return — Warehouse → Vendor flow (auto-fetch + Send to Vendor)
# ---------------------------------------------------------------------------

def _vendor_address(vendor: Vendor | None) -> str | None:
    if not vendor or not vendor.address:
        return None
    parts = [vendor.address, vendor.city, vendor.state, vendor.pincode]
    return ", ".join(p for p in parts if p)



async def _po_of(db: AsyncSession, po_id: int | None):
    """One purchase order, or None where procurement cannot be reached."""
    if not po_id:
        return None
    try:
        from app.modules.procurement.models import PurchaseOrder as _PO
        return await db.get(_PO, po_id)
    except Exception:
        logger.debug("PO %s not reachable", po_id, exc_info=True)
        return None


async def _receipt_vendor(db: AsyncSession, receipt: m.Receipt | None,
                          po_id: int | None = None) -> tuple[int | None, str | None]:
    """Whose delivery this was: the GRN's own vendor, else the vendor on its PO.

    The fallback is not a nicety. A goods receipt raised as a gate entry — the driver's
    paperwork typed in at the barrier — frequently carries no `vendor_id` of its own,
    and the only place the supplier is named is the purchase order it was received
    against. `create_return` has always read the two in this order; `update_return` and
    `send_to_vendor` did not, so binding such a GRN to a return left the vendor null and
    the send then refused the document for having no vendor.

    Takes a SAVED ROW. The payload equivalent is `_receipt_write_vendor`, which used to
    be called `_receipt_vendor` too and was shadowed by this one — see the note in its
    docstring before renaming either of them back.
    """
    if receipt is not None and receipt.vendor_id:
        return receipt.vendor_id, receipt.vendor_name
    po = await _po_of(db, po_id or (receipt.po_id if receipt is not None else None))
    if po is not None and po.vendor_id:
        return po.vendor_id, po.vendor_name
    return None, (receipt.vendor_name if receipt is not None else None)


async def _receipt_indent(db: AsyncSession, receipt: m.Receipt | None,
                          po=None) -> tuple[int | None, str | None]:
    """The request the material was bought against: the GRN's lines, else its PO.

    `inb_receipt_items.indent_id` is only filled where the receipt was raised FROM an
    indent-linked purchase order line, and a great many receipts — anything received
    against a PO whose lines were not stamped, and every gate entry typed in at the
    barrier — carry it on no line at all. The purchase order keeps the same backward
    pointer (`pro_purchase_orders.indent_id`, the link procurement writes when a PO is
    raised off an indent), so where the receipt is silent the PO still answers, and the
    Indent field on a return stopped reading as "there wasn't one".
    """
    if receipt is not None:
        line = (await db.execute(
            select(m.ReceiptItem)
            .where(m.ReceiptItem.receipt_id == receipt.id,
                   m.ReceiptItem.indent_id.isnot(None))
            .order_by(m.ReceiptItem.line_no).limit(1))).scalars().first()
        if line is not None:
            return line.indent_id, line.indent_no
    if po is None and receipt is not None:
        po = await _po_of(db, receipt.po_id)
    if po is not None and getattr(po, "indent_id", None):
        # `pro_purchase_orders.indent_no` is a snapshot procurement only fills on some
        # doors — a PO raised through the requisition/RFQ/quotation route carries the id
        # and leaves the number NULL. Returning that pair unread put an indent_id on the
        # screen with an empty Indent field beside it, which reads as "there wasn't one".
        return po.indent_id, getattr(po, "indent_no", None) or await _indent_no(
            db, po.indent_id)
    return None, None


async def _indent_no(db: AsyncSession, indent_id: int | None) -> str | None:
    """The indent's own number, for the trails that hold only its id."""
    if not indent_id:
        return None
    try:
        from app.modules.indents.models import Indent as _Indent
        indent = await db.get(_Indent, indent_id)
    except Exception:
        logger.debug("Indent %s not reachable", indent_id, exc_info=True)
        return None
    return getattr(indent, "indent_no", None)


async def _trace_purchase_source(db: AsyncSession, doc: m.PurchaseReturn) -> dict:
    """The purchase behind a return that was raised without one.

    A return the returns module raises off a branch consignment stores no `grn_id`, no
    `po_id` and often no vendor: at gate-out it resolves those by asking whether a PO was
    raised against the INDENT the field return names, and where the branch was served out
    of stock bought on some other indent's order — the ordinary case — that query finds
    nothing and the document is saved with the whole chain null. The review screen then
    had nothing to show and the send had no vendor to send to.

    So the chain is read here instead, backwards from the only thing such a document
    reliably carries: the stock itself. A line's batch names the GRN it arrived on
    (`stk_batches.grn_id`), and failing that the receipts for that item at this return's
    own warehouse do. The GRN names its PO and the PO names the vendor.

    NOTHING here is written to the document. Every value goes onto transient `traced_*`
    fields the schema serves separately from the stored ones, because `get_return` is
    called at the top of `update_return`, `submit_return` and `act_on_return`, each of
    which commits — assigning to a real column here would silently persist a traced guess
    as though the storekeeper had bound it. Binding is a WRITE and belongs to the send,
    where a person has read the vendor's name on a confirm and pressed the button.

    Returns `{}` when the trail cannot be read, which is an honest answer: the screen says
    the return was raised without a purchase transaction and offers Edit, where the
    existing source picker binds one properly.
    """
    if doc.grn_id or doc.po_id:
        return {}
    item_ids = [line.item_id for line in (doc.items or []) if line.item_id]
    batch_ids = [line.batch_id for line in (doc.items or []) if line.batch_id]
    if not item_ids:
        return {}

    receipt: m.Receipt | None = None
    how = ""
    # 1. The batch is the strongest evidence there is — it IS the delivery this stock
    #    came in on, recorded when the GRN was posted.
    if batch_ids:
        grn_ids = list((await db.execute(
            select(m.Batch.grn_id).where(m.Batch.id.in_(batch_ids),
                                         m.Batch.grn_id.isnot(None))
        )).scalars().all())
        if len(set(grn_ids)) == 1:
            receipt = await db.get(m.Receipt, grn_ids[0])
            how = "the batch this stock was received under"
    # 2. Otherwise the receipts that brought this item into the warehouse now sending it
    #    back. The most recent is used where there are several, and the note says so —
    #    a traced answer the screen labels as traced beats an empty vendor block.
    if receipt is None:
        stmt = (select(m.Receipt)
                .join(m.ReceiptItem, m.ReceiptItem.receipt_id == m.Receipt.id)
                .where(m.ReceiptItem.item_id.in_(item_ids),
                       m.Receipt.status != ReceiptStatus.CANCELLED.value))
        if doc.warehouse_id:
            stmt = stmt.where(m.Receipt.warehouse_id == doc.warehouse_id)
        # Deduplicated by receipt: the join yields one row per matching LINE, so a GRN
        # carrying two of the returned items would otherwise look like two GRNs and be
        # described as ambiguous when it is not.
        rows = list((await db.execute(
            stmt.order_by(m.Receipt.id.desc()).limit(20))).scalars().all())
        found: list[m.Receipt] = []
        for candidate in rows:
            if all(candidate.id != seen.id for seen in found):
                found.append(candidate)
        if found:
            receipt = found[0]
            how = ("the goods receipt this item arrived on" if len(found) == 1
                   else "the most recent goods receipt for this item")
    if receipt is None:
        return {}

    vendor_id, vendor_name = await _receipt_vendor(db, receipt)
    po = await _po_of(db, receipt.po_id)
    indent_id, indent_no = await _receipt_indent(db, receipt, po)
    return {
        "grn_id": receipt.id, "grn_no": receipt.grn_no, "grn_date": receipt.grn_date,
        "invoice_no": receipt.invoice_no or None, "invoice_date": receipt.invoice_date,
        "po_id": receipt.po_id or (po.id if po is not None else None),
        "po_no": receipt.po_no or (po.po_no if po is not None else None),
        "vendor_id": vendor_id, "vendor_name": vendor_name,
        "indent_id": indent_id, "indent_no": indent_no,
        "how": how,
    }


async def trace_purchase_sources(db: AsyncSession,
                                 rows: list[m.PurchaseReturn]) -> dict[int, dict]:
    """`_trace_purchase_source` for a whole page, in a fixed number of queries.

    The register has the same problem the review screen had: a return the returns module
    raised off a branch consignment stores no GRN, PO or vendor, so the GRN and Vendor
    columns were empty on every one of those rows and only the PRET number read. Tracing
    them one at a time would be a query per row per column; this reads the lot in six,
    whatever the page size.

    Keyed by return id, and only for the rows that name no purchase of their own —
    a row with a stored GRN is already answering the question. Same contract as the
    single-document version: nothing is written, and the caller must present the values
    as traced rather than as the document's own.
    """
    pending = [row for row in rows if not row.grn_id and not row.po_id]
    if not pending:
        return {}
    ids = [row.id for row in pending]
    warehouse_of = {row.id: row.warehouse_id for row in pending}

    lines = list((await db.execute(
        select(m.PurchaseReturnItem.return_id, m.PurchaseReturnItem.item_id,
               m.PurchaseReturnItem.batch_id)
        .where(m.PurchaseReturnItem.return_id.in_(ids)))).all())
    if not lines:
        return {}
    item_ids = {item_id for _, item_id, _ in lines if item_id}
    batch_ids = {batch_id for _, _, batch_id in lines if batch_id}

    # batch -> the GRN it was received under
    batch_grn: dict[int, int] = {}
    if batch_ids:
        batch_grn = {bid: gid for bid, gid in (await db.execute(
            select(m.Batch.id, m.Batch.grn_id)
            .where(m.Batch.id.in_(batch_ids), m.Batch.grn_id.isnot(None)))).all()}

    # (item, warehouse) -> the receipts that brought it in, newest first
    by_item: dict[tuple[int, int | None], list[m.Receipt]] = {}
    receipts: dict[int, m.Receipt] = {}
    if item_ids:
        for receipt, item_id in (await db.execute(
            select(m.Receipt, m.ReceiptItem.item_id)
            .join(m.ReceiptItem, m.ReceiptItem.receipt_id == m.Receipt.id)
            .where(m.ReceiptItem.item_id.in_(item_ids),
                   m.Receipt.status != ReceiptStatus.CANCELLED.value)
            .order_by(m.Receipt.id.desc())
        )).all():
            receipts[receipt.id] = receipt
            seen = by_item.setdefault((item_id, receipt.warehouse_id), [])
            if all(receipt.id != other.id for other in seen):
                seen.append(receipt)
    for grn_id in set(batch_grn.values()):
        if grn_id not in receipts:
            found = await db.get(m.Receipt, grn_id)
            if found is not None:
                receipts[grn_id] = found

    # the POs and vendors behind whichever receipts got picked
    pos: dict[int, object] = {}
    po_ids = {r.po_id for r in receipts.values() if r.po_id}
    if po_ids:
        try:
            from app.modules.procurement.models import PurchaseOrder as _PO
            pos = {po.id: po for po in (await db.execute(
                select(_PO).where(_PO.id.in_(po_ids)))).scalars().all()}
        except Exception:
            logger.debug("POs behind traced returns not reachable", exc_info=True)
    vendors: dict[int, Vendor] = {}
    vendor_ids = {r.vendor_id for r in receipts.values() if r.vendor_id}
    vendor_ids |= {getattr(po, "vendor_id", None) for po in pos.values()}
    vendor_ids.discard(None)
    if vendor_ids:
        vendors = {v.id: v for v in (await db.execute(
            select(Vendor).where(Vendor.id.in_(vendor_ids)))).scalars().all()}

    out: dict[int, dict] = {}
    for return_id in ids:
        mine = [(i, b) for r, i, b in lines if r == return_id]
        receipt = None
        # The batch first, exactly as the single-document trace does.
        batch_hits = {batch_grn[b] for _, b in mine if b and b in batch_grn}
        if len(batch_hits) == 1:
            receipt = receipts.get(next(iter(batch_hits)))
        if receipt is None:
            candidates: list[m.Receipt] = []
            for item_id, _ in mine:
                for found in by_item.get((item_id, warehouse_of.get(return_id)), []):
                    if all(found.id != other.id for other in candidates):
                        candidates.append(found)
            candidates.sort(key=lambda r: r.id, reverse=True)
            receipt = candidates[0] if candidates else None
        if receipt is None:
            continue
        po = pos.get(receipt.po_id) if receipt.po_id else None
        vendor_id = receipt.vendor_id or getattr(po, "vendor_id", None)
        vendor = vendors.get(vendor_id) if vendor_id else None
        out[return_id] = {
            "grn_id": receipt.id, "grn_no": receipt.grn_no,
            "po_id": receipt.po_id or getattr(po, "id", None),
            "po_no": receipt.po_no or getattr(po, "po_no", None),
            "vendor_id": vendor_id,
            "vendor_name": (vendor.name if vendor else None)
            or receipt.vendor_name or getattr(po, "vendor_name", None),
        }
    return out


# A purchase return may be handed to the vendor from either of two states, and it has
# to be both (2026-09-19).
#
# DRAFT is the original path: raise it and send it, no approval anywhere. APPROVED is
# what `submit_return` produces once a PURCHASE_RETURN ladder has signed — and until
# now `send_to_vendor` refused everything but DRAFT, so submitting a return for
# approval permanently foreclosed sending it. The two were rival lifecycles on one
# table and taking the second was a one-way door into a document that could never
# leave. BHS/NA/2026-27/PRET0001 is sitting in exactly that state.
#
# Deliberately NOT here: PENDING_APPROVAL. A return waiting on a signature has not been
# agreed yet, and sending it would be the send racing the ladder — which is the whole
# point of having asked for one.
SENDABLE_RETURN_STATUSES = frozenset({
    ReturnStatus.DRAFT.value, ReturnStatus.APPROVED.value,
})


async def _enrich_return_with_vendor(db: AsyncSession, doc: m.PurchaseReturn,
                                     vendor_id: int | None = None) -> m.PurchaseReturn:
    """Auto-fetch vendor details from mst_vendors — never typed, always read.

    `vendor_id` overrides the document's own only where the document HAS none and the
    chain was traced (`_trace_purchase_source`); the master is still the one source of
    the vendor's details either way.
    """
    vendor_id = doc.vendor_id or vendor_id
    vendor = await db.get(Vendor, vendor_id) if vendor_id else None
    # A MANUAL return's vendor was typed and there may be no `mst_vendors` row behind
    # it at all. Served out of the document's own `manual_vendor_*` columns onto the
    # same `vendor_*` names the sourced path uses, so the API shape does not change and
    # no reader has to branch. Where a manual return DOES name a real vendor the master
    # still wins for anything left blank — the typed value is the override, not a
    # second copy of the master.
    if doc.is_manual:
        doc.vendor_code = doc.manual_vendor_code or (vendor.code if vendor else None)
        doc.vendor_contact_person = doc.manual_vendor_contact_person or (
            vendor.contact_person if vendor else None)
        doc.vendor_phone = doc.manual_vendor_phone or (vendor.phone if vendor else None)
        doc.vendor_email = doc.manual_vendor_email or (vendor.email if vendor else None)
        doc.vendor_address = doc.manual_vendor_address or _vendor_address(vendor)
        doc.vendor_city = doc.manual_vendor_city or (vendor.city if vendor else None)
        doc.vendor_state = doc.manual_vendor_state or (vendor.state if vendor else None)
        doc.vendor_pincode = doc.manual_vendor_pincode or (
            vendor.pincode if vendor else None)
        doc.vendor_gstin = doc.manual_vendor_gstin or (vendor.gstin if vendor else None)
        doc.traced_vendor_name = None
    elif vendor:
        doc.vendor_code = vendor.code  # transient for serializer
        doc.vendor_contact_person = vendor.contact_person
        doc.vendor_phone = vendor.phone
        doc.vendor_email = vendor.email
        doc.vendor_address = _vendor_address(vendor)
        doc.vendor_city = vendor.city
        doc.vendor_state = vendor.state
        doc.vendor_gstin = vendor.gstin
        doc.vendor_pincode = vendor.pincode
        # The master's name, served beside the document's own snapshot rather than
        # written over it. `vendor_name` is a COLUMN: assigning to it here would be
        # persisted by whichever caller commits next (`update_return`, `submit_return`
        # and `act_on_return` all call `get_return` first), which for a TRACED vendor
        # would stamp a guess onto the document as though somebody had bound it.
        doc.traced_vendor_name = vendor.name
    else:
        doc.traced_vendor_name = None
        doc.vendor_code = None
        doc.vendor_contact_person = None
        doc.vendor_phone = None
        doc.vendor_email = None
        doc.vendor_address = None
        doc.vendor_city = None
        doc.vendor_state = None
        doc.vendor_gstin = None
        doc.vendor_pincode = None
    # Reason label, and whether the stored reason IS one of the served codes.
    #
    # `reason_code` is null far more often than it looks: a return the returns module
    # raises automatically off a branch consignment stores the reason's LABEL ("Damaged
    # in transit"), because on that document the reason is prose written by the field.
    # `send_to_vendor` only accepts one of the codes, so a screen that posted the stored
    # reason back was refused on exactly those documents. Served, so the review screen
    # knows to ask for a reason instead of guessing one.
    doc.reason_code = None
    if doc.reason:
        for val, label in s.PURCHASE_RETURN_REASONS:
            if val == doc.reason:
                doc.reason_label = label
                doc.reason_code = val
                break
        else:
            doc.reason_label = doc.reason
    else:
        doc.reason_label = None
    # Only a DRAFT can be sent to the vendor. A SENT_TO_VENDOR/DISPATCHED/
    # COMPLETED row must never offer the button again (duplicate-send guard).
    # A draft with no vendor at all or no lines is refused by `send_to_vendor` too —
    # offering the button there only produces an error the storekeeper cannot act on.
    # A TRACED vendor counts: the send posts it back and binds it, which is the press
    # that turns a traced chain into a bound one.
    #
    # On a MANUAL return the vendor is a NAME and frequently has no `mst_vendors` row —
    # that is the whole point of one — so the name is what the send is gated on there.
    doc.can_send_to_vendor = (
        doc.status in SENDABLE_RETURN_STATUSES
        and (vendor_id is not None
             or (doc.is_manual and bool((doc.vendor_name or "").strip())))
        and bool(doc.items)
    )
    return doc


# Where the material a purchase return sends back came FROM. The values are written by
# the returns module (`returns.enums.PurchaseReturnSource`) and the labels are repeated
# here rather than imported: the dependency runs returns -> warehouse and must not be
# turned around for a display string. An unknown value serves no label rather than a
# guess, so a category added there shows as its raw code until it is named here too.
PURCHASE_RETURN_SOURCE_LABELS: dict[str, str] = {
    "FROM_WAREHOUSE": "From warehouse",
    "FROM_LIP_MDB": "From LIP / MDB",
    "QC_REJECTED_GRN": "QC rejected after GRN",
}


async def _decorate_purchase_return(db: AsyncSession, doc: m.PurchaseReturn) -> m.PurchaseReturn:
    # Where the material came from, named. The column has been written since 2026-09-08
    # and nothing served it.
    doc.source_category_label = PURCHASE_RETURN_SOURCE_LABELS.get(
        doc.source_category or "")
    # What the supplier answered, worded for the pill. FIRST, before the manual branch
    # returns early below: an answer belongs to a return that has been SENT, and a
    # manual return is sent to a vendor exactly as a sourced one is.
    _apply_vendor_answer(doc)
    # A MANUAL return names no purchase because there is none to name — the goods'
    # paperwork never reached this system. Tracing one would go looking for a GRN
    # behind stock the document never claimed came from a GRN, and dress whatever it
    # found up as this return's chain. Its vendor and its per-line quantities are
    # already on the document; nothing here is derived.
    if doc.is_manual:
        doc.chain_traced = False
        doc.chain_note = None
        doc.traced_grn_id = doc.traced_grn_no = None
        doc.traced_po_id = doc.traced_po_no = None
        doc.traced_vendor_id = doc.traced_vendor_name = None
        # The rest of the chain's transient fields, set to nothing rather than left
        # unset: they are plain attributes on the ORM object, so a reader that skips
        # this branch's assignments gets AttributeError and not None.
        doc.grn_date = None
        doc.invoice_no = doc.invoice_date = None
        doc.indent_id = doc.indent_no = None
        doc.material_receipt_id = None
        await _enrich_return_with_vendor(db, doc)
        # A manual line's purchased / already-returned / available were TYPED and are
        # stored on the row; the sourced path derives them and must overwrite nothing
        # here. They are already on `doc.items` as columns, so there is nothing to do.
        return await _decorate_return_dispatch(db, doc)
    # Where the document names no purchase at all, read the one behind its stock. Served
    # under `traced_*` and never written (see `_trace_purchase_source`).
    traced = await _trace_purchase_source(db, doc)
    doc.chain_traced = bool(traced)
    doc.chain_note = (
        f"This return was raised without a purchase transaction on it. The details below "
        f"are read from {traced['how']} — sending binds them to the return."
        if traced else None)
    doc.traced_grn_id = traced.get("grn_id")
    doc.traced_grn_no = traced.get("grn_no")
    doc.traced_po_id = traced.get("po_id")
    doc.traced_po_no = traced.get("po_no")
    doc.traced_vendor_id = traced.get("vendor_id")
    await _enrich_return_with_vendor(db, doc, vendor_id=traced.get("vendor_id"))
    if traced:
        doc.grn_date = traced.get("grn_date")
        doc.invoice_no = traced.get("invoice_no")
        doc.invoice_date = traced.get("invoice_date")
        doc.indent_id = traced.get("indent_id")
        doc.indent_no = traced.get("indent_no")
        if doc.traced_vendor_name is None:
            doc.traced_vendor_name = traced.get("vendor_name")
    # Enrich each line with original / previously returned / returnable
    # Caps already computed in _apply_return_lines; re-derive for read.
    caps: dict[int, Decimal] = {}
    originals: dict[int, Decimal] = {}
    po_caps: dict[int, Decimal] = {}
    po_originals: dict[int, Decimal] = {}
    # Keyed by item_id rather than by source line, for the lines that carry no
    # `grn_item_id`/`po_item_id` — every return the returns module raises automatically
    # off a branch consignment is one of those (it knows the item and the quantity that
    # went on the truck, not which GRN line it came off). Without these the read path
    # reported each such line's own quantity as its availability while
    # `_apply_return_lines` validated the save against the real per-item cap, so the
    # screen could offer a quantity the save then refused.
    item_caps: dict[int, Decimal] = {}
    item_originals: dict[int, Decimal] = {}
    po_item_caps: dict[int, Decimal] = {}
    po_item_originals: dict[int, Decimal] = {}
    # The GRN the availability is measured against: the one bound to the document, or
    # the one traced behind its stock. Availability has to answer the same question
    # either way, or the screen offers a quantity the save refuses.
    grn_for_caps = doc.grn_id or doc.traced_grn_id
    po_for_caps = doc.po_id or (doc.traced_po_id if not grn_for_caps else None)
    if grn_for_caps:
        receipt = await db.get(m.Receipt, grn_for_caps)
        if receipt:
            # The purchase the return answers — the GRN's own date and the vendor's
            # invoice behind it, which is the reference the vendor argues about.
            doc.grn_date = receipt.grn_date
            doc.invoice_no = receipt.invoice_no or None
            doc.invoice_date = receipt.invoice_date
            doc.material_receipt_id = receipt.id
            # `po_no` is a COLUMN — served beside the stored one, never written over it
            # (see the note in `_enrich_return_with_vendor`).
            if not doc.po_no and receipt.po_no:
                doc.traced_po_no = doc.traced_po_no or receipt.po_no
            # need items — load without selectinload for simplicity
            stmt = select(m.ReceiptItem).where(m.ReceiptItem.receipt_id == grn_for_caps)
            grn_items = (await db.execute(stmt)).scalars().all()
            # The request the material was bought against — the GRN's own lines where
            # they carry it, the purchase order behind it where they do not.
            doc.indent_id, doc.indent_no = await _receipt_indent(db, receipt)
            originals = {it.id: _grn_line_returnable(it) for it in grn_items}
            caps = dict(originals)
            for it in grn_items:
                item_originals[it.item_id] = (
                    item_originals.get(it.item_id, ZERO) + _grn_line_returnable(it))
            item_caps = dict(item_originals)
            # subtract already returned except this doc
            already = (await db.execute(
                select(m.PurchaseReturnItem.grn_item_id,
                       func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
                .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
                .where(m.PurchaseReturn.grn_id == grn_for_caps,
                       m.PurchaseReturn.id != doc.id,
                       m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                       m.PurchaseReturnItem.grn_item_id.isnot(None))
                .group_by(m.PurchaseReturnItem.grn_item_id)
            )).all()
            for gid, qty in already:
                caps[gid] = max(caps.get(gid, ZERO) - _d(qty), ZERO)
                grn_line = next((it for it in grn_items if it.id == gid), None)
                if grn_line is not None:
                    item_caps[grn_line.item_id] = max(
                        item_caps.get(grn_line.item_id, ZERO) - _d(qty), ZERO)
            # Quantities already returned on lines carrying no link count too — the same
            # correction `_apply_return_lines` makes, or the cap silently re-opens.
            already_unlinked = (await db.execute(
                select(m.PurchaseReturnItem.item_id,
                       func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
                .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
                .where(m.PurchaseReturn.grn_id == grn_for_caps,
                       m.PurchaseReturn.id != doc.id,
                       m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                       m.PurchaseReturnItem.grn_item_id.is_(None))
                .group_by(m.PurchaseReturnItem.item_id)
            )).all()
            for iid, qty in already_unlinked:
                item_caps[iid] = max(item_caps.get(iid, ZERO) - _d(qty), ZERO)
    elif po_for_caps:
        try:
            from app.modules.procurement.models import POItem as _POItemR
            po_items = (await db.execute(
                select(_POItemR).where(_POItemR.po_id == po_for_caps))).scalars().all()
            po_originals = {it.id: _d(it.quantity) for it in po_items}
            po_caps = dict(po_originals)
            for it in po_items:
                po_item_originals[it.item_id] = (
                    po_item_originals.get(it.item_id, ZERO) + _d(it.quantity))
            po_item_caps = dict(po_item_originals)
            already_po = (await db.execute(
                select(m.PurchaseReturnItem.po_item_id,
                       func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
                .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
                .where(m.PurchaseReturn.po_id == po_for_caps,
                       m.PurchaseReturn.id != doc.id,
                       m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                       m.PurchaseReturnItem.po_item_id.isnot(None))
                .group_by(m.PurchaseReturnItem.po_item_id)
            )).all()
            for pid, qty in already_po:
                po_caps[pid] = max(po_caps.get(pid, ZERO) - _d(qty), ZERO)
                po_line = next((it for it in po_items if it.id == pid), None)
                if po_line is not None:
                    po_item_caps[po_line.item_id] = max(
                        po_item_caps.get(po_line.item_id, ZERO) - _d(qty), ZERO)
            already_po_unlinked = (await db.execute(
                select(m.PurchaseReturnItem.item_id,
                       func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
                .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
                .where(m.PurchaseReturn.po_id == po_for_caps,
                       m.PurchaseReturn.id != doc.id,
                       m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                       m.PurchaseReturnItem.po_item_id.is_(None))
                .group_by(m.PurchaseReturnItem.item_id)
            )).all()
            for iid, qty in already_po_unlinked:
                po_item_caps[iid] = max(po_item_caps.get(iid, ZERO) - _d(qty), ZERO)
        except Exception:
            logger.debug("PO returnable decoration skipped", exc_info=True)
    for line in doc.items or []:
        gid = line.grn_item_id
        pid = line.po_item_id
        if gid:
            orig = originals.get(gid, _d(line.quantity))
            prev = max(orig - caps.get(gid, orig), ZERO)
            ret = caps.get(gid, _d(line.quantity))
        elif pid and po_originals:
            orig = po_originals.get(pid, _d(line.quantity))
            prev = max(orig - po_caps.get(pid, orig), ZERO)
            ret = po_caps.get(pid, _d(line.quantity))
        elif line.item_id in item_originals:
            # No source line on the row, but the GRN knows this item: report what the
            # save will actually allow, which is the item's own cap plus what this
            # document is already holding (its own quantity is not "already returned").
            orig = item_originals[line.item_id]
            prev = max(orig - item_caps.get(line.item_id, orig), ZERO)
            ret = item_caps.get(line.item_id, _d(line.quantity))
        elif line.item_id in po_item_originals:
            orig = po_item_originals[line.item_id]
            prev = max(orig - po_item_caps.get(line.item_id, orig), ZERO)
            ret = po_item_caps.get(line.item_id, _d(line.quantity))
        else:
            orig = _d(line.quantity)
            prev = ZERO
            ret = _d(line.quantity)
        line.original_qty = orig
        line.previously_returned = prev
        line.returnable_qty = ret
    return await _decorate_return_dispatch(db, doc)


async def _decorate_return_dispatch(db: AsyncSession,
                                    doc: m.PurchaseReturn) -> m.PurchaseReturn:
    """The logistics leg carrying this return, where it has already been sent.

    Read back off `out_dispatches` rather than stored on the return: `send_to_vendor`
    set the two transient fields on its own response only, so the Dispatch reference
    vanished from the screen on the next refresh of a return that plainly had one.

    Its own function because a MANUAL return leaves `_decorate_purchase_return` early —
    it has no chain to trace and no caps to compute — and would otherwise skip this and
    lose the dispatch link the moment it was sent.
    """
    if getattr(doc, "dispatch_id", None) is None:
        # SET TO NOTHING FIRST, rather than left unset when there is no consignment.
        # These are plain transient attributes on the ORM object, so a reader that hits
        # the no-consignment path gets AttributeError and not None — which is exactly what
        # took the journey down on every DRAFT the first time it was run against the live
        # database. The same reason `_decorate_purchase_return`'s manual branch assigns
        # its whole set explicitly.
        doc.dispatch_id = None
        doc.dispatch_no = None
        leg = await db.scalar(
            select(m.Dispatch)
            .where(m.Dispatch.ref_type == "PURCHASE_RETURN", m.Dispatch.ref_id == doc.id)
            .order_by(m.Dispatch.id.desc()).limit(1))
        if leg is not None:
            doc.dispatch_id = leg.id
            doc.dispatch_no = leg.dispatch_no
    return await _decorate_return_inbound_leg(db, doc)


async def _decorate_return_inbound_leg(db: AsyncSession,
                                       doc: m.PurchaseReturn) -> m.PurchaseReturn:
    """The vehicle bringing an approved return's material back, and which press is next.

    ONE SERVED SHAPE OVER TWO SOURCES, which is the whole point of it. On a
    VENDOR_ARRANGES leg the vendor stated a vehicle over the phone and the columns on
    this row are the only record of it. On a WAREHOUSE_REQUESTS leg the vehicle belongs
    to the Logistics transport request the desk assigned it on, and it is READ off that
    leg here rather than mirrored onto `pro_returns` — a stored copy would go stale the
    first time logistics re-assigned a truck, and the return would then name a vehicle
    that was never coming. Same reason `_decorate_return_dispatch` above reads the
    consignment back instead of trusting what `send_to_vendor` stamped on its response.

    `collection_tr_id` is reused rather than a second pair of columns added: it already
    means "the Logistics trip fetching goods from this supplier for this return", which
    is exactly what a warehouse-requested vehicle is. The supplier-collection path
    (`_raise_collection_shipment`) writes the same pair, and the two can never both
    apply — a return whose desk requested a vehicle is past the rung the supplier
    portal's answer can be given on (`VENDOR_ANSWERABLE_RETURN_STATUSES`).

    The `can_*` flags are served for the same reason the labels are: the rungs a press
    is legal on are the service's own guards, and a screen re-deriving them from the
    status string would be a second copy of the ladder drifting from the first. They say
    where the DOCUMENT stands, never whether this user may press — the permission is
    checked on the route, and hiding a button is not the control (rule 6).
    """
    from app.modules.logistics.models import TransportRequest

    doc.inbound_tr_status = None
    # What the desk recorded off the vendor, as the starting answer. On a vendor-arranged
    # leg it is the ONLY answer — there is no transport request to overwrite it.
    doc.inbound_vehicle_no = doc.arranged_vehicle_no
    doc.inbound_driver_name = doc.arranged_driver_name
    doc.inbound_driver_phone = doc.arranged_driver_phone
    doc.inbound_transporter_name = doc.arranged_transporter_name
    doc.inbound_lr_no = doc.arranged_lr_no
    doc.inbound_expected_date = doc.arranged_expected_date
    doc.inbound_dispatched_at = doc.arranged_dispatched_at

    if doc.inbound_tr_id:
        leg = await db.get(TransportRequest, doc.inbound_tr_id)
        if leg is not None:
            doc.inbound_tr_status = leg.status
            # Only where the leg says something. A DRAFT request carries no vehicle
            # yet, and blanking the answer because logistics has not filled its own
            # column in would lose the only one anybody had.
            doc.inbound_vehicle_no = leg.vehicle_number or doc.inbound_vehicle_no
            doc.inbound_driver_name = leg.driver_name or doc.inbound_driver_name
            doc.inbound_driver_phone = leg.driver_phone or doc.inbound_driver_phone
            doc.inbound_transporter_name = (leg.carrier_name
                                            or doc.inbound_transporter_name)
            doc.inbound_lr_no = leg.lr_no or doc.inbound_lr_no
            doc.inbound_expected_date = (leg.expected_delivery
                                         or doc.inbound_expected_date)
            doc.inbound_dispatched_at = (leg.dispatched_at
                                         or doc.inbound_dispatched_at)

    # The one rung that covers two things a person distinguishes — see
    # `enums.ReturnStatus.VEHICLE_REQUESTED`. Refined here because only this function
    # has the leg; `_apply_vendor_answer` worded it off the status alone for the
    # register, and the more specific answer replaces it on the document.
    doc.status_label = (
        return_stage_label(doc.status,
                           vehicle_assigned=bool(doc.inbound_vehicle_no
                                                 or doc.inbound_driver_name))
        or getattr(doc, "status_label", None))

    # WHICH RUNG THIS DOCUMENT IS STANDING AT, served rather than worked out in a screen.
    #
    # Every flag reads the SAME frozenset the matching service guard reads, which is what
    # makes the button a screen draws and the press the server accepts provably the same
    # thing. Re-deriving them from the status string in the browser would be a second copy
    # of the ladder, free to drift from the first.
    #
    # ONE of these puts a button in front of an employee — `can_arrange_transport`, the
    # single decision this warehouse still makes. The `awaiting_*` flags below are
    # READ-ONLY: they say which press the VENDOR owes us, so our screen can show where the
    # return is standing without offering to answer for them.
    doc.can_arrange_transport = doc.status in RETURN_TRANSPORTABLE_STATUSES
    # Retained spelling of the flag above — see `schemas.ReturnDetail`.
    doc.can_arrange_vehicle = doc.can_arrange_transport
    doc.can_confirm_receipt = doc.status in RETURN_INBOUND_STATUSES

    doc.awaiting_vendor_decision = doc.status in RETURN_DECIDABLE_STATUSES
    doc.awaiting_vendor_settlement = doc.status in RETURN_SETTLEABLE_STATUSES
    # Only the vendor-arranged branch waits on the vendor for a vehicle; on the other one
    # it is Logistics' to assign and nothing is owed by the vendor at all.
    doc.awaiting_vendor_transport = (
        doc.vehicle_arrangement == ReturnVehicleArrangement.VENDOR_ARRANGES.value
        and doc.status in RETURN_VENDOR_ACCEPTABLE_STATUSES)
    doc.awaiting_vendor_receipt = doc.status in RETURN_VENDOR_RECEIVABLE_STATUSES
    doc.awaiting_replacement_dispatch = (
        doc.status in RETURN_REPLACEMENT_DISPATCHABLE_STATUSES)

    # WHERE THE REPLACEMENT'S INTAKE HAS GOT TO — the GRN, its QC and its putaway.
    #
    # Served for the same reason everything else here is: those three rungs live on
    # `inb_receipts`, `inb_inspections` and `whs_warehouse_items`, and a screen that went
    # and read them itself would be re-deriving the ladder the journey already describes.
    # This is the same intake `_journey_legs` draws, so the sentence on the return's own
    # band and the tracker beside it cannot say two different things.
    #
    # DETAIL PATH ONLY, and deliberately: `_decorate_purchase_return` runs on `get_return`
    # and on the vendor's copy, never on `list_returns`. Three more queries on a register
    # of two hundred rows would be six hundred queries to say something no register column
    # shows.
    intake = await _replacement_intake(db, doc)
    doc.replacement_grn_no = intake["grn_no"] or doc.vendor_followup_receipt_no
    doc.replacement_grn_status = intake["grn_status"]
    doc.replacement_inspection_no = intake["inspection_no"]
    doc.replacement_putaway_total = intake["putaway_total"]
    doc.replacement_putaway_done = intake["putaway_done"]
    doc.replacement_intake_complete = intake["intake_complete"]
    doc.replacement_intake_stage = _replacement_intake_stage(doc, intake)
    return doc


def _replacement_intake_stage(doc: m.PurchaseReturn, intake: dict) -> str | None:
    """What the store still owes on the replacement, in one sentence, or None.

    None — not a fallback string — on a return with no replacement coming, so a screen
    writes `replacement_intake_stage && <panel>` and a refund, a refusal and every return
    raised before this flow existed render exactly as they did.

    Composed HERE rather than in the screen for the reason every label in this module is:
    the register, the detail band and the tracker must not word one document three ways.
    """
    if not intake["grn_no"] or doc.status in RETURN_CLOSED_STATUSES:
        return None
    grn = intake["grn_no"]
    if not intake["grn_booked"]:
        return (f"The replacement is booked in on goods receipt {grn}. Submit it when the "
                f"lorry arrives — the return moves on with it.")
    if intake["qc_failed"]:
        return (f"QC rejected the replacement on {grn}. Nothing will be put away and this "
                f"return stays open until the vendor is asked again.")
    if not intake["qc_passed"]:
        return (f"{grn} is booked in and waiting on QC"
                + (f" ({intake['inspection_no']})" if intake["inspection_no"] else "")
                + ". Putaway opens once QC passes.")
    if intake["putaway_open"]:
        return (f"QC passed {grn}. {intake['putaway_done']} of "
                f"{intake['putaway_total']} putaway task(s) placed — this return closes "
                f"itself when the last one is confirmed.")
    return f"The replacement is on the shelf against {grn}; this return is closing."


def purchase_return_reasons() -> list[dict]:
    return [{"value": v, "label": l} for v, l in s.PURCHASE_RETURN_REASONS]


def purchase_return_vehicle_arrangements() -> list[dict]:
    """The two cards offered once a sent return has been approved.

    Served rather than written into the screen for the reason every catalogue in this
    module is: the sentence a desk decides against and the sentence the audit trail
    records have to be the same sentence.
    """
    return [{"value": value, "label": label, "help": help_text,
             "raises_vehicle_request": raises}
            for value, label, help_text, raises in RETURN_VEHICLE_ARRANGEMENTS]


def purchase_return_logistics_modes() -> list[dict]:
    """The three ways a return travels back, and what each one asks for.

    The `needs_*` flags travel WITH the option rather than being restated in the
    screen: the wizard renders the carrier fields because the mode it is on said it
    needs a carrier, so turning COURIER on later is one row in the catalogue.
    """
    return [
        {"value": v, "label": label, "help": help_,
         "needs_carrier": v in s.LOGISTICS_MODES_NEEDING_CARRIER,
         "needs_vehicle": v in s.LOGISTICS_MODES_NEEDING_VEHICLE,
         "needs_bearer": v in s.LOGISTICS_MODES_NEEDING_BEARER,
         # The one mode that hands the load on instead of finishing it at the gate.
         # Read off the same constant `send_to_vendor` raises the shipment from, so the
         # wizard cannot ask for a signature on a leg that has not travelled yet.
         "raises_shipment": v == LOGISTICS_MODE_RAISING_SHIPMENT}
        for v, label, help_ in s.PURCHASE_RETURN_LOGISTICS_MODES
    ]


def _validate_return_logistics(data: "s.PurchaseReturnLogisticsIn") -> str:
    """Check a posted logistics block and hand back the canonical mode.

    Split out from `_apply_return_logistics` below because a MANUAL return raises no
    dispatch to apply anything to and still has to be checked — the storekeeper
    answered the same questions on the same wizard, and a value that would have been
    refused on a sourced return cannot be quietly accepted on a manual one just
    because there is no row waiting for it.
    """
    valid = {v for v, _, _ in s.PURCHASE_RETURN_LOGISTICS_MODES}
    mode = (data.mode or "").strip().upper()
    if mode not in valid:
        raise ValidationError(
            f"Choose how the return travels — one of: {', '.join(sorted(valid))}.")

    # Mode-specific. The wizard asks these on the Logistics step and will not move
    # past it without them; repeated here because the endpoint is reachable without
    # the wizard and an unattributed leg is the thing this flow exists to stop.
    if mode in s.LOGISTICS_MODES_NEEDING_BEARER and not (data.hand_carried_by or "").strip():
        raise ValidationError(
            "Enter who is carrying the goods — a hand-over has no carrier and no "
            "vehicle, so the person's name is the whole record of who took them.")
    if mode in s.LOGISTICS_MODES_NEEDING_VEHICLE and not (data.vehicle_number or "").strip():
        raise ValidationError(
            "Enter the vehicle number — an own-vehicle leg is identified by which "
            "vehicle went.")
    if mode in s.LOGISTICS_MODES_NEEDING_CARRIER and not (data.carrier_name or "").strip():
        raise ValidationError(
            "Enter the carrier — a third-party leg has to say who is carrying it.")

    # The supplier's signature — on the two modes where the goods are ALREADY GONE by
    # the time this endpoint is reached. A hand-over and a third-party handover both
    # happen at the gate in the same breath as the send: somebody walked out with the
    # carton, or the hired truck drove off with it, and the wizard records who signed.
    #
    # AN OWN VEHICLE LEG IS NOT THAT, and demanding a signature on it was the defect
    # (2026-09-11). Our own truck has not left the yard when the send is pressed — the
    # whole point of the mode is that the trip still has to be ARRANGED, which is why it
    # is the one mode that raises a shipment in Logistics
    # (`LOGISTICS_MODE_RAISING_SHIPMENT`). Requiring the supplier's acknowledgement here
    # forced the storekeeper to certify a signature that could not exist yet, and
    # `_apply_return_logistics` then stamped the consignment ACKNOWLEDGED on the
    # strength of it — which put it outside the statuses `transport_released` will act
    # on, so the logistics desk could never gate it out. The load was finished on paper
    # in the warehouse and its shipment was a ghost. The signature is taken later, on
    # the leg, where it actually happens.
    if mode != LOGISTICS_MODE_RAISING_SHIPMENT:
        if not (data.acknowledged_by_name or "").strip():
            raise ValidationError(
                "Enter who at the supplier acknowledged the return — the acknowledgement "
                "is what closes the handover.")
        if data.acknowledged_at is None:
            raise ValidationError("Enter the date and time the supplier acknowledged it.")
    return mode


def _apply_return_logistics(dispatch, data: "s.PurchaseReturnLogisticsIn", mode: str) -> None:
    """Write a validated logistics block onto the consignment the send just raised.

    Every column here already existed on `out_dispatches` — transport mode, vehicle,
    driver, LR, e-way bill, freight, the delivery point, the acknowledgement and the
    POD. The send simply never filled any of them, so a purchase return left the gate
    as a consignment that said who it was for and nothing about how it got there.

    ONLY THE FIELDS THE CHOSEN MODE OWNS ARE WRITTEN. A leg that was switched from
    third-party to own-vehicle halfway through the wizard must not arrive carrying a
    carrier name from the abandoned branch — the shipments board would show a hired
    truck that was never hired.
    """
    dispatch.transport_mode = mode

    if mode in s.LOGISTICS_MODES_NEEDING_CARRIER:
        dispatch.carrier_name = (data.carrier_name or "").strip() or None
        dispatch.lr_no = (data.lr_no or "").strip() or None
        if data.freight_amount is not None:
            dispatch.freight_amount = _d(data.freight_amount)
    elif mode in s.LOGISTICS_MODES_NEEDING_VEHICLE:
        dispatch.vehicle_number = (data.vehicle_number or "").strip() or None
        dispatch.driver_name = (data.driver_name or "").strip() or None
        dispatch.driver_phone = (data.driver_phone or "").strip() or None
        # An own vehicle is one already going that way — it costs the job nothing, and
        # ZERO is the honest figure rather than a null that reads as "not captured".
        dispatch.freight_amount = ZERO
    else:
        # By hand. Nobody was hired, so there is no carrier field to fill and no
        # freight — the bearer is recorded where every other mode records its driver,
        # which keeps "who physically had the goods" in one column across all three.
        dispatch.driver_name = (data.hand_carried_by or "").strip() or None
        dispatch.freight_amount = ZERO

    # The delivery point. Only overwritten when the wizard actually supplied one —
    # `send_to_vendor` already seeded these from the vendor master, and a blank box
    # that was never edited must not wipe the address it was pre-filled with.
    if (data.delivery_address or "").strip():
        dispatch.delivery_address = data.delivery_address.strip()
    if (data.contact_person or "").strip():
        dispatch.contact_person = data.contact_person.strip()
    if (data.contact_phone or "").strip():
        dispatch.contact_phone = data.contact_phone.strip()

    # What left the gate. `total_packages` was defaulted to the line count by the
    # send; a counted figure from the packing bench replaces it.
    if data.total_packages is not None:
        dispatch.total_packages = int(data.total_packages)
    if data.total_weight_kg is not None:
        dispatch.total_weight_kg = _d(data.total_weight_kg)
    if (data.eway_bill_no or "").strip():
        dispatch.eway_bill_no = data.eway_bill_no.strip()
    if (data.gate_pass_no or "").strip():
        dispatch.gate_pass_no = data.gate_pass_no.strip()
    if data.expected_delivery is not None:
        dispatch.expected_delivery = data.expected_delivery
    if (data.dispatch_remarks or "").strip():
        dispatch.remarks = f"{dispatch.remarks} | {data.dispatch_remarks.strip()}"

    # AN OWN VEHICLE LEG IS HANDED TO LOGISTICS, NOT CLOSED HERE (2026-09-11).
    #
    # Our own truck has not left the yard when the send is pressed, so there is nothing
    # to acknowledge and nothing has been delivered. The consignment is left at
    # APPROVED — which is precisely the status `transport_released` and `gate_out` both
    # accept — and `_raise_return_shipment` puts the trip on the Logistics Dispatch
    # board as a DRAFT. The desk then arranges the vehicle, releases the leg, and THAT
    # is what gates the consignment out and moves the stock.
    #
    # Stamping ACKNOWLEDGED here was the defect. It read as delivered-and-signed the
    # instant the return was sent, which put the consignment outside the three statuses
    # `transport_released` acts on, so the release hook returned at its first guard and
    # `_apply_gate_out` never ran: no gate-out, no stock movement, no `stk_ledger` row.
    # The document was finished inside the warehouse and its shipment could never do
    # anything — the load "stayed in the warehouse" instead of going to Logistics.
    #
    # `pod_url` is still taken if one was somehow supplied, because a proof of delivery
    # is evidence and discarding it would lose a fact; it simply does not close the
    # consignment on its own.
    if (data.pod_url or "").strip():
        dispatch.pod_url = data.pod_url.strip()
    if mode == LOGISTICS_MODE_RAISING_SHIPMENT:
        dispatch.status = DispatchStatus.APPROVED.value
        return

    # The signature, and the status that follows from it, on the two modes where the
    # goods genuinely have gone. `_validate_return_logistics` guarantees both values are
    # present on these, so the consignment is genuinely acknowledged and saying APPROVED
    # — where it used to stop forever — would understate it.
    #
    # SAFE ON A VENDOR RETURN, and only on one: every path that treats an ACKNOWLEDGED
    # consignment as stock already credited (`_dispatch_for_receipt`,
    # `can_forward_dispatch`, the inwardable list) is gated on
    # `_lands_on_internal_shelf`, which excludes `_LEAVES_THE_COMPANY` types and
    # requires a destination warehouse. A VENDOR_RETURN leg is in that tuple and
    # carries no `to_warehouse_id`, so it can never be offered for inward or forward.
    dispatch.acknowledged_by_name = data.acknowledged_by_name.strip()
    dispatch.acknowledged_at = data.acknowledged_at
    dispatch.delivered_at = data.acknowledged_at    # signed for means it arrived
    dispatch.status = DispatchStatus.ACKNOWLEDGED.value


# ---------------------------------------------------------------------------
# The return shipment: an Own Vehicle return, on the Logistics Dispatch board
# ---------------------------------------------------------------------------

#: The one delivery method on the Send to Vendor wizard that raises a shipment of its
#: own in Logistics.
#:
#: "Own Vehicle" is the WAREHOUSE's own truck. Nobody is hired, so there is no tender
#: and no carrier portal to wait on — but a vehicle still has to be assigned, the load
#: still leaves the gate, and the vendor still signs for it. That is a logistics leg,
#: and it was the only one of the three with nowhere to be worked from: a hand-over has
#: no vehicle to arrange, and a third-party leg goes out with the carrier the
#: storekeeper already named on the wizard.
LOGISTICS_MODE_RAISING_SHIPMENT = "OWN_VEHICLE"

#: What the leg is raised AS when the send said nothing about how it travels.
#:
#: The ordinary case since 2026-09-11: filling in a purchase return and pressing Send
#: puts it in front of the supplier immediately, and the transport is arranged
#: afterwards by the people who arrange transport. Nobody has stated a mode at that
#: point, so one has to be assumed for the draft — and the desk changes it on the
#: Dispatch screen before anything is booked.
#:
#: THIRD_PARTY is that assumption, taken from `returns._release_to_logistics`, which
#: made the same call for the same reason: a return leg is a hired truck unless
#: somebody says otherwise. It is only ever a DRAFT's starting value — no carrier is
#: invited and no tender runs until the desk dispatches it.
LOGISTICS_MODE_UNSTATED = "THIRD_PARTY"


def _split_packages(total: int | None, count: int) -> list[int]:
    """`total` cartons spread over `count` lines, remainder to the earliest lines.

    The leg's header totals are DERIVED from its lines and nothing may set them
    directly (`transport._recompute_totals`), so the counted figure from the packing
    bench only survives onto the shipment if it is distributed. Spread rather than
    stacked on line one, because the carrier reads the per-line count off the same
    document. Nothing counted falls back to one carton per line, which is what the
    consignment beside it already assumes (`total_packages=len(doc.items)`).
    """
    if count <= 0:
        return []
    if not total or total < 1:
        return [1] * count
    base, extra = divmod(int(total), count)
    return [base + (1 if i < extra else 0) for i in range(count)]


def _return_shipment_seed(doc, dispatch, vendor, mode: str) -> dict:
    """Everything the return leg needs, read while the send's objects are still live.

    `transport.create_tr` COMMITS, so it cannot be called before `send_to_vendor` has
    committed its own work — and after that commit every instance here is expired.
    Reading the values out first is what keeps the leg from touching a closed
    transaction, and is the same order `returns._release_to_logistics` runs in.
    """
    lines = list(doc.items or [])
    packages = _split_packages(dispatch.total_packages, len(lines))
    total_qty = sum((_d(l.quantity) for l in lines), ZERO)
    counted_weight = _d(dispatch.total_weight_kg) if dispatch.total_weight_kg else None
    return {
        "mode": mode,
        "return_id": doc.id,
        "return_no": doc.return_no,
        "vendor_name": (vendor.name if vendor else doc.vendor_name) or "the vendor",
        "delivery_address": dispatch.delivery_address,
        "contact_person": dispatch.contact_person,
        "contact_phone": dispatch.contact_phone,
        "warehouse_id": doc.warehouse_id,
        "warehouse_name": doc.warehouse_name,
        "dispatch_id": dispatch.id,
        "dispatch_no": dispatch.dispatch_no,
        "vehicle_number": dispatch.vehicle_number,
        "driver_name": dispatch.driver_name,
        "driver_phone": dispatch.driver_phone,
        "gate_pass_no": dispatch.gate_pass_no,
        "eway_bill_no": dispatch.eway_bill_no,
        "expected_delivery": dispatch.expected_delivery,
        "lines": [{
            "item_id": line.item_id,
            "item_code": line.item_code,
            "item_name": line.item_name,
            "uom_code": line.uom_code,
            "quantity": float(_d(line.quantity)),
            "package_count": packages[index],
            # Apportioned by quantity share so the derived header equals what was
            # weighed. Left as None when nothing was weighed — an unweighed line has
            # NO weight, and zero reads as "it weighs nothing".
            "weight_kg": (float(counted_weight * _d(line.quantity) / total_qty)
                          if counted_weight and total_qty > ZERO else None),
            "remarks": line.reason,
        } for index, line in enumerate(lines)],
    }


async def _raise_return_shipment(db: AsyncSession, seed: dict, user, *,
                                 stamp_outbound: bool = False) -> None:
    """Put a purchase return's outward leg on the Logistics Dispatch board as a DRAFT.

    THE SAME DOOR FIELD RETURNS ALREADY COME THROUGH. `DispatchPage` reads a second
    board below the consignment queue — `source_type=RETURN`, every status from DRAFT
    through IN_TRANSIT — and a DRAFT row there gets the Dispatch press that opens
    `/logistics/dispatch/new?tr_id=`. So this raises an ordinary transport request and
    nothing else: no new table, no new status, no screen to build. The rungs the leg
    then climbs are the ones every shipment climbs, which is what the return has to
    walk through — the vehicle assigned and the leg readied, the gate pass written and
    the load dispatched, the trip tracked, the vendor receiving it, and the
    acknowledgement that closes it.

    `source_id` IS DELIBERATELY LEFT NULL, and it is the one subtle thing here. Every
    hook the returns module registers on a shipment starts at `_return_behind`, which
    takes `source_type=RETURN` plus `source_id` and looks the id up in `inv_sto` —
    field returns' own table. A purchase return's id comes from `pro_returns`, an
    unrelated sequence, so passing it would eventually name somebody else's field
    return and let `_transport_released` debit a shelf this return never touched.
    `_return_behind` lets go of a leg with no `source_id` at its first line, so leaving
    it null is what makes this leg provably not theirs. Nothing in logistics reads the
    column — the board and the confirm screen both show `source_no` — so the Return ID
    still travels, as the number a person actually reads, and `dispatch_id` keeps the
    machine-readable link back through the consignment.

    Raised AFTER the caller has committed, and never allowed to undo it: the transport
    decision has been taken and a leg that could not be raised must not un-take it. It is
    logged and the return still stands — the desk can raise one by hand from the Shipments
    register, which is exactly the position every return was in before this.

    `stamp_outbound` WRITES THE LEG'S ID BACK onto the return, and that link is what makes
    the release hook able to find it: `_outbound_return_released` matches `outbound_tr_id`
    and moves the return to STOCK_PICKED_UP when the load actually goes. Its own column
    rather than `inbound_tr_id` or `collection_tr_id`, which two other settlements match
    on — see the model. Off by default so the historical caller, which raised this leg at
    send time and had no rung to move, behaves exactly as it did.
    """
    from app.modules.logistics import transport as lgs_transport
    from app.modules.logistics.enums import TransportSource
    from app.modules.logistics.schemas import TRCreate, TRLineIn

    tr = await lgs_transport.create_tr(db, TRCreate(
        mode=seed["mode"],
        source_type=TransportSource.RETURN.value,
        source_id=None,                       # see the docstring — load-bearing
        source_no=seed["return_no"],
        dispatch_id=seed["dispatch_id"],
        consignment_no=seed["dispatch_no"],
        from_warehouse_id=seed["warehouse_id"],
        from_warehouse_name=seed["warehouse_name"],
        # `create_tr` refuses an inbound leg that does not name where it is going, and
        # for a purchase return that is the vendor rather than one of our warehouses.
        to_location_name=seed["vendor_name"],
        delivery_address=seed["delivery_address"],
        contact_person=seed["contact_person"],
        contact_phone=seed["contact_phone"],
        vehicle_number=seed["vehicle_number"],
        driver_name=seed["driver_name"],
        driver_phone=seed["driver_phone"],
        gate_pass_no=seed["gate_pass_no"],
        eway_bill_no=seed["eway_bill_no"],
        expected_delivery=seed["expected_delivery"],
        remarks=(f"Purchase Return {seed['return_no']} → {seed['vendor_name']} — "
                 f"arrange the outward leg"
                 + (f" · vehicle {seed['vehicle_number']}"
                    if seed["vehicle_number"] else "")),
        lines=[TRLineIn(**line) for line in seed["lines"]],
    ), user)

    if stamp_outbound:
        # A plain UPDATE rather than loading the row: `create_tr` has just committed and
        # the caller's instance is expired. Same device `_raise_collection_shipment` uses.
        await db.execute(
            update(m.PurchaseReturn)
            .where(m.PurchaseReturn.id == seed["return_id"])
            .values(outbound_tr_id=tr.id, outbound_tr_no=tr.tr_no))

    await write_audit(
        db, entity="pro_returns", entity_id=seed["return_id"],
        entity_no=seed["return_no"], action=AuditAction.UPDATE, actor=user,
        after={"transport_request_no": tr.tr_no, "transport_request_id": tr.id,
               "outbound_tr_no": tr.tr_no if stamp_outbound else None,
               "status": tr.status},
        summary=f"Purchase Return {seed['return_no']}: return leg {tr.tr_no} "
                f"raised in Logistics as a draft")
    await db.commit()
    logger.info("Purchase Return %s raised return leg %s (%s)",
                seed["return_no"], tr.tr_no, tr.status)


def _collection_shipment_seed(row, vendor) -> dict:
    """Everything the collection leg needs, read while the answer's objects are live.

    Same ordering, and for the same reason, as `_return_shipment_seed` above:
    `transport.create_tr` COMMITS, so it cannot be called before
    `vendor_respond_to_return` has committed its own work — and after that commit every
    instance here is expired.

    Reads the collection's facts off the RETURN rather than off an inbound receipt,
    because on this path there is no receipt: the trip is the only document the answer
    raises, and the receipt follows when the trip lands. See `PurchaseReturn.collection_tr_id`.
    """
    return {
        "return_id": row.id,
        "return_no": row.return_no,
        "vendor_name": (vendor.name if vendor else row.vendor_name) or "the supplier",
        "warehouse_name": row.warehouse_name,
        "pickup_address": row.collection_pickup_address,
        "ready_date": row.collection_ready_date,
        # Who the driver calls when the vehicle reaches the supplier's gate.
        "contact_person": vendor.contact_person if vendor else None,
        "contact_phone": vendor.phone if vendor else None,
        "lines": [{
            "item_id": line.item_id,
            "item_code": line.item_code,
            "item_name": line.item_name,
            "uom_code": line.uom_code,
            "quantity": float(_d(line.quantity)),
            # One carton per line, which is what the consignment beside an outward
            # return already assumes. Nothing has been packed or weighed: the cartons
            # are standing on the SUPPLIER's dock and nobody here has counted them, so
            # `weight_kg` is deliberately left unsaid rather than invented — an
            # unweighed line has no weight, and zero reads as "it weighs nothing".
            "package_count": 1,
            "remarks": line.reason,
        } for line in (row.items or [])],
    }


async def _raise_collection_shipment(db: AsyncSession, seed: dict, user) -> None:
    """Put a WE_COLLECT replacement on the Logistics Dispatch board as a DRAFT.

    THE OTHER HALF OF `_raise_return_shipment`, and the leg that had nowhere to be
    worked from. When the supplier answers REPLACED they also say how the replacement
    travels: SUPPLIER_DELIVERS puts it on their own vehicle and it simply arrives, and
    the store inwards it through the ordinary receipt → QC → putaway path — that branch
    is untouched here and behaves exactly as it always has. WE_COLLECT is the other
    answer, and it means the goods are sitting ready on the supplier's dock and
    somebody HERE has to send a vehicle for them.

    Until now nothing did. `_raise_vendor_return_inbound` raised the draft receipt with
    the words "COLLECTION REQUIRED — somebody here must send a vehicle" in its remarks,
    left `expected_delivery` null on purpose because no vehicle had been scheduled, and
    that was the end of it: no trip existed anywhere, on any board, and the collection
    was remembered or it was not.

    THE SAME DOOR EVERY OTHER RETURN LEG COMES THROUGH. `DispatchPage` reads a second
    board below the consignment queue — `source_type=RETURN`, every status from DRAFT
    through IN_TRANSIT — and a DRAFT row there gets the Dispatch press that opens
    `/logistics/dispatch/new?tr_id=`. So this raises an ordinary transport request and
    nothing else: no new table, no new status, no screen to build, and the rungs the
    leg then climbs are the ones every shipment climbs.

    `source_id` IS DELIBERATELY LEFT NULL, for exactly the reason `_raise_return_shipment`
    gives: the returns module's hooks start at `_return_behind`, which takes
    `source_type=RETURN` plus `source_id` and looks the id up in `inv_sto` — field
    returns' own table, an unrelated sequence from `pro_returns`. Leaving it null is
    what makes this leg provably not theirs. The return number still travels as
    `source_no`, which is what the board and the confirm screen actually show.

    WHICH WAY ROUND THE ENDS GO. This leg runs supplier → our warehouse, so the pickup
    end is the supplier and `to_location_name` is our own warehouse — which is also the
    check that makes it safe, since `create_tr` refuses an inbound leg that does not
    name where it is coming back to. `from_warehouse_id` stays NULL: the load starts on
    a dock that is not a warehouse of ours, and writing an id there would have the board
    claim one of our own sites shipped it. The pickup ADDRESS goes in the remarks rather
    than `delivery_address`, because that column renders under "To" on the dispatch
    confirm screen and the supplier's dock is where this vehicle comes FROM.

    Raised AFTER the answer has committed, and never allowed to undo it: the supplier
    has answered and the answer is final. A leg that could not be raised is logged and
    the answer still stands — the desk can raise one by hand from the Shipments
    register, which is exactly the position every collection was in before this.

    THE LEG'S ID IS STAMPED BACK ONTO THE RETURN, and that link is load-bearing rather
    than decorative: the inbound receipt is no longer raised when the supplier answers,
    so something has to raise it when our vehicle actually gets back.
    `transport_acknowledged` matches the signed leg to `collection_tr_id` to find the
    return waiting on it. Without the stamp the goods arrive against nothing.
    """
    from app.modules.logistics import transport as lgs_transport
    from app.modules.logistics.enums import TransportSource
    from app.modules.logistics.schemas import TRCreate, TRLineIn

    tr = await lgs_transport.create_tr(db, TRCreate(
        mode=LOGISTICS_MODE_RAISING_SHIPMENT,
        source_type=TransportSource.RETURN.value,
        source_id=None,                       # see the docstring — load-bearing
        source_no=seed["return_no"],
        from_warehouse_id=None,               # see the docstring — not a site of ours
        from_warehouse_name=seed["vendor_name"],
        to_location_name=seed["warehouse_name"],
        contact_person=seed["contact_person"],
        contact_phone=seed["contact_phone"],
        # `expected_delivery` IS DELIBERATELY LEFT NULL, for the same reason
        # `_raise_vendor_return_inbound` leaves it null on the receipt: the only date
        # anybody has stated about this trip is the supplier's GOODS READY date, and
        # that is the earliest the vehicle may collect — not when the load is due back
        # at our gate. Nobody can know that until the desk arranges the vehicle, which
        # is the press this draft exists to put in front of them. The ready date travels
        # in the remarks below, worded as what it actually is.
        remarks=(
            f"Purchase Return {seed['return_no']} — collect the replacement from "
            f"{seed['vendor_name']}."
            + (f" Collect from: {seed['pickup_address']}."
               if seed["pickup_address"] else "")
            + (f" Goods ready from {seed['ready_date']:%d %b %Y}."
               if seed["ready_date"] else "")
            + " The inbound receipt is raised when this leg is acknowledged."),
        lines=[TRLineIn(**line) for line in seed["lines"]],
    ), user)

    # The link back, without which the goods arrive against nothing — see the docstring.
    # A plain UPDATE rather than loading the row: `create_tr` has just committed and the
    # return instance the caller held is expired.
    await db.execute(
        update(m.PurchaseReturn)
        .where(m.PurchaseReturn.id == seed["return_id"])
        .values(collection_tr_id=tr.id, collection_tr_no=tr.tr_no))

    await write_audit(
        db, entity="pro_returns", entity_id=seed["return_id"],
        entity_no=seed["return_no"], action=AuditAction.UPDATE, actor=user,
        after={"collection_tr_no": tr.tr_no, "collection_tr_id": tr.id,
               "status": tr.status},
        summary=f"Purchase Return {seed['return_no']}: collection shipment {tr.tr_no} "
                f"raised in Logistics as a draft")
    await db.commit()
    logger.info("Purchase Return %s raised collection shipment %s (%s)",
                seed["return_no"], tr.tr_no, tr.status)


#: What a SUPPLIER may see of a purchase return: only one that has actually been sent
#: to them. A draft, a return waiting on our own approval and a rejected one are all
#: internal — the supplier is not a party to them and must never be shown one, exactly
#: as `_vendor_visible_po` refuses to show a vendor an unissued order. CANCELLED is out
#: too: a return cancelled before it went was never sent, and one cannot be cancelled
#: after (see the status guards at the top of `send_to_vendor`).
#
# WIDENED 2026-09-11, and this is load-bearing rather than cosmetic. A sent return no
# longer stops at SENT_TO_VENDOR: the decision desk answers it, picks how the material
# comes back, and the document walks on through the inbound rungs. Leaving those out
# would have the consignment VANISH off the supplier's own board the moment we approved
# it — the supplier is still holding the goods and is still a party to every one of
# those rungs. What they may DO with it is a separate question and deliberately
# unchanged: `VENDOR_ANSWERABLE_RETURN_STATUSES` is still only SENT_TO_VENDOR and
# DISPATCHED, so once our desk has taken the decision the portal's answer is closed and
# a supplier reply can no longer raise a second trip for one load.
# WIDENED AGAIN 2026-09-12, and load-bearing rather than cosmetic. The supplier is now
# the party who ANSWERS this document — they approve or reject it, choose refund or
# replacement, accept the collection, sign for the goods and dispatch the replacement —
# so every rung between the send and the close is a rung they are standing on. Leaving
# one out does not merely hide a row: it 404s the press that rung exists for, because
# `_vendor_return` scopes reads and writes through this same tuple.
#
# REJECTED is in it for the first time. A return the supplier themselves refused must
# stay readable to them — it is their own answer, and a document that vanishes the moment
# you answer it reads as the answer having failed. REJECTED is still unreachable by every
# write press, which guard on their own narrower rungs.
_VENDOR_VISIBLE_RETURN_STATUSES = (
    ReturnStatus.SENT_TO_VENDOR.value,
    ReturnStatus.DISPATCHED.value,
    ReturnStatus.VENDOR_APPROVED.value,
    ReturnStatus.REPLACEMENT_AGREED.value,
    ReturnStatus.AWAITING_VENDOR_VEHICLE.value,
    ReturnStatus.VENDOR_TRANSPORT_ACCEPTED.value,
    ReturnStatus.VEHICLE_REQUESTED.value,
    ReturnStatus.STOCK_PICKED_UP.value,
    ReturnStatus.VENDOR_RECEIVED.value,
    ReturnStatus.REPLACEMENT_DISPATCHED.value,
    ReturnStatus.IN_TRANSIT.value,
    ReturnStatus.RECEIVED_AT_WAREHOUSE.value,
    ReturnStatus.REFUNDED.value,
    ReturnStatus.REJECTED.value,
    ReturnStatus.COMPLETED.value,
)


def _vendor_owns_return_clause(vendor: Vendor | None, vendor_id: int):
    """Whose return this is, as one WHERE clause shared by the list and the detail.

    `vendor_id` — the bound link — is the whole of the answer for every return raised off
    a purchase, and it is the answer for a MANUAL return too now that
    `_match_manual_vendor` binds the typed company name at create, at edit and at send.

    THE SECOND ARM IS FOR THE ROWS THAT PREDATE THAT BINDING. Every manual return already
    in `pro_returns` was saved with a typed `vendor_name` and a NULL `vendor_id` — the
    screen never posted one — so those documents have no link to bind and never will
    without being reopened. Matching them on the typed name is what lets a supplier see a
    return that was sent to them last week, rather than only the ones raised from now on.

    NARROW ON PURPOSE. It reaches only a MANUAL return, only one with NO `vendor_id` at
    all, and only where the typed name IS this supplier's own name. A bound return is
    never re-matched, so the name can never pull in somebody else's document, and a
    return bound to vendor A can never surface for vendor B.
    """
    owned = [m.PurchaseReturn.vendor_id == vendor_id]
    folded = _fold_company(vendor.name if vendor else None)
    if folded:
        owned.append(and_(
            m.PurchaseReturn.is_manual.is_(True),
            m.PurchaseReturn.vendor_id.is_(None),
            _fold_company_sql(m.PurchaseReturn.vendor_name) == folded,
        ))
    return or_(*owned)


async def vendor_list_returns(db: AsyncSession, vendor_id: int, params: PageParams,
                              search: str | None = None,
                              status: str | None = None) -> dict:
    """The goods this supplier has been sent back. Never anyone else's, never a draft.

    LIVES IN THE WAREHOUSE MODULE, and is mounted on the supplier portal's own prefix
    from `router.supplier_router`. It reads `pro_returns`, which this module owns, and
    procurement — where the rest of the portal lives — sits EARLIER in the import chain
    and may not import warehouse (rule 5). Putting the query there would have inverted
    the chain; putting the route here costs nothing, because `get_current_vendor` is a
    `core` dependency any module may use, and the carrier portal in logistics already
    mounts its own routes under `/api/supplier` the same way.

    The vendor id comes from the token at the router, never from the request, so this
    can only ever answer the caller's own returns.
    """
    # Read for the ownership clause below, and for nothing else — a manual return raised
    # before the typed name was bound carries the name and no id. See
    # `_vendor_owns_return_clause`.
    vendor = await db.get(Vendor, vendor_id)
    stmt = (select(m.PurchaseReturn)
            .where(_vendor_owns_return_clause(vendor, vendor_id),
                   m.PurchaseReturn.status.in_(_VENDOR_VISIBLE_RETURN_STATUSES)))
    if search:
        like = f"%{search}%"
        # The numbers a supplier actually has written on their own paperwork.
        stmt = stmt.where(or_(m.PurchaseReturn.return_no.ilike(like),
                              m.PurchaseReturn.po_no.ilike(like),
                              m.PurchaseReturn.grn_no.ilike(like)))
    if status:
        # Narrowing only, and only WITHIN what this supplier may already read: an
        # unknown or internal status filters to nothing rather than widening scope.
        stmt = stmt.where(m.PurchaseReturn.status == status,
                          m.PurchaseReturn.status.in_(_VENDOR_VISIBLE_RETURN_STATUSES))
    stmt = stmt.order_by(m.PurchaseReturn.return_date.desc(),
                         m.PurchaseReturn.id.desc())
    page = await paginate(db, stmt, params)

    rows = page["items"]
    if not rows:
        return page

    # The consignment behind each one, in ONE query rather than per row. A manual
    # return raises none, so its logistics fields stay null and the portal says the
    # goods are on their way without inventing a lorry for them.
    legs = {
        leg.ref_id: leg
        for leg in (await db.execute(
            select(m.Dispatch).where(
                m.Dispatch.ref_type == "PURCHASE_RETURN",
                m.Dispatch.ref_id.in_([r.id for r in rows]),
                m.Dispatch.status != DispatchStatus.CANCELLED.value,
            )
        )).scalars()
    }
    for row in rows:
        _apply_vendor_return_leg(row, legs.get(row.id))
    return page


def _vendor_reason_label(reason: str | None) -> str | None:
    """A stored reason code as the supplier should read it, or whatever was stored.

    Falls back to the raw value rather than to null: a reason typed before the
    catalogue existed is still a reason, and blanking it would say the goods came back
    for no stated cause.
    """
    return dict(s.PURCHASE_RETURN_REASONS).get(reason or "", reason)


def _vendor_refund_label(row) -> str | None:
    """The refund set beside what was sent back, as one sentence.

    Worded HERE and not in the portal because the comparison is the whole point. A
    supplier crediting less than the consignment was worth is the normal case — freight
    deducted, a restocking charge kept back, a disputed line — and a screen that printed
    the refund on its own would leave the buyer subtracting two numbers by eye to find
    out whether a return had been settled short. Saying it in words means every screen
    that shows a refund says the same thing about it.

    Null unless there is a figure: a REPLACED or RETURNED answer settles in goods, and a
    legacy ACCEPTED row never captured an amount at all.
    """
    amount = row.vendor_refund_amount
    if amount is None:
        return None
    returned = _d(row.total_value)
    amount = _d(amount)
    if amount >= returned:
        return "the full value of the return"
    shortfall = returned - amount
    return f"of {returned:,.2f} returned — {shortfall:,.2f} less than the full value"


def _vendor_response_label(value: str | None) -> str | None:
    """The supplier's answer as a sentence, or None while they have not given one.

    THE ONE PLACE an answer becomes words, shared by the supplier's portal and by our
    own screens. Falls back to the stored value rather than to null for the same reason
    `_vendor_reason_label` does — a value nobody has worded yet must still show as
    SOMETHING — and stays null when there is no answer, which is every return raised
    before the portal could give one.
    """
    if not value:
        return None
    return dict(s.VENDOR_RETURN_RESPONSES).get(value, value)


def _apply_vendor_answer(row) -> None:
    """What the supplier said, worded for OUR screens, onto one internal return row.

    Shared by the register (`list_returns`) and the document (`_decorate_purchase_return`)
    so the two cannot word the same return differently — the failure this fixes was a
    screen saying nothing at all, and two screens saying different things is the same
    failure wearing a hat.

    `status_label` is wording over the STORED status, which is deliberately not touched:
    `vendor_response` is its own axis (see the enum's docstring), and a return the
    supplier has accepted is still, on our books, a return we have sent them. Null while
    unanswered, so a screen writes `status_label ?? status` and every pre-portal row
    renders exactly as it did.
    """
    # The INBOUND LEG's own wording wins where it says anything, and it can only say
    # anything on a rung the supplier's answer cannot reach: `vendor_return_stage_label`
    # is null outside `VENDOR_ANSWERABLE_RETURN_STATUSES` (SENT_TO_VENDOR / DISPATCHED)
    # and every rung `return_stage_label` words is past both. So the two never both
    # answer, and `or` is the order they are read in rather than a precedence rule —
    # written as a chain anyway, because "the newest thing that happened wins" is the
    # property that has to survive the next status being added to either map.
    row.status_label = (return_stage_label(row.status)
                        or vendor_return_stage_label(row.status, row.vendor_response))
    row.vendor_response_label = _vendor_response_label(row.vendor_response)
    row.vehicle_arrangement_label = RETURN_VEHICLE_ARRANGEMENT_LABELS.get(
        row.vehicle_arrangement or "")


def _apply_vendor_return_leg(row, leg) -> None:
    """Hang the reason wording and the consignment's facts onto one portal row.

    Shared by the supplier portal's LIST and its DETAIL so the two cannot drift — the
    detail is the same row with its lines attached, and a field enriched in one place
    only would have gone null the moment the supplier opened it.

    `leg` is None on a manual return, which raises no consignment at all. Every
    logistics field then stays null, and the portal says the goods are on their way
    without inventing a lorry for them.
    """
    row.reason_code = row.reason
    row.reason_label = _vendor_reason_label(row.reason)
    # The supplier's own answer, worded for them. Falls back to the stored value rather
    # than to null for the same reason `_vendor_reason_label` does, and stays null while
    # the return is unanswered — which is every row raised before 2026-09-11.
    row.vendor_response_label = _vendor_response_label(row.vendor_response)
    row.vendor_refund_label = _vendor_refund_label(row)
    # WHERE THE RETURN IS STANDING, as a sentence. The supplier now answers five of the
    # rungs themselves, so their copy has to say which one it is on — a portal showing
    # "REPLACEMENT_AGREED" is showing them our database. Worded by the same function our
    # own screens use, so the two sides cannot describe one document differently.
    row.status_label = (return_stage_label(row.status)
                        or vendor_return_stage_label(row.status, row.vendor_response))
    row.vehicle_arrangement_label = RETURN_VEHICLE_ARRANGEMENT_LABELS.get(
        row.vehicle_arrangement or "")
    modes = {v: label for v, label, _ in s.PURCHASE_RETURN_LOGISTICS_MODES}
    row.dispatch_no = leg.dispatch_no if leg else None
    row.transport_mode = leg.transport_mode if leg else None
    row.transport_mode_label = (
        modes.get(leg.transport_mode or "", leg.transport_mode) if leg else None)
    row.carrier_name = leg.carrier_name if leg else None
    row.vehicle_number = leg.vehicle_number if leg else None
    row.driver_name = leg.driver_name if leg else None
    row.lr_no = leg.lr_no if leg else None
    row.eway_bill_no = leg.eway_bill_no if leg else None
    row.total_packages = leg.total_packages if leg else None
    row.expected_delivery = leg.expected_delivery if leg else None
    row.acknowledged_by_name = leg.acknowledged_by_name if leg else None
    row.acknowledged_at = leg.acknowledged_at if leg else None
    # Detail-only, and harmless on a list row: `VendorReturnListRow` does not declare
    # these, so they are simply not serialised there.
    row.delivery_address = leg.delivery_address if leg else None
    row.contact_person = leg.contact_person if leg else None
    row.contact_phone = leg.contact_phone if leg else None
    row.total_weight_kg = leg.total_weight_kg if leg else None


async def _vendor_return(db: AsyncSession, vendor_id: int,
                         return_id: int) -> m.PurchaseReturn:
    """One return, scoped to the supplier asking for it, or a 404.

    THE ONE PLACE the portal's scoping rule is written, shared by the read and by both
    of the supplier's write actions. Extracted on 2026-09-11 when those writes landed:
    a second copy of this WHERE clause is how one endpoint quietly ends up able to
    answer another supplier's document.

    Scoped in the WHERE clause rather than by fetching and then checking, so a return
    belonging to somebody else and one that has not been sent are the SAME 404 —
    telling the caller which would confirm that a guessed return number exists.
    """
    # Scoped with the SAME ownership clause the list uses, for the same reason this
    # function exists at all: a manual return the list showed off its typed name would
    # otherwise 404 the moment the supplier clicked it.
    vendor = await db.get(Vendor, vendor_id)
    row = (await db.execute(
        select(m.PurchaseReturn)
        # The lines come with the header rather than in a query of their own: the
        # relationship is `delete-orphan`, so assigning a separately fetched list to
        # `row.items` would hand SQLAlchemy an orphan set to reconcile on the next
        # flush. Eager-loading it is read-only and already ordered by `line_no`.
        .options(selectinload(m.PurchaseReturn.items))
        .where(
            m.PurchaseReturn.id == return_id,
            _vendor_owns_return_clause(vendor, vendor_id),
            m.PurchaseReturn.status.in_(_VENDOR_VISIBLE_RETURN_STATUSES),
        )
    )).scalar_one_or_none()
    if row is None:
        raise NotFoundError(f"Return {return_id} not found")
    return row


async def vendor_get_return(db: AsyncSession, vendor_id: int, return_id: int):
    """One purchase return, with its lines, as the SUPPLIER sees it.

    The list could say a consignment existed but never what was in it, so a supplier
    could not check the carton against their own paperwork without telephoning the
    store. This is that document.

    SCOPED EXACTLY AS THE LIST IS, and deliberately in the same WHERE clause rather
    than by fetching and then checking: the vendor id comes from the token at the
    router, and `_VENDOR_VISIBLE_RETURN_STATUSES` keeps a draft, a return still in our
    own approval and a rejected one out of reach. A return belonging to somebody else
    and one that has not been sent are the SAME 404 — telling the caller which would
    confirm that a return number they guessed exists.
    """
    row = await _vendor_return(db, vendor_id, return_id)

    leg = (await db.execute(
        select(m.Dispatch).where(
            m.Dispatch.ref_type == "PURCHASE_RETURN",
            m.Dispatch.ref_id == row.id,
            m.Dispatch.status != DispatchStatus.CANCELLED.value,
        )
    )).scalars().first()
    _apply_vendor_return_leg(row, leg)

    for line in row.items:
        # The line's own reason where it has one, else the document's — a consignment
        # usually comes back for one cause and repeating it per line would be noise,
        # but a mixed one must not show blank cells against the odd line out.
        line.reason_label = _vendor_reason_label(line.reason) or row.reason_label

    # The supplier's own identity, for the acknowledgement receipt: a receipt has to
    # name both parties, and `warehouse_name` (ours) is already a column on the row.
    # Reused rather than re-read so a manual return's TYPED vendor arrives under the
    # same names as a sourced one's — see `_enrich_return_with_vendor`. Read-only here:
    # nothing on this path commits, which is the condition that function's docstring
    # warns about.
    await _enrich_return_with_vendor(db, row)
    await _apply_vendor_replacement_leg(db, row)
    await _apply_replacement_line_prefill(db, row)
    row.replacement_documents = await _replacement_documents(db, row.id)
    return row


#: The label each stored category is shown under, off the served meta rather than
#: written twice. A category with no entry (one retired later) falls back to its own
#: value instead of rendering blank.
_REPLACEMENT_DOC_LABELS = {str(d["value"]): str(d["label"])
                           for d in REPLACEMENT_DOCUMENT_META}


def replacement_document_types() -> tuple[dict, ...]:
    """The two mandatory replacement files, as the form should draw them.

    A plain read of `REPLACEMENT_DOCUMENT_META`. It exists so the router does not import
    the enum directly: the screen's fields and the dispatch guard then have exactly one
    source, and adding a third document is one edit in one file.
    """
    return REPLACEMENT_DOCUMENT_META


async def _replacement_documents(db: AsyncSession, return_id: int) -> list:
    """The replacement's paperwork on file, newest first, labelled for the screen.

    Reads `sys_attachments` filed under `RETURN_ATTACHMENT_ENTITY` and narrowed to the
    two replacement categories, so an unrelated file attached to the same return — a
    photograph of the damage that caused it, say — can never be mistaken for the
    invoice the dispatch is waiting on.
    """
    rows = await attachments.list_attachments(db, RETURN_ATTACHMENT_ENTITY, return_id)
    out = []
    for row in rows:
        category = (row.doc_category or "").upper()
        if category not in _REPLACEMENT_DOC_LABELS:
            continue
        out.append(s.ReplacementDocumentRead(
            id=row.id, doc_category=category,
            label=_REPLACEMENT_DOC_LABELS[category],
            file_name=row.file_name, file_size=row.file_size,
            mime_type=row.mime_type, uploaded_by_name=row.uploaded_by_name,
            created_at=row.created_at,
        ))
    return out


async def _assert_replacement_docs_editable(row) -> None:
    """The paperwork may only be changed while the dispatch is still to come.

    Once the replacement has gone the files are evidence of what left the supplier's
    dock, and the buyer's store has been told they exist. Swapping one afterwards would
    rewrite the record of a consignment already on the road.
    """
    if row.replacement_dispatched_at:
        raise ValidationError(
            f"The replacement for {row.return_no} was already dispatched on "
            f"{row.replacement_dispatched_at:%d %b %Y} — its paperwork can no longer be "
            "changed. Raise the discrepancy with the buyer instead.")
    if row.status not in RETURN_REPLACEMENT_DISPATCHABLE_STATUSES:
        _decision_guard(row, "the replacement's paperwork can only be attached once the "
                             "returned goods are on their way to you")


async def vendor_upload_replacement_document(db: AsyncSession, vendor_id: int,
                                             return_id: int, *, doc_category: str,
                                             upload):
    """The supplier attaching the loading photograph, or the replacement invoice.

    ONE FILE PER SLOT, and re-uploading REPLACES rather than adds. A supplier who picked
    the wrong file from their phone has to be able to correct it, and "the most recent
    one is the real one" is a rule the buyer's store would have to be told; two invoices
    against one consignment is an argument, not a record. The superseded row and its
    bytes go together, through the platform's own delete so the audit trail carries it.

    THE PHOTO SLOT TAKES IMAGES ONLY (`REPLACEMENT_PHOTO_SUFFIXES`). The platform
    whitelist is wider on purpose — a PDF is a perfectly good attachment in general —
    but it is not a photograph of a loaded pallet, and accepting one here would leave
    the requirement satisfiable by the thing it exists to stop.

    Everything else about the upload is the platform's: the extension and leading-byte
    check, the 20 MB cap enforced while the bytes stream, the generated storage name and
    the audit row. This function adds the scoping and the slot rules and nothing more.
    """
    category = (doc_category or "").upper()
    if category not in _REPLACEMENT_DOC_LABELS:
        raise ValidationError(
            f"{doc_category!r} is not a replacement document. Attach the "
            + " or the ".join(str(d["noun"]) for d in REPLACEMENT_DOCUMENT_META) + ".")

    row = await _vendor_return(db, vendor_id, return_id)
    await _assert_replacement_docs_editable(row)

    if category == ReplacementDocument.PHOTO.value:
        suffix = Path(upload.filename or "").suffix.lower()
        if suffix not in REPLACEMENT_PHOTO_SUFFIXES:
            raise ValidationError(
                f"{suffix or 'That file'} is not an image. Photograph the goods, or "
                "attach a JPG or PNG — the invoice goes in the slot below.")

    # The previous file for THIS slot only, and read before the new one is written so a
    # failed upload leaves the old one in place rather than the slot empty.
    existing = [a for a in await attachments.list_attachments(
        db, RETURN_ATTACHMENT_ENTITY, row.id)
        if (a.doc_category or "").upper() == category]

    saved = await attachments.add_attachment(
        db, entity_type=RETURN_ATTACHMENT_ENTITY, entity_id=row.id,
        upload=upload, doc_category=category, user=None)

    for old in existing:
        await attachments.delete_attachment(
            db, old.id, None, entity_type=RETURN_ATTACHMENT_ENTITY, entity_id=row.id)

    logger.info("Purchase Return %s: %s attached by vendor %s (%s)",
                row.return_no, category, vendor_id, saved.file_name)
    return await vendor_get_return(db, vendor_id, return_id)


async def vendor_delete_replacement_document(db: AsyncSession, vendor_id: int,
                                             return_id: int, attachment_id: int):
    """Remove one of the two files before the replacement goes.

    Scoped twice over: the return must be this supplier's, and the attachment must hang
    on that return — `require_attachment` inside the platform delete proves the second,
    which is what stops an id from another document being passed in here.
    """
    row = await _vendor_return(db, vendor_id, return_id)
    await _assert_replacement_docs_editable(row)
    await attachments.delete_attachment(
        db, attachment_id, None,
        entity_type=RETURN_ATTACHMENT_ENTITY, entity_id=row.id)
    return await vendor_get_return(db, vendor_id, return_id)


async def vendor_replacement_document_file(db: AsyncSession, vendor_id: int,
                                           return_id: int, attachment_id: int):
    """The stored bytes of one of them, for the supplier to check what they sent.

    The return is scoped BEFORE the attachment is opened, so an id belonging to another
    supplier's document never reaches the filesystem.
    """
    row = await _vendor_return(db, vendor_id, return_id)
    await attachments.require_attachment(
        db, attachment_id, entity_type=RETURN_ATTACHMENT_ENTITY, entity_id=row.id)
    return await attachments.attachment_file(db, attachment_id)


async def _apply_replacement_line_prefill(db: AsyncSession, row) -> None:
    """What a replacement of each line must state, and what we originally received.

    DETAIL ONLY, and only while the return is unanswered — this exists to fill in the
    form on the Accept screen, and a queue row has no form on it. Once the supplier has
    answered there is nothing left to prefill and the queries are skipped.

    TWO DIFFERENT FACTS, from two different places, and they must not be confused:

    * `needs_batch` / `needs_expiry` are the ITEM MASTER's, and they are the same two
      flags `_apply_receipt_lines` enforces when the store submits the GRN. Served so the
      portal asks for exactly what the receiving desk will insist on — the supplier finds
      out before they press rather than from a refusal afterwards.
    * `original_*` are the GRN LINE's — the batch and dates of the goods we are sending
      back. A PREFILL, never a binding: the replacement is different physical stock and
      the supplier is expected to correct them. They are handed over because on the
      ordinary one-batch replacement correcting a prefilled date is one keystroke and
      typing it from a delivery note is a phone call, and because seeing the batch they
      shipped us is half of what a supplier needs to investigate the complaint.

    A MANUAL return has no GRN line and frequently no item master row either, so every
    field here stays at its default and the portal simply asks for the lot in free text.
    """
    if row.vendor_response:
        return
    grn_line_ids = {line.grn_item_id for line in row.items if line.grn_item_id}
    grn_lines = {}
    if grn_line_ids:
        grn_lines = {r.id: r for r in (await db.execute(
            select(m.ReceiptItem).where(m.ReceiptItem.id.in_(grn_line_ids)))
        ).scalars()}
    for line in row.items:
        if line.item_id:
            item = await db.get(Item, line.item_id)
            if item is not None:
                line.needs_batch = bool(item.is_batch_tracked)
                line.needs_expiry = bool(item.has_expiry)
                # One flag, two words for it — the same choice `_apply_receipt_lines`
                # makes when it refuses the line for want of this date.
                line.life_label = "Warranty end" if item.is_asset else "Expiry"
        source = grn_lines.get(line.grn_item_id)
        if source is not None:
            # The return line's own `batch_no` is the same batch, and is preferred where
            # the GRN line has none: a return raised against a specific batch names it,
            # and falling back the other way would blank a field the reader can see on
            # the document above.
            line.original_batch_no = source.batch_no or line.batch_no
            line.original_mfg_date = source.mfg_date
            line.original_expiry_date = source.expiry_date
        else:
            line.original_batch_no = line.batch_no


async def _apply_vendor_replacement_leg(db: AsyncSession, row) -> None:
    """How the replacement is travelling, read back off the receipt it raised.

    Stored on `inb_receipts` and READ here rather than copied onto the return, so the
    supplier's page and the store's receiving screen cannot show two different dates for
    one lorry. Costs one query by primary key, and only on a detail — a queue row says
    "replacement being sent" and that is the whole answer at that level.

    Silent when there is no follow-up receipt (a refund, a legacy ACCEPTED row, an
    unanswered return) and when there is one but it carries no date — a RETURNED
    consignment raises a receipt too, and that lorry is ours, not theirs.
    """
    row.replacement_expected_date = None
    row.replacement_label = None
    row.replacement_mode = None
    row.replacement_ready_date = None
    row.replacement_pickup_address = None
    if row.vendor_response != VendorReturnResponse.REPLACED.value:
        return

    # A COLLECTION HAS NO RECEIPT YET, and is still the thing the reader most wants
    # described (2026-09-11). The answer raises the trip and the receipt follows when
    # our vehicle gets back, so between those two moments the facts live on the return
    # itself — and reading them only off the receipt left the screen silent for exactly
    # the stretch when somebody is chasing the collection.
    if row.collection_tr_id and not row.vendor_followup_receipt_id:
        row.replacement_mode = s.INBOUND_MODES_COLLECTED[0]
        row.replacement_ready_date = row.collection_ready_date
        row.replacement_pickup_address = row.collection_pickup_address
        parts = ["we will collect"]
        if row.collection_ready_date:
            parts.append(f"ready from {row.collection_ready_date:%d %b %Y}")
        if row.collection_pickup_address:
            parts.append(f"from {row.collection_pickup_address}")
        if row.collection_tr_no:
            parts.append(f"on {row.collection_tr_no}")
        row.replacement_label = " · ".join(parts)
        return

    if not row.vendor_followup_receipt_id:
        return

    receipt = await db.get(m.Receipt, row.vendor_followup_receipt_id)
    if receipt is None:
        # The store cancelled or deleted it. The return still records that a replacement
        # was promised; it simply cannot say how it travels any more.
        return

    row.replacement_expected_date = receipt.expected_delivery
    row.replacement_mode = receipt.inbound_transport_mode
    row.replacement_ready_date = receipt.goods_ready_date
    row.replacement_pickup_address = receipt.pickup_address

    # Two legs, two sentences, because the supplier is owed a different assurance by
    # each: a delivery tells them what we are expecting and when, and a collection tells
    # them we accepted the job of fetching it — which is the half a supplier asking us to
    # collect actually wants confirmed.
    parts = []
    if receipt.inbound_transport_mode in s.INBOUND_MODES_COLLECTED:
        parts.append("we will collect")
        if receipt.goods_ready_date:
            parts.append(f"ready from {receipt.goods_ready_date:%d %b %Y}")
        if receipt.pickup_address:
            parts.append(f"from {receipt.pickup_address}")
    else:
        if receipt.expected_delivery:
            parts.append(f"expected {receipt.expected_delivery:%d %b %Y}")
        if receipt.transporter_name:
            parts.append(receipt.transporter_name)
        if receipt.vehicle_no:
            parts.append(f"vehicle {receipt.vehicle_no}")
        if receipt.lr_no:
            parts.append(f"LR {receipt.lr_no}")
    row.replacement_label = " · ".join(parts) or None


async def vendor_confirm_return_receipt(db: AsyncSession, vendor_id: int,
                                        return_id: int,
                                        data: "s.VendorReturnReceiptIn"):
    """The supplier signing for the returned goods at their own dock.

    THE RUNG THIS MOVES CHANGED on 2026-09-12. It used to be a record of the handover and
    nothing else — it moved no status, because under the old flow the goods went out with
    the paperwork and the supplier's answer was a separate, ungated act. Now the signature
    IS a rung: the return has travelled to them (on their vehicle or ours), and their
    signature is what ends our liability for the stock and opens the replacement dispatch.

    Still a record of the HANDOVER and still moves no stock. What the supplier sends back
    is `vendor_dispatch_replacement`, a separate press, because signing for a carton and
    having packed its replacement are different statements days apart.

    Reachable from BOTH transport branches — their own vehicle arriving home, or ours
    delivering — which is why `RETURN_VENDOR_RECEIVABLE_STATUSES` holds two rungs.

    Signed ONCE. A second signature is refused rather than ignored: the first carries a
    timestamp somebody may already have quoted, and silently overwriting it would destroy
    the only evidence of when the goods actually landed.
    """
    row = await _vendor_return(db, vendor_id, return_id)
    if row.vendor_receipt_confirmed_at is not None:
        raise ValidationError(
            f"{row.return_no} was already signed for on "
            f"{row.vendor_receipt_confirmed_at:%d %b %Y at %H:%M}"
            f"{f' by {row.vendor_receipt_by_name}' if row.vendor_receipt_by_name else ''}.")
    if row.status not in RETURN_VENDOR_RECEIVABLE_STATUSES:
        _decision_guard(row, "goods can only be signed for once they are on their way to "
                             "you")

    before = row.status
    row.vendor_receipt_confirmed_at = utcnow()
    row.vendor_receipt_by_name = data.received_by_name.strip()
    row.vendor_receipt_vehicle_no = (data.vehicle_number or "").strip() or None
    row.vendor_receipt_remarks = (data.remarks or "").strip() or None
    row.status = ReturnStatus.VENDOR_RECEIVED.value

    await write_audit(
        db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
        action=AuditAction.UPDATE, actor=None,
        before={"status": before},
        summary=(f"Purchase Return {row.return_no}: "
                 f"{row.vendor_name or 'the vendor'} signed for the returned goods"
                 + (f" — received by {row.vendor_receipt_by_name}"
                    if row.vendor_receipt_by_name else "")),
        after={
            "status": row.status,
            "vendor_receipt_by_name": row.vendor_receipt_by_name,
            "vendor_receipt_vehicle_no": row.vendor_receipt_vehicle_no,
            "vendor_receipt_remarks": row.vendor_receipt_remarks,
            "acting_vendor_id": vendor_id,
        })
    await db.commit()
    logger.info("Purchase Return %s signed for by the vendor", row.return_no)
    return await vendor_get_return(db, vendor_id, return_id)


def _dispatch_as_answer(data: "s.ReplacementDispatchIn") -> SimpleNamespace:
    """The dispatch note in the shape `_raise_vendor_return_inbound` already reads.

    An ADAPTER, not a second copy of the receipt builder. That function has read
    `replacement_*` off the supplier's answer since the day it was written, and it is
    long, careful and correct — rewriting it to take two request shapes would be two
    chances to get a batch number onto the wrong line. Mapping the field names here costs
    eight lines and leaves it untouched.

    The mode is always SUPPLIER_DELIVERS. On this rung the vendor HAS dispatched — the
    goods are on a vehicle they chose — so there is nothing to collect and the two
    collection fields are unset. That is also why `expected_date` is a real promise of
    arrival here rather than the ready date a collection would carry.
    """
    return SimpleNamespace(
        replacement_mode=s.INBOUND_MODES_ARRIVING[0],
        replacement_expected_date=data.expected_date,
        replacement_transporter_name=(data.transporter_name or "").strip() or None,
        replacement_vehicle_no=(data.vehicle_no or "").strip() or None,
        replacement_lr_no=(data.lr_no or "").strip() or None,
        replacement_pickup_address=None,
        replacement_ready_date=None,
        replacement_lines=data.lines,
    )


async def vendor_dispatch_replacement(db: AsyncSession, vendor_id: int, return_id: int,
                                      data: "s.ReplacementDispatchIn"):
    """THE REPLACEMENT DISPATCH NOTE — the vendor has put replacement goods on a vehicle.

    The last thing the vendor does, and the document the store receives against. It
    carries what the business requires a dispatch note to carry: the items and quantities
    off this return, the batch, manufacturing date and expiry of the goods ACTUALLY being
    sent, the dispatch date, the purchase return number and the GRN/PO references — all of
    which are either on the return already or stated here.

    THE BATCH IS NOT THIS RETURN'S BATCH, and that is the whole reason the per-line
    columns exist. `PurchaseReturnItem.batch_no` is the lot of the FAULTY goods travelling
    the other way: different physical stock, a different expiry, and inheriting it would
    prefill the store's GRN with a wrong lot number. Only the vendor packing the carton
    knows the replacement's, so they are asked here, and refused if an item the master
    says is batch- or expiry-tracked arrives without one — the same rule
    `_apply_receipt_lines` will apply when the store books it in, applied early enough
    that somebody can still answer it.

    IT RAISES THE INBOUND RECEIPT, and raises it HERE rather than when the replacement was
    promised. Until the goods are on a vehicle the warehouse has nothing to do: no lorry
    has gone, no date exists, and a dateless draft receipt sitting in their queue is a
    document pretending to be work.

    REUSES AN EXISTING RECEIPT where one is already there. Returns answered under the old
    flow had their receipt raised at answer time and carried into this one by the
    migration; raising a second would have the store expecting two lorries for one
    replacement.

    IT CARRIES THE REPLACEMENT'S PAPERWORK (2026-09-16) — a picture of the goods as they
    were loaded, which is REQUIRED, and the supplier's invoice or bill, which is not.
    Both are `sys_attachments` rows filed against this return; which of them the dispatch
    waits for is `REQUIRED_REPLACEMENT_DOCUMENTS` and nothing else, and it is enforced
    here rather than only hidden behind a disabled button. See `ReplacementDocument` for
    why the picture is the half that cannot wait.

    IT ALSO SIGNS FOR THE RETURNED GOODS (2026-09-16). The vendor's separate "sign for the
    goods" press is gone from the portal, and this one absorbed it: dispatching a
    replacement is itself the statement that the faulty stock arrived, so the rung it used
    to gate is now reachable directly and this function stamps the receipt on the way
    through. `vendor_confirm_return_receipt` is still served and still moves the same
    status — an integration calling it keeps working, and a return signed that way arrives
    here already stamped.

    ANSWERED ONCE, by `RETURN_REPLACEMENT_DISPATCHABLE_STATUSES`.
    """
    row = await _vendor_return(db, vendor_id, return_id)
    if row.status not in RETURN_REPLACEMENT_DISPATCHABLE_STATUSES:
        if row.replacement_dispatched_at:
            raise ValidationError(
                f"The replacement for {row.return_no} was already dispatched on "
                f"{row.replacement_dispatched_at:%d %b %Y}"
                f"{f' ({row.replacement_dispatch_no})' if row.replacement_dispatch_no else ''}"
                f" — it cannot be dispatched twice.")
        _decision_guard(row, "a replacement can only be dispatched once the returned goods "
                             "are on their way to you")

    # THE REQUIRED FILES, REFUSED HERE AND NOT ONLY ON THE SCREEN (2026-09-16). The
    # portal disables its own press until they are uploaded; this is the check that means
    # it. A requirement enforced only in the browser is a requirement the next client — a
    # retry, a script, a second tab left open from before the files were swapped — does
    # not have.
    #
    # Reads `REQUIRED_REPLACEMENT_DOCUMENTS`, so a slot the business later makes optional
    # (as the invoice became) stops being demanded here with no edit to this function.
    #
    # Checked BEFORE anything is written, so a dispatch refused for missing paperwork
    # leaves the return exactly where it stood rather than half-stamped.
    on_file = {(d.doc_category or "").upper()
               for d in await _replacement_documents(db, row.id)}
    missing = [str(meta["noun"]) for meta in REPLACEMENT_DOCUMENT_META
               if str(meta["value"]) in REQUIRED_REPLACEMENT_DOCUMENTS
               and str(meta["value"]) not in on_file]
    if missing:
        raise ValidationError(
            f"{row.return_no} cannot be dispatched yet — attach the "
            + " and the ".join(missing) + " first.")

    # Refused NOW if it could never raise a receipt, and the cartons checked NOW against
    # the item master — finding either out after the lorry has left would be too late,
    # with the vendor long gone from the screen.
    _assert_inbound_raisable(row)
    stated = await _validate_replacement_cartons(db, row, data.lines)
    for line in row.items:
        answer = stated.get(line.line_no)
        if answer is not None:
            line.replacement_batch_no = answer.batch_no
            line.replacement_mfg_date = answer.mfg_date
            line.replacement_expiry_date = answer.expiry_date

    before = row.status
    now = utcnow()

    # THE SIGNATURE, where nobody has given one. Dispatching the replacement is the
    # statement that the faulty goods arrived, so the "Vendor received" leg of the buyer's
    # tracker is stamped from here rather than sitting on "waiting on the vendor to sign"
    # forever behind a press that no longer exists.
    #
    # A RETURN ALREADY SIGNED KEEPS ITS OWN STAMP. Rows answered under the old two-press
    # flow carry a timestamp and a name from the day the goods actually landed, and the
    # dispatch can be days later — overwriting it would move the end of the buyer's
    # liability to a date nothing happened on and destroy the only record of the real one.
    signed_here = row.vendor_receipt_confirmed_at is None
    if signed_here:
        row.vendor_receipt_confirmed_at = now
        # Said out loud rather than left to read as a dock signature that was never given.
        row.vendor_receipt_remarks = (row.vendor_receipt_remarks
                                      or "Confirmed by the replacement dispatch note")

    row.replacement_dispatched_at = now
    row.replacement_dispatch_no = (data.dispatch_no or "").strip() or None
    row.replacement_dispatch_date = data.dispatch_date
    row.replacement_expected_date = data.expected_date
    row.replacement_transporter_name = (data.transporter_name or "").strip() or None
    row.replacement_vehicle_no = (data.vehicle_no or "").strip() or None
    row.replacement_lr_no = (data.lr_no or "").strip() or None
    row.replacement_remarks = (data.remarks or "").strip() or None
    row.status = ReturnStatus.REPLACEMENT_DISPATCHED.value

    # The document the store will book the replacement in against — see the docstring for
    # why it is raised at this moment and why an existing one is reused.
    if not row.vendor_followup_receipt_id:
        receipt = await _raise_vendor_return_inbound(db, row, _dispatch_as_answer(data))
        row.vendor_followup_receipt_id = receipt.id
        row.vendor_followup_receipt_no = receipt.grn_no
    else:
        logger.info("Purchase Return %s already has inbound receipt %s — not raising a "
                    "second one for the replacement",
                    row.return_no, row.vendor_followup_receipt_no)

    await write_audit(
        db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
        action=AuditAction.UPDATE, actor=None,
        before={"status": before},
        after={
            "status": row.status,
            "replacement_dispatch_no": row.replacement_dispatch_no,
            "replacement_dispatch_date": (str(row.replacement_dispatch_date)
                                          if row.replacement_dispatch_date else None),
            "replacement_expected_date": (str(row.replacement_expected_date)
                                          if row.replacement_expected_date else None),
            "replacement_transporter_name": row.replacement_transporter_name,
            "replacement_vehicle_no": row.replacement_vehicle_no,
            "replacement_lr_no": row.replacement_lr_no,
            "vendor_followup_receipt_no": row.vendor_followup_receipt_no,
            # WHAT THEY SAID IS IN THE CARTON, on the trail as well as on the lines: the
            # receipt is a draft the store edits as the goods turn up, so the batch and
            # expiry the VENDOR stated would otherwise be overwritten with no record that
            # it had ever been different — and on a batch dispute that record is the whole
            # argument.
            "replacement_lines": [
                {"line_no": answer.line_no, "batch_no": answer.batch_no,
                 "mfg_date": str(answer.mfg_date) if answer.mfg_date else None,
                 "expiry_date": str(answer.expiry_date) if answer.expiry_date else None}
                for answer in data.lines
            ] or None,
            "remarks": row.replacement_remarks,
            # Only when THIS press was the signature. On a return signed separately the
            # trail already carries that act as its own audit row, and repeating it here
            # would read as a second signing.
            "vendor_receipt_confirmed_at": (str(row.vendor_receipt_confirmed_at)
                                            if signed_here else None),
            # WHICH FILES THE DISPATCH WENT OUT ON. The rows carry their own upload
            # audit, but only this says which ones were on file at the moment the
            # consignment was released — the question asked months later when a
            # short delivery is being argued.
            "replacement_documents": sorted(on_file) or None,
            "acting_vendor_id": vendor_id,
        },
        summary=(f"Purchase Return {row.return_no}: replacement dispatched by "
                 f"{row.vendor_name or 'the vendor'}"
                 + (" (receipt of the returned goods confirmed by the same note)"
                    if signed_here else "")
                 + (f" ({row.replacement_dispatch_no})"
                    if row.replacement_dispatch_no else "")
                 + (f", expected {row.replacement_expected_date:%d %b %Y}"
                    if row.replacement_expected_date else "")))
    await db.commit()
    logger.info("Purchase Return %s: replacement dispatched, receipt %s",
                row.return_no, row.vendor_followup_receipt_no)
    return await vendor_get_return(db, vendor_id, return_id)


async def vendor_respond_to_return(db: AsyncSession, vendor_id: int, return_id: int,
                                   data: "s.VendorReturnResponseIn"):
    """The supplier's decision about the goods: refund, replace, or send them back.

    RETIRED 2026-09-12 — no route reaches this any more. It answered THREE questions in
    one press (do you accept, what do we get, and how does the replacement travel) on a
    return whose goods had already gone out with the paperwork. Those are now four
    separate presses on the rungs the business actually works them:
    `vendor_decide_return`, `vendor_settle_return`, `vendor_accept_transport` /
    `vendor_record_pickup`, and `vendor_dispatch_replacement`.

    Kept rather than deleted because `_raise_collection_shipment` and `_collection_arrived`
    still settle the collection legs it raised, and a reader tracing a live
    `collection_tr_id` back to the press that created it needs to find it.

    ANSWERED ONCE, exactly as `vendor_respond_to_po` is and for the same reason: a
    supplier who has answered and wants to change it is a conversation with the buyer,
    not a button. Re-pressing is refused rather than ignored, because the second press
    would otherwise raise a SECOND inbound receipt against the same consignment and the
    store would be expecting two lorries.

    RETURNED and REPLACED both mean goods are travelling back to us, so each raises a
    DRAFT inbound receipt (`_raise_vendor_return_inbound`). REFUNDED settles in money and
    raises nothing — the consignment is finished where it stands and the figure is the
    only thing left of it.

    THE REFUND IS CAPPED AT WHAT WAS SENT BACK, and the cap is checked HERE rather than
    in the schema because only this function has the row. `total_value` is ours — it is
    what we valued the consignment at when we raised it — and a supplier cannot credit
    more than that: the overage would be a payment against nothing, and it would arrive
    through a route where the counterparty controls the number. The schema has already
    refused zero, a negative, an amount on a non-refund answer and a refund with no
    amount, so the only thing left to check is the one thing it could not see.
    """
    row = await _vendor_return(db, vendor_id, return_id)
    if row.vendor_response:
        answered = dict(s.VENDOR_RETURN_RESPONSES).get(row.vendor_response,
                                                       row.vendor_response)
        raise ValidationError(
            f'{row.return_no} was already answered "{answered}"'
            f"{f' on {row.vendor_response_at:%d %b %Y}' if row.vendor_response_at else ''}. "
            "Ask the buyer to raise a fresh document if something needs to change.")

    refund = data.refund_amount
    if refund is not None and _d(refund) > _d(row.total_value):
        raise ValidationError(
            f"A refund of {_d(refund):,.2f} is more than the {_d(row.total_value):,.2f} "
            f"of goods on {row.return_no}. Credit that value or less.")

    row.vendor_response = data.response.value
    row.vendor_response_at = utcnow()
    row.vendor_response_note = (data.remarks or "").strip() or None
    row.vendor_refund_amount = refund

    # The document the answer produces, where it produces one. Created BEFORE the
    # commit so the receipt and the answer that caused it land in one transaction —
    # a rollback must not leave a return claiming a receipt that was never raised.
    # WHICH DOCUMENT THIS ANSWER RAISES, and it is one or the other (2026-09-11).
    #
    # A COLLECTION — the supplier is replacing the goods and has asked us to come and
    # fetch them — raises the TRIP, and nothing in the warehouse at all. There is
    # nothing for the store to do yet: no vehicle has gone, no date exists, and nobody
    # knows when the goods will be in the building. A draft receipt sitting in their
    # queue for goods nobody has collected is a document pretending to be work.
    #
    # Everything else — a SUPPLIER_DELIVERS replacement, a RETURNED consignment — raises
    # the inbound receipt exactly as it always has, the instant the supplier answers.
    # Their goods are already on a vehicle heading towards us; there is no trip to
    # arrange and nothing to wait for. That path is byte-for-byte unchanged.
    collecting = (row.vendor_response == VendorReturnResponse.REPLACED.value
                  and data.replacement_mode in s.INBOUND_MODES_COLLECTED)

    receipt = None
    leg_seed = None
    if collecting:
        # Refused NOW if it could never raise a receipt, and the supplier's cartons
        # checked NOW against the item master — the receipt is deferred, the questions
        # are not. Finding either out after our vehicle has driven there and back would
        # be finding out far too late, with the supplier long gone from the screen.
        _assert_inbound_raisable(row)
        stated = await _validate_replacement_cartons(db, row, data.replacement_lines)
        # What the supplier said, kept until there is a receipt to write it onto.
        row.collection_pickup_address = data.replacement_pickup_address
        row.collection_ready_date = data.replacement_ready_date
        for line in row.items:
            answer = stated.get(line.line_no)
            line.replacement_batch_no = answer.batch_no if answer else None
            line.replacement_mfg_date = answer.mfg_date if answer else None
            line.replacement_expiry_date = answer.expiry_date if answer else None
        # Read while these instances are still live: the commit below expires every one
        # of them, and `create_tr` cannot run before it.
        collect_from = await db.get(Vendor, row.vendor_id) if row.vendor_id else None
        leg_seed = _collection_shipment_seed(row, collect_from)
    elif row.vendor_response in VENDOR_RETURN_INBOUND_RESPONSES:
        receipt = await _raise_vendor_return_inbound(db, row, data)
        row.vendor_followup_receipt_id = receipt.id
        row.vendor_followup_receipt_no = receipt.grn_no

    await write_audit(
        db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
        action=AuditAction.UPDATE, actor=None,
        summary=f"Supplier answered {row.return_no}: {row.vendor_response}",
        after={
            "vendor_response": row.vendor_response,
            "vendor_response_note": row.vendor_response_note,
            # str(), not float(): this is the money figure the buyer will reconcile a
            # credit note against, and the audit row must not be the place a decimal
            # turns into a binary approximation of itself.
            "vendor_refund_amount": (str(row.vendor_refund_amount)
                                     if row.vendor_refund_amount is not None else None),
            "vendor_followup_receipt_no": row.vendor_followup_receipt_no,
            # The replacement's promised arrival, recorded on the TRAIL even though it
            # is stored on the receipt: the receipt is a draft the store will edit as the
            # goods actually turn up, so what the supplier originally promised would
            # otherwise be overwritten with no record that it had ever been different.
            "replacement_mode": data.replacement_mode,
            "replacement_expected_date": (str(data.replacement_expected_date)
                                          if data.replacement_expected_date else None),
            "replacement_transporter_name": data.replacement_transporter_name,
            "replacement_vehicle_no": data.replacement_vehicle_no,
            "replacement_lr_no": data.replacement_lr_no,
            # A collection is the supplier asking US to do the moving, so what they asked
            # for has to survive on the trail even after the store edits the draft.
            "replacement_ready_date": (str(data.replacement_ready_date)
                                       if data.replacement_ready_date else None),
            "replacement_pickup_address": data.replacement_pickup_address,
            # WHAT THEY SAID IS IN THE CARTON, on the trail for the same reason the
            # travel facts are: the receipt is a draft the store will edit as the goods
            # actually turn up, so the batch and expiry the SUPPLIER stated would
            # otherwise be overwritten with no record that it had ever been different —
            # and on a batch dispute that record is the whole argument.
            "replacement_lines": [
                {"line_no": answer.line_no,
                 "batch_no": answer.batch_no,
                 "mfg_date": str(answer.mfg_date) if answer.mfg_date else None,
                 "expiry_date": str(answer.expiry_date) if answer.expiry_date else None}
                for answer in data.replacement_lines
            ] or None,
            "acting_vendor_id": vendor_id,
        })
    await db.commit()

    # The collection leg, dropped on the Logistics Dispatch board as a DRAFT — the same
    # board an outward Own Vehicle return already lands on, so nothing is created by
    # hand there. Swallowed on failure ON PURPOSE: the answer above has committed, it
    # is final and the inbound receipt exists, and none of that may be undone because a
    # shipment could not be raised. See `_raise_collection_shipment`.
    #
    # `user` is None here and correctly so — this is the SUPPLIER's press on their own
    # portal, and there is no employee behind it to attribute the leg to.
    if leg_seed is not None:
        try:
            await _raise_collection_shipment(db, leg_seed, None)
        except Exception:
            logger.exception(
                "Purchase Return %s was answered, but its collection shipment could "
                "not be raised in Logistics", leg_seed["return_no"])
            await db.rollback()

    return await vendor_get_return(db, vendor_id, return_id)


def _assert_inbound_raisable(row: m.PurchaseReturn) -> None:
    """Can an inbound receipt be raised against this return at all?

    Split out of `_raise_vendor_return_inbound` (2026-09-11) because a COLLECTION no
    longer raises its receipt at answer time and still has to be refused at answer time
    if it could never raise one. Finding out at acknowledgement — after our vehicle has
    driven to the supplier and back — would be finding out far too late.
    """
    if not row.warehouse_id:
        raise ValidationError(
            f"{row.return_no} names no warehouse, so there is nowhere to send the "
            "goods back to. Ask the buyer to complete the return first.")
    unnamed = [line.line_no for line in row.items if not line.item_id]
    if unnamed:
        raise ValidationError(
            f"Line{'s' if len(unnamed) > 1 else ''} "
            f"{', '.join(str(n) for n in unnamed)} of {row.return_no} "
            f"name{'' if len(unnamed) > 1 else 's'} an item that is not in the item "
            "master, so no inbound receipt can be raised against it. Contact the buyer.")


async def _validate_replacement_cartons(db: AsyncSession, row: m.PurchaseReturn,
                                        replacement_lines) -> dict:
    """What the supplier says is in each carton, checked against the item master.

    Split out for the same reason `_assert_inbound_raisable` is: on a collection the
    receipt these answers are written onto is not raised until our vehicle brings the
    goods back, and the checks must still happen in the press that makes the promise —
    while the only person who can read a lot number off a carton in their own warehouse
    is still on the screen.

    The two rules are exactly the two `_apply_receipt_lines` will apply when the store
    submits the GRN. Applying them here is what stops a receipt being raised that can be
    opened and never finished.

    Returns the supplier's answers keyed on `line_no`, for whichever caller needs them.
    """
    stated = {answer.line_no: answer for answer in replacement_lines}
    # A number that is on no line of this return is refused rather than ignored: it means
    # the two sides disagree about what is coming back, and the batch it carries would
    # otherwise be dropped without a word.
    unknown = sorted(set(stated) - {line.line_no for line in row.items})
    if unknown:
        raise ValidationError(
            f"{row.return_no} has no line "
            f"{', '.join(str(n) for n in unknown)}, so there is nothing to send a "
            "replacement for against it.")

    for line in row.items:
        answer = stated.get(line.line_no)
        item = await _item_snapshot(db, line.item_id)
        if item.is_batch_tracked and not ((answer.batch_no if answer else "") or "").strip():
            raise ValidationError(
                f"Line {line.line_no}: {item.code} is batch tracked — give the "
                "batch number of the replacement goods you are sending.")
        if item.has_expiry and (answer.expiry_date if answer else None) is None:
            what = "warranty end date" if item.is_asset else "expiry date"
            raise ValidationError(
                f"Line {line.line_no}: {item.code} needs a {what} — give it for the "
                "replacement goods you are sending.")
    return stated


async def _raise_vendor_return_inbound(db: AsyncSession, row: m.PurchaseReturn,
                                       data: "s.VendorReturnResponseIn") -> m.Receipt:
    """The DRAFT inbound receipt for goods the supplier is sending back to us.

    Both answers that produce one produce the SAME shape of document — an expected
    delivery at the warehouse that sent the return — and differ only in the sentence on
    it, in whether the supplier told us how it travels, and in whose batch is on the
    line. `ReceiptType.RETURN` already existed for exactly this.

    HOW IT TRAVELS, on a REPLACEMENT (2026-09-11). The receipt used to be raised with no
    expected date, no vehicle and no LR, so the store knew what to expect and never when
    — the storekeeper found out when the lorry appeared at the gate. The supplier states
    those facts in the same press that promises the replacement and they are written
    HERE, onto `inb_receipts`' own columns, which the receiving screen already reads.
    Nothing is stored on `pro_returns`: one fact, one place.

    A RETURNED consignment gets none of them, and that is correct rather than an
    omission — those are the goods WE despatched, travelling on the leg WE booked, and
    `out_dispatches` already holds that lorry. Writing the supplier's answer over it
    would replace what we know with what they guessed.

    WHOSE BATCH IS ON THE LINE, and the reason it branches. On a RETURNED consignment the
    same physical goods come back, so the return line's `batch_no` is the batch that will
    arrive and is carried across. On a REPLACEMENT it is the batch of the FAULTY goods
    going the other way — different physical stock, a different batch, frequently a
    different expiry — so copying it would hand the store a prefilled batch number that
    is wrong, on the one screen where a wrong batch becomes wrong stock.

    THE SUPPLIER IS ASKED INSTEAD (2026-09-11), per line, and that is what
    `data.replacement_lines` carries. Leaving it blank for the store to fill in was the
    obvious answer and it did not work: an expiry-tracked line with no expiry date is
    refused by `_apply_receipt_lines` when the GRN is submitted, so the receipt raised
    here could be opened and never finished. The storekeeper cannot supply either fact —
    the batch and the printed expiry belong to a carton standing in the supplier's
    warehouse — and the supplier can, in the same press that promises the replacement. So
    the two rules that will stop the GRN are applied HERE, against the same item master,
    and the answer is refused while the person who knows it is still on the screen.

    A line whose item needs neither is untouched and may be answered or not; and a
    RETURNED consignment is never asked, because those goods are already ours and their
    batch is on the return.

    THREE THINGS THIS DELIBERATELY DOES NOT DO, all of them load-bearing:

    * It does not post stock, and it does not go near `move_stock`. The row is a DRAFT
      with `received_qty` zero on every line; the goods are still on a lorry somewhere.
      The store inwards it through the ordinary GRN → QC → putaway path, which is the
      only path allowed to touch a balance (rule 7). `ordered_qty` carries what to
      EXPECT, which is what the receiving screen reconciles against.
    * It does not call `create_receipt`. That service takes an employee and a
      `ReceiptWrite` full of decisions a supplier is not entitled to make (warehouse,
      project, bins). The row is built here instead, in the module that owns
      `inb_receipts` — so raising it crosses no module boundary at all.
    * It does not run a workflow. A draft nobody has submitted has nothing to approve;
      approval happens when the store submits the receipt, exactly as for any other.

    A line with no `item_id` is refused rather than dropped. `inb_receipt_items.item_id`
    is NOT NULL, and a manually-typed return line may legitimately name an item the
    masters do not hold — silently skipping it would raise a receipt short of a line
    and the shortage would only surface when the lorry arrived.
    """
    _assert_inbound_raisable(row)

    replacing = row.vendor_response == VendorReturnResponse.REPLACED.value
    # Which of the two inbound legs, on a replacement. The schema has already refused a
    # mode on any other answer and refused each leg the other's fields, so these can be
    # copied across without re-deciding anything here.
    collecting = replacing and data.replacement_mode in s.INBOUND_MODES_COLLECTED

    receipt = m.Receipt(
        grn_no=await next_number(db, WarehouseDocType.RECEIPT.value),
        receipt_type=ReceiptType.RETURN.value,
        grn_date=ist_today(),
        # How the replacement travels, as the supplier stated it. All null on a RETURNED
        # consignment — see the docstring: that lorry is ours and `out_dispatches` holds
        # it.
        inbound_transport_mode=data.replacement_mode if replacing else None,
        # A DELIVERY's facts. `expected_delivery` is what the receiving screen sorts its
        # queue by, and it stays null on a collection ON PURPOSE: until somebody here
        # schedules a vehicle, nothing is due at the gate on any date, and a ready date
        # written here would have the store waiting for a lorry that was never sent.
        expected_delivery=data.replacement_expected_date if replacing else None,
        transporter_name=data.replacement_transporter_name if replacing else None,
        vehicle_no=data.replacement_vehicle_no if replacing else None,
        lr_no=data.replacement_lr_no if replacing else None,
        # A COLLECTION's facts: where the vehicle goes, and the earliest it may go.
        pickup_address=data.replacement_pickup_address if collecting else None,
        goods_ready_date=data.replacement_ready_date if collecting else None,
        # The purchase behind the original return, carried across so the new receipt
        # traces back to the same order the goods were bought on.
        po_id=row.po_id,
        po_no=row.po_no,
        vendor_id=row.vendor_id,
        vendor_name=row.vendor_name,
        # Back to the warehouse that sent them. NOT NULL on the table, which is why the
        # guard above exists.
        warehouse_id=row.warehouse_id,
        warehouse_name=row.warehouse_name,
        status=ReceiptStatus.DRAFT.value,
        remarks=(
            f"Raised automatically from purchase return {row.return_no} — "
            f"{VENDOR_RETURN_INBOUND_RESPONSES[row.vendor_response]}."
            # Said in WORDS as well as in the column, because a storekeeper opening this
            # reads the remark first and a collection that looks like a delivery is a
            # vehicle nobody sends. The columns are what screens act on; this is what a
            # person acts on.
            + (" COLLECTION REQUIRED — the goods are ready at the supplier and somebody "
               "here must send a vehicle." if collecting else "")
            + (f" Supplier's note: {row.vendor_response_note}"
               if row.vendor_response_note else "")
        ),
        total_items=len(row.items),
        # Nothing has been received yet: this document says what to EXPECT.
        total_received_qty=0,
        total_accepted_qty=0,
        total_rejected_qty=0,
        total_value=sum((line.amount or Decimal(0)) for line in row.items) or Decimal(0),
    )
    # WHAT IS IN THE CARTON, as the supplier stated it, line by line, keyed on the
    # `line_no` the portal showed them — and checked against the item master before any
    # of it is written. See `_validate_replacement_cartons`.
    stated = (await _validate_replacement_cartons(db, row, data.replacement_lines)
              if replacing else {})

    receipt.items = []
    for line in row.items:
        answer = stated.get(line.line_no)
        batch_no = line.batch_no
        mfg_date = expiry_date = None
        if replacing:
            # Theirs is the only batch that can be right here, and ours is the batch of
            # the FAULTY goods travelling the other way — see the docstring. What the
            # supplier states is taken; nothing is inherited.
            batch_no = answer.batch_no if answer else None
            mfg_date = answer.mfg_date if answer else None
            expiry_date = answer.expiry_date if answer else None
        receipt.items.append(m.ReceiptItem(
            line_no=line.line_no,
            po_item_id=line.po_item_id,
            item_id=line.item_id,
            item_code=line.item_code,
            item_name=line.item_name,
            uom_code=line.uom_code,
            ordered_qty=line.quantity,
            received_qty=0,
            accepted_qty=0,
            rejected_qty=0,
            short_qty=0,
            rate=line.rate,
            amount=line.amount,
            batch_no=batch_no,
            mfg_date=mfg_date,
            expiry_date=expiry_date,
            qc_status=QcStatus.PENDING.value,
            remarks=line.reason,
        ))
    db.add(receipt)
    await db.flush()
    await write_audit(
        db, entity="inb_receipts", entity_id=receipt.id, entity_no=receipt.grn_no,
        action=AuditAction.CREATE, actor=None,
        summary=f"Raised from purchase return {row.return_no}",
        after={"receipt_type": receipt.receipt_type,
               "source_return_no": row.return_no,
               "vendor_response": row.vendor_response})
    return receipt


def _logistics_audit(data: "s.PurchaseReturnLogisticsIn", mode: str) -> dict:
    """The logistics block as flat, JSON-safe facts for the audit trail.

    This is the ONLY record a manual return keeps of how it travelled, so it holds
    every field rather than a summary — see the manual branch of `send_to_vendor`.
    """
    def _txt(v):
        return (v or "").strip() or None

    return {
        "mode": mode,
        "hand_carried_by": _txt(data.hand_carried_by),
        "vehicle_number": _txt(data.vehicle_number),
        "driver_name": _txt(data.driver_name),
        "driver_phone": _txt(data.driver_phone),
        "carrier_name": _txt(data.carrier_name),
        "lr_no": _txt(data.lr_no),
        "freight_amount": (str(data.freight_amount)
                           if data.freight_amount is not None else None),
        "delivery_address": _txt(data.delivery_address),
        "contact_person": _txt(data.contact_person),
        "contact_phone": _txt(data.contact_phone),
        "total_packages": data.total_packages,
        "total_weight_kg": (str(data.total_weight_kg)
                            if data.total_weight_kg is not None else None),
        "eway_bill_no": _txt(data.eway_bill_no),
        "gate_pass_no": _txt(data.gate_pass_no),
        "expected_delivery": (data.expected_delivery.isoformat()
                              if data.expected_delivery else None),
        "dispatch_remarks": _txt(data.dispatch_remarks),
        "acknowledged_by_name": _txt(data.acknowledged_by_name),
        "acknowledged_at": (data.acknowledged_at.isoformat()
                            if data.acknowledged_at else None),
        "pod_url": _txt(data.pod_url),
    }


# ---------------------------------------------------------------------------
# The purchase-return dossier — the whole trail, read only
# ---------------------------------------------------------------------------

#: What each row on the trail is called, and which half of the story it belongs to.
#: PURCHASE is how the material was bought, RETURN is how it came back, and DOCUMENT is
#: the purchase return itself standing between the two.
_TRAIL_KINDS: dict[str, tuple[str, str]] = {
    "INDENT": ("Indent", "PURCHASE"),
    "REQUISITION": ("Requisition", "PURCHASE"),
    "RFQ": ("RFQ", "PURCHASE"),
    "QUOTATION": ("Quotation", "PURCHASE"),
    "PO": ("Purchase Order", "PURCHASE"),
    "GRN": ("Goods Receipt", "PURCHASE"),
    "VENDOR_INVOICE": ("Vendor Invoice", "PURCHASE"),
    "QC": ("QC Inspection", "PURCHASE"),
    "BRANCH_RETURN": ("Branch Return", "RETURN"),
    "TRANSPORT_REQUEST": ("Transport / Consignment", "RETURN"),
    "PURCHASE_RETURN": ("Purchase Return", "DOCUMENT"),
    "DISPATCH": ("Dispatch to Vendor", "DOCUMENT"),
    "CREDIT_NOTE": ("Credit Note", "DOCUMENT"),
}

#: Where each kind of document is read in the app. `{id}` is substituted. A kind absent
#: from here renders as a row that cannot be opened, which is honest — better than a
#: link into a module that has no detail screen for it. QUOTATION is deliberately
#: absent: procurement serves a quotations REGISTER and no per-quotation route, so the
#: row names the quotation and does not pretend to open it.
_TRAIL_ROUTES: dict[str, str] = {
    "INDENT": "/indents/{id}",
    "REQUISITION": "/procurement/requisitions/{id}",
    "RFQ": "/procurement/rfqs/{id}",
    "PO": "/pos/{id}",
    "GRN": "/warehouse/grn/{id}",
    "QC": "/warehouse/quality-inspection/{id}",
    "BRANCH_RETURN": "/returns/{id}",
    "TRANSPORT_REQUEST": "/logistics/shipments/{id}",
    "DISPATCH": "/warehouse/dispatch/{id}",
}


def _trail_row(doc_type: str, *, doc_id=None, doc_no=None, status=None, day=None,
               party=None, facts=None, traced=False) -> dict:
    """One trail row. Every kind carries the same keys so the screen never branches."""
    label, leg = _TRAIL_KINDS.get(doc_type, (doc_type.replace("_", " ").title(),
                                             "PURCHASE"))
    route = _TRAIL_ROUTES.get(doc_type)
    return {
        "doc_type": doc_type,
        "doc_label": label,
        "doc_id": doc_id,
        "doc_no": doc_no,
        "status": status,
        "doc_date": day.date() if isinstance(day, datetime) else day,
        "party": party,
        # Only the pairs that actually have a value: a trail row padded with dashes
        # reads as a form somebody failed to fill in.
        "facts": [[k, str(v)] for k, v in (facts or []) if v not in (None, "", [])],
        "leg": leg,
        "traced": traced,
        "route": route.format(id=doc_id) if route and doc_id else None,
    }


async def _branch_return_of(db: AsyncSession, doc: m.PurchaseReturn):
    """The branch consignment this purchase return was raised off, where there was one.

    `inv_sto` is inventory's table and the returns module's document; it is READ here
    and never written. The link is `pro_returns.source_return_id`, stamped by
    `returns.service._warehouse_return_document` when the gate-out raised this draft.
    """
    if not doc.source_return_id:
        return None
    try:
        from app.modules.inventory.models import StockTransferOrder as _STO
        return await db.get(_STO, doc.source_return_id)
    except Exception:
        logger.debug("Branch return %s not reachable", doc.source_return_id,
                     exc_info=True)
        return None


async def _transport_of_branch_return(db: AsyncSession, source_return_id: int | None):
    """The consignment that carried the branch return in, off its public link.

    Read from `lgs_transport_requests.source_type/source_id` rather than by unpacking
    the JSON the returns module keeps in `inv_sto.remarks` — that payload is that
    module's private encoding and this one has no business parsing it.
    """
    if not source_return_id:
        return None
    try:
        from app.modules.logistics.models import TransportRequest as _TR
        return await db.scalar(
            select(_TR).where(_TR.source_type == "RETURN",
                              _TR.source_id == source_return_id)
            .order_by(_TR.id.desc()).limit(1))
    except Exception:
        logger.debug("Transport request for return %s not reachable", source_return_id,
                     exc_info=True)
        return None


async def _procurement_trail(db: AsyncSession, po) -> list[dict]:
    """Requisition, RFQ and quotation behind a purchase order.

    Every one of them is a snapshot column ON the PO (`requisition_id`, `rfq_id`,
    `quotation_id`), so this is three gets and no searching. Swallowed as a group where
    procurement cannot be imported: a return is still readable without the buying trail.
    """
    rows: list[dict] = []
    if po is None:
        return rows
    try:
        from app.modules.procurement.models import RFQ as _RFQ
        from app.modules.procurement.models import Quotation as _Quotation
        from app.modules.procurement.models import Requisition as _Requisition
    except Exception:
        logger.debug("Procurement models not reachable", exc_info=True)
        return rows

    req = await db.get(_Requisition, po.requisition_id) if getattr(
        po, "requisition_id", None) else None
    if req is not None:
        rows.append(_trail_row(
            "REQUISITION", doc_id=req.id, doc_no=req.req_no, status=req.status,
            day=req.req_date, party=req.created_by_name,
            facts=[("Lines", req.total_items), ("Project", req.project_name),
                   ("Approved by", req.approved_by_name)]))
    elif getattr(po, "requisition_no", None):
        rows.append(_trail_row("REQUISITION", doc_no=po.requisition_no))

    rfq = await db.get(_RFQ, po.rfq_id) if getattr(po, "rfq_id", None) else None
    if rfq is not None:
        rows.append(_trail_row(
            "RFQ", doc_id=rfq.id, doc_no=rfq.rfq_no, status=rfq.status,
            day=rfq.rfq_date, party=rfq.awarded_vendor_name,
            facts=[("Vendors invited", rfq.vendor_count),
                   ("Responses", rfq.response_count),
                   ("Awarded to", rfq.awarded_vendor_name)]))
    elif getattr(po, "rfq_no", None):
        rows.append(_trail_row("RFQ", doc_no=po.rfq_no))

    quote = await db.get(_Quotation, po.quotation_id) if getattr(
        po, "quotation_id", None) else None
    if quote is not None:
        rows.append(_trail_row(
            "QUOTATION", doc_id=quote.id, doc_no=quote.quotation_no,
            status=quote.status, day=quote.quotation_date, party=quote.vendor_name,
            facts=[("Quoted", f"₹ {_d(quote.grand_total):,.2f}"),
                   ("Vendor ref", quote.vendor_ref_no),
                   ("Payment terms", quote.payment_terms)]))
    elif getattr(po, "quotation_no", None):
        rows.append(_trail_row("QUOTATION", doc_no=po.quotation_no))
    return rows


async def _dossier_documents(db: AsyncSession, doc: m.PurchaseReturn) -> list[dict]:
    """Every document behind this return, oldest step of the flow first.

    Two legs meeting at this document: how the material was BOUGHT (indent, requisition,
    RFQ, quotation, PO, GRN, the vendor's invoice, QC) and how it came BACK (the branch
    consignment, the transport request that carried it). The purchase return itself sits
    between them, and the dispatch and credit note follow it.

    `traced` is carried per row rather than as one flag on the response: on a return
    raised off a branch consignment the whole purchase leg is READ off the stock and the
    return leg is the document's own, and a reader has to be able to tell which half is
    evidence and which half is binding.
    """
    rows: list[dict] = []
    traced = bool(getattr(doc, "chain_traced", False))

    # `getattr` throughout: every `traced_*` and chain field is a TRANSIENT attribute
    # set by `_decorate_purchase_return`, not a column, so a document that took a
    # different path through it — a manual return takes the early exit — has the
    # attribute missing rather than None, and a plain `doc.x` raises AttributeError.
    grn_id = doc.grn_id or getattr(doc, "traced_grn_id", None)
    receipt = await db.get(m.Receipt, grn_id) if grn_id else None
    po = await _po_of(db, doc.po_id or getattr(doc, "traced_po_id", None)
                      or getattr(receipt, "po_id", None))

    # --- how it was bought ---------------------------------------------------------
    indent_id = getattr(doc, "indent_id", None) or getattr(po, "indent_id", None)
    indent_no = getattr(doc, "indent_no", None) or await _indent_no(db, indent_id)
    if indent_id or indent_no:
        indent = None
        try:
            from app.modules.indents.models import Indent as _Indent
            indent = await db.get(_Indent, indent_id) if indent_id else None
        except Exception:
            logger.debug("Indent %s not reachable", indent_id, exc_info=True)
        rows.append(_trail_row(
            "INDENT", doc_id=indent_id, doc_no=indent_no,
            status=getattr(indent, "status", None),
            day=getattr(indent, "indent_date", None),
            party=getattr(indent, "requested_by_name", None),
            facts=[("Project", getattr(indent, "project_name", None)),
                   ("Office", getattr(indent, "office_name", None)),
                   ("Lines", getattr(indent, "total_items", None))],
            traced=traced))

    rows.extend(row | {"traced": traced} for row in await _procurement_trail(db, po))

    if po is not None:
        rows.append(_trail_row(
            "PO", doc_id=po.id, doc_no=po.po_no, status=po.status, day=po.po_date,
            party=po.vendor_name,
            facts=[("Order value", f"₹ {_d(po.total_amount):,.2f}"),
                   ("Raised by", po.created_by_name),
                   ("Approved", po.approved_at.date().isoformat()
                    if getattr(po, "approved_at", None) else None)],
            traced=traced))
    elif doc.po_no or getattr(doc, "traced_po_no", None):
        rows.append(_trail_row("PO",
                               doc_no=doc.po_no or getattr(doc, "traced_po_no", None),
                               traced=traced))

    if receipt is not None:
        rows.append(_trail_row(
            "GRN", doc_id=receipt.id, doc_no=receipt.grn_no, status=receipt.status,
            day=receipt.grn_date, party=receipt.vendor_name or getattr(po, "vendor_name", None),
            facts=[("Received at", receipt.warehouse_name),
                   ("Gate entry", getattr(receipt, "gate_entry_no", None))],
            traced=traced))
        # The vendor's own invoice behind the GRN — the reference the vendor argues the
        # return against. Its own row because it is the vendor's paper, not ours.
        if receipt.invoice_no:
            rows.append(_trail_row(
                "VENDOR_INVOICE", doc_no=receipt.invoice_no, day=receipt.invoice_date,
                party=receipt.vendor_name or getattr(po, "vendor_name", None),
                traced=traced))

        qc = await db.scalar(
            select(m.Inspection).where(m.Inspection.receipt_id == receipt.id)
            .order_by(m.Inspection.id.desc()).limit(1))
        if qc is not None:
            rows.append(_trail_row(
                "QC", doc_id=qc.id, doc_no=qc.inspection_no, status=qc.status,
                day=qc.inspection_date, party=qc.inspector_name,
                facts=[("Passed", qc.passed_items), ("Failed", qc.failed_items),
                       ("Type", qc.inspection_type)],
                traced=traced))

    # --- how it came back ----------------------------------------------------------
    branch = await _branch_return_of(db, doc)
    if branch is not None:
        rows.append(_trail_row(
            "BRANCH_RETURN", doc_id=branch.id, doc_no=branch.sto_no,
            status=branch.status, day=branch.created_at,
            party=branch.requested_by_name,
            facts=[("From", branch.from_warehouse_name),
                   ("To", branch.to_warehouse_name),
                   ("Approved by", branch.approved_by_name),
                   ("Dispatched", branch.dispatched_at.strftime("%d %b %Y %H:%M")
                    if branch.dispatched_at else None),
                   ("Acknowledged", branch.received_at.strftime("%d %b %Y %H:%M")
                    if branch.received_at else None)]))
    elif doc.source_return_no:
        rows.append(_trail_row("BRANCH_RETURN", doc_no=doc.source_return_no))

    tr = await _transport_of_branch_return(db, doc.source_return_id)
    if tr is not None:
        rows.append(_trail_row(
            "TRANSPORT_REQUEST", doc_id=tr.id, doc_no=tr.tr_no, status=tr.status,
            day=tr.tr_date, party=tr.carrier_name or tr.driver_name,
            facts=[("Gate pass", tr.gate_pass_no), ("Vehicle", tr.vehicle_number),
                   ("Driver", tr.driver_name), ("LR / docket", tr.lr_no or tr.docket_no),
                   ("Consignment", tr.consignment_no),
                   ("Dispatched", tr.dispatched_at.strftime("%d %b %Y %H:%M")
                    if tr.dispatched_at else None),
                   ("Delivered", tr.delivered_at.strftime("%d %b %Y %H:%M")
                    if tr.delivered_at else None)]))

    # --- the document itself, and what has left it ----------------------------------
    rows.append(_trail_row(
        "PURCHASE_RETURN", doc_id=doc.id, doc_no=doc.return_no, status=doc.status,
        day=doc.return_date, party=doc.vendor_name or getattr(doc, "traced_vendor_name", None),
        facts=[("Raised by", doc.created_by_name),
               ("Lines", doc.total_items),
               ("Value", f"₹ {_d(doc.total_value):,.2f}"),
               ("Source", doc.source_category_label),
               ("Sent to vendor", doc.sent_at.strftime("%d %b %Y %H:%M")
                if doc.sent_at else None)]))

    if getattr(doc, "dispatch_id", None) or getattr(doc, "dispatch_no", None):
        rows.append(_trail_row(
            "DISPATCH", doc_id=doc.dispatch_id, doc_no=doc.dispatch_no,
            party=doc.vendor_name or getattr(doc, "traced_vendor_name", None)))
    if doc.credit_note_no:
        rows.append(_trail_row("CREDIT_NOTE", doc_no=doc.credit_note_no,
                               party=doc.vendor_name or getattr(doc, "traced_vendor_name", None)))
    return rows


#: How an audit row reads as a sentence. Keyed on the field the row recorded, because
#: `sys_audit_log` stores WHAT changed and not why — the words belong here, next to the
#: flow, rather than being invented on the screen.
_EVENT_TITLES: dict[str, str] = {
    "status": "Status changed",
    "phase": "Moved to the next desk",
    "disposition": "Decision taken",
    "leg": "Return leg set",
    "condition": "Condition recorded on arrival",
    "signed_by": "Signed for at the far end",
    "acknowledged_by": "Acknowledged",
    "transport_request_no": "Consignment raised",
    "warehouse_return_no": "Warehouse document raised",
    "source_category": "Filed against the vendor",
    "comments": "Comment added",
    "note": "Note added",
    "dispatch_no": "Dispatched",
    "credit_note_no": "Credit note recorded",
    "reason": "Reason recorded",
}


def _audit_event(row, entity_label: str) -> dict:
    """One `sys_audit_log` row as a sentence a reader can follow.

    The log keeps `{"field": {"from": x, "to": y}}` and nothing else, so the title comes
    off the most significant field the row touched and the detail names the rest. A
    field nobody has written words for still shows — as its own name — rather than
    being dropped, because a silent gap in a trail is worse than a plain one.
    """
    changed = row.changed_fields
    if isinstance(changed, str):
        # Some rows in the live log were written before the column was typed JSON and
        # come back as text. Decoded rather than dropped: an event with no detail on it
        # is a hole in the trail, and the words are right there in the string.
        try:
            changed = json.loads(changed)
        except (TypeError, ValueError):
            changed = {}
    if not isinstance(changed, dict):
        changed = {}
    status_to = (changed.get("status") or {}).get("to")
    # Whichever recognised field the row carries first, in the order the flow cares
    # about; the raw action where it carries none of them.
    title = None
    for field in _EVENT_TITLES:
        if field in changed:
            title = _EVENT_TITLES[field]
            break
    if row.action == "CREATE":
        title = f"{entity_label} created"
    elif title is None:
        title = f"{entity_label} {str(row.action or '').lower()}"

    parts: list[str] = []
    for field, change in changed.items():
        if not isinstance(change, dict):
            continue
        to = change.get("to")
        if to in (None, "", False):
            continue
        was = change.get("from")
        name = field.replace("_", " ")
        parts.append(f"{name}: {was} → {to}" if was not in (None, "")
                     else f"{name}: {to}")
    return {
        "at": row.created_at,
        "entity": row.entity_type,
        "doc_no": row.entity_no,
        "action": row.action,
        "title": title,
        "detail": " · ".join(parts) or None,
        "actor_name": row.actor_name,
        "status_to": status_to,
    }


async def _dossier_timeline(db: AsyncSession, doc: m.PurchaseReturn) -> list[dict]:
    """Everything that has happened, on this return AND on the return that caused it.

    One trail, not two. To the warehouse person reading a DRAFT nobody remembers
    raising, the branch's approvals, the decision desk, the gate-out and the
    acknowledgement that produced it are the same story as this document's own — and
    the whole of it was already in `sys_audit_log`, unread.

    Approval actions come from the workflow engine on top, so a ladder configured for
    purchase returns shows its signatures here beside the audit rows.
    """
    from app.platform.settings.models import AuditLog

    wanted: list[tuple[str, int, str]] = [("pro_returns", doc.id, "Purchase return")]
    if doc.source_return_id:
        wanted.append(("inv_sto", doc.source_return_id, "Branch return"))
    tr = await _transport_of_branch_return(db, doc.source_return_id)
    if tr is not None:
        wanted.append(("lgs_transport_requests", tr.id, "Consignment"))

    events: list[dict] = []
    for entity, entity_id, label in wanted:
        rows = (await db.execute(
            select(AuditLog)
            .where(AuditLog.entity_type == entity, AuditLog.entity_id == entity_id)
            .order_by(AuditLog.id)
        )).scalars().all()
        events.extend(_audit_event(row, label) for row in rows)

    # The signatures, where a ladder is configured for purchase returns. Swallowed on
    # failure: the audit trail above is the record, and a workflow that cannot be read
    # must not take the history down with it.
    try:
        for action in await engine.history(
                db, WarehouseDocType.PURCHASE_RETURN.value, doc.id):
            events.append({
                "at": action.acted_at,
                "entity": "wf_actions",
                "doc_no": doc.return_no,
                "action": action.action,
                "title": action.stage_name or "Approval",
                "detail": action.comments,
                "actor_name": action.actor_name,
                "status_to": None,
            })
    except Exception:
        logger.debug("Approval history for return %s not reachable", doc.id,
                     exc_info=True)

    # Oldest first: this is read as a story, and a story starts at the beginning. Rows
    # with no timestamp sort last rather than crashing the comparison.
    events.sort(key=lambda event: (event["at"] is None, event["at"] or utcnow()))
    return events


#: What `_replacement_intake` answers when there is nothing to answer about — no
#: replacement receipt, or the read failed. A dict of the same shape rather than None, so
#: `_journey_legs` never has to branch on whether it was given one and a screen never sees
#: a different set of legs because a query went wrong.
_NO_INTAKE: dict = {
    "receipt_id": None, "grn_no": None, "grn_status": None, "grn_raised_at": None,
    "grn_booked": False, "grn_booked_at": None,
    "inspection_no": None, "inspection_status": None, "inspection_at": None,
    "qc_required": False, "qc_passed": False, "qc_failed": False, "qc_partial": False,
    "putaway_total": 0, "putaway_done": 0, "putaway_open": 0, "putaway_at": None,
    "putaway_bins": None,
    "stock_posted": False, "intake_complete": False, "completed_at": None,
}


async def _replacement_intake(db: AsyncSession, doc: m.PurchaseReturn) -> dict:
    """How far the replacement has got through the store's ordinary inward path.

    READ, NEVER STORED, and read off the three documents that already own these facts:
    the goods receipt the dispatch note raised (`inb_receipts`), its QC
    (`inb_inspections`) and its putaway tasks (`whs_warehouse_items`). Nothing here is
    mirrored onto `pro_returns` — see `enums.RETURN_REPLACEMENT_INTAKE_STATUSES` for why
    a copy of the receipt's ladder on the return was refused.

    `vendor_followup_receipt_id` is the link, and it is the one the dispatch note already
    stamped: one return, one intake receipt, which is also what stops a second GRN being
    raised for one lorry (`vendor_dispatch_replacement`).

    NEVER RAISES. The journey is a read on a screen a person opens to find out where their
    document is; a tracker that 500s because a putaway query failed is worse than one that
    says "not yet". A failed read comes back as `_NO_INTAKE`, which draws the three legs as
    not-yet-started rather than inventing progress.
    """
    if not getattr(doc, "vendor_followup_receipt_id", None):
        return dict(_NO_INTAKE)
    try:
        receipt = await db.scalar(
            select(m.Receipt)
            .options(selectinload(m.Receipt.items))
            .where(m.Receipt.id == doc.vendor_followup_receipt_id))
        if receipt is None:
            return dict(_NO_INTAKE)

        out = dict(_NO_INTAKE)
        out["receipt_id"] = receipt.id
        out["grn_no"] = receipt.grn_no
        out["grn_status"] = receipt.status
        out["grn_raised_at"] = receipt.created_at
        # BOOKED IN means the store has said what physically arrived, which is the submit.
        # A DRAFT is the expectation the dispatch note raised and nothing more; a CANCELLED
        # receipt never became a GRN at all.
        out["grn_booked"] = receipt.status not in {ReceiptStatus.DRAFT.value,
                                                   ReceiptStatus.GATE_ENTRY.value,
                                                   ReceiptStatus.CANCELLED.value}
        out["grn_booked_at"] = receipt.updated_at if out["grn_booked"] else None
        out["stock_posted"] = bool(receipt.is_stock_posted)
        out["completed_at"] = receipt.posted_at
        out["intake_complete"] = receipt.status == ReceiptStatus.COMPLETED.value

        # WHETHER QC IS OWED AT ALL. A line the item master exempts arrives NOT_REQUIRED
        # and goes straight to putaway, so a receipt made entirely of those has no
        # inspection to wait for and the leg must say so rather than hanging on one that
        # is never coming.
        out["qc_required"] = any(
            line.qc_status != QcStatus.NOT_REQUIRED.value for line in receipt.items)
        out["qc_passed"] = receipt.status in {ReceiptStatus.QC_PASSED.value,
                                              ReceiptStatus.PARTIALLY_RECEIVED.value,
                                              ReceiptStatus.COMPLETED.value}
        out["qc_failed"] = receipt.status == ReceiptStatus.QC_FAILED.value
        out["qc_partial"] = receipt.status == ReceiptStatus.PARTIALLY_RECEIVED.value

        inspection = await db.scalar(
            select(m.Inspection)
            .where(m.Inspection.receipt_id == receipt.id,
                   m.Inspection.status != InspectionStatus.CANCELLED.value)
            .order_by(m.Inspection.id.desc()).limit(1))
        if inspection is not None:
            out["inspection_no"] = inspection.inspection_no
            out["inspection_status"] = inspection.status
            out["inspection_at"] = inspection.created_at

        # The putaway tasks this receipt raised. Counted rather than listed: the tracker
        # says "3 of 4 placed", and the tasks themselves are worked on their own screen.
        rows = (await db.execute(
            select(m.PutawayTask.status, m.PutawayTask.completed_at,
                   m.PutawayTask.lot_no)
            .where(m.PutawayTask.grn_id == receipt.id)
        )).all()
        live = [row for row in rows if row.status != PutawayStatus.CANCELLED.value]
        done = [row for row in live if row.status == PutawayStatus.COMPLETED.value]
        out["putaway_total"] = len(live)
        out["putaway_done"] = len(done)
        out["putaway_open"] = len(live) - len(done)
        out["putaway_at"] = max((row.completed_at for row in done
                                 if row.completed_at), default=None)
        return out
    except Exception:
        logger.exception("The replacement intake behind %s could not be read",
                         doc.return_no)
        return dict(_NO_INTAKE)


def _journey_legs(doc: m.PurchaseReturn, intake: dict | None = None) -> list[dict]:
    """The twelve legs of a purchase return, each with where it got to and what it said.

    READ, NEVER STORED. Every value below comes off a column the document already carries
    or off the trail that is already written — nothing is recorded for the tracker's
    benefit, so the tracker cannot show a step the documents do not.

    EVERY LEG IS DRAWN FOR EVERY RETURN, including ones this particular document will
    never reach: a refund never gets to transport, a rejected return never gets past the
    decision. A tracker that dropped steps per document would describe a different flow on
    every screen, so a leg with nothing to do is CAPTIONED as having nothing to do. That is
    the rule the stock-return tracker already follows.

    A REFUSAL HALTS THE FLOW. Every leg after the one that stopped stays `pending`, so a
    rejected return can never render as though the goods moved.

    `intake` is what `_replacement_intake` read off the goods receipt, its QC and its
    putaway tasks — the last three legs before the close. Passed IN rather than read here
    because this function is deliberately synchronous and pure: it is the one place the
    whole ladder is written down, and every caller must get the same answer for the same
    document. Omitting it draws those three as not yet started, which is exactly right for
    a return that has no replacement coming.
    """
    intake = intake or dict(_NO_INTAKE)
    status = doc.status
    rejected = status == ReturnStatus.REJECTED.value
    cancelled = status == ReturnStatus.CANCELLED.value
    refunded = status == ReturnStatus.REFUNDED.value
    closed = status in RETURN_CLOSED_STATUSES

    # Every one of these is a TRANSIENT attribute assigned by a decorator, not a column,
    # and several decorators assign theirs only on the branch that has something to say.
    # `getattr` rather than attribute access throughout, because this function runs on a
    # document at EVERY rung — including a DRAFT, which has been down none of those
    # branches. Reading one directly is an AttributeError, not a None.
    dispatch_no = getattr(doc, "dispatch_no", None)
    indent_no = getattr(doc, "indent_no", None)
    reason_label = getattr(doc, "reason_label", None)
    arrangement_label = getattr(doc, "vehicle_arrangement_label", None)

    # How far along the ladder this document has actually travelled. Read off the stamps
    # rather than off the status, because the status says where it is now and a tracker
    # has to say where it has BEEN.
    sent = bool(doc.sent_at)
    decided = bool(doc.vendor_decision)
    approved = doc.vendor_decision == ApprovalAction.APPROVED.value
    settled = bool(doc.vendor_response) or refunded
    transport_chosen = bool(doc.vehicle_arrangement)
    picked_up = bool(doc.arranged_dispatched_at) or status in {
        ReturnStatus.STOCK_PICKED_UP.value, ReturnStatus.VENDOR_RECEIVED.value,
        ReturnStatus.REPLACEMENT_DISPATCHED.value,
        ReturnStatus.RECEIVED_AT_WAREHOUSE.value, ReturnStatus.COMPLETED.value}
    vendor_has_it = bool(doc.vendor_receipt_confirmed_at)
    replacement_gone = bool(doc.replacement_dispatched_at)
    back_here = bool(doc.received_at)

    def leg(key: str, label: str, *, done: bool, current: bool = False,
            at=None, actor: str | None = None, detail: str | None = None,
            ref: str | None = None, state: str | None = None) -> dict:
        return {
            "key": key, "label": label,
            "state": state or ("completed" if done
                               else "current" if current else "pending"),
            "at": at, "actor_name": actor, "detail": detail, "reference_no": ref,
        }

    legs = [
        leg("created", "Created", done=True, at=doc.created_at,
            actor=doc.created_by_name, ref=doc.return_no,
            detail=reason_label or doc.reason),
        leg("sent_to_vendor", "Sent to vendor", done=sent, current=not sent,
            at=doc.sent_at, actor=doc.created_by_name,
            ref=doc.grn_no or doc.po_no or indent_no,
            detail=("Sent for the vendor to verify against the GRN, PO and QC"
                    if sent else "Not sent yet")),
    ]

    legs.append(leg(
        "vendor_decision", "Vendor decision",
        done=decided, current=sent and not decided,
        at=doc.vendor_decision_at, actor=doc.vendor_decision_by_name,
        detail=(doc.vendor_decision_note or
                ("Approved by the vendor" if approved else
                 "Rejected by the vendor" if decided else
                 "Waiting on the vendor to approve or reject")),
        state="rejected" if rejected else None))

    legs.append(leg(
        "settlement", "Refund / Replacement",
        done=settled, current=approved and not settled and not closed,
        at=doc.vendor_response_at or doc.refunded_at,
        actor=doc.vendor_name,
        detail=(f"Refund of {_d(doc.vendor_refund_amount):,.2f} agreed" if refunded
                else "Replacement agreed" if settled
                else "Rejected — nothing to settle" if rejected
                else "Waiting on the vendor to choose refund or replacement")))

    # The three travelling legs. A refund never reaches them and says so rather than
    # sitting at "pending" forever, which reads as work somebody still owes.
    money = refunded or (rejected and not transport_chosen)
    nothing_to_move = ("Settled in money — nothing travels" if refunded
                       else "Rejected — nothing travels" if rejected else None)

    legs.append(leg(
        "transport", "Transport",
        done=transport_chosen and picked_up,
        current=settled and not money and not picked_up,
        at=doc.vehicle_arrangement_at, actor=doc.vehicle_arrangement_by_name,
        ref=doc.outbound_tr_no or dispatch_no,
        detail=(nothing_to_move or arrangement_label
                or "Waiting on the warehouse to arrange transport"),
        state="cancelled" if money else None))

    legs.append(leg(
        "vendor_received", "Vendor received",
        done=vendor_has_it, current=picked_up and not vendor_has_it and not money,
        at=doc.vendor_receipt_confirmed_at, actor=doc.vendor_receipt_by_name,
        detail=(nothing_to_move or doc.vendor_receipt_remarks
                or ("Signed for at the vendor's dock" if vendor_has_it else
                    "Waiting on the vendor to sign for the goods")),
        state="cancelled" if money else None))

    legs.append(leg(
        "replacement_dispatched", "Replacement dispatched",
        done=replacement_gone,
        current=vendor_has_it and not replacement_gone and not money,
        at=doc.replacement_dispatched_at, actor=doc.vendor_name,
        ref=doc.replacement_dispatch_no or doc.vendor_followup_receipt_no,
        detail=(nothing_to_move or doc.replacement_remarks
                or ("Replacement on its way" if replacement_gone else
                    "Waiting on the vendor to dispatch the replacement")),
        state="cancelled" if money else None))

    legs.append(leg(
        "warehouse_received", "Warehouse received",
        done=back_here, current=replacement_gone and not back_here and not money,
        at=doc.received_at, actor=doc.received_by_name,
        ref=doc.vendor_followup_receipt_no,
        detail=(nothing_to_move or doc.received_remarks
                or ("Replacement received" if back_here else
                    "Waiting on the replacement to arrive")),
        state="cancelled" if money else None))

    # ---- the store's ordinary inward path, READ off the three documents that own it ----
    #
    # GRN, then QC, then putaway. Not a second flow built for returns: the goods receipt
    # the dispatch note raised is booked in, inspected and placed exactly as any other
    # delivery is, on the screens the store already works. These legs only SAY where that
    # has got to, so the person chasing the return does not have to go and find three
    # other documents to answer "is it on the shelf yet".
    #
    # A return that produces no replacement — a refund, a refusal, or one closed under the
    # older flow that never had an intake receipt — says these will never happen rather
    # than sitting at `pending`, which reads as work somebody still owes.
    grn_no = intake["grn_no"]
    grn_booked = intake["grn_booked"]
    qc_required = intake["qc_required"]
    qc_passed = intake["qc_passed"]
    qc_failed = intake["qc_failed"]
    put_total = intake["putaway_total"]
    put_done = intake["putaway_done"]
    placed = put_total > 0 and intake["putaway_open"] == 0
    no_intake = nothing_to_move or (
        "Closed with no replacement to book in"
        if (closed or cancelled) and not grn_no else None)

    legs.append(leg(
        "grn", "GRN",
        done=grn_booked, current=bool(grn_no) and back_here and not grn_booked,
        at=intake["grn_booked_at"] if grn_booked else intake["grn_raised_at"],
        ref=grn_no,
        detail=(no_intake
                or (f"Booked in on {grn_no}" if grn_booked
                    else f"Draft {grn_no} raised — waiting on the store to book it in"
                    if grn_no else "No goods receipt raised yet")),
        state="cancelled" if no_intake else None))

    legs.append(leg(
        "qc", "QC inspection",
        done=qc_passed or (grn_booked and not qc_required),
        current=grn_booked and qc_required and not (qc_passed or qc_failed),
        at=intake["inspection_at"], ref=intake["inspection_no"],
        detail=(no_intake
                or ("QC not required for these lines" if grn_booked and not qc_required
                    else "QC failed — the replacement was rejected" if qc_failed
                    else "Passed in part — some quantity was rejected"
                    if intake["qc_partial"]
                    else "QC passed" if qc_passed
                    else "Waiting on the QC inspection" if grn_booked
                    else "Inspected once the goods receipt is booked in")),
        state="cancelled" if no_intake else "rejected" if qc_failed else None))

    legs.append(leg(
        "putaway", "Putaway",
        done=placed,
        current=(qc_passed or (grn_booked and not qc_required)) and not placed,
        at=intake["putaway_at"],
        detail=(no_intake
                or ("QC failed — nothing to put away" if qc_failed
                    else f"{put_done} of {put_total} placed" if put_total
                    else "Waiting on QC before the stock may be placed")),
        state="cancelled" if no_intake or qc_failed else None))

    legs.append(leg(
        "closed", "Closed", done=closed, current=placed and not closed,
        # WHEN it closed. A refund is settled by the vendor's own answer; a replacement is
        # closed by its putaway finishing, and the receipt's posting stamp is that moment
        # — read off the intake rather than stored, like every other value here.
        at=(doc.vendor_response_at if refunded
            else intake["completed_at"] if closed else None),
        ref=doc.credit_note_no or (grn_no if closed and not refunded else None),
        detail=("Refund settled" if refunded else
                "Rejected by the vendor" if rejected else
                "Cancelled" if cancelled else
                (f"Closed — the replacement was put away against {grn_no}"
                 if grn_no else "Closed") if closed else
                "Closes once the replacement is put away"),
        state="rejected" if rejected else "cancelled" if cancelled else None))

    # A refusal halts everything after the leg that stopped — see the docstring.
    if rejected or cancelled:
        halted = False
        for row in legs:
            if row["state"] in {"rejected", "cancelled"}:
                halted = True
                continue
            if halted and row["state"] == "current":
                row["state"] = "pending"

    # THE TRACKER READS LEFT TO RIGHT, so it must be monotonic: a document that has
    # demonstrably reached leg 8 has passed legs 1-7, whatever stamps those legs do or do
    # not carry.
    #
    # This is not hypothetical tidying. Returns migrated from the older vendor -> warehouse
    # flow were received at the warehouse without ever passing through the settlement and
    # transport rungs, which did not exist when they travelled — so they rendered as
    # "received" AND "waiting on the vendor to choose refund or replacement" at the same
    # time, which is not a state any document can be in. An unstamped leg behind a
    # completed one means the step happened and nobody recorded it, never that it is still
    # owed.
    #
    # `cancelled` and `rejected` legs are left exactly as they are: those say a leg will
    # never happen, which is a different statement from one that happened unrecorded.
    last_done = max((i for i, row in enumerate(legs)
                     if row["state"] == "completed"), default=-1)
    for row in legs[:max(last_done, 0)]:
        if row["state"] in {"pending", "current"}:
            row["state"] = "completed"
    # Exactly one leg may be current. If back-filling consumed it, the document is
    # standing on the first leg that has still not happened.
    #
    # NOT on a document that STOPPED. A rejected or cancelled return is standing on
    # nothing — nobody owes it a press — and restoring a `current` marker here would put
    # "waiting on the vendor to choose refund or replacement" on a return the vendor has
    # already refused. A halted flow has no current leg, which is the whole point of
    # halting it.
    halted = rejected or cancelled
    if not halted and not any(row["state"] == "current" for row in legs):
        for row in legs[last_done + 1:]:
            if row["state"] == "pending":
                row["state"] = "current"
                break
    return legs


def _journey_summary(doc: m.PurchaseReturn, legs: list[dict]) -> tuple[int, str]:
    """Which leg the document is standing on, and the sentence that says so.

    Composed here rather than in a screen, for the reason every label in this module is:
    the register, the detail screen and the vendor's copy must not word one document three
    different ways.
    """
    current = next((i for i, row in enumerate(legs) if row["state"] == "current"), None)
    if current is None:
        # Nothing is outstanding: either it is finished, or it stopped.
        last_done = max((i for i, row in enumerate(legs)
                         if row["state"] in {"completed", "rejected", "cancelled"}),
                        default=0)
        return last_done + 1, (doc.status_label or PURCHASE_RETURN_PHASES[last_done][1])
    return current + 1, f"Waiting: {legs[current]['detail'] or legs[current]['label']}"


async def purchase_return_journey(db: AsyncSession, return_id: int, user=None) -> dict:
    """The whole journey of one purchase return, as a tracker reads it.

    Served on the DOSSIER rather than as an endpoint of its own: the detail screen already
    fetches the dossier, and a second round trip for facts drawn from the same row would
    be a second chance for the two to disagree about where the document is.
    """
    doc = await get_return(db, return_id, user)
    legs = _journey_legs(doc, await _replacement_intake(db, doc))
    sequence, message = _journey_summary(doc, legs)
    return {
        "return_id": doc.id,
        "return_no": doc.return_no,
        "status": doc.status,
        "status_label": doc.status_label,
        "phases": legs,
        "current_sequence": sequence,
        "current_stage_message": message,
    }


async def purchase_return_dossier(db: AsyncSession, return_id: int, user=None) -> dict:
    """The whole paper trail behind one purchase return, and its history, in one call.

    Read-only and side-effect free. `get_return` runs first and is what decides whether
    this login may read the document at all — the trail behind a document must never be
    visible to somebody the document itself is not.

    Nothing here is stored: every row is resolved on read, from the tables that own it.
    """
    doc = await get_return(db, return_id, user)
    documents = await _dossier_documents(db, doc)
    timeline = await _dossier_timeline(db, doc)
    note = None
    if doc.is_manual:
        note = (
            "This return was entered by hand — its vendor and its lines were typed, "
            "not read off a purchase in this system, so there is no buying trail "
            "behind it."
            + (f" The storekeeper's own reference is {doc.source_ref_no}."
               if doc.source_ref_no else ""))
    elif getattr(doc, "chain_traced", False):
        note = (
            "This return names no purchase of its own — it was raised off the stock "
            "coming back. The buying trail below is READ from the goods receipt that "
            "stock arrived on; sending the return to the vendor binds it.")
    elif not any(row["leg"] == "PURCHASE" for row in documents):
        note = ("No purchase trail could be read behind this return. Use Edit to pick "
                "the Purchase Invoice / PO it was bought on.")
    legs = _journey_legs(doc, await _replacement_intake(db, doc))
    sequence, message = _journey_summary(doc, legs)
    return {
        "return_id": doc.id,
        "return_no": doc.return_no,
        "documents": documents,
        "timeline": timeline,
        "trail_note": note,
        # The tracker, on the same call the trail and the history already come on. See
        # `purchase_return_journey` for why it is not an endpoint of its own.
        "journey": legs,
        "current_sequence": sequence,
        "current_stage_message": message,
    }


async def _first_line_by_parent(db: AsyncSession, model, parent_col,
                                parent_ids: list[int]) -> dict[int, object]:
    """The first line of each parent document, in ONE query, keyed by parent id.

    Reads the LINE table rather than walking `parent.items`. Those relationships are
    plain lazy ones (no `lazy="selectin"`), and touching one on an AsyncSession raises
    `MissingGreenlet` — which is exactly what took `purchase_return_source_options`
    down: the receipt loop accessed `grn.items` outside any try/except, so the whole
    endpoint 500'd and the New Purchase Return picker opened empty with no explanation
    anywhere on the screen (fixed 2026-09-10).

    Ordered by `id`, never by `line_no`. Every line table here carries a JSON column,
    MySQL sizes a filesort record by each column's MAXIMUM possible width, and a sort
    over one of them raises 1038 "Out of sort memory" at ANY row count — three rows or
    three million (see the CLAUDE.md note). `id` is the primary key, so reading it is an
    index scan with no sort at all, and for lines the insert order IS the line order.
    """
    if not parent_ids:
        return {}
    rows = (await db.execute(
        select(model).where(parent_col.in_(parent_ids)).order_by(model.id)
    )).scalars().all()
    first: dict[int, object] = {}
    for row in rows:
        first.setdefault(getattr(row, parent_col.key), row)
    return first


async def purchase_return_source_options(db: AsyncSession, params: PageParams, *,
                                         search: str | None = None,
                                         warehouse_id: int | None = None,
                                         user=None) -> dict:
    """Searchable eligible source transactions: GRN / PO / Indent / Item.

    Uses existing SCM data only — no duplicate master.

    Every family's first line comes from `_first_line_by_parent`, one query apiece.
    Nothing in here may touch `parent.items`: see that helper for what happens when it
    does. The PO and indent families are additionally wrapped, because their tables
    belong to earlier modules that a deployment can legitimately not have reachable —
    but the wrapper is for the IMPORT, not for a per-row mistake, and it logs at
    warning now: swallowed at debug, a lazy-load error inside either block silently
    dropped every purchase order and every indent from the picker and looked exactly
    like a site that had none.
    """
    # Scope warehouses for this user
    allowed = await warehouse_ids_for_user(db, user) if user else None
    term = (search or "").strip()
    like = f"%{term}%" if term else None

    # --- GRNs (inb_receipts) — the primary purchase transaction with vendor ---
    grn_stmt = select(m.Receipt).where(m.Receipt.status != ReceiptStatus.CANCELLED.value)
    if allowed is not None:
        grn_stmt = grn_stmt.where(m.Receipt.warehouse_id.in_(allowed or {0}))
    if warehouse_id:
        grn_stmt = grn_stmt.where(m.Receipt.warehouse_id == warehouse_id)
    if like:
        grn_stmt = grn_stmt.where(or_(
            m.Receipt.grn_no.ilike(like),
            m.Receipt.vendor_name.ilike(like),
            m.Receipt.po_no.ilike(like),
            m.Receipt.invoice_no.ilike(like),
        ))
    grn_stmt = grn_stmt.order_by(m.Receipt.id.desc()).limit(20)
    grns = (await db.execute(grn_stmt)).scalars().all()

    options: list[dict] = []
    vendor_cache: dict[int, Vendor] = {}
    grn_first = await _first_line_by_parent(
        db, m.ReceiptItem, m.ReceiptItem.receipt_id, [g.id for g in grns])
    for grn in grns:
        vendor = vendor_cache.get(grn.vendor_id) if grn.vendor_id else None
        if grn.vendor_id and grn.vendor_id not in vendor_cache:
            vendor = await db.get(Vendor, grn.vendor_id)
            vendor_cache[grn.vendor_id] = vendor
        # First item snapshot, for the label only. Off the batched read above — never
        # `grn.items`, which is the lazy relationship that used to 500 this endpoint.
        first_item = grn_first.get(grn.id)
        options.append({
            "source_type": "GRN",
            "source_id": grn.id,
            "source_no": grn.grn_no,
            "source_date": grn.grn_date,
            "vendor_id": grn.vendor_id,
            "vendor_name": grn.vendor_name or (vendor.name if vendor else None),
            "vendor_code": vendor.code if vendor else None,
            "item_id": first_item.item_id if first_item else None,
            "item_code": first_item.item_code if first_item else None,
            "item_name": first_item.item_name if first_item else None,
            "warehouse_id": grn.warehouse_id,
            "warehouse_name": grn.warehouse_name,
            "po_id": grn.po_id,
            "po_no": grn.po_no,
            "grn_id": grn.id,
            "grn_no": grn.grn_no,
            "indent_id": first_item.indent_id if first_item and hasattr(first_item, 'indent_id') else None,
            "indent_no": first_item.indent_no if first_item and hasattr(first_item, 'indent_no') else None,
        })

    # --- POs (pro_purchase_orders) — where GRN not yet created ---
    try:
        from app.modules.procurement.models import PurchaseOrder, POItem
        po_stmt = select(PurchaseOrder).where(PurchaseOrder.status != POStatus.CANCELLED.value)
        if like:
            po_stmt = po_stmt.where(or_(
                PurchaseOrder.po_no.ilike(like),
                PurchaseOrder.vendor_name.ilike(like),
            ))
        po_stmt = po_stmt.order_by(PurchaseOrder.id.desc()).limit(20)
        pos = (await db.execute(po_stmt)).scalars().all()
        po_first = await _first_line_by_parent(
            db, POItem, POItem.po_id, [p.id for p in pos])
        for po in pos:
            vendor = vendor_cache.get(po.vendor_id) if po.vendor_id else None
            if po.vendor_id and po.vendor_id not in vendor_cache:
                vendor = await db.get(Vendor, po.vendor_id)
                vendor_cache[po.vendor_id] = vendor
            first = po_first.get(po.id)
            options.append({
                "source_type": "PO",
                "source_id": po.id,
                "source_no": po.po_no,
                "source_date": po.po_date if hasattr(po, 'po_date') else None,
                "vendor_id": po.vendor_id,
                "vendor_name": po.vendor_name or (vendor.name if vendor else None),
                "vendor_code": vendor.code if vendor else None,
                "item_id": first.item_id if first else None,
                "item_code": first.item_code if first else None,
                "item_name": first.item_name if first else None,
                "warehouse_id": None,
                "warehouse_name": po.facility_name if hasattr(po, 'facility_name') else None,
                "po_id": po.id,
                "po_no": po.po_no,
                "indent_id": po.indent_id if hasattr(po, 'indent_id') else None,
                "indent_no": po.indent_no if hasattr(po, 'indent_no') else None,
            })
    except Exception:
        logger.warning("PO source options skipped — purchase orders will not appear in "
                       "the purchase-return picker", exc_info=True)

    # --- Indents (ind_indents) — for returns against original request ---
    try:
        from app.modules.indents.models import Indent, IndentItem as IItem
        ind_stmt = select(Indent).where(Indent.status.in_([
            IndentStatus.APPROVED.value, IndentStatus.ORDERED.value,
            IndentStatus.CLOSED.value, IndentStatus.PARTIALLY_FULFILLED.value]))
        if like:
            ind_stmt = ind_stmt.where(or_(
                Indent.indent_no.ilike(like),
                Indent.remarks.ilike(like),
            ))
        ind_stmt = ind_stmt.order_by(Indent.id.desc()).limit(20)
        inds = (await db.execute(ind_stmt)).scalars().all()
        ind_first = await _first_line_by_parent(
            db, IItem, IItem.indent_id, [i.id for i in inds])
        for ind in inds:
            # try to resolve vendor via linked PO
            vendor_id = None
            vendor_name = None
            po_id = None
            po_no = None
            try:
                from app.modules.procurement.models import PurchaseOrder as _PO
                po = await db.scalar(select(_PO).where(_PO.indent_id == ind.id).limit(1))
                if po:
                    vendor_id = po.vendor_id
                    vendor_name = po.vendor_name
                    po_id = po.id
                    po_no = po.po_no
            except Exception:
                pass
            first = ind_first.get(ind.id)
            options.append({
                "source_type": "INDENT",
                "source_id": ind.id,
                "source_no": ind.indent_no,
                "source_date": ind.indent_date if hasattr(ind, 'indent_date') else None,
                "vendor_id": vendor_id,
                "vendor_name": vendor_name,
                "vendor_code": None,
                "item_id": first.item_id if first and hasattr(first, 'item_id') else None,
                "item_code": first.item_code if first and hasattr(first, 'item_code') else None,
                "item_name": first.item_name if first and hasattr(first, 'item_name') else None,
                "warehouse_id": None,
                "warehouse_name": None,
                "po_id": po_id,
                "po_no": po_no,
                "indent_id": ind.id,
                "indent_no": ind.indent_no,
            })
    except Exception:
        logger.warning("Indent source options skipped — indents will not appear in the "
                       "purchase-return picker", exc_info=True)

    # Filter by search if term but nothing matched — already filtered per query
    # Sort: GRN first, then PO, then INDENT
    order = {"GRN": 0, "PO": 1, "INDENT": 2}
    options.sort(key=lambda r: (order.get(r["source_type"], 9), r["source_no"]))

    # Paginate in-memory (small set)
    total = len(options)
    page = params.page or 1
    size = params.size or 20
    start = (page - 1) * size
    sliced = options[start:start + size]
    return {"items": sliced, "total": total, "page": page, "size": size}


async def purchase_return_source_lookup(db: AsyncSession, *, doc_no: str,
                                        source_type: str | None = None,
                                        user=None) -> dict:
    """One document, by the number a storekeeper typed in.

    ADDED 2026-09-10. The picker offers the twenty most recent goods receipts, purchase
    orders and indents, and that is the right list to BROWSE — but a storekeeper holding
    a paper indent knows the number and should not have to scroll sixty rows to find it,
    and the document they want is frequently older than any of the sixty. Typing the
    number is the other half of the same question.

    Exact match only, case-insensitive and trimmed. NOT a search: a fuzzy answer here
    would auto-fetch a vendor off the wrong purchase and the storekeeper would have no
    way to tell — the picker beside it is where browsing belongs. Tried in the order the
    numbers are most likely to be held on paper: GRN, then the vendor's own invoice
    number on that GRN, then PO, then indent.

    Warehouse scope is applied to receipts exactly as the picker applies it, so typing a
    number never reaches a document the login could not have picked from the list.
    """
    typed = (doc_no or "").strip()
    if not typed:
        return {"found": False, "can_return": False, "option": None, "message": None}
    wanted = (source_type or "").upper().strip() or None
    if wanted and wanted not in ("GRN", "PO", "INDENT"):
        raise ValidationError(
            f"{wanted} is not a document type you can return against. "
            f"Type a GRN, purchase order or indent number.")
    allowed = await warehouse_ids_for_user(db, user) if user else None

    def answer(option, *, can_return=True, message=None) -> dict:
        return {"found": option is not None, "option": option,
                "can_return": bool(option is not None and can_return),
                "message": message}

    # --- the goods receipt, and the vendor's invoice number written on it -----------
    if wanted in (None, "GRN"):
        stmt = select(m.Receipt).where(
            m.Receipt.status != ReceiptStatus.CANCELLED.value,
            or_(func.lower(m.Receipt.grn_no) == typed.lower(),
                func.lower(m.Receipt.invoice_no) == typed.lower()))
        if allowed is not None:
            stmt = stmt.where(m.Receipt.warehouse_id.in_(allowed or {0}))
        receipt = await db.scalar(stmt.order_by(m.Receipt.id.desc()).limit(1))
        if receipt is not None:
            vendor_id, vendor_name = await _receipt_vendor(db, receipt)
            vendor = await db.get(Vendor, vendor_id) if vendor_id else None
            first = (await _first_line_by_parent(
                db, m.ReceiptItem, m.ReceiptItem.receipt_id, [receipt.id])).get(receipt.id)
            indent_id, indent_no = await _receipt_indent(db, receipt)
            return answer({
                "source_type": "GRN", "source_id": receipt.id,
                "source_no": receipt.grn_no, "source_date": receipt.grn_date,
                "vendor_id": vendor_id,
                "vendor_name": (vendor.name if vendor else None) or vendor_name,
                "vendor_code": vendor.code if vendor else None,
                "item_id": getattr(first, "item_id", None),
                "item_code": getattr(first, "item_code", None),
                "item_name": getattr(first, "item_name", None),
                "warehouse_id": receipt.warehouse_id,
                "warehouse_name": receipt.warehouse_name,
                "po_id": receipt.po_id, "po_no": receipt.po_no,
                "grn_id": receipt.id, "grn_no": receipt.grn_no,
                "indent_id": indent_id, "indent_no": indent_no,
            }, message=(
                None if vendor_id else
                "This goods receipt names no vendor, and none could be read from the "
                "purchase order behind it."), can_return=vendor_id is not None)

    # --- the purchase order --------------------------------------------------------
    if wanted in (None, "PO"):
        try:
            from app.modules.procurement.models import POItem, PurchaseOrder as _PO
            po = await db.scalar(
                select(_PO).where(func.lower(_PO.po_no) == typed.lower(),
                                  _PO.status != POStatus.CANCELLED.value)
                .order_by(_PO.id.desc()).limit(1))
            if po is not None:
                vendor = await db.get(Vendor, po.vendor_id) if po.vendor_id else None
                first = (await _first_line_by_parent(
                    db, POItem, POItem.po_id, [po.id])).get(po.id)
                return answer({
                    "source_type": "PO", "source_id": po.id, "source_no": po.po_no,
                    "source_date": getattr(po, "po_date", None),
                    "vendor_id": po.vendor_id,
                    "vendor_name": po.vendor_name or (vendor.name if vendor else None),
                    "vendor_code": vendor.code if vendor else None,
                    "item_id": getattr(first, "item_id", None),
                    "item_code": getattr(first, "item_code", None),
                    "item_name": getattr(first, "item_name", None),
                    "warehouse_id": None,
                    "warehouse_name": getattr(po, "facility_name", None),
                    "po_id": po.id, "po_no": po.po_no,
                    "grn_id": None, "grn_no": None,
                    "indent_id": getattr(po, "indent_id", None),
                    "indent_no": getattr(po, "indent_no", None)
                    or await _indent_no(db, getattr(po, "indent_id", None)),
                }, message=(
                    None if po.vendor_id else
                    "This purchase order names no vendor."),
                    can_return=po.vendor_id is not None)
        except ValidationError:
            raise
        except Exception:
            logger.warning("Purchase orders not reachable for a typed lookup",
                           exc_info=True)

    # --- the indent ----------------------------------------------------------------
    if wanted in (None, "INDENT"):
        try:
            from app.modules.indents.models import Indent as _Indent
            from app.modules.indents.models import IndentItem as _IndentItem
            indent = await db.scalar(
                select(_Indent).where(func.lower(_Indent.indent_no) == typed.lower())
                .order_by(_Indent.id.desc()).limit(1))
            if indent is not None:
                # The vendor an indent can be returned to is the vendor of the purchase
                # order raised off it — an indent is a REQUEST and names no supplier of
                # its own. Said plainly where there is none, at the moment the number is
                # typed, rather than letting the form fill up and the save refuse it.
                po = None
                try:
                    from app.modules.procurement.models import PurchaseOrder as _PO2
                    po = await db.scalar(
                        select(_PO2).where(_PO2.indent_id == indent.id)
                        .order_by(_PO2.id.desc()).limit(1))
                except Exception:
                    logger.warning("PO behind indent %s not reachable", indent.id,
                                   exc_info=True)
                vendor = await db.get(Vendor, po.vendor_id) if po is not None and po.vendor_id else None
                first = (await _first_line_by_parent(
                    db, _IndentItem, _IndentItem.indent_id, [indent.id])).get(indent.id)
                return answer({
                    "source_type": "INDENT", "source_id": indent.id,
                    "source_no": indent.indent_no,
                    "source_date": getattr(indent, "indent_date", None),
                    "vendor_id": getattr(po, "vendor_id", None),
                    "vendor_name": (vendor.name if vendor else None)
                    or getattr(po, "vendor_name", None),
                    "vendor_code": vendor.code if vendor else None,
                    "item_id": getattr(first, "item_id", None),
                    "item_code": getattr(first, "item_code", None),
                    "item_name": getattr(first, "item_name", None),
                    "warehouse_id": getattr(indent, "warehouse_id", None),
                    "warehouse_name": getattr(indent, "warehouse_name", None),
                    "po_id": getattr(po, "id", None),
                    "po_no": getattr(po, "po_no", None),
                    "grn_id": None, "grn_no": None,
                    "indent_id": indent.id, "indent_no": indent.indent_no,
                }, message=(
                    None if po is not None and po.vendor_id else
                    "No purchase order was raised against this indent, so there is no "
                    "vendor to return the goods to. Type the GRN or PO number the goods "
                    "actually came in on instead."),
                    can_return=po is not None and po.vendor_id is not None)
        except Exception:
            logger.warning("Indents not reachable for a typed lookup", exc_info=True)

    kind = {"GRN": "goods receipt", "PO": "purchase order",
            "INDENT": "indent"}.get(wanted or "", "goods receipt, purchase order or indent")
    return answer(None, message=(
        f"No {kind} numbered “{typed}” was found on your warehouses. Check the number, "
        f"or pick from the list instead."))


async def purchase_return_source_detail(db: AsyncSession, *,
                                        source_type: str,
                                        source_id: int,
                                        item_id: int | None = None) -> dict:
    """Auto-fetch full vendor + item + purchase details for one source.

    Single call, single truth — no manual typing.
    """
    source_type = (source_type or "GRN").upper().strip()
    if source_type not in ("GRN", "PO", "INDENT", "ITEM", "MATERIAL_RECEIPT"):
        if source_type == "MATERIAL_RECEIPT":
            source_type = "GRN"
        else:
            raise ValidationError(f"Unknown source type {source_type}")

    vendor_out = s.VendorDetailOut()
    purchase = s.PurchaseDetailsOut()
    item_details: list[s.ItemDetailOut] = []
    warehouse_id = None
    warehouse_name = None
    source_no = ""
    # ---- GRN ----
    if source_type == "GRN":
        receipt = await _load(db, m.Receipt, source_id, "Purchase Invoice/GRN", m.Receipt.items)
        source_no = receipt.grn_no
        purchase.grn_id = receipt.id
        purchase.grn_no = receipt.grn_no
        purchase.receipt_id = receipt.id
        purchase.receipt_no = receipt.grn_no
        purchase.receipt_date = receipt.grn_date
        purchase.po_id = receipt.po_id
        purchase.po_no = receipt.po_no
        purchase.invoice_no = receipt.invoice_no
        purchase.invoice_date = receipt.invoice_date
        purchase.indent_id = None
        warehouse_id = receipt.warehouse_id
        warehouse_name = receipt.warehouse_name
        # Indent linkage: the receipt's own lines where they carry it, the purchase
        # order behind it where they do not (see `_receipt_indent`).
        purchase.indent_id, purchase.indent_no = await _receipt_indent(db, receipt)

        # Vendor — full master auto-fetch
        vendor = await db.get(Vendor, receipt.vendor_id) if receipt.vendor_id else None
        if vendor:
            vendor_out.vendor_id = vendor.id
            vendor_out.vendor_code = vendor.code
            vendor_out.vendor_name = vendor.name
            vendor_out.contact_person = vendor.contact_person
            vendor_out.phone = vendor.phone
            vendor_out.email = vendor.email
            vendor_out.address = vendor.address
            vendor_out.city = vendor.city
            vendor_out.state = vendor.state
            vendor_out.pincode = vendor.pincode
            vendor_out.gstin = vendor.gstin
        else:
            vendor_out.vendor_id = receipt.vendor_id
            vendor_out.vendor_name = receipt.vendor_name
            vendor_out.vendor_code = None

        # Per-item returnable computation (reuse caps logic)
        # original = rejected_qty >0 ? rejected_qty : received_qty
        already_by_grn_item: dict[int, Decimal] = {}
        already_rows = (await db.execute(
            select(m.PurchaseReturnItem.grn_item_id,
                   func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
            .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
            .where(m.PurchaseReturn.grn_id == receipt.id,
                   m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                   m.PurchaseReturnItem.grn_item_id.isnot(None))
            .group_by(m.PurchaseReturnItem.grn_item_id)
        )).all()
        for gid, qty in already_rows:
            already_by_grn_item[gid] = _d(qty)

        for line in receipt.items:
            if item_id and line.item_id != item_id:
                continue
            item = await db.get(Item, line.item_id)
            original = _grn_line_returnable(line)
            if original <= ZERO:
                original = _d(line.ordered_qty) if hasattr(line, 'ordered_qty') else _d(line.received_qty)
            previously = already_by_grn_item.get(line.id, ZERO)
            returnable = max(original - previously, ZERO)
            # batch/lot
            batch = await db.get(m.Batch, line.batch_id) if getattr(line, 'batch_id', None) else None
            unit_price = _d(line.rate) or None
            item_details.append(s.ItemDetailOut(
                **combinations.carry(line),
                item_id=line.item_id,
                item_code=line.item_code or (item.code if item else None),
                item_name=line.item_name or (item.name if item else None),
                description=item.description if item else None,
                uom_code=line.uom_code or (item.uom_code if item else None),
                batch_no=line.batch_no or (batch.batch_no if batch else None),
                batch_id=getattr(line, 'batch_id', None),
                serial_no=None,
                grn_item_id=line.id,
                original_qty=original,
                previously_returned=previously,
                returnable_qty=returnable,
                unit_price=unit_price,
                amount=(returnable * unit_price) if unit_price else None,
                warehouse_id=receipt.warehouse_id,
                warehouse_name=receipt.warehouse_name,
            ))
        if not item_details:
            raise ValidationError(f"GRN {receipt.grn_no} has no eligible lines for the selected item")

    elif source_type == "PO":
        from app.modules.procurement.models import PurchaseOrder, POItem
        po = await _get(db, PurchaseOrder, source_id, "Purchase Order")
        source_no = po.po_no
        purchase.po_id = po.id
        purchase.po_no = po.po_no
        purchase.order_date = po.po_date if hasattr(po, 'po_date') else None
        purchase.indent_id = po.indent_id if hasattr(po, 'indent_id') else None
        purchase.indent_no = po.indent_no if hasattr(po, 'indent_no') else None
        # vendor
        vendor = await db.get(Vendor, po.vendor_id) if po.vendor_id else None
        if vendor:
            vendor_out.vendor_id = vendor.id
            vendor_out.vendor_code = vendor.code
            vendor_out.vendor_name = vendor.name
            vendor_out.contact_person = vendor.contact_person
            vendor_out.phone = vendor.phone
            vendor_out.email = vendor.email
            vendor_out.address = vendor.address
            vendor_out.city = vendor.city
            vendor_out.state = vendor.state
            vendor_out.pincode = vendor.pincode
            vendor_out.gstin = vendor.gstin
        else:
            vendor_out.vendor_id = po.vendor_id
            vendor_out.vendor_name = po.vendor_name
        # linked warehouse via receipt or indent
        # try receipt
        receipt = await db.scalar(select(m.Receipt).where(m.Receipt.po_id == po.id).limit(1))
        if receipt:
            warehouse_id = receipt.warehouse_id
            warehouse_name = receipt.warehouse_name
            purchase.grn_id = receipt.id
            purchase.grn_no = receipt.grn_no
        # items: po lines
        po_items_stmt = select(POItem).where(POItem.po_id == po.id)
        if item_id:
            po_items_stmt = po_items_stmt.where(POItem.item_id == item_id)
        po_items = (await db.execute(po_items_stmt)).scalars().all()
        # already returned per po_item
        already_by_po_item: dict[int, Decimal] = {}
        already_po = (await db.execute(
            select(m.PurchaseReturnItem.po_item_id,
                   func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
            .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
            .where(m.PurchaseReturn.po_id == po.id,
                   m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                   m.PurchaseReturnItem.po_item_id.isnot(None))
            .group_by(m.PurchaseReturnItem.po_item_id)
        )).all()
        for pid, qty in already_po:
            already_by_po_item[pid] = _d(qty)
        for line in po_items:
            item = await db.get(Item, line.item_id)
            original = _d(line.quantity)
            previously = already_by_po_item.get(line.id, ZERO)
            returnable = max(original - previously, ZERO)
            unit_price = _d(line.rate) or None
            item_details.append(s.ItemDetailOut(
                **combinations.carry(line),
                item_id=line.item_id,
                item_code=line.item_code or (item.code if item else None),
                item_name=line.item_name or (item.name if item else None),
                description=item.description if item else None,
                uom_code=line.uom_code or (item.uom_code if item else None),
                batch_no=None,
                batch_id=None,
                po_item_id=line.id,
                original_qty=original,
                previously_returned=previously,
                returnable_qty=returnable,
                unit_price=unit_price,
                amount=(returnable * unit_price) if unit_price else None,
                warehouse_id=warehouse_id,
                warehouse_name=warehouse_name,
            ))

    elif source_type == "INDENT":
        from app.modules.indents.models import Indent, IndentItem
        indent = await _get(db, Indent, source_id, "Indent")
        source_no = indent.indent_no
        purchase.indent_id = indent.id
        purchase.indent_no = indent.indent_no
        # vendor via linked PO if any
        try:
            from app.modules.procurement.models import PurchaseOrder as _PO
            po = await db.scalar(select(_PO).where(_PO.indent_id == indent.id).limit(1))
            if po:
                vendor = await db.get(Vendor, po.vendor_id) if po.vendor_id else None
                if vendor:
                    vendor_out.vendor_id = vendor.id
                    vendor_out.vendor_code = vendor.code
                    vendor_out.vendor_name = vendor.name
                    vendor_out.contact_person = vendor.contact_person
                    vendor_out.phone = vendor.phone
                    vendor_out.email = vendor.email
                    vendor_out.address = vendor.address
                    vendor_out.city = vendor.city
                    vendor_out.state = vendor.state
                    # Both were missing here while the GRN and PO branches above set
                    # them, so an indent-sourced return auto-fetched a vendor whose
                    # address ended at the state and whose GSTIN read as "—" — the one
                    # field the vendor argues a return against.
                    vendor_out.pincode = vendor.pincode
                    vendor_out.gstin = vendor.gstin
                else:
                    vendor_out.vendor_id = po.vendor_id
                    vendor_out.vendor_name = po.vendor_name
                purchase.po_id = po.id
                purchase.po_no = po.po_no
        except Exception:
            # Never silent: this block is the whole vendor auto-fetch for an
            # indent-sourced return, and swallowing it left the vendor card blank with
            # nothing said anywhere about why.
            logger.warning("Vendor could not be read from the PO behind indent %s",
                           indent.id, exc_info=True)
        # items
        stmt = select(IndentItem).where(IndentItem.indent_id == indent.id)
        if item_id:
            stmt = stmt.where(IndentItem.item_id == item_id)
        lines = (await db.execute(stmt)).scalars().all()
        for line in lines:
            item = await db.get(Item, line.item_id) if hasattr(line, 'item_id') else None
            # indent quantity fields vary by version
            original = _d(getattr(line, 'quantity', None) or getattr(line, 'approved_qty', None) or getattr(line, 'requested_qty', 0))
            # previously returned via purchase returns linked to this indent (not direct; use po linkage)
            previously = ZERO
            returnable = max(original - previously, ZERO)
            item_details.append(s.ItemDetailOut(
                **combinations.carry(line),
                item_id=getattr(line, 'item_id', 0),
                item_code=getattr(line, 'item_code', None) or (item.code if item else None),
                item_name=getattr(line, 'item_name', None) or (item.name if item else None),
                description=item.description if item else None,
                uom_code=getattr(line, 'uom_code', None) or (item.uom_code if item else None),
                batch_no=None,
                batch_id=None,
                original_qty=original,
                previously_returned=previously,
                returnable_qty=returnable,
                warehouse_id=warehouse_id,
                warehouse_name=warehouse_name,
            ))

    elif source_type == "ITEM":
        if not item_id:
            item_id = source_id
        item = await _get(db, Item, int(item_id), "Item")
        source_no = item.code
        # vendor via preferred vendor_items
        vendor_item = await db.scalar(
            select(Vendor).join(s.Item, False)  # placeholder
        ) if False else None
        # find preferred vendor for item
        from app.shared.models.master import VendorItem as _VI
        vi = await db.scalar(select(_VI).where(_VI.item_id == item.id, _VI.is_preferred.is_(True)).limit(1))
        if vi:
            vendor = await db.get(Vendor, vi.vendor_id)
            if vendor:
                vendor_out.vendor_id = vendor.id
                vendor_out.vendor_code = vendor.code
                vendor_out.vendor_name = vendor.name
                vendor_out.contact_person = vendor.contact_person
                vendor_out.phone = vendor.phone
                vendor_out.email = vendor.email
                vendor_out.address = vendor.address
                vendor_out.city = vendor.city
                vendor_out.state = vendor.state
        # warehouse: caller's primary location?
        item_details.append(s.ItemDetailOut(
            item_id=item.id,
            item_code=item.code,
            item_name=item.name,
            description=item.description,
            uom_code=item.uom_code,
            batch_no=None,
            batch_id=None,
            original_qty=ZERO,
            previously_returned=ZERO,
            returnable_qty=ZERO,
            warehouse_id=None,
            warehouse_name=None,
        ))

    total_orig = sum((_d(it.original_qty) for it in item_details), ZERO)
    total_prev = sum((_d(it.previously_returned) for it in item_details), ZERO)
    total_ret = sum((_d(it.returnable_qty) for it in item_details), ZERO)

    return {
        "source_type": source_type,
        "source_id": source_id,
        "source_no": source_no,
        "vendor": vendor_out.model_dump() if hasattr(vendor_out, 'model_dump') else vendor_out,
        "items": [it.model_dump() if hasattr(it, 'model_dump') else it for it in item_details],
        "purchase": purchase.model_dump() if hasattr(purchase, 'model_dump') else purchase,
        "warehouse_id": warehouse_id,
        "warehouse_name": warehouse_name,
        "total_original_qty": total_orig,
        "total_previously_returned": total_prev,
        "total_returnable_qty": total_ret,
    }


async def send_to_vendor(db: AsyncSession, return_id: int, data: s.PurchaseReturnSendToVendorIn, user) -> m.PurchaseReturn:
    """Warehouse → Vendor: the single 'Send to Vendor' commitment.

    1. Validate the return is sendable - a DRAFT, or APPROVED by its ladder
    2. Validate return quantity ≤ returnable, vendor locked to source, all required fields
    3. Create/link Existing Logistics transaction (out_dispatches VENDOR_RETURN)
    4. Flip -> SENT_TO_VENDOR, stamp sent_at, keep the dispatch link for the trail
    5. A SENT_TO_VENDOR row can never be sent again.
    """
    doc = await _load(db, m.PurchaseReturn, return_id, "Return", m.PurchaseReturn.items)
    # Status guard — only a DRAFT can be sent; everything sent/settled is refused.
    if doc.status == ReturnStatus.CANCELLED.value:
        raise ValidationError("A cancelled return cannot be sent to vendor")
    if doc.status == ReturnStatus.SENT_TO_VENDOR.value:
        raise ValidationError("This Purchase Return has already been sent to the vendor")
    if doc.status == ReturnStatus.COMPLETED.value:
        raise ValidationError("This return is already completed")
    if doc.status == ReturnStatus.DISPATCHED.value:
        raise ValidationError("This return has already been dispatched to the vendor")
    if doc.status == ReturnStatus.PENDING_APPROVAL.value:
        raise ValidationError(
            "This Purchase Return is waiting for approval. It can be sent to the "
            "vendor once it has been approved.")
    if doc.status not in SENDABLE_RETURN_STATUSES:
        raise ValidationError(
            f"A Purchase Return can be sent to the vendor while it is a draft, or "
            f"once it has been approved. This return is {doc.status}.")

    # Validate reason
    valid_reasons = {v for v, _ in s.PURCHASE_RETURN_REASONS}
    if data.return_reason not in valid_reasons:
        raise ValidationError(f"Return reason must be one of: {', '.join(sorted(valid_reasons))}")
    if data.return_reason == "OTHER" and not (data.remarks or "").strip():
        raise ValidationError("Remarks are required when reason is Other")

    # How it travels. Checked HERE, before either branch below commits anything, so a
    # half-answered wizard is refused with the document still a DRAFT the storekeeper
    # can go back and finish — rather than after the status has already flipped.
    # Absent on purpose is not an error: the block is optional, and a caller that
    # predates the wizard sends exactly what it always did. See the schema.
    logistics_mode = (_validate_return_logistics(data.logistics)
                      if data.logistics is not None else None)

    # --- a MANUAL return goes out on its own terms ----------------------------------
    #
    # There is no source document to bind, no vendor to re-lock against one, and no
    # returnable cap to re-check — the figures beside each line ARE the storekeeper's
    # figures, checked against each other in `_apply_manual_return_lines`.
    #
    # NO `out_dispatches` RECORD IS RAISED, and that is deliberate rather than an
    # omission. A dispatch line requires a master `item_id` (`out_dispatch_items` is
    # NOT NULL on it and is the logistics module's table, shared with consignments), and
    # a manual return exists precisely because its goods are not in the masters. Filing
    # invented lines into the logistics register to satisfy a foreign key would put
    # stock movements on the books for goods this system never held. The document still
    # records that it went, and when it went, which is the fact being asserted.
    if doc.is_manual:
        if not (doc.vendor_name or "").strip() and not doc.vendor_id:
            raise ValidationError(
                "Enter the vendor's name before sending — the return has to say who "
                "the goods are going back to.")
        # LAST CHANCE TO BIND, for every manual return raised before the typed name was
        # matched against the master at all. Those rows carry a name and a null
        # `vendor_id`, so sending them put the goods on the road with no supplier able to
        # see the document. Only ever fills a null — a return already bound is left
        # exactly as it is.
        if not doc.vendor_id:
            matched = await _match_manual_vendor(
                db, doc.vendor_name, doc.manual_vendor_code, doc.manual_vendor_gstin)
            if matched:
                doc.vendor_id = matched.id
        if data.items:
            await _apply_manual_return_lines(db, doc, data.items)
        if not doc.items:
            raise ValidationError("A return with no lines sends nothing back")
        before_status = doc.status
        doc.reason = data.return_reason
        doc.remarks = (data.remarks or "").strip() or None
        doc.status = ReturnStatus.SENT_TO_VENDOR.value
        doc.sent_at = utcnow()
        # The wizard's logistics answers, kept in the AUDIT TRAIL and nowhere else.
        # A manual return raises no `out_dispatches` row — see the block above for
        # why, and it has not changed — so there is no consignment to hang a
        # transport mode on. The trail is a real, structured, permanent record, and
        # losing what the storekeeper typed because the destination column does not
        # exist would be worse than filing it here.
        after = {"status": doc.status, "is_manual": True,
                 "vendor_name": doc.vendor_name,
                 "sent_at": doc.sent_at.isoformat() if doc.sent_at else None,
                 "reason": doc.reason}
        if logistics_mode:
            after["logistics"] = _logistics_audit(data.logistics, logistics_mode)
        await write_audit(
            db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
            action=AuditAction.UPDATE, actor=user,
            before={"status": before_status},
            after=after)
        await db.commit()
        return await get_return(db, doc.id, user)

    # Bind source if provided — but never to a different vendor than the locked one.
    if data.grn_id:
        receipt = await db.get(m.Receipt, data.grn_id)
        if not receipt:
            raise NotFoundError(f"Purchase Invoice/GRN {data.grn_id} not found")
        if receipt.vendor_id and doc.vendor_id and int(receipt.vendor_id) != int(doc.vendor_id):
            raise ValidationError(
                "Vendor must come from the selected Purchase Invoice/PO and cannot be changed.")
        doc.grn_id = receipt.id
        doc.grn_no = receipt.grn_no
        if not doc.po_id and receipt.po_id:
            doc.po_id = receipt.po_id
            doc.po_no = receipt.po_no
        if not doc.vendor_id:
            # Through the PO where the GRN names no vendor — see `_receipt_vendor`.
            # Without this the send bound the GRN and then refused the document a
            # line later for having no vendor to send it to.
            doc.vendor_id, doc.vendor_name = await _receipt_vendor(db, receipt)
        if not doc.warehouse_id and receipt.warehouse_id:
            doc.warehouse_id = receipt.warehouse_id
            doc.warehouse_name = receipt.warehouse_name
    if data.po_id:
        try:
            from app.modules.procurement.models import PurchaseOrder as _PO2
            po = await db.get(_PO2, data.po_id)
            if not po:
                raise NotFoundError(f"Purchase Order {data.po_id} not found")
            if po.vendor_id and doc.vendor_id and int(po.vendor_id) != int(doc.vendor_id):
                raise ValidationError(
                    "Vendor must come from the selected Purchase Invoice/PO and cannot be changed.")
            doc.po_id = po.id
            doc.po_no = po.po_no
            if not doc.vendor_id:
                doc.vendor_id = po.vendor_id
                doc.vendor_name = po.vendor_name
        except (NotFoundError, ValidationError):
            raise
        except Exception:
            doc.po_id = data.po_id
    if data.vendor_id:
        if doc.vendor_id and int(data.vendor_id) != int(doc.vendor_id):
            raise ValidationError(
                "Vendor must come from the selected Purchase Invoice/PO and cannot be changed.")
        vendor = await db.get(Vendor, data.vendor_id)
        if not vendor:
            raise NotFoundError(f"Vendor {data.vendor_id} not found")
        doc.vendor_id = vendor.id
        doc.vendor_name = vendor.name
    if data.warehouse_id:
        wh = await db.get(Warehouse, data.warehouse_id)
        if not wh:
            raise NotFoundError(f"Warehouse {data.warehouse_id} not found")
        doc.warehouse_id = wh.id
        doc.warehouse_name = wh.name

    # Final vendor/warehouse validation
    if not doc.vendor_id:
        raise ValidationError("Vendor is required — select a purchase transaction to auto-fetch vendor")
    if not doc.warehouse_id:
        raise ValidationError("Warehouse is required — select a purchase transaction to auto-fetch warehouse")

    # Validate stock/return eligibility & apply lines with returnable check
    # Build caps for validation message
    caps: dict[int | None, Decimal] = {}
    if doc.grn_id:
        receipt = await _load(db, m.Receipt, doc.grn_id, "Receipt", m.Receipt.items)
        caps_by_grn = {l.id: _grn_line_returnable(l) for l in receipt.items}
        already = (await db.execute(
            select(m.PurchaseReturnItem.grn_item_id, func.coalesce(func.sum(m.PurchaseReturnItem.quantity), 0))
            .join(m.PurchaseReturn, m.PurchaseReturn.id == m.PurchaseReturnItem.return_id)
            .where(m.PurchaseReturn.grn_id == doc.grn_id,
                   m.PurchaseReturn.id != doc.id,
                   m.PurchaseReturn.status != ReturnStatus.CANCELLED.value,
                   m.PurchaseReturnItem.grn_item_id.isnot(None))
            .group_by(m.PurchaseReturnItem.grn_item_id)
        )).all()
        for gid, qty in already:
            caps_by_grn[gid] = max(caps_by_grn.get(gid, ZERO) - _d(qty), ZERO)
        caps = caps_by_grn
        # Validate each incoming line against cap
        for line in data.items:
            cap = caps.get(line.grn_item_id) if line.grn_item_id else None
            if cap is not None and _d(line.quantity) > cap:
                raise ValidationError(
                    f"Return quantity cannot exceed the available returnable quantity of {cap}.")

    # Also validate requested qty not negative and item exists
    for idx, line in enumerate(data.items, start=1):
        if _d(line.quantity) <= ZERO:
            raise ValidationError(f"Line {idx}: return quantity must be greater than 0")
        if not line.item_id:
            # Optional on the schema because manual lines exist; a sourced send still
            # needs it, and reaching `_item_snapshot` with None raised a 500 instead.
            raise ValidationError(
                f"Line {idx}: pick the item from the source document.")
        await _item_snapshot(db, line.item_id)

    # Apply lines (also re-checks cap)
    await _apply_return_lines(db, doc, data.items)
    doc.reason = data.return_reason
    doc.remarks = (data.remarks or "").strip() or None

    # THE QC THAT CONDEMNED THE GOODS, bound here for the same reason the GRN, the PO and
    # the vendor are bound here: sending is what turns a read of the trail into a claim
    # against a supplier, and the inspection is the evidence behind the claim. Only ever
    # written where it is not already set — a return raised off a branch consignment
    # carries its own QC from birth and that one is the better answer.
    await _bind_return_inspection(db, doc)

    # Update return status — DRAFT -> SENT_TO_VENDOR.
    #
    # NOTHING PHYSICAL HAPPENS HERE, and that is the change of 2026-09-12. This press used
    # to raise the `out_dispatches` consignment AND a logistics leg, so the goods left the
    # warehouse in the same breath as the paperwork and the vendor was asked to approve a
    # consignment already standing on their dock. The business does it the other way
    # round: the vendor reads the return against the GRN/PO/QC and says yes or no, then
    # says refund or replacement, and only then does this warehouse decide whose vehicle
    # carries the goods. The consignment and the leg are raised at that decision instead —
    # see `arrange_return_transport`. A document that has gone out for an answer has moved
    # no stock, so rule 7 has nothing to say about this function any more.
    before = doc.status
    doc.status = ReturnStatus.SENT_TO_VENDOR.value
    doc.sent_at = utcnow()

    sent_after = {"status": doc.status, "vendor_id": doc.vendor_id,
                  "grn_no": doc.grn_no, "po_no": doc.po_no,
                  "inspection_no": doc.inspection_no,
                  "total_qty": str(doc.total_qty),
                  "reason": doc.reason,
                  "sent_at": doc.sent_at.isoformat() if doc.sent_at else None}
    # A caller that still states how the goods travel is VALIDATED as before (a
    # half-answered block is refused, and the document stays a DRAFT they can finish) but
    # no longer acted on here — nothing travels until the vendor has answered and the
    # transport decision has been taken. Kept on the TRAIL rather than dropped, because
    # what somebody typed is a real record and losing it silently is worse than filing it
    # somewhere the transport step can read it back.
    if logistics_mode:
        sent_after["logistics_stated_at_send"] = _logistics_audit(data.logistics,
                                                                  logistics_mode)
    await write_audit(db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
                      action=AuditAction.UPDATE, actor=user,
                      before={"status": before},
                      after=sent_after,
                      summary=(f"Purchase Return {doc.return_no} sent to "
                               f"{doc.vendor_name or 'the vendor'} for their decision"))
    await db.commit()

    enriched = await _load(db, m.PurchaseReturn, doc.id, "Return", m.PurchaseReturn.items)
    await _decorate_purchase_return(db, enriched)
    return await _decorate_can_approve(db, enriched, WarehouseDocType.PURCHASE_RETURN.value, user)


async def _bind_return_inspection(db: AsyncSession, doc: m.PurchaseReturn) -> None:
    """Name the QC inspection behind this return's goods receipt, if it has none yet.

    NEVER OVERWRITES. A return raised automatically off a branch consignment already
    carries the inspection its own chain named, and that one was resolved with the
    returned items in hand — this one is resolved from the GRN alone. Where both exist the
    earlier answer is the better answer, so this only fills a blank.

    The latest NON-CANCELLED inspection against the receipt, which is the same query
    `_dossier_documents` has always used for the trail row, with the status filter it was
    missing — a cancelled or rejected inspection winning on `MAX(id)` would name the one
    piece of evidence that was withdrawn.

    Silent where there is nothing to name: a return with no GRN, or a GRN nobody
    inspected, keeps a null QC rather than borrowing somebody else's.
    """
    if doc.inspection_no or not doc.grn_id:
        return
    qc = await db.scalar(
        select(m.Inspection)
        .where(m.Inspection.receipt_id == doc.grn_id,
               m.Inspection.status.notin_([InspectionStatus.CANCELLED.value,
                                           InspectionStatus.REJECTED.value]))
        .order_by(m.Inspection.id.desc()).limit(1))
    if qc is not None:
        doc.inspection_id = qc.id
        doc.inspection_no = qc.inspection_no


async def _build_return_consignment(db: AsyncSession, doc: m.PurchaseReturn, user,
                                    logistics_mode: str | None,
                                    logistics: "s.PurchaseReturnLogisticsIn | None",
                                    ) -> m.Dispatch:
    """The warehouse's own outward document for the goods going back to the vendor.

    MOVED OUT OF `send_to_vendor` on 2026-09-12 (it was inline there) and into the
    transport decision, because that is when the load actually travels. Byte-for-byte the
    same document it always was — same `ref_type`, same `DispatchStatus.APPROVED`, same
    lines — so `transport_released` -> `_apply_gate_out` settles it exactly as before and
    the stock side never had two copies. What changed is only the moment it is raised.

    Left at APPROVED rather than despatched: the goods are still on our floor, and the
    gate-out is the logistics release (branch B) or the vendor's own pickup (branch A).
    """
    vendor = await db.get(Vendor, doc.vendor_id) if doc.vendor_id else None
    wh = await db.get(Warehouse, doc.warehouse_id) if doc.warehouse_id else None
    dispatch = m.Dispatch(
        dispatch_no=await _consignment_no(db),
        dispatch_type=DispatchType.VENDOR_RETURN.value if hasattr(DispatchType, 'VENDOR_RETURN') else "VENDOR_RETURN",
        dispatch_date=ist_today() if 'ist_today' in globals() else date.today(),
        warehouse_id=doc.warehouse_id,
        warehouse_name=wh.name if wh else doc.warehouse_name,
        warehouse_address=wh.address if wh else None,
        vendor_id=doc.vendor_id,
        vendor_name=vendor.name if vendor else doc.vendor_name,
        delivery_address=_vendor_address(vendor) if vendor else None,
        contact_person=vendor.contact_person if vendor and vendor.contact_person else None,
        contact_phone=vendor.phone if vendor else None,
        ref_type="PURCHASE_RETURN",
        ref_id=doc.id,
        ref_no=doc.return_no,
        status=DispatchStatus.APPROVED.value,
        total_items=len(doc.items),
        total_qty=sum((_d(l.quantity) for l in doc.items), ZERO),
        total_packages=len(doc.items),
        total_value=sum((_d(l.amount) for l in doc.items), ZERO),
        remarks=(f"Purchase Return {doc.return_no} → Vendor "
                 f"{vendor.name if vendor else doc.vendor_name}"
                 + (f" | Reason: {doc.reason}" if doc.reason else "")
                 + (f" | {doc.remarks}" if doc.remarks else "")),
        created_by_id=getattr(user, "id", None),
        created_by_name=_name(user),
    )
    # How it travels, who signed, and what left the gate — applied AFTER the defaults
    # above are set, because several of its fields (the delivery point, the package
    # count) refine a value the vendor master or the line count already seeded.
    if logistics_mode and logistics is not None:
        _apply_return_logistics(dispatch, logistics, logistics_mode)
    db.add(dispatch)
    await db.flush()
    # Dispatch items
    for idx, line in enumerate(doc.items, start=1):
        batch = await db.get(m.Batch, line.batch_id) if line.batch_id else None
        # A manual line typed before the code was resolved at save carries no item id,
        # and `out_dispatch_items.item_id` is NOT NULL — the raw database refusal came
        # back to the desk as "item_id is required" on a form where the item was plainly
        # filled in. Resolve the code here too, and say which line if it names nothing.
        item_id = line.item_id
        if not item_id:
            found = await _item_by_code(db, line.item_code)
            if found is not None:
                item_id = line.item_id = found.id
                line.item_code = found.code
                line.uom_code = line.uom_code or found.uom_code
        if not item_id:
            named = f" - the code {line.item_code} matches none" if line.item_code else ""
            raise ValidationError(
                f"Line {idx} ({line.item_name or 'no name'}) is not linked to an item "
                f"in the master{named}. Open the return, pick the item from the master "
                "and save it, then arrange transport: the consignment and the stock "
                "movement are both keyed on it.")
        db.add(m.DispatchItem(
            dispatch_id=dispatch.id,
            line_no=idx,
            item_id=item_id,
            item_code=line.item_code,
            item_name=line.item_name,
            uom_code=line.uom_code,
            batch_id=line.batch_id,
            batch_no=line.batch_no or (batch.batch_no if batch else None),
            quantity=_d(line.quantity),
            rate=_d(line.rate) if line.rate else None,
            amount=_d(line.amount) if line.amount else None,
            remarks=line.reason,
            **combinations.carry(line),
        ))
    await db.flush()

    # The link the serializer reads, and the one `_decorate_return_dispatch` will find on
    # every later load off `out_dispatches` directly.
    doc.dispatch_id = dispatch.id
    doc.dispatch_no = dispatch.dispatch_no

    dispatch_after = {"ref_type": "PURCHASE_RETURN", "ref_no": doc.return_no,
                      "vendor": doc.vendor_name, "warehouse": doc.warehouse_name}
    if logistics_mode and logistics is not None:
        dispatch_after["logistics"] = _logistics_audit(logistics, logistics_mode)
    await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                      entity_no=dispatch.dispatch_no,
                      action=AuditAction.CREATE, actor=user,
                      after=dispatch_after)
    return dispatch


# ---------------------------------------------------------------------------
# After SENT_TO_VENDOR: the vendor's decision, and the journey the goods then make
# ---------------------------------------------------------------------------
#
# THE FLOW, in the order a person works it, and WHO presses each button:
#
#   SENT_TO_VENDOR ──Reject (VENDOR, remarks required)──> REJECTED         (terminal)
#                  ──Approve (VENDOR)──────────────────> VENDOR_APPROVED
#                        ├─ Refund (VENDOR) ───────────> REFUNDED          (terminal)
#                        └─ Replacement (VENDOR) ──────> REPLACEMENT_AGREED
#                              │
#                              └─ whose vehicle? (WAREHOUSE)
#                                   ├─ Vendor arranges
#                                   │    -> AWAITING_VENDOR_VEHICLE
#                                   │    -> VENDOR accepts the job
#                                   │         -> VENDOR_TRANSPORT_ACCEPTED
#                                   │    -> VENDOR records the pickup
#                                   │         -> STOCK_PICKED_UP
#                                   └─ Warehouse requests a vehicle
#                                        -> VEHICLE_REQUESTED   (leg raised in Logistics)
#                                        -> STOCK_PICKED_UP     (logistics releases it)
#                              -> VENDOR_RECEIVED          (VENDOR signs at their dock)
#                              -> REPLACEMENT_DISPATCHED   (VENDOR's dispatch note, which
#                                                           raises the DRAFT GRN)
#                              -> RECEIVED_AT_WAREHOUSE    (the store SUBMITS that GRN)
#                                   -> QC inspection on the same GRN
#                                   -> putaway, once QC has passed it
#                              -> COMPLETED                (the last putaway closes it)
#
# THE TAIL IS THE STORE'S ORDINARY INWARD PATH (2026-09-14). Everything after the vendor's
# dispatch note happens on documents that already exist — the goods receipt, its
# inspection, its putaway tasks — worked on the screens the store already works, with the
# guards those documents already carry. Nothing about a replacement is booked in, inspected
# or placed differently from any other delivery, which is why there is no second ladder
# here: `RECEIVED_AT_WAREHOUSE` is where the return stands for the whole of it, and
# `_close_return_on_intake_complete` is the single hook that ends it when the receipt
# reaches COMPLETED. The journey READS those three rungs (`_replacement_intake`) so a
# person chasing the return can see them without opening three other documents.
#
# WHO DECIDES CHANGED on 2026-09-12. Approve/Reject and Refund/Replacement used to be
# OUR desk's presses, on a return whose goods had already gone out with the send. They
# are the VENDOR's, made on their own portal against paperwork, before anything travels.
# `decide_sent_return` and `arrange_return_vehicle` are gone with that change; the desk
# keeps exactly one press in this whole sequence — `arrange_return_transport`, which is
# the only question the business actually asks this warehouse.
#
# Every press below follows rule 9 — load, validate the CURRENT status, change it, write
# the audit row, commit — and every audit row is written against `pro_returns`, which is
# what puts the whole of this on the document's own History tab and its Journey
# (`_dossier_timeline` unions `sys_audit_log` for this entity). Nothing here writes a
# second history table.
#
# DUPLICATE PRESSES ARE REFUSED BY THE RUNGS THEMSELVES. Each press guards on its own
# frozenset from `enums` (`RETURN_DECIDABLE_STATUSES` and friends) and the act moves the
# document off that rung, so the second press is refused by the same test that refuses an
# early one. Nothing needs a separate "already done" flag, and the served `can_*` flags
# are computed from the same sets so the screen and the server cannot disagree.
#
# WHAT IS DELIBERATELY NOT HERE: no stock moves on any of these presses. Stock leaves the
# books through `_apply_gate_out` on the consignment — the shared path the logistics
# release and the vendor pickup both go through — and `complete_return` still owns the
# close. These rungs record where the goods ARE, which is a different question from what
# they are worth to us (rule 7 — stock changes only through `move_stock()`).


def _decision_guard(doc: m.PurchaseReturn, what: str) -> None:
    """Refuse a press the document is not standing at, in words that say why.

    Its own function because every press below needs the same sentence shape, and a
    reader hitting "cannot approve a DRAFT" needs to be told what CAN be done with a
    draft rather than only that this cannot.

    `status_label` is read with `getattr` because it is a TRANSIENT assigned by
    `_decorate_purchase_return`, and every caller here loads the row raw — `_load` and
    `_vendor_return` both return an undecorated instance. Reading it directly raised
    AttributeError instead of this ValidationError, so a press made one rung too early
    came back as a 500 with no explanation rather than the sentence written below. It is
    a fallback anyway: the raw status is what every filter matches on.
    """
    raise ValidationError(
        f"{doc.return_no} is {getattr(doc, 'status_label', None) or doc.status} — {what}")


async def vendor_decide_return(db: AsyncSession, vendor_id: int, return_id: int,
                               data: "s.VendorReturnDecisionIn"):
    """The VENDOR's Approve or Reject on a return we have sent them.

    THE DECISION MOVED HOUSE on 2026-09-12. This used to be `decide_sent_return`, a press
    on our own returns desk gated on `return.approve`, answering for a vendor who was
    already holding the goods. The business does not work that way: the return goes out as
    PAPERWORK, the vendor reads it against the GRN, the PO and the QC that condemned the
    stock, and the vendor says whether they accept it back. Nothing has travelled yet, so
    a rejection costs a conversation rather than a wasted lorry.

    NOT `engine.act`, and that judgement is unchanged from the desk version. The workflow
    engine owns the chain that signs a document BEFORE it goes out (rule 8) — that is
    `submit_return` starting a PURCHASE_RETURN instance while the return is still a draft,
    and it still does. This is a counterparty's answer on a document that instance has
    finished with, and starting a second instance against the same (doc_type, doc_id) is
    exactly what the engine refuses. So it is the document's own status transition,
    recorded in `sys_audit_log` where the History tab and the Journey both read it.

    NO PERMISSION CODE, and none is wanted: the caller is a vendor, not an employee, and
    `_vendor_return` scopes the row to the vendor id taken from their token at the router.
    A return belonging to somebody else is a 404, not a 403.

    A REJECTION MUST SAY WHY. An approval need not — the reason it was approved is the
    reason it was raised, and a second mandatory box is one people type "ok" into. The
    refusal is read by the storekeeper who raised the return and has to argue it, so an
    unexplained one is useless to them.

    ANSWERED ONCE. A decided return is past `RETURN_DECIDABLE_STATUSES`, so the second
    press is refused by the same guard that refuses one too early.
    """
    doc = await _vendor_return(db, vendor_id, return_id)
    if doc.status not in RETURN_DECIDABLE_STATUSES:
        if doc.vendor_decision:
            raise ValidationError(
                f"{doc.return_no} was already "
                f"{'approved' if doc.vendor_decision == ApprovalAction.APPROVED.value else 'rejected'}"
                f"{f' on {doc.vendor_decision_at:%d %b %Y}' if doc.vendor_decision_at else ''}"
                f" — it cannot be decided twice. Ask the buyer to raise a fresh document "
                f"if something needs to change.")
        _decision_guard(doc, "only a return that has been sent to you and not yet "
                             "answered can be approved or rejected")

    approved = data.action == ApprovalAction.APPROVED.value
    note = (data.remarks or "").strip() or None
    if not approved and not note:
        raise ValidationError(
            "Say why you are rejecting this return — the warehouse that raised it reads "
            "this and has to act on it.")

    before = doc.status
    doc.vendor_decision = (ApprovalAction.APPROVED.value if approved
                           else ApprovalAction.REJECTED.value)
    doc.vendor_decision_at = utcnow()
    # Deliberately NOT `vendor_decision_by_id`: that column is a soft fk to an EMPLOYEE
    # and there is no employee behind this press. The name is the vendor's own, which is
    # the honest record of who answered.
    doc.vendor_decision_by_name = doc.vendor_name or "the vendor"
    doc.vendor_decision_note = note
    doc.status = (ReturnStatus.VENDOR_APPROVED.value if approved
                  else ReturnStatus.REJECTED.value)

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=None,
        before={"status": before},
        after={"status": doc.status, "vendor_decision": doc.vendor_decision,
               "decided_by": doc.vendor_decision_by_name, "comments": note,
               "acting_vendor_id": vendor_id},
        summary=(f"Purchase Return {doc.return_no} "
                 f"{'approved' if approved else 'rejected'} by "
                 f"{doc.vendor_decision_by_name}"
                 + (f" — {note}" if note else "")))
    await db.commit()
    logger.info("Purchase Return %s %s by the vendor", doc.return_no,
                "approved" if approved else "rejected")
    return await vendor_get_return(db, vendor_id, return_id)


async def vendor_settle_return(db: AsyncSession, vendor_id: int, return_id: int,
                               data: "s.VendorReturnSettlementIn"):
    """Refund or Replacement — the VENDOR's second answer, once they have approved.

    Two outcomes and no third. The old portal offered a RETURNED option beside these
    ("we refuse these goods and are sending them back"), which was a refusal wearing the
    costume of a settlement: it arrived on the same press as the two real settlements and
    had to be untangled downstream. Refusal is now its own earlier press
    (`vendor_decide_return`), so by the time anybody gets here the return has been
    accepted and the only question left is what we get for it.

    REFUND is terminal. Nothing travels, so there is no transport question, no vehicle and
    no receipt — the figure and its stamp are the whole of what is left. The amount is
    capped against `total_value` HERE rather than in the schema, because only this function
    has the row and the cap is the one check an attacker would otherwise control both sides
    of. A partial credit is ordinary (freight deducted, a restocking charge kept back); an
    over-credit is a payment against nothing.

    REPLACEMENT hands the document to OUR warehouse, which owes exactly one decision —
    whose vehicle moves the goods. That is why it lands on its own rung rather than
    staying on VENDOR_APPROVED: a person chasing the return needs to know which desk is
    holding it, and "approved" does not say.

    ANSWERED ONCE, by `RETURN_SETTLEABLE_STATUSES`. Answering moves the document off the
    rung, so neither outcome can be pressed twice and one can never overwrite the other.
    """
    doc = await _vendor_return(db, vendor_id, return_id)
    if doc.status not in RETURN_SETTLEABLE_STATUSES:
        if doc.vendor_response:
            answered = dict(s.VENDOR_RETURN_RESPONSES).get(doc.vendor_response,
                                                           doc.vendor_response)
            raise ValidationError(
                f'{doc.return_no} was already settled as "{answered}"'
                f"{f' on {doc.vendor_response_at:%d %b %Y}' if doc.vendor_response_at else ''}"
                f". Ask the buyer to raise a fresh document if something needs to change.")
        _decision_guard(doc, "a refund or a replacement can only be chosen once you have "
                             "approved the return")

    refunding = data.settlement == VendorReturnResponse.REFUNDED.value
    note = (data.remarks or "").strip() or None
    before = doc.status

    if refunding:
        amount = _d(data.refund_amount)
        if amount <= ZERO:
            raise ValidationError("The refund amount must be greater than 0.")
        total = _d(doc.total_value)
        if total > ZERO and amount > total:
            raise ValidationError(
                f"A refund of {amount:,.2f} is more than the {total:,.2f} of goods on "
                f"{doc.return_no}. Credit that value or less.")
        doc.vendor_refund_amount = amount
        doc.status = ReturnStatus.REFUNDED.value
    else:
        doc.status = ReturnStatus.REPLACEMENT_AGREED.value

    doc.vendor_response = (VendorReturnResponse.REFUNDED.value if refunding
                           else VendorReturnResponse.REPLACED.value)
    doc.vendor_response_at = utcnow()
    doc.vendor_response_note = note

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=None,
        before={"status": before},
        after={"status": doc.status, "vendor_response": doc.vendor_response,
               # str(), not float(): this is the figure a credit note is reconciled
               # against, and the audit row must not be where a decimal turns into a
               # binary approximation of itself.
               "vendor_refund_amount": (str(doc.vendor_refund_amount)
                                        if doc.vendor_refund_amount is not None else None),
               "remarks": note, "acting_vendor_id": vendor_id},
        summary=(f"Purchase Return {doc.return_no}: "
                 + (f"{doc.vendor_name or 'the vendor'} is refunding "
                    f"{_d(doc.vendor_refund_amount):,.2f}" if refunding
                    else f"{doc.vendor_name or 'the vendor'} is sending a replacement — "
                         f"the warehouse now arranges transport")
                 + (f" — {note}" if note else "")))
    await db.commit()
    logger.info("Purchase Return %s settled by the vendor as %s",
                doc.return_no, doc.vendor_response)
    return await vendor_get_return(db, vendor_id, return_id)


async def _ensure_return_warehouse(db: AsyncSession, doc: m.PurchaseReturn,
                                   user=None) -> None:
    """Make sure the return says which of OUR points the load leaves from.

    `out_dispatches.warehouse_id` is NOT NULL; `pro_returns.warehouse_id` is not, and the
    gap between the two is what reaches the transport screen as a raw column name, on a
    band whose only fields are the pickup address and the ready date. There is nothing on
    that screen to fill in, because the value is missing from the RETURN, not the form.

    How a return gets there: `send_to_vendor` refuses a sourced return with no warehouse,
    but a MANUAL one returns before that check, and a return raised automatically off a
    branch consignment copies whatever the stock transfer named at its end — so a leg
    whose end had no warehouse row behind it leaves the id null with the NAME still
    written on the document.

    Resolved in the order the answer is actually known, and never invented:

      1. the id the return already carries;
      2. the goods receipt behind it — `inb_receipts.warehouse_id` is NOT NULL and is
         literally where the material was booked in;
      3. the warehouse master, matched on the name the document is already showing. Some
         rows carry a picker's display label ("CENTRAL WAREHOUSE-1 - MAIN") rather than
         the plain name, so the code and the part before a " - " suffix are tried too.
         Every match is exact and case-insensitive: this narrows a name down to the row
         that already bears it, and never picks between two that merely look alike;
      4. THE PERSON PRESSING THE BUTTON — their own primary stocking point, across every
         live post they hold. A manual draft carries no warehouse, no GRN and no item, so
         1-3 have nothing to read and this is the only place the answer exists: the goods
         are standing on the floor of the point that person works, which is what the
         question was asking. This is why there is NO warehouse dropdown on the band —
         asking a storekeeper to confirm their own only warehouse is a press with one
         possible answer. Only where every live post agrees on ONE point: two posts at
         two different stores is a genuine ambiguity, and guessing would send a vehicle
         to the wrong building.

    Whatever it resolves is STAMPED BACK onto the return, because every later read asks
    the same column — the register's warehouse filter, `scope_condition`, and the receipt
    the replacement is booked in against would all go on getting null.

    Where nothing resolves the press is refused in words a storekeeper can act on, with
    the document untouched — which is why this runs before the arrangement is written.
    """
    if doc.warehouse_id:
        return

    if doc.grn_id:
        receipt = await db.get(m.Receipt, doc.grn_id)
        if receipt is not None and receipt.warehouse_id:
            doc.warehouse_id = receipt.warehouse_id
            doc.warehouse_name = receipt.warehouse_name or doc.warehouse_name
            return

    named = (doc.warehouse_name or "").strip()
    if named:
        candidates = [named]
        if " - " in named:
            candidates.append(named.rsplit(" - ", 1)[0].strip())
        for candidate in candidates:
            if not candidate:
                continue
            wh = await db.scalar(
                select(Warehouse)
                .where(Warehouse.is_active.is_(True),
                       or_(func.lower(Warehouse.name) == candidate.lower(),
                           func.lower(Warehouse.code) == candidate.lower()))
                .limit(1))
            if wh is not None:
                doc.warehouse_id = wh.id
                doc.warehouse_name = wh.name
                return

    if user is not None:
        own: set[int] = set()
        for position_id in await stock_locations.active_positions_of(db, user):
            point = await stock_locations.primary_location_for(db, position_id)
            if point:
                own.add(point)
        if len(own) == 1:
            wh = await db.get(Warehouse, own.pop())
            if wh is not None and wh.is_active:
                doc.warehouse_id = wh.id
                doc.warehouse_name = wh.name
                return

    raise ValidationError(
        f"{doc.return_no} does not say which warehouse the goods are leaving from, and "
        f"the consignment that carries them cannot be raised without one"
        + (f" — “{named}” is not a warehouse on the master."
           if named else ".")
        + " Set the warehouse on the return, or ask an administrator to tag your login "
          "to the stocking point you work, then arrange the transport again.")


async def arrange_return_transport(db: AsyncSession, return_id: int,
                                   data: s.ReturnVehicleArrangementIn,
                                   user) -> m.PurchaseReturn:
    """Who moves the goods to the vendor — the ONE decision this warehouse still makes.

    Opened by the vendor agreeing to replace, and it is the only press left on our side
    until the replacement turns up. Two answers:

    VENDOR_ARRANGES — the vendor sends their own vehicle to collect. Nothing is asked of
    Logistics and no transport request is raised; the return waits on
    AWAITING_VENDOR_VEHICLE for the vendor to accept the job on their portal.

    WAREHOUSE_REQUESTS — the LOGISTICS RETURN LEG. An ordinary transport request on the
    board logistics already works: `DispatchPage` reads a second queue of
    `source_type=RETURN` rows and a DRAFT there gets the Dispatch press, which opens
    `/logistics/dispatch/new?tr_id=`. No new table, no new logistics status, no screen to
    build — the leg goes through `transport.create_tr`, the public intake, exactly as
    every other return leg in this module does.

    THE CONSIGNMENT IS RAISED HERE, not at the send. `out_dispatches` is the warehouse's
    own outward document and it describes goods actually leaving; raising it when the
    paperwork went out (which is what `send_to_vendor` used to do) had it claiming a load
    had travelled while the vendor was still reading the return. Raised on BOTH branches,
    because the goods leave the building either way and `_apply_gate_out` — the one place
    stock comes off the books — hangs off it.

    ASKED ONCE, by `RETURN_TRANSPORTABLE_STATUSES`. Answering moves the document off the
    rung, which is what stops a second press raising a second consignment and a second
    vehicle for one load.
    """
    doc = await _load(db, m.PurchaseReturn, return_id, "Return", m.PurchaseReturn.items)
    if doc.status not in RETURN_TRANSPORTABLE_STATUSES:
        if doc.vehicle_arrangement:
            raise ValidationError(
                f"{doc.return_no} is already set to "
                f"{RETURN_VEHICLE_ARRANGEMENT_LABELS.get(doc.vehicle_arrangement, doc.vehicle_arrangement)}"
                f" — the transport for this return has already been arranged.")
        _decision_guard(doc, "transport can only be arranged once the vendor has approved "
                             "the return and asked for a replacement")

    valid = set(RETURN_VEHICLE_ARRANGEMENT_LABELS)
    if data.arrangement not in valid:
        raise ValidationError(
            f"Pick how the vehicle is arranged: {', '.join(sorted(valid))}")
    if not doc.items:
        raise ValidationError(
            f"{doc.return_no} has no lines — there is nothing to put on a vehicle.")

    # Which of OUR points the load leaves from, resolved and stamped on the document
    # BEFORE anything is written: `out_dispatches.warehouse_id` is NOT NULL and the
    # consignment is raised further down this same function, so a return that cannot
    # answer has to be refused while it is still standing where the desk left it.
    await _ensure_return_warehouse(db, doc, user)

    raises_request = data.arrangement in RETURN_ARRANGEMENTS_RAISING_REQUEST
    before = doc.status
    doc.vehicle_arrangement = data.arrangement
    doc.vehicle_arrangement_at = utcnow()
    doc.vehicle_arrangement_by_name = _name(user)
    doc.status = (ReturnStatus.VEHICLE_REQUESTED.value if raises_request
                  else ReturnStatus.AWAITING_VENDOR_VEHICLE.value)
    # Where the vehicle collects FROM is our own warehouse on this leg, so what the desk
    # states here is the delivery end — the vendor's dock — and the ready date is the
    # earliest the load can go. Stored on the same two columns either branch uses.
    doc.inbound_pickup_address = (data.pickup_address or "").strip() or None
    doc.inbound_ready_date = data.ready_date

    remarks = (data.remarks or "").strip() or None

    # The warehouse's outward document, on both branches — see the docstring.
    dispatch = await _build_return_consignment(db, doc, user, None, None)

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": doc.status, "vehicle_arrangement": doc.vehicle_arrangement,
               "dispatch_no": dispatch.dispatch_no, "dispatch_id": dispatch.id,
               "pickup_address": doc.inbound_pickup_address,
               "ready_date": (doc.inbound_ready_date.isoformat()
                              if doc.inbound_ready_date else None),
               "remarks": remarks},
        summary=(f"Purchase Return {doc.return_no}: "
                 f"{RETURN_VEHICLE_ARRANGEMENT_LABELS[data.arrangement]}"
                 + (" — return leg going to Logistics" if raises_request
                    else " — the vendor is collecting from the warehouse")
                 + f" (consignment {dispatch.dispatch_no})"))

    # Read while the instances are still live: the commit below expires every one of them
    # and `create_tr` cannot run before it. Same ordering, for the same reason, as
    # `_return_shipment_seed` and `_collection_shipment_seed`.
    vendor = await db.get(Vendor, doc.vendor_id) if doc.vendor_id else None
    seed = (_return_shipment_seed(doc, dispatch, vendor, LOGISTICS_MODE_UNSTATED)
            if raises_request else None)

    await db.commit()

    # Raised AFTER the arrangement has committed, and never allowed to undo it: the desk
    # has answered, and a leg that could not be raised must not un-answer them. Logged and
    # swallowed, exactly as `_raise_collection_shipment` is — the desk can raise one by
    # hand from the Shipments register, which is where every return was before any of this
    # existed.
    if seed is not None:
        try:
            await _raise_return_shipment(db, seed, user, stamp_outbound=True)
        except Exception:
            logger.exception(
                "Purchase Return %s was set to a warehouse-arranged vehicle, but the "
                "return leg could not be raised in Logistics", doc.return_no)
            await db.rollback()

    return await get_return(db, return_id, user)


# ---------------------------------------------------------------------------
# RETIRED 2026-09-12: the vendor -> warehouse vehicle request
#
# `_inbound_vehicle_seed` and `_raise_inbound_vehicle_request` below raised a leg that
# COLLECTED the returned material FROM the vendor, because the old flow sent the goods
# out with the paperwork and then had to fetch them back if anything went wrong. The
# business's leg runs the other way — our warehouse to the vendor — and that is
# `_raise_return_shipment`, called from `arrange_return_transport`.
#
# Nothing calls these two any more. They are kept rather than deleted because the columns
# they wrote (`inbound_tr_id` / `inbound_tr_no`) are still carried by returns already in
# flight, and `_inbound_vehicle_arrived` / `_inbound_vehicle_released` still settle those
# legs when logistics signs them. Deleting the raiser while its readers stay would leave
# the pair unreadable to whoever next has to work out where those rows came from.
# ---------------------------------------------------------------------------


async def _inbound_vehicle_seed(db: AsyncSession, doc: m.PurchaseReturn) -> dict:
    """Everything the vehicle request needs, read while the arrangement's rows are live.

    RETIRED — see the block above. `transport.create_tr` COMMITS, so it could not be
    called before its caller had committed its own work, and after that commit every
    instance here is expired.
    """
    vendor = await db.get(Vendor, doc.vendor_id) if doc.vendor_id else None
    return {
        "return_id": doc.id,
        "return_no": doc.return_no,
        "vendor_name": (vendor.name if vendor else doc.vendor_name) or "the vendor",
        "warehouse_id": doc.warehouse_id,
        "warehouse_name": doc.warehouse_name or "our warehouse",
        "pickup_address": doc.inbound_pickup_address or (
            _vendor_address(vendor) if vendor else None),
        "ready_date": doc.inbound_ready_date,
        # Who the driver calls when the vehicle reaches the vendor's gate.
        "contact_person": (vendor.contact_person if vendor
                           else doc.manual_vendor_contact_person),
        "contact_phone": vendor.phone if vendor else doc.manual_vendor_phone,
        "lines": [{
            "item_id": line.item_id,
            "item_code": line.item_code,
            "item_name": line.item_name,
            "uom_code": line.uom_code,
            "quantity": float(_d(line.quantity)),
            # One carton per line, which is what every other return leg assumes. Nothing
            # has been packed or weighed — the cartons are standing on the VENDOR's dock
            # and nobody here has counted them — so `weight_kg` is left unsaid rather
            # than invented: an unweighed line has no weight, and zero reads as "it
            # weighs nothing".
            "package_count": 1,
            "remarks": line.reason,
        } for line in (doc.items or []) if line.item_id],
    }


async def _raise_inbound_vehicle_request(db: AsyncSession, seed: dict, user) -> None:
    """Put the warehouse's vehicle request on the Logistics Dispatch board as a DRAFT.

    THE SAME DOOR EVERY OTHER RETURN LEG COMES THROUGH, and the reason this needed no
    new screen: `DispatchPage` already reads a second board below the consignment queue
    (`source_type=RETURN`, DRAFT through IN_TRANSIT), and a DRAFT row there gets the
    Dispatch press that opens `/logistics/dispatch/new?tr_id=`. That screen is where the
    vehicle and the driver are named. So this raises an ordinary transport request and
    nothing else, and the rungs the leg then climbs are the ones every shipment climbs.

    `source_id` IS DELIBERATELY LEFT NULL, for exactly the reason `_raise_return_shipment`
    and `_raise_collection_shipment` both give: the returns module's hooks start at
    `_return_behind`, which takes `source_type=RETURN` plus `source_id` and looks the id
    up in `inv_sto` — field returns' own table, an unrelated sequence from `pro_returns`.
    Passing a purchase return's id would eventually name somebody else's field return and
    let a release debit a shelf this return never touched. Leaving it null is what makes
    this leg provably not theirs. The return number still travels as `source_no`, which
    is what the board and the confirm screen actually show.

    WHICH WAY ROUND THE ENDS GO. This leg runs vendor -> our warehouse, so
    `to_location_name` is our own warehouse — which is also the check that makes it safe,
    since `create_tr` refuses an inbound leg that does not name where it is coming back
    to. `from_warehouse_id` stays NULL: the load starts on a dock that is not a site of
    ours, and writing an id there would have the board claim one of our own warehouses
    shipped it. The pickup ADDRESS goes in the remarks rather than `delivery_address`,
    because that column renders under "To" on the dispatch confirm screen and the
    vendor's dock is where this vehicle comes FROM.

    `expected_delivery` IS DELIBERATELY LEFT NULL. The only date anybody has stated is
    the vendor's goods-ready date, which is the earliest the vehicle may collect — not
    when the load is due back at our gate. Nobody can know that until the desk assigns
    the vehicle, which is the press this draft exists to put in front of them.

    THE LEG'S ID IS STAMPED BACK ONTO THE RETURN, and that link is load-bearing rather
    than decorative: `_decorate_return_inbound_leg` reads the vehicle and the driver off
    it, and `_inbound_vehicle_arrived` matches a signed leg back to the return waiting
    on it. Without the stamp the vehicle arrives against nothing.
    """
    from app.modules.logistics import transport as lgs_transport
    from app.modules.logistics.enums import TransportSource
    from app.modules.logistics.schemas import TRCreate, TRLineIn

    tr = await lgs_transport.create_tr(db, TRCreate(
        # OUR OWN VEHICLE is the assumption, not a decision taken here: the warehouse
        # asked for a vehicle, which is what "own vehicle" means on this board, and the
        # desk changes the mode on the Dispatch screen before anything is booked. Same
        # starting value `_raise_collection_shipment` uses for the same leg shape.
        mode=LOGISTICS_MODE_RAISING_SHIPMENT,
        source_type=TransportSource.RETURN.value,
        source_id=None,                       # see the docstring — load-bearing
        source_no=seed["return_no"],
        from_warehouse_id=None,               # see the docstring — not a site of ours
        from_warehouse_name=seed["vendor_name"],
        to_location_name=seed["warehouse_name"],
        contact_person=seed["contact_person"],
        contact_phone=seed["contact_phone"],
        remarks=(
            f"Purchase Return {seed['return_no']} — collect the returned material from "
            f"{seed['vendor_name']} and deliver it to {seed['warehouse_name']}."
            + (f" Collect from: {seed['pickup_address']}."
               if seed["pickup_address"] else "")
            + (f" Ready from {seed['ready_date']:%d %b %Y}."
               if seed["ready_date"] else "")
            + " Assign the vehicle and the driver on this leg — the purchase return "
              "reads them back off it."),
        lines=[TRLineIn(**line) for line in seed["lines"]],
    ), user)

    # The link back, without which the vehicle arrives against nothing — see the
    # docstring. A plain UPDATE rather than loading the row: `create_tr` has just
    # committed and the return instance the caller held is expired.
    await db.execute(
        update(m.PurchaseReturn)
        .where(m.PurchaseReturn.id == seed["return_id"])
        .values(inbound_tr_id=tr.id, inbound_tr_no=tr.tr_no))

    await write_audit(
        db, entity="pro_returns", entity_id=seed["return_id"],
        entity_no=seed["return_no"], action=AuditAction.UPDATE, actor=user,
        after={"inbound_tr_no": tr.tr_no, "inbound_tr_id": tr.id,
               "transport_status": tr.status},
        summary=f"Purchase Return {seed['return_no']}: vehicle request {tr.tr_no} "
                f"raised in Logistics as a draft")
    await db.commit()
    logger.info("Purchase Return %s raised vehicle request %s (%s)",
                seed["return_no"], tr.tr_no, tr.status)


#: The stated-vehicle columns, and the request field each is filled from. One mapping,
#: read by both vendor transport presses, so the accept and the pickup cannot disagree
#: about where a vehicle number is stored.
_VENDOR_VEHICLE_FIELDS: tuple[tuple[str, str], ...] = (
    ("arranged_vehicle_no", "vehicle_no"),
    ("arranged_driver_name", "driver_name"),
    ("arranged_driver_phone", "driver_phone"),
    ("arranged_transporter_name", "transporter_name"),
    ("arranged_lr_no", "lr_no"),
    ("arranged_expected_date", "expected_date"),
)


def _apply_vendor_vehicle(doc: m.PurchaseReturn, data) -> dict:
    """Copy the vehicle the vendor stated onto the return; report what changed.

    ONLY WHAT WAS STATED. A blank field on a form filled in over several calls means
    "nothing to say about this", never "erase what is there" — the same rule the masters
    importer follows for an empty cell. A vendor names a truck on Monday, rings back on
    Tuesday with the driver and swaps the vehicle on Wednesday when it breaks down, and
    none of those three presses may wipe the other two.
    """
    changed: dict[str, str | None] = {}
    for column, field in _VENDOR_VEHICLE_FIELDS:
        value = getattr(data, field, None)
        if isinstance(value, str):
            value = value.strip() or None
        if value is not None:
            setattr(doc, column, value)
            changed[column] = str(value)
    return changed


async def vendor_accept_transport(db: AsyncSession, vendor_id: int, return_id: int,
                                  data: "s.VendorTransportAcceptIn"):
    """The VENDOR accepts the collection job and names the vehicle they are sending.

    ONLY on a VENDOR_ARRANGES leg. Where the warehouse asked Logistics for a vehicle it
    belongs to the transport request logistics assigned it on and is read back off that
    leg (`_decorate_return_inbound_leg`) — offering the vendor a second place to type one
    is exactly how two documents end up naming different trucks for one load. The
    arrangement is checked as well as the status, because a rung alone cannot say whose
    vehicle it is.

    ACCEPTING IS ANSWERED ONCE — the rung moves — but the VEHICLE DETAILS stay editable
    afterwards through `vendor_record_pickup`, because a truck named three days before it
    turns up is frequently not the truck that turns up.
    """
    doc = await _vendor_return(db, vendor_id, return_id)
    if doc.vehicle_arrangement != ReturnVehicleArrangement.VENDOR_ARRANGES.value:
        raise ValidationError(
            f"{doc.return_no} is being collected by a vehicle the warehouse has arranged "
            f"through Logistics — there is nothing for you to accept here.")
    if doc.status not in RETURN_VENDOR_ACCEPTABLE_STATUSES:
        if doc.vendor_transport_accepted_at:
            raise ValidationError(
                f"You already accepted the collection for {doc.return_no}"
                f"{f' on {doc.vendor_transport_accepted_at:%d %b %Y}' if doc.vendor_transport_accepted_at else ''}"
                f" — record the pickup when your vehicle has loaded.")
        _decision_guard(doc, "the collection can only be accepted once the warehouse has "
                             "asked you to send a vehicle")

    before = doc.status
    changed = _apply_vendor_vehicle(doc, data)
    doc.vendor_transport_accepted_at = utcnow()
    doc.vendor_transport_accepted_by_name = doc.vendor_name or "the vendor"
    doc.status = ReturnStatus.VENDOR_TRANSPORT_ACCEPTED.value

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=None,
        before={"status": before},
        after={"status": doc.status, **changed,
               "accepted_by": doc.vendor_transport_accepted_by_name,
               "remarks": (data.remarks or "").strip() or None,
               "acting_vendor_id": vendor_id},
        summary=(f"Purchase Return {doc.return_no}: "
                 f"{doc.vendor_name or 'the vendor'} accepted the collection"
                 + (f" — vehicle {doc.arranged_vehicle_no}"
                    if doc.arranged_vehicle_no else "")))
    await db.commit()
    return await vendor_get_return(db, vendor_id, return_id)


async def vendor_record_pickup(db: AsyncSession, vendor_id: int, return_id: int,
                               data: "s.VendorPickupIn"):
    """The vendor's vehicle has loaded at our warehouse and left with the goods.

    THE GATE-OUT ON THE VENDOR BRANCH. On the warehouse branch it is Logistics releasing
    the leg that takes the stock off our books; here there is no logistics document to say
    so, so the vendor says it — and the SAME `_apply_gate_out` runs against the same
    consignment, which is what keeps one path for stock leaving (rule 7) rather than two
    that have to be kept in agreement.

    A SEPARATE PRESS from accepting, rather than inferred from a vehicle number being
    present, because knowing which truck is coming on Thursday is not the same fact as it
    having loaded and gone.

    IDEMPOTENT. A return already past this rung is refused rather than gating out twice —
    a second gate-out would debit the shelf a second time for one load.
    """
    doc = await _vendor_return(db, vendor_id, return_id)
    if doc.vehicle_arrangement != ReturnVehicleArrangement.VENDOR_ARRANGES.value:
        raise ValidationError(
            f"{doc.return_no} is travelling on a vehicle the warehouse arranged — "
            f"Logistics records when it leaves.")
    if doc.status not in RETURN_VENDOR_PICKUP_STATUSES:
        if doc.arranged_dispatched_at:
            raise ValidationError(
                f"The pickup for {doc.return_no} was already recorded"
                f"{f' on {doc.arranged_dispatched_at:%d %b %Y}' if doc.arranged_dispatched_at else ''}"
                f" — sign for the goods when they reach you.")
        _decision_guard(doc, "the pickup can only be recorded once you have accepted the "
                             "collection")

    before = doc.status
    changed = _apply_vendor_vehicle(doc, data)
    doc.arranged_dispatched_at = utcnow()
    doc.status = ReturnStatus.STOCK_PICKED_UP.value

    # The goods have physically left. Take them off the books through the one path that
    # does that, against the consignment this return already raised.
    gated = await _gate_out_return_consignment(db, doc, None)

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=None,
        before={"status": before},
        after={"status": doc.status, **changed,
               "picked_up_at": doc.arranged_dispatched_at.isoformat(),
               "gate_pass_no": gated,
               "remarks": (data.remarks or "").strip() or None,
               "acting_vendor_id": vendor_id},
        summary=(f"Purchase Return {doc.return_no}: collected from "
                 f"{doc.warehouse_name or 'the warehouse'} by "
                 f"{doc.vendor_name or 'the vendor'}"
                 + (f" on {doc.arranged_vehicle_no}" if doc.arranged_vehicle_no else "")))
    await db.commit()
    logger.info("Purchase Return %s picked up by the vendor's own vehicle", doc.return_no)
    return await vendor_get_return(db, vendor_id, return_id)


async def _gate_out_return_consignment(db: AsyncSession, doc: m.PurchaseReturn,
                                       user) -> str | None:
    """Take the goods off the books, through the consignment this return raised.

    `_apply_gate_out` is the SHARED path — the logistics release hook has always called
    it, and the vendor-pickup branch calls it here — so stock leaving a warehouse for a
    vendor happens in exactly one place however the truck was booked (rule 7).

    Runs inside the caller's transaction and never commits. Returns the gate pass number
    where there was one, for the audit row.

    NEVER RAISES. The goods are on a lorry and the document has to say so; refusing to
    record that because the consignment is in an unexpected state would leave the two
    further apart rather than closer. The same rule every hook in this module runs on.
    """
    try:
        # `items` AND `packages` eagerly, because `_apply_gate_out` walks both and they
        # are plain lazy relationships — touching one on an AsyncSession raises
        # MissingGreenlet. Exactly what `_consignment_of` loads, for exactly this reason.
        dispatch = await db.scalar(
            select(m.Dispatch)
            .options(selectinload(m.Dispatch.items),
                     selectinload(m.Dispatch.packages))
            .where(m.Dispatch.ref_type == "PURCHASE_RETURN",
                   m.Dispatch.ref_id == doc.id)
            .order_by(m.Dispatch.id.desc()).limit(1))
        if dispatch is None:
            logger.warning("Purchase Return %s has no consignment to gate out",
                           doc.return_no)
            return None
        if dispatch.status in {DispatchStatus.DISPATCHED.value,
                               DispatchStatus.IN_TRANSIT.value,
                               DispatchStatus.DELIVERED.value,
                               DispatchStatus.ACKNOWLEDGED.value}:
            logger.info("Purchase Return %s: consignment %s has already left — not "
                        "gating it out twice", doc.return_no, dispatch.dispatch_no)
            return dispatch.gate_pass_no
        await _apply_gate_out(db, dispatch, dispatch.gate_pass_no, user)
        return dispatch.gate_pass_no
    except Exception:
        logger.exception("Purchase Return %s: the consignment could not be gated out",
                         doc.return_no)
        return None


async def confirm_return_received(db: AsyncSession, return_id: int,
                                  data: s.ReturnReceivedIn, user) -> m.PurchaseReturn:
    """The REPLACEMENT is in the building, and somebody here has signed for it.

    What happens to the goods AFTER they are in the building is the store's ordinary inward
    path — the draft receipt the dispatch note raised, then GRN, QC and putaway — and
    nothing here short-circuits it: no stock is posted by this press (rule 7), because a
    signature at the gate is not a count on a shelf. The return then closes on the last
    putaway (`_close_return_on_intake_complete`), never here.

    THE ORDINARY WAY IN IS THE RECEIPT, not this press. Submitting the goods receipt is
    what brings the return home (`_settle_return_on_receipt`), because that is where the
    store says what physically arrived. This route survives for the load that turns up
    while the paperwork lags — signing at the gate must never be impossible — and it is
    refused once the receipt has already done it, which is what stops the two recording
    one lorry twice.

    WHAT ARRIVES HERE CHANGED on 2026-09-12. It used to be the FAULTY material coming back
    from a vendor who had refused it. It is now the replacement the vendor dispatched,
    which is the only thing still travelling towards us by this point — the faulty stock
    went the other way and the vendor has already signed for it.

    Reachable WITHOUT waiting for a logistics acknowledgement, on purpose. A load that
    arrived while the paperwork lagged must not leave the warehouse unable to say so.
    Whichever happens first wins, and the second finds the return already here and does
    nothing rather than overwriting a signature.
    """
    doc = await _load(db, m.PurchaseReturn, return_id, "Return", m.PurchaseReturn.items)
    if doc.status == ReturnStatus.RECEIVED_AT_WAREHOUSE.value:
        raise ValidationError(
            f"{doc.return_no} was already received"
            + (f" by {doc.received_by_name}" if doc.received_by_name else "")
            + (f" on {doc.received_at:%d %b %Y}" if doc.received_at else "") + ".")
    # `RETURN_INBOUND_STATUSES` rather than only the replacement-dispatched rung, and
    # deliberately wider than the other guards in this file: it also holds the rungs a
    # return raised under the older vendor -> warehouse flow travels, and those rows must
    # still be signable in. A return that has not moved at all is still refused.
    if doc.status not in RETURN_INBOUND_STATUSES:
        _decision_guard(doc, "only a return with material on its way to this warehouse "
                             "can be received")

    before = doc.status
    doc.status = ReturnStatus.RECEIVED_AT_WAREHOUSE.value
    doc.received_at = utcnow()
    doc.received_by_name = (data.received_by_name or "").strip() or _name(user)
    doc.received_remarks = (data.remarks or "").strip() or None

    await write_audit(
        db, entity="pro_returns", entity_id=doc.id, entity_no=doc.return_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": doc.status, "received_by": doc.received_by_name,
               "received_at": doc.received_at.isoformat(),
               "remarks": doc.received_remarks,
               "vehicle_no": doc.arranged_vehicle_no,
               "inbound_tr_no": doc.inbound_tr_no},
        summary=(f"Purchase Return {doc.return_no}: material received at "
                 f"{doc.warehouse_name or 'the warehouse'}, signed by "
                 f"{doc.received_by_name}"))
    await db.commit()
    logger.info("Purchase Return %s received back at the warehouse", doc.return_no)
    return await get_return(db, return_id, user)


async def _inbound_vehicle_arrived(db: AsyncSession, tr, user) -> bool:
    """A warehouse-requested vehicle has landed — bring the return in with it.

    THE OTHER END of `_raise_inbound_vehicle_request`. Matched on `inbound_tr_id`, which
    is its OWN column rather than the `collection_tr_id` the supplier-collection path
    uses: the two trips look alike but settle differently, and sharing the column would
    have `_collection_arrived` raise an inbound receipt against a supplier answer this
    return never carried.

    Returns whether this leg belonged to a purchase return's inbound vehicle, so the
    caller knows to stop — the leg carries no consignment and none of the consignment
    settlement applies to it.

    IDEMPOTENT. A second acknowledgement finds the return already received and does
    nothing rather than overwriting the signature that is on it.

    Runs inside the transport service's transaction and never commits. It also never
    raises: the vehicle is in the yard and the driver has been signed off, and refusing
    to record that because the return behind it is in an unexpected state would leave
    the two documents further apart rather than closer — the same rule every hook in
    this module runs on.
    """
    if not getattr(tr, "id", None):
        return False
    row = (await db.execute(
        select(m.PurchaseReturn)
        .where(m.PurchaseReturn.inbound_tr_id == tr.id)
    )).scalars().first()
    if row is None:
        return False
    if row.status == ReturnStatus.RECEIVED_AT_WAREHOUSE.value:
        logger.info("%s: %s is already received — not signing it in twice",
                    tr.tr_no, row.return_no)
        return True

    before = row.status
    row.status = ReturnStatus.RECEIVED_AT_WAREHOUSE.value
    row.received_at = utcnow()
    row.received_by_name = tr.acknowledged_by_name or _name(user)
    row.received_remarks = tr.ack_remarks or None
    await write_audit(
        db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": row.status, "received_by": row.received_by_name,
               "inbound_tr_no": tr.tr_no, "vehicle_no": tr.vehicle_number},
        summary=(f"Purchase Return {row.return_no}: {tr.tr_no} delivered the returned "
                 f"material to {row.warehouse_name or 'the warehouse'}"))
    logger.info("%s brought %s back to the warehouse", tr.tr_no, row.return_no)
    return True


async def _inbound_vehicle_released(db: AsyncSession, tr, user) -> bool:
    """The requested vehicle has left with the load — put the return on the road.

    The rung between the request and the arrival, and the only one logistics can tell us
    about: `ON_RELEASE` fires when the leg is actually dispatched, which for this leg is
    the vehicle setting off with the material on it.

    Deliberately does NOT try to record "a vehicle has been assigned". That is a press on
    logistics' own Dispatch screen and they expose no hook for it, so it is WORDED off
    the leg's columns on every read (`_decorate_return_inbound_leg`) rather than stored —
    see `enums.ReturnStatus.VEHICLE_REQUESTED`.
    """
    if not getattr(tr, "id", None):
        return False
    row = (await db.execute(
        select(m.PurchaseReturn)
        .where(m.PurchaseReturn.inbound_tr_id == tr.id)
    )).scalars().first()
    if row is None:
        return False
    if row.status != ReturnStatus.VEHICLE_REQUESTED.value:
        # Already on the road, already received, or cancelled. Nothing a release can add.
        return True
    before = row.status
    row.status = ReturnStatus.IN_TRANSIT.value
    await write_audit(
        db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
        action=AuditAction.UPDATE, actor=user,
        before={"status": before},
        after={"status": row.status, "inbound_tr_no": tr.tr_no,
               "vehicle_no": tr.vehicle_number, "driver_name": tr.driver_name},
        summary=(f"Purchase Return {row.return_no}: {tr.tr_no} left "
                 f"{row.vendor_name or 'the vendor'} with the returned material"
                 + (f" on {tr.vehicle_number}" if tr.vehicle_number else "")
                 + (f", driver {tr.driver_name}" if tr.driver_name else "")))
    logger.info("%s put %s on the road", tr.tr_no, row.return_no)
    return True


async def _outbound_return_released(db: AsyncSession, tr, user) -> None:
    """The RETURN LEG has left our warehouse — the goods are on their way to the vendor.

    The other end of `_raise_return_shipment(..., stamp_outbound=True)`, matched on
    `outbound_tr_id`. Its OWN column rather than `inbound_tr_id` or `collection_tr_id`,
    which two other settlements match on: the three trips look alike and settle
    differently, and sharing a column would have each one fire on documents it was never
    written for.

    RETURNS NOTHING, and that is deliberate — it is the one probe in `transport_released`
    that must NOT short-circuit. The other two answer "this leg is a purchase return's
    vehicle and none of the consignment settlement applies to it". This leg DOES carry a
    consignment (`dispatch_id` is set on it), and that consignment still has to be gated
    out by the path below, which is the only place stock comes off the books. So this
    records the rung and lets the caller carry on.

    IDEMPOTENT. A return already past this rung is left alone rather than re-stamped.

    Runs inside the transport service's transaction and never commits. It also never
    raises: the load has gone and the driver is away, and refusing to record that because
    the return behind it is in an unexpected state would leave the two documents further
    apart rather than closer — the rule every hook in this module runs on.
    """
    if not getattr(tr, "id", None):
        return
    try:
        row = (await db.execute(
            select(m.PurchaseReturn)
            .where(m.PurchaseReturn.outbound_tr_id == tr.id)
        )).scalars().first()
        if row is None:
            return
        if row.status != ReturnStatus.VEHICLE_REQUESTED.value:
            logger.info("%s: %s is already past pickup — not stamping it twice",
                        tr.tr_no, row.return_no)
            return
        before = row.status
        row.status = ReturnStatus.STOCK_PICKED_UP.value
        await write_audit(
            db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
            action=AuditAction.UPDATE, actor=user,
            before={"status": before},
            after={"status": row.status, "outbound_tr_no": tr.tr_no,
                   "vehicle_no": tr.vehicle_number, "driver_name": tr.driver_name},
            summary=(f"Purchase Return {row.return_no}: {tr.tr_no} left "
                     f"{row.warehouse_name or 'the warehouse'} for "
                     f"{row.vendor_name or 'the vendor'}"
                     + (f" on {tr.vehicle_number}" if tr.vehicle_number else "")
                     + (f", driver {tr.driver_name}" if tr.driver_name else "")))
        logger.info("%s carried %s out to the vendor", tr.tr_no, row.return_no)
    except Exception:
        logger.exception("Purchase Return behind %s could not be marked as picked up",
                         getattr(tr, "tr_no", tr.id))


# ---------------------------------------------------------------------------
# Serials, batches, scanning
# ---------------------------------------------------------------------------

async def list_serials(db: AsyncSession, params: PageParams, *, status: str | None = None,
                       item_id: int | None = None, batch_id: int | None = None,
                       warehouse_id: int | None = None, bin_id: int | None = None,
                       search: str | None = None, issue_id: int | None = None,
                       issue_line_id: int | None = None, unbatched: bool = False,
                       claim_free: bool = False,
                       scope: str | None = None, user=None) -> dict:
    """Units, optionally narrowed to what one issue line may still pick.

    `unbatched` narrows to units with no batch — a bare `batch_id` of None means
    "any batch", which is wrong for a pick off the unbatched lot. `claim_free` drops
    every unit a document is holding, for a picker with no line of its own (a stock
    movement).

    `issue_id` + `issue_line_id` drop every unit another document — or another line
    of this same issue — is already holding, while keeping the ones this line holds
    itself. Without it the picker offered the same serial on two lines of the same
    item, and the second line only found out at the shelf.

    `scope` widens the circle when the bay is empty: `batch` drops the bin but keeps
    the batch, `point` drops both and lists the whole point. The save still
    validates the line's own bay and batch — this only lets the picker SEE further.
    """
    stmt = select(m.SerialNumber)
    if issue_id:
        claim_free = _unit_claim_free_clause(
            _issue_line_serial_marker(issue_id, issue_line_id))
        # The units held for this issue's own project are its to name.
        issue_project = await db.scalar(
            select(m.MaterialIssue.project_id).where(m.MaterialIssue.id == issue_id))
        if issue_project:
            claim_free = or_(claim_free, m.SerialNumber.remarks.like(
                f"{PROJECT_HOLD_UNIT_PREFIX}{issue_project} %"))
        stmt = stmt.where(claim_free)
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.SerialNumber.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        )).where(m.SerialNumber.is_active.is_(True))
    if status:
        stmt = stmt.where(m.SerialNumber.status == status)
    if item_id:
        stmt = stmt.where(m.SerialNumber.item_id == item_id)
    widen = (scope or "exact").lower()
    if widen == "point":
        pass
    elif widen == "batch":
        if batch_id:
            stmt = stmt.where(m.SerialNumber.batch_id == batch_id)
        elif unbatched:
            stmt = stmt.where(m.SerialNumber.batch_id.is_(None))
    elif batch_id:
        stmt = stmt.where(m.SerialNumber.batch_id == batch_id)
    elif unbatched:
        stmt = stmt.where(m.SerialNumber.batch_id.is_(None))
    # `issue_id` first: with an issue, `claim_free` was rebound to a SQL clause above,
    # and asking a clause for its truth raises TypeError.
    if not issue_id and claim_free:
        stmt = stmt.where(_unit_claim_free_clause(None))
    if warehouse_id:
        stmt = stmt.where(m.SerialNumber.warehouse_id == warehouse_id)
    if bin_id and widen == "exact":
        stmt = stmt.where(m.SerialNumber.bin_id == bin_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.SerialNumber.serial_number.ilike(like),
            m.SerialNumber.imei.ilike(like),
            m.SerialNumber.asset_code.ilike(like),
            m.SerialNumber.consumable_code.ilike(like)))

    page = await paginate(db, stmt.order_by(m.SerialNumber.id.desc()), params)
    hu_of = {row.id: row.handling_unit_id for row in page["items"]}
    page["items"] = await _decorate_serials(db, page["items"])
    # The PACKAGE each unit sits in (2026-10-26), so a lot reads as packages with
    # their codes inside them. One query for the page.
    hu_ids = {v for v in hu_of.values() if v}
    packs = {hu.id: hu for hu in (await db.execute(select(m.HandlingUnit).where(
        m.HandlingUnit.id.in_(hu_ids)))).scalars().all()} if hu_ids else {}
    for row in page["items"]:
        hu = packs.get(hu_of.get(row["id"]))
        if hu is not None and hu.status in box_codes.LIVE:
            row["package_code"] = hu.hu_code
            row["package_name"] = hu.pack_name
            row["package_holds"] = float(wh_packing.held(hu))
    return page


async def serial_summary(db: AsyncSession, *, item_ids: list[int],
                         warehouse_ids: list[int] | None = None,
                         user=None) -> list[dict]:
    """Serials and their asset/consumable codes, grouped by item and stocking point.

    The stock screens live in inventory, which may not import this module (rule 5) and
    has nowhere to keep a per-unit identity: `stk_balance` is one row per LOT and a lot
    here holds up to 88 serials, so its single `serial_number` column cannot answer
    "which units are these". Rather than denormalise 10,000 serials into a column that
    only fits one, the screens ask this endpoint for the page they are showing and
    merge — the same shape as the KPI summary calls beside them.

    Returns a few sample codes plus the count, which is what a list row can show; the
    full list is one `/serials?item_id=&warehouse_id=` call away for the detail panel.
    """
    if not item_ids:
        return []
    stmt = (
        select(m.SerialNumber.item_id, m.SerialNumber.warehouse_id,
               m.SerialNumber.bin_id, m.SerialNumber.batch_id,
               m.SerialNumber.serial_number, m.SerialNumber.imei,
               m.SerialNumber.asset_code, m.SerialNumber.consumable_code)
        .where(m.SerialNumber.item_id.in_(item_ids),
               m.SerialNumber.is_active.is_(True))
        .order_by(m.SerialNumber.id)
    )
    if warehouse_ids:
        stmt = stmt.where(m.SerialNumber.warehouse_id.in_(warehouse_ids))
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.SerialNumber.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        ))

    # Which of these items the master says actually carry a per-unit identity. A unit
    # row for a MEASURED item (cotton in grams, spirit in litres) still holds a real
    # putaway code — the label on the package a storekeeper shelved — but its serial
    # number is an artefact: you cannot serialise a gram. `serial_number` is UNIQUE and
    # NOT NULL on the table, so the artefact cannot be blanked in place; it is
    # suppressed here instead, which keeps the row's key and its code intact.
    tracked = {r[0] for r in (await db.execute(
        select(Item.id).where(Item.id.in_(item_ids),
                              or_(Item.is_serial_tracked.is_(True),
                                  Item.is_imei_tracked.is_(True)))
    )).all()}

    # Keyed down to the BIN and the BATCH, not just the stocking point: "which units
    # are in this bin" is the question the stock screens are actually asked, and one
    # warehouse holds the same item in several bins. The caller indexes the result
    # from the most specific key it has down to item+warehouse, so a serial row that
    # has not been given a bin yet (most of the live data) still finds its lot.
    grouped: dict[tuple, dict] = {}
    for (item_id, warehouse_id, bin_id, batch_id,
         serial, imei, asset, consumable) in (await db.execute(stmt)).all():
        key = (item_id, warehouse_id, bin_id, batch_id)
        bucket = grouped.setdefault(key, {
            "item_id": item_id, "warehouse_id": warehouse_id,
            "bin_id": bin_id, "batch_id": batch_id,
            "count": 0, "serials": [], "imeis": [], "codes": [],
            # Split by kind as well as merged: the stock ledger gives an asset code and
            # a consumable code a column each, and one unit is only ever one of the two.
            "asset_codes": [], "consumable_codes": [],
            "asset_count": 0, "consumable_count": 0,
        })
        bucket["count"] += 1
        # Five is enough to recognise the lot; the rest are behind the detail panel.
        if serial and item_id in tracked and len(bucket["serials"]) < 5:
            bucket["serials"].append(serial)
        if imei and item_id in tracked and len(bucket["imeis"]) < 5:
            bucket["imeis"].append(imei)
        code = asset or consumable
        if code and len(bucket["codes"]) < 5:
            bucket["codes"].append(code)
        if asset:
            bucket["asset_count"] += 1
            if len(bucket["asset_codes"]) < 5:
                bucket["asset_codes"].append(asset)
        elif consumable:
            bucket["consumable_count"] += 1
            if len(bucket["consumable_codes"]) < 5:
                bucket["consumable_codes"].append(consumable)
    return list(grouped.values())


#: How many identities one lookup will answer for. A ledger page is 100 rows at most
#: and a single movement can carry a whole putaway, so the cap is generous; it exists
#: so a hand-built request cannot ask for the whole table in one `IN (...)`.
UNIT_CODE_LOOKUP_CAP = 2000


async def unit_codes(db: AsyncSession, codes: list[str], user=None) -> list[dict]:
    """The other identities carried by units the caller can already name.

    NEW 2026-08-22, for the stock ledger. A `stk_ledger` row names the units that
    MOVED, in `serial_numbers` — but the asset and consumable codes minted at putaway
    live per unit in this module's `whs_serial_numbers`, and inventory may not read it
    (rule 5). Without this the ledger screen had nothing to show in its code columns
    for a serial-tracked movement, so it fell back to the units standing in that lot
    RIGHT NOW: a movement of 2 mice displayed the 198 codes on the shelf behind them.
    A ledger is a record of what happened, and "what is there now" is a different
    question that the balance screen already answers.

    Matched on all three identity columns, not just the serial: `_place_unit_codes`
    writes the minted code into `serial_number` as well for an item with no serial
    tracking of its own (the column is UNIQUE and NOT NULL and there is nothing else
    to put there), so the string a ledger row carries is a serial for one item and a
    consumable code for the next. The caller holds one string per unit and should not
    have to know which kind it is — the same reasoning as `unit_lookup`.

    Scoped like every other read here: a login is told about units at the points it is
    allowed to see, and no others.
    """
    wanted = list(dict.fromkeys(
        c.strip() for c in (codes or []) if c and c.strip()))[:UNIT_CODE_LOOKUP_CAP]
    if not wanted:
        return []

    stmt = (
        select(m.SerialNumber.serial_number, m.SerialNumber.imei,
               m.SerialNumber.asset_code, m.SerialNumber.consumable_code,
               m.SerialNumber.item_id, m.SerialNumber.warehouse_id,
               m.SerialNumber.status)
        .where(or_(m.SerialNumber.serial_number.in_(wanted),
                   m.SerialNumber.asset_code.in_(wanted),
                   m.SerialNumber.consumable_code.in_(wanted)),
               m.SerialNumber.is_active.is_(True))
        .order_by(m.SerialNumber.id)
    )
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.SerialNumber.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        ))

    return [
        {"serial_number": serial, "imei": imei, "asset_code": asset,
         "consumable_code": consumable, "item_id": item_id,
         "warehouse_id": warehouse_id, "status": status}
        for (serial, imei, asset, consumable,
             item_id, warehouse_id, status) in (await db.execute(stmt)).all()
    ]


async def unit_lookup(db: AsyncSession, code: str, user=None) -> dict:
    """Everything known about ONE physical unit, found by any identity it carries.

    Serial, IMEI, asset code or consumable code — a store user has whichever one is
    printed on the label in front of them, and should not have to know which kind it
    is. Exact match first so a full code never loses to a partial one, then a prefix
    match so a half-typed code still finds its unit.
    """
    value = (code or "").strip()
    if not value:
        raise ValidationError("Enter a serial, IMEI, asset code or consumable code")

    cols = (m.SerialNumber.serial_number, m.SerialNumber.imei,
            m.SerialNumber.asset_code, m.SerialNumber.consumable_code)
    base = select(m.SerialNumber).where(m.SerialNumber.is_active.is_(True))
    if user is not None:
        base = base.where(await scope_condition(
            db, user,
            warehouse_col=m.SerialNumber.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
        ))

    row = await db.scalar(base.where(or_(*(c == value for c in cols))))
    if row is None:
        row = await db.scalar(
            base.where(or_(*(c.ilike(f"{value}%") for c in cols)))
            .order_by(m.SerialNumber.id))
    # "Nothing carries this" is an ordinary answer to a search box, not a fault: the
    # stock screens ask on every keystroke, and raising here would file a 404 in
    # sys_app_logs for every word anyone typed while looking for an item by name.
    if row is None:
        return {"found": False, "matched": value}

    unit = await _decorate_serial(db, row)
    unit["found"] = True
    unit["matched"] = value
    return unit


async def _decorate_serials(db: AsyncSession, rows: list[m.SerialNumber]) -> list[dict]:
    """`_decorate_serial` for a whole page, with the lookups done once.

    NOT a micro-optimisation (2026-09-03). The per-row version awaits five times, and
    on a lot standing in ONE bin under ONE batch every one of those is an identity-map
    hit that still pays a full `greenlet_spawn` — about 0.8 ms each. A page of 500 unit
    rows spent 2.09 of its 2.31 seconds in here doing no database work whatsoever, and
    the units panel walks twenty of those pages to show a lot of 10,000. The live table
    holds 324,368 rows with single lots of 100,000, so this is the difference between a
    panel that opens and one the storekeeper gives up on.

    Four queries for the whole page, then a plain synchronous loop.
    """
    if not rows:
        return []

    async def by_id(model, ids: set[int]) -> dict:
        ids = {i for i in ids if i}
        if not ids:
            return {}
        return {r.id: r for r in (await db.execute(
            select(model).where(model.id.in_(ids))
        )).scalars()}

    items = await by_id(Item, {r.item_id for r in rows})
    warehouses = await by_id(Warehouse, {r.warehouse_id for r in rows})
    batches = await by_id(m.Batch, {r.batch_id for r in rows})
    bins = await by_id(Bin, {r.bin_id for r in rows})

    out: list[dict] = []
    for row in rows:
        item = items.get(row.item_id)
        wh = warehouses.get(row.warehouse_id)
        batch = batches.get(row.batch_id)
        b = bins.get(row.bin_id)
        out.append({
            "id": row.id, "item_id": row.item_id,
            "item_code": item.code if item else None,
            "item_name": item.name if item else None,
            "is_asset": bool(getattr(item, "is_asset", False)) if item else False,
            "serial_number": row.serial_number,
            "imei": row.imei,
            "batch_id": row.batch_id, "batch_no": batch.batch_no if batch else None,
            "mfg_date": batch.mfg_date if batch else None,
            "expiry_date": batch.expiry_date if batch else None,
            "warehouse_id": row.warehouse_id, "warehouse_name": wh.name if wh else None,
            "bin_id": row.bin_id, "bin_code": b.code if b else None,
            "bin_floor_level": getattr(b, "floor_level", None) if b else None,
            "asset_code": row.asset_code, "consumable_code": row.consumable_code,
            "status": row.status, "remarks": row.remarks, "is_active": row.is_active,
        })
    return out


async def _decorate_serial(db: AsyncSession, row: m.SerialNumber) -> dict:
    """One unit. The page-at-a-time version above is what list endpoints use."""
    return (await _decorate_serials(db, [row]))[0]


async def list_batches(db: AsyncSession, params: PageParams, *, item_id: int | None = None,
                       expiring_days: int | None = None, search: str | None = None,
                       user=None) -> dict:
    """FIXED 2026-08-20 — was unscoped. `whs_batches` carries the VENDOR a batch came
    from and the GRN it landed on, so an unscoped register told every stock viewer who
    supplies which branch. It has no warehouse column of its own, so it is bounded
    through the stock that actually holds the batch — the same warehouse rung the
    balance grid uses, which keeps the two screens agreeing about which shelves a login
    owns."""
    stmt = select(m.Batch)
    if user is not None:
        allowed = await warehouse_ids_for_user(db, user)
        if allowed is not None:
            from app.modules.inventory.models import Stock
            stmt = stmt.where(m.Batch.id.in_(
                select(Stock.batch_id).where(Stock.warehouse_id.in_(allowed or {0}))))
    if item_id:
        stmt = stmt.where(m.Batch.item_id == item_id)
    if expiring_days is not None:
        cutoff = ist_today() + timedelta(days=expiring_days)
        stmt = stmt.where(m.Batch.expiry_date.isnot(None), m.Batch.expiry_date <= cutoff)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.Batch.batch_no.ilike(like), m.Batch.item_code.ilike(like),
            m.Batch.item_name.ilike(like), m.Batch.grn_no.ilike(like)))
    # MySQL has no `NULLS LAST` syntax. Sorting by the null predicate first is
    # portable and puts dated batches before undated ones.
    page = await paginate(
        db,
        stmt.order_by(m.Batch.expiry_date.is_(None), m.Batch.expiry_date.asc()),
        params,
    )
    item_ids = {row.item_id for row in page["items"]}
    if item_ids:
        rows = (await db.execute(select(Item.id, Item.is_asset).where(Item.id.in_(item_ids)))).all()
        asset_by_item = {item_id: bool(is_asset) for item_id, is_asset in rows}
        for row in page["items"]:
            row.is_asset = asset_by_item.get(row.item_id, False)
    return page


def _dispatch_destination(dispatch: m.Dispatch) -> str | None:
    return (dispatch.to_warehouse_name or dispatch.customer_name
            or dispatch.project_name or dispatch.delivery_address)


_PUBLIC_LABEL_TOKEN = re.compile(r"^([dphu])(\d+)\.([A-Za-z0-9_-]{22})$")


def public_label_token(kind: str, row_id: int) -> str:
    """A short, non-enumerable capability for one printed label.

    ``d`` identifies a whole consignment and ``p`` one package; ``h`` a stock pack
    (a carton or a box on the shelf) and ``u`` one coded unit (2026-10-27). The identifier is
    visible, but changing it invalidates the HMAC, so knowing one label never grants
    access to the next database row. Tokens deliberately do not expire: a physical
    shipping label must remain useful for the life of the consignment. Rotating the
    deployment SECRET_KEY revokes every old label when that is explicitly required.
    """
    if kind not in {"d", "p", "h", "u"} or row_id < 1:
        raise ValueError("Public label tokens require kind d/p/h/u and a positive id")
    message = f"warehouse-public-label:v1:{kind}:{row_id}".encode()
    digest = hmac.new(settings.SECRET_KEY.encode(), message, hashlib.sha256).digest()[:16]
    signature = base64.urlsafe_b64encode(digest).decode().rstrip("=")
    return f"{kind}{row_id}.{signature}"


def parse_public_label_token(token: str) -> tuple[str, int] | None:
    match = _PUBLIC_LABEL_TOKEN.fullmatch((token or "").strip())
    if not match:
        return None
    kind, raw_id, supplied = match.groups()
    row_id = int(raw_id)
    expected = public_label_token(kind, row_id).rsplit(".", 1)[1]
    return (kind, row_id) if hmac.compare_digest(supplied, expected) else None


async def _dispatch_lines(db: AsyncSession, dispatch_id: int) -> list[m.DispatchItem]:
    return list((await db.scalars(
        select(m.DispatchItem).where(m.DispatchItem.dispatch_id == dispatch_id)
        .order_by(m.DispatchItem.line_no)
    )).all())


def _scan_line(line: m.DispatchItem, package_no: str | None = None,
               unit_code: str | None = None) -> s.ScanLine:
    return s.ScanLine(
        item_code=line.item_code, item_name=line.item_name, uom_code=line.uom_code,
        quantity=line.quantity or Decimal(0), batch_no=line.batch_no,
        serial_no=line.serial_no, package_no=package_no,
        imei_no=line.imei_no, expiry_date=line.expiry_date, unit_code=unit_code,
    )


async def _unit_codes(db: AsyncSession,
                      lines: list[m.DispatchItem]) -> dict[tuple[int, int | None], str]:
    """The asset / consumable code for each (item, batch) a scan is about to show.

    One query for the whole scan, not one per line. The codes live on `stk_balance`
    (put-away mints them there), and warehouse may not import inventory's service —
    rule 5 — so this reads the model directly and writes nothing.
    """
    # Imported here, as elsewhere in this file: the model is inventory's and a
    # module-level import of it is not worth widening for one lookup.
    from app.modules.inventory.models import Stock

    keys = {(line.item_id, line.batch_id) for line in lines if line.item_id}
    if not keys:
        return {}
    rows = (await db.execute(
        select(Stock.item_id, Stock.batch_id, Stock.asset_code, Stock.consumable_code)
        .where(Stock.item_id.in_({item_id for item_id, _ in keys}))
    )).all()
    found: dict[tuple[int, int | None], str] = {}
    for item_id, batch_id, asset_code, consumable_code in rows:
        code = asset_code or consumable_code
        if code:
            found.setdefault((item_id, batch_id), code)
    # Fall back to any code held for the item when the batch does not line up: an
    # allocation-drafted issue carries no batch_id, and "no code at all" is a worse
    # answer than the code the item's stock actually holds.
    by_item = {item_id: code for (item_id, _), code in found.items()}
    return {key: found.get(key) or by_item.get(key[0]) for key in keys
            if found.get(key) or by_item.get(key[0])}


async def _scanned_dispatch(db: AsyncSession, dispatch: m.Dispatch) -> s.ScanResult:
    """A consignment label answers with the cartons it holds."""
    lines = await _dispatch_lines(db, dispatch.id)
    packages = list((await db.scalars(
        select(m.DispatchPackage).where(m.DispatchPackage.dispatch_id == dispatch.id)
        .order_by(m.DispatchPackage.id)
    )).all())
    by_package: dict[int | None, list[m.DispatchItem]] = defaultdict(list)
    for line in lines:
        by_package[line.package_id].append(line)
    package_no_by_id = {pkg.id: pkg.package_no for pkg in packages}
    unit_codes = await _unit_codes(db, lines)

    return s.ScanResult(
        kind="DISPATCH", id=dispatch.id, doc_no=dispatch.dispatch_no,
        deep_link=f"/warehouse/dispatch/consignments/{dispatch.id}",
        title=f"Consignment {dispatch.dispatch_no}",
        subtitle=f"Material issue {dispatch.ref_no}" if dispatch.ref_no else None,
        status=dispatch.status,
        meta=[
            {"label": "From", "value": dispatch.warehouse_name},
            {"label": "Destination", "value": _dispatch_destination(dispatch)},
            {"label": "Date", "value": str(dispatch.dispatch_date) if dispatch.dispatch_date else None},
            {"label": "Vehicle", "value": dispatch.vehicle_number},
        ],
        packages=[
            s.ScanPackage(
                id=pkg.id, package_no=pkg.package_no, barcode=pkg.barcode,
                package_type=pkg.package_type, status=pkg.status,
                item_count=len(by_package.get(pkg.id, [])),
                quantity=sum((line.quantity or Decimal(0) for line in by_package.get(pkg.id, [])),
                             Decimal(0)),
                weight_kg=pkg.weight_kg, is_fragile=bool(pkg.is_fragile),
                is_temp_controlled=bool(pkg.is_temp_controlled),
            )
            for pkg in packages
        ],
        # Unpacked lines included: a consignment scanned mid-packing must still say
        # what it is carrying, not report an empty load.
        items=[_scan_line(line, package_no_by_id.get(line.package_id),
                          unit_codes.get((line.item_id, line.batch_id)))
               for line in lines],
        package_count=len(packages),
        item_count=len(lines),
        total_qty=sum((line.quantity or Decimal(0) for line in lines), Decimal(0)),
    )


async def _scanned_package(db: AsyncSession, value: str) -> s.ScanResult | None:
    """A carton label answers with the item codes, names and counts inside it.

    Matched on the stored barcode first, then on `<DISPATCH_NO>|<PACKAGE_NO>`, because
    the barcode a label prints is minted from the material issue's number while the
    fallback the screen renders uses the consignment's.
    """
    head, _, tail = value.partition("|")
    tail = tail.strip()
    pkg = await db.scalar(select(m.DispatchPackage).where(m.DispatchPackage.barcode == value))
    if not pkg and tail:
        pkg = await db.scalar(
            select(m.DispatchPackage)
            .join(m.Dispatch, m.Dispatch.id == m.DispatchPackage.dispatch_id)
            .where(m.Dispatch.dispatch_no == head, m.DispatchPackage.package_no == tail))
    if not pkg:
        return None

    return await _scanned_package_row(db, pkg)


async def _scanned_package_row(db: AsyncSession, pkg: m.DispatchPackage) -> s.ScanResult:
    """The package result once its signed token or printed barcode found the row."""

    dispatch = await db.get(m.Dispatch, pkg.dispatch_id)
    lines = [line for line in await _dispatch_lines(db, pkg.dispatch_id)
             if line.package_id == pkg.id]
    unit_codes = await _unit_codes(db, lines)
    return s.ScanResult(
        kind="PACKAGE", id=pkg.id, doc_no=pkg.package_no,
        deep_link=f"/warehouse/dispatch/consignments/{pkg.dispatch_id}",
        title=f"Package {pkg.package_no}",
        subtitle=f"Consignment {dispatch.dispatch_no}" if dispatch else None,
        status=pkg.status,
        meta=[
            {"label": "From", "value": dispatch.warehouse_name if dispatch else None},
            {"label": "Type", "value": pkg.package_type},
            {"label": "Weight", "value": f"{pkg.weight_kg} kg" if pkg.weight_kg else None},
            {"label": "Consignment", "value": dispatch.dispatch_no if dispatch else None},
            {"label": "Destination", "value": _dispatch_destination(dispatch) if dispatch else None},
        ],
        items=[_scan_line(line, pkg.package_no,
                          unit_codes.get((line.item_id, line.batch_id)))
               for line in lines],
        item_count=len(lines),
        total_qty=sum((line.quantity or Decimal(0) for line in lines), Decimal(0)),
    )


async def public_label_scan(db: AsyncSession, token: str) -> s.ScanResult:
    """Current read-only label details for a valid, unguessable printed capability."""
    parsed = parse_public_label_token(token)
    if not parsed:
        # The same answer for malformed, forged and absent rows: the public endpoint
        # never becomes an oracle for database identifiers.
        raise NotFoundError("This consignment label is not valid")
    kind, row_id = parsed
    if kind in {"h", "u"}:
        # A stock pack or a unit label (2026-10-27): live, read-only, and never the
        # employee-only parts (who holds it, the unit codes inside).
        row = await db.get(m.HandlingUnit if kind == "h" else m.SerialNumber, row_id)
        if row is None:
            raise NotFoundError("This label is not valid")
        built = (await box_codes.scan_pack(db, row, public=True) if kind == "h"
                 else await box_codes.scan_unit(db, row, public=True))
        return s.ScanResult(**built)
    if kind == "d":
        dispatch = await db.get(m.Dispatch, row_id)
        if not dispatch:
            raise NotFoundError("This consignment label is not valid")
        result = await _scanned_dispatch(db, dispatch)
        # A consignment label is a summary, not a packing manifest. Keep only the
        # package count; package identities and item details belong to package QRs.
        result.packages = []
        result.items = []
        result.item_count = 0
        result.total_qty = Decimal(0)
    else:
        package = await db.get(m.DispatchPackage, row_id)
        if not package:
            raise NotFoundError("This consignment label is not valid")
        result = await _scanned_package_row(db, package)
    # A public label is a dead end by design. Never send the employee application's
    # document route even though the internal scanner uses the same response shape.
    result.deep_link = None
    return result


async def scan(db: AsyncSession, code: str) -> s.ScanResult:
    """Works out what a scanned code is.

    One endpoint rather than one per kind, because a scanner cannot tell the operator
    which screen to be on first. Order matters: document numbers are checked before
    bins so a code that could be either resolves to the document someone scanned it
    from.

    A package label carries a pipe (`<ISSUE_OR_DISPATCH_NO>|PKG-01`) and no document
    number ever does, so the package lookup runs first: the head of a package label is
    the material issue's number, and without this it resolved to the issue instead of
    the carton that was actually in someone's hand.
    """
    value = (code or "").strip()
    if not value:
        raise ValidationError("Nothing was scanned")

    head = value.split("|")[0]

    if "|" in value:
        pkg = await _scanned_package(db, value)
        if pkg:
            return pkg

    dispatch = await db.scalar(select(m.Dispatch).where(m.Dispatch.dispatch_no == head))
    if dispatch:
        return await _scanned_dispatch(db, dispatch)

    receipt = await db.scalar(select(m.Receipt).where(
        or_(m.Receipt.grn_no == head, m.Receipt.gate_entry_no == head)))
    if receipt:
        return s.ScanResult(kind="RECEIPT", id=receipt.id, doc_no=receipt.grn_no,
                            deep_link=f"/warehouse/transactions/grn/{receipt.id}")

    issue = await db.scalar(select(m.MaterialIssue).where(m.MaterialIssue.issue_no == head))
    if issue:
        return s.ScanResult(kind="ISSUE", id=issue.id, doc_no=issue.issue_no,
                            deep_link=f"/warehouse/transactions/material-issues/{issue.id}")

    # A carton, a box or a strip on the shelf (2026-10-27): what it is, where it is
    # now and what is inside it, read live.
    pack = await db.scalar(select(m.HandlingUnit).where(m.HandlingUnit.hu_code == value))
    if pack:
        return s.ScanResult(**await box_codes.scan_pack(db, pack))

    serial = await db.scalar(select(m.SerialNumber).where(
        or_(m.SerialNumber.serial_number == value, m.SerialNumber.asset_code == value,
            m.SerialNumber.consumable_code == value, m.SerialNumber.imei == value))
        .order_by(m.SerialNumber.is_active.desc(), m.SerialNumber.id.desc()).limit(1))
    if serial:
        return s.ScanResult(**await box_codes.scan_unit(db, serial))

    bin_row = await db.scalar(select(Bin).where(Bin.code == value))
    if bin_row:
        return s.ScanResult(kind="BIN", id=bin_row.id, doc_no=bin_row.code, deep_link=None)

    raise NotFoundError(f"Nothing in the warehouse matches {value}")


# ---------------------------------------------------------------------------
# Attachments and notifications
# ---------------------------------------------------------------------------

# The implementation moved to platform/settings/attachments.py so indents can use the
# same store for delivery photos and bills. Re-exported under the names the warehouse
# router already calls, so its endpoints are unchanged.
list_attachments = attachments.list_attachments
attachment_file = attachments.attachment_file


async def add_attachment(db: AsyncSession, *, entity_type: str, entity_id: int,
                         upload, doc_category: str | None, user):
    """File one against a warehouse document this login may actually work.

    FIXED 2026-09-03 — this was the platform function re-exported raw, and its route
    takes `entity_type` and `entity_id` as FORM FIELDS. Anyone holding `receipt.create`
    could therefore post a file against any receipt, inspection, issue or dispatch in
    the company, at any warehouse — false evidence filed on somebody else's document,
    which is the whole reason attachments exist on these papers. `assert_attachment_scope`
    is the same check the list and download routes have run since they were fixed; it
    also refuses an `entity_type` that is not one of the four, so the form field can no
    longer file bytes under an arbitrary key that only another module reads.
    """
    await assert_attachment_scope(db, user, entity_type, entity_id)
    return await attachments.add_attachment(
        db, entity_type=entity_type, entity_id=entity_id, upload=upload,
        doc_category=doc_category, user=user)


async def delete_attachment(db: AsyncSession, attachment_id: int, user) -> None:
    """Remove one, once this login is proved to hold the document it hangs on.

    FIXED 2026-09-03 — likewise re-exported raw, and addressed by attachment id alone.
    `receipt.create` was a licence to delete ANY row in `sys_attachments`: another
    warehouse's QC photographs, an indent's delivery proof, a shipment's way bill.
    The row is read first so the check runs against the document it actually names.
    """
    row = await attachments.require_attachment(
        db, attachment_id, entity_type=tuple(_ATTACHMENT_PARENTS))
    await assert_attachment_scope(db, user, row.entity_type, row.entity_id)
    await attachments.delete_attachment(
        db, attachment_id, user,
        entity_type=row.entity_type, entity_id=row.entity_id)


async def list_notifications(db: AsyncSession, params: PageParams, user, *,
                             unread_only: bool = False) -> dict:
    stmt = select(m.Notification).where(m.Notification.employee_id == getattr(user, "id", 0))
    if unread_only:
        stmt = stmt.where(m.Notification.is_read.is_(False))
    return await paginate(db, stmt.order_by(m.Notification.id.desc()), params)


async def mark_notification_read(db: AsyncSession, notification_id: int,
                                 user) -> m.Notification:
    row = await _get(db, m.Notification, notification_id, "Notification")
    if row.employee_id != getattr(user, "id", None):
        raise NotFoundError(f"Notification {notification_id} not found")
    row.is_read = True
    await db.commit()
    await db.refresh(row)
    return row


async def mark_all_notifications_read(db: AsyncSession, user) -> dict:
    rows = (await db.execute(
        select(m.Notification).where(
            m.Notification.employee_id == getattr(user, "id", 0),
            m.Notification.is_read.is_(False))
    )).scalars().all()
    for row in rows:
        row.is_read = True
    await db.commit()
    return {"updated": len(rows)}


# ---------------------------------------------------------------------------
# Acknowledgements owed by a requester
# ---------------------------------------------------------------------------

# Statuses at which a consignment has physically left the warehouse. Before these it is
# still on site however finished the paperwork looks.
_ON_THE_ROAD = (
    DispatchStatus.DISPATCHED.value,
    DispatchStatus.IN_TRANSIT.value,
    DispatchStatus.DELIVERED.value,
    DispatchStatus.ACKNOWLEDGED.value,
)


def _pending_with(approved: Decimal, issued: Decimal, dispatched: Decimal,
                  received: Decimal, indent_status: str,
                  on_order: Decimal = ZERO) -> str | None:
    """Plain-English answer to "where is the rest of my stuff".

    Read top-down: the nearest place the goods have got to is the honest answer. Derived
    at read time from the issue and dispatch state, never stored, so it cannot go stale
    behind the documents it describes.

    `on_order` is THIS LINE's quantity sitting with procurement, and it is asked before
    the indent status because the indent status answers for the whole document. An
    indent whose first line was served off the shelf and whose second went out to be
    bought is PARTIALLY_FULFILLED, so the status branch below never fired and the
    bought line was described as sitting "in the warehouse, not yet issued" — the one
    place it certainly was not.
    """
    if received >= approved:
        return None
    if dispatched > received:
        return "On the way to you"
    if issued > dispatched:
        return "Issued, waiting to be dispatched"
    if on_order > ZERO:
        return "With procurement"
    if indent_status in (IndentStatus.PENDING_PROCUREMENT.value,
                         IndentStatus.PARTIALLY_ORDERED.value,
                         IndentStatus.ORDERED.value):
        return "With procurement"
    return "In the warehouse, not yet issued"


def _relayed_onward():
    """True for an issue line whose goods did NOT stop at the delivery point.

    WH -> MDP -> LIP is one indent served by TWO posted issues, both carrying the same
    `indent_item_id`. Summing them told the requester an approved quantity of 1 had
    been issued twice — "2 waiting for you to confirm" against a single unit.

    The leg that must not count is the one whose dispatch handed the goods to another
    stocking point WHICH THEN ISSUED THEM ON. Both halves matter: a dispatch to a LIP
    also names a `to_warehouse_id`, and dropping every leg with one would have blanked
    the direct WH -> LIP flow, where that first leg is the whole delivery.

    Correlated per LINE, not per document: a consignment part-forwarded and part-held
    at the MDP should count only what actually moved on.
    """
    onward = aliased(m.MaterialIssue)
    onward_line = aliased(m.MaterialIssueLine)
    return (
        select(onward_line.id)
        .select_from(m.Dispatch)
        .join(onward, and_(
            onward.warehouse_id == m.Dispatch.to_warehouse_id,
            onward.id != m.MaterialIssueLine.issue_id,
            onward.direction == IssueDirection.OUT.value,
            onward.is_stock_posted.is_(True),
        ))
        .join(onward_line, and_(
            onward_line.issue_id == onward.id,
            onward_line.indent_item_id == m.MaterialIssueLine.indent_item_id,
        ))
        .where(
            _carries_issue(m.MaterialIssueLine.issue_id),
            m.Dispatch.to_warehouse_id.isnot(None),
        )
        .exists()
    )


async def _package_rows_packed(db: AsyncSession, rows_by_line: dict, *, by: str) -> None:
    """Put each package's OWN packs of a line on its acknowledgement row (2026-10-22)
    — what the packer put in that carton, not the issued packs repeated. `by` says
    what the rows are keyed on: an indent line, or (direct issue) the item."""
    package_ids = {p["package_id"] for rows in rows_by_line.values() for p in rows
                   if p.get("package_id")}
    if not package_ids:
        return
    packs_by_package: dict[int, list] = {}
    for package_id, entries in (await db.execute(
            select(m.DispatchPackage.id, m.DispatchPackage.item_packs)
            .where(m.DispatchPackage.id.in_(package_ids)))).all():
        if isinstance(entries, str):
            entries = json.loads(entries or "null")
        packs_by_package[package_id] = entries or []
    issue_line_ids = {int(e["issue_item_id"]) for entries in packs_by_package.values()
                      for e in entries if e.get("issue_item_id")}
    column = {"indent_item": m.MaterialIssueLine.indent_item_id,
              "item": m.MaterialIssueLine.item_id}[by]
    owner = dict((await db.execute(
        select(m.MaterialIssueLine.id, column)
        .where(m.MaterialIssueLine.id.in_(issue_line_ids or {0})))).all())
    for line_key, rows in rows_by_line.items():
        for row in rows:
            parts = [e.get("pack_breakdown") or []
                     for e in packs_by_package.get(row.get("package_id"), [])
                     if e.get("issue_item_id") and owner.get(int(e["issue_item_id"])) == line_key]
            merged = wh_packing.merge_breakdowns(parts) if parts else None
            if merged:
                row["pack_breakdown"] = merged["pack_breakdown"]
                row["pack_text"] = merged["pack_text"]


async def _delivery_rows(db: AsyncSession, indents: list) -> list[dict]:
    """Approved / issued / dispatched / received per line, for a set of indents.

    Shared by the requester's delivery list and by one indent's fulfilment trail, so the
    two can never disagree about how far an order has got.
    """
    from app.modules.indents.models import IndentItem
    from app.modules.indents.service import _on_order_by_lines, owed_quantity

    if not indents:
        return []

    indent_ids = [indent.id for indent in indents]
    relayed = _relayed_onward()
    # Posted issues only: a draft or in-approval issue has moved nothing, and showing it
    # as "issued" would tell the requester their goods are on the way when they are not.
    issued_rows = (await db.execute(
        select(m.MaterialIssueLine.indent_item_id,
               func.sum(m.MaterialIssueLine.issued_qty - func.coalesce(m.MaterialIssueLine.returned_qty, 0)))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .where(m.MaterialIssue.indent_id.in_(indent_ids),
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(True),
               m.MaterialIssueLine.indent_item_id.isnot(None),
               ~relayed)
        .group_by(m.MaterialIssueLine.indent_item_id)
    )).all()
    issued_by_line = {row[0]: _d(row[1]) for row in issued_rows}

    dispatched_rows = (await db.execute(
        select(m.MaterialIssueLine.indent_item_id,
               func.sum(m.MaterialIssueLine.issued_qty - func.coalesce(m.MaterialIssueLine.returned_qty, 0)))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .join(m.Dispatch, _carries_issue(m.MaterialIssue.id))
        .where(m.MaterialIssue.indent_id.in_(indent_ids),
               m.MaterialIssue.is_stock_posted.is_(True),
               m.Dispatch.status.in_(_ON_THE_ROAD),
               m.MaterialIssueLine.indent_item_id.isnot(None),
               ~relayed)
        .group_by(m.MaterialIssueLine.indent_item_id)
    )).all()
    dispatched_by_line = {row[0]: _d(row[1]) for row in dispatched_rows}

    # The packs those dispatched lines travel in, per indent line (2026-10-22): the
    # same issue lines as the total above, merged when several served one line.
    sent_lines = (await db.execute(
        select(m.MaterialIssueLine.id, m.MaterialIssueLine.indent_item_id,
               m.MaterialIssueLine.issued_qty - func.coalesce(m.MaterialIssueLine.returned_qty, 0))
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .join(m.Dispatch, _carries_issue(m.MaterialIssue.id))
        .where(m.MaterialIssue.indent_id.in_(indent_ids),
               m.MaterialIssue.is_stock_posted.is_(True),
               m.Dispatch.status.in_(_ON_THE_ROAD),
               m.MaterialIssueLine.indent_item_id.isnot(None),
               ~relayed)
        .distinct())).all()
    sent_packs = await wh_packing.issue_line_packs(db, {r[0]: _d(r[2]) for r in sent_lines})
    packs_by_indent_line: dict[int, list] = defaultdict(list)
    for line_id, indent_item_id, _qty in sent_lines:
        if line_id in sent_packs:
            packs_by_indent_line[indent_item_id].append(sent_packs[line_id]["pack_breakdown"])

    # Preserve the physical packing split for the requester. This query is scoped to
    # the same visible indents and posted outbound issues as the delivery totals above;
    # it does not widen RBAC access, it only describes packages already in those rows.
    package_rows = (await db.execute(
        select(
            m.MaterialIssueLine.indent_item_id,
            m.Dispatch.id,
            m.Dispatch.dispatch_no,
            m.DispatchItem.package_id,
            m.DispatchPackage.package_no,
            func.sum(m.DispatchItem.quantity),
            m.DispatchPackage.package_type,
            m.DispatchPackage.barcode,
            m.DispatchPackage.weight_kg,
            m.DispatchPackage.length_cm,
            m.DispatchPackage.width_cm,
            m.DispatchPackage.height_cm,
            m.DispatchPackage.is_fragile,
            m.DispatchPackage.is_temp_controlled,
            m.DispatchPackage.packed_by_name,
            m.DispatchPackage.packed_at,
        )
        .select_from(m.DispatchItem)
        .join(m.Dispatch, m.Dispatch.id == m.DispatchItem.dispatch_id)
        .join(m.MaterialIssue, and_(
            _carries_issue(m.MaterialIssue.id),
            # On a grouped consignment each line names the issue it was packed from;
            # without this a line would be counted once per issue carrying its item.
            or_(m.DispatchItem.issue_id.is_(None),
                m.DispatchItem.issue_id == m.MaterialIssue.id)))
        .join(m.MaterialIssueLine, and_(
            m.MaterialIssueLine.issue_id == m.MaterialIssue.id,
            m.MaterialIssueLine.item_id == m.DispatchItem.item_id,
            m.MaterialIssueLine.indent_item_id.isnot(None)))
        .join(IndentItem, and_(
            IndentItem.id == m.MaterialIssueLine.indent_item_id,
            IndentItem.indent_id == m.DispatchItem.indent_id,
            IndentItem.item_id == m.DispatchItem.item_id))
        .join(m.DispatchPackage, m.DispatchPackage.id == m.DispatchItem.package_id)
        .where(IndentItem.indent_id.in_(indent_ids),
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(True),
               m.Dispatch.status.in_(_ON_THE_ROAD),
               m.DispatchItem.package_id.isnot(None),
               ~relayed)
        .group_by(m.MaterialIssueLine.indent_item_id,
                  m.Dispatch.id,
                  m.Dispatch.dispatch_no,
                  m.DispatchItem.package_id,
                  m.DispatchPackage.package_no,
                  m.DispatchPackage.package_type,
                  m.DispatchPackage.barcode,
                  m.DispatchPackage.weight_kg,
                  m.DispatchPackage.length_cm,
                  m.DispatchPackage.width_cm,
                  m.DispatchPackage.height_cm,
                  m.DispatchPackage.is_fragile,
                  m.DispatchPackage.is_temp_controlled,
                  m.DispatchPackage.packed_by_name,
                  m.DispatchPackage.packed_at)
        .order_by(m.Dispatch.id, m.DispatchPackage.id)
    )).all()
    packages_by_line: dict[int, list[dict]] = defaultdict(list)
    for row in package_rows:
        packages_by_line[row[0]].append({
            "dispatch_id": row[1],
            "dispatch_no": row[2],
            "package_id": row[3],
            "package_no": row[4],
            "quantity": float(_d(row[5])),
            "package_type": row[6],
            "barcode": row[7],
            "weight_kg": float(_d(row[8])) if row[8] is not None else None,
            "length_cm": float(_d(row[9])) if row[9] is not None else None,
            "width_cm": float(_d(row[10])) if row[10] is not None else None,
            "height_cm": float(_d(row[11])) if row[11] is not None else None,
            "is_fragile": bool(row[12]),
            "is_temp_controlled": bool(row[13]),
            "packed_by_name": row[14],
            "packed_at": row[15],
        })
    await _package_rows_packed(db, packages_by_line, by="indent_item")
    # The PACKAGES each carton holds of a line issued in packages (2026-10-26) — the
    # site checks them carton by carton.
    carton_ids = {row["package_id"] for rows in packages_by_line.values() for row in rows}
    if carton_ids:
        item_of_line = {item.id: item.item_id for indent in indents for item in indent.items}
        in_carton: dict[tuple, list[dict]] = defaultdict(list)
        for package_id, item_id, code, qty, got, status in (await db.execute(
                select(m.DispatchItem.package_id, m.DispatchItem.item_id,
                       m.DispatchItem.box_code, m.DispatchItem.quantity,
                       m.DispatchItem.delivered_qty, m.Dispatch.status)
                .join(m.Dispatch, m.Dispatch.id == m.DispatchItem.dispatch_id)
                .where(m.DispatchItem.package_id.in_(carton_ids),
                       m.DispatchItem.box_code.isnot(None))
                .order_by(m.DispatchItem.id))).all():
            in_carton[(package_id, item_id)].append({
                "code": code, "quantity": float(_d(qty)),
                # What arrived in it, once the consignment is signed for (2026-10-26).
                "received": (float(_d(got)) if status == DispatchStatus.ACKNOWLEDGED.value
                             else None)})
        # Carton › box, and the strips inside each (2026-10-28): the site checks a
        # delivery the way it was packed, and may mark one strip of a box short.
        await box_codes.decorate_packs(db, [r for rows in in_carton.values() for r in rows])
        for line_id, rows in packages_by_line.items():
            for row in rows:
                row["box_codes"] = in_carton.get((row["package_id"], item_of_line.get(line_id)), [])

    # ------------------------------------------------------------------
    # Which physical units left for each (indent, item)
    # ------------------------------------------------------------------
    # `whs_serial_numbers` is the only per-UNIT record there is, and it carries no
    # foreign key to the document moving it — the link is `remarks`, a stamp that is
    # REWRITTEN at every doorway the unit passes through. So the read has to name
    # every stamp a unit may be wearing right now, and attribute it through the issue
    # LINE rather than the issue header. Both halves failed silently as "Not recorded"
    # on a line that plainly had serials:
    #
    #   * a consignment credited at its destination re-stamps its units
    #     `Received by <dispatch_no>` (`_land_units`), so every delivery to an LIP or
    #     an MDP lost its serials at the moment the goods arrived — which is exactly
    #     when the requester opens this screen to acknowledge them;
    #   * a reservation is stamped per LINE (`_issue_line_serial_marker`), not per
    #     document, so units captured on an approved-but-unposted issue matched none
    #     of the document-level markers;
    #   * the issue HEADER names one indent and a consolidated issue serves several
    #     on its lines, so one indent collected every unit on the issue and the others
    #     were told nothing had been recorded.
    issue_line_rows = (await db.execute(
        select(m.MaterialIssueLine.issue_id, m.MaterialIssueLine.id,
               m.MaterialIssueLine.item_id, IndentItem.indent_id)
        .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
        .join(IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id)
        .where(IndentItem.indent_id.in_(indent_ids),
               m.MaterialIssue.direction == IssueDirection.OUT.value,
               m.MaterialIssue.is_stock_posted.is_(True),
               ~relayed)
    )).all()

    # marker -> {item_id: {indent_id, ...}}. A per-line stamp resolves to exactly one
    # line; the document-level ones are shared by the issue's lines, so the item is
    # what tells them apart.
    marker_targets: dict[str, dict[int, set[int]]] = defaultdict(lambda: defaultdict(set))
    issue_ids: set[int] = set()
    for issue_id, line_id, item_id, indent_id in issue_line_rows:
        issue_ids.add(issue_id)
        for marker in (*_issue_serial_markers(issue_id),
                       _issue_line_serial_marker(issue_id, line_id)):
            marker_targets[marker][item_id].add(indent_id)

    # The consignments carrying those issues. A credited arrival re-stamps the units
    # with the consignment's number, which is the only trace left of where they came
    # from — so the dispatch number is a marker like any other.
    dispatch_rows = (await db.execute(
        select(m.Dispatch.id, m.Dispatch.dispatch_no, m.MaterialIssue.id)
        .join(m.MaterialIssue, _carries_issue(m.MaterialIssue.id))
        .where(m.MaterialIssue.id.in_(issue_ids or {0}),
               m.Dispatch.status != DispatchStatus.CANCELLED.value)
    )).all() if issue_ids else []
    dispatch_ids: list[int] = []
    for dispatch_id, dispatch_no, issue_id in dispatch_rows:
        dispatch_ids.append(dispatch_id)
        source = marker_targets.get(_shipped_unit_marker("issue", issue_id), {})
        for marker in (_shipped_unit_marker("dispatch", dispatch_id),
                       f"Received by {dispatch_no}" if dispatch_no else None):
            if not marker:
                continue
            for item_id, indents_for_item in source.items():
                marker_targets[marker][item_id] |= indents_for_item

    serials_by_indent_item: dict[tuple[int, int], list[str]] = defaultdict(list)

    def _record(indent_id: int, item_id: int, code: str | None) -> None:
        value = str(code or "").strip()
        if not value:
            return
        bucket = serials_by_indent_item[(indent_id, item_id)]
        if value not in bucket:
            bucket.append(value)

    if marker_targets:
        # Named by whichever identifier the unit actually carries — `serial_number`
        # alone left an IMEI-tracked handset and an asset-coded unit reading "Not
        # recorded" while their labels sat one column over. `_unit_keys` is the same
        # answer the picker gives, so the acknowledgement and the issue speak about a
        # unit with one name.
        unit_rows = (await db.execute(
            select(m.SerialNumber)
            .where(m.SerialNumber.remarks.in_(list(marker_targets)),
                   m.SerialNumber.is_active.is_(True))
            .order_by(m.SerialNumber.id)
        )).scalars().all()
        modes: dict[int, str] = {}
        for row in unit_rows:
            targets = marker_targets.get(row.remarks or "", {}).get(row.item_id)
            if not targets:
                continue
            if row.item_id not in modes:
                modes[row.item_id] = _unit_mode(await db.get(Item, row.item_id))
            keys = _unit_keys(row, modes[row.item_id])
            code = keys[0] if keys else (row.serial_number or row.asset_code
                                         or row.consumable_code or row.imei)
            for indent_id in sorted(targets):
                _record(indent_id, row.item_id, code)

    # The consignment's own per-unit lines, for a load gated out without an issue
    # behind it — those units are stamped against the dispatch, never against an issue.
    if dispatch_ids:
        dispatch_serial_rows = (await db.execute(
            select(m.Dispatch.id, m.DispatchItem.item_id, m.DispatchItem.serial_no)
            .join(m.DispatchItem, m.DispatchItem.dispatch_id == m.Dispatch.id)
            .where(m.Dispatch.id.in_(dispatch_ids),
                   m.Dispatch.status.in_(_ON_THE_ROAD),
                   m.DispatchItem.serial_no.isnot(None))
            .order_by(m.Dispatch.id, m.DispatchItem.item_id, m.DispatchItem.line_no)
        )).all()
        # (dispatch_id, dispatch_no, issue_id) — the issue is what the markers key on.
        by_dispatch = {row[0]: row[2] for row in dispatch_rows}
        for dispatch_id, item_id, serial_no in dispatch_serial_rows:
            issue_id = by_dispatch.get(dispatch_id)
            targets = (marker_targets
                       .get(_shipped_unit_marker("issue", issue_id), {})
                       .get(item_id, set())) if issue_id else set()
            for indent_id in sorted(targets):
                _record(indent_id, item_id, serial_no)

    shipments = await _shipments_by_indent(db, indent_ids)

    # What of each line somebody is already BUYING. The indents module owns the
    # definition of "on order" (`_SETTLED_MR_STATUSES`) and the fulfilment desk's
    # remainder is netted by the same function — reading it here rather than writing a
    # second query is what keeps the requester's screen and the desk from disagreeing
    # about whether a line went out to procurement.
    on_order_by_line = await _on_order_by_lines(
        db, [item.id for indent in indents for item in indent.items])
    item_ids = {item.item_id for indent in indents for item in indent.items}
    # WHICH identifier the requester is being asked to match, not merely whether one
    # exists. `is_serial_tracked` alone answered for every item that names its units,
    # so an IMEI-tracked handset and an asset-coded unit showed no panel at all —
    # `_tracking_type` is the same served answer the picker uses, and it is asked per
    # LINE because an item may be asset-coded in the master with nothing coded here.
    item_rows = {
        row.id: row
        for row in (await db.execute(
            select(Item).where(Item.id.in_(item_ids))
        )).scalars().all()
    } if item_ids else {}

    shipments = await _shipments_by_indent(db, indent_ids)

    # What was actually ISSUED against each line, by brand / variant / model
    # (2026-10-26) — off the posted issue lines, so a brand the desk substituted, or
    # stock with no brand recorded, reads as what arrived rather than as what the
    # indent asked for.
    issued_combos: dict[int, list[dict]] = {}
    line_ids = [item.id for indent in indents for item in indent.items]
    if line_ids:
        for row in (await db.execute(
                select(m.MaterialIssueLine.indent_item_id, m.MaterialIssueLine.brand_id,
                       m.MaterialIssueLine.variant_id, m.MaterialIssueLine.model_id,
                       m.MaterialIssueLine.brand_name, m.MaterialIssueLine.variant_name,
                       m.MaterialIssueLine.model_name,
                       func.sum(m.MaterialIssueLine.issued_qty))
                .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
                .where(m.MaterialIssueLine.indent_item_id.in_(line_ids),
                       m.MaterialIssue.is_stock_posted.is_(True),
                       m.MaterialIssue.direction == IssueDirection.OUT.value)
                .group_by(m.MaterialIssueLine.indent_item_id, m.MaterialIssueLine.brand_id,
                          m.MaterialIssueLine.variant_id, m.MaterialIssueLine.model_id,
                          m.MaterialIssueLine.brand_name, m.MaterialIssueLine.variant_name,
                          m.MaterialIssueLine.model_name))).all():
            line_id, b, v, mo, bn, vn, mn, qty = row
            issued_combos.setdefault(int(line_id), []).append({
                "brand_id": int(b or 0), "variant_id": int(v or 0), "model_id": int(mo or 0),
                "brand_name": bn, "variant_name": vn, "model_name": mn,
                "no_brand": not int(b or 0), "quantity": float(qty or 0)})

    # Issued in BOXES (2026-10-26): the boxes each indent line went out in — the
    # receiving site checks boxes, never one code per piece.
    boxes_by_line: dict[int, list[dict]] = {}
    if line_ids:
        for issue_id, issue_line_id, indent_line_id in (await db.execute(
                select(m.MaterialIssue.id, m.MaterialIssueLine.id,
                       m.MaterialIssueLine.indent_item_id)
                .join(m.MaterialIssue, m.MaterialIssue.id == m.MaterialIssueLine.issue_id)
                .where(m.MaterialIssueLine.indent_item_id.in_(line_ids),
                       m.MaterialIssue.is_stock_posted.is_(True),
                       m.MaterialIssue.direction == IssueDirection.OUT.value))).all():
            for box in await box_codes.line_boxes(db, issue_id, issue_line_id):
                boxes_by_line.setdefault(int(indent_line_id), []).append({
                    "code": box.hu_code, "pack_name": box.pack_name,
                    "quantity": float(box_codes.held(box))})
        await box_codes.decorate_packs(db, [r for rows in boxes_by_line.values() for r in rows])

    out = []
    for indent in indents:
        lines = []
        for item in sorted(indent.items, key=lambda i: i.line_no or 0):
            approved = owed_quantity(item)
            received = _d(item.received_quantity)
            issued = issued_by_line.get(item.id, ZERO)
            dispatched = dispatched_by_line.get(item.id, ZERO)
            on_order = on_order_by_line.get(item.id, ZERO)
            line_serials = serials_by_indent_item.get((indent.id, item.item_id), [])
            line_boxes = boxes_by_line.get(item.id, [])
            if line_boxes:
                line_serials = []
            lines.append({
                "indent_item_id": item.id,
                "item_id": item.item_id,
                "item_code": item.item_code,
                "item_name": item.item_name,
                "uom_code": item.uom_code,
                # What the indent asked for — a brand / variant / model, or Any.
                **combinations.carry(item),
                # And what was actually issued, per brand (2026-10-26).
                "issued_combinations": issued_combos.get(item.id, []),
                # Issued in boxes: the box codes, each with what it carried.
                "box_codes": line_boxes,
                "approved_quantity": float(approved),
                "issued_quantity": float(issued),
                "dispatched_quantity": float(dispatched),
                "received_quantity": float(received),
                "is_serial_tracked": bool(getattr(
                    item_rows.get(item.item_id), "is_serial_tracked", False)),
                # Served, never inferred in a screen (same rule as the issue picker):
                # a serial, an IMEI, an asset tag and a lot code are fifteen
                # characters of upper case apiece, and only the item says which one
                # the labels below are.
                "tracking_type": _tracking_type(
                    item_rows.get(item.item_id),
                    has_units=bool(line_serials),
                ) if item_rows.get(item.item_id) is not None else TrackingType.NONE.value,
                "serial_numbers": line_serials,
                # Served, not inferred: the screen cannot tell a line being bought in
                # from one waiting on a shelf, and guessing it from the indent status
                # is exactly what got a procurement line labelled "on the way".
                "on_order_quantity": float(on_order),
                "package_quantities": packages_by_line.get(item.id, []),
                # The packs it was sent in, merged over its issue lines (2026-10-22).
                **(wh_packing.merge_breakdowns(packs_by_indent_line.get(item.id, []),
                                               item.uom_code) or {}),
                "pending_with": _pending_with(approved, issued, dispatched, received,
                                              indent.status, on_order),
            })
        out.append({
            "indent_id": indent.id,
            "indent_no": indent.indent_no,
            "indent_type": indent.indent_type,
            "indent_date": indent.indent_date,
            "required_date": indent.required_date,
            "status": indent.status,
            "priority": indent.priority,
            "project_name": indent.project_name,
            # Nothing has reached the requester yet, so there is nothing to confirm. The
            # row still shows, because "where is my stuff" is the other half of the job.
            "can_acknowledge": any(line["dispatched_quantity"] > line["received_quantity"]
                                   for line in lines),
            "lines": lines,
            # "Where is it and how do I follow it" — the courier docket and the
            # tracking link, on the same row as the confirm button. Without this the
            # requester was told a consignment had left and given no way to chase it.
            "shipments": shipments.get(indent.id, []),
        })
    return out


async def _shipments_by_indent(db: AsyncSession,
                               indent_ids: list[int]) -> dict[int, list[dict]]:
    """The transport legs carrying each of these indents, newest first.

    Read from `lgs_transport_requests` directly: logistics owns the leg and sits before
    this module in the import chain (rule 5), so reading it here is the allowed
    direction — and it keeps the requester's screen to one round trip.

    Matched on `indent_id` OR on the consignment the leg is carrying, because a leg
    raised against a consolidated consignment names the dispatch and not always an
    indent, and a requester whose parcel travelled in somebody else's carton still has
    to be able to track it.
    """
    from app.modules.logistics.models import TransportRequest

    if not indent_ids:
        return {}

    dispatch_rows = (await db.execute(
        select(m.Dispatch.id, m.MaterialIssue.indent_id)
        .join(m.MaterialIssue, _carries_issue(m.MaterialIssue.id))
        .where(m.MaterialIssue.indent_id.in_(indent_ids),
               m.Dispatch.status != DispatchStatus.CANCELLED.value)
    )).all()
    # A set per consignment: a grouped one carries issues for several indents, and the
    # leg moving it is every one of those requesters' parcel.
    indents_of_dispatch: dict[int, set[int]] = defaultdict(set)
    for dispatch_id, row_indent_id in dispatch_rows:
        if row_indent_id:
            indents_of_dispatch[dispatch_id].add(row_indent_id)

    legs = (await db.execute(
        select(TransportRequest)
        .where(or_(TransportRequest.indent_id.in_(indent_ids),
                   TransportRequest.dispatch_id.in_(list(indents_of_dispatch) or [0])))
        .order_by(TransportRequest.id.desc())
    )).scalars().all()

    by_indent: dict[int, list[dict]] = {}
    for leg in legs:
        targets = ({leg.indent_id} if leg.indent_id
                   else indents_of_dispatch.get(leg.dispatch_id, set()))
        for indent_id in targets:
            if indent_id not in indent_ids:
                continue
            by_indent.setdefault(indent_id, []).append(_shipment_row(leg))
    return by_indent


def _shipment_row(leg) -> dict:
    """One transport leg as the requester's delivery screen shows it."""
    return {
        "dispatch_id": leg.dispatch_id,
        "tr_id": leg.id,
        "tr_no": leg.tr_no,
        "mode": leg.mode,
        "status": leg.status,
        "carrier_name": leg.carrier_name,
        "vehicle_number": leg.vehicle_number,
        "driver_name": leg.driver_name,
        "driver_phone": leg.driver_phone,
        # The handle the field is given. A courier books on a docket, a truck on
        # an LR; the screen shows whichever one exists.
        "lr_no": leg.lr_no,
        "docket_no": leg.docket_no,
        "tracking_url": leg.tracking_url,
        "expected_delivery": leg.expected_delivery,
        "dispatched_at": leg.dispatched_at,
        "delivered_at": leg.delivered_at,
        "acknowledged_at": leg.acknowledged_at,
    }


async def acknowledgements_for_requester(db: AsyncSession, user, *, search: str | None = None,
                                         status: str | None = None,
                                         only_actionable: bool = False,
                                         indent_types: list[str] | None = None) -> list[dict]:
    """Every indent this person raised that has reached the delivery stage.

    Served from the warehouse module because the evidence — what was issued, what was
    dispatched — lives in `out_issues` and `out_dispatches`. Indents may not import this
    module (rule 5), so the join happens on this side of the line and indents keeps
    ownership of the acknowledgement itself.

    CLOSED is included alongside the still-receiving statuses. Confirming the last line
    of an indent sets it CLOSED (`indents._fulfilment_status`), so listing only the
    receivable ones made a delivery vanish from this screen at the exact moment the
    requester finished with it — no record of what they had confirmed, and no way back
    to the photo they attached. `can_acknowledge` is already false for them, so they
    read as history; "Ready to confirm" still narrows to the ones that need work.
    """
    from app.modules.indents.models import Indent, IndentItem
    from app.modules.indents.service import _RECEIVABLE_STATUSES

    visible_statuses = tuple(_RECEIVABLE_STATUSES | {IndentStatus.CLOSED.value})
    # The person AND the hat they are wearing. `requested_by_id` alone identifies the
    # employee, and an employee holds more than one position — a storekeeper who also
    # drives read both sets of indents here from either session, because this endpoint
    # is the one indent list that does not go through `indent_access_condition` (which
    # ANDs exactly this predicate for exactly this reason). Nothing in RBAC could fix
    # it: no scope rung was ever consulted.
    #
    # A NULL `position_id` stays visible. Those are indents raised before the column
    # was written, they belong to no hat, and dropping them would take a requester's
    # own delivery off the only screen that confirms it.
    from app.modules.indents.service import own_shelf_points, str_addressed_to

    position_id = getattr(user, "active_position_id", None)
    mine = Indent.requested_by_id == getattr(user, "id", 0)
    if position_id is not None:
        mine = and_(mine, or_(Indent.position_id == position_id,
                              Indent.position_id.is_(None)))
    # The raiser, or (for an STR) whoever holds the shelf it is bound for: the
    # receiving storekeeper sees an incoming transfer the moment it leaves the gate
    # (2026-10-29). Same predicate the sign-off checks (`indents._receives_str`).
    stmt = (
        select(Indent)
        .options(selectinload(Indent.items))
        .where(or_(mine, str_addressed_to(await own_shelf_points(db, user))),
               Indent.status.in_(visible_statuses),
               # Only what logistics has taken out of the gate. An indent whose stock
               # is merely set aside, still being bought or issued but not yet on a
               # consignment has nothing for the requester to acknowledge.
               select(m.MaterialIssue.id)
               .join(m.Dispatch, _carries_issue(m.MaterialIssue.id))
               .where(m.MaterialIssue.indent_id == Indent.id,
                      m.MaterialIssue.is_stock_posted.is_(True),
                      m.Dispatch.status.in_(_ON_THE_ROAD))
               .correlate(Indent).exists())
    )
    if status:
        stmt = stmt.where(Indent.status == status)
    # Reached through `stock.transfer.receive` alone: stock transfer requests only.
    if via_scoped_grant(db, INDENT_VIEW):
        indent_types = [_STR_INDENT_TYPE]
    # Indents > Acknowledgements asks for REGULAR/MONTHLY, Stock Transfer for STR.
    if indent_types:
        stmt = stmt.where(Indent.indent_type.in_(indent_types))
    if search:
        like = f"%{search.strip()}%"
        # Item text as well as the indent number: people look for "the masks", not for
        # a document number they never memorised.
        stmt = stmt.where(or_(
            Indent.indent_no.ilike(like),
            Indent.project_name.ilike(like),
            select(IndentItem.id).where(
                IndentItem.indent_id == Indent.id,
                or_(IndentItem.item_code.ilike(like), IndentItem.item_name.ilike(like)),
            ).exists(),
        ))
    indents = list((await db.execute(stmt.order_by(Indent.id.desc()))).scalars().all())

    rows = await _delivery_rows(db, indents)
    # The route each STR travels, off the orders serving it (2026-10-29): Stock
    # Transfer > Acknowledgements names the STO and "source -> destination" per card.
    str_ids = [i.id for i in indents if i.indent_type == _STR_INDENT_TYPE]
    if str_ids:
        from app.modules.inventory.models import StockTransferOrder
        routes: dict[int, list] = defaultdict(list)
        for order in (await db.execute(
            select(StockTransferOrder.str_id, StockTransferOrder.sto_no,
                   StockTransferOrder.from_warehouse_name,
                   StockTransferOrder.to_warehouse_name)
            .where(StockTransferOrder.str_id.in_(str_ids))
            .order_by(StockTransferOrder.id)
        )).all():
            routes[order.str_id].append(order)
        for row in rows:
            orders = routes.get(row["indent_id"], [])
            row["sto_nos"] = [o.sto_no for o in orders]
            row["from_warehouse_names"] = list(dict.fromkeys(
                o.from_warehouse_name for o in orders if o.from_warehouse_name))
            row["to_warehouse_name"] = next(
                (o.to_warehouse_name for o in orders if o.to_warehouse_name), None)
    if only_actionable:
        rows = [row for row in rows if row["can_acknowledge"]]
    return rows


async def indent_fulfilment(db: AsyncSession, indent_id: int) -> list[dict]:
    """The delivery half of an indent's journey, as stepper stages.

    The approval journey stops at "Ready for Allocation" — everything that physically
    happens to the goods after that lived only in the warehouse module and never showed
    on the indent. These are the missing steps.
    """
    from app.modules.indents.models import Indent

    indent = (await db.execute(
        select(Indent).options(selectinload(Indent.items)).where(Indent.id == indent_id)
    )).scalar_one_or_none()
    if indent is None:
        raise NotFoundError(f"Indent {indent_id} not found")

    rows = await _delivery_rows(db, [indent])
    if not rows:
        return []
    lines = rows[0]["lines"]

    owed = sum(line["approved_quantity"] for line in lines)
    issued = sum(line["issued_quantity"] for line in lines)
    dispatched = sum(line["dispatched_quantity"] for line in lines)
    received = sum(line["received_quantity"] for line in lines)

    # Delivered is a stronger claim than dispatched: the consignment has to have been
    # marked as arrived, not merely sent.
    delivered_docs = list((await db.execute(
        select(m.Dispatch.dispatch_no, m.Dispatch.status)
        .join(m.MaterialIssue, _carries_issue(m.MaterialIssue.id))
        .where(m.MaterialIssue.indent_id == indent_id,
               m.Dispatch.status.in_(_ON_THE_ROAD))
        .order_by(m.Dispatch.id.desc())
    )).all())
    delivered = any(row[1] in (DispatchStatus.DELIVERED.value,
                               DispatchStatus.ACKNOWLEDGED.value)
                    for row in delivered_docs)
    dispatch_label = ", ".join(row[0] for row in delivered_docs[:2]) or None

    def step(key, label, done, started, caption):
        # "current" means started but not finished — the stage somebody is waiting on.
        return {"key": key, "label": label, "caption": caption,
                "state": "completed" if done else "current" if started else "pending"}

    def part(moved: float) -> str:
        return f"{moved:g} of {owed:g}"

    return [
        step("allocated", "Stock allocated",
             indent.status != IndentStatus.AWAITING_ALLOCATION.value,
             True,
             indent.status.replace("_", " ").title()),
        step("issued", "Issued from store", issued >= owed and owed > 0, issued > 0,
             part(issued) if issued else "Not yet issued"),
        step("dispatched", "Dispatched", dispatched >= owed and owed > 0, dispatched > 0,
             dispatch_label or (part(dispatched) if dispatched else "Not yet sent")),
        step("delivered", "Delivered", delivered, dispatched > 0,
             "Arrived" if delivered else "In transit" if dispatched else "Not yet sent"),
        step("received", "Confirmed by requester",
             indent.status == IndentStatus.CLOSED.value, received > 0,
             part(received) if received else "Awaiting confirmation"),
    ]


# ---------------------------------------------------------------------------
# Dashboard and reports
# ---------------------------------------------------------------------------

async def dashboard(db: AsyncSession, warehouse_id: int | None = None, user=None) -> dict:
    """Queue depths in one call.

    The screen this feeds used to fire eight list requests and count the rows it got
    back, which meant every number was the size of the first page rather than the size
    of the queue.

    Every count is bounded by the warehouses this login may see — the same set
    `list_receipts`, `list_stock` and the rest of the module already use. Without it
    these tiles counted the whole network: "At gate 2" for a storekeeper with exactly
    one gate entry of their own, and no way to reach the other one from any screen.
    A tile has to agree with the list it links to.
    """
    from app.modules.inventory.models import Stock

    allowed = await warehouse_ids_for_user(db, user)

    def scoped(stmt, column):
        if warehouse_id:
            return stmt.where(column == warehouse_id)
        # None means unrestricted (admin, stock.view.all). An empty set means this
        # login reaches no warehouse at all, and every queue is genuinely zero.
        if allowed is not None:
            return stmt.where(column.in_(allowed) if allowed else false())
        return stmt

    async def count(model, column, *conditions) -> int:
        stmt = select(func.count()).select_from(model).where(*conditions)
        return int(await db.scalar(scoped(stmt, column)) or 0)

    pending_gate = await count(
        m.Receipt, m.Receipt.warehouse_id,
        m.Receipt.receipt_type == ReceiptType.GATE_ENTRY.value,
        m.Receipt.status == ReceiptStatus.GATE_ENTRY.value)
    pending_grn = await count(
        m.Receipt, m.Receipt.warehouse_id,
        m.Receipt.receipt_type == ReceiptType.PURCHASE.value,
        m.Receipt.status.in_([ReceiptStatus.DRAFT.value, ReceiptStatus.PENDING_QC.value]))
    pending_qc = await count(
        m.Inspection, m.Inspection.warehouse_id,
        m.Inspection.status.in_(_any_case(InspectionStatus.DRAFT.value,
                                          InspectionStatus.IN_PROGRESS.value)))
    pending_put = await count(
        m.PutawayTask, m.PutawayTask.warehouse_id,
        m.PutawayTask.status.in_([PutawayStatus.PENDING.value,
                                  PutawayStatus.IN_PROGRESS.value]),
        m.PutawayTask.is_active.is_(True))
    open_picks = await count(
        m.Picking, m.Picking.warehouse_id,
        m.Picking.status.in_([
            PickingStatus.DRAFT.value,
            PickingStatus.RELEASED.value,
            PickingStatus.IN_PROGRESS.value,
        ]))
    pending_issues = await count(
        m.MaterialIssue, m.MaterialIssue.warehouse_id,
        m.MaterialIssue.status.in_([IssueStatus.PENDING_APPROVAL.value, IssueStatus.APPROVED.value]))
    in_transit = await count(
        m.Dispatch, m.Dispatch.warehouse_id,
        m.Dispatch.status.in_([DispatchStatus.DISPATCHED.value,
                               DispatchStatus.IN_TRANSIT.value]))
    open_returns = await count(
        m.PurchaseReturn, m.PurchaseReturn.warehouse_id,
        m.PurchaseReturn.status.in_([ReturnStatus.DRAFT.value,
                                     ReturnStatus.PENDING_APPROVAL.value,
                                     ReturnStatus.APPROVED.value]))

    # The same costed value Inventory > Overview and the stock balance tiles report:
    # an uncosted row falls back to the item's last known price rather than counting
    # as worthless. Summing total_qty * valuation_rate here made this tile disagree
    # with Overview on the very same warehouse. The join is OUTER so a balance row
    # whose item has gone still contributes its qty at zero rather than vanishing.
    from app.shared.models.master import Item as _Item
    from app.modules.inventory.service import costed_value_sum

    if hasattr(Stock, "valuation_rate"):
        value_stmt = (
            select(costed_value_sum(Stock.total_qty, Stock.valuation_rate,
                                    _Item.purchase_price))
            .select_from(Stock)
            .outerjoin(_Item, _Item.id == Stock.item_id)
        )
    else:
        value_stmt = select(func.coalesce(func.sum(Stock.total_qty), 0))
    stock_value = _d(await db.scalar(scoped(value_stmt, Stock.warehouse_id)))

    # Utilisation is bins in use over active bins: capacity per item is not modelled,
    # so "how many bins are doing something" is the honest measure to show.
    bin_total = int(await db.scalar(
        scoped(select(func.count()).select_from(Bin).where(Bin.is_active.is_(True)),
               Bin.warehouse_id)) or 0)
    bin_used = int(await db.scalar(
        scoped(select(func.count(func.distinct(Stock.bin_id)))
               .where(Stock.bin_id != m.NO_BIN, Stock.total_qty > 0), Stock.warehouse_id)) or 0)
    utilisation = Decimal(round(bin_used * 100 / bin_total, 2)) if bin_total else ZERO

    # Both take the same bound as the tiles above: the activity list and the inward
    # chart sit on the same screen and must describe the same warehouses.
    recent = await _recent_activity(db, warehouse_id, allowed=allowed)
    trend = await _inward_trend(db, warehouse_id, allowed=allowed)

    return {
        "pending_gate_entries": pending_gate,
        "pending_grn": pending_grn,
        "pending_inspections": pending_qc,
        "pending_putaways": pending_put,
        "open_picklists": open_picks,
        "pending_issues": pending_issues,
        "in_transit_dispatches": in_transit,
        "open_returns": open_returns,
        "stock_value": stock_value,
        "bin_utilisation_percent": utilisation,
        "recent": recent,
        "inward_trend": trend,
    }


async def _recent_activity(db: AsyncSession, warehouse_id: int | None, limit: int = 10,
                           *, allowed: set[int] | None = None) -> list[dict]:
    """The last few documents across the whole chain, newest first.

    `allowed` is the caller's warehouse set (None = unrestricted). Without it this
    listed the newest receipts, issues and dispatches in the company on a screen the
    reader could not open a single one of them from.
    """
    out: list[dict] = []

    async def collect(model, no_column, doc_type: str) -> None:
        stmt = select(model).order_by(model.id.desc()).limit(limit)
        if hasattr(model, "warehouse_id"):
            if warehouse_id:
                stmt = stmt.where(model.warehouse_id == warehouse_id)
            elif allowed is not None:
                stmt = stmt.where(
                    model.warehouse_id.in_(allowed) if allowed else false())
        for row in (await db.execute(stmt)).scalars().all():
            out.append({
                "id": row.id, "doc_no": getattr(row, no_column),
                "doc_type": doc_type, "status": row.status,
                "created_at": getattr(row, "created_at", None),
            })

    await collect(m.Receipt, "grn_no", "RECEIPT")
    await collect(m.MaterialIssue, "issue_no", "ISSUE")
    await collect(m.Dispatch, "dispatch_no", "DISPATCH")

    def _sort_key(row: dict) -> datetime:
        """Sort on a single, comparable notion of "when".

        MySQL DATETIME columns come back naive, but rows written in the same session
        that set them from utcnow() are still tz-aware in the identity map. Mixing the
        two in one sort raises TypeError and takes the whole dashboard down with it,
        so both are flattened to naive UTC here rather than trusted to match.
        """
        value = row["created_at"]
        if value is None:
            return datetime.min
        return value.replace(tzinfo=None) if value.tzinfo else value

    out.sort(key=_sort_key, reverse=True)
    return out[:limit]


async def _inward_trend(db: AsyncSession, warehouse_id: int | None, days: int = 14,
                        *, allowed: set[int] | None = None) -> list[dict]:
    since = ist_today() - timedelta(days=days)
    stmt = (select(m.Receipt.grn_date,
                   func.coalesce(func.sum(m.Receipt.total_received_qty), 0),
                   func.coalesce(func.sum(m.Receipt.total_accepted_qty), 0),
                   func.coalesce(func.sum(m.Receipt.total_rejected_qty), 0))
            .where(m.Receipt.grn_date >= since,
                   m.Receipt.status != ReceiptStatus.CANCELLED.value)
            .group_by(m.Receipt.grn_date).order_by(m.Receipt.grn_date))
    if warehouse_id:
        stmt = stmt.where(m.Receipt.warehouse_id == warehouse_id)
    elif allowed is not None:
        stmt = stmt.where(
            m.Receipt.warehouse_id.in_(allowed) if allowed else false())

    return [{"date": str(row[0]), "received": float(_d(row[1])),
             "accepted": float(_d(row[2])), "rejected": float(_d(row[3]))}
            for row in (await db.execute(stmt)).all()]


def _col(key: str, header: str, numeric: bool = False) -> dict:
    return {"key": key, "header": header, "numeric": numeric}


async def run_report(db: AsyncSession, key: str, *, warehouse_id: int | None = None,
                     date_from: date | None = None, date_to: date | None = None) -> dict:
    """Reports carry their own columns, so adding one is a backend change alone.

    The screens this replaced hardcoded seven column layouts in the frontend, and two
    of them still had headings for columns the query had stopped returning.
    """
    if key == "inward-register":
        stmt = select(m.Receipt).where(m.Receipt.status != ReceiptStatus.CANCELLED.value)
        if warehouse_id:
            stmt = stmt.where(m.Receipt.warehouse_id == warehouse_id)
        if date_from:
            stmt = stmt.where(m.Receipt.grn_date >= date_from)
        if date_to:
            stmt = stmt.where(m.Receipt.grn_date <= date_to)
        rows = (await db.execute(stmt.order_by(m.Receipt.grn_date.desc()))).scalars().all()
        return {
            "columns": [_col("grn_no", "GRN"), _col("grn_date", "Date"),
                        _col("vendor_name", "Vendor"), _col("po_no", "PO"),
                        _col("total_received_qty", "Received", True),
                        _col("total_accepted_qty", "Accepted", True),
                        _col("total_rejected_qty", "Rejected", True),
                        _col("status", "Status")],
            "rows": [{"grn_no": r.grn_no, "grn_date": str(r.grn_date),
                      "vendor_name": r.vendor_name, "po_no": r.po_no,
                      "total_received_qty": float(_d(r.total_received_qty)),
                      "total_accepted_qty": float(_d(r.total_accepted_qty)),
                      "total_rejected_qty": float(_d(r.total_rejected_qty)),
                      "status": r.status} for r in rows],
            "total": len(rows),
        }

    if key == "qc-summary":
        stmt = select(m.Inspection)
        if warehouse_id:
            stmt = stmt.where(m.Inspection.warehouse_id == warehouse_id)
        if date_from:
            stmt = stmt.where(m.Inspection.inspection_date >= date_from)
        if date_to:
            stmt = stmt.where(m.Inspection.inspection_date <= date_to)
        rows = (await db.execute(stmt.order_by(m.Inspection.id.desc()))).scalars().all()
        return {
            "columns": [_col("inspection_no", "Inspection"), _col("inspection_date", "Date"),
                        _col("grn_no", "GRN"), _col("vendor_name", "Vendor"),
                        _col("total_items", "Lines", True), _col("passed_items", "Passed", True),
                        _col("failed_items", "Failed", True), _col("status", "Status")],
            "rows": [{"inspection_no": r.inspection_no,
                      "inspection_date": str(r.inspection_date), "grn_no": r.grn_no,
                      "vendor_name": r.vendor_name, "total_items": r.total_items,
                      "passed_items": r.passed_items, "failed_items": r.failed_items,
                      "status": r.status} for r in rows],
            "total": len(rows),
        }

    if key == "putaway-ageing":
        stmt = select(m.PutawayTask).where(
            m.PutawayTask.is_active.is_(True),
            m.PutawayTask.status.in_([PutawayStatus.PENDING.value,
                                      PutawayStatus.IN_PROGRESS.value]))
        if warehouse_id:
            stmt = stmt.where(m.PutawayTask.warehouse_id == warehouse_id)
        tasks = (await db.execute(stmt.order_by(m.PutawayTask.created_at))).scalars().all()
        rows = []
        for task in tasks:
            decorated = await _decorate_putaway(db, task)
            created = decorated["created_at"]
            age = (utcnow() - created).days if created else 0
            rows.append({"putaway_no": decorated["putaway_no"], "grn_no": decorated["grn_no"],
                         "item_code": decorated["item_code"], "item_name": decorated["item_name"],
                         "qty": float(_d(decorated["qty"])), "age_days": age,
                         "status": decorated["status"]})
        return {
            "columns": [_col("putaway_no", "Task"), _col("grn_no", "GRN"),
                        _col("item_code", "Item"), _col("item_name", "Description"),
                        _col("qty", "Quantity", True), _col("age_days", "Age (days)", True),
                        _col("status", "Status")],
            "rows": rows, "total": len(rows),
        }

    if key == "issue-register":
        stmt = select(m.MaterialIssue)
        if warehouse_id:
            stmt = stmt.where(m.MaterialIssue.warehouse_id == warehouse_id)
        if date_from:
            stmt = stmt.where(m.MaterialIssue.issue_date >= date_from)
        if date_to:
            stmt = stmt.where(m.MaterialIssue.issue_date <= date_to)
        rows = (await db.execute(stmt.order_by(m.MaterialIssue.id.desc()))).scalars().all()
        return {
            "columns": [_col("issue_no", "Issue"), _col("issue_date", "Date"),
                        _col("issued_to_name", "Issued to"),
                        _col("department_name", "Department"),
                        _col("indent_no", "Indent"), _col("total_qty", "Quantity", True),
                        _col("total_value", "Value", True), _col("status", "Status")],
            "rows": [{"issue_no": r.issue_no, "issue_date": str(r.issue_date),
                      "issued_to_name": r.issued_to_name, "department_name": r.department_name,
                      "indent_no": r.indent_no, "total_qty": float(_d(r.total_qty)),
                      "total_value": float(_d(r.total_value)), "status": r.status}
                     for r in rows],
            "total": len(rows),
        }

    if key == "dispatch-register":
        stmt = select(m.Dispatch)
        if warehouse_id:
            stmt = stmt.where(m.Dispatch.warehouse_id == warehouse_id)
        if date_from:
            stmt = stmt.where(m.Dispatch.dispatch_date >= date_from)
        if date_to:
            stmt = stmt.where(m.Dispatch.dispatch_date <= date_to)
        rows = (await db.execute(stmt.order_by(m.Dispatch.id.desc()))).scalars().all()
        return {
            "columns": [_col("dispatch_no", "Dispatch"), _col("dispatch_date", "Date"),
                        _col("destination", "To"), _col("vehicle_number", "Vehicle"),
                        _col("total_packages", "Packages", True),
                        _col("total_qty", "Quantity", True),
                        _col("expected_delivery", "Expected"), _col("status", "Status")],
            "rows": [{"dispatch_no": r.dispatch_no, "dispatch_date": str(r.dispatch_date),
                      "destination": r.to_warehouse_name or r.customer_name or r.vendor_name,
                      "vehicle_number": r.vehicle_number,
                      "total_packages": r.total_packages,
                      "total_qty": float(_d(r.total_qty)),
                      "expected_delivery": str(r.expected_delivery) if r.expected_delivery else None,
                      "status": r.status} for r in rows],
            "total": len(rows),
        }

    if key == "bin-utilisation":
        from app.modules.inventory.models import Stock
        # Only real bins hold stock, so only real bins have a utilisation. A lane or a
        # rack appearing at 0% would read as an empty bin rather than as scaffolding.
        stmt = select(Bin).where(
            Bin.is_active.is_(True),
            Bin.bin_type.in_(await storage_types.pickable_codes(db)))
        if warehouse_id:
            stmt = stmt.where(Bin.warehouse_id == warehouse_id)
        bins = (await db.execute(stmt.order_by(Bin.code))).scalars().all()

        # Ancestry for the Path column. One extra query for the whole tree beats walking
        # up from each bin, and the path is derived rather than stored so it cannot rot.
        ancestry = {
            r.id: (r.code, r.parent_id)
            for r in (await db.execute(select(Bin))).scalars().all()
        }

        def full_path(bin_id: int) -> str:
            parts, seen = [], set()
            current = bin_id
            while current in ancestry and current not in seen:
                seen.add(current)                 # a cycle in the data must not hang us
                code, parent = ancestry[current]
                parts.append(code)
                current = parent
            return "/".join(reversed(parts))

        # Volume occupancy for the whole set in two queries — the same pattern
        # `bin_occupancy_map` uses for the putaway chips.
        room = await capacity.bin_occupancy_map(db, list(bins))

        rows = []
        for b in bins:
            held = _d(await db.scalar(
                select(func.coalesce(func.sum(Stock.total_qty), 0)).where(Stock.bin_id == b.id)))
            cap_qty = _d(b.capacity_qty)
            occ = room.get(b.id, {})
            cap_vol = occ.get("capacity_volume")    # Decimal | None
            occ_vol = occ.get("occupied_volume") or _d(0)
            free_vol = occ.get("free_volume")       # Decimal | None
            vol_pct = occ.get("utilisation_pct")    # float | None
            vol_status = occ.get("status", capacity.STATUS_NO_CAPACITY)
            rows.append({
                "code": b.code,
                "name": b.name,
                "path": full_path(b.id),
                # --- quantity dimension (existing, kept for backward compat) ---
                "capacity_qty": float(cap_qty),
                "occupied_qty": float(held),
                "utilisation": float(round(held * 100 / cap_qty, 2)) if cap_qty else 0.0,
                # --- volume dimension (new) ---
                "capacity_volume": float(cap_vol) if cap_vol is not None else None,
                "occupied_volume": float(occ_vol),
                "free_volume": float(free_vol) if free_vol is not None else None,
                "volume_utilisation_pct": float(round(vol_pct, 2)) if vol_pct is not None else None,
                "volume_status": vol_status,
                # --- the discrete and payload gates ---
                # A bay at its stated pallet limit is full whatever its cube says, so a
                # utilisation report that only ranks on volume points a slotting review
                # at the wrong locations. `volume_status` is already the WORST of the
                # three verdicts (see `bin_occupancy_map`); these are the figures
                # behind it.
                "capacity_units": occ.get("capacity_units"),
                "occupied_units": float(occ.get("occupied_units") or 0),
                "capacity_weight_kg": (
                    float(occ["capacity_weight_kg"])
                    if occ.get("capacity_weight_kg") is not None else None),
                "occupied_weight_kg": float(occ.get("occupied_weight_kg") or 0),
                "is_pickable": "Yes" if b.is_pickable else "No",
            })
        return {
            "columns": [
                _col("code", "Bin"),
                _col("name", "Name"),
                _col("path", "Path"),
                # qty-based columns
                _col("capacity_qty", "Cap. Qty", True),
                _col("occupied_qty", "Occupied Qty", True),
                _col("utilisation", "Qty Util %", True),
                # volume-based columns
                _col("capacity_volume", "Cap. Vol (m³)", True),
                _col("occupied_volume", "Occupied Vol (m³)", True),
                _col("free_volume", "Free Vol (m³)", True),
                _col("volume_utilisation_pct", "Vol Util %", True),
                _col("volume_status", "Status"),
                # handling-unit and payload columns
                _col("occupied_units", "Units", True),
                _col("capacity_units", "Max Units", True),
                _col("occupied_weight_kg", "Load (kg)", True),
                _col("capacity_weight_kg", "Max Load (kg)", True),
                _col("is_pickable", "Pickable"),
            ],
            "rows": rows,
            "total": len(rows),
        }

    if key == "batch-expiry":
        stmt = select(m.Batch).where(m.Batch.expiry_date.isnot(None))
        if date_to:
            stmt = stmt.where(m.Batch.expiry_date <= date_to)
        rows = (await db.execute(stmt.order_by(m.Batch.expiry_date))).scalars().all()
        today = ist_today()
        return {
            "columns": [_col("batch_no", "Batch"), _col("item_code", "Item"),
                        _col("item_name", "Description"), _col("vendor_name", "Vendor"),
                        _col("expiry_date", "Expires"), _col("days_left", "Days left", True),
                        _col("initial_qty", "Received", True), _col("status", "Status")],
            "rows": [{"batch_no": r.batch_no, "item_code": r.item_code,
                      "item_name": r.item_name, "vendor_name": r.vendor_name,
                      "expiry_date": str(r.expiry_date),
                      "days_left": (r.expiry_date - today).days,
                      "initial_qty": float(_d(r.initial_qty)), "status": r.status}
                     for r in rows],
            "total": len(rows),
        }

    raise NotFoundError(f"No report called {key}")


# ---------------------------------------------------------------------------
# Options (lookups the forms need)
# ---------------------------------------------------------------------------

LOOKUP_LIMIT = 200
# One grouped consignment is one lorry-load of issues, not a batch job. Well past any
# real delivery, and small enough that a save stays one short request.
MAX_ISSUES_PER_CONSIGNMENT = 50
# How far back the recommendation list looks for issues waiting to be sent.
RECOMMENDATION_SCAN_LIMIT = 300


async def item_options(db: AsyncSession, search: str | None = None, *,
                       warehouse_id: int | None = None,
                       in_stock: bool = False,
                       indent_id: int | None = None,
                       project_id: int | None = None,
                       user=None) -> list[dict]:
    """Items for a picker — and, when a point is named, what that point actually holds.

    `project_id`: lots held for that project count as drawable, as on stock-sources.

    The plain catalogue is right for a GRN (goods arrive for items the shelf has never
    seen) and wrong for an ISSUE. A material issue raised without an indent asked the
    storekeeper to choose from the whole item master, several thousand rows, of which
    a given point stocks a few hundred; he picked one, and the batch and location
    pickers below then dead-ended on "nothing on the shelf" with nothing said about
    why. The item was never issuable — that fact simply arrived two decisions too late.

    So `warehouse_id` decorates every row with what is there — `on_hand`, and how many
    batches and locations it is spread over — and `in_stock` narrows the list to the
    items a picker can actually be sent for. Both are opt-in: every existing caller
    (GRN, put-away, inspection) passes neither and gets exactly the list it had.

    `on_hand` is DRAWABLE, not `available_qty`: an approved allocation reserves the
    stock it is about to issue, so a document issuing what was reserved for it sees its
    own rows at zero free. Same rule as `issue_stock_sources`, applied a level up, so
    the item list and the batch list underneath it can never disagree about whether
    there is anything to take.
    """
    from app.modules.inventory.models import Reservation, Stock

    stmt = select(Item).where(Item.is_active.is_(True)) if hasattr(Item, "is_active") \
        else select(Item)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(Item.code.ilike(like), Item.name.ilike(like)))

    held: dict[int, dict] = {}
    if warehouse_id:
        # What this warehouse can give of each item, and how far it is spread. Read
        # once for the whole list rather than per row — `stk_balance` is one row per
        # (item, bin, batch) and a well-stocked point has thousands.
        if indent_id or project_id:
            mine = (
                select(Reservation.stock_id.label("stock_id"),
                       func.sum(Reservation.quantity).label("qty"))
                .where(_own_hold_clause(indent_id, project_id),
                       Reservation.status == ReservationStatus.ACTIVE.value)
                .group_by(Reservation.stock_id)
                .subquery()
            )
            own = func.coalesce(func.sum(mine.c.qty), 0)
        else:
            mine = None
            own = literal(0)

        counts = (
            select(Stock.item_id,
                   func.sum(Stock.available_qty).label("available_qty"),
                   own.label("own_reserved_qty"),
                   func.count(func.distinct(Stock.batch_id)).label("batches"),
                   func.count(func.distinct(Stock.bin_id)).label("locations"))
            .select_from(Stock)
        )
        if mine is not None:
            counts = counts.outerjoin(mine, mine.c.stock_id == Stock.id)
        counts = counts.where(Stock.warehouse_id == warehouse_id,
                              _stock_offerable(indent_id, project_id)).group_by(Stock.item_id)
        if user is not None:
            counts = counts.where(await scope_condition(
                db, user,
                warehouse_col=Stock.warehouse_id,
                warehouse_ids=await warehouse_ids_for_user(db, user),
            ))
        for item_id, available, own_qty, batches, locations in (
                await db.execute(counts)).all():
            drawable = _d(available) + _d(own_qty)
            if drawable <= ZERO:
                continue
            held[int(item_id)] = {
                "on_hand": drawable,
                # NO_BATCH / NO_BIN are 0, not a real id — bulk stock is one "batch"
                # and one "location" by this count, which is what it looks like on the
                # floor too.
                "batch_count": int(batches or 0),
                "location_count": int(locations or 0),
            }
        if in_stock:
            # Nothing here is nothing to offer. An empty `held` narrows to an empty
            # list rather than falling back to the catalogue, because a silent
            # widening is how the picker got misleading in the first place.
            stmt = stmt.where(Item.id.in_(held.keys() or {0}))

    rows = (await db.execute(stmt.order_by(Item.code).limit(LOOKUP_LIMIT))).scalars().all()
    # How many decimals each row's unit allows — the same rule `_apply_issue_lines`
    # enforces on save (SCM_0080). Served here so the issue form can stop a
    # fractional quantity being TYPED for a whole-unit item, rather than only
    # refusing it after the fact.
    decimals = await uom_rules.decimals_by_code(db, {r.uom_code for r in rows})
    return [{
        "id": r.id,
        "code": r.code,
        "name": r.name,
        "uom_code": r.uom_code,
        "qty_decimals": decimals.get(r.uom_code, uom_rules.MAX_DECIMALS),
        "is_batch_tracked": bool(r.is_batch_tracked),
        "is_serial_tracked": bool(r.is_serial_tracked),
        # The GRN form reads this to decide whether to show the IMEI column, the
        # same way it reads is_serial_tracked for serials.
        "is_imei_tracked": bool(r.is_imei_tracked),
        "has_expiry": bool(r.has_expiry),
        "is_asset": bool(r.is_asset),
        "requires_qi": bool(r.requires_qi),
        # `None` when no point was named — "nobody asked", which a screen must not
        # draw as "this point holds none".
        **(held.get(r.id, {"on_hand": ZERO, "batch_count": 0, "location_count": 0})
           if warehouse_id else {}),
    } for r in rows]


async def vendor_options(db: AsyncSession, search: str | None = None) -> list[dict]:
    stmt = select(Vendor)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(Vendor.code.ilike(like), Vendor.name.ilike(like)))
    rows = (await db.execute(stmt.order_by(Vendor.name).limit(LOOKUP_LIMIT))).scalars().all()
    return [{"id": r.id, "code": r.code, "name": r.name} for r in rows]


async def warehouse_options(db: AsyncSession, *, search: str | None = None, mine_only: bool = False,
                            all_points: bool = False, user=None) -> list[dict]:
    """Stocking points for a picker. Scoped to this login unless asked otherwise.

    Scoping is the DEFAULT, not an opt-in. It used to be the reverse — `mine_only`
    had to be passed — and every screen that forgot it (the dashboard filter, Material
    Inward, GRN, Put-away, Material Issues, QC) offered all 1,500 points in the
    company. A lab technician holding one LIP picked from the whole network, and a
    storekeeper inwarded a delivery into an unrelated demo MDP: the stock posted
    correctly and then sat somewhere his own screens are scoped away from, so every
    inventory page read empty while the goods were plainly in the building.

    `all_points=True` is the deliberate exception for a DESTINATION picker — you
    dispatch TO a point you do not hold, and a transfer needs the whole network. Only
    the "to warehouse" fields pass it.

    `mine_only` is kept as an alias for the old callers; it means the same thing the
    default now does.
    """
    stmt = select(Warehouse).where(Warehouse.is_active.is_(True))
    if search:
        from sqlalchemy import or_
        stmt = stmt.where(
            or_(Warehouse.code.ilike(f"%{search}%"), Warehouse.name.ilike(f"%{search}%"))
        )
    if not all_points:
        allowed = await warehouse_ids_for_user(db, user) if user is not None else None
        if allowed is not None:
            stmt = stmt.where(Warehouse.id.in_(allowed or {0}))
    rows = (await db.execute(stmt.order_by(Warehouse.code))).scalars().all()
    # `warehouse_type` rides along so a form can tell an MDP or LIP from a main store
    # without a second round trip — the GRN screen hides purchase-order and vendor
    # fields, and trims its receipt types, at the bottom of the chain.
    return [{"id": r.id, "code": r.code, "name": r.name,
             "is_bin_managed": r.is_bin_managed,
             "warehouse_type": r.warehouse_type} for r in rows]


def _own_hold_clause(indent_id: int | None, project_id: int | None = None,
                     issue_id: int | None = None):
    """Which `inv_reservations` rows a document may draw on as its own: its indent's
    reservation, the lots held for its project, and — for a direct issue being edited —
    the stock it reserved itself. Everybody else's stay hidden."""
    from app.modules.inventory.models import ProjectHold, Reservation

    clauses = []
    if issue_id:
        clauses.append(and_(Reservation.ref_type == InventoryRefType.ISSUE_HOLD.value,
                            Reservation.ref_id == issue_id))
    if indent_id:
        clauses.append(and_(Reservation.ref_type == InventoryRefType.RESERVATION.value,
                            Reservation.ref_id == indent_id))
    if project_id:
        clauses.append(and_(
            Reservation.ref_type == InventoryRefType.PROJECT_HOLD.value,
            Reservation.ref_id.in_(select(ProjectHold.id).where(
                ProjectHold.project_id == project_id,
                ProjectHold.status == ProjectHoldStatus.ACTIVE.value))))
    return or_(*clauses) if clauses else false()


def _stock_offerable(indent_id: int | None, project_id: int | None = None,
                     issue_id: int | None = None):
    """Stock a picker may still choose: what is free, plus what THIS indent is holding.

    FIXED 2026-08-21 — both option lists filtered on `available_qty > 0` alone, and an
    approved allocation RESERVES the stock it is about to issue. So a line that takes
    the whole balance erased its own batch and bin from its own dropdowns: WHI/2026-27/
    00047 line 2 held batch 22 / bin 4 correctly and drew two empty boxes, because the
    10 units on that balance were reserved by the very indent being issued. The sibling
    line only rendered because 5 units happened to be spare.

    Issuing exactly what is on hand is the normal case, not the edge one, so the
    document's own hold has to come back. Same shape as `_free_by_point`'s
    `exclude_allocation_id`: everyone else's reservations still hide the row.
    """
    from app.modules.inventory.models import Reservation, Stock

    free = Stock.available_qty > ZERO
    if not indent_id and not project_id and not issue_id:
        return free
    mine = Stock.id.in_(
        select(Reservation.stock_id).where(
            _own_hold_clause(indent_id, project_id, issue_id),
            Reservation.status == ReservationStatus.ACTIVE.value,
        )
    )
    if not indent_id:
        return or_(free, mine)
    # An indent's hold is a QUANTITY that floats between batches (2026-10-12): a row
    # carrying ANOTHER indent's hold can be traded for on save (`swap_holds`), so an
    # indent issue is offered it too.
    any_indent = Stock.id.in_(
        select(Reservation.stock_id).where(
            Reservation.ref_type == InventoryRefType.RESERVATION.value,
            Reservation.status == ReservationStatus.ACTIVE.value,
        )
    )
    return or_(free, mine, any_indent)


async def bin_options(db: AsyncSession, warehouse_id: int, search: str | None = None,
                      item_id: int | None = None, batch_id: int | None = None,
                      storage_type_id: str | None = None,
                      all_locations: bool = False,
                      exclude_bin_id: int | None = None,
                      indent_id: int | None = None,
                      user=None) -> list[dict]:
    """Somewhere in this warehouse to take stock from, or put it.

    Every row carries its WHOLE ancestry — `path`, `path_names`, `steps` — not just a
    bin code. `F1-A1-R1-B2` on its own tells a storekeeper nothing about which end of
    which floor he is being sent to, and the codes are near-identical by design; the
    picker has to say Ground Floor / Aisle 1 / Rack 1 / Bin 2 or it is asking him to
    memorise the warehouse.

    Structure — floors, lanes, racks, shelves — is offered too when `all_locations` is
    set, and ALWAYS when the query is narrowed to stock that is actually there: a
    location holding goods is a location they can be picked from, whatever rung of the
    tree it sits on. Stock lands outside a bin whenever a putaway is confirmed against
    a rung above one, which the floor is now allowed to do.

    Narrowed to the caller's own floors when they have any. `user` is optional so the
    internal callers that are not answering a request keep working, but every ROUTE
    passes it: this list is what a putaway, a movement and a material issue all pick
    their location from, and offering a floor the write gate would refuse is a form
    that cannot be saved. The picker and `floor_scope_ids` read the same set — the
    dropdown is the courtesy, the gate is the rule.
    """
    holding = bool(item_id or batch_id)
    # Same as `issue_stock_sources`: stock at bin 0 joins no location, so it would be
    # missing from every "where is it" answer below. See `unlocated.heal`.
    await unlocated.heal(db, warehouse_id, user)
    stmt = select(Bin).where(Bin.warehouse_id == warehouse_id, Bin.is_active.is_(True))
    if user is not None:
        allowed = await floor_scope_ids(db, user)
        if allowed is not None:
            # An empty set is a floor in-charge with no floor assigned. Offer nothing
            # rather than everything — the write gate refuses them either way, and a
            # full dropdown would only send them to a form that cannot be saved.
            stmt = stmt.where(Bin.id.in_(allowed) if allowed else false())
    if not all_locations and not holding:
        stmt = stmt.where(Bin.bin_type.in_(await storage_types.pickable_codes(db)))
    # A destination that is also the source is not a movement. Excluded here rather
    # than only in the form, so the offer and the rule the service enforces agree.
    if exclude_bin_id:
        stmt = stmt.where(Bin.id != exclude_bin_id)
    if storage_type_id:
        if storage_type_id.isdigit():
            type_id = int(storage_type_id)
            storage_type = await db.get(m.StorageType, type_id)
            clauses = [Bin.storage_type_id == type_id]
            # Legacy locations can have the correct denormalised code while their
            # newer master id is null. A selected master type must find both shapes.
            if storage_type is not None and storage_type.code:
                clauses.append(func.upper(Bin.bin_type) == storage_type.code.upper())
            stmt = stmt.where(or_(*clauses))
        else:
            stmt = stmt.where(func.upper(Bin.bin_type) == storage_type_id.upper())
    if item_id or batch_id:
        from app.modules.inventory.models import Stock
        stmt = stmt.join(Stock, Stock.bin_id == Bin.id).where(
            Stock.warehouse_id == warehouse_id,
            _stock_offerable(indent_id),
        )
        if item_id:
            stmt = stmt.where(Stock.item_id == item_id)
        if batch_id:
            stmt = stmt.where(Stock.batch_id == batch_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(Bin.code.ilike(like), Bin.name.ilike(like)))
    rows = (await db.execute(stmt.distinct().order_by(Bin.code).limit(LOOKUP_LIMIT))).scalars().all()
    index = await _location_index(db, warehouse_id)
    out = []
    for r in rows:
        node = index.get(r.id, {})
        parents = (node.get("steps") or [])[:-1]
        out.append({
            "id": r.id,
            "code": r.code,
            # What the dropdown reads out. The bin's own name first, then the walk to
            # it, so the label is "Bin 1 · Ground Floor / Aisle 1 / Rack 1" and a
            # storekeeper can find it without opening a second screen.
            "name": " · ".join(filter(None, [
                r.name or r.code,
                " / ".join(step["name"] for step in parents) or None,
            ])),
            "bin_type": r.bin_type,
            "is_pickable": r.is_pickable,
            "path": node.get("path") or r.code,
            "path_names": node.get("path_names") or (r.name or r.code),
            "steps": node.get("steps") or [],
        })
    return out


async def batch_options(
    db: AsyncSession,
    *,
    item_id: int,
    warehouse_id: int,
    bin_id: int | None = None,
    indent_id: int | None = None,
) -> list[dict]:
    from app.modules.inventory.models import Stock

    stmt = (
        select(m.Batch)
        .join(Stock, Stock.batch_id == m.Batch.id)
        .where(
            m.Batch.item_id == item_id,
            Stock.warehouse_id == warehouse_id,
            # See `_stock_offerable`: the document's own reservation must not hide the
            # batch it is issuing from.
            _stock_offerable(indent_id),
        )
        .distinct()
    )
    if bin_id:
        stmt = stmt.where(Stock.bin_id == bin_id)
    rows = (await db.execute(
        stmt.order_by(m.Batch.expiry_date.is_(None), m.Batch.expiry_date)
        .limit(LOOKUP_LIMIT)
    )).scalars().all()
    return [{"id": row.id, "code": row.batch_no, "name": row.batch_no} for row in rows]


async def po_options(db: AsyncSession, search: str | None = None, warehouse_id: int | None = None) -> list[dict]:
    # Three columns, not the whole row: see _po_number for why selecting the mapped
    # PurchaseOrder is a 1054 against the live schema.
    from app.modules.procurement.models import PurchaseOrder
    from app.shared.enums import POStatus
    stmt = select(PurchaseOrder.id, PurchaseOrder.po_no, PurchaseOrder.vendor_name)
    # Only orders the vendor has actually been told about. Listing every PO offered a
    # storekeeper drafts nobody has approved and orders already cancelled — and the
    # receipt would then post stock against a commitment that was never made. Mirrors
    # the GRN guard, which has always required an order to have been sent.
    stmt = stmt.where(PurchaseOrder.status.in_((
        POStatus.SENT_TO_VENDOR.value,
        POStatus.ACCEPTED_BY_SUPPLIER.value,
        POStatus.PARTIALLY_RECEIVED.value)))
    
    # Only orders that the supplier has explicitly accepted.
    from app.shared.enums import POVendorStatus
    from sqlalchemy import or_
    stmt = stmt.where(PurchaseOrder.vendor_status == POVendorStatus.ACCEPTED.value)

    # And only orders with something still to come.
    #
    # The status filter above is not enough on its own, for two reasons. An order
    # received before `_sync_po_receipt_status` learned to run on submit still reads
    # ACCEPTED_BY_SUPPLIER — BHS/104/2026-27/PO0013 does, with every one of its
    # nineteen lines on a receipt — and no migration is going to walk history. And a
    # DRAFT receipt claims goods without moving the order at all, which is right: a
    # draft is a claim, not a delivery.
    #
    # So this is derived, off the same rows `po_received_by_line` and
    # `_assert_po_fulfilment` read, and it holds the one property that matters: **the
    # dropdown offers exactly the orders the save would accept.** A picker that offers
    # what the server refuses is a picker nobody trusts twice.
    from app.modules.procurement.models import POItem
    taken = (
        select(m.ReceiptItem.po_item_id.label("po_item_id"),
               func.sum(m.ReceiptItem.received_qty).label("qty"))
        .join(m.Receipt, m.Receipt.id == m.ReceiptItem.receipt_id)
        .where(m.Receipt.status != ReceiptStatus.CANCELLED.value,
               m.ReceiptItem.po_item_id.is_not(None))
        .group_by(m.ReceiptItem.po_item_id)
        .subquery()
    )
    open_orders = (
        select(POItem.po_id)
        .outerjoin(taken, taken.c.po_item_id == POItem.id)
        .group_by(POItem.po_id)
        # Per LINE, then summed: an order over-received on one line and short on
        # another is still short, and netting the two would hide the line that is
        # actually still coming.
        .having(func.sum(func.greatest(
            POItem.quantity - func.coalesce(taken.c.qty, 0), 0)) > 0)
    )
    stmt = stmt.where(PurchaseOrder.id.in_(open_orders))

    # Narrow to the orders this warehouse could actually receive, when the warehouse
    # says which office or facility it belongs to. A warehouse that says neither is
    # not filtered at all — an empty dropdown is worse than a long one.
    if warehouse_id:
        from app.shared.models.warehouse import Warehouse
        wh = await db.get(Warehouse, warehouse_id)
        if wh is not None:
            conditions = []
            if wh.office_id:
                conditions.append(PurchaseOrder.office_id == wh.office_id)
            if wh.facility_id:
                conditions.append(PurchaseOrder.facility_id == wh.facility_id)
            conditions.append(PurchaseOrder.facility_id == warehouse_id)
            if conditions:
                stmt = stmt.where(or_(*conditions))

    if search:
        stmt = stmt.where(PurchaseOrder.po_no.ilike(f"%{search}%"))
    rows = (await db.execute(
        stmt.order_by(PurchaseOrder.id.desc()).limit(LOOKUP_LIMIT))).all()
    return [{"id": po_id, "code": po_no, "name": vendor_name or po_no}
            for po_id, po_no, vendor_name in rows]


async def receipt_options(
    db: AsyncSession,
    search: str | None = None,
    receipt_type: str | None = None,
    *,
    warehouse_id: int | None = None,
    for_putaway: bool = False,
    for_qc: bool = False,
    user=None,
) -> list[dict]:
    stmt = select(m.Receipt).where(m.Receipt.status != ReceiptStatus.CANCELLED.value)
    # A lookup is not exempt from scoping. Unscoped, this listed every GRN in the
    # company, so a storekeeper at one MDP was offered receipts from points they have
    # never stood in and cannot put anything away at.
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.Receipt.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.Receipt.created_by_id,
            project_col=m.Receipt.project_id,
        ))
    if warehouse_id:
        stmt = stmt.where(m.Receipt.warehouse_id == warehouse_id)
    if receipt_type:
        stmt = stmt.where(m.Receipt.receipt_type.in_(_receipt_types_for(receipt_type)))
    if for_putaway:
        # Only what a putaway could actually be raised against — see
        # `_putaway_block_reason`, which is the same set of rules stated once more as
        # SQL. A bulk point posts its stock at receipt and has no bins to put it in,
        # so offering its GRNs here promises a step that does not exist.
        settled = (
            select(m.PutawayTask.grn_item_id)
            .where(m.PutawayTask.status.in_(_SETTLED_PUTAWAY_STATUSES))
        )
        waiting = (
            select(m.ReceiptItem.receipt_id)
            .where(
                m.ReceiptItem.qc_status == QcStatus.PASSED.value,
                m.ReceiptItem.accepted_qty > 0,
                m.ReceiptItem.id.notin_(settled),
            )
        )
        stmt = (
            stmt.join(Warehouse, Warehouse.id == m.Receipt.warehouse_id)
            .where(
                Warehouse.is_bin_managed.is_(True),
                m.Receipt.is_stock_posted.is_(False),
                m.Receipt.id.in_(waiting),
            )
        )
    if for_qc:
        # Only the deliveries an inspection could still be raised against. Narrowed the
        # same way `for_putaway` is, and for the same reason: the picker listed every
        # receipt ever booked in, so an inspector chose a GRN whose QC had finished
        # months ago and typed a second inspection over it.
        #
        # The test is the LINE, not the receipt's status. `qc_status` is what QC itself
        # writes, so a line still at PENDING is the one statement of "this has not been
        # inspected" that cannot go stale — where `status == PENDING_QC` is a rung a
        # receipt passes through and leaves. On this database not one receipt is sitting
        # at PENDING_QC while thirty lines are still PENDING, so narrowing on the status
        # would have emptied the picker and taken the screen with it.
        #
        # Plus RECEIVED_RECEIPT_STATUSES, because QC comes after the goods are declared
        # received: a DRAFT receipt's lines read PENDING having never been inspected,
        # and offering one would have an inspector sign for a count nobody has submitted.
        pending = (
            select(m.ReceiptItem.receipt_id)
            .where(m.ReceiptItem.qc_status == QcStatus.PENDING.value)
        )
        stmt = stmt.where(
            m.Receipt.status.in_(RECEIVED_RECEIPT_STATUSES),
            m.Receipt.id.in_(pending),
        )
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.Receipt.grn_no.ilike(like),
            m.Receipt.gate_entry_no.ilike(like),
            m.Receipt.vendor_name.ilike(like),
        ))
    rows = (await db.execute(
        stmt.order_by(m.Receipt.id.desc()).limit(LOOKUP_LIMIT))).scalars().all()
    return [{
        "id": r.id,
        "code": (
            r.gate_entry_no
            if r.receipt_type == ReceiptType.GATE_ENTRY.value
            else r.grn_no
        ),
        # Who it came from, which is the thing that tells two GRNs apart. Falling back
        # to the number printed the number twice — "REC/.../00066 — REC/.../00066" —
        # on every receipt with no vendor behind it, which is every transfer and every
        # incoming consignment.
        "name": (r.vendor_name or r.transfer_no or r.po_no
                 or r.warehouse_name or r.grn_no),
    } for r in rows]


async def incoming_dispatch_options(
    db: AsyncSession,
    warehouse_id: int,
    search: str | None = None,
) -> list[dict]:
    """Consignments on their way to this point that nobody has inwarded yet.

    This is what an MDP or a LIP opens the inward screen for: not a purchase order,
    but the lorry the main store sent them.
    """
    inwarded = select(m.Receipt.transfer_id).where(
        m.Receipt.receipt_type == ReceiptType.DISPATCH.value,
        m.Receipt.status != ReceiptStatus.CANCELLED.value,
        m.Receipt.transfer_id.is_not(None),
    )
    stmt = select(m.Dispatch).where(
        m.Dispatch.to_warehouse_id == warehouse_id,
        m.Dispatch.status.in_(_INWARDABLE_DISPATCH_STATUSES),
        m.Dispatch.id.notin_(inwarded),
    )
    # A consignment that was acknowledged has already been credited to this point by
    # `acknowledge_dispatch`, so offering it here would only lead to a rejection.
    # A point that runs a receiving desk is the exception: acknowledgement there
    # credited nothing, so the acknowledged lorry is precisely what it came to inward.
    # The two halves of this `or_` are `_lands_on_internal_shelf` said in SQL — every
    # row here already matches on `to_warehouse_id`, so only the type is left to test,
    # and the two must never drift apart or a lorry is offered twice or not at all.
    if not await requires_inward(db, warehouse_id):
        stmt = stmt.where(or_(
            m.Dispatch.dispatch_type.in_(_LEAVES_THE_COMPANY),
            m.Dispatch.status != DispatchStatus.ACKNOWLEDGED.value,
        ))
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(
            m.Dispatch.dispatch_no.ilike(like),
            m.Dispatch.ref_no.ilike(like),
            m.Dispatch.warehouse_name.ilike(like),
            m.Dispatch.lr_no.ilike(like),
        ))
    rows = (await db.execute(
        stmt.order_by(m.Dispatch.id.desc()).limit(LOOKUP_LIMIT))).scalars().all()
    return [{
        "id": r.id,
        "code": r.dispatch_no,
        "name": " · ".join(filter(None, [r.warehouse_name, r.ref_no])) or r.dispatch_no,
    } for r in rows]


async def dispatch_receipt_source(
    db: AsyncSession, dispatch_id: int, warehouse_id: int,
) -> dict:
    """The consignment's lines, shaped for the inward form."""
    dispatch = await _dispatch_for_receipt(
        db,
        receipt_type=ReceiptType.DISPATCH,
        dispatch_id=dispatch_id,
        warehouse_id=warehouse_id,
    )
    wh = await _warehouse(db, warehouse_id)
    indent_id = next((l.indent_id for l in dispatch.items if l.indent_id), None)
    indent_no = next((l.indent_no for l in dispatch.items if l.indent_no), None)

    # The dispatch line only snapshots batch_no and has no expiry column at all, so
    # the storekeeper retyped both off the carton on every line. The dates live on
    # stk_batches; resolve the lines to their batch rows in two queries (a 40-line
    # consignment is not 40 round trips) and prefill what was actually sent.
    batch_ids = {l.batch_id for l in dispatch.items
                 if l.batch_id and l.batch_id != m.NO_BATCH}
    # A serialised line names units, not a batch — the serial row knows its batch.
    serials = [l.serial_no for l in dispatch.items if l.serial_no]
    serial_batch: dict[str, int] = {}
    if serials:
        for serial_no, batch_id in (await db.execute(
            select(m.SerialNumber.serial_number, m.SerialNumber.batch_id)
            .where(m.SerialNumber.serial_number.in_(serials))
        )).all():
            if batch_id and batch_id != m.NO_BATCH:
                serial_batch[serial_no] = batch_id
                batch_ids.add(batch_id)
    batches = {b.id: b for b in (await db.execute(
        select(m.Batch).where(m.Batch.id.in_(batch_ids))
    )).scalars().all()} if batch_ids else {}

    # The inward form only renders its serial and IMEI cells for a line that says it
    # is tracked, and a prefilled line said nothing — so the numbers the consignment
    # carries had nowhere to show and the storekeeper was asked for them again.
    tracked_item_ids = {line.item_id for line in dispatch.items}
    tracking = {
        row.id: row for row in (await db.execute(
            select(Item).where(Item.id.in_(tracked_item_ids))
        )).scalars().all()
    } if tracked_item_ids else {}

    items = _group_dispatch_lines(dispatch.items, serial_batch, batches, tracking)
    await _receipt_lines_packed(db, items, dispatch_id=dispatch.id)

    return {
        "dispatch_id": dispatch.id,
        "dispatch_no": dispatch.dispatch_no,
        "warehouse_id": wh.id,
        "warehouse_name": wh.name,
        "is_bin_managed": wh.is_bin_managed,
        "from_warehouse_id": dispatch.warehouse_id,
        "from_warehouse_name": dispatch.warehouse_name,
        "project_id": dispatch.project_id,
        "dispatch_date": dispatch.dispatch_date,
        "lr_no": dispatch.lr_no,
        "vehicle_number": dispatch.vehicle_number,
        "indent_id": indent_id,
        "indent_no": indent_no,
        "items": items,
    }


async def _receipt_lines_packed(db: AsyncSession, items: list[dict], *,
                                dispatch_id: int | None = None) -> None:
    """Put the packs the goods were SENT in onto the receiving point's GRN lines
    (2026-10-22), so the destination books them in — and shelves them — as the same
    cartons, and its stock balance shows them. One hierarchy per line: a row fed by
    issue lines packed two different ways is left loose rather than guessed at."""
    # What the cartons said, first (2026-10-22): the packer may have changed it.
    carton: dict[int, list] = {}
    if dispatch_id:
        for entries in (await db.execute(
                select(m.DispatchPackage.item_packs)
                .where(m.DispatchPackage.dispatch_id == dispatch_id))).scalars().all():
            if isinstance(entries, str):
                entries = json.loads(entries or "null")
            for row in entries or []:
                if row.get("issue_item_id") and row.get("pack_hierarchy_id"):
                    carton.setdefault(int(row["issue_item_id"]), []).append(row)
    if carton:
        for row in items:
            lines = row.get("_issue_lines") or {}
            got = [c for line_id in lines for c in carton.get(line_id, [])]
            hids = {c["pack_hierarchy_id"] for c in got}
            if got and all(line_id in carton for line_id in lines) and len(hids) == 1:
                merged = wh_packing.merge_breakdowns(
                    [c.get("pack_breakdown") or [] for c in got], row.get("uom_code"))
                if merged:
                    row["pack_hierarchy_id"] = hids.pop()
                    row["pack_breakdown"] = merged["pack_breakdown"]
                    row["_issue_lines"] = {}

    wanted: dict[int, Decimal] = {}
    for row in items:
        for line_id, qty in (row.get("_issue_lines") or {}).items():
            wanted[line_id] = wanted.get(line_id, ZERO) + _d(qty)
    packs = await wh_packing.issue_line_packs(db, wanted)
    hierarchy = dict((await db.execute(
        select(m.MaterialIssueLine.id, m.MaterialIssueLine.pack_hierarchy_id)
        .where(m.MaterialIssueLine.id.in_(list(packs) or [0])))).all())
    for row in items:
        lines = row.pop("_issue_lines", None) or {}
        if not lines or any(line_id not in packs for line_id in lines):
            continue
        hids = {hierarchy.get(line_id) for line_id in lines}
        if len(hids) != 1 or None in hids:
            continue
        # Each issue line's packs for the share of it on THIS row.
        parts = []
        for line_id, qty in lines.items():
            if _d(qty) == wanted[line_id]:
                parts.append(packs[line_id]["pack_breakdown"])
            else:
                share = await wh_packing.issue_line_packs(db, {line_id: qty})
                parts.append((share.get(line_id) or {}).get("pack_breakdown") or [])
        merged = wh_packing.merge_breakdowns(parts, row.get("uom_code"))
        if merged:
            row["pack_hierarchy_id"] = hids.pop()
            row["pack_breakdown"] = merged["pack_breakdown"]


def _group_dispatch_lines(lines, serial_batch: dict[str, int], batches: dict,
                          tracking: dict) -> list[dict]:
    """The consignment's lines, one row per item rather than one per unit.

    A serialised item leaves the gate as one `out_dispatch_items` row PER UNIT — ten
    handsets are ten lines of qty 1 — and rendering those straight put ten rows of 1
    on the receiver's GRN, which he then inwarded as ten separate stock lines. The
    units are still named individually; they are collected onto the line they belong
    to instead of each becoming a line of its own.

    Batch is part of the key: two batches of the same item are two things to receive,
    with their own expiry, and must not be added together. So is the indent, because
    a consolidated consignment serving two requests owes each of them separately.

    Pure, and separate from the query above, so the grouping can be tested without a
    database — it is the part that was wrong.
    """
    items: list[dict] = []
    grouped: dict[tuple, dict] = {}
    for line in lines:
        batch_id = line.batch_id if (
            line.batch_id and line.batch_id != m.NO_BATCH
        ) else serial_batch.get(line.serial_no or "")
        batch = batches.get(batch_id) if batch_id else None
        key = (line.item_id, batch_id or 0, line.batch_no or "", line.indent_id or 0,
               _combo3(getattr(line, "brand_id", 0), getattr(line, "variant_id", 0),
                       getattr(line, "model_id", 0)))
        existing = grouped.get(key)
        if existing is not None:
            for field in ("ordered_qty", "received_qty", "accepted_qty"):
                existing[field] = _d(existing[field]) + _d(line.quantity)
            if getattr(line, "issue_item_id", None):
                sent = existing.setdefault("_issue_lines", {})
                sent[line.issue_item_id] = _d(sent.get(line.issue_item_id)) + _d(line.quantity)
            if line.serial_no:
                existing["serial_numbers"] = (existing["serial_numbers"] or []) + [
                    line.serial_no]
            if line.imei_no:
                existing["imei_numbers"] = (existing["imei_numbers"] or []) + [
                    line.imei_no]
            continue
        row = {
            "item_id": line.item_id,
            # What was sent: the same brand / variant / model lands here (2026-10-23).
            **combinations.carry(line),
            # The snapshot the consignment carries. Without these the inward form had
            # an item id and nothing to show for it, so every line rendered as the
            # placeholder "PO line" with no code, name or unit.
            "item_code": line.item_code,
            "item_name": line.item_name,
            "uom_code": line.uom_code,
            "indent_id": line.indent_id,
            "indent_no": line.indent_no,
            # What was sent is what the receiver is asked to confirm or correct —
            # typing it back off the challan is how a shortage gets missed.
            "ordered_qty": _d(line.quantity),
            "received_qty": _d(line.quantity),
            "accepted_qty": _d(line.quantity),
            "rate": line.rate,
            # The line's own snapshot wins: a hand-corrected consignment keeps
            # showing what was actually sent. The batch lookup is now only a
            # fallback, for consignments dispatched before the dates were carried.
            "batch_no": line.batch_no or (batch.batch_no if batch else None),
            "mfg_date": line.mfg_date or (batch.mfg_date if batch else None),
            "expiry_date": line.expiry_date or (batch.expiry_date if batch else None),
            "serial_numbers": [line.serial_no] if line.serial_no else None,
            # Prefilled from the unit that was dispatched. The receiving storekeeper
            # was being asked to retype every IMEI off the handset — "enter exactly 1
            # IMEI numbers for ..." — against a GRN that already knew which unit
            # was in the box.
            "imei_numbers": [line.imei_no] if line.imei_no else None,
            "is_serial_tracked": bool(
                getattr(tracking.get(line.item_id), "is_serial_tracked", False)),
            "is_imei_tracked": bool(
                getattr(tracking.get(line.item_id), "is_imei_tracked", False)),
            # Which issue lines this row carries, and how much of each — read by the
            # caller to put the packs on it, then dropped (2026-10-22).
            "_issue_lines": ({line.issue_item_id: _d(line.quantity)}
                             if getattr(line, "issue_item_id", None) else {}),
        }
        grouped[key] = row
        items.append(row)

    return items


async def indent_options(
    db: AsyncSession, search: str | None = None, warehouse_id: int | None = None,
) -> list[dict]:
    from app.modules.indents.models import Indent
    from app.modules.inventory.models import Reservation

    stmt = (
        select(Indent)
        .join(Reservation, Reservation.ref_id == Indent.id)
        .where(
            Reservation.ref_type == InventoryRefType.RESERVATION.value,
            Reservation.status == ReservationStatus.ACTIVE.value,
        )
        .distinct()
    )
    if warehouse_id is not None:
        stmt = stmt.where(Reservation.warehouse_id == warehouse_id)
    if search:
        stmt = stmt.where(Indent.indent_no.ilike(f"%{search}%"))
    rows = (await db.execute(stmt.order_by(Indent.id.desc()).limit(LOOKUP_LIMIT))).scalars().all()
    
    if warehouse_id is not None:
        peers = await _same_tier_warehouse_ids(db, warehouse_id)
    else:
        peers = None

    items = []
    for r in rows:
        caps = await _indent_cap(db, r.id)
        taken = await _already_issued(db, r.id, warehouse_ids=peers)
        if not any(cap > taken.get(item_id, ZERO) for item_id, cap in caps.items()):
            continue
        if warehouse_id is not None:
            # Offered only while something reserved HERE is still unclaimed. A draft
            # already covering this point's whole allocation is the document to open —
            # offering the indent again is how the same units were drafted twice.
            # Cancelling that draft frees the claim, and the indent comes back.
            held = await _held_by_line(db, r.id, warehouse_id=warehouse_id)
            claims = await _unposted_claims(db, r.id, warehouse_id)
            if not any(qty > claims.get(line_id, ZERO) for line_id, qty in held.items()):
                continue
        # An STR says so in the picker — its number alone reads like any indent's.
        items.append({"id": r.id, "code": r.indent_no,
                      "name": ("STR · " if r.indent_type == _STR_INDENT_TYPE else "")
                      + (getattr(r, "department_name", None) or r.indent_no)})
    return items


async def issue_transfer_context(db: AsyncSession, issue_id: int) -> dict:
    """Everything a consignment, a dispatch and an in-person handover inherit from the
    issue behind them (2026-10-29), so nobody re-types it: what it serves (STR / STO /
    indent / direct) and its number, where it goes, the department and project, who
    it is issued to with their code and phone, the SAC and the vehicle.

    Read, never stored: the issue is the one place these were decided, and a copy on
    the consignment would be a second answer the day the issue is corrected.
    """
    from app.modules.indents.models import Indent
    from app.platform.hcm.models import HcmEmployee

    issue = await db.get(m.MaterialIssue, issue_id)
    if issue is None:
        raise NotFoundError(f"Material issue {issue_id} not found")
    await _decorate_indent_types(db, [issue])
    indent = await db.get(Indent, issue.indent_id) if issue.indent_id else None
    person = await db.get(HcmEmployee, issue.issued_to_id) if issue.issued_to_id else None
    office_id, office_name = await _issue_destination(db, issue)
    sac = await _office_sac(db, office_id)
    point = await _requesting_point(db, issue)
    sto_no = getattr(issue, "sto_no", None)
    indent_type = getattr(issue, "indent_type", None)
    kind = ("STR" if indent_type == _STR_INDENT_TYPE else "INDENT") if issue.indent_id         else ("STO" if sto_no else "DIRECT")
    return {
        "issue_id": issue.id, "issue_no": issue.issue_no,
        "kind": kind,
        "reference_no": (issue.indent_no if kind in ("STR", "INDENT") else sto_no),
        "str_no": issue.indent_no if kind == "STR" else getattr(issue, "sto_str_no", None),
        "sto_no": sto_no,
        "indent_no": issue.indent_no if kind == "INDENT" else None,
        "from_warehouse_name": issue.warehouse_name,
        "destination_warehouse_id": getattr(point, "id", None)
            or getattr(issue, "sto_to_warehouse_id", None),
        "destination_warehouse_name": getattr(point, "name", None)
            or getattr(issue, "sto_to_warehouse_name", None),
        "destination_office_name": office_name,
        "sac": sac,
        "department_name": issue.department_name
            or getattr(indent, "department_name", None),
        "project_name": issue.project_name or getattr(indent, "project_name", None),
        "issued_to_id": issue.issued_to_id,
        "issued_to_name": issue.issued_to_name or getattr(person, "full_name", None),
        "issued_to_code": getattr(person, "emp_code", None),
        "issued_to_phone": getattr(person, "mobile", None),
        "vehicle_number": issue.vehicle_number,
    }


async def consignment_transfer_context(db: AsyncSession, dispatch_id: int) -> dict | None:
    """The transfer context of a consignment: its issue's, read through the first
    issue it carries. None for a consignment that carries no material issue."""
    dispatch = await db.get(m.Dispatch, dispatch_id)
    if dispatch is None:
        raise NotFoundError(f"Consignment {dispatch_id} not found")
    issue_id = await db.scalar(
            select(m.DispatchSource.issue_id)
            .where(m.DispatchSource.dispatch_id == dispatch_id,
                   m.DispatchSource.issue_id.is_not(None))
            .order_by(m.DispatchSource.id).limit(1))
    if not issue_id and dispatch.ref_id and dispatch.ref_type in SINGLE_ISSUE_REF_TYPES:
        issue_id = dispatch.ref_id
    if not issue_id:
        return None
    context = await issue_transfer_context(db, issue_id)
    # The consignment's own vehicle wins: it is what the gate pass will name.
    context["vehicle_number"] = dispatch.vehicle_number or context["vehicle_number"]
    return context


async def sto_issue_options(
    db: AsyncSession, search: str | None = None, warehouse_id: int | None = None,
) -> list[dict]:
    """Approved Stock Transfer Orders leaving this point, each with the issue that
    executes it (2026-10-29).

    An approved direct STO already HAS its issue — `draft_issue_for_sto` wrote it on
    approval — so the issue form's STO picker never drafts a second one: picking an
    order opens the issue it already has. Offered while that issue is still open;
    posted or cancelled, there is nothing left to issue against it.
    """
    from app.modules.inventory.enums import STOStatus
    from app.modules.inventory.models import STO_KIND_TRANSFER, StockTransferOrder

    stmt = (
        select(StockTransferOrder, m.MaterialIssue.status.label("issue_status"))
        .outerjoin(m.MaterialIssue, m.MaterialIssue.id == StockTransferOrder.issue_id)
        .where(StockTransferOrder.doc_kind == STO_KIND_TRANSFER,
               StockTransferOrder.status == STOStatus.APPROVED.value,
               or_(StockTransferOrder.issue_id.is_(None),
                   m.MaterialIssue.is_stock_posted.is_(False)),
               or_(m.MaterialIssue.status.is_(None),
                   m.MaterialIssue.status != IssueStatus.CANCELLED.value))
    )
    if warehouse_id is not None:
        stmt = stmt.where(StockTransferOrder.from_warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(StockTransferOrder.sto_no.ilike(like),
                              StockTransferOrder.to_warehouse_name.ilike(like),
                              StockTransferOrder.str_no.ilike(like)))
    rows = (await db.execute(
        stmt.order_by(StockTransferOrder.id.desc()).limit(LOOKUP_LIMIT))).all()
    return [{
        "id": order.id, "sto_no": order.sto_no,
        "kind": "STR" if order.str_id else "DIRECT", "str_no": order.str_no,
        "from_warehouse_id": order.from_warehouse_id,
        "from_warehouse_name": order.from_warehouse_name,
        "to_warehouse_id": order.to_warehouse_id,
        "to_warehouse_name": order.to_warehouse_name,
        "issue_id": order.issue_id, "issue_no": order.issue_no,
        "issue_status": issue_status,
        "item_count": len(order.items or []),
        "requested_qty": float(sum((_d(i.requested_qty) for i in order.items or []), ZERO)),
    } for order, issue_status in rows]


async def indent_issue_source(
    db: AsyncSession, indent_id: int, warehouse_id: int,
) -> dict:
    """The approved reservation handoff used to seed a warehouse issue."""
    from app.modules.indents.models import Indent
    from app.modules.inventory.models import Reservation
    from app.platform.hcm.models import HcmEmployee

    indent = await _get(db, Indent, indent_id, "Indent")
    requested_by_id = getattr(indent, "requested_by_id", None)
    requested_by = await db.get(HcmEmployee, requested_by_id) if requested_by_id else None
    from app.modules.inventory.models import Stock
    rows = (await db.execute(
        select(
            Reservation.ref_line_id,
            Reservation.item_id,
            Reservation.bin_id,
            Reservation.batch_id,
            Reservation.project_id,
            func.sum(Reservation.quantity),
            # Which brand / variant / model is held (2026-10-23) — off the stock row
            # the hold sits on, so a hold made before the column existed reads too.
            Stock.brand_id, Stock.variant_id, Stock.model_id,
        )
        .join(Stock, Stock.id == Reservation.stock_id)
        .where(
            Reservation.ref_type == InventoryRefType.RESERVATION.value,
            Reservation.ref_id == indent_id,
            Reservation.warehouse_id == warehouse_id,
            Reservation.status == ReservationStatus.ACTIVE.value,
        )
        .group_by(
            Reservation.ref_line_id,
            Reservation.item_id,
            Reservation.bin_id,
            Reservation.batch_id,
            Reservation.project_id,
            Stock.brand_id, Stock.variant_id, Stock.model_id,
        )
        .order_by(Reservation.ref_line_id, Reservation.item_id)
    )).all()
    if not rows:
        raise ValidationError(
            f"{indent.indent_no} has no active reservation in this warehouse"
        )

    # Stock is one shared pool: inventory allocates by availability, not by project
    # (see inventory/availability.candidate_stock), so one indent legitimately draws
    # from rows received for other projects — or for none at all. The project on a
    # stock row is history, not a fence, so a mixed draw is reported, never blocked.
    # The consuming project is the indent's; the source project stays on each ledger
    # row written at posting.
    mixed_projects = any(
        (row.project_id or 0) != (getattr(indent, "project_id", None) or 0)
        for row in rows
    )

    item_ids = {row.item_id for row in rows}
    item_by_id = {
        item.id: item
        for item in (await db.execute(select(Item).where(Item.id.in_(item_ids)))).scalars().all()
    } if item_ids else {}

    bin_ids = {row.bin_id for row in rows if row.bin_id}
    bin_by_id = {
        b.id: b
        for b in (await db.execute(select(m.Bin).where(m.Bin.id.in_(bin_ids)))).scalars().all()
    } if bin_ids else {}

    batch_ids = {row.batch_id for row in rows if row.batch_id}
    batch_by_id = {
        b.id: b
        for b in (await db.execute(select(m.Batch).where(m.Batch.id.in_(batch_ids)))).scalars().all()
    } if batch_ids else {}

    peers = await _same_tier_warehouse_ids(db, warehouse_id)
    taken = await _already_issued(db, indent_id, warehouse_ids=peers)
    caps = await _indent_cap(db, indent_id)

    items = []
    # What the indent still owes this tier, per item, SPENT as the rows are read. One
    # item reserved over two batches is two rows, and capping each row at the whole
    # outstanding figure prefilled 5 + 5 against an indent owed 6 — a form the save
    # then refused, with no hint which line to cut.
    left = {item_id: max(ZERO, cap - taken.get(item_id, ZERO))
            for item_id, cap in caps.items()}
    # And what other unposted issues at this point already claim of the same hold —
    # spent off the rows the same way, oldest reservation row first.
    claimed = await _unposted_claims(db, indent_id, warehouse_id)
    for row in rows:
        item_id = row.item_id
        reserved_qty = _d(row[5])
        line_claim = claimed.get(row.ref_line_id or 0, ZERO)
        usable = max(ZERO, reserved_qty - line_claim)
        if row.ref_line_id:
            claimed[row.ref_line_id] = max(ZERO, line_claim - reserved_qty)
        qty = min(usable, left.get(item_id, ZERO))
        if qty <= ZERO:
            continue
        left[item_id] = left.get(item_id, ZERO) - qty
        items.append({
            "indent_item_id": row.ref_line_id,
            "item_id": item_id,
            "item_code": item_by_id[item_id].code if item_id in item_by_id else None,
            "item_name": item_by_id[item_id].name if item_id in item_by_id else None,
            "is_serial_tracked": (
                bool(item_by_id[item_id].is_serial_tracked)
                if item_id in item_by_id else False
            ),
            "bin_id": row.bin_id or None,
            "bin_code": bin_by_id[row.bin_id].code if row.bin_id and row.bin_id in bin_by_id else None,
            "bin_path": getattr(bin_by_id[row.bin_id], "path", None) if row.bin_id and row.bin_id in bin_by_id else None,
            "batch_id": row.batch_id or None,
            "batch_no": batch_by_id[row.batch_id].batch_no if row.batch_id and row.batch_id in batch_by_id else None,
            "requested_qty": qty,
            "issued_qty": qty,
        })

    if not items:
        holders = await _live_issue_labels(db, indent_id, [warehouse_id])
        raise ValidationError(
            f"{indent.indent_no} has nothing left to issue from this point"
            + (f" — {holders} already cover{'s' if ',' not in holders else ''} what is "
               "reserved here. Open that issue instead." if holders else "."))

    return {
        "indent_id": indent.id,
        "indent_no": indent.indent_no,
        "warehouse_id": warehouse_id,
        "department_id": getattr(indent, "department_id", None),
        "department_name": getattr(indent, "department_name", None),
        "project_id": getattr(indent, "project_id", None) or None,
        "project_name": getattr(indent, "project_name", None) or None,
        "mixed_projects": mixed_projects,
        "issued_to_id": requested_by_id,
        "issued_to_name": requested_by.full_name if requested_by else None,
        "vehicle_id": getattr(indent, "vehicle_id", None),
        "vehicle_number": (
            getattr(indent, "vehicle_number", None)
            or _vehicle_from_office_name(requested_by.office_name if requested_by else None)
        ),
        "destination_office_id": requested_by.office_id if requested_by else None,
        "destination_office_name": requested_by.office_name if requested_by else None,
        # Travels with the office the goods are headed to, so picking the indent
        # fills the SAC the same way it fills the destination — the raiser's office
        # code, never the storekeeper's own.
        "destination_office_sac": await _office_sac(
            db, requested_by.office_id if requested_by else None),
        # One line per indent line, QUANTITY only (2026-10-12): the hold is a quantity
        # that floats between batches, and the storekeeper picks the batch — offered
        # earliest-expiry first — and the location on the issue itself. Per brand /
        # variant / model held (2026-10-23): 5 Alpha and 3 Beta are two lines.
        "items": await _named_combinations(db, [
            {
                "indent_item_id": line_id,
                "item_id": item_id,
                "brand_id": combo[0], "variant_id": combo[1], "model_id": combo[2],
                "item_code": item_by_id[item_id].code if item_id in item_by_id else None,
                "item_name": item_by_id[item_id].name if item_id in item_by_id else None,
                "is_serial_tracked": (
                    bool(item_by_id[item_id].is_serial_tracked)
                    if item_id in item_by_id else False
                ),
                "bin_id": None, "bin_code": None, "bin_path": None,
                "batch_id": None, "batch_no": None,
                "requested_qty": qty,
                "issued_qty": qty,
            }
            for (line_id, item_id, combo), qty in _sum_by_line(rows).items()
        ]),
    }


async def _named_combinations(db: AsyncSession, rows: list[dict]) -> list[dict]:
    await combinations.fill_names(db, rows)
    return rows


def _sum_by_line(rows) -> dict[tuple, Decimal]:
    """Reservation rows (line, item, bin, batch, project, qty, b, v, m) summed per
    indent line and brand / variant / model."""
    out: dict[tuple, Decimal] = {}
    for row in rows:
        key = (row.ref_line_id, row.item_id,
               _combo3(row.brand_id, row.variant_id, row.model_id))
        out[key] = out.get(key, ZERO) + _d(row[5])
    return out


async def picking_issue_source(db: AsyncSession, picking_id: int) -> dict:
    """Turn a completed physical pick into the material-issue draft that posts it."""
    from app.modules.indents.models import Indent
    from app.modules.inventory.models import Reservation
    from app.platform.hcm.models import HcmEmployee

    picking = await get_picking(db, picking_id)
    _guard(
        picking.status,
        {PickingStatus.PICKED.value, PickingStatus.COMPLETED.value},
        "create an issue from", "material fulfilment",
    )
    indent_id = picking.ref_id if picking.ref_type == "INDENT" else None
    indent = await db.get(Indent, indent_id) if indent_id else None
    requested_by_id = getattr(indent, "requested_by_id", None) if indent else None
    requested_by = await db.get(HcmEmployee, requested_by_id) if requested_by_id else None

    reservations = []
    if indent_id:
        reservations = list((await db.execute(
            select(Reservation).where(
                Reservation.ref_type == InventoryRefType.RESERVATION.value,
                Reservation.ref_id == indent_id,
                Reservation.warehouse_id == picking.warehouse_id,
                Reservation.status == ReservationStatus.ACTIVE.value,
            ).order_by(Reservation.id)
        )).scalars().all())

    # Same rule as indent_issue_source: a pick that spans projects is reported, not
    # refused. The pick already happened — the goods are off the shelf.
    indent_project = (getattr(indent, "project_id", None) if indent else None) or 0
    mixed_projects = any((row.project_id or 0) != indent_project for row in reservations)

    items = []
    item_ids = {line.item_id for line in picking.items}
    item_by_id = {
        item.id: item
        for item in (await db.execute(select(Item).where(Item.id.in_(item_ids)))).scalars().all()
    } if item_ids else {}

    bin_ids = {line.bin_id for line in picking.items if line.bin_id}
    bin_by_id = {
        b.id: b
        for b in (await db.execute(select(m.Bin).where(m.Bin.id.in_(bin_ids)))).scalars().all()
    } if bin_ids else {}

    batch_ids = {line.batch_id for line in picking.items if line.batch_id}
    batch_by_id = {
        b.id: b
        for b in (await db.execute(select(m.Batch).where(m.Batch.id.in_(batch_ids)))).scalars().all()
    } if batch_ids else {}

    for line in picking.items:
        qty = _d(line.picked_qty)
        if qty <= ZERO:
            continue
        reservation = next(
            (
                row for row in reservations
                if row.item_id == line.item_id
                and (not line.bin_id or row.bin_id == line.bin_id)
                and (not line.batch_id or row.batch_id == line.batch_id)
            ),
            None,
        )
        items.append({
            "indent_item_id": reservation.ref_line_id if reservation else None,
            "item_id": line.item_id,
            "item_code": item_by_id[line.item_id].code if line.item_id in item_by_id else None,
            "item_name": item_by_id[line.item_id].name if line.item_id in item_by_id else None,
            "is_serial_tracked": (
                bool(item_by_id[line.item_id].is_serial_tracked)
                if line.item_id in item_by_id else False
            ),
            "bin_id": line.bin_id,
            "bin_code": bin_by_id[line.bin_id].code if line.bin_id and line.bin_id in bin_by_id else None,
            "bin_path": getattr(bin_by_id[line.bin_id], "path", None) if line.bin_id and line.bin_id in bin_by_id else None,
            "batch_id": line.batch_id,
            "batch_no": batch_by_id[line.batch_id].batch_no if line.batch_id and line.batch_id in batch_by_id else None,
            "requested_qty": _d(line.required_qty),
            "issued_qty": qty,
        })
    if not items:
        raise ValidationError(f"{picking.pick_no} has no picked quantity to issue")

    return {
        "picking_id": picking.id,
        "warehouse_id": picking.warehouse_id,
        "indent_id": indent_id,
        "department_id": getattr(indent, "department_id", None) if indent else None,
        "department_name": getattr(indent, "department_name", None) if indent else None,
        "project_id": indent_project or None,
        "project_name": getattr(indent, "project_name", None) if indent else None,
        "mixed_projects": mixed_projects,
        # Same default as indent_issue_source: whoever raised the request.
        "issued_to_id": requested_by_id,
        "issued_to_name": requested_by.full_name if requested_by else None,
        "vehicle_id": getattr(indent, "vehicle_id", None) if indent else None,
        "vehicle_number": (
            (getattr(indent, "vehicle_number", None) if indent else None)
            or _vehicle_from_office_name(requested_by.office_name if requested_by else None)
        ),
        "items": items,
    }


async def inspectable_issue_options(db: AsyncSession,
                                    search: str | None = None) -> list[dict]:
    """Posted outward issues that still owe an outward QC.

    Deliberately NOT `issue_options`. That one lists what may be DISPATCHED, so it
    excludes exactly the issues this screen exists to inspect (`qc_status` PENDING or
    FAILED) — pointing the Outward QC lookup at it would have offered a list of issues
    the create guard then refuses one by one.

    The pair it does share with `create_outbound_inspection` is the guard itself: an
    issue already carrying a live inspection is off the list, because raising a second
    one against it is refused there.
    """
    inspected = set((await db.execute(
        select(m.OutboundInspection.issue_id).where(
            m.OutboundInspection.status.notin_([
                InspectionStatus.CANCELLED.value,
                InspectionStatus.REJECTED.value,
            ]),
            m.OutboundInspection.issue_id.isnot(None),
        )
    )).scalars().all())
    stmt = select(m.MaterialIssue).where(
        m.MaterialIssue.direction == IssueDirection.OUT.value,
        m.MaterialIssue.is_stock_posted.is_(True),
        m.MaterialIssue.qc_status.in_(INSPECTABLE_QC),
    )
    if inspected:
        stmt = stmt.where(m.MaterialIssue.id.notin_(inspected))
    if search:
        stmt = stmt.where(m.MaterialIssue.issue_no.ilike(f"%{search}%"))
    rows = (await db.execute(
        stmt.order_by(m.MaterialIssue.id.desc()).limit(LOOKUP_LIMIT)
    )).scalars().all()
    return [
        {
            "id": row.id,
            "code": row.issue_no,
            "name": row.issued_to_name or row.department_name or row.issue_no,
        }
        for row in rows
    ]


async def _requesting_points(
    db: AsyncSession,
    issues: list[m.MaterialIssue],
) -> dict[int, Warehouse | None]:
    """`_requesting_point` for many issues in four queries rather than several each.

    Same answer, same order of preference: the office of the person the issue names,
    else the office on the indent, resolved to the lowest-id active point serving it.
    The recommendation list and the grouped issue picker both ask this of up to a few
    hundred issues, where one call per issue was a query storm per keystroke.
    """
    from app.platform.hcm.models import HcmEmployee
    from app.modules.indents.models import Indent

    employee_ids = {row.issued_to_id for row in issues if row.issued_to_id}
    indent_ids = {row.indent_id for row in issues if row.indent_id}
    office_of_employee = dict((await db.execute(
        select(HcmEmployee.id, HcmEmployee.office_id).where(HcmEmployee.id.in_(employee_ids))
    )).all()) if employee_ids else {}
    office_of_indent = dict((await db.execute(
        select(Indent.id, Indent.office_id).where(Indent.id.in_(indent_ids))
    )).all()) if indent_ids else {}

    office_of_issue: dict[int, int | None] = {}
    for row in issues:
        office_id = office_of_employee.get(row.issued_to_id) if row.issued_to_id else None
        office_of_issue[row.id] = office_id or office_of_indent.get(row.indent_id)

    chosen_ids = {row.destination_warehouse_id for row in issues
                  if getattr(row, "destination_warehouse_id", None)}
    chosen = {
        point.id: point for point in (await db.execute(
            select(Warehouse).where(Warehouse.id.in_(chosen_ids)))).scalars().all()
    } if chosen_ids else {}

    office_ids = {value for value in office_of_issue.values() if value}
    point_of_office: dict[int, Warehouse] = {}
    if office_ids:
        for point in (await db.execute(
            select(Warehouse)
            .where(Warehouse.office_id.in_(office_ids), Warehouse.is_active.is_(True))
            .order_by(Warehouse.id)
        )).scalars().all():
            point_of_office.setdefault(point.office_id, point)
    # A chosen destination wins, exactly as in `_requesting_point`.
    chosen_of_issue = {row.id: chosen.get(row.destination_warehouse_id)
                       for row in issues if getattr(row, "destination_warehouse_id", None)}
    return {
        issue_id: chosen_of_issue.get(issue_id)
        or (point_of_office.get(office_id) if office_id else None)
        for issue_id, office_id in office_of_issue.items()
    }


# An outward issue reaches logistics once outward QC has passed it (PARTIAL: the
# accepted part), or when none of its items requires QC at all (NOT_REQUIRED — see
# the note in `post_issue`). The two sets are disjoint, so an issue is offered to
# exactly one of the QC desk and the packing desk, never both.
CONSIGNABLE_QC = (QcStatus.PASSED.value, QcStatus.PARTIAL.value,
                  QcStatus.NOT_REQUIRED.value)
INSPECTABLE_QC = (QcStatus.PENDING.value, QcStatus.FAILED.value)


def _consignable_issues_stmt():
    """Posted outward issues whose outward QC does not hold them back.

    What `_consignment_issues` accepts, as a query — so a picker built on it never
    offers an issue the save would refuse.
    """
    return select(m.MaterialIssue).where(
        m.MaterialIssue.direction == IssueDirection.OUT.value,
        m.MaterialIssue.is_stock_posted.is_(True),
        m.MaterialIssue.qc_status.in_(CONSIGNABLE_QC),
    )


async def issue_options(db: AsyncSession, search: str | None = None, *,
                        warehouse_id: int | None = None,
                        destination_warehouse_id: int | None = None) -> list[dict]:
    """Posted outward issues that have not already become a consignment.

    `warehouse_id` + `destination_warehouse_id` narrow it to issues that may share a
    consignment with ones already chosen — same point out, same point in — so adding a
    second issue to a grouped consignment can never pick one the save would refuse.
    """
    used = await _issue_ids_in_live_consignments(db)
    stmt = _consignable_issues_stmt()
    if used:
        stmt = stmt.where(m.MaterialIssue.id.notin_(used))
    if warehouse_id:
        stmt = stmt.where(m.MaterialIssue.warehouse_id == warehouse_id)
    if search:
        stmt = stmt.where(m.MaterialIssue.issue_no.ilike(f"%{search}%"))
    rows = (await db.execute(
        stmt.order_by(m.MaterialIssue.id.desc()).limit(LOOKUP_LIMIT)
    )).scalars().all()
    if destination_warehouse_id:
        points = await _requesting_points(db, list(rows))
        rows = [
            row for row in rows
            if (point := points.get(row.id)) is not None
            and point.id == destination_warehouse_id
            and point.id != row.warehouse_id
        ]
    return [
        {
            "id": row.id,
            "code": row.issue_no,
            "name": row.issued_to_name or row.department_name or row.issue_no,
        }
        for row in rows
    ]


async def returnable_issue_options(
    db: AsyncSession,
    search: str | None = None,
) -> list[dict]:
    stmt = select(m.MaterialIssue).where(
        m.MaterialIssue.direction == IssueDirection.OUT.value,
        m.MaterialIssue.is_stock_posted.is_(True),
        m.MaterialIssue.status.in_(
            (
                IssueStatus.ISSUED.value,
                IssueStatus.DISPATCHED.value,
                IssueStatus.ACKNOWLEDGED.value,
                IssueStatus.PARTIALLY_RETURNED.value,
            )
        ),
    )
    if search:
        stmt = stmt.where(m.MaterialIssue.issue_no.ilike(f"%{search}%"))
    rows = (await db.execute(
        stmt.order_by(m.MaterialIssue.id.desc()).limit(LOOKUP_LIMIT)
    )).scalars().all()
    return [{
        "id": row.id,
        "code": row.issue_no,
        "name": row.issued_to_name or row.department_name or row.issue_no,
    } for row in rows]


async def issue_dispatch_sources(db: AsyncSession, issue_ids: str) -> dict:
    """One packing source for several issues bound for the same stocking point.

    The same rows `issue_dispatch_source` serves for each issue, one after another, with
    every line naming the issue it came from — packing keys on (issue, item, batch), so
    the same item on two issues is two separate things to pack.
    """
    ids: list[int] = []
    for part in (issue_ids or "").split(","):
        part = part.strip()
        if not part:
            continue
        if not part.isdigit():
            raise ValidationError(f"'{part}' is not a material issue id")
        ids.append(int(part))
    unique = list(dict.fromkeys(ids))
    if not unique:
        raise ValidationError("Select at least one material issue")
    if len(unique) > MAX_ISSUES_PER_CONSIGNMENT:
        raise ValidationError(
            f"One consignment can carry at most {MAX_ISSUES_PER_CONSIGNMENT} material issues")

    sources = [await issue_dispatch_source(db, issue_id) for issue_id in unique]
    if len({row["warehouse_id"] for row in sources}) != 1:
        raise ValidationError(
            "These material issues leave from different stocking points. One consignment "
            "is one lorry from one place — pick issues from the same point.")
    if len(sources) > 1:
        for row in sources:
            if not row.get("destination_warehouse_id"):
                raise ValidationError(
                    f"{row['issue_no']} has no stocking point to deliver to, so it cannot "
                    "share a consignment. Send it on its own.")
        names = {row["destination_warehouse_id"]: row.get("destination_warehouse_name")
                 for row in sources}
        if len(names) > 1:
            raise ValidationError(
                "These material issues are going to different stocking points ("
                + ", ".join(sorted(str(name) for name in names.values()))
                + "). Only issues for the same LIP/MDP can travel in one consignment.")
    first = sources[0]
    return {
        **first,
        "issue_ids": [row["issue_id"] for row in sources],
        "issue_nos": [row["issue_no"] for row in sources],
        "issue_no": first["issue_no"] if len(sources) == 1 else f"{len(sources)} material issues",
        "items": [item for row in sources for item in row["items"]],
    }


async def consignment_recommendations(db: AsyncSession, user, limit: int = 8) -> list[dict]:
    """Issues waiting at the same stocking point for the same LIP/MDP, grouped.

    A suggestion, never a decision: each group is issues that are ready (posted,
    through outward QC, on no consignment yet), leave from one point this login can
    see, and are addressed to one other point. The biggest groups come first, and among
    equals the one that has waited longest. Built on the same rules as the save and the
    picker, so every suggestion can be packed as offered.
    """
    stmt = _consignable_issues_stmt().where(
        m.MaterialIssue.status == IssueStatus.ISSUED.value,
    )
    used = await _issue_ids_in_live_consignments(db)
    if used:
        stmt = stmt.where(m.MaterialIssue.id.notin_(used))
    allowed = await warehouse_ids_for_user(db, user)
    if allowed is not None:
        if not allowed:
            return []
        stmt = stmt.where(m.MaterialIssue.warehouse_id.in_(allowed))
    rows = list((await db.execute(
        stmt.options(selectinload(m.MaterialIssue.items))
        .order_by(m.MaterialIssue.id.desc())
        .limit(RECOMMENDATION_SCAN_LIMIT)
    )).scalars().all())
    if not rows:
        return []

    points = await _requesting_points(db, rows)
    groups: dict[tuple[int, int], list[m.MaterialIssue]] = defaultdict(list)
    destinations: dict[int, Warehouse] = {}
    for issue in rows:
        point = points.get(issue.id)
        # No point, or the point that issued it: nothing to carry, so nothing to group.
        if point is None or point.id == issue.warehouse_id:
            continue
        destinations[point.id] = point
        groups[(issue.warehouse_id, point.id)].append(issue)

    ready = [(key, members) for key, members in groups.items() if len(members) > 1]
    ready.sort(key=lambda entry: (-len(entry[1]),
                                  min(row.issue_date for row in entry[1])))
    ready = ready[:limit]

    origin_names = dict((await db.execute(
        select(Warehouse.id, Warehouse.name)
        .where(Warehouse.id.in_({key[0] for key, _ in ready}))
    )).all()) if ready else {}

    out: list[dict] = []
    for (origin_id, destination_id), members in ready:
        members = members[:MAX_ISSUES_PER_CONSIGNMENT]
        members.sort(key=lambda row: (row.issue_date, row.id))
        destination = destinations[destination_id]
        origin_name = origin_names.get(origin_id) or members[0].warehouse_name
        issues_out: list[dict] = []
        mr_nos: list[str] = []
        for issue in members:
            issue_mrs = [row["mr_no"] for row in await _issue_mr_sources(db, issue)
                         if row["mr_no"]]
            mr_nos.extend(no for no in issue_mrs if no not in mr_nos)
            issues_out.append({
                "issue_id": issue.id,
                "issue_no": issue.issue_no,
                "issue_date": issue.issue_date,
                "indent_no": issue.indent_no,
                "mr_nos": issue_mrs,
                "item_lines": len(issue.items),
                "total_qty": _d(issue.total_qty),
            })
        oldest = members[0].issue_date
        waited = (ist_today() - oldest).days if oldest else 0
        out.append({
            "key": f"{origin_id}:{destination_id}",
            "label": destination.name,
            "headline": f"{len(members)} issues ready for {destination.name}",
            "reason": (
                f"All leave from {origin_name} and go to {destination.name}. "
                "Send them together in one consignment instead of "
                f"{len(members)} separate trips."
                + (f" The oldest has waited {waited} day{'s' if waited != 1 else ''}."
                   if waited > 0 else "")
            ),
            "issue_ids": [row.id for row in members],
            "issue_nos": [row.issue_no for row in members],
            "issues": issues_out,
            "warehouse_id": origin_id,
            "warehouse_name": origin_name,
            "destination_warehouse_id": destination_id,
            "destination_warehouse_name": destination.name,
            "destination_office_name": getattr(destination, "office_name", None),
            "total_qty": sum((_d(row.total_qty) for row in members), ZERO),
            "item_lines": sum(len(row.items) for row in members),
            "mr_nos": mr_nos,
            "oldest_issue_date": oldest,
        })
    return out


async def issue_dispatch_source(db: AsyncSession, issue_id: int) -> dict:
    issue = await get_issue(db, issue_id)
    if issue.direction != IssueDirection.OUT.value or not issue.is_stock_posted:
        raise ValidationError("Only a posted outward issue can become a dispatch")
    if issue.qc_status not in CONSIGNABLE_QC:
        raise ValidationError("QC Outward must be completed before dispatch.")
    existing = await _live_consignment_for_issue(db, issue.id)
    if existing is not None:
        raise ValidationError(f"{issue.issue_no} is already packed on consignment {existing}")
    item_ids = {line.item_id for line in issue.items}
    item_by_id = {
        item.id: item
        for item in (await db.execute(select(Item).where(Item.id.in_(item_ids)))).scalars().all()
    } if item_ids else {}
    # Per issue LINE, never per (item, batch): one batch drawn from two bays is two
    # lines, and grouping by batch handed both rows every unit of the batch — the
    # packer then saw codes on a row that never sent them. `_issue_units_by_line`
    # attributes each posted unit by the batch AND bay it left from.
    units_by_line = await _issue_units_by_line(db, issue)
    imei_by_serial: dict[str, str] = {}
    serials_by_line: dict[int, list[str]] = {}
    for line_id, rows in units_by_line.items():
        serials_by_line[line_id] = [row.serial_number for row in rows if row.serial_number]
        # Keyed on every name of the unit, so the consignment can print the IMEI beside
        # the unit it belongs to instead of the receiving point retyping it.
        for row in rows:
            if not row.imei:
                continue
            for key in (row.serial_number, row.asset_code, row.consumable_code):
                if key:
                    imei_by_serial[key] = row.imei

    def _get_line_serials(line) -> list[str]:
        return serials_by_line.get(line.id, [])

    # The point the indent was raised from, so the form can PREFILL "To warehouse"
    # rather than leaving it blank and hoping. The server derived it either way, but
    # nobody could see the decision until they had saved — and a consignment saved
    # with a blank destination is one the receiving point cannot raise a GRN against.
    requesting = await _requesting_point(db, issue)

    qc = await db.scalar(
        select(m.OutboundInspection).where(
            m.OutboundInspection.issue_id == issue.id,
            m.OutboundInspection.status == InspectionStatus.COMPLETED.value
        ).order_by(m.OutboundInspection.id.desc()).limit(1).options(
            selectinload(m.OutboundInspection.items)
        )
    )

    qc_accepted = {}
    qc_serials = {}
    if qc:
        for item in qc.items:
            qc_accepted[item.issue_item_id] = item.accepted_qty
            if item.serial_numbers:
                data = item.serial_numbers
                accepted = (data.get("accepted", []) if isinstance(data, dict)
                            else data if isinstance(data, list) else [])
                # A box code stands for the units inside it (2026-10-26); a box with
                # no unit rows travels by quantity.
                qc_serials[item.issue_item_id] = await box_codes.expand_box_codes(
                    db, list(accepted), item_id=item.item_id)

    # Issued in BOXES (2026-10-26): such a line is packed by quantity and its boxes
    # are named on it — never asked for one unit code per piece, which a box of old
    # stock may not even have.
    box_lines: dict[int, list[dict]] = {}
    for issue_line in issue.items:
        after_qc = await box_codes.packages_after_qc(db, issue, issue_line)
        if after_qc or await box_codes.has_boxes(db, issue.id, issue_line.id):
            box_lines[issue_line.id] = [{"code": code, "quantity": float(qty)}
                                        for code, qty in after_qc.items()]
            # The carton and box each package came out of (2026-10-28), so the packer
            # can put one carton's packages together.
            await box_codes.decorate_packs(db, box_lines[issue_line.id], inner=False)

    def _get_accepted_serials(line) -> list[str]:
        if line.id in box_lines:
            return []
        if line.id in qc_serials:
            s_data = qc_serials[line.id]
            if isinstance(s_data, dict):
                return s_data.get("accepted", [])
            elif isinstance(s_data, list):
                return s_data
            return []
        return _get_line_serials(line)

    mr_rows = await _issue_mr_sources(db, issue)
    line_mr = mr_rows[0] if len(mr_rows) == 1 else {}
    # The issue line's packs, cut to what this consignment takes of it (2026-10-22).
    line_packs = await wh_packing.issue_line_packs(
        db, {line.id: _d(qc_accepted.get(line.id, line.issued_qty)) for line in issue.items})
    # A line in packages is described as its packages (2026-10-26).
    for issue_line in issue.items:
        if box_lines.get(issue_line.id):
            carries = {row["code"]: _d(row["quantity"]) for row in box_lines[issue_line.id]}
            packs = await box_codes.carton_packs(db, list(carries), carries, issue_line.uom_code)
            if packs:
                line_packs[issue_line.id] = {"pack_breakdown": packs["pack_breakdown"],
                                             "pack_text": packs["pack_text"]}

    return {
        "issue_id": issue.id,
        "issue_ids": [issue.id],
        "issue_no": issue.issue_no,
        "issue_nos": [issue.issue_no],
        "warehouse_id": issue.warehouse_id,
        "project_id": issue.project_id,
        "destination_office_id": getattr(issue, "destination_office_id", None),
        "destination_office_name": getattr(issue, "destination_office_name", None),
        "destination_office_sac": getattr(issue, "destination_office_sac", None),
        # Shown read-only on the consignment form: see _consignment_vehicle.
        "vehicle_number": _consignment_vehicle(
            issue, getattr(issue, "destination_office_name", None)),
        "destination_warehouse_id": (
            requesting.id if requesting and requesting.id != issue.warehouse_id else None
        ),
        "destination_warehouse_name": (
            requesting.name if requesting and requesting.id != issue.warehouse_id else None
        ),
        # The issue was made AT the point that asked for it, so the goods are already
        # there: no consignment, no dispatch, no GRN. The screen says so instead of
        # showing an unexplained empty destination.
        "destination_is_origin": bool(requesting and requesting.id == issue.warehouse_id),
        "items": [
            {
                "issue_id": issue.id,
                "issue_no": issue.issue_no,
                "issue_item_id": line.id,
                "mr_id": line_mr.get("mr_id"),
                "mr_no": line_mr.get("mr_no"),
                "indent_id": issue.indent_id,
                "indent_no": issue.indent_no,
                "item_id": line.item_id,
                "item_code": line.item_code,
                "item_name": line.item_name,
                # The issue line's brand / variant / model, carried to the cartons.
                **combinations.carry(line),
                "uom_code": line.uom_code,
                "batch_id": line.batch_id,
                "batch_no": line.batch_no,
                "bin_code": line.bin_code,
                # SERIAL / IMEI / ASSET / CONSUMABLE / NONE: what the codes on this
                # row are, so the packing screen names them and knows which it may
                # choose itself (asset and consumable codes) and which it may not.
                "tracking_type": (TrackingType.NONE.value if line.id in box_lines
                                  else getattr(line, "tracking_type", None)),
                "box_codes": box_lines.get(line.id, []),
                "requires_qc": bool(getattr(line, "requires_qc", False)),
                # Snapshotted on the issue line at creation, so the packer sees what
                # is actually in the carton rather than a blank the receiving point
                # has to guess at.
                "mfg_date": line.mfg_date,
                "expiry_date": line.expiry_date,
                "is_serial_tracked": (
                    bool(item_by_id[line.item_id].is_serial_tracked)
                    if line.item_id in item_by_id and line.id not in box_lines else False
                ) or bool(_get_accepted_serials(line)),
                "is_imei_tracked": (
                    bool(item_by_id[line.item_id].is_imei_tracked)
                    if line.item_id in item_by_id else False
                ) or any(s in imei_by_serial for s in _get_accepted_serials(line)),
                "serial_numbers": _get_accepted_serials(line),
                "imei_by_serial": {
                    serial: imei_by_serial[serial]
                    for serial in _get_accepted_serials(line)
                    if serial in imei_by_serial
                },
                "quantity": _d(qc_accepted.get(line.id, line.issued_qty)),
                "rate": line.rate,
                "remarks": line.remarks,
                **line_packs.get(line.id, {}),
            }
            for line in issue.items
            if _d(qc_accepted.get(line.id, line.issued_qty)) > ZERO
        ],
    }


async def employee_options(db: AsyncSession, search: str | None = None) -> list[dict]:
    from app.platform.hcm.models import HcmEmployee
    stmt = select(HcmEmployee).where(HcmEmployee.is_active.is_(True))
    if search:
        like = f"%{search}%"
        # The column is `emp_code`, not `employee_code` — HCM's own naming, and
        # `hcm/mappers.py` is the only place that name is allowed to be translated.
        stmt = stmt.where(or_(HcmEmployee.full_name.ilike(like),
                              HcmEmployee.emp_code.ilike(like)))
    rows = (await db.execute(
        stmt.order_by(HcmEmployee.full_name).limit(LOOKUP_LIMIT))).scalars().all()
    return [{"id": r.id, "code": r.emp_code, "name": r.full_name} for r in rows]


async def employee_destination(db: AsyncSession, employee_id: int) -> dict:
    """Where a direct issue goes when it names this employee.

    Same answer `_issue_destination` falls back to on a saved issue — the
    employee's own office — plus the SAC and vehicle the form shows beside it,
    so a direct issue fills Destination / SAC / Vehicle on Issued-to select
    instead of waiting for an indent that is never coming.
    """
    from app.platform.hcm.models import HcmEmployee

    employee = await db.get(HcmEmployee, employee_id)
    if employee is None:
        raise NotFoundError(f"Employee {employee_id} not found")
    office_name = employee.office_name
    return {
        "issued_to_id": employee.id,
        "issued_to_name": employee.full_name,
        "destination_office_id": employee.office_id,
        "destination_office_name": office_name,
        "destination_office_sac": await _office_sac(db, employee.office_id),
        "vehicle_number": _vehicle_from_office_name(office_name),
        # So Project / Department fill on Issued-to too, not only from an indent.
        "department_id": employee.department_id,
        "department_name": employee.department_name,
        "project_id": employee.project_id,
        "project_name": employee.project_name,
    }


async def _issue_destination_point(
    db: AsyncSession, warehouse_id: int | None, origin_id: int,
) -> Warehouse | None:
    """The chosen destination point of an issue, checked. None when none was chosen."""
    if not warehouse_id:
        return None
    point = await db.get(Warehouse, warehouse_id)
    if point is None or not point.is_active:
        raise ValidationError("The destination is not an active warehouse, MDP or LIP")
    if point.id == origin_id:
        raise ValidationError(
            f"{point.name} is the warehouse the goods are leaving. Pick where they are "
            "going instead.")
    return point


async def _own_point_ids(db: AsyncSession, user) -> set[int]:
    """The stocking points this login works FROM — never offered as a destination.

    Its own floor only, not everything its role may see: a District Manager can see
    every LIP under him, and every one of those is somewhere he sends goods to. With a
    post in hand it is the shelves that post holds (BUG_SCM_012); otherwise the points
    the person is in charge of or that sit on their own office.
    """
    if user is None:
        return set()
    position = getattr(user, "active_position_id", None)
    if position is not None:
        return await stock_locations.held_location_ids(db, position, subtree=False)
    conditions = [Warehouse.incharge_id == user.id]
    if getattr(user, "office_id", None) is not None:
        conditions.append(Warehouse.office_id == user.office_id)
    return set((await db.execute(
        select(Warehouse.id).where(Warehouse.is_active.is_(True), or_(*conditions))
    )).scalars().all())


#: Every active stocking point with its office's SAC, held briefly per process. ~1,000
#: rows, each needing the office's raw HCM payload for its SAC — read once a minute,
#: not once a keystroke. The points change on an HCM sync, not between two searches.
_DESTINATION_CATALOG: dict[str, object] = {"at": 0.0, "rows": []}
_DESTINATION_TTL = 60.0
_POINT_ORDER = {"MAIN": 0, "MDP": 1, "LIP": 2}


async def _destination_catalog(db: AsyncSession) -> list[dict]:
    import time
    from app.platform.hcm import mappers
    from app.platform.hcm.models import HcmOffice

    now = time.monotonic()
    if _DESTINATION_CATALOG["rows"] and now - float(_DESTINATION_CATALOG["at"]) < _DESTINATION_TTL:
        return _DESTINATION_CATALOG["rows"]  # type: ignore[return-value]
    rows = []
    for point, office_name, raw in (await db.execute(
        select(Warehouse, HcmOffice.name, HcmOffice.raw)
        .outerjoin(HcmOffice, HcmOffice.id == Warehouse.office_id)
        .where(Warehouse.is_active.is_(True))
    )).all():
        office = point.office_name or office_name
        rows.append({
            "warehouse_id": point.id,
            "code": point.code,
            "name": point.name,
            "warehouse_type": point.warehouse_type,
            "office_id": point.office_id,
            "office_name": office,
            "sac": mappers.office_sac(raw),
            # Only a point standing on an MMU office has one — its name ends in it.
            "vehicle_number": _vehicle_from_office_name(office),
        })
    rows.sort(key=lambda r: (_POINT_ORDER.get(r["warehouse_type"], 0), r["name"].lower()))
    _DESTINATION_CATALOG.update(at=now, rows=rows)
    return rows


def _matches(needles: list[str], *values) -> bool:
    """Every word typed appears somewhere in the row — in any field, in any order."""
    haystack = " ".join(str(v) for v in values if v).lower()
    return all(needle in haystack for needle in needles)


async def issue_destination_options(
    db: AsyncSession, user, *, search: str | None = None,
    from_warehouse_id: int | None = None, office_id: int | None = None,
    with_sac: bool = False, limit: int = 50,
) -> dict:
    """Where a direct issue can go: every warehouse, MDP and LIP but the user's own.

    Searched across the point's code and name, its office, its service area code and
    its vehicle, every word anywhere — "badangi", "550R" and "AP39UH" all find the
    same LIP. `office_id` narrows to the point(s) on one office (the issued-to person
    has been chosen); `with_sac` to the points that carry a service area code, for the
    SAC picker. An exact SAC or code match sorts first.
    """
    own = await _own_point_ids(db, user)
    if from_warehouse_id:
        own = own | {from_warehouse_id}
    needles = [word for word in (search or "").lower().split() if word]
    exact = (search or "").strip().lower()
    hits = [
        row for row in await _destination_catalog(db)
        if row["warehouse_id"] not in own
        and (office_id is None or row["office_id"] == office_id)
        and (not with_sac or row["sac"])
        and _matches(needles, row["code"], row["name"], row["office_name"],
                     row["sac"], row["vehicle_number"], row["warehouse_type"])
    ]
    if exact:
        hits.sort(key=lambda r: 0 if exact in {(r["sac"] or "").lower(),
                                                (r["code"] or "").lower()} else 1)
    return {"items": hits[:limit], "total": len(hits)}


async def issue_employee_options(
    db: AsyncSession, *, search: str | None = None, office_id: int | None = None,
    limit: int = 30,
) -> dict:
    """Every active employee, searched on the SERVER — not the first page of them.

    The old lookup loaded one capped page and filtered it in the browser, so anybody
    past that page could not be found at all. Every word typed must match one of the
    code, the name, the POSITION code, the office, the department or the project.
    `office_id` narrows to the people of the chosen destination. Each row carries the
    position code(s) the person holds — the primary post first — because one name can
    stand on two posts, and the post is what the store actually recognises.
    """
    from app.platform.hcm.models import HcmEmployee, HcmPosition, HcmPositionAssignment

    held = (
        select(HcmPositionAssignment.employee_id)
        .join(HcmPosition, HcmPosition.id == HcmPositionAssignment.position_id)
        .where(HcmPositionAssignment.is_active.is_(True), HcmPosition.is_active.is_(True))
    )
    stmt = select(HcmEmployee).where(HcmEmployee.is_active.is_(True))
    if office_id is not None:
        stmt = stmt.where(HcmEmployee.office_id == office_id)
    for word in (search or "").split():
        like = f"%{word}%"
        stmt = stmt.where(or_(
            HcmEmployee.emp_code.ilike(like), HcmEmployee.full_name.ilike(like),
            HcmEmployee.office_name.ilike(like), HcmEmployee.department_name.ilike(like),
            HcmEmployee.project_name.ilike(like),
            HcmEmployee.id.in_(held.where(HcmPosition.code.ilike(like)))))
    total = await db.scalar(select(func.count()).select_from(stmt.subquery())) or 0
    exact = (search or "").strip()
    order = [HcmEmployee.full_name]
    if exact:
        # The code typed in full puts that person first.
        order.insert(0, case((HcmEmployee.emp_code == exact, 0), else_=1))
    rows = (await db.execute(stmt.order_by(*order).limit(limit))).scalars().all()

    # One query for the page's posts, primary first.
    #
    # HCM also assigns a LIP's store-keeper post to the Driver and the DEO who carry
    # that charge on the side, so read raw, every one of them wore a Store Keeper code.
    # A person is shown their OWN post: a store-keeper post appears only for somebody
    # who holds nothing else, i.e. who IS a Store Keeper.
    posts: dict[int, list[tuple[str, str | None]]] = {}
    side_charge: dict[int, list[tuple[str, str | None]]] = {}
    if rows:
        for employee_id, code, title, role in (await db.execute(
            select(HcmPositionAssignment.employee_id, HcmPosition.code,
                   func.coalesce(HcmPosition.role_name, HcmPosition.name),
                   HcmPosition.role_name)
            .join(HcmPosition, HcmPosition.id == HcmPositionAssignment.position_id)
            .where(HcmPositionAssignment.employee_id.in_([r.id for r in rows]),
                   HcmPositionAssignment.is_active.is_(True),
                   HcmPosition.is_active.is_(True),
                   HcmPosition.code.is_not(None))
            .order_by(HcmPositionAssignment.employee_id,
                      HcmPositionAssignment.is_primary.desc(), HcmPosition.id)
        )).all():
            keeper = "storekeeper" in (role or "").replace(" ", "").replace("-", "").lower()
            bucket = side_charge if keeper else posts
            if code not in {c for c, _t in bucket.get(employee_id, [])}:
                bucket.setdefault(employee_id, []).append((code, title))
        for employee_id, keeper_posts in side_charge.items():
            posts.setdefault(employee_id, keeper_posts)
    return {
        "items": [{
            "id": r.id, "code": r.emp_code, "name": r.full_name,
            "position_codes": [c for c, _t in posts.get(r.id, [])],
            "position_name": (posts.get(r.id) or [(None, None)])[0][1],
            "office_id": r.office_id, "office_name": r.office_name,
            "department_name": r.department_name, "project_name": r.project_name,
        } for r in rows],
        "total": total,
    }


async def project_options(db: AsyncSession, search: str | None = None) -> list[dict]:
    from app.shared.models.master import Project
    stmt = select(Project)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(or_(Project.code.ilike(like), Project.name.ilike(like)))
    rows = (await db.execute(stmt.order_by(Project.name).limit(LOOKUP_LIMIT))).scalars().all()
    return [{"id": r.id, "code": r.code, "name": r.name} for r in rows]


async def department_options(db: AsyncSession) -> list[dict]:
    from app.platform.hcm.models import HcmDepartment
    rows = (await db.execute(
        select(HcmDepartment).order_by(HcmDepartment.name).limit(LOOKUP_LIMIT))).scalars().all()
    return [{"id": r.id, "code": getattr(r, "code", None), "name": r.name} for r in rows]


async def vehicle_options(db: AsyncSession, search: str | None = None) -> list[dict]:
    """Vehicles live in the transport tables the DB team owns (`trn_vehicles`).

    Queried by raw text rather than mapped: this module has no business declaring a
    model for another team's table just to fill a dropdown, and mapping it here would
    be a second mapper the day transport maps it properly.
    """
    from sqlalchemy import text

    sql = ("SELECT id, vehicle_number FROM trn_vehicles "
           "WHERE (:search IS NULL OR vehicle_number LIKE :like) "
           "ORDER BY vehicle_number LIMIT :limit")
    try:
        rows = (await db.execute(text(sql), {
            "search": search, "like": f"%{search or ''}%", "limit": LOOKUP_LIMIT})).all()
    except Exception:  # noqa: BLE001 - the table belongs to another team and may not exist yet
        logger.warning("trn_vehicles is not available; the vehicle dropdown will be empty")
        return []
    return [{"id": r[0], "code": r[1], "name": r[1]} for r in rows]


async def carrier_options(db: AsyncSession, search: str | None = None) -> list[dict]:
    """Carriers likewise live in `trn_carriers`."""
    from sqlalchemy import text

    sql = ("SELECT id, name FROM trn_carriers "
           "WHERE (:search IS NULL OR name LIKE :like) "
           "ORDER BY name LIMIT :limit")
    try:
        rows = (await db.execute(text(sql), {
            "search": search, "like": f"%{search or ''}%", "limit": LOOKUP_LIMIT})).all()
    except Exception:  # noqa: BLE001
        logger.warning("trn_carriers is not available; the carrier dropdown will be empty")
        return []
    return [{"id": r[0], "code": None, "name": r[1]} for r in rows]


# ---------------------------------------------------------------------------
# Deleting a draft
#
# Eight document types can be started and abandoned, and until now nothing could
# clear them: `cancel_*` leaves a CANCELLED row on the list forever, and most of the
# eight have no cancel at all. Half-typed GRNs and empty picklists piled up in front
# of the work that mattered.
#
# A draft is deleted, not cancelled, because it never happened: it holds no stock, no
# ledger row and no reservation, and no later document points back at it. Everything
# past DRAFT is history and stays — the guards below refuse anything that has moved
# stock, been submitted, or grown a child document. The audit row is written BEFORE
# the delete so the trail survives the row (rule 9).
# ---------------------------------------------------------------------------

class _Draft:
    """One deletable document type: where it lives, what counts as a draft, and what
    has to be checked before it can go."""

    __slots__ = ("model", "table", "no_col", "statuses", "label", "children")

    def __init__(self, model, table: str, no_col: str, statuses: set[str], label: str,
                 children: tuple = ()):
        self.model = model
        self.table = table
        self.no_col = no_col
        self.statuses = statuses
        self.label = label
        #: (model, column, human name) — a row here means something references this
        #: document and deleting it would orphan that thing.
        self.children = children


DRAFT_KINDS: dict[str, _Draft] = {
    "receipt": _Draft(
        m.Receipt, "inb_receipts", "grn_no",
        {ReceiptStatus.DRAFT.value, ReceiptStatus.GATE_ENTRY.value}, "receipt",
        children=((m.Inspection, "receipt_id", "quality inspection"),
                  (m.PutawayTask, "grn_id", "put-away task"),
                  (m.PurchaseReturn, "grn_id", "purchase return")),
    ),
    "inspection": _Draft(
        m.Inspection, "inb_inspections", "inspection_no",
        {InspectionStatus.DRAFT.value}, "inspection",
    ),
    "putaway": _Draft(
        m.PutawayTask, "whs_warehouse_items", "putaway_no",
        {PutawayStatus.DRAFT.value}, "put-away task",
    ),
    "picking": _Draft(
        m.Picking, "out_picking", "pick_no",
        {PickingStatus.DRAFT.value}, "picklist",
        children=((m.MaterialIssue, "picking_id", "material issue"),),
    ),
    "issue": _Draft(
        m.MaterialIssue, "out_issues", "issue_no",
        {IssueStatus.DRAFT.value}, "material issue",
    ),
    "dispatch": _Draft(
        m.Dispatch, "out_dispatches", "dispatch_no",
        {DispatchStatus.DRAFT.value}, "dispatch",
    ),
    "return": _Draft(
        m.PurchaseReturn, "pro_returns", "return_no",
        {ReturnStatus.DRAFT.value}, "purchase return",
    ),
    # No "movement" entry here: an SMO lives on `inv_sto`, shared with transfers, and
    # has no `warehouse_id`/`created_by_id` for `_draft_in_scope` to read — see
    # `_delete_movement_draft`. A saved SMO is a DRAFT until it is submitted, and
    # nothing moves before that, so a draft is safe to discard.
}


async def _delete_movement_draft(db: AsyncSession, order_id: int, user) -> None:
    from app.modules.inventory.models import StockTransferOrder

    order = await _smo_by(db, order_id=order_id, lock=True)
    if order is None:
        raise NotFoundError(f"Stock movement order {order_id} not found")
    if user is not None:
        visible = await db.scalar(
            select(func.count()).select_from(StockTransferOrder).where(
                StockTransferOrder.id == order.id,
                await scope_condition(
                    db, user,
                    warehouse_col=StockTransferOrder.from_warehouse_id,
                    warehouse_ids=await warehouse_ids_for_user(db, user),
                    owner_col=StockTransferOrder.requested_by_id)))
        if not visible:
            raise NotFoundError(f"Stock movement order {order_id} not found")
    _guard(order.status, {MovementOrderStatus.DRAFT.value}, "delete", "stock movement order")
    await write_audit(db, entity="inv_sto", entity_id=order.id, entity_no=order.sto_no,
                      action=AuditAction.DEACTIVATE, actor=user,
                      before={"status": order.status, "deleted": True}, after=None)
    await db.delete(order)
    await db.commit()


async def _draft_in_scope(db: AsyncSession, row, user) -> bool:
    """Can this person see this document at all?

    Deletion reuses the list's own scope predicate rather than a rule of its own —
    a draft you cannot see on the list must not be one you can delete by guessing
    its id, and two separate rules would drift apart the first time one changed.
    """
    if user is None:
        return True
    model = type(row)
    cond = await scope_condition(
        db, user,
        warehouse_col=getattr(model, "warehouse_id", None),
        warehouse_ids=await warehouse_ids_for_user(db, user),
        owner_col=getattr(model, "created_by_id", None),
        project_col=getattr(model, "project_id", None),
    )
    return bool(await db.scalar(
        select(func.count()).select_from(model).where(model.id == row.id, cond)))


async def delete_draft(db: AsyncSession, kind: str, doc_id: int, user) -> None:
    """Deletes one abandoned draft. Refuses anything that is not one."""
    if kind == "movement":
        return await _delete_movement_draft(db, doc_id, user)
    spec = DRAFT_KINDS.get(kind)
    if spec is None:
        raise ValidationError(f"{kind} is not a document that can be deleted.")

    row = await _get(db, spec.model, doc_id, spec.label.title())
    doc_no = getattr(row, spec.no_col, None) or f"#{doc_id}"

    if not await _draft_in_scope(db, row, user):
        raise NotFoundError(f"{spec.label.title()} {doc_id} not found")

    _guard(row.status, spec.statuses, "delete", spec.label)

    # A draft that somehow moved stock is not a draft. Belt and braces: the status
    # guard above should already have caught it, and if it did not, the row is real.
    if getattr(row, "is_stock_posted", False):
        raise ValidationError(
            f"{doc_no} has already been posted to stock and cannot be deleted.")

    for child_model, column, name in spec.children:
        used = await db.scalar(
            select(func.count()).select_from(child_model)
            .where(getattr(child_model, column) == row.id))
        if used:
            raise ValidationError(
                f"{doc_no} already has a {name} against it. Delete that first — "
                f"removing this would leave the {name} pointing at nothing.")

    # Written first: a deleted row cannot be audited afterwards, and the trail is
    # the only remaining record that this document ever existed.
    await write_audit(db, entity=spec.table, entity_id=row.id, entity_no=doc_no,
                      action=AuditAction.DEACTIVATE, actor=user,
                      before={"status": row.status, "deleted": True},
                      after=None)
    # Lines go with the parent: every one of these documents declares
    # `cascade="all, delete-orphan"` on its children.
    await db.delete(row)
    await db.commit()
    logger.info("deleted %s draft %s by employee %s", spec.label, doc_no,
                getattr(user, "id", None))


# ---------------------------------------------------------------------------
# Working a monthly cycle in the warehouse
#
# Approval consolidates a cycle and allocation batches it, but execution did not: a
# cycle of 900 monthly indents lands as 900 issue drafts and a storekeeper was opening
# each one to post it. These two functions close that gap.
#
# Same rule as everywhere else in this flow — nothing is merged. `issue_cycles` is a
# GROUP BY over the issues this login can already see, and `post_issues_batch` is a
# loop that calls the ordinary `post_issue`, so every issue keeps its own stock
# movement, its own ledger rows and its own audit trail. A batch is a way of clicking,
# not a document.
# ---------------------------------------------------------------------------

async def issue_cycles(db: AsyncSession, user) -> list[dict]:
    """Outstanding material issues, grouped by the monthly cycle they serve.

    Scoped exactly as `list_issues` scopes the screen behind it: the same warehouse
    set and the same rung, so a batch can never contain a row the storekeeper could
    not have opened one at a time.
    """
    from app.modules.indents.models import Indent
    from app.modules.indents.enums import IndentType
    from app.modules.indents.service import (
        consolidation_key, cycle_key, _month_label,
    )

    stmt = (
        select(m.MaterialIssue, Indent)
        .join(Indent, Indent.id == m.MaterialIssue.indent_id)
        .where(
            Indent.indent_type == IndentType.MONTHLY.value,
            m.MaterialIssue.direction == IssueDirection.OUT.value,
            m.MaterialIssue.status.in_([
                IssueStatus.DRAFT.value,
                IssueStatus.APPROVED.value,
            ]),
        )
    )
    if user is not None:
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.MaterialIssue.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.MaterialIssue.created_by_id,
            project_col=m.MaterialIssue.project_id,
        ))

    groups: dict[tuple, dict] = {}
    for issue, indent in (await db.execute(stmt)).all():
        # The consolidation document, not the month: two cycles for the same month are
        # two separate lots to pick, and merging them here would hand a storekeeper a
        # batch that no approval screen upstream ever showed as one thing.
        cycle = consolidation_key(indent.consolidation_id, indent)
        key = (cycle, issue.warehouse_id)
        row = groups.setdefault(key, {
            "cycle": cycle,
            "_cycle_month": cycle_key(indent),
            "_consolidation_id": indent.consolidation_id or 0,
            "cycle_label": _month_label(cycle_key(indent)),
            "warehouse_id": issue.warehouse_id,
            "warehouse_name": issue.warehouse_name,
            "issue_count": 0,
            "ready_count": 0,
            "draft_count": 0,
            "indent_count": 0,
            "total_qty": ZERO,
            "issue_ids": [],
            "ready_issue_ids": [],
            "indent_ids": set(),
        })
        row["issue_count"] += 1
        row["total_qty"] += _d(issue.total_qty)
        row["issue_ids"].append(issue.id)
        row["indent_ids"].add(indent.id)
        if issue.status == IssueStatus.APPROVED.value:
            row["ready_count"] += 1
            # Only the approved ones can actually be posted; the screen needs the
            # split so "Post 40 issues" never means "attempt 60 and fail on 20".
            row["ready_issue_ids"].append(issue.id)
        else:
            row["draft_count"] += 1

    out = []
    for row in groups.values():
        row["indent_count"] = len(row.pop("indent_ids"))
        row["total_qty"] = float(row["total_qty"])
        out.append(row)
    # Newest cycle first, and the fullest warehouse within it — the queue a person
    # opens the screen to clear. Sorted on the month and the document id rather than on
    # the key, which would order C9 after C10.
    out.sort(key=lambda r: (r.pop("_cycle_month"), r.pop("_consolidation_id"),
                            r["issue_count"]), reverse=True)
    return out


async def post_issues_batch(db: AsyncSession, issue_ids: list[int], user) -> dict:
    """Post several material issues in one call. One stock movement each, as always.

    Partial success is the expected outcome rather than an error: in a cycle of forty
    issues, one short of stock must not stop the other thirty-nine from going out. Each
    failure is named and returned so the storekeeper knows exactly what is left.
    """
    if not issue_ids:
        raise ValidationError("Pick at least one issue to post")

    posted, failed = [], []
    for issue_id in issue_ids:
        try:
            issue = await post_issue(db, issue_id, user)
            posted.append({"issue_id": issue.id, "issue_no": issue.issue_no,
                           "status": issue.status})
        except AppException as exc:
            # post_issue commits its own work, so a failure has written nothing. The
            # rollback clears the session for the next one.
            await db.rollback()
            failed.append({"issue_id": issue_id, "error": str(exc)})

    return {
        "posted": posted,
        "failed": failed,
        "posted_count": len(posted),
        "failed_count": len(failed),
    }


# ---------------------------------------------------------------------------
# The hand-back from the outward leg
# ---------------------------------------------------------------------------
# Logistics carries the consignment; the paperwork it settles is ours. Logistics sits
# BEFORE warehouse in the import chain (rule 5) and may not call into this module, so
# the direction is inverted: this module registers itself on `logistics.hooks` at
# import time and the transport service calls whatever it finds there.
#
# Both hooks run inside the transport service's transaction and neither commits. Both
# are also written never to RAISE on a state they cannot settle — the load leaving the
# yard is a physical fact, and refusing to record it because the consignment behind it
# is in an unexpected state would leave the two documents further apart, not closer.
# Anything skipped is logged loudly, which is the same rule the workflow fallbacks run
# on (rule 8).

async def _consignment_of(db: AsyncSession, tr) -> m.Dispatch | None:
    """The warehouse consignment a transport request is carrying, if it names one."""
    if not getattr(tr, "dispatch_id", None):
        return None
    return (await db.execute(
        select(m.Dispatch)
        .options(selectinload(m.Dispatch.items), selectinload(m.Dispatch.packages))
        .where(m.Dispatch.id == tr.dispatch_id)
    )).scalar_one_or_none()


async def transport_released(db: AsyncSession, tr, user) -> None:
    """The load left with logistics — gate the consignment out behind it.

    Without this the consignment sat at PACKED forever: `_delivery_rows` counts a line
    as dispatched only once its consignment is on the road, so the requester's own
    Acknowledgements screen showed nothing to confirm while the goods were already on
    a truck, and the indent stayed open with no way to close it.
    """
    # A PURCHASE RETURN'S INBOUND VEHICLE comes first and returns: it carries no
    # consignment, so everything below would fall out at the next line anyway — but it
    # has its own settlement, and reaching it by accident of a null `dispatch_id` would
    # be luck rather than intent. Same arrangement `transport_acknowledged` already has.
    if await _inbound_vehicle_released(db, tr, user):
        return

    # A MULTI-DROP TRIP carries several consignments and names none of them in
    # `dispatch_id`; the trip gates each one out through `_apply_gate_out` itself.
    from app.modules.warehouse import trips
    if await trips.trip_shipment_released(db, tr, user):
        return

    # A PURCHASE RETURN'S OUTWARD LEG, on the other hand, DOES carry a consignment, so
    # this one records its rung and deliberately falls through rather than returning.
    # The gate-out below is the only place stock comes off the books, and short-circuiting
    # here would leave the goods on a lorry and still on the shelf.
    await _outbound_return_released(db, tr, user)

    dispatch = await _consignment_of(db, tr)
    if dispatch is None:
        return
    # PENDING_APPROVAL belongs here too, now that the release gate is retired: the
    # consignments submitted by it are still sitting in that chain, and the press that
    # would have answered them is the one that just ran. Leaving them out would strand
    # exactly the documents the retired gate created.
    if dispatch.status not in (DispatchStatus.APPROVED.value,
                               DispatchStatus.PACKED.value,
                               DispatchStatus.PENDING_APPROVAL.value):
        # Already gated out through the warehouse's own screen, or cancelled. Either
        # way there is nothing left for the release to say.
        return
    # A chain the retired gate started is answered by the load leaving, not left open
    # in somebody's inbox forever. Cancelled rather than approved: nobody signed it,
    # and recording an approval no human made would be a lie in `wf_actions` (rule 9).
    await _cancel_open_dispatch_approval(db, dispatch, user)
    if await _dispatch_signature_outstanding(db, dispatch, user):
        # Logged, never refused. `transport_release_blocked` is where that signature is
        # demanded, and it runs while the load can still be held back; reaching this
        # line means it went anyway — a carrier scan or a delivery landing on a leg
        # nobody pressed the button on. Recording a departure that has physically
        # happened is the lesser wrong: leaving the consignment at PACKED behind a
        # shipment already in transit is what kept `dispatched_quantity` at zero and
        # the requester's acknowledgement out of reach.
        logger.warning(
            "%s gated %s out on a release that never got its dispatch signature",
            tr.tr_no, dispatch.dispatch_no)
    for issue_id in await _dispatch_issue_ids(db, dispatch):
        issue = await db.get(m.MaterialIssue, issue_id)
        if issue is None or not issue.is_stock_posted:
            logger.warning(
                "%s released transport but an issue behind %s has not posted stock; "
                "not gated out", tr.tr_no, dispatch.dispatch_no)
            return

    await _apply_gate_out(db, dispatch, tr.gate_pass_no, user)
    logger.info("%s gated out %s on transport release", tr.tr_no, dispatch.dispatch_no)


async def transport_release_blocked(db: AsyncSession, tr, user) -> str | None:
    """May the load leave? Asked BEFORE logistics releases it.

    The one place a refusal still means something. This check used to sit in
    `transport_released`, which runs after the goods have gone: it could not stop the
    departure, only decline to record it, and a consignment left at PACKED behind a
    shipment already IN_TRANSIT is strictly worse than either outcome — `_delivery_rows`
    counts nothing as dispatched, the requester is never offered the acknowledgement,
    and the indent stays open on goods that are already on a truck.

    Silent where the project never configured a Dispatch chain, which is the same
    contract `_dispatch_signature_outstanding` has always had.
    """
    dispatch = await _consignment_of(db, tr)
    if dispatch is None:
        return None
    if dispatch.status in _ON_THE_ROAD:
        # Already gated out through the warehouse's own screen — the signature, if one
        # was owed, was settled there.
        return None
    if dispatch.status == DispatchStatus.CANCELLED.value:
        return f"{dispatch.dispatch_no} is cancelled — it cannot be dispatched"
    if dispatch.status == DispatchStatus.PENDING_APPROVAL.value:
        # Actively with an approver. Not conditional on a ladder lookup: the document
        # is already IN one.
        return (f"{dispatch.dispatch_no} is waiting on "
                f"{dispatch.current_approver_name or 'approval'} and cannot leave yet")
    if dispatch.status == DispatchStatus.REJECTED.value:
        return f"{dispatch.dispatch_no} was rejected — it cannot be dispatched"
    if not await _dispatch_signature_outstanding(db, dispatch, user):
        return None

    # A ladder EXISTING is not the same as anybody having to sign, and only the engine
    # can tell the two apart: every rung switched off, or a local post retired, and it
    # resolves to NO_APPROVAL. Refusing on the mere existence of a chain would block
    # releases nobody was ever waiting on. So ask it properly — the same call
    # `gate_out` makes through `_dispatch_approval_pending`, minus the commit.
    #
    # Asked on THIS session, which the objection below rolls back with the rest of the
    # transport transaction — so nothing here is left half-submitted.
    instance = await _apply_dispatch_submit(db, dispatch, user)
    if instance.status == InstanceStatus.APPROVED.value:
        # Nobody had to sign. The consignment now reads APPROVED and `transport_released`
        # gates it out on the way past, which is exactly the old behaviour.
        return None

    # Somebody does have to sign, and the dispatch press is the only place left that can
    # ask them.
    #
    # FIXED 2026-08-21 — this used to refuse with "send it for release on Consignments,
    # then dispatch it again", which was already the weaker half of the contract (the
    # rolled-back submit meant the chain had NOT started) and became impossible when
    # that button was taken off the consignment screen: the desk was told to press
    # something that no longer exists, and the load could never leave. Releasing is not
    # a separate errand — it is what pressing dispatch on a consignment this project
    # guards MEANS.
    #
    # So the request is raised through a session of its own, which survives the
    # objection that takes this transaction down. Same pattern, and same reason, as
    # `platform/admin/app_logs.py`: a fact that must outlive the failure it describes.
    approver = await _submit_dispatch_independently(dispatch.id, user)
    return (f"{dispatch.dispatch_no} cannot leave yet — it is now with "
            f"{approver or 'an approver'} to release. Dispatch it again once "
            f"they have signed.")


async def _submit_dispatch_independently(dispatch_id: int, user) -> str | None:
    """Start a consignment's release chain on its own session, and name the approver.

    The caller is about to raise, so a submit written on ITS session would be rolled
    back and the desk would be told to wait for an approval nobody had been asked for.
    Returns None when the chain could not be started — the objection still stands, it
    just cannot name anybody.
    """
    try:
        async with SessionLocal() as db:
            dispatch = (await db.execute(
                select(m.Dispatch)
                .options(selectinload(m.Dispatch.items), selectinload(m.Dispatch.packages))
                .where(m.Dispatch.id == dispatch_id)
            )).scalar_one_or_none()
            if dispatch is None:
                return None
            # Re-checked on this session: another press may have got here first, and
            # submitting a consignment that is already in approval would start a second
            # chain against the same document.
            if dispatch.status != DispatchStatus.PACKED.value:
                return dispatch.current_approver_name
            await _apply_dispatch_submit(db, dispatch, user)
            await write_audit(db, entity="out_dispatches", entity_id=dispatch.id,
                              entity_no=dispatch.dispatch_no, action=AuditAction.UPDATE,
                              actor=user, before={"status": DispatchStatus.PACKED.value},
                              after={"status": dispatch.status},
                              summary=f"Sent {dispatch.dispatch_no} for release on dispatch")
            await db.commit()
            return dispatch.current_approver_name
    except Exception:
        logger.exception("Could not send %s for release", dispatch_id)
        return None


async def _cancel_open_dispatch_approval(db: AsyncSession, dispatch: m.Dispatch,
                                         user) -> None:
    """Close any release chain still open on this consignment.

    The release gate is retired (`_register_transport_hooks`), but the consignments it
    submitted before that are still parked at PENDING_APPROVAL with a live instance and
    a row in somebody's inbox. The dispatch press is what those chains were waiting to
    hear, so it ends them — otherwise the approver keeps a queue of decisions for loads
    that have already gone.

    `abandon`, not `act`: nobody signed it, and recording an approval no human made
    would be a lie in `wf_actions` (rule 9). The engine writes its own CANCELLED row.
    """
    await engine.abandon(
        db, WarehouseDocType.DISPATCH.value, dispatch.id, user,
        reason="Released by the dispatch press; the separate release step is retired",
    )


async def _dispatch_signature_outstanding(db: AsyncSession, dispatch: m.Dispatch,
                                          user) -> bool:
    """Read-only twin of `_dispatch_approval_pending`, for the hook.

    Same question, none of the side effects: the original SUBMITS an unsubmitted
    consignment and raises when one is mid-approval, and neither belongs inside a hook
    running in somebody else's transaction — a commit there would split the transport
    release in half, and a raise would refuse to record a load that has physically
    gone. This only answers "may it leave", and the caller logs and walks away when it
    may not.

    Like the original, conditional on a DISPATCH ladder EXISTING for this scope. Where
    nobody configured one — every project today — a packed consignment gates straight
    out exactly as it did before.
    """
    if dispatch.status == DispatchStatus.APPROVED.value:
        return False

    project_id, _ = await wf_ladder.project_for(
        db, getattr(user, "active_position_id", None), user)
    if await wf_ladder.find_ladder(
            db, project_id, WarehouseDocType.DISPATCH.value) is None:
        return False

    instance = (await db.execute(
        select(WfInstance)
        .where(WfInstance.doc_type == WarehouseDocType.DISPATCH.value,
               WfInstance.doc_id == dispatch.id)
        .order_by(WfInstance.id.desc()).limit(1)
    )).scalars().first()
    return instance is None or instance.status != InstanceStatus.APPROVED.value


def _stored_collection_answer(row: m.PurchaseReturn) -> SimpleNamespace:
    """The supplier's collection answer, rebuilt from what was kept on the return.

    Shaped like `VendorReturnResponseIn` because `_raise_vendor_return_inbound` reads
    these attribute names off it — one receipt builder serves the delivery and the
    collection, and a second copy of that loop for the deferred case is exactly the
    drift worth avoiding.

    NOT the real schema, and that is deliberate rather than lazy. `VendorReturnResponseIn`
    refuses a `replacement_ready_date` in the past, correctly: a supplier promising goods
    ready last Tuesday is answering the wrong question. But this runs when the leg is
    ACKNOWLEDGED, days or weeks after the promise was made and kept, by which time that
    date is ALWAYS in the past. Replaying the answer through its own validator would
    therefore fail every single time, on a document that was valid when it was written.
    The validators belong to the press that took the answer; this only carries it.
    """
    return SimpleNamespace(
        replacement_mode=s.INBOUND_MODES_COLLECTED[0],
        # A collection's own two facts. The delivery fields stay None: nobody drove it
        # here, and a transporter or LR number written now would be inventing one.
        replacement_pickup_address=row.collection_pickup_address,
        replacement_ready_date=row.collection_ready_date,
        replacement_expected_date=None,
        replacement_transporter_name=None,
        replacement_vehicle_no=None,
        replacement_lr_no=None,
        # Plain namespaces rather than `VendorReplacementLineIn` for the same reason the
        # outer object is one: the builder reads four attributes off each.
        replacement_lines=[
            SimpleNamespace(line_no=line.line_no,
                            batch_no=line.replacement_batch_no,
                            mfg_date=line.replacement_mfg_date,
                            expiry_date=line.replacement_expiry_date)
            for line in row.items
        ],
    )


async def _collection_arrived(db: AsyncSession, tr, user) -> bool:
    """A vendor collection leg has landed — raise the receipt it was fetching.

    THE OTHER END of `_raise_collection_shipment`. When the supplier answers REPLACED
    and asks us to collect, the answer raises the TRIP and nothing in the warehouse:
    there is nothing for the store to do while the goods are still on the supplier's
    dock. This is the moment that stops being true — our vehicle has been, and somebody
    here has signed for what came back — so this is where the inbound receipt is raised,
    against the facts the supplier stated when they answered.

    Everything the receipt needs was validated in that press and kept on the return
    (`collection_pickup_address`, `collection_ready_date`) and on its lines
    (`replacement_batch_no` and the two dates). So the answer is rebuilt exactly as the
    supplier gave it and handed to the same `_raise_vendor_return_inbound` a delivery
    uses — one receipt builder, not a second drifting copy for the collection case.

    Returns whether this leg was a collection, so the caller knows to stop: a collection
    leg carries no consignment and none of the consignment settlement below applies.

    IDEMPOTENT. A second acknowledgement finds `vendor_followup_receipt_id` already set
    and does nothing rather than raising a second receipt — the store would otherwise be
    expecting two lorries for one collection.
    """
    if not getattr(tr, "id", None):
        return False
    row = (await db.execute(
        select(m.PurchaseReturn)
        .options(selectinload(m.PurchaseReturn.items))
        .where(m.PurchaseReturn.collection_tr_id == tr.id)
    )).scalars().first()
    if row is None:
        return False
    if row.vendor_followup_receipt_id:
        logger.info("%s: %s already has receipt %s — not raising a second",
                    tr.tr_no, row.return_no, row.vendor_followup_receipt_no)
        return True

    receipt = await _raise_vendor_return_inbound(db, row, _stored_collection_answer(row))
    row.vendor_followup_receipt_id = receipt.id
    row.vendor_followup_receipt_no = receipt.grn_no
    await write_audit(
        db, entity="pro_returns", entity_id=row.id, entity_no=row.return_no,
        action=AuditAction.UPDATE, actor=user,
        summary=f"{row.return_no}: {tr.tr_no} brought the replacement back — "
                f"inbound receipt {receipt.grn_no} raised",
        after={"vendor_followup_receipt_no": receipt.grn_no,
               "collection_tr_no": tr.tr_no})
    logger.info("%s landed the collection for %s as receipt %s",
                tr.tr_no, row.return_no, receipt.grn_no)
    return True


async def transport_acknowledged(db: AsyncSession, tr, user) -> None:
    """The receiving site signed for the leg — settle what the leg was carrying.

    One signature, one set of consequences: the consignment reads ACKNOWLEDGED, the
    material issue behind it is signed off, the arrival is credited to the receiving
    shelf and the indent closes once nothing is still owed on it. All of that already
    lives in `_apply_dispatch_acknowledgement`; this only decides that it applies.
    """
    # A VENDOR COLLECTION comes first and returns: it carries no consignment, so
    # everything below would fall out at the next line anyway — but it has its own
    # settlement, and reaching it by accident of a null `dispatch_id` would be luck
    # rather than intent.
    if await _collection_arrived(db, tr, user):
        return
    # A PURCHASE RETURN'S INBOUND VEHICLE, for the same reason. Matched on its own
    # column, so the two can never both claim one leg.
    if await _inbound_vehicle_arrived(db, tr, user):
        return

    dispatch = await _consignment_of(db, tr)
    if dispatch is None:
        return
    if dispatch.status not in (DispatchStatus.DISPATCHED.value,
                               DispatchStatus.IN_TRANSIT.value,
                               DispatchStatus.DELIVERED.value):
        return

    note = tr.ack_remarks or None
    if (tr.ack_condition or "GOOD") != "GOOD":
        # The claim itself stays on the shipment timeline where the Exceptions desk
        # works it. What the consignment records is that the site said so.
        note = f"{tr.ack_condition.title()} on arrival: {note or '—'}"
    await _apply_dispatch_acknowledgement(
        db, dispatch,
        s.AcknowledgeWrite(acknowledged_by_name=tr.acknowledged_by_name,
                           pod_url=tr.pod_url, remarks=note, lines=[]),
        user,
    )
    logger.info("%s acknowledged %s for the receiving site",
                tr.tr_no, dispatch.dispatch_no)


async def write_off_units_for_adjustment(
    db: AsyncSession, adjustment, adj_item, user
) -> None:
    """Retire a write-off line's unit codes the moment its stock leaves.

    The audit's OUT movement shrinks `stk_balance`; the units on `whs_serial_numbers`
    would otherwise still read `available`, and the issue screen's code auto-fill and
    picker would keep offering codes for units the audit just declared gone. This is
    the codes' half of the same posting: same transaction, so they are retired with
    the stock or not at all.

    `adj_item.serial_numbers` are the codes the auditor PICKED on the form, matched
    to this line's item, batch and bin; a code naming some other unit is refused, so
    the audit cannot retire stock it did not name. When it names none, the damaged
    units had no known identity worth telling apart — the oldest N available codes
    on the (item, batch, bin) are retired instead, so the unit rows stay in step
    with the balance and the picker cannot offer them.

    Registered on `inventory.hooks.ON_ADJUSTMENT_OUT` at import time; inventory may
    not import warehouse (rule 5).
    """
    wanted = int(_d(adj_item.quantity or 0))
    if wanted <= 0:
        return
    picked = [str(c).strip() for c in (adj_item.serial_numbers or []) if str(c).strip()]

    stmt = (
        select(m.SerialNumber)
        .where(
            m.SerialNumber.item_id == adj_item.item_id,
            m.SerialNumber.warehouse_id == adjustment.warehouse_id,
            m.SerialNumber.status == SerialStatus.AVAILABLE.value,
            m.SerialNumber.is_active.is_(True),
            m.SerialNumber.batch_id == (adj_item.batch_id or None),
            m.SerialNumber.bin_id == (adj_item.bin_id or None),
        )
        .order_by(m.SerialNumber.id.asc())
        .with_for_update()
    )
    rows = (await db.execute(stmt)).scalars().all()
    by_code = {}
    for row in rows:
        for code in (row.serial_number, row.imei, row.asset_code, row.consumable_code):
            if code:
                by_code[code] = row

    if picked:
        missing = [c for c in picked if c not in by_code]
        if missing:
            raise ValidationError(
                f"{len(missing)} of the codes picked on this audit line are not "
                f"available units of this item at this batch and location "
                f"(e.g. {', '.join(missing[:3])}) — the audit cannot write them off"
            )
        victims = [by_code[c] for c in picked]
    else:
        # Unclaimed units first. Retiring a code an open issue already holds would
        # leave that issue naming a unit that no longer exists, and it would fail at
        # posting; only when the free ones run out are claimed ones taken.
        def claimed(row) -> bool:
            return any((row.remarks or "").startswith(prefix)
                       for prefix in _CLAIMED_REMARK_PREFIXES)
        victims = sorted(rows, key=lambda row: (claimed(row), row.id))[:wanted]
    if not victims:
        return

    label = f"Written off by {adjustment.adjustment_no}"
    await _set_unit_fields(
        db,
        [row.id for row in victims],
        status=SerialStatus.SCRAPPED.value,
        is_active=False,
        remarks=label,
    )


def _register_transport_hooks() -> None:
    """Wire this module onto the outward leg, once, at import.

    RETIRED 2026-08-21 — `transport_release_blocked` is deliberately NOT registered.
    The consignment's release was a second sign-off on a decision the dispatch press
    already IS, and because a consignment is only submitted at that press the gate
    fired last: after the transport request, after the tender, after the award. The
    desk picked a carrier, agreed a freight, and only then was told the load could not
    leave. Pressing Dispatch is the release; there is nothing left for a separate one
    to add. The function stays for `submit_dispatch`, which is still a route.
    """
    from app.modules.logistics import hooks as lgs_hooks

    for registry, hook in ((lgs_hooks.ON_RELEASE, transport_released),
                           (lgs_hooks.ON_ACKNOWLEDGE, transport_acknowledged)):
        if hook not in registry:
            registry.append(hook)


_register_transport_hooks()


def _register_stock_transfer_hooks() -> None:
    """An approved STO drafts its material issue here (inventory may not import us)."""
    from app.modules.inventory import hooks as inv_hooks

    if draft_issue_for_sto not in inv_hooks.ON_STO_APPROVED:
        inv_hooks.ON_STO_APPROVED.append(draft_issue_for_sto)


_register_stock_transfer_hooks()


def _register_audit_write_off_hook() -> None:
    """Retire the unit codes an approved stock-audit write-off takes off the shelf.

    Warehouse owns `whs_serial_numbers`; inventory owns the posting it sits inside
    (rule 5), so the handoff is a hook rather than an import, and it fires INSIDE
    the posting transaction: the codes go with the stock or the posting does not
    happen. See `write_off_units_for_adjustment`.
    """
    from app.modules.inventory import hooks as inv_hooks

    if write_off_units_for_adjustment not in inv_hooks.ON_ADJUSTMENT_OUT:
        inv_hooks.ON_ADJUSTMENT_OUT.append(write_off_units_for_adjustment)


_register_audit_write_off_hook()

# ---------------- Outbound Quality Inspection ----------------

async def get_outbound_inspection(db: AsyncSession, inspection_id: int) -> m.OutboundInspection:
    inspection = await _load(db, m.OutboundInspection, inspection_id, "OutboundInspection",
                             m.OutboundInspection.items)
    setattr(inspection, "is_stock_transfer",
            await is_stock_transfer_issue(db, inspection.issue_id))
    # Each line's packs, for what was inspected (2026-10-22).
    packs = await wh_packing.issue_line_packs(
        db, {it.issue_item_id: _d(it.inspected_qty) for it in inspection.items
             if it.issue_item_id})
    for it in inspection.items:
        found = packs.get(it.issue_item_id) or {}
        setattr(it, "pack_breakdown", found.get("pack_breakdown"))
        setattr(it, "pack_text", found.get("pack_text"))
    return inspection

def _outbound_inspection_totals(inspection: m.OutboundInspection) -> None:
    inspection.total_items = len(inspection.items)
    passed = 0
    failed = 0
    for line in inspection.items:
        if line.result == InspectionResult.PASSED.value:
            passed += 1
        elif line.result == InspectionResult.FAILED.value:
            failed += 1
        elif line.result == InspectionResult.PARTIAL.value:
            # A partial is one line that yielded both passed and failed units. Both
            # counters increment because the vendor needs a reason for the failed portion
            # just as much as the line must pass to bank what was accepted.
            passed += 1
            failed += 1
    inspection.passed_items = passed
    inspection.failed_items = failed

async def _apply_outbound_inspection_lines(db: AsyncSession, inspection: m.OutboundInspection,
                                           lines: list[s.OutboundInspectionItemWrite]) -> None:
    inspection.items.clear()
    await db.flush()

    issued_by_line: dict[int, Decimal] = {}
    issued_by_item: dict[int, Decimal] = {}
    line_id_by_item: dict[int, int] = {}
    if inspection.issue_id:
        for row_id, item_id, qty in (await db.execute(
            select(m.MaterialIssueLine.id, m.MaterialIssueLine.item_id, m.MaterialIssueLine.issued_qty)
            .where(m.MaterialIssueLine.issue_id == inspection.issue_id)
        )).all():
            issued_by_line[row_id] = _d(qty)
            issued_by_item[item_id] = issued_by_item.get(item_id, ZERO) + _d(qty)
            line_id_by_item.setdefault(item_id, row_id)

    # The units each issue line actually sent out, named every way the unit can be
    # read — serial, IMEI, asset tag, consumable code. Serials were the only kind QC
    # knew about, so an asset- or lot-coded item went through outward QC with no way
    # to say WHICH units passed.
    units_by_line: dict[int, set[str]] = {}
    # Issued in BOXES (2026-10-26): the box codes each issue line sent, and what each
    # box carried of it — a box line is inspected by its boxes, not by unit rows.
    boxes_by_line: dict[int, dict[str, Decimal]] = {}
    if inspection.issue_id:
        issue = await get_issue(db, inspection.issue_id)
        for line_id, rows in (await _issue_units_by_line(db, issue)).items():
            units_by_line[line_id] = {
                value for row in rows
                for value in (row.serial_number, row.imei, row.asset_code,
                              row.consumable_code) if value}
        for issue_line in issue.items:
            boxes = await box_codes.line_boxes(db, issue.id, issue_line.id)
            if boxes:
                boxes_by_line[issue_line.id] = {box.hu_code: box_codes.held(box)
                                                for box in boxes}
    decimals = await uom_rules.decimals_by_code(
        db, [(await _item_snapshot(db, line.item_id)).uom_code for line in lines])

    for line in lines:
        item = await _item_snapshot(db, line.item_id)
        inspected = _d(line.inspected_qty)
        if inspected < ZERO:
            raise ValidationError(f"{item.code}: inspected quantity cannot be negative")
            
        if line.issue_item_id is None and inspection.issue_id:
            line.issue_item_id = line_id_by_item.get(line.item_id)
            if line.issue_item_id is None:
                raise ValidationError(f"{item.code} is not on this Material Issue")
        if line.issue_item_id is not None:
            if line.issue_item_id not in issued_by_line:
                repointed = line_id_by_item.get(line.item_id)
                if repointed is None:
                    raise ValidationError(f"{item.code} is not on this Material Issue")
                line.issue_item_id = repointed
            issued = issued_by_line[line.issue_item_id]
            if inspected > issued:
                raise ValidationError(
                    f"{item.code}: {inspected} inspected but only {issued} was "
                    f"issued. QC cannot pass more than was issued."
                )
        if _d(line.accepted_qty) > inspected:
            raise ValidationError(
                f"{item.code}: {line.accepted_qty} accepted out of {inspected} "
                f"inspected. Accepted cannot exceed inspected."
            )
        accepted = min(_d(line.accepted_qty), inspected)
        rejected = inspected - accepted
        result = (line.result.value if line.result != InspectionResult.PENDING
                  else _derive_result(inspected, accepted))
                  
        serials_data = line.serial_numbers or []
        if isinstance(serials_data, dict):
             serials = [value.strip() for value in serials_data.get("accepted", []) if value.strip()]
        elif isinstance(serials_data, list):
             serials = [value.strip() for value in serials_data if value.strip()]
        else:
             serials = []
        if len(serials) != len(set(serials)):
            raise ValidationError(f"{item.code}: accepted serial numbers must be unique")
            
        # Counted units (Nos, Box…) and serialized items are inspected and accepted
        # whole — QC0038 passed 3.63 Nos of A4 paper. Name the line and the way out:
        # one item can sit on several lines (one per bin), so a bare item code read
        # as "still the same error" after the inspector had fixed a different line.
        label = f"{item.code} (batch {line.batch_no or '-'})"
        whole_units = item.is_serial_tracked or decimals.get(
            item.uom_code, uom_rules.MAX_DECIMALS) == 0
        if whole_units:
            issued_here = issued_by_line.get(line.issue_item_id) if line.issue_item_id else None
            # An issue saved before whole units were enforced may still be 9.5 Nos;
            # inspecting all of it must stay possible or that issue is stranded.
            if inspected != inspected.to_integral_value() and inspected != issued_here:
                raise ValidationError(
                    f"{label}: inspected {inspected} {item.uom_code} — counted units "
                    "are inspected whole.")
            if accepted != accepted.to_integral_value():
                whole = Decimal(int(accepted))
                raise ValidationError(
                    f"{label}: accepted {accepted} {item.uom_code} — counted units are "
                    f"accepted whole. Accept {whole} and reject the remaining "
                    f"{inspected - whole} with a reason.")

        sent = units_by_line.get(line.issue_item_id or 0, set())
        boxes = boxes_by_line.get(line.issue_item_id or 0)
        pack_rejections: dict[str, float] = {}
        if boxes:
            # Inspected by the PACKAGE (2026-10-26). Every unit rejected is said to
            # have come out of a named package: a package rejected whole is left out
            # of the accepted codes, and units rejected out of a package that is
            # otherwise kept are recorded against it (`pack_rejections`). So what is
            # accepted is exactly what the kept packages carry, less those units.
            stray = [value for value in serials if value not in boxes]
            if stray:
                raise ValidationError(
                    f"{label}: {', '.join(stray[:5])} is not a package this issue line sent")
            if not serials and accepted >= sum(boxes.values(), ZERO):
                serials = list(boxes)
            for code, qty in (line.pack_rejections or {}).items():
                if _d(qty) <= ZERO:
                    continue
                if code not in serials:
                    raise ValidationError(
                        f"{label}: units are rejected out of {code}, which is not kept — "
                        "reject the package whole instead")
                if _d(qty) >= boxes[code]:
                    raise ValidationError(
                        f"{label}: all {boxes[code]} of {code} are rejected — reject the "
                        "package whole (untick it) instead")
                pack_rejections[code] = float(_d(qty))
            kept = (sum((boxes[code] for code in serials), ZERO)
                    - sum((_d(q) for q in pack_rejections.values()), ZERO))
            if kept != accepted:
                raise ValidationError(
                    f"{label}: the packages kept carry {kept} after what was rejected "
                    f"out of them, but {accepted} is accepted. Say which packages the "
                    f"{inspected - accepted} rejected came from")
            if accepted <= ZERO:
                serials = []
        elif sent:
            stray = [value for value in serials if value not in sent]
            if stray:
                raise ValidationError(
                    f"{label}: {', '.join(stray[:5])} did not go out on this issue line")
            if len(serials) != int(accepted):
                raise ValidationError(
                    f"{label}: choose exactly {int(accepted)} accepted units "
                    f"({len(serials)} selected)")
        elif (item.is_serial_tracked and not line.issue_item_id
              and len(serials) != int(accepted)):
            # A line whose issue sent no units came off a lot with none recorded
            # (2026-10-23): it is inspected by quantity.
            raise ValidationError(
                f"{label}: choose exactly {int(accepted)} accepted serial numbers")

        reason = line.rejection_reason or line.defect_type
        if rejected > ZERO and not (reason or "").strip():
            raise ValidationError(
                f"{label}: {rejected} rejected — enter a Rejection reason on this line "
                "before saving")

        inspection.items.append(m.OutboundInspectionItem(
            issue_item_id=line.issue_item_id,
            **(combinations.carry(await db.get(m.MaterialIssueLine, line.issue_item_id))
               if line.issue_item_id else dict(combinations.NONE)),
            item_id=item.id, item_code=item.code, item_name=item.name,
            uom_code=item.uom_code, batch_no=line.batch_no,
            inspected_qty=inspected, accepted_qty=accepted, rejected_qty=rejected,
            parameters=[p.model_dump() for p in line.parameters] if line.parameters else None,
            result=result, defect_type=reason, remarks=line.remarks,
            serial_numbers={"accepted": serials} if serials else None,
            pack_rejections=pack_rejections or None,
        ))
    _outbound_inspection_totals(inspection)

async def create_outbound_inspection(db: AsyncSession, data: s.OutboundInspectionWrite, user) -> m.OutboundInspection:
    # Reached through `stock.transfer.qc` alone: only a stock transfer's issue.
    if (via_scoped_grant(db, QC_OUTWARD_CREATE)
            and not await is_stock_transfer_issue(db, data.issue_id)):
        raise PermissionError_("Missing permission: qc_outward.create")
    issue = await get_issue(db, data.issue_id) if data.issue_id else None
    wh = await db.get(Warehouse, data.warehouse_id) if data.warehouse_id else None

    if issue is not None:
        existing = await db.scalar(
            select(m.OutboundInspection).where(
                m.OutboundInspection.issue_id == issue.id,
                # REJECTED counts as gone, like CANCELLED: an approver who sent the
                # check back has ended it, and refusing a fresh one would leave the
                # issue stuck at PENDING QC with no way to inspect it again.
                m.OutboundInspection.status.notin_([
                    InspectionStatus.CANCELLED.value,
                    InspectionStatus.REJECTED.value,
                ]),
            ).limit(1)
        )
        if existing is not None:
            raise ValidationError(
                f"{issue.issue_no} is already inspected on {existing.inspection_no}. "
                f"Cancel that one to inspect it again."
            )
        if issue.qc_status not in INSPECTABLE_QC:
            raise ValidationError(
                f"{issue.issue_no} QC status is {issue.qc_status}. Cannot inspect."
            )

    inspection = m.OutboundInspection(
        items=[],
        # From the receipt it belongs to — see the note on the GRN number.
        inspection_no=await next_number(db, WarehouseDocType.INSPECTION.value,
                                        project=getattr(issue, "project_name", None)),
        inspection_date=data.inspection_date,
        issue_id=data.issue_id,
        issue_no=issue.issue_no if issue else None,
        warehouse_id=data.warehouse_id or (issue.warehouse_id if issue else None),
        warehouse_name=wh.name if wh else (issue.warehouse_name if issue else None),
        status=InspectionStatus.DRAFT.value,
        inspector_id=data.inspector_id or getattr(user, "id", None),
        inspector_name=_name(user) if not data.inspector_id else None,
        remarks=data.remarks,
    )
    db.add(inspection)
    await db.flush()

    await _apply_outbound_inspection_lines(db, inspection, data.items)
    await db.flush()

    await write_audit(db, entity="whs_inspections", entity_id=inspection.id,
                      entity_no=inspection.inspection_no, action=AuditAction.CREATE, actor=user,
                      after={"status": inspection.status, "lines": len(inspection.items)})
    await db.commit()
    return await get_outbound_inspection(db, inspection.id)

async def update_outbound_inspection(db: AsyncSession, inspection_id: int, data: s.OutboundInspectionWrite, user) -> m.OutboundInspection:
    inspection = await get_outbound_inspection(db, inspection_id)
    _guard(inspection.status,
           {InspectionStatus.DRAFT.value, InspectionStatus.IN_PROGRESS.value},
           "edit", "outbound inspection")

    before = {"status": inspection.status, "failed_items": inspection.failed_items}
    inspection.inspection_date = data.inspection_date
    inspection.inspector_id = data.inspector_id or inspection.inspector_id
    inspection.remarks = data.remarks
    inspection.status = InspectionStatus.IN_PROGRESS.value

    await _apply_outbound_inspection_lines(db, inspection, data.items)
    await db.flush()

    await write_audit(db, entity="whs_inspections", entity_id=inspection.id,
                      entity_no=inspection.inspection_no, action=AuditAction.UPDATE, actor=user,
                      before=before,
                      after={"status": inspection.status, "failed_items": inspection.failed_items})
    await db.commit()
    return await get_outbound_inspection(db, inspection_id)

def _outbound_inspection_context(inspection: m.OutboundInspection, user) -> dict:
    return {
        "doc_no": inspection.inspection_no,
        "doc_summary": f"Outward QC {inspection.inspection_no}",
        "warehouse_id": inspection.warehouse_id,
        "issue_no": inspection.issue_no,
        "failed_items": inspection.failed_items,
        "requester_position_id": getattr(user, "active_position_id", None),
    }


async def _apply_outbound_inspection_result(db: AsyncSession,
                                            inspection: m.OutboundInspection) -> str:
    """Complete the check and hand the verdict to the material issue.

    Split out of `complete_outbound_inspection` so approval can reach it too: where a
    ladder is configured the verdict is applied when the last approver signs, not when
    the inspector saves. Neither commits nor audits; the caller owns both.
    """
    inspection.status = InspectionStatus.COMPLETED.value

    issue = await get_issue(db, inspection.issue_id)
    # Lines the sheet does not carry needed no check and still go out whole, so a
    # sheet that failed everything it held leaves the issue PARTIAL, not FAILED.
    covered = {row.issue_item_id for row in inspection.items}
    unchecked = any(line.id not in covered and _d(line.issued_qty) > ZERO
                    for line in issue.items)
    issue.qc_status = _outbound_qc_verdict(
        passed=inspection.passed_items, failed=inspection.failed_items,
        lines=len(inspection.items), unchecked=unchecked)
    return issue.qc_status


def _outbound_qc_verdict(*, passed: int, failed: int, lines: int, unchecked: bool) -> str:
    """The issue's QC status from its sheet, counting lines that never needed one.

    Pure. `unchecked` is "the issue also carries goods outside the sheet" — those are
    consignable whatever the sheet says, so they turn a FAILED into a PARTIAL.
    """
    if passed == lines:
        return QcStatus.PASSED.value
    if failed == lines:
        return QcStatus.PARTIAL.value if unchecked else QcStatus.FAILED.value
    return QcStatus.PARTIAL.value


async def _outbound_inspection_approval_pending(db: AsyncSession,
                                                inspection: m.OutboundInspection,
                                                user) -> bool:
    """Does this check owe a signature before it may release the issue?

    Deliberately conditional on a QC_OUTWARD ladder EXISTING for this project, the
    same contract `_dispatch_approval_pending` keeps. Where nobody has configured one
    - every project today - this returns False and the inspector's Complete finishes
    the check on the spot, exactly as before. Configuring a chain on Approvals Config
    is what turns the step on, which is the whole point of that screen.

    Returns True when the caller should stop and leave the document in approval.
    """
    project_id, _project_name = await wf_ladder.project_for(
        db, getattr(user, "active_position_id", None), user)
    if await wf_ladder.find_ladder(
            db, project_id, WarehouseDocType.QC_OUTWARD.value) is None:
        return False

    instance = (await db.execute(
        select(WfInstance)
        .where(WfInstance.doc_type == WarehouseDocType.QC_OUTWARD.value,
               WfInstance.doc_id == inspection.id)
        .order_by(WfInstance.id.desc()).limit(1)
    )).scalars().first()
    if instance is not None and instance.status == InstanceStatus.APPROVED.value:
        return False
    if instance is not None and instance.status == InstanceStatus.IN_PROGRESS.value:
        raise ValidationError(
            f"{inspection.inspection_no} is waiting on "
            f"{inspection.current_approver_name or 'approval'}"
        )

    # Never submitted. Start the chain rather than refusing: to the inspector,
    # Complete means "I am done with this check", and where the project asks for a
    # signature that means sending it, not an error pointing at another button. A
    # chain that resolves to NO_APPROVAL comes back approved immediately and the
    # verdict is applied by the caller.
    started = await engine.start(
        db, WarehouseDocType.QC_OUTWARD.value, inspection.id,
        _outbound_inspection_context(inspection, user), user)
    if started.status == InstanceStatus.APPROVED.value:
        inspection.current_approver_name = None
        return False
    inspection.status = InspectionStatus.PENDING_APPROVAL.value
    inspection.current_approver_name = _approver_label(
        await engine.current_approvers(
            db, WarehouseDocType.QC_OUTWARD.value, inspection.id),
        await _approver_rank(db, WarehouseDocType.QC_OUTWARD.value, inspection.id))
    return True


async def complete_outbound_inspection(db: AsyncSession, inspection_id: int, user) -> m.OutboundInspection:
    inspection = await get_outbound_inspection(db, inspection_id)
    _guard(inspection.status,
           {InspectionStatus.DRAFT.value, InspectionStatus.IN_PROGRESS.value},
           "complete", "outbound inspection")

    if not inspection.items:
        raise ValidationError("Cannot complete an empty inspection")

    for line in inspection.items:
        if line.result == InspectionResult.PENDING.value:
            raise ValidationError(
                f"Line {line.item_code} is pending. "
                "Record a result for every item before completing the inspection."
            )

    before = inspection.status
    if await _outbound_inspection_approval_pending(db, inspection, user):
        # Now with its approvers. The issue keeps its PENDING qc_status until they sign.
        await write_audit(db, entity="whs_inspections", entity_id=inspection.id,
                          entity_no=inspection.inspection_no, action=AuditAction.UPDATE,
                          actor=user, before={"status": before},
                          after={"status": inspection.status,
                                 "current_approver_name": inspection.current_approver_name})
        await db.commit()
        return await get_outbound_inspection(db, inspection_id)

    qc_status = await _apply_outbound_inspection_result(db, inspection)

    await write_audit(db, entity="whs_inspections", entity_id=inspection.id,
                      entity_no=inspection.inspection_no, action=AuditAction.UPDATE, actor=user,
                      before={"status": before},
                      after={"status": inspection.status, "issue_qc_status": qc_status})
    await db.commit()
    return await get_outbound_inspection(db, inspection_id)


async def act_on_outbound_inspection(db: AsyncSession, inspection_id: int, action: str,
                                     comments: str, user) -> m.OutboundInspection:
    """Approve or reject an outward check that is waiting on a signature.

    The engine owns the chain; this owns the document status and the verdict it
    releases. A rejection stops the material issue moving on at all rather than
    passing it with a note - the consignment guard reads `qc_status`, and it cannot
    tell the difference between the two.
    """
    inspection = await get_outbound_inspection(db, inspection_id)
    _guard(inspection.status, {InspectionStatus.PENDING_APPROVAL.value},
           action.lower(), "outbound inspection")

    before = inspection.status
    instance = await engine.act(
        db, WarehouseDocType.QC_OUTWARD.value, inspection.id, action, user, comments,
        context=_outbound_inspection_context(inspection, user),
    )
    after: dict = {}
    if instance.status == InstanceStatus.APPROVED.value:
        after["issue_qc_status"] = await _apply_outbound_inspection_result(db, inspection)
        inspection.approved_by_name = _name(user)
        inspection.approved_at = utcnow()
        inspection.current_approver_name = None
    elif instance.status == InstanceStatus.REJECTED.value:
        inspection.status = InspectionStatus.REJECTED.value
        inspection.current_approver_name = None
    else:
        inspection.current_approver_name = _approver_label(
            await engine.current_approvers(
                db, WarehouseDocType.QC_OUTWARD.value, inspection.id),
            await _approver_rank(db, WarehouseDocType.QC_OUTWARD.value, inspection.id))

    after["status"] = inspection.status
    await write_audit(db, entity="whs_inspections", entity_id=inspection.id,
                      entity_no=inspection.inspection_no, action=AuditAction.UPDATE,
                      actor=user, before={"status": before}, after=after)
    await db.commit()
    return await get_outbound_inspection(db, inspection_id)


def _stock_transfer_issue_ids():
    """Material issues that execute a stock transfer: the issue an STO names, or one
    serving an STR (on the header, or per line for a consolidated issue)."""
    from app.modules.indents.models import Indent, IndentItem
    from app.modules.inventory.models import StockTransferOrder

    str_indents = select(Indent.id).where(Indent.indent_type == _STR_INDENT_TYPE)
    return select(m.MaterialIssue.id).where(or_(
        m.MaterialIssue.id.in_(select(StockTransferOrder.issue_id)
                               .where(StockTransferOrder.issue_id.is_not(None))),
        # A floor piece of a split STO issue executes the same transfer (SCM_0011).
        m.MaterialIssue.parent_issue_id.in_(
            select(StockTransferOrder.issue_id)
            .where(StockTransferOrder.issue_id.is_not(None))),
        m.MaterialIssue.indent_id.in_(str_indents),
        m.MaterialIssue.id.in_(
            select(m.MaterialIssueLine.issue_id)
            .join(IndentItem, IndentItem.id == m.MaterialIssueLine.indent_item_id)
            .where(IndentItem.indent_id.in_(str_indents))),
    ))


async def list_outbound_inspections(db: AsyncSession, params: PageParams,
                                    status: str | None = None,
                                    warehouse_id: int | None = None,
                                    search: str | None = None, user=None,
                                    stock_transfer: bool | None = None) -> dict:
    stmt = select(m.OutboundInspection).where(m.OutboundInspection.status != InspectionStatus.CANCELLED.value)
    # A login reaching this list only through `stock.transfer.qc` sees transfer QC and
    # nothing else, whatever it asked for.
    if via_scoped_grant(db, QC_OUTWARD_VIEW):
        stock_transfer = True
    # Outward QC of a stock transfer is worked on Inventory > Stock Transfer (True);
    # the warehouse's own Outward QC list leaves it out (False). None = everything.
    if stock_transfer is not None:
        in_transfer = m.OutboundInspection.issue_id.in_(_stock_transfer_issue_ids())
        stmt = stmt.where(in_transfer if stock_transfer else ~in_transfer)
    if user is not None:
        # The same rung every other warehouse list obeys - this one read the whole
        # network, so an Outward QC screen showed checks run at points the login has
        # never held. Falls back to the inspector's own rows for the reason
        # `list_inspections` does: their signature is on the document.
        stmt = stmt.where(await scope_condition(
            db, user,
            warehouse_col=m.OutboundInspection.warehouse_id,
            warehouse_ids=await warehouse_ids_for_user(db, user),
            owner_col=m.OutboundInspection.inspector_id,
        ))
    if status:
        stmt = stmt.where(m.OutboundInspection.status == status)
    if warehouse_id:
        stmt = stmt.where(m.OutboundInspection.warehouse_id == warehouse_id)
    if search:
        like = f"%{search}%"
        stmt = stmt.where(
            or_(
                m.OutboundInspection.inspection_no.ilike(like),
                m.OutboundInspection.issue_no.ilike(like),
                m.OutboundInspection.warehouse_name.ilike(like),
            )
        )
    return await paginate(db, stmt.order_by(m.OutboundInspection.created_at.desc()), params)


# ---------------- Stock Transfer's scoped grants (require_permission_or) ----------------
#
# Inventory > Stock Transfer works a transfer's material issue and its outward QC on
# this module's own endpoints. Its `stock.transfer.*` codes reach them through
# `core.dependencies.require_permission_or`, and these say whether THIS request's
# document is a stock transfer. A route with no document in its path answers True and
# the service narrows instead (`list_outbound_inspections`, `create_outbound_inspection`).

async def transfer_issue_in_reach(db: AsyncSession, request, user) -> bool:
    issue_id = request.path_params.get("issue_id")
    return True if issue_id is None else await is_stock_transfer_issue(db, int(issue_id))


async def transfer_qc_in_reach(db: AsyncSession, request, user) -> bool:
    inspection_id = request.path_params.get("inspection_id")
    if inspection_id is None:
        return True
    issue_id = await db.scalar(select(m.OutboundInspection.issue_id)
                               .where(m.OutboundInspection.id == int(inspection_id)))
    return await is_stock_transfer_issue(db, issue_id)


async def anywhere_in_reach(db: AsyncSession, request, user) -> bool:
    """For read-only lookups a transfer's screens need (tracking types, stock sources):
    they name no document, and what they return is already scoped to the login."""
    return True


# Multi-drop trips register their own shipment hooks at import (`trips._register`).
# Imported last: `trips` reaches back into this module for the gate-out and the
# acknowledgement helpers, all of which are defined by this line.
from app.modules.warehouse import trips as _trips  # noqa: E402,F401
